(* 1RB0LD_0RC0LE_1RD1RA_0RE1RF_1LF0RC_0LA--- halts. *)

From BusyCoq Require Import Individual62.
From Coq Require Import String Bool Lists.List PeanoNat NArith PArith ZArith ZifyNat ZifyN Lia.
Import ListNotations.
Set Default Goal Selector "!".

Definition tm : TM := TM_from_str "1RB0LD_0RC0LE_1RD1RA_0RE1RF_1LF0RC_0LA---".

Module Internal.

(* --- ScratchEval.v --- *)
Local Close Scope sym_scope.
Local Open Scope bool_scope.
Local Open Scope list_scope.
Local Open Scope N_scope.

(* ========================================================================= *)
(* Basic Option / List / Equality Helpers                                    *)
(* ========================================================================= *)

Definition isEmpty {A : Type} (xs : list A) : bool :=
  match xs with
  | [] => true
  | _ :: _ => false
  end.

Definition isSome {A : Type} (o : option A) : bool :=
  match o with
  | Some _ => true
  | None => false
  end.

Fixpoint list_eqb {A : Type} (eqb : A -> A -> bool) (xs ys : list A) : bool :=
  match xs, ys with
  | [], [] => true
  | x :: xs', y :: ys' => eqb x y && list_eqb eqb xs' ys'
  | _, _ => false
  end.

Definition option_eqb {A : Type} (eqb : A -> A -> bool) (ox oy : option A) : bool :=
  match ox, oy with
  | None, None => true
  | Some x, Some y => eqb x y
  | _, _ => false
  end.

Fixpoint splitAtList {A : Type} (n : nat) (xs : list A) : option (list A * list A) :=
  match n with
  | O => Some ([], xs)
  | S n' =>
    match xs with
    | [] => None
    | x :: xs' =>
      option_map (fun ps => (x :: fst ps, snd ps)) (splitAtList n' xs')
    end
  end.

(* ========================================================================= *)
(* Token Alphabet & RLE Tape Data Structures                                 *)
(* ========================================================================= *)

Inductive Tok : Type :=
  | T_0 | T_1 | T_2 | T_3 | T_4 | T_5 | T_6.

Definition tok_eqb (a b : Tok) : bool :=
  match a, b with
  | T_0, T_0 | T_1, T_1 | T_2, T_2 | T_3, T_3
  | T_4, T_4 | T_5, T_5 | T_6, T_6 => true
  | _, _ => false
  end.

Inductive SegPiece : Type :=
  | SPsingle (b : N)
  | SPpair (v1 v2 rep : N).

Definition segPiece_eqb (x y : SegPiece) : bool :=
  match x, y with
  | SPsingle b1, SPsingle b2 => (b1 =? b2)
  | SPpair v1 v2 r1, SPpair u1 u2 r2 => (v1 =? u1) && (v2 =? u2) && (r1 =? r2)
  | _, _ => false
  end.

Inductive RleItem : Type :=
  | RIsingle (a : N) (h : bool) (s0 : N) (segTail : list SegPiece) (aRight : option N)
  | RItranspRun (a b rep : N)
  | RIpairRun (a1 : N) (h1 : bool) (b1 a2 : N) (h2 : bool) (b2 rep : N)
  | RIraw (t : Tok) (n : N).

Definition rleItem_eqb (x y : RleItem) : bool :=
  match x, y with
  | RIsingle a1 h1 s1 seg1 ar1, RIsingle a2 h2 s2 seg2 ar2 =>
      (a1 =? a2) && Bool.eqb h1 h2 && (s1 =? s2) &&
      list_eqb segPiece_eqb seg1 seg2 && option_eqb N.eqb ar1 ar2
  | RItranspRun a1 b1 r1, RItranspRun a2 b2 r2 =>
      (a1 =? a2) && (b1 =? b2) && (r1 =? r2)
  | RIpairRun a1 h1 b1 c1 j1 d1 r1, RIpairRun a2 h2 b2 c2 j2 d2 r2 =>
      (a1 =? a2) && Bool.eqb h1 h2 && (b1 =? b2) &&
      (c1 =? c2) && Bool.eqb j1 j2 && (d1 =? d2) && (r1 =? r2)
  | RIraw t1 n1, RIraw t2 n2 =>
      tok_eqb t1 t2 && (n1 =? n2)
  | _, _ => false
  end.

(* ========================================================================= *)
(* 1-Hub Fast Simulator (step1Unzip, step1Phases, step1Hub)                  *)
(* ========================================================================= *)

Definition unpackFrontSeg (segs : list SegPiece) : option (N * list SegPiece) :=
  match segs with
  | SPsingle s1 :: rest => Some (s1, rest)
  | SPpair v1 v2 rep :: rest =>
      if 1 <=? rep then
        let rep' := rep - 1 in
        Some (v1, SPsingle v2 :: (if rep' =? 0 then rest else SPpair v1 v2 rep' :: rest))
      else None
  | [] => None
  end.

Fixpoint step1Unzip (E : N) (revPref : list RleItem) (segs : list SegPiece) (tail : list RleItem)
    {struct segs} : option (list RleItem) :=
  match segs with
  | [] => None
  | SPsingle sv :: segRest =>
      if (1 <=? sv) && (sv + 1 <=? E) && negb (isEmpty segRest) then
        step1Unzip (E - sv) (RIsingle 1 true (sv - 1) [] None :: revPref) segRest tail
      else if (1 <=? E) && (E + 1 <=? sv) then
        Some (List.rev revPref ++ RIsingle 1 true (E - 1) (SPsingle (sv - E - 1) :: segRest) None :: tail)
      else None
  | SPpair v1 v2 rep :: segRest =>
      if (1 <=? v1) && (1 <=? v2) && (1 <=? rep) then
        let pc := v1 + v2 in
        let q := if 2 + pc <=? E then N.min rep ((E - 2) / pc) else 0 in
        let E1 := E - q * pc in
        let rev1 := if 0 <? q then RIpairRun 1 true (v1 - 1) 1 true (v2 - 1) q :: revPref else revPref in
        let remRep := rep - q in
        if remRep =? 0 then
          step1Unzip E1 rev1 segRest tail
        else
          let restAfter := if remRep =? 1 then segRest else SPpair v1 v2 (remRep - 1) :: segRest in
          if (1 <=? E1) && (E1 + 1 <=? v1) then
            Some (List.rev rev1 ++ RIsingle 1 true (E1 - 1) (SPsingle (v1 - E1 - 1) :: SPsingle v2 :: restAfter) None :: tail)
          else if (v1 + 1 <=? E1) && (E1 - v1 + 1 <=? v2) then
            let E2 := E1 - v1 in
            Some (List.rev (RIsingle 1 true (v1 - 1) [] None :: rev1) ++
              RIsingle 1 true (E2 - 1) (SPsingle (v2 - E2 - 1) :: restAfter) None :: tail)
          else None
      else None
  end.

Definition step1DumpSegsAux
    (kP1 : N -> list RleItem -> option (list RleItem))
    (E_rem : N) (revPref : list RleItem)
    (sa : N) (sh : bool) (s0 : N) (segTail : list SegPiece) (tail : list RleItem)
    : option (list RleItem) :=
  match unpackFrontSeg segTail with
  | None => None
  | Some (s1, segRest) =>
      if E_rem + 1 <? s1 then
        Some (List.rev revPref ++
          RIsingle sa sh (s0 + E_rem + 1) (SPsingle (s1 - (E_rem + 1)) :: segRest) None :: tail)
      else if s1 + 1 <=? E_rem then
        let E_after := E_rem - s1 in
        if isEmpty segRest then
          kP1 E_after (RIsingle sa sh (s0 + s1 + 1) [] None :: revPref)
        else
          step1Unzip E_after (RIsingle sa sh (s0 + s1 + 1) [] None :: revPref) segRest tail
      else None
  end.

Fixpoint step1Phases (isP2 : bool) (E : N) (revPref rest : list RleItem)
    {struct rest} : option (list RleItem) :=
  if negb isP2 then
    (* Phase 1 *)
    match rest with
    | [] => None
    | RItranspRun a b rep :: tail =>
        if (2 <=? a) && (a mod 2 =? 0) && (1 <=? b) then
          let cost := rep * (a / 2 + b) in
          if cost <=? E then
            step1Phases false (E - cost) (RItranspRun a b rep :: revPref) tail
          else None
        else None
    | RIsingle a h s0 segTail None :: tail =>
        if 1 <=? a then
          let jj := a / 2 in
          if E <=? jj then
            if (1 <=? E) && (2 * E + 1 <=? a) then
              Some (List.rev revPref ++ RIsingle (2 * E - 1) h s0 segTail (Some (a - 2 * E)) :: tail)
            else None
          else
            if negb h then
              if isEmpty segTail then
                if a mod 2 =? 0 then
                  if (2 <=? a) && (1 <=? s0) && (jj + s0 <=? E) then
                    step1Phases false (E - (jj + s0)) (RIsingle a false s0 [] None :: revPref) tail
                  else None
                else
                  if (2 <=? s0) && (jj + s0 <=? E) then
                    step1Phases false (E - (jj + s0)) (RIsingle a true (s0 - 1) [] None :: revPref) tail
                  else if (jj + 1 <=? E) && (E + 1 <=? jj + s0) then
                    Some (List.rev revPref ++
                      RIsingle a true (E - jj - 1) [SPsingle (jj + s0 - E - 1)] None :: tail)
                  else None
              else None
            else
              if a mod 2 =? 0 then
                if 1 <=? s0 then
                  let E_rem := E - jj - 1 in
                  if isEmpty segTail then
                    step1Phases true E_rem (RIsingle (a + 1) false s0 [] None :: revPref) tail
                  else
                    step1DumpSegsAux (fun E' rev' => step1Phases false E' rev' tail)
                      E_rem revPref (a + 1) false s0 segTail tail
                else None
              else
                if 2 <=? s0 then
                  let E_rem := E - jj - 1 in
                  if isEmpty segTail then
                    step1Phases true E_rem (RIsingle (a + 1) true (s0 - 1) [] None :: revPref) tail
                  else
                    step1DumpSegsAux (fun E' rev' => step1Phases false E' rev' tail)
                      E_rem revPref (a + 1) true (s0 - 1) segTail tail
                else None
        else None
    | _ :: _ => None
    end
  else
    (* Phase 2 *)
    let E_rem := E in
    match rest with
    | [] =>
        match revPref with
        | RIsingle a h s0 [] None :: prev =>
            Some (List.rev prev ++ [RIsingle a h (s0 + E_rem + 1) [] None])
        | _ => None
        end
    | RItranspRun a b rep :: tail =>
        if (1 <=? a) && (1 <=? b) then
          step1Phases true E_rem (RItranspRun a b rep :: revPref) tail
        else None
    | RIpairRun a1 h1 b1 a2 h2 b2 rep :: tail =>
        if (h1 || ((1 <=? a1) && (1 <=? b1))) && (h2 || ((1 <=? a2) && (1 <=? b2))) then
          step1Phases true E_rem (RIpairRun a1 h1 b1 a2 h2 b2 rep :: revPref) tail
        else None
    | RIsingle a h s0 segTail None :: tail =>
        if h || ((1 <=? a) && (1 <=? s0)) then
          if isEmpty segTail then
            step1Phases true E_rem (RIsingle a h s0 [] None :: revPref) tail
          else
            step1DumpSegsAux (fun E' rev' => step1Phases false E' rev' tail)
              E_rem revPref a h s0 segTail tail
        else None
    | RIsingle aL h s0 segTail (Some aR) :: tail =>
        if (h || (1 <=? s0)) && (2 * (E_rem + 1) <=? aR) then
          Some (List.rev revPref ++
            RIsingle (aL + 2 * (E_rem + 1)) h s0 segTail (Some (aR - 2 * (E_rem + 1))) :: tail)
        else if isEmpty segTail && (1 <=? s0) && (aR / 2 <=? E_rem) then
          let q_as := aR / 2 in
          let Er := E_rem - q_as in
          if h then
            if aR mod 2 =? 0 then
              step1Phases true Er (RIsingle (aL + aR + 2) false s0 [] None :: revPref) tail
            else
              step1Phases true Er (RIsingle (aL + aR + 2) true (s0 - 1) [] None :: revPref) tail
          else
            let b_rem := s0 - 1 in
            if aR mod 2 =? 0 then
              if b_rem <=? Er then
                step1Phases false (Er - b_rem) (RIsingle (aL + aR + 1) false s0 [] None :: revPref) tail
              else
                Some (List.rev revPref ++
                  RIsingle (aL + aR + 1) false (Er + 1) [SPsingle (b_rem - Er - 1)] None :: tail)
            else
              if b_rem <=? Er then
                step1Phases false (Er - b_rem) (RIsingle (aL + aR + 1) true b_rem [] None :: revPref) tail
              else
                Some (List.rev revPref ++
                  RIsingle (aL + aR + 1) true Er [SPsingle (b_rem - Er - 1)] None :: tail)
        else None
    | RIraw _ _ :: _ => None
    end.

Definition step1Phase1 : N -> list RleItem -> list RleItem -> option (list RleItem) :=
  step1Phases false.

Definition step1Phase2 : N -> list RleItem -> list RleItem -> option (list RleItem) :=
  step1Phases true.

Definition step1Hub (xs : list RleItem) : option (list RleItem) :=
  match xs with
  | RIsingle a0 h0 b0 [] None :: rest =>
      if negb h0 then
        if (3 <=? a0) && (a0 mod 2 =? 1) && (3 <=? b0) && (b0 - 2 <=? a0 / 2) then
          let b0p := b0 - 2 in
          step1Phase1 (a0 / 2 - b0p) [RIsingle (a0 + 3) true b0p [] None] rest
        else None
      else
        if (2 <=? a0) && (a0 mod 2 =? 0) && (2 <=? b0) && (b0 <=? a0 / 2) then
          step1Phase1 (a0 / 2 - b0) [RIsingle (a0 + 3) false b0 [] None] rest
        else None
  | _ => None
  end.

(* ========================================================================= *)
(* Normalization Operators (3 active ops)                                    *)
(* ========================================================================= *)

Inductive NormOp : Type :=
  | NOsplitTransp (i : nat) (k : N)
  | NOtranspToSingle (i : nat)
  | NOphaseShiftL (i : nat).

Definition normOpIndex (op : NormOp) : nat :=
  match op with
  | NOsplitTransp i _ | NOtranspToSingle i | NOphaseShiftL i => i
  end.

Definition applyNormHead (op : NormOp) (xs : list RleItem) : option (list RleItem) :=
  match op with
  | NOsplitTransp _ k =>
      match xs with
      | RItranspRun a b n :: rest =>
          if k <=? n then Some (RItranspRun a b k :: RItranspRun a b (n - k) :: rest) else None
      | _ => None
      end
  | NOtranspToSingle _ =>
      match xs with
      | RItranspRun a b n :: rest =>
          if n =? 1 then Some (RIsingle a false b [] None :: rest) else None
      | _ => None
      end
  | NOphaseShiftL _ =>
      match xs with
      | RIsingle a1 h1 b1 [] None :: RIpairRun a2 h2 b2 u1 j1 c1 n :: rest =>
          if (a1 =? u1) && Bool.eqb h1 j1 && (b1 =? c1) then
            Some (RIpairRun a1 h1 b1 a2 h2 b2 n :: RIsingle a1 h1 b1 [] None :: rest)
          else None
      | _ => None
      end
  end.

Definition applyNorm (op : NormOp) (xs : list RleItem) : option (list RleItem) :=
  match splitAtList (normOpIndex op) xs with
  | None => None
  | Some (pref, suf) => option_map (fun ys => pref ++ ys) (applyNormHead op suf)
  end.

(* ========================================================================= *)
(* Prefix Scanner & Raw Token-Window Engine                                  *)
(* ========================================================================= *)

Fixpoint step1Pref (isP2 : bool) (E : N) (revPref rest : list RleItem)
    {struct rest} : option (bool * N * list RleItem) :=
  if negb isP2 then
    match rest with
    | [] => Some (false, E, revPref)
    | item :: tail =>
        match item with
        | RItranspRun a b rep =>
            if (2 <=? a) && (a mod 2 =? 0) && (1 <=? b) then
              let cost := rep * (a / 2 + b) in
              if cost <=? E then
                step1Pref false (E - cost) (RItranspRun a b rep :: revPref) tail
              else None
            else None
        | RIsingle a h s0 segTail None =>
            let j := a / 2 in
            if (1 <=? a) && (j <? E) then
              let E1 := E - j in
              if negb h then
                if isEmpty segTail then
                  if a mod 2 =? 1 then
                    if (1 <=? s0) && (s0 <=? E1) then
                      step1Pref false (E1 - s0) (RIsingle a true (s0 - 1) [] None :: revPref) tail
                    else None
                  else
                    if (2 <=? a) && (1 <=? s0) && (s0 <=? E1) then
                      step1Pref false (E1 - s0) (RIsingle a false s0 [] None :: revPref) tail
                    else None
                else None
              else
                if isEmpty segTail && (1 <=? s0) then
                  if a mod 2 =? 0 then
                    step1Pref true (E1 - 1) (RIsingle (a + 1) false s0 [] None :: revPref) tail
                  else
                    step1Pref true (E1 - 1) (RIsingle (a + 1) true (s0 - 1) [] None :: revPref) tail
                else None
            else None
        | _ => None
        end
    end
  else
    let E_rem := E in
    match rest with
    | [] => Some (true, E_rem, revPref)
    | item :: tail =>
        match item with
        | RItranspRun a b rep =>
            if (1 <=? a) && (1 <=? b) then
              step1Pref true E_rem (RItranspRun a b rep :: revPref) tail
            else None
        | RIpairRun a1 h1 b1 a2 h2 b2 rep =>
            if (1 <=? a1) && (1 <=? b1) && (1 <=? a2) && (1 <=? b2) then
              step1Pref true E_rem (RIpairRun a1 h1 b1 a2 h2 b2 rep :: revPref) tail
            else None
        | RIsingle a h s0 [] None =>
            if (1 <=? a) && (1 <=? s0) then
              step1Pref true E_rem (RIsingle a h s0 [] None :: revPref) tail
            else None
        | RIsingle a h s0 [] (Some aR) =>
            let q_as := aR / 2 in
            if (1 <=? s0) && (q_as <=? E_rem) then
              let Er := E_rem - q_as in
              if h then
                if aR mod 2 =? 0 then
                  step1Pref true Er (RIsingle (a + aR + 2) false s0 [] None :: revPref) tail
                else
                  step1Pref true Er (RIsingle (a + aR + 2) true (s0 - 1) [] None :: revPref) tail
              else
                if aR mod 2 =? 0 then
                  if s0 - 1 <=? Er then
                    step1Pref false (Er - (s0 - 1)) (RIsingle (a + aR + 1) false s0 [] None :: revPref) tail
                  else None
                else
                  if s0 - 1 <=? Er then
                    step1Pref false (Er - (s0 - 1)) (RIsingle (a + aR + 1) true (s0 - 1) [] None :: revPref) tail
                  else None
            else None
        | _ => None
        end
    end.

Definition step1PrefP1 := step1Pref false.
Definition step1PrefP2 := step1Pref true.

Definition step1HubPrefix (xs : list RleItem) : option (bool * N * list RleItem) :=
  match xs with
  | RIsingle a0 h0 b0 [] None :: rest =>
      if negb h0 then
        if (1 <=? a0) && (a0 mod 2 =? 1) && (2 <=? b0) && (b0 - 2 <=? a0 / 2) then
          step1PrefP1 (a0 / 2 - (b0 - 2)) [RIsingle (a0 + 3) true (b0 - 2) [] None] rest
        else None
      else
        if (2 <=? a0) && (a0 mod 2 =? 0) && (1 <=? b0) && (b0 <=? a0 / 2) then
          step1PrefP1 (a0 / 2 - b0) [RIsingle (a0 + 3) false b0 [] None] rest
        else None
  | _ => None
  end.

Inductive LeftBase : Type :=
  | LBblank : LeftBase
  | LBpipe (E : N) (revOut : list RleItem) : LeftBase.

Inductive RightBase : Type :=
  | RBblank : RightBase
  | RBtail : RightBase.

Record RawCfg : Type := mkRawCfg {
  rc_q : Q;
  rc_L : list (Tok * N);
  rc_lBase : LeftBase;
  rc_R : list (Tok * N);
  rc_rBase : RightBase
}.

Definition isLBblank (lb : LeftBase) : bool :=
  match lb with LBblank => true | LBpipe _ _ => false end.

Definition isRBblank (rb : RightBase) : bool :=
  match rb with RBblank => true | RBtail => false end.

Definition isRBtail (rb : RightBase) : bool :=
  match rb with RBtail => true | RBblank => false end.

Definition pushRun (t : Tok) (n : N) (xs : list (Tok * N)) : list (Tok * N) :=
  if n =? 0 then xs
  else
    match xs with
    | (t', m) :: rest => if tok_eqb t t' then (t, n + m) :: rest else (t, n) :: (t', m) :: rest
    | [] => [(t, n)]
    end.

Definition dropTrailingBlankL (xs : list (Tok * N)) (blankOk : bool) : list (Tok * N) :=
  match xs with
  | [(T_0, _)] => if blankOk then [] else xs
  | _ => xs
  end.

Definition decRun (t : Tok) (n : N) (rest : list (Tok * N)) : list (Tok * N) :=
  if n =? 0 then rest else (t, n) :: rest.

Fixpoint popBit (xs : list (Tok * N)) (blankOk : bool) : option (Sym * list (Tok * N)) :=
  match xs with
  | [] => if blankOk then Some (S0, []) else None
  | (t, n) :: rest =>
      if n =? 0 then popBit rest blankOk
      else
        let rest' := decRun t (n - 1) rest in
        match t with
        | T_0 => Some (S0, rest')
        | T_1 => Some (S1, rest')
        | T_2 => Some (S0, pushRun T_0 1 (pushRun T_1 1 rest'))
        | T_3 => Some (S0, pushRun T_1 2 rest')
        | T_4 => Some (S0, pushRun T_1 1 (pushRun T_3 1 rest'))
        | T_5 => Some (S0, pushRun T_1 1 (pushRun T_2 1 rest'))
        | T_6 => Some (S0, pushRun T_0 1 (pushRun T_1 1 (pushRun T_0 1 (pushRun T_1 1 rest'))))
        end
  end.

Definition popZero (xs : list (Tok * N)) (blankOk : bool) : option (list (Tok * N)) :=
  match popBit xs blankOk with
  | Some (S0, xs') => Some xs'
  | _ => None
  end.

Fixpoint headStartsZero (xs : list (Tok * N)) (lb : LeftBase) : bool :=
  match xs with
  | [] => true
  | (t, n) :: rest =>
      if n =? 0 then headStartsZero rest lb
      else match t with T_1 => false | _ => true end
  end.

Definition coalStepL (xs : list (Tok * N)) : option (list (Tok * N)) :=
  match xs with
  | (T_0, n0) :: (T_1, m) :: rest =>
      if n0 =? 2 then
        if 1 <=? m then Some (pushRun T_2 1 (decRun T_1 (m - 1) rest)) else None
      else if n0 =? 1 then
        if 2 <=? m then Some (pushRun T_3 1 (decRun T_1 (m - 2) rest))
        else if m =? 1 then
          match rest with
          | (T_2, k) :: rest2 => if 1 <=? k then Some (pushRun T_5 1 (decRun T_2 (k - 1) rest2)) else None
          | (T_3, k) :: rest2 => if 1 <=? k then Some (pushRun T_4 1 (decRun T_3 (k - 1) rest2)) else None
          | (T_6, k) :: rest2 => Some (pushRun T_5 k (pushRun T_0 1 (pushRun T_1 1 rest2)))
          | _ => None
          end
        else None
      else None
  | _ => None
  end.

Fixpoint coalL (fuel : nat) (xs : list (Tok * N)) : list (Tok * N) :=
  match fuel with
  | O => xs
  | S fuel' =>
      match coalStepL xs with
      | None => xs
      | Some xs' => coalL fuel' xs'
      end
  end.

Definition coalStepR (xs : list (Tok * N)) : option (list (Tok * N)) :=
  match xs with
  | (T_0, n0) :: (T_1, m) :: rest =>
      if n0 =? 2 then
        if 1 <=? m then Some (pushRun T_2 1 (decRun T_1 (m - 1) rest)) else None
      else if n0 =? 1 then
        if 2 <=? m then Some (pushRun T_3 1 (decRun T_1 (m - 2) rest))
        else if m =? 1 then
          match rest with
          | (T_3, k) :: rest2 => if 1 <=? k then Some (pushRun T_4 1 (decRun T_3 (k - 1) rest2)) else None
          | _ => None
          end
        else None
      else None
  | _ => None
  end.

Fixpoint coalR (fuel : nat) (xs : list (Tok * N)) : list (Tok * N) :=
  match fuel with
  | O => xs
  | S fuel' =>
      match coalStepR xs with
      | None => xs
      | Some xs' => coalR fuel' xs'
      end
  end.

Definition appendT4Rev (b : N) (rev : list RleItem) : list RleItem :=
  match rev with
  | RIsingle a h s0 [] aR :: rest => RIsingle a h (s0 + b) [] aR :: rest
  | _ => RIraw T_4 b :: rev
  end.

Definition peelRun (t : Tok) (xs : list (Tok * N)) : N * list (Tok * N) :=
  match xs with
  | (t', n) :: rest => if tok_eqb t' t then (n, rest) else (0, xs)
  | [] => (0, [])
  end.

Definition tryPromotePipe (Lrest : list (Tok * N)) (lb : LeftBase) : option LeftBase :=
  match lb with
  | LBpipe Ep rev =>
      match Lrest with
      | [(T_5, b)] => if 1 <=? b then Some (LBpipe Ep (appendT4Rev b rev)) else None
      | [(T_5, b); (T_4, n4); (T_3, k); (T_2, n2)] =>
          if (n4 =? 1) && (n2 =? 1) then
            Some (LBpipe Ep (RIsingle (k + 1) false (b + 1) [] None :: rev))
          else None
      | [(T_4, n4); (T_3, k); (T_2, n2)] =>
          if (n4 =? 1) && (n2 =? 1) then
            Some (LBpipe Ep (RIsingle (k + 1) false 1 [] None :: rev))
          else None
      | [(T_5, b); (T_4, n4); (T_2, n2)] =>
          if (n4 =? 1) && (n2 =? 1) then
            Some (LBpipe Ep (RIsingle 1 false (b + 1) [] None :: rev))
          else None
      | [(T_4, n4); (T_2, n2)] =>
          if (n4 =? 1) && (n2 =? 1) then
            Some (LBpipe Ep (RIsingle 1 false 1 [] None :: rev))
          else None
      | [(T_5, b); (T_4, n4); (T_3, k)] =>
          if n4 =? 1 then Some (LBpipe Ep (RIsingle k true b [] None :: rev)) else None
      | [(T_4, n4); (T_3, k)] =>
          if n4 =? 1 then Some (LBpipe Ep (RIsingle k true 0 [] None :: rev)) else None
      | [(T_5, b); (T_4, n4)] =>
          if n4 =? 1 then Some (LBpipe Ep (RIsingle 0 true b [] None :: rev)) else None
      | [(T_4, n4)] =>
          if n4 =? 1 then Some (LBpipe Ep (RIsingle 0 true 0 [] None :: rev)) else None
      | _ => None
      end
  | LBblank =>
      let p1 := peelRun T_5 Lrest in
      match snd p1 with
      | (T_4, n4) :: r2 =>
          if n4 =? 1 then
            let p2 := peelRun T_3 r2 in
            let p3 := peelRun T_2 (snd p2) in
            match snd p3 with
            | [(T_0, c0); (T_1, c1); (T_0, c2); (T_1, c3)] =>
                if (c0 =? 1) && (c1 =? 1) && (c2 =? 1) && (c3 =? 1) then
                  let E := fst p3 / 2 in
                  if fst p3 mod 2 =? 0 then
                    Some (LBpipe E [RIsingle (fst p2 + 2 * E + 1) true (fst p1) [] None])
                  else
                    Some (LBpipe E [RIsingle (fst p2 + 2 * E + 2) false (fst p1 + 1) [] None])
                else None
            | _ => None
            end
          else None
      | _ => None
      end
  end.

Definition symToTok (s : Sym) : Tok :=
  match s with S0 => T_0 | S1 => T_1 end.

Definition stepRaw1 (c : RawCfg) : option RawCfg :=
  match popBit (rc_R c) (isRBblank (rc_rBase c)) with
  | None => None
  | Some (sym, R1) =>
      match tm (rc_q c, sym) with
      | None => None
      | Some (w, R, q') =>
          let wt := symToTok w in
          let L' := dropTrailingBlankL (coalL 4%nat (pushRun wt 1 (rc_L c))) (isLBblank (rc_lBase c)) in
          Some (mkRawCfg q' L' (rc_lBase c) (coalR 4%nat R1) (rc_rBase c))
      | Some (w, L, q') =>
          match popBit (rc_L c) (isLBblank (rc_lBase c)) with
          | None => None
          | Some (lb, L1) =>
              let wt := symToTok w in
              let lt := symToTok lb in
              let R' := dropTrailingBlankL (coalR 4%nat (pushRun lt 1 (pushRun wt 1 R1))) (isRBblank (rc_rBase c)) in
              Some (mkRawCfg q' (coalL 4%nat L1) (rc_lBase c) R' (rc_rBase c))
          end
      end
  end.

Definition stepRawFast (c : RawCfg) : option RawCfg :=
  match rc_q c with
  | A =>
      match rc_L c with
      | (T_1, n1) :: Ltail =>
          if n1 =? 1 then
            let fallback (Lrest : list (Tok * N)) :=
              match rc_R c with
              | (T_2, k) :: R' =>
                  if 1 <=? k then Some (mkRawCfg A ((T_1, 1) :: pushRun T_3 k Lrest) (rc_lBase c) R' (rc_rBase c))
                  else None
              | _ => None
              end in
            match Ltail with
            | (T_2, n2) :: Lrest =>
                if n2 =? 1 then
                  match tryPromotePipe Lrest (rc_lBase c) with
                  | Some lb' => Some (mkRawCfg A [(T_1, 1); (T_2, 1)] lb' (rc_R c) (rc_rBase c))
                  | None =>
                      match rc_R c with
                      | (T_4, k) :: R' =>
                          if 1 <=? k then
                            Some (mkRawCfg A ((T_1, 1) :: (T_2, 1) :: pushRun T_5 k Lrest) (rc_lBase c) R' (rc_rBase c))
                          else None
                      | (T_2, k) :: R' =>
                          if 1 <=? k then
                            Some (mkRawCfg A ((T_1, 1) :: pushRun T_3 k ((T_2, 1) :: Lrest)) (rc_lBase c) R' (rc_rBase c))
                          else None
                      | _ => None
                      end
                  end
                else fallback Ltail
            | _ => fallback Ltail
            end
          else None
      | _ => None
      end
  | B => None
  | C =>
      match rc_R c with
      | (T_2, k) :: R' =>
          if 1 <=? k then Some (mkRawCfg C (pushRun T_2 k (rc_L c)) (rc_lBase c) R' (rc_rBase c))
          else None
      | (T_1, n1) :: (T_2, k) :: R' =>
          if (n1 =? 1) && (1 <=? k) then
            Some (mkRawCfg C (pushRun T_3 k (rc_L c)) (rc_lBase c) ((T_1, 1) :: R') (rc_rBase c))
          else None
      | (T_1, n1) :: (T_4, k) :: R' =>
          if (n1 =? 1) && (1 <=? k) then
            let L' :=
              match rc_L c with
              | (T_3, m) :: Lrest =>
                  if 1 <=? m then
                    pushRun T_2 1 (pushRun T_5 (k - 1) (pushRun T_4 1 (decRun T_3 (m - 1) Lrest)))
                  else pushRun T_6 k (rc_L c)
              | (T_2, m) :: Lrest =>
                  if 1 <=? m then
                    pushRun T_2 1 (pushRun T_5 k (decRun T_2 (m - 1) Lrest))
                  else pushRun T_6 k (rc_L c)
              | _ => pushRun T_6 k (rc_L c)
              end in
            Some (mkRawCfg C L' (rc_lBase c) ((T_1, 1) :: R') (rc_rBase c))
          else None
      | _ => None
      end
  | D => None
  | E =>
      match rc_L c with
      | (T_3, m) :: L' =>
          if 2 <=? m then
            match popZero (rc_R c) (isRBblank (rc_rBase c)) with
            | Some R0 => Some (mkRawCfg E ((T_3, 1) :: L') (rc_lBase c) (pushRun T_0 1 (pushRun T_2 (m - 1) R0)) (rc_rBase c))
            | None => None
            end
          else if m =? 1 then
            if headStartsZero L' (rc_lBase c) then
              match popZero (rc_R c) (isRBblank (rc_rBase c)) with
              | Some R0 => Some (mkRawCfg F (pushRun T_1 2 L') (rc_lBase c) (pushRun T_0 1 (pushRun T_1 1 R0)) (rc_rBase c))
              | None => None
              end
            else None
          else None
      | (T_5, k) :: L' =>
          if (1 <=? k) && headStartsZero L' (rc_lBase c) then
            match rc_R c with
            | (T_0, n0) :: (T_2, m) :: R' =>
                if (n0 =? 1) && (1 <=? m) then
                  Some (mkRawCfg E L' (rc_lBase c) ((T_0, 1) :: (T_2, 1) :: pushRun T_4 k (decRun T_2 (m - 1) R')) (rc_rBase c))
                else None
            | _ => None
            end
          else None
      | (T_0, n0) :: (T_1, n1) :: (T_4, n4) :: (T_5, k) :: L' =>
          if (n0 =? 1) && (n1 =? 1) && (n4 =? 1) && (1 <=? k) && headStartsZero L' (rc_lBase c) then
            match rc_R c with
            | (T_0, r0) :: (T_1, r1) :: R' =>
                if (r0 =? 1) && (r1 =? 1) then
                  Some (mkRawCfg E ((T_0, 1) :: (T_1, 1) :: (T_4, 1) :: L') (rc_lBase c)
                    ((T_0, 1) :: (T_1, 1) :: pushRun T_4 k R') (rc_rBase c))
                else None
            | _ => None
            end
          else None
      | _ => None
      end
  | F =>
      match rc_L c with
      | (T_1, n1) :: Lrest =>
          if n1 =? 2 then
            match tryPromotePipe Lrest (rc_lBase c) with
            | Some lb' => Some (mkRawCfg F [(T_1, 2)] lb' (rc_R c) (rc_rBase c))
            | None =>
                match Lrest, rc_lBase c with
                | [], LBpipe Ep rev =>
                    let pullOther :=
                      if 1 <=? Ep then
                        match popZero (rc_R c) (isRBblank (rc_rBase c)) with
                        | Some R0 => Some (mkRawCfg E [(T_0, 1); (T_1, 1)] (LBpipe (Ep - 1) rev) (pushRun T_1 1 R0) (rc_rBase c))
                        | None => None
                        end
                      else None in
                    match rc_R c with
                    | (T_4, k) :: R' =>
                        let m := N.min k Ep in
                        if 1 <=? m then
                          Some (mkRawCfg F (rc_L c) (LBpipe (Ep - m) (appendT4Rev m rev)) (decRun T_4 (k - m) R') (rc_rBase c))
                        else None
                    | (T_2, k) :: R' =>
                        let j := N.min (k / 2) Ep in
                        if 1 <=? j then
                          Some (mkRawCfg F [(T_1, 2); (T_3, 2 * j)] (LBpipe (Ep - j) rev) (decRun T_2 (k - 2 * j) R') (rc_rBase c))
                        else pullOther
                    | _ => pullOther
                    end
                | (T_5, k) :: L', _ =>
                    match rc_R c with
                    | (T_0, r0) :: (T_1, r1) :: R' =>
                        if (r0 =? 1) && (r1 =? 1) && (1 <=? k) && headStartsZero L' (rc_lBase c) then
                          Some (mkRawCfg F ((T_1, 2) :: L') (rc_lBase c) ((T_0, 1) :: (T_1, 1) :: pushRun T_4 k R') (rc_rBase c))
                        else None
                    | _ => None
                    end
                | (T_3, k) :: L', _ =>
                    match rc_R c with
                    | (T_0, r0) :: (T_1, r1) :: R' =>
                        if (r0 =? 1) && (r1 =? 1) && (1 <=? k) && headStartsZero L' (rc_lBase c) then
                          Some (mkRawCfg F ((T_1, 2) :: L') (rc_lBase c) ((T_0, 1) :: (T_1, 1) :: pushRun T_2 k R') (rc_rBase c))
                        else None
                    | _ => None
                    end
                | _, _ => None
                end
            end
          else None
      | _ => None
      end
  end.

Definition stepRaw (c : RawCfg) : option RawCfg :=
  match stepRawFast c with
  | Some c' => Some c'
  | None => stepRaw1 c
  end.

Fixpoint runRawUntil (done : RawCfg -> bool) (fuel : nat) (c : RawCfg) : option RawCfg :=
  match fuel with
  | O => if done c then Some c else None
  | S fuel' =>
      if done c then Some c
      else
        match stepRaw c with
        | None => None
        | Some c' => runRawUntil done fuel' c'
        end
  end.

Fixpoint segToRuns (segs : list SegPiece) : option (list (Tok * N)) :=
  match segs with
  | [] => Some []
  | SPsingle v :: rest =>
      option_map (fun r => (T_3, 1) :: (if v =? 0 then r else (T_4, v) :: r)) (segToRuns rest)
  | SPpair _ _ _ :: _ => None
  end.

Definition itemToRuns (it : RleItem) : option (list (Tok * N)) :=
  match it with
  | RIraw t n => Some (if n =? 0 then [] else [(t, n)])
  | RIsingle a h s0 segTail aRight =>
      option_map (fun sr =>
        (if a =? 0 then [] else [(T_2, a)])
        ++ (match aRight with None => [] | Some aR => (T_0, 1) :: (if aR =? 0 then [] else [(T_2, aR)]) end)
        ++ (if h then [(T_0, 1); (T_1, 1); (T_2, 1)] else [])
        ++ (if s0 =? 0 then [] else [(T_4, s0)])
        ++ sr) (segToRuns segTail)
  | _ => None
  end.

Fixpoint itemsToRuns (xs : list RleItem) : option (list (Tok * N)) :=
  match xs with
  | [] => Some []
  | x :: xs' =>
      match itemToRuns x, itemsToRuns xs' with
      | Some rx, Some rxs => Some (rx ++ rxs)
      | _, _ => None
      end
  end.

Definition runsToItems (rs : list (Tok * N)) : list RleItem :=
  List.map (fun tn => RIraw (fst tn) (snd tn)) rs.

Definition footerRuns : list (Tok * N) := [(T_0, 1); (T_1, 1); (T_0, 1); (T_1, 1)].
Definition shortFooterRuns : list (Tok * N) := [(T_0, 1); (T_1, 1)].

Definition stripFooterRuns (rs : list (Tok * N)) : option (list (Tok * N)) :=
  match List.rev rs with
  | (T_1, c1) :: (T_0, c2) :: (T_1, c3) :: (T_0, c4) :: rest =>
      if (c1 =? 1) && (c2 =? 1) && (c3 =? 1) && (c4 =? 1) then Some (List.rev rest) else None
  | _ => None
  end.

Definition stripShortFooterRuns (rs : list (Tok * N)) : option (list (Tok * N)) :=
  match List.rev rs with
  | (T_1, c1) :: (T_0, c2) :: rest =>
      if (c1 =? 1) && (c2 =? 1) then Some (List.rev rest) else None
  | _ => None
  end.

Definition isInitHubDone (c : RawCfg) : bool :=
  match rc_q c, rc_L c, rc_lBase c, rc_R c, rc_rBase c with
  | E, [], LBblank, (T_2, n2) :: (T_0, n0) :: (T_1, n1) :: R_out, RBblank =>
      if (n2 =? 1) && (n0 =? 1) && (n1 =? 1) then isSome (stripFooterRuns R_out) else false
  | _, _, _, _, _ => false
  end.

Definition runRawFromInit (fuel : nat) : option (list RleItem) :=
  let rc0 := mkRawCfg A [] LBblank [] RBblank in
  match runRawUntil isInitHubDone fuel rc0 with
  | Some rc1 =>
      match rc_q rc1, rc_L rc1, rc_lBase rc1, rc_R rc1, rc_rBase rc1 with
      | E, [], LBblank, (T_2, n2) :: (T_0, n0) :: (T_1, n1) :: R_out, RBblank =>
          if (n2 =? 1) && (n0 =? 1) && (n1 =? 1) then
            option_map runsToItems (stripFooterRuns R_out)
          else None
      | _, _, _, _, _ => None
      end
  | None => None
  end.

Definition isRawHalt (c : RawCfg) : bool :=
  match rc_q c, popBit (rc_R c) (isRBblank (rc_rBase c)) with
  | F, Some (S1, _) => true
  | _, _ => false
  end.

Definition pop01 (rs : list (Tok * N)) (isBlank : bool) : option (list (Tok * N)) :=
  match popBit rs isBlank with
  | Some (S0, r1) =>
      match popBit r1 isBlank with
      | Some (S1, r2) => Some r2
      | _ => None
      end
  | _ => None
  end.

Definition stepRawHalt1 (c : RawCfg) : option RawCfg :=
  match rc_q c, rc_L c, rc_lBase c with
  | F, [(T_1, n1)], LBpipe Ep rev =>
      if (n1 =? 2) && (Ep =? 0) then
        match pop01 (rc_R c) (isRBblank (rc_rBase c)), itemsToRuns (List.rev rev) with
        | Some R', Some prefRuns =>
            Some (mkRawCfg E [] LBblank ((T_2, 1) :: (T_0, 1) :: (T_1, 1) :: (prefRuns ++ R')) (rc_rBase c))
        | _, _ => stepRaw c
        end
      else stepRaw c
  | _, _, _ => stepRaw c
  end.

Fixpoint runRawHaltUntil (done : RawCfg -> bool) (fuel : nat) (c : RawCfg) : option RawCfg :=
  match fuel with
  | O => if done c then Some c else None
  | S fuel' =>
      if done c then Some c
      else
        match stepRawHalt1 c with
        | None => None
        | Some c' => runRawHaltUntil done fuel' c'
        end
  end.

Definition runPipeRawHalt (prefixLen winLen fuel : nat) (xs : list RleItem) : bool :=
  match splitAtList prefixLen xs with
  | None => false
  | Some (pref, afterPref) =>
      match splitAtList winLen afterPref with
      | None => false
      | Some (win, tail) =>
          match itemsToRuns win with
          | None => false
          | Some winRuns =>
              let rBase := if isEmpty tail then RBblank else RBtail in
              let R_body := if isEmpty tail then winRuns ++ footerRuns else winRuns in
              let initRaw :=
                if Nat.eqb prefixLen O then
                  Some (mkRawCfg E [] LBblank ((T_2, 1) :: (T_0, 1) :: (T_1, 1) :: R_body) rBase)
                else
                  match step1HubPrefix pref with
                  | None => None
                  | Some (false, Ep, revPref) =>
                      Some (mkRawCfg F [(T_1, 2)] (LBpipe Ep revPref) R_body rBase)
                  | Some (true, Ep, revPref) =>
                      Some (mkRawCfg A [(T_1, 1); (T_2, 1)] (LBpipe Ep revPref) R_body rBase)
                  end in
              match initRaw with
              | None => false
              | Some rc0 => isSome (runRawHaltUntil isRawHalt fuel rc0)
              end
          end
      end
  end.

(* ========================================================================= *)
(* Semigroup Sink Dumper (dumpFromT1, applySinkDumpBig)                      *)
(* ========================================================================= *)

Definition isSkipP2Item (it : RleItem) : bool :=
  match it with
  | RIsingle a h s0 [] None => h || ((1 <=? a) && (1 <=? s0))
  | RItranspRun a b _ => (1 <=? a) && (1 <=? b)
  | RIpairRun a1 h1 b1 a2 h2 b2 _ =>
      (h1 || ((1 <=? a1) && (1 <=? b1))) && (h2 || ((1 <=? a2) && (1 <=? b2)))
  | _ => false
  end.

Fixpoint hasPosSeg (segs : list SegPiece) : bool :=
  match segs with
  | [] => false
  | SPsingle _ :: _ => true
  | SPpair _ _ rep :: rest => (1 <=? rep) || hasPosSeg rest
  end.

Definition matchPairSeg (E : N) (segs : list SegPiece) : option (N * N * N * list SegPiece) :=
  match segs with
  | SPpair v1 v2 rep :: rest =>
      if (2 <=? v1) && (2 <=? v2) && (1 <=? rep) && (v1 + v2 <=? E) then
        let maxQ := if hasPosSeg rest then rep else rep - 1 in
        let q := N.min (E / (v1 + v2)) maxQ in
        if 1 <=? q then
          Some (v1, v2, q, if rep =? q then rest else SPpair v1 v2 (rep - q) :: rest)
        else None
      else None
  | _ => None
  end.

Fixpoint dumpFromT1Aux (fuel : nat) (E : N) (segs : list SegPiece) : option (list RleItem) :=
  match fuel with
  | O => None
  | S fuel' =>
      if E =? 0 then
        match unpackFrontSeg segs with
        | Some (s1, rest) => Some [RIraw T_1 1; RIsingle 0 false s1 rest None]
        | None => None
        end
      else
        match matchPairSeg E segs with
        | Some (v1, v2, q, segs') =>
            if E - q * (v1 + v2) <? E then
              option_map (fun ys => RIpairRun 1 true (v1 - 1) 1 true (v2 - 1) q :: ys)
                (dumpFromT1Aux fuel' (E - q * (v1 + v2)) segs')
            else None
        | None =>
            match unpackFrontSeg segs with
            | Some (s1, segRest) =>
                if 2 <=? s1 then
                  if E <=? s1 - 1 then
                    Some [RIsingle 1 true (E - 1) (SPsingle (s1 - 1 - E) :: segRest) None]
                  else if hasPosSeg segRest then
                    if E - s1 <? E then
                      option_map (fun ys => RIsingle 1 true (s1 - 1) [] None :: ys)
                        (dumpFromT1Aux fuel' (E - s1) segRest)
                    else None
                  else None
                else None
            | None => None
            end
        end
  end.

Definition dumpFromT1 (E : N) (segs : list SegPiece) : option (list RleItem) :=
  dumpFromT1Aux (2 * List.length segs + 4)%nat E segs.

Fixpoint applySinkDumpBig (E : N) (items : list RleItem) {struct items} : option (list RleItem) :=
  if E =? 0 then Some items
  else
    match items with
    | [] => None
    | item :: rest =>
        match item with
        | RIsingle aL h s0 segTail (Some aR) =>
            if (h || (1 <=? s0)) && (2 * E <=? aR) then
              Some (RIsingle (aL + 2 * E) h s0 segTail (Some (aR - 2 * E)) :: rest)
            else None
        | RIsingle a h s0 segTail None =>
            if isEmpty segTail && isEmpty rest then
              if h || ((1 <=? a) && (1 <=? s0)) then
                Some [RIsingle a h (s0 + E) [] None]
              else None
            else if isEmpty segTail then
              if h || ((1 <=? a) && (1 <=? s0)) then
                option_map (fun ys => RIsingle a h s0 [] None :: ys) (applySinkDumpBig E rest)
              else None
            else
              match unpackFrontSeg segTail with
              | Some (s1, segRest) =>
                  if E <=? s1 then
                    if h || ((1 <=? a) && (1 <=? s0)) then
                      Some (RIsingle a h (s0 + E) (SPsingle (s1 - E) :: segRest) None :: rest)
                    else None
                  else if (a =? 1) && h && hasPosSeg segRest then
                    option_map
                      (fun emitted => RIsingle 1 true (s0 + s1 + 1) [] None :: emitted ++ rest)
                      (dumpFromT1 (E - (s1 + 1)) segRest)
                  else None
              | None => None
              end
        | RIraw T_1 n1 =>
            if n1 =? 1 then
              match rest with
              | RIsingle a2 false s1 segRest None :: rest' =>
                  if a2 =? 0 then
                    option_map (fun ys => ys ++ rest') (dumpFromT1 E (SPsingle s1 :: segRest))
                  else None
              | _ => None
              end
            else None
        | _ =>
            if isSkipP2Item item then
              option_map (fun ys => item :: ys) (applySinkDumpBig E rest)
            else None
        end
    end.

(* ========================================================================= *)
(* Odometer / Eater / Slicer / Wave / Mirror Macro Accelerators              *)
(* ========================================================================= *)

Definition c0Valid (a0 : N) (h0 : bool) (b0 : N) : bool :=
  (3 <=? a0) && (if h0 then (a0 mod 2 =? 0) && (2 <=? b0) else (a0 mod 2 =? 1) && (3 <=? b0)).

Definition c0E1 (a0 : N) (h0 : bool) (b0 : N) : N :=
  if h0 then a0 / 2 - b0 else a0 / 2 + 2 - b0.

Definition c0StepN (a0 : N) (h0 : bool) (b0 Nv : N) : N * bool * N :=
  let nH0 := if h0 then Nv / 2 else (Nv + 1) / 2 in
  (a0 + 3 * Nv, if Nv mod 2 =? 1 then negb h0 else h0, b0 - 2 * nH0).

Definition c0TotalIn (a0 : N) (h0 : bool) (b0 Nv : N) : N :=
  let M := Nv / 2 in
  let ah0 := a0 / 2 in
  let eEv := if h0 then ah0 - b0 else ah0 + 2 - b0 in
  let eOd := if h0 then ah0 + 3 - b0 else ah0 + 4 - b0 in
  let tot := M * (eEv + eOd) + 5 * M * (M - 1) in
  if Nv mod 2 =? 1 then tot + eEv + 5 * M else tot.

Definition isTranspItem (it : RleItem) : bool :=
  match it with
  | RIsingle a false b [] None => (2 <=? a) && (a mod 2 =? 0) && (2 <=? b)
  | RItranspRun a b rep => (2 <=? a) && (a mod 2 =? 0) && (2 <=? b) && (1 <=? rep)
  | _ => false
  end.

Definition isTranspList (xs : list RleItem) : bool :=
  List.forallb isTranspItem xs.

Definition transpItemCost (it : RleItem) : N :=
  match it with
  | RIsingle a _ b _ _ => a / 2 + b
  | RItranspRun a b rep => rep * (a / 2 + b)
  | _ => 0
  end.

Fixpoint transpListCost (xs : list RleItem) : N :=
  match xs with
  | [] => 0
  | x :: xs' => transpItemCost x + transpListCost xs'
  end.

Definition digState (a : N) (h : bool) : option N :=
  if h then
    if a mod 2 =? 1 then Some 0 else if 2 <=? a then Some 1 else None
  else
    if a mod 2 =? 1 then Some 2 else None.

Definition digStep1 (a : N) (h : bool) (b : N) : N * bool * N * N * bool :=
  if h then
    if a mod 2 =? 1 then (a + 1, true, b - 1, a / 2, false)
    else (a + 1, false, b, a / 2, false)
  else
    (a, true, b - 1, a / 2 + b, true).

Definition digCycleCost (a : N) (h : bool) (b Qv : N) : N :=
  let base := 3 * (a / 2) + b + (if h && (a mod 2 =? 0) then 0 else 1) in
  Qv * base + (Qv * (Qv - 1)) / 2.

Fixpoint digStepGo (u : nat) (aa : N) (hh : bool) (bb cc co : N) : N * bool * N * N * N :=
  match u with
  | O => (aa, hh, bb, cc, co)
  | S u' =>
      let '(aa', hh', bb', dc, cry) := digStep1 aa hh bb in
      digStepGo u' aa' hh' bb' (cc + dc) (co + (if cry then 1 else 0))
  end.

Definition digStepFast (a : N) (h : bool) (b Cv : N) : N * bool * N * N * N :=
  let Qv := Cv / 3 in
  let rem := N.to_nat (Cv mod 3) in
  let cQ := digCycleCost a h b Qv in
  digStepGo rem (a + 2 * Qv) h (b - 2 * Qv) cQ Qv.

Definition liftDigitRelayLB (a : N) (h : bool) (b Qv Bv Dv B_last : N) : option (N * N * N) :=
  if (Qv =? 0) || (b <? 2 * Qv + 2) || (Dv <? 1) then None
  else
    match digState a h with
    | Some st =>
        let m := a / 2 in
        if st =? 2 then
          if (m + 3 <=? Bv) && (m + Qv + 1 <=? B_last) &&
             ((Qv <=? 1) || (3 * m + b + 1 <=? 3 * Bv + 3 * Dv)) &&
             (3 * m + b + Qv <=? 2 * Bv + Dv * (6 * Qv - 5) + B_last) then
            Some (3 * Bv + 3 * Dv - (3 * m + b + 1), 9 * Dv - 1,
                  2 * Bv + Dv * (6 * Qv - 5) + B_last - (3 * m + b + Qv))
          else None
        else if st =? 1 then
          if (m + 1 <=? Bv) && (m + 3 <=? Bv + Dv) && (m + Qv <=? B_last) &&
             ((Qv <=? 1) || (3 * m + b + 1 <=? 3 * Bv + 6 * Dv)) &&
             (2 * m + b + 1 <=? Bv + Dv * (3 * Qv - 2) + B_last) then
            Some (3 * Bv + 6 * Dv - (3 * m + b + 1), 9 * Dv - 1,
                  Bv + Dv * (3 * Qv - 2) + B_last - (2 * m + b))
          else None
        else if st =? 0 then
          let lastCost := m + Qv + (b - 2 * Qv + 1) in
          if (m + 1 <=? Bv) && (m + 2 <=? Bv + Dv) && (m + 4 <=? Bv + 2 * Dv) &&
             ((Qv <=? 1) || (3 * m + b + 3 <=? 3 * Bv + 9 * Dv)) &&
             (lastCost + 1 <=? B_last) then
            Some (3 * Bv + 9 * Dv - (3 * m + b + 3), 9 * Dv - 1, B_last - lastCost)
          else None
        else None
    | None => None
    end.

Definition ActiveGroup : Type := list RleItem * N * bool * N.

Fixpoint splitActivePrefixAux (revSp : list RleItem) (k : nat) (items : list RleItem)
    {struct items} : option (list ActiveGroup * list RleItem) :=
  match k with
  | O => if isEmpty revSp then Some ([], items) else None
  | S k' =>
      match items with
      | [] => None
      | x :: rest =>
          if isTranspItem x then
            splitActivePrefixAux (x :: revSp) (S k') rest
          else
            match x with
            | RIsingle a h b [] None =>
                if isSome (digState a h) then
                  option_map (fun p => ((List.rev revSp, a, h, b) :: fst p, snd p))
                    (splitActivePrefixAux [] k' rest)
                else None
            | _ => None
            end
      end
  end.

Definition splitActivePrefix (k : nat) (items : list RleItem)
    : option (list ActiveGroup * list RleItem) :=
  splitActivePrefixAux [] k items.

Fixpoint itemsOfActiveGroups (gs : list ActiveGroup) : list RleItem :=
  match gs with
  | [] => []
  | (sp, a, h, b) :: gs' => sp ++ [RIsingle a h b [] None] ++ itemsOfActiveGroups gs'
  end.

Fixpoint runRelayDigits (mult Bv Dv B_last : N) (gs : list ActiveGroup)
    : option (list ActiveGroup * N * N * N * N) :=
  match gs with
  | [] => Some ([], 0, Bv, Dv, B_last)
  | (sp, a, h, b) :: gs' =>
      let sc := transpListCost sp in
      if (Bv <? sc) || (B_last <? sc) then None
      else
        let Qv := mult * (3 ^ N.of_nat (List.length gs')) in
        let B1 := Bv - sc in
        let L1 := B_last - sc in
        match liftDigitRelayLB a h b Qv B1 Dv L1 with
        | Some (B2, D2, L2) =>
            option_map
              (fun res =>
                let '(gsOut, cRest, Bf, Df, Lf) := res in
                ((sp, a + 2 * Qv, h, b - 2 * Qv) :: gsOut,
                 (3 * Qv) * sc + digCycleCost a h b Qv + cRest, Bf, Df, Lf))
              (runRelayDigits mult B2 D2 L2 gs')
        | None => None
        end
  end.

Definition relayFinalOk (mult aF : N) (hF : bool) (bF scF B1 L1 : N) : option (N * bool * N * N) :=
  let mF := aF / 2 in
  match digState aF hF with
  | Some st =>
      if st =? 0 then
        if mult =? 1 then
          if (2 <=? bF) && (mF + 1 <=? L1) then
            Some (aF + 1, true, bF - 1, scF + mF)
          else None
        else
          if (3 <=? bF) && (mF + 1 <=? B1) && (mF + 2 <=? L1) then
            Some (aF + 2, false, bF - 1, 2 * scF + 2 * mF + 1)
          else None
      else if st =? 1 then
        if (mult =? 1) && (2 <=? bF) && (mF + 1 <=? L1) then
          Some (aF + 1, false, bF, scF + mF)
        else None
      else None
  | None => None
  end.

Definition stepOdoRelay (k : nat) (mult : N) (items : list RleItem) : option (list RleItem) :=
  if negb (mult =? 1) && negb (mult =? 2) then None
  else
    match items with
    | RIsingle a0 h0 b0 [] None :: rest =>
        let Nv := mult * (3 ^ N.of_nat k) in
        if negb (c0Valid a0 h0 b0 && (Nv + (if h0 then 4 else 5) <=? b0) && (b0 + 1 <=? a0 / 2)) then None
        else
          match splitActivePrefix (S k) rest with
          | Some (allGs, suf) =>
              match List.rev allGs with
              | (spF, aF, hF, bF) :: revMid =>
                  let midGs := List.rev revMid in
                  let e0 := c0E1 a0 h0 b0 in
                  match runRelayDigits mult e0 2 (e0 + 2 * (Nv - 1)) midGs with
                  | Some (midGs', midCost, Bf, _Df, Lf) =>
                      let scF := transpListCost spF in
                      if (Bf <? scF) || (Lf <? scF) then None
                      else
                        let B1 := Bf - scF in
                        let L1 := Lf - scF in
                        match relayFinalOk mult aF hF bF scF B1 L1 with
                        | Some (aF', hF', bF', fCost) =>
                            let totIn := c0TotalIn a0 h0 b0 Nv in
                            let totCost := midCost + fCost in
                            if totCost <=? totIn then
                              let '(a0', h0', b0') := c0StepN a0 h0 b0 Nv in
                              option_map
                                (fun suf' =>
                                  RIsingle a0' h0' b0' [] None ::
                                    itemsOfActiveGroups midGs' ++ spF ++ [RIsingle aF' hF' bF' [] None] ++ suf')
                                (applySinkDumpBig (totIn - totCost) suf)
                            else None
                        | None => None
                        end
                  | None => None
                  end
              | [] => None
              end
          | None => None
          end
    | _ => None
    end.

Fixpoint runD0Digits (Cv Mv : N) (gs : list ActiveGroup)
    : option (list ActiveGroup * N * N * N) :=
  match gs with
  | [] => Some ([], 0, Cv, Mv)
  | (sp, a, h, b) :: gs' =>
      let sc := transpListCost sp in
      if Mv <? sc then None
      else
        let M1 := Mv - sc in
        if (a <? 1) || (b <? 2 * (Cv / 3) + 4) || (M1 <? a / 2 + b + 2) then None
        else
          let '(a', h', b', cost, C') := digStepFast a h b Cv in
          let M2 := M1 - (a / 2 + b) in
          option_map
            (fun res =>
              let '(gsOut, cRest, Cf, Mf) := res in
              ((sp, a', h', b') :: gsOut, Cv * sc + cost + cRest, Cf, Mf))
            (runD0Digits C' M2 gs')
  end.

Definition stepOdoD0 (k : nat) (Nv : N) (items : list RleItem) : option (list RleItem) :=
  if Nv =? 0 then None
  else
    match items with
    | RIsingle a0 h0 b0 [] None :: rest =>
        if negb (c0Valid a0 h0 b0 && (Nv + (if h0 then 4 else 5) <=? b0) && (b0 + 1 <=? a0 / 2)) then None
        else
          match splitActivePrefix k rest with
          | Some (gs, suf) =>
              let M0 := c0E1 a0 h0 b0 in
              match runD0Digits Nv M0 gs with
              | Some (gs', totCost, Cf, _Mf) =>
                  if negb (Cf =? 0) then None
                  else
                    let totIn := c0TotalIn a0 h0 b0 Nv in
                    if totIn <? totCost then None
                    else
                      let E_rem := totIn - totCost in
                      match applySinkDumpBig E_rem suf with
                      | Some suf' =>
                          let '(aN, hN, bN) := c0StepN a0 h0 b0 Nv in
                          Some (RIsingle aN hN bN [] None :: itemsOfActiveGroups gs' ++ suf')
                      | None => None
                      end
              | None => None
              end
          | None => None
          end
    | _ => None
    end.

Definition eaterConst (B_tr : N) : N :=
  let q := B_tr / 2 - 1 in
  q * (B_tr + 1) + (q * (q - 1)) / 2 + 3 * q + 3.

Definition eaterC1Cost (ah1 d_ah1 B_tr Mv : N) : N :=
  let N_eat := 3 * (B_tr / 2) in
  Mv * (ah1 * N_eat + eaterConst B_tr) + (d_ah1 * N_eat) * (Mv * (Mv - 1) / 2).

Definition eaterC2Cost (T_tr B_tr rep Mv : N) : N :=
  let C_eat := B_tr / 2 in
  (T_tr * C_eat) * (Mv * rep - Mv * (Mv - 1) / 2).

Definition stepEater (k : nat) (Mv : N) (items : list RleItem) : option (list RleItem) :=
  if Mv =? 0 then None
  else
    match items with
    | RIsingle a0 h0 b0 [] None :: RIsingle a1 false B_tr [] None :: RItranspRun A_tr B_tr2 rep :: rest =>
        if negb ((4 <=? B_tr) && (B_tr mod 2 =? 0) && (B_tr2 =? B_tr) &&
                 (2 <=? A_tr) && (A_tr mod 2 =? 0) &&
                 (3 <=? a1) && (a1 mod 2 =? 1) && (Mv + 1 <=? rep)) then None
        else
          let C_eat := B_tr / 2 in
          let Nv := Mv * (3 * C_eat) in
          if negb (c0Valid a0 h0 b0 && (Nv + (if h0 then 4 else 5) <=? b0) && (b0 + 1 <=? a0 / 2)) then None
          else
            let ah1 := a1 / 2 in
            let T_tr := A_tr / 2 + B_tr in
            let d_ah1 := A_tr / 2 + C_eat in
            let E0 := c0E1 a0 h0 b0 in
            let floorCost := ah1 + B_tr + 3 + rep * T_tr in
            if E0 <? floorCost then None
            else
              match splitActivePrefix k rest with
              | Some (gs, suf) =>
                  let M_out := E0 - floorCost in
                  let C_out := Mv * C_eat in
                  match runD0Digits C_out M_out gs with
                  | Some (gs', c3_cost, Cf, _Mf) =>
                      if negb (Cf =? 0) then None
                      else
                        let totIn := c0TotalIn a0 h0 b0 Nv in
                        let c12_cost := eaterC1Cost ah1 d_ah1 B_tr Mv + eaterC2Cost T_tr B_tr rep Mv in
                        let totCost := c12_cost + c3_cost in
                        if totIn <? totCost then None
                        else
                          match applySinkDumpBig (totIn - totCost) suf with
                          | Some suf' =>
                              let '(aN, hN, bN) := c0StepN a0 h0 b0 Nv in
                              Some (RIsingle aN hN bN [] None ::
                                    RIsingle (a1 + Mv * (A_tr + B_tr)) false B_tr [] None ::
                                    RItranspRun A_tr B_tr (rep - Mv) ::
                                    itemsOfActiveGroups gs' ++ suf')
                          | None => None
                          end
                  | None => None
                  end
              | None => None
              end
    | _ => None
    end.

Definition stepSlicer12 (k0 k1 : nat) (Mv : N) (items : list RleItem) : option (list RleItem) :=
  match items with
  | RIsingle a0 true b0 [] None :: rest0 =>
      if negb (a0 mod 2 =? 0) || (b0 <? 12 * Mv + 2) then None
      else
        match splitAtList k0 rest0 with
        | None => None
        | Some (sp0, rest1) =>
            if negb (isTranspList sp0) then None
            else
              match rest1 with
              | RIsingle a1 false b1 [] None :: rest2 =>
                  if negb (a1 mod 2 =? 1) || (b1 <? 8 * Mv + 2) then None
                  else
                    match splitAtList k1 rest2 with
                    | None => None
                    | Some (sp1, rest3) =>
                        if negb (isTranspList sp1) then None
                        else
                          match rest3 with
                          | RIsingle aj false sj segTail None :: rest4 =>
                              if negb (aj mod 2 =? 0) || (sj <? 64) then None
                              else
                                let m0 := a0 / 2 in
                                let m1 := a1 / 2 in
                                let m := aj / 2 in
                                let Dv := sj - 64 in
                                let C0 := transpListCost sp0 in
                                let C1 := transpListCost sp1 in
                                if (b0 + C0 + m1 + 3 <=? m0) && (85 * Mv <=? Dv) && (Dv + 1 <=? m) &&
                                   (3 * (m0 - b0 - C0) + 8 =? (3 * m1 + b1 + 1) + C1 + (m - Dv)) then
                                  Some (
                                    RIsingle (a0 + 36 * Mv) true (b0 - 12 * Mv) [] None ::
                                    sp0 ++
                                    RIsingle (a1 + 8 * Mv) false (b1 - 8 * Mv) [] None ::
                                    sp1 ++
                                    RIsingle (aj + 2 * Mv) false (sj - 85 * Mv) (SPpair 41 40 Mv :: segTail) None ::
                                    rest4)
                                else None
                          | _ => None
                          end
                    end
              | _ => None
              end
        end
  | _ => None
  end.

Definition wave402dS0 (m0 b0 sp0_c m1 b1 sp1_c k_tr : N) : N :=
  402 * (m0 - b0 - sp0_c) + 186988 - 134 * (3 * m1 + b1 + 1 + sp1_c + 97 * k_tr).

Definition wave402Stot (m0 b0 sp0_c m1 b1 sp1_c k_tr Wv : N) : N :=
  Wv * wave402dS0 m0 b0 sp0_c m1 b1 sp1_c k_tr + 186528 * Wv * (Wv - 1).

Definition wave402RegimeOk (m0 b0 sp0_c m1 b1 sp1_c k_tr Wv : N) : bool :=
  if Wv =? 0 then true
  else
    let E0 := m0 - b0 - sp0_c in
    let Cv := sp1_c + 97 * k_tr in
    let E1_max := E0 + 1005 * (Wv - 1) + 998 in
    let m1_max := m1 + 134 * Wv - 1 in
    let b1_max := b1 - 268 * Wv + 2 in
    let C_max := Cv + 97 * (Wv - 1) in
    let ok2 := (2 * E1_max + 2 <? 2 * m1_max + b1_max) &&
               (Cv + 150 + (3 * m1 + b1 + 1) <=? 3 * E0 + 8) in
    let ok1A := (E1_max <? m1_max + b1_max) &&
                (Cv + 150 + (2 * m1 + b1) <=? 2 * E0 + 3) in
    let ok0A := (Cv + 150 + (m1 + b1) <=? E0) in
    let ok0C := (m1 + b1 <=? E0) &&
                (E1_max <? m1_max + b1_max + C_max) &&
                (Cv + 150 + (2 * m1 + b1) <=? 2 * E0 + 3) in
    let ok0B := (m1 + b1 <=? E0) &&
                (2 * E1_max + 2 <? 2 * m1_max + b1_max + C_max) &&
                (Cv + 150 + (3 * m1 + b1 + 1) <=? 3 * E0 + 8) in
    let ok1B := (E1_max <? m1_max + b1_max) &&
                (2 * E1_max + 2 <? 2 * m1_max + b1_max + C_max) &&
                (Cv + 150 + (3 * m1 + b1 + 1) <=? 3 * E0 + 8) in
    ok2 || ok1A || ok0A || ok0C || ok0B || ok1B.

Definition extractTR138 (hasTR : bool) (xs : list RleItem) : option (N * list RleItem) :=
  if hasTR then
    match xs with
    | RItranspRun ay by' k_tr :: rest =>
        if (ay =? 138) && (by' =? 28) then Some (k_tr, rest) else None
    | _ => None
    end
  else Some (0, xs).

Definition stepWave402 (k0 k1 : nat) (Wv : N) (hasTR : bool) (items : list RleItem) : option (list RleItem) :=
  match items with
  | RIsingle a0 true b0 [] None :: rest0 =>
      if negb (a0 mod 2 =? 0) then None
      else
        match splitAtList k0 rest0 with
        | None => None
        | Some (sp0, rest1a) =>
            if negb (isTranspList sp0) then None
            else
              match rest1a with
              | RIsingle a1 false b1 [] None :: rest1 =>
                  if negb (a1 mod 2 =? 1) then None
                  else
                    match splitAtList k1 rest1 with
                    | None => None
                    | Some (sp1, rest2) =>
                        if negb (isTranspList sp1) then None
                        else
                          match extractTR138 hasTR rest2 with
                          | None => None
                          | Some (k_tr, rest3) =>
                              match rest3 with
                              | RIsingle au1 true bu1 [] None :: RIsingle au2 false bu2 [] None ::
                                RIpairRun pa1 true pb1 pa2 true pb2 pr :: tail =>
                                  if (au1 =? 5) && (bu1 =? 35) && (au2 =? 3) && (bu2 =? 39) &&
                                     (pa1 =? 1) && (pb1 =? 39) && (pa2 =? 1) && (pb2 =? 40) then
                                    let m0 := a0 / 2 in
                                    let m1 := a1 / 2 in
                                    let c0 := transpListCost sp0 in
                                    let c1 := transpListCost sp1 in
                                    if (402 * Wv + 3 <=? b0) && (b0 + c0 + m1 + 4 <=? m0) &&
                                       (268 * Wv + 2 <=? b1) && (2 * Wv <=? pr) &&
                                       wave402RegimeOk m0 b0 c0 m1 b1 c1 k_tr Wv then
                                      let S_tot := wave402Stot m0 b0 c0 m1 b1 c1 k_tr Wv in
                                      match applySinkDumpBig S_tot tail with
                                      | None => None
                                      | Some tail' =>
                                          let trOut :=
                                            if k_tr + Wv =? 0 then [] else [RItranspRun 138 28 (k_tr + Wv)] in
                                          Some (RIsingle (a0 + 1206 * Wv) true (b0 - 402 * Wv) [] None ::
                                            sp0 ++ [RIsingle (a1 + 268 * Wv) false (b1 - 268 * Wv) [] None] ++
                                            sp1 ++ trOut ++
                                            [RIsingle 5 true 35 [] None; RIsingle 3 false 39 [] None;
                                             RIpairRun 1 true 39 1 true 40 (pr - 2 * Wv)] ++ tail')
                                      end
                                    else None
                                  else None
                              | _ => None
                              end
                          end
                    end
              | _ => None
              end
        end
  | _ => None
  end.

Definition m3752Stot (m0 b0 sp0_c k rep Mv : N) : N :=
  let dS0 := 1876 * (k - (m0 - b0 - sp0_c) - 97 * rep) + 1080450 in
  Mv * dS0 + 1240036 * Mv * (Mv - 1).

Definition stepMirror3752 (k0 : nat) (Mv : N) (items : list RleItem) : option (list RleItem) :=
