                       (97 * rep + 6620 <=? k - (m0 - b0 - c0)) &&
                       ((m0 - b0 - c0) + 3819 * Mv + 4040 <=? k) then
                      let S_tot := m3752Stot m0 b0 c0 k rep Mv in
                      match applySinkDumpBig S_tot tail with
                      | None => None
                      | Some tail' =>
                          Some (RIsingle (a0 + 11256 * Mv) true (b0 - 3752 * Mv) [] None ::
                            sp0 ++ [RIsingle (am + 11122 * Mv) true 27 [] None;
                              RItranspRun 138 28 (rep - 53 * Mv);
