Definition m162Stot (m0 b0 sp0_c k Mv : N) : N :=
  let dS0 := 81 * (k - (m0 - b0 - sp0_c)) - 15577 in
  Mv * dS0 - 13041 * Mv * (Mv - 1).

Definition stepMirror162 (k0 : nat) (Mv : N) (items : list RleItem) : option (list RleItem) :=
  match items with
  | RIsingle a0 true b0 [] None :: rest0 =>
      if negb (a0 mod 2 =? 0) then None
      else
        match splitAtList k0 rest0 with
        | None => None
        | Some (sp0, rest1) =>
            if negb (isTranspList sp0) then None
            else
              match rest1 with
              | RIsingle am true bm [] None ::
                RIsingle u1 true ub1 [] None :: RIsingle u2 true ub2 [] None :: RIsingle u3 true ub3 [] None ::
                RIpairRun pa1 true pb1 pa2 true pb2 pr :: tail =>
                  if (am mod 2 =? 1) && (bm =? 20) &&
                     (u1 =? 8) && (ub1 =? 32) && (u2 =? 3) && (ub2 =? 38) && (u3 =? 2) && (ub3 =? 38) &&
                     (pa1 =? 1) && (pb1 =? 40) && (pa2 =? 1) && (pb2 =? 39) then
                    let m0 := a0 / 2 in
                    let k := am / 2 in
                    let c0 := transpListCost sp0 in
                    if (162 * Mv + 3 <=? b0) && (b0 + c0 + 1 <=? m0) &&
                       (2 * Mv <=? pr) &&
                       ((m0 - b0 - c0) + 322 * Mv + 500 <=? k) then
                      let S_tot := m162Stot m0 b0 c0 k Mv in
                      match applySinkDumpBig S_tot tail with
                      | None => None
                      | Some tail' =>
                          Some (RIsingle (a0 + 486 * Mv) true (b0 - 162 * Mv) [] None ::
                            sp0 ++ [RIsingle (am + 166 * Mv) true 20 [] None;
                              RIsingle 8 true 32 [] None; RIsingle 3 true 38 [] None; RIsingle 2 true 38 [] None;
                              RIpairRun 1 true 40 1 true 39 (pr - 2 * Mv)] ++ tail')
                      end
                    else None
                  else None
              | _ => None
              end
        end
  | _ => None
  end.

(* ========================================================================= *)
(* Big 1-Hub & Raw Bridge Operators (hbz, hd, raw, raw2, auto)               *)
(* ========================================================================= *)

Definition step1Phase2OrBig (E : N) (revOut tail : list RleItem) : option (list RleItem) :=
  match step1Phase2 E revOut tail with
  | Some ys => Some ys
  | None => option_map (fun ys => List.rev revOut ++ ys) (applySinkDumpBig (E + 1) tail)
  end.

Inductive AsplitResult : Type :=
  | ARcreate (out : list RleItem)
  | ARdump (E_rem a : N) (h : bool) (q : N) (segs : list SegPiece)
  | ARcont (E' : N) (rev' : list RleItem) (segs : list SegPiece)
  | ARcontDrop1 (E' : N) (rev' : list RleItem) (segs2 : list SegPiece)
  | ARcontDrop1P2 (E' : N) (rev' : list RleItem).

Definition step1Phase1Asplit (E : N) (revOut : list RleItem) (aL : N) (h : bool) (s0 : N)
    (segTail : list SegPiece) (aR : N) (rest : list RleItem) : option AsplitResult :=
  if (aL mod 2 =? 1) && (aL / 2 + 2 <=? E) then
    if negb h && (s0 =? 1) && isEmpty segTail then
      match rest with
      | RIsingle a2 false b2 segTail2 None :: _ =>
          if (1 <=? a2) && (1 <=? b2) && (a2 + 2 <=? aR) then
            let rem := aR - a2 - 2 in
            let b2' := b2 - 1 in
            let E_avail := E - aL / 2 - 1 + rem / 2 in
            if b2' <=? E_avail then
              let hOut := rem mod 2 =? 0 in
              let bOut := if hOut then b2' else b2' + 1 in
              let rev' := RIsingle (aL + aR + a2 + 2) hOut bOut [] None :: revOut in
              Some (ARcontDrop1 (E_avail - b2') rev' segTail2)
            else None
          else None
      | RIsingle a2 true b2 segTail2 None :: _ =>
          if (1 <=? a2) && (1 <=? b2) && (a2 + 2 <=? aR) && isEmpty segTail2 then
            let rem := aR - a2 - 2 in
            let b2' := b2 - 1 in
            let E' := E - aL / 2 - 1 + rem / 2 in
            let hOut := rem mod 2 =? 0 in
            let bOut := if hOut then b2' else b2' + 1 in
            let rev' := RIsingle (aL + aR + a2 + 3) hOut bOut [] None :: revOut in
            Some (ARcontDrop1P2 E' rev')
          else None
      | _ => None
      end
    else if h && (s0 =? 0) && isEmpty segTail then
      match rest with
      | RIsingle a2 true b2 segTail2 None :: _ =>
          if (1 <=? b2) && (a2 + 2 <=? aR) && isEmpty segTail2 then
            let rem := aR - a2 - 2 in
            let b2' := b2 - 1 in
            let E' := E - aL / 2 - 1 + rem / 2 in
            let hOut := rem mod 2 =? 0 in
            let bOut := if hOut then b2' else b2' + 1 in
            let rev' := RIsingle (aL + aR + a2 + 3) hOut bOut [] None :: revOut in
            Some (ARcontDrop1P2 E' rev')
          else None
      | RIsingle a2 false b2 segTail2 None :: _ =>
          if (1 <=? b2) && (a2 + 2 <=? aR) then
            let rem := aR - a2 - 2 in
            let b2' := b2 - 1 in
            let E_avail := E - aL / 2 - 1 + rem / 2 in
            if b2' <=? E_avail then
              let hOut := rem mod 2 =? 0 in
              let bOut := if hOut then b2' else b2' + 1 in
              let rev' := RIsingle (aL + aR + a2 + 2) hOut bOut [] None :: revOut in
              Some (ARcontDrop1 (E_avail - b2') rev' segTail2)
            else None
          else None
      | _ => None
      end
    else
      let E_rem := E - aL / 2 - 2 in
      if aR mod 2 =? 1 then
        let q := aR / 2 in
        let base := if h then 1 else 2 in
        let need := q + base in
        if 1 <=? q then
          if need <=? s0 then
            Some (ARdump E_rem (aL + aR + 2) false q (SPsingle (s0 - need) :: segTail))
          else if base <=? s0 then
            let p := s0 - base in
            let d := q - p - 1 in
            let E' := E - aL / 2 - 1 + d in
            let rev' := RIsingle (aL + aR + 2) false (p + 1) [] None :: revOut in
            Some (ARcont E' rev' segTail)
          else None
        else None
      else
        if 2 <=? aR then
          let q := (aR - 2) / 2 in
          let base := if h then 2 else 3 in
          let need := q + base in
          if need <=? s0 then
            Some (ARdump E_rem (aL + aR + 2) true q (SPsingle (s0 - need) :: segTail))
          else if base <=? s0 then
            let p := s0 - base in
            let d := q - p - 1 in
            let E' := E - aL / 2 - 1 + d in
            let rev' := RIsingle (aL + aR + 2) true (p + 1) [] None :: revOut in
            Some (ARcont E' rev' segTail)
          else if (negb h && (s0 =? 2)) || (h && (s0 =? 1)) then
            let E' := E - aL / 2 - 1 + q in
            let rev' := RIsingle (aL + aR + 2) true 0 [] None :: revOut in
            Some (ARcont E' rev' segTail)
          else None
        else None
  else if (1 <=? E) && (2 * E + 1 <=? aL) then
    Some (ARcreate (List.rev revOut ++
      RIraw T_2 (2 * E - 1) :: RIraw T_0 1 ::
      RIsingle (aL - 2 * E) h s0 segTail (Some aR) :: rest))
  else None.

Definition step1DumpSegsBigAux
    (kP1Big : N -> list RleItem -> list RleItem -> option (list RleItem))
    (E : N) (revOut : list RleItem) (sa : N) (sh : bool) (s0 : N)
    (segTail : list SegPiece) (rest : list RleItem) : option (list RleItem) :=
  match unpackFrontSeg segTail with
  | None => None
  | Some (s1, segRest) =>
      if E + 1 <=? s1 then
        Some (List.rev revOut ++
          RIsingle sa sh (s0 + E + 1) (SPsingle (s1 - (E + 1)) :: segRest) None :: rest)
      else if s1 + 1 <=? E then
        let E' := E - s1 in
        let rev' := RIsingle sa sh (s0 + s1 + 1) [] None :: revOut in
        if isEmpty segRest then kP1Big E' rev' rest
        else step1Unzip E' rev' segRest rest
      else None
  end.

Fixpoint step1PhasesBigFuel (fuel : nat) (isP2 : bool) (E : N) (revOut tail : list RleItem)
    {struct fuel} : option (list RleItem) :=
  match fuel with
  | O => None
  | S fuel' =>
      let dumpBig := step1DumpSegsBigAux (step1PhasesBigFuel fuel' false) in
      if negb isP2 then
        (* step1Phase1Big *)
        match step1Phase1 E revOut tail with
        | Some ys => Some ys
        | None =>
            match tail with
            | [] => if 1 <=? E then Some (List.rev revOut ++ [RIsingle 0 true (E - 1) [] None]) else None
            | item :: rest =>
                match step1PrefP1 E revOut [item] with
                | Some (false, E', rev') => step1PhasesBigFuel fuel' false E' rev' rest
                | Some (true, E', rev') => step1PhasesBigFuel fuel' true E' rev' rest
                | None =>
                    match item with
                    | RIsingle a true s0 segTail None =>
                        if negb (isEmpty segTail) && (a / 2 + 1 <=? E) then
                          let E_rem := E - a / 2 - 1 in
                          if a mod 2 =? 0 then
                            if 1 <=? s0 then dumpBig E_rem revOut (a + 1) false s0 segTail rest
                            else None
                          else
                            if 2 <=? s0 then dumpBig E_rem revOut (a + 1) true (s0 - 1) segTail rest
                            else None
                        else if (a =? 0) && isEmpty segTail && (1 <=? E) && (1 <=? s0) then
                          step1PhasesBigFuel fuel' true (E - 1) (RIsingle 1 false s0 [] None :: revOut) rest
                        else if isEmpty segTail && (s0 =? 0) && (a / 2 + 1 <=? E) then
                          let E_rem := E - a / 2 - 1 in
                          match rest with
                          | RIsingle a2 h2 b2 segTail2 None :: rest2 =>
                              if a mod 2 =? 0 then
                                if h2 then
                                  if isEmpty segTail2 then
                                    step1PhasesBigFuel fuel' true E_rem (RIsingle (a + 1 + a2) true b2 [] None :: revOut) rest2
                                  else
                                    dumpBig E_rem revOut (a + 1 + a2) true b2 segTail2 rest2
                                else if 1 <=? b2 then
                                  if isEmpty segTail2 then
                                    step1PhasesBigFuel fuel' true E_rem (RIsingle (a + 1 + a2) false b2 [] None :: revOut) rest2
                                  else
                                    dumpBig E_rem revOut (a + 1 + a2) false b2 segTail2 rest2
                                else None
                              else
                                if negb h2 && (1 <=? b2) then
                                  if isEmpty segTail2 then
                                    step1PhasesBigFuel fuel' true E_rem (RIsingle (a + 1 + a2) true (b2 - 1) [] None :: revOut) rest2
                                  else
                                    dumpBig E_rem revOut (a + 1 + a2) true (b2 - 1) segTail2 rest2
                                else if h2 && (a / 2 + 2 <=? E) then
                                  let E_rem2 := E - a / 2 - 2 in
                                  if isEmpty segTail2 then
                                    step1PhasesBigFuel fuel' true E_rem2 (RIsingle (a + 1 + a2) false (b2 + 1) [] None :: revOut) rest2
                                  else
                                    dumpBig E_rem2 revOut (a + 1 + a2) false (b2 + 1) segTail2 rest2
                                else None
                          | RIsingle a2 false b2 segTail2 (Some aR) :: rest2 =>
                              if (a mod 2 =? 1) && (2 <=? aR) && (aR mod 2 =? 0) && (1 <=? b2) &&
                                 (a / 2 + aR / 2 + 1 <=? E) then
                                let Er := E - a / 2 - aR / 2 - 1 in
                                let a' := a + a2 + aR + 2 in
                                let b_rem := b2 - 1 in
                                if b_rem <=? Er then
                                  let E' := Er - b_rem in
                                  let rev' := RIsingle a' true b_rem [] None :: revOut in
                                  if isEmpty segTail2 then step1PhasesBigFuel fuel' false E' rev' rest2
                                  else step1Unzip E' rev' segTail2 rest2
                                else
                                  Some (List.rev revOut ++
                                    RIsingle a' true Er (SPsingle (b_rem - Er - 1) :: segTail2) None :: rest2)
                              else None
                          | _ => None
                          end
                        else None
                    | RIsingle a false s0 segTail None =>
                        if (a =? 0) && isEmpty segTail then
                          if s0 <=? E then
                            step1PhasesBigFuel fuel' false (E - s0) (RIsingle 0 false s0 [] None :: revOut) rest
                          else None
                        else
                          let jj := a / 2 in
                          if a mod 2 =? 0 then
                            if (2 <=? a) && (jj + 1 <=? E) && (E + 1 <=? jj + s0) then
                              Some (List.rev revOut ++
                                RIsingle a false (E - jj) (SPsingle (jj + s0 - E - 1) :: segTail) None :: rest)
                            else if (2 <=? a) && (1 <=? s0) && (jj + s0 <=? E) && negb (isEmpty segTail) then
                              step1Unzip (E - (jj + s0)) (RIsingle a false s0 [] None :: revOut) segTail rest
                            else None
                          else
                            if (jj + 1 <=? E) && (E + 1 <=? jj + s0) then
                              Some (List.rev revOut ++
                                RIsingle a true (E - jj - 1) (SPsingle (jj + s0 - E - 1) :: segTail) None :: rest)
                            else if (2 <=? s0) && (jj + s0 <=? E) && negb (isEmpty segTail) then
                              step1Unzip (E - (jj + s0)) (RIsingle a true (s0 - 1) [] None :: revOut) segTail rest
                            else None
                    | RIsingle aL h s0 segTail (Some aR) =>
                        match step1Phase1Asplit E revOut aL h s0 segTail aR rest with
                        | None => None
                        | Some (ARcreate out) => Some out
                        | Some (ARdump E_rem a h' q segs) => dumpBig E_rem revOut a h' q segs rest
                        | Some (ARcont E' rev' segs) =>
                            if isEmpty segs then step1PhasesBigFuel fuel' false E' rev' rest
                            else step1Unzip E' rev' segs rest
                        | Some (ARcontDrop1 E' rev' segs2) =>
                            match rest with
                            | _ :: rest2 =>
                                if isEmpty segs2 then step1PhasesBigFuel fuel' false E' rev' rest2
                                else step1Unzip E' rev' segs2 rest2
                            | [] => None
                            end
                        | Some (ARcontDrop1P2 E' rev') =>
                            match rest with
                            | _ :: rest2 => step1PhasesBigFuel fuel' true E' rev' rest2
                            | [] => None
                            end
                        end
                    | RIpairRun a1 true b1 a2 h2 b2 rep =>
                        if (1 <=? rep) && (1 <=? b1) && (a1 / 2 + 1 <=? E) &&
                           (h2 || ((1 <=? a2) && (1 <=? b2))) then
                          let E_rem := E - a1 / 2 - 1 in
                          let first := if a1 mod 2 =? 0 then RIsingle (a1 + 1) false b1 [] None
                                       else RIsingle (a1 + 1) true (b1 - 1) [] None in
                          let rev1 := RIsingle a2 h2 b2 [] None :: first :: revOut in
                          let rev2 := if rep =? 1 then rev1 else RIpairRun a1 true b1 a2 h2 b2 (rep - 1) :: rev1 in
                          step1PhasesBigFuel fuel' true E_rem rev2 rest
                        else None
                    | RItranspRun a b rep =>
                        if (2 <=? a) && (a mod 2 =? 0) && (1 <=? b) && (1 <=? rep) then
                          let jj := a / 2 in
                          let unit := jj + b in
                          let q := E / unit in
                          if q <? rep then
                            let E_rem := E - q * unit in
                            let rev1 := if q =? 0 then revOut else RItranspRun a b q :: revOut in
                            let tail' := if rep - q - 1 =? 0 then rest else RItranspRun a b (rep - q - 1) :: rest in
                            if (1 <=? E_rem) && (2 * E_rem + 1 <=? a) then
                              Some (List.rev rev1 ++ RIsingle (2 * E_rem - 1) false b [] (Some (a - 2 * E_rem)) :: tail')
                            else if (jj + 1 <=? E_rem) && (E_rem + 1 <=? unit) then
                              Some (List.rev rev1 ++ RIsingle a false (E_rem - jj) [SPsingle (unit - E_rem - 1)] None :: tail')
                            else None
                          else None
                        else None
                    | RIraw T_2 aL =>
                        if (1 <=? E) && (2 * E + 1 <=? aL) then
                          Some (List.rev revOut ++
                            RIraw T_2 (2 * E - 1) :: RIraw T_0 1 :: RIraw T_2 (aL - 2 * E) :: rest)
                        else None
                    | _ => None
                    end
                end
            end
        end
      else
        (* step1Phase2Big *)
        match step1Phase2OrBig E revOut tail with
        | Some ys => Some ys
        | None =>
            match tail with
            | [] => None
            | item :: rest =>
                match step1PrefP2 E revOut [item] with
                | Some (true, E', rev') => step1PhasesBigFuel fuel' true E' rev' rest
                | Some (false, E', rev') => step1PhasesBigFuel fuel' false E' rev' rest
                | None =>
                    match item with
                    | RIsingle sa sh s0 segTail None =>
                        if sh || ((1 <=? sa) && (1 <=? s0)) then
                          if isEmpty segTail then
                            step1PhasesBigFuel fuel' true E (RIsingle sa sh s0 [] None :: revOut) rest
                          else
                            dumpBig E revOut sa sh s0 segTail rest
                        else None
                    | RIsingle aL h s0 segTail (Some aR) =>
                        if (1 <=? s0) && (aR / 2 <=? E) then
                          let q_as := aR / 2 in
                          let Er := E - q_as in
                          if h then
                            let a' := aL + aR + 2 in
                            let h' := negb (aR mod 2 =? 0) in
                            let s0' := if aR mod 2 =? 0 then s0 else s0 - 1 in
                            if isEmpty segTail then
                              step1PhasesBigFuel fuel' true Er (RIsingle a' h' s0' [] None :: revOut) rest
                            else
                              dumpBig Er revOut a' h' s0' segTail rest
                          else
                            let a' := aL + aR + 1 in
                            let h' := negb (aR mod 2 =? 0) in
                            let s0b := if aR mod 2 =? 0 then 1 else 0 in
                            let b_rem := s0 - 1 in
                            if b_rem <=? Er then
                              let E' := Er - b_rem in
                              let rev' := RIsingle a' h' (s0b + b_rem) [] None :: revOut in
                              if isEmpty segTail then step1PhasesBigFuel fuel' false E' rev' rest
                              else step1Unzip E' rev' segTail rest
                            else
                              Some (List.rev revOut ++
                                RIsingle a' h' (s0b + Er) (SPsingle (b_rem - Er - 1) :: segTail) None :: rest)
                        else if (s0 =? 0) && h && (aR mod 2 =? 0) && isEmpty segTail && (aR / 2 <=? E) then
                          match rest with
                          | RIsingle a2 h2 s02 segTail2 None :: rest2 =>
                              if h2 || (1 <=? s02) then
                                let Er := E - aR / 2 in
                                let a' := aL + aR + 2 + a2 in
                                if isEmpty segTail2 then
                                  step1PhasesBigFuel fuel' true Er (RIsingle a' h2 s02 [] None :: revOut) rest2
                                else
                                  dumpBig Er revOut a' h2 s02 segTail2 rest2
                              else None
                          | _ => None
                          end
                        else None
                    | RIraw T_2 a1 =>
                        match rest with
                        | RIraw T_0 n0 :: RIsingle a2 h s0 segTail (Some a3) :: rest2 =>
                            if n0 =? 1 then
                              if 2 * (E + 1) <=? a2 then
                                Some (List.rev revOut ++
                                  RIraw T_2 (a1 + 2 * (E + 1)) :: RIraw T_0 1 ::
                                  RIsingle (a2 - 2 * (E + 1)) h s0 segTail (Some a3) :: rest2)
                              else if (a2 mod 2 =? 1) && (a2 / 2 + 1 <=? E) then
                                let E_rem := E - a2 / 2 - 1 in
                                if a3 mod 2 =? 1 then
                                  let q3 := a3 / 2 in
                                  let need := q3 + (if h then 1 else 2) in
                                  if (1 <=? q3) && (need <=? s0) then
                                    dumpBig E_rem revOut (a1 + a2 + a3 + 3) false q3
                                      (SPsingle (s0 - need) :: segTail) rest2
                                  else None
                                else if 2 <=? a3 then
                                  let q3 := (a3 - 2) / 2 in
                                  let need := q3 + (if h then 2 else 3) in
                                  if need <=? s0 then
                                    dumpBig E_rem revOut (a1 + a2 + a3 + 3) true q3
                                      (SPsingle (s0 - need) :: segTail) rest2
                                  else None
                                else None
                              else None
                            else None
                        | RIraw T_0 n0 :: RIraw T_2 a2 :: RIraw T_0 n0b :: rest3 =>
                            if (n0 =? 1) && (n0b =? 1) && (2 * (E + 1) <=? a2) then
                              Some (List.rev revOut ++
                                RIraw T_2 (a1 + 2 * (E + 1)) :: RIraw T_0 1 ::
                                RIraw T_2 (a2 - 2 * (E + 1)) :: RIraw T_0 1 :: rest3)
                            else None
                        | _ => None
                        end
                    | _ => None
                    end
                end
            end
        end
  end.

Definition step1Phase1Big (E : N) (revOut tail : list RleItem) : option (list RleItem) :=
  step1PhasesBigFuel (S (List.length tail)) false E revOut tail.

Definition step1Phase2Big (E : N) (revOut tail : list RleItem) : option (list RleItem) :=
  step1PhasesBigFuel (S (List.length tail)) true E revOut tail.

Definition step1DumpSegsBig (E : N) (revOut : list RleItem) (sa : N) (sh : bool) (s0 : N)
    (segTail : list SegPiece) (rest : list RleItem) : option (list RleItem) :=
  step1DumpSegsBigAux step1Phase1Big E revOut sa sh s0 segTail rest.

Definition isMergeC0 (h0 : bool) (b0 a1 : N) : bool :=
  (h0 && (b0 =? 0)) || (negb h0 && (b0 =? 1) && (1 <=? a1)).

Definition step1HubPrefixBig (pref : list RleItem) : option (bool * N * list RleItem) :=
  match step1HubPrefix pref with
  | Some r => Some r
  | None =>
      match pref with
      | RIsingle a0 false b0 [] None :: rest =>
          if b0 =? 2 then
            if (3 <=? a0) && (a0 mod 2 =? 1) then
              step1PrefP1 (a0 / 2) [RIsingle (a0 + 3) true 0 [] None] rest
            else None
          else
            match rest with
            | RIsingle a1 h1 b1 [] None :: rest2 =>
                if isMergeC0 false b0 a1 && (a1 + 1 <=? a0) && (1 <=? b1) then
                  let d := a0 - a1 - 1 in
                  let Ev := d / 2 in
                  if negb h1 then
                    if b1 - 1 <=? Ev then
                      let item := if d mod 2 =? 0 then RIsingle (a0 + a1 + 3) true (b1 - 1) [] None
                                  else RIsingle (a0 + a1 + 3) false b1 [] None in
                      step1PrefP1 (Ev - (b1 - 1)) [item] rest2
                    else None
                  else
                    let item := if d mod 2 =? 0 then RIsingle (a0 + a1 + 4) true (b1 - 1) [] None
                                else RIsingle (a0 + a1 + 4) false b1 [] None in
                    step1PrefP2 Ev [item] rest2
                else None
            | _ => None
            end
      | RIsingle a0 true b0 [] None :: rest =>
          if b0 =? 1 then
            if (2 <=? a0) && (a0 mod 2 =? 0) then
              step1PrefP1 (a0 / 2 - 1) [RIsingle (a0 + 3) false 1 [] None] rest
            else None
          else
            match rest with
            | RIsingle a1 h1 b1 [] None :: rest2 =>
                if isMergeC0 true b0 a1 && (a1 + 1 <=? a0) && (1 <=? b1) then
                  let d := a0 - a1 - 1 in
                  let Ev := d / 2 in
                  if negb h1 then
                    if b1 - 1 <=? Ev then
                      let item := if d mod 2 =? 0 then RIsingle (a0 + a1 + 3) true (b1 - 1) [] None
                                  else RIsingle (a0 + a1 + 3) false b1 [] None in
                      step1PrefP1 (Ev - (b1 - 1)) [item] rest2
                    else None
                  else
                    let item := if d mod 2 =? 0 then RIsingle (a0 + a1 + 4) true (b1 - 1) [] None
                                else RIsingle (a0 + a1 + 4) false b1 [] None in
                    step1PrefP2 Ev [item] rest2
                else None
            | _ => None
            end
      | _ => None
      end
  end.

Definition step1HubB0Z (xs : list RleItem) : option (list RleItem) :=
  match xs with
  | RIsingle a0 h0 b0 [] None :: RIsingle a1 h1 b1 segTail None :: rest =>
      if isMergeC0 h0 b0 a1 && (a1 + 1 <=? a0) && (1 <=? b1) then
        let d := a0 - a1 - 1 in
        let Ev := d / 2 in
        if negb h1 then
          if b1 - 1 <=? Ev then
            let item := if d mod 2 =? 0 then RIsingle (a0 + a1 + 3) true (b1 - 1) [] None
                        else RIsingle (a0 + a1 + 3) false b1 [] None in
            if isEmpty segTail then
              step1Phase1Big (Ev - (b1 - 1)) [item] rest
            else
              step1Unzip (Ev - (b1 - 1)) [item] segTail rest
          else
            let rem := b1 - 1 - Ev - 1 in
            let item := if d mod 2 =? 0 then RIsingle (a0 + a1 + 3) true Ev (SPsingle rem :: segTail) None
                        else RIsingle (a0 + a1 + 3) false (Ev + 1) (SPsingle rem :: segTail) None in
            Some (item :: rest)
        else
          if isEmpty segTail then
            let item := if d mod 2 =? 0 then RIsingle (a0 + a1 + 4) true (b1 - 1) [] None
                        else RIsingle (a0 + a1 + 4) false b1 [] None in
            step1Phase2Big Ev [item] rest
          else
            let h' := d mod 2 =? 0 in
            let s0' := if h' then b1 - 1 else b1 in
            step1DumpSegsBig Ev [] (a0 + a1 + 4) h' s0' segTail rest
      else None
  | _ => None
  end.

Definition step1HubDump (p : nat) (xs : list RleItem) : option (list RleItem) :=
  match splitAtList p xs with
  | None => None
  | Some (pref, tail) =>
      match step1HubPrefixBig pref with
      | Some (true, Ev, revOut) => step1Phase2Big Ev revOut tail
      | Some (false, Ev, revOut) => step1Phase1Big Ev revOut tail
      | None => None
      end
  end.

Definition pop01Runs (rs : list (Tok * N)) : option (list (Tok * N)) :=
  match rs with
  | (T_0, n0) :: (T_1, m) :: rest =>
      if (n0 =? 1) && (1 <=? m) then Some (decRun T_1 (m - 1) rest) else None
  | (T_3, m) :: rest =>
      if 1 <=? m then Some (pushRun T_1 1 (decRun T_3 (m - 1) rest)) else None
  | (T_4, m) :: rest =>
      if 1 <=? m then Some (pushRun T_3 1 (decRun T_4 (m - 1) rest)) else None
  | (T_5, m) :: rest =>
      if 1 <=? m then Some (pushRun T_2 1 (decRun T_5 (m - 1) rest)) else None
  | _ => None
  end.

Definition isFooterOnly (rs : list (Tok * N)) : bool :=
  match stripFooterRuns rs with
  | Some [] => true
  | _ => false
  end.

Definition isRawDoneBig (c : RawCfg) : bool :=
  match rc_q c, rc_L c, rc_lBase c, rc_R c, rc_rBase c with
  | E, [], LBblank, (T_2, n2) :: (T_0, n0) :: (T_1, n1) :: _, _ =>
      (n2 =? 1) && (n0 =? 1) && (n1 =? 1)
  | F, [(T_1, n1)], LBpipe Ep _, Rv, rb =>
      if n1 =? 2 then
        if Ep =? 0 then isSome (pop01Runs Rv) || (isEmpty Rv && isRBtail rb)
        else
          (isEmpty Rv && isRBtail rb) ||
          (isRBblank rb && isFooterOnly Rv)
      else false
  | A, [(T_1, n1); (T_2, n2)], LBpipe _ _, [], RBtail =>
      (n1 =? 1) && (n2 =? 1)
  | _, _, _, _, _ => false
  end.

Definition stepPipeRawBig (prefixLen winLen fuel : nat) (xs : list RleItem) : option (list RleItem) :=
  match splitAtList prefixLen xs with
  | None => None
  | Some (pref, afterPref) =>
      match splitAtList winLen afterPref with
      | None => None
      | Some (win, tail) =>
          match itemsToRuns win with
          | None => None
          | Some winRuns =>
              let rBase := if isEmpty tail then RBblank else RBtail in
              let R_body := if isEmpty tail then winRuns ++ footerRuns else winRuns in
              let initRaw :=
                if Nat.eqb prefixLen O then
                  stepRaw (mkRawCfg E [] LBblank ((T_2, 1) :: (T_0, 1) :: (T_1, 1) :: R_body) rBase)
                else
                  match step1HubPrefixBig pref with
                  | None => None
                  | Some (false, Ep, revPref) =>
                      Some (mkRawCfg F [(T_1, 2)] (LBpipe Ep revPref) R_body rBase)
                  | Some (true, Ep, revPref) =>
                      Some (mkRawCfg A [(T_1, 1); (T_2, 1)] (LBpipe Ep revPref) R_body rBase)
                  end in
              match initRaw with
              | None => None
              | Some rc0 =>
                  match runRawUntil isRawDoneBig fuel rc0 with
                  | None => None
                  | Some rc1 =>
                      match rc_q rc1 with
                      | A =>
                          match rc_L rc1, rc_lBase rc1, rc_R rc1, rc_rBase rc1 with
                          | [(T_1, n1); (T_2, n2)], LBpipe Ep revOut, [], RBtail =>
                              if (n1 =? 1) && (n2 =? 1) then step1Phase2Big Ep revOut tail else None
                          | _, _, _, _ => None
                          end
                      | E =>
                          match rc_L rc1, rc_lBase rc1, rc_R rc1, rc_rBase rc1 with
                          | [], LBblank, (T_2, n2) :: (T_0, n0) :: (T_1, n1) :: R_out, RBblank =>
                              if (n2 =? 1) && (n0 =? 1) && (n1 =? 1) then
                                option_map runsToItems (stripFooterRuns R_out)
                              else None
                          | [], LBblank, (T_2, n2) :: (T_0, n0) :: (T_1, n1) :: R_out, RBtail =>
                              if (n2 =? 1) && (n0 =? 1) && (n1 =? 1) then
                                Some (runsToItems R_out ++ tail)
                              else None
                          | _, _, _, _ => None
                          end
                      | F =>
                          match rc_L rc1, rc_lBase rc1, rc_R rc1, rc_rBase rc1 with
                          | [(T_1, n1)], LBpipe Ep revOut, R_in, rb =>
                              if n1 =? 2 then
                                if isEmpty R_in && isRBtail rb then
                                  step1Phase1Big Ep revOut tail
                                else if Ep =? 0 then
                                  match rb with
                                  | RBblank =>
                                      match pop01Runs R_in with
                                      | Some R_out =>
                                          option_map (fun body => List.rev revOut ++ runsToItems body)
                                            (stripFooterRuns R_out)
                                      | None => None
                                      end
                                  | RBtail =>
                                      match pop01Runs R_in with
                                      | Some R_out => Some (List.rev revOut ++ runsToItems R_out ++ tail)
                                      | None => None
                                      end
                                  end
                                else
                                  match rb with
                                  | RBblank =>
                                      if isFooterOnly R_in then
                                        Some (List.rev revOut ++ [RIsingle 0 true (Ep - 1) [] None])
                                      else None
                                  | RBtail => None
                                  end
                              else None
                          | _, _, _, _ => None
                          end
                      | _ => None
                      end
                  end
              end
          end
      end
  end.

Definition stepPipeRawToShort (prefixLen fuel : nat) (xs : list RleItem) : option (list RleItem) :=
  match splitAtList prefixLen xs with
  | None => None
  | Some (pref, win) =>
      match itemsToRuns win with
      | None => None
      | Some winRuns =>
          match step1HubPrefix pref with
          | None => None
          | Some (isP2, Ep, revPref) =>
              let rc0 :=
                if isP2 then mkRawCfg A [(T_1, 1); (T_2, 1)] (LBpipe Ep revPref) (winRuns ++ footerRuns) RBblank
                else mkRawCfg F [(T_1, 2)] (LBpipe Ep revPref) (winRuns ++ footerRuns) RBblank in
              match runRawUntil isRawDoneBig fuel rc0 with
              | None => None
              | Some rc1 =>
                  match rc_q rc1, rc_L rc1, rc_lBase rc1, rc_rBase rc1 with
                  | F, [(T_1, n1)], LBpipe Ep' revOut, RBblank =>
                      if (n1 =? 2) && (Ep' =? 0) then
                        match pop01Runs (rc_R rc1) with
                        | Some R_out =>
                            option_map (fun body => List.rev revOut ++ runsToItems body)
                              (stripShortFooterRuns R_out)
                        | None => None
                        end
                      else None
                  | _, _, _, _ => None
                  end
              end
          end
      end
  end.

Definition stepPipeRawFromShort (prefixLen fuel : nat) (xs : list RleItem) : option (list RleItem) :=
  match splitAtList prefixLen xs with
  | None => None
  | Some (pref, win) =>
      match itemsToRuns win with
      | None => None
      | Some winRuns =>
          match step1HubPrefix pref with
          | None => None
          | Some (isP2, Ep, revPref) =>
              let rc0 :=
                if isP2 then mkRawCfg A [(T_1, 1); (T_2, 1)] (LBpipe Ep revPref) (winRuns ++ shortFooterRuns) RBblank
                else mkRawCfg F [(T_1, 2)] (LBpipe Ep revPref) (winRuns ++ shortFooterRuns) RBblank in
              match runRawUntil isRawDoneBig fuel rc0 with
              | None => None
              | Some rc1 =>
                  match rc_q rc1, rc_L rc1, rc_lBase rc1, rc_rBase rc1 with
                  | F, [(T_1, n1)], LBpipe Ep' revOut, RBblank =>
                      if (n1 =? 2) && (Ep' =? 0) then
                        match pop01Runs (rc_R rc1) with
                        | Some R_out =>
                            option_map (fun body => List.rev revOut ++ runsToItems body)
                              (stripFooterRuns R_out)
                        | None => None
                        end
                      else None
                  | _, _, _, _ => None
                  end
              end
          end
      end
  end.

Definition consNormSeg (s : SegPiece) (ys : list SegPiece) : list SegPiece :=
  match s with
  | SPpair v1 v2 r1 =>
      if r1 =? 0 then ys
      else
        match ys with
        | SPpair u1 u2 r2 :: rest =>
            if (v1 =? u1) && (v2 =? u2) then SPpair v1 v2 (r1 + r2) :: rest
            else SPpair v1 v2 r1 :: ys
        | _ => SPpair v1 v2 r1 :: ys
        end
  | SPsingle v1 =>
      match ys with
      | SPsingle v2 :: SPpair u1 u2 r :: rest =>
          if (v1 =? u1) && (v2 =? u2) then SPpair v1 v2 (r + 1) :: rest
          else SPsingle v1 :: ys
      | SPsingle v2 :: SPsingle u1 :: SPsingle u2 :: rest =>
          if (v1 =? u1) && (v2 =? u2) then SPpair v1 v2 2 :: rest
          else SPsingle v1 :: ys
      | _ => SPsingle v1 :: ys
      end
  end.

Fixpoint normSegs (segs : list SegPiece) : list SegPiece :=
  match segs with
  | [] => []
  | s :: ss => consNormSeg s (normSegs ss)
  end.

Definition consPackRaw (x : RleItem) (ys : list RleItem) : list RleItem :=
  match x with
  | RIraw t n =>
      if n =? 0 then ys
      else
        match t with
        | T_4 =>
            match ys with
            | RIsingle a2 false s2 segTail None :: rest =>
                if a2 =? 0 then RIsingle 0 false (n + s2) segTail None :: rest
                else RIsingle 0 false n [] None :: ys
            | RIraw T_4 s2 :: rest => RIsingle 0 false (n + s2) [] None :: rest
            | _ => RIsingle 0 false n [] None :: ys
            end
        | T_5 =>
            if n =? 1 then
              match ys with
              | RIsingle a2 false s0 segTail None :: rest =>
                  if a2 =? 0 then RIsingle 0 true s0 segTail None :: rest
                  else RIsingle 0 true 0 [] None :: ys
              | _ => RIsingle 0 true 0 [] None :: ys
              end
            else RIraw T_5 n :: ys
        | T_2 =>
            match ys with
            | RIsingle a2 h s0 segTail aR :: rest =>
                if a2 =? 0 then RIsingle n h s0 segTail aR :: rest
                else RIraw T_2 n :: ys
            | RIraw T_2 a2 :: rest => RIraw T_2 (n + a2) :: rest
            | _ => RIraw T_2 n :: ys
            end
        | T_0 =>
            if n =? 1 then
              match ys with
              | RIraw T_1 n1 :: restY =>
                  if n1 =? 1 then
                    match restY with
                    | RIsingle a h s0 segTail aR :: rest =>
                        if (a =? 1) && negb h && match aR with None => true | Some _ => false end then
                          RIsingle 0 true s0 segTail None :: rest
                        else if 2 <=? a then
                          RIsingle 0 true 0 [] None :: RIsingle (a - 1) h s0 segTail aR :: rest
                        else RIraw T_0 1 :: ys
                    | RIraw T_2 m :: rest =>
                        if m =? 1 then
                          match rest with
                          | RIraw T_3 n3 :: RIsingle a2 false s1 segRest None :: rest2 =>
                              if (n3 =? 1) && (a2 =? 0) then
                                RIsingle 0 true 0 (SPsingle s1 :: segRest) None :: rest2
                              else RIsingle 0 true 0 [] None :: rest
                          | _ => RIsingle 0 true 0 [] None :: rest
                          end
                        else if 2 <=? m then
                          RIsingle 0 true 0 [] None :: RIraw T_2 (m - 1) :: rest
                        else RIraw T_0 1 :: ys
                    | _ => RIraw T_0 1 :: ys
                    end
                  else RIraw T_0 1 :: ys
              | RIsingle aR h s0 segTail None :: rest =>
                  if 1 <=? aR then RIsingle 0 h s0 segTail (Some aR) :: rest
                  else RIraw T_0 1 :: ys
              | _ => RIraw T_0 1 :: ys
              end
            else RIraw T_0 n :: ys
        | _ =>
            match ys with
            | RIraw tk2 n2 :: rest => if tok_eqb t tk2 then RIraw t (n + n2) :: rest else RIraw t n :: ys
            | _ => RIraw t n :: ys
            end
        end
  | RItranspRun a b r =>
      if r =? 0 then ys else RItranspRun a b r :: ys
  | RIpairRun a1 h1 b1 a2 h2 b2 r =>
      if r =? 0 then ys else RIpairRun a1 h1 b1 a2 h2 b2 r :: ys
  | RIsingle a h s0 segTail aR =>
      match ys with
      | RIraw T_3 n3 :: rest =>
          if n3 =? 1 then
            match rest with
            | RIsingle a2 false s1 segRest None :: rest2 =>
                if a2 =? 0 then RIsingle a h s0 (normSegs (segTail ++ SPsingle s1 :: segRest)) aR :: rest2
                else RIsingle a h s0 (normSegs (segTail ++ [SPsingle 0])) aR :: rest
            | _ => RIsingle a h s0 (normSegs (segTail ++ [SPsingle 0])) aR :: rest
            end
          else RIsingle a h s0 (normSegs segTail) aR :: ys
      | RIraw T_4 m :: rest =>
          if isEmpty segTail then RIsingle a h (s0 + m) [] aR :: rest
          else RIsingle a h s0 (normSegs segTail) aR :: ys
      | _ => RIsingle a h s0 (normSegs segTail) aR :: ys
      end
  end.

Fixpoint packRawItems (xs : list RleItem) : list RleItem :=
  match xs with
  | [] => []
  | x :: xs' => consPackRaw x (packRawItems xs')
  end.

Definition consNormItem (x : RleItem) (ys : list RleItem) : list RleItem :=
  match x with
  | RItranspRun a b r1 =>
      if r1 =? 0 then ys
      else
        match ys with
        | RItranspRun a2 b2 r2 :: rest =>
            if (a =? a2) && (b =? b2) then RItranspRun a b (r1 + r2) :: rest
            else RItranspRun a b r1 :: ys
        | RIsingle a2 false b2 [] None :: rest =>
            if (a =? a2) && (b =? b2) then RItranspRun a b (r1 + 1) :: rest
            else RItranspRun a b r1 :: ys
        | _ => RItranspRun a b r1 :: ys
        end
  | RIpairRun a1 h1 b1 a2 h2 b2 r1 =>
      if r1 =? 0 then ys
      else
        match ys with
        | RIpairRun u1 j1 c1 u2 j2 c2 r2 :: rest =>
            if (a1 =? u1) && Bool.eqb h1 j1 && (b1 =? c1) &&
               (a2 =? u2) && Bool.eqb h2 j2 && (b2 =? c2) then
              RIpairRun a1 h1 b1 a2 h2 b2 (r1 + r2) :: rest
            else RIpairRun a1 h1 b1 a2 h2 b2 r1 :: ys
        | RIsingle u1 j1 c1 [] None :: RIsingle u2 j2 c2 [] None :: rest =>
            if (a1 =? u1) && Bool.eqb h1 j1 && (b1 =? c1) &&
               (a2 =? u2) && Bool.eqb h2 j2 && (b2 =? c2) then
              RIpairRun a1 h1 b1 a2 h2 b2 (r1 + 1) :: rest
            else RIpairRun a1 h1 b1 a2 h2 b2 r1 :: ys
        | _ => RIpairRun a1 h1 b1 a2 h2 b2 r1 :: ys
        end
  | RIsingle a h s0 segTail aR =>
      let seg' := normSegs segTail in
      match seg', aR with
      | [], None =>
          let tryPairMerge :=
            match ys with
            | RIsingle a2 h2 b2 [] None :: RIpairRun u1 j1 c1 u2 j2 c2 r :: rest =>
                if (a =? u1) && Bool.eqb h j1 && (s0 =? c1) &&
                   (a2 =? u2) && Bool.eqb h2 j2 && (b2 =? c2) then
                  RIpairRun a h s0 a2 h2 b2 (r + 1) :: rest
                else RIsingle a h s0 [] None :: ys
            | RIsingle a2 h2 b2 [] None :: RIsingle u1 j1 c1 [] None :: RIsingle u2 j2 c2 [] None :: rest =>
                if (a =? u1) && Bool.eqb h j1 && (s0 =? c1) &&
                   (a2 =? u2) && Bool.eqb h2 j2 && (b2 =? c2) &&
                   (negb (a =? a2) || negb (Bool.eqb h h2) || negb (s0 =? b2)) then
                  RIpairRun a h s0 a2 h2 b2 2 :: rest
                else RIsingle a h s0 [] None :: ys
            | _ => RIsingle a h s0 [] None :: ys
            end in
          if negb h then
            match ys with
            | RItranspRun a2 b2 r :: rest =>
                if (a =? a2) && (s0 =? b2) then RItranspRun a s0 (r + 1) :: rest
                else RIsingle a false s0 [] None :: ys
            | RIsingle a2 false b2 [] None :: rest =>
                if (a =? a2) && (s0 =? b2) && (2 <=? a) && (a mod 2 =? 0) && (1 <=? s0) then
                  RItranspRun a s0 2 :: rest
                else tryPairMerge
            | _ => tryPairMerge
            end
          else tryPairMerge
      | _, _ => RIsingle a h s0 seg' aR :: ys
      end
  | RIraw t n =>
      if n =? 0 then ys
      else
        match ys with
        | RIraw tk2 n2 :: rest =>
            if tok_eqb t tk2 then RIraw t (n + n2) :: rest else RIraw t n :: ys
        | _ => RIraw t n :: ys
        end
  end.

Fixpoint normItems (xs : list RleItem) : list RleItem :=
  match xs with
  | [] => []
  | x :: xs' => consNormItem x (normItems xs')
  end.

Definition autoPackNorm (xs : list RleItem) : list RleItem :=
  normItems (packRawItems xs).

Definition stepPipeRawBridge (p1 f1 p2 f2 : nat) (xs : list RleItem) : option (list RleItem) :=
  match stepPipeRawToShort p1 f1 xs with
  | None => None
  | Some mid => option_map autoPackNorm (stepPipeRawFromShort p2 f2 (autoPackNorm mid))
  end.

(* ========================================================================= *)
(* Certificate Evaluator (CertOp, stepCert1, runCert, checkCert, checkInit)  *)
(* ========================================================================= *)

Inductive CertOp : Type :=
  | COh1 (n : nat)
  | COhbz
  | COhd (p : nat)
  | COd0 (k : nat) (Nv : N)
  | COrel (k : nat) (mult : N)
  | COeat (k : nat) (Mv : N)
  | COsl (k0 k1 : nat) (Mv : N)
  | COwv (k0 k1 : nat) (Wv : N) (hasTR : bool)
  | COm37 (k0 : nat) (Mv : N)
  | COm162 (k0 : nat) (Mv : N)
  | COraw (p w f : nat)
  | COraw2 (p1 f1 p2 f2 : nat)
  | COnorm (op : NormOp)
  | COauto.

Fixpoint runH1 (n : nat) (xs : list RleItem) : option (list RleItem) :=
  match n with
  | O => Some xs
  | S n' =>
      match step1Hub xs with
      | None => None
      | Some xs' => runH1 n' xs'
      end
  end.

Definition stepCert1 (op : CertOp) (xs : list RleItem) : option (list RleItem) :=
  match op with
  | COh1 n => runH1 n xs
  | COhbz => step1HubB0Z xs
  | COhd p => step1HubDump p xs
  | COd0 k Nv => stepOdoD0 k Nv xs
  | COrel k mult => stepOdoRelay k mult xs
  | COeat k Mv => stepEater k Mv xs
  | COsl k0 k1 Mv => stepSlicer12 k0 k1 Mv xs
  | COwv k0 k1 Wv hasTR => stepWave402 k0 k1 Wv hasTR xs
  | COm37 k0 Mv => stepMirror3752 k0 Mv xs
  | COm162 k0 Mv => stepMirror162 k0 Mv xs
  | COraw p w f => option_map autoPackNorm (stepPipeRawBig p w f xs)
  | COraw2 p1 f1 p2 f2 => stepPipeRawBridge p1 f1 p2 f2 xs
  | COnorm nop => applyNorm nop xs
  | COauto => Some (autoPackNorm xs)
  end.

Fixpoint runCert (ops : list CertOp) (xs : list RleItem) : option (list RleItem) :=
  match ops with
  | [] => Some xs
  | op :: ops' =>
      match stepCert1 op xs with
      | None => None
      | Some xs' => runCert ops' xs'
      end
  end.

Definition checkCert (ops : list CertOp) (src tgt : list RleItem) : bool :=
  option_eqb (list_eqb rleItem_eqb) (runCert ops src) (Some tgt).

Definition checkInit (fuel : nat) (tgt : list RleItem) : bool :=
  option_eqb (list_eqb rleItem_eqb) (option_map autoPackNorm (runRawFromInit fuel)) (Some tgt).

(* --- ScratchAtom.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.


Local Close Scope sym_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

Notation b0 := (const S0).

Definition T0 : list Sym := [S0].
Definition T1 : list Sym := [S1].
Definition T2 : list Sym := [S0; S0; S1].
Definition T3 : list Sym := [S0; S1; S1].
Definition T4 : list Sym := [S0; S1; S0; S1; S1].
Definition T5 : list Sym := [S0; S1; S0; S0; S1].
Definition T6 : list Sym := [S0; S0; S1; S0; S1].

Lemma step_C_t2_one (l r : Stream Sym) :
  (l {{C}}> (T2 *> r)) -[ tm ]->* ((T2 *> l) {{C}}> r).
Proof. execute. Qed.

Lemma step_C_1_t2_one (l r : Stream Sym) :
  (l {{C}}> (T1 *> T2 *> r)) -[ tm ]->* ((T3 *> l) {{C}}> (T1 *> r)).
Proof. execute. Qed.

Lemma step_C_1_t4_one (l r : Stream Sym) :
  (l {{C}}> (T1 *> T4 *> r)) -[ tm ]->* ((T6 *> l) {{C}}> (T1 *> r)).
Proof. execute. Qed.

Lemma step_E_t3_one (l r : Stream Sym) :
  ((T3 *> T0 *> l) {{E}}> (T0 *> r)) -[ tm ]->* ((T0 *> l) {{E}}> (T0 *> T2 *> r)).
Proof. execute. Qed.

Lemma step_E_t4_one (l r : Stream Sym) :
  ((T4 *> T0 *> l) {{E}}> (T0 *> T2 *> r)) -[ tm ]->* ((T0 *> l) {{E}}> (T0 *> T2 *> T5 *> r)).
Proof. execute. Qed.

Lemma step_E_t5_one (l r : Stream Sym) :
  ((T5 *> T0 *> l) {{E}}> (T0 *> T2 *> r)) -[ tm ]->* ((T0 *> l) {{E}}> (T0 *> T2 *> T4 *> r)).
Proof. execute. Qed.

Lemma step_E_t2_bounce (l r : Stream Sym) :
  ((T2 *> l) {{E}}> (T0 *> r)) -[ tm ]->* ((T3 *> l) {{C}}> (T1 *> r)).
Proof. execute. Qed.

Lemma step_C_1_t5_bounce (l r : Stream Sym) :
  ((T0 *> l) {{C}}> (T1 *> T5 *> r)) -[ tm ]->* ((T0 *> l) {{E}}> (T0 *> T4 *> r)).
