(* Section 7.3: Parametric Sweeps *)

(* --- ScratchS1.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

Lemma evstep_halts : forall c c',
  c -[ tm ]->* c' -> halted tm c' -> halts tm c.
Proof.
  intros c c' Hstep Hhalt.
  induction Hstep as [|x y z Hxy _ IH]; eauto.
Qed.

Lemma c0_eq : (b0 {{A}}> b0) = c0.
Proof. reflexivity. Qed.

(* ========================================================================= *)
(* Section 1: Token Alphabet & Exact Bit-Algebra Identities                  *)
(* ========================================================================= *)

Lemma zPz (w : list Sym) : w ^^ 0 = [].
Proof. reflexivity. Qed.

Lemma zLan (b : Stream Sym) : ([] : list Sym) *> b = b.
Proof. reflexivity. Qed.

Lemma zPsr (w : list Sym) (k : nat) (b : Stream Sym) :
  (w ^^ S k) *> b = w *> (w ^^ k) *> b.
Proof. apply Str_app_assoc. Qed.

Lemma zPal (w : list Sym) (k : nat) (b : Stream Sym) :
  (w ^^ k) *> w *> b = (w ^^ S k) *> b.
Proof.
  rewrite lpow_shift', <- Str_app_assoc. reflexivity.
Qed.

Lemma zP1 (w : list Sym) (b : Stream Sym) :
  (w ^^ 1) *> b = w *> b.
Proof.
  rewrite zPsr, zPz, zLan. reflexivity.
Qed.

Lemma pow_add_blank (w : list Sym) (m n : nat) (b : Stream Sym) :
  (w ^^ (m + n)) *> b = (w ^^ m) *> (w ^^ n) *> b.
Proof.
  rewrite lpow_add, Str_app_assoc. reflexivity.
Qed.

Lemma list_pow_zero (w : list Sym) : w ^^ 0 = [].
Proof. reflexivity. Qed.

Lemma list_pow_succ (w : list Sym) (n : nat) : w ^^ (n + 1) = w ++ w ^^ n.
Proof. replace (n + 1) with (S n) by lia. reflexivity. Qed.

Lemma list_pow_one (w : list Sym) : w ^^ 1 = w.
Proof. simpl. apply app_nil_r. Qed.

Lemma list_pow_add (w : list Sym) (m n : nat) : w ^^ (m + n) = w ^^ m ++ w ^^ n.
Proof. apply lpow_add. Qed.

Lemma list_pow_succ_right (w : list Sym) (n : nat) : w ^^ (n + 1) = w ^^ n ++ w.
Proof.
  replace (n + 1) with (S n) by lia.
  simpl. symmetry. apply lpow_shift.
Qed.

Lemma append_assoc {A : Type} (xs ys zs : list A) :
  (xs ++ ys) ++ zs = xs ++ (ys ++ zs).
Proof. symmetry. apply app_assoc. Qed.

Lemma t6_t3_eq : T6 ++ T3 = T2 ++ T4.
Proof. reflexivity. Qed.

Lemma t6_t2_eq : T6 ++ T2 = T2 ++ T5.
Proof. reflexivity. Qed.

Lemma t01_t6_pow (k : nat) : [S0; S1] ++ (T6 ^^ k) = (T5 ^^ k) ++ [S0; S1].
Proof.
  induction k as [|k IH].
  - reflexivity.
  - change ([S0; S1] ++ (T6 ++ T6 ^^ k) = (T5 ++ T5 ^^ k) ++ [S0; S1]).
    rewrite <- append_assoc, (append_assoc T5).
    change ([S0; S1] ++ T6) with (T5 ++ [S0; S1]).
    rewrite append_assoc, IH. reflexivity.
Qed.

Lemma t2_t5_pow (k : nat) : T2 ++ (T5 ^^ k) = (T6 ^^ k) ++ T2.
Proof.
  induction k as [|k IH].
  - reflexivity.
  - change (T2 ++ (T5 ++ T5 ^^ k) = (T6 ++ T6 ^^ k) ++ T2).
    rewrite <- append_assoc, <- t6_t2_eq, append_assoc, IH, append_assoc. reflexivity.
Qed.

Lemma t3_pow_t2_headZero (k : nat) (l : Stream Sym) :
  exists l', (T3 ^^ k) *> T2 *> l = T0 *> l'.
Proof.
  destruct k as [|k'].
  - exists ([S0; S1] *> l). reflexivity.
  - exists ([S1; S1] *> (T3 ^^ k') *> T2 *> l). rewrite zPsr. reflexivity.
Qed.

(* ========================================================================= *)
(* Section 2: Atomic 1-Token Rules & Parametric k-Sweeps                     *)
(* ========================================================================= *)

Lemma rule_C_t2 (k : nat) (l r : Stream Sym) :
  (l {{C}}> ((T2 ^^ k) *> r)) -[ tm ]->* (((T2 ^^ k) *> l) {{C}}> r).
Proof.
  revert l. induction k as [|k IH]; intros l.
  - apply evstep_refl.
  - rewrite zPsr.
    eapply evstep_trans; [apply step_C_t2_one |].
    eapply evstep_trans; [apply (IH (T2 *> l)) |].
    rewrite zPal. apply evstep_refl.
Qed.

Lemma rule_C_1_t2 (k : nat) (l r : Stream Sym) :
  (l {{C}}> (T1 *> (T2 ^^ k) *> r)) -[ tm ]->* (((T3 ^^ k) *> l) {{C}}> (T1 *> r)).
Proof.
  revert l. induction k as [|k IH]; intros l.
  - apply evstep_refl.
  - rewrite zPsr.
    eapply evstep_trans; [apply step_C_1_t2_one |].
    eapply evstep_trans; [apply (IH (T3 *> l)) |].
    rewrite zPal. apply evstep_refl.
Qed.

Lemma rule_C_1_t4 (k : nat) (l r : Stream Sym) :
  (l {{C}}> (T1 *> (T4 ^^ k) *> r)) -[ tm ]->* (((T6 ^^ k) *> l) {{C}}> (T1 *> r)).
Proof.
  revert l. induction k as [|k IH]; intros l.
  - apply evstep_refl.
  - rewrite zPsr.
    eapply evstep_trans; [apply step_C_1_t4_one |].
    eapply evstep_trans; [apply (IH (T6 *> l)) |].
    rewrite zPal. apply evstep_refl.
Qed.

Lemma rule_E_t3 (k : nat) (l r : Stream Sym) :
  (((T3 ^^ k) *> T0 *> l) {{E}}> (T0 *> r)) -[ tm ]->* ((T0 *> l) {{E}}> (T0 *> (T2 ^^ k) *> r)).
Proof.
  revert l r. induction k as [|k IH]; intros l r.
  - apply evstep_refl.
  - rewrite zPsr. destruct k as [|k'].
    + simpl lpow. rewrite !zLan. apply step_E_t3_one.
    + assert (Hhead : (T3 ^^ S k') *> T0 *> l = T0 *> [S1; S1] *> (T3 ^^ k') *> T0 *> l).
      { rewrite zPsr. reflexivity. }
      eapply evstep_trans.
      * rewrite Hhead. apply step_E_t3_one.
      * eapply evstep_trans; [apply (IH l (T2 *> r)) |].
        rewrite zPal. apply evstep_refl.
Qed.

Lemma rule_E_t5 (k : nat) (l r : Stream Sym) :
  (((T5 ^^ k) *> T0 *> l) {{E}}> (T0 *> T2 *> r)) -[ tm ]->*
  ((T0 *> l) {{E}}> (T0 *> T2 *> (T4 ^^ k) *> r)).
Proof.
  revert l r. induction k as [|k IH]; intros l r.
  - apply evstep_refl.
  - rewrite zPsr. destruct k as [|k'].
    + simpl lpow. rewrite !zLan. apply step_E_t5_one.
    + assert (Hhead : (T5 ^^ S k') *> T0 *> l = T0 *> [S1; S0; S0; S1] *> (T5 ^^ k') *> T0 *> l).
      { rewrite zPsr. reflexivity. }
      eapply evstep_trans.
      * rewrite Hhead. apply step_E_t5_one.
      * eapply evstep_trans; [apply (IH l (T4 *> r)) |].
        rewrite zPal. apply evstep_refl.
Qed.

Lemma bounce_t5 (k : nat) (l r : Stream Sym) :
  ((T2 *> T0 *> l) {{E}}> (T0 *> (T2 ^^ k) *> T5 *> r)) -[ tm ]->*
  ((T0 *> l) {{E}}> (T0 *> (T2 ^^ (k + 1)) *> T4 *> r)).
Proof.
  replace (k + 1) with (S k) by lia.
  eapply evstep_trans; [apply step_E_t2_bounce |].
  eapply evstep_trans; [apply rule_C_1_t2 |].
  rewrite zPal.
  assert (Hhead : (T3 ^^ S k) *> T0 *> l = T0 *> [S1; S1] *> (T3 ^^ k) *> T0 *> l).
  { rewrite zPsr. reflexivity. }
  eapply evstep_trans.
  - rewrite Hhead. apply step_C_1_t5_bounce.
  - rewrite <- Hhead. apply rule_E_t3.
Qed.

Definition RoundTrip (P_in P_out : list Sym) (tail : Stream Sym) : Prop :=
  forall (k : nat) (l : Stream Sym),
    (((T3 ^^ k) *> T2 *> T0 *> l) {{C}}> (T1 *> P_in *> tail)) -[ tm ]->*
    ((T0 *> l) {{E}}> (T0 *> (T2 ^^ (k + 1)) *> P_out *> tail)).

Lemma rt_cons_t4_one {P_in P_out : list Sym} {tail : Stream Sym}
    (h : RoundTrip P_in P_out tail) :
    RoundTrip (T4 ++ P_in) (T4 ++ P_out) tail.
Proof.
  intros k l.
  rewrite Str_app_assoc.
  eapply evstep_trans; [apply step_C_1_t4_one |].
  destruct k as [|k'].
  - rewrite zPz, zLan.
    assert (H62 : T6 *> T2 *> T0 *> l = T2 *> T5 *> T0 *> l).
    { rewrite <- Str_app_assoc, t6_t2_eq, Str_app_assoc. reflexivity. }
    rewrite H62.
    assert (H5head : T5 *> T0 *> l = T0 *> [S1; S0; S0; S1] *> T0 *> l) by reflexivity.
    eapply evstep_trans.
    + rewrite H5head.
      pose proof (h 0 ([S1; S0; S0; S1] *> T0 *> l)) as H0.
      rewrite zPz, zLan in H0.
      change (0 + 1) with 1 in H0. rewrite zP1 in H0. exact H0.
    + rewrite <- H5head, Str_app_assoc. change (0 + 1) with 1. rewrite zP1.
      apply step_E_t5_one.
  - rewrite zPsr.
    assert (H63 : T6 *> T3 *> (T3 ^^ k') *> T2 *> T0 *> l = T2 *> T4 *> (T3 ^^ k') *> T2 *> T0 *> l).
    { rewrite <- Str_app_assoc, t6_t3_eq, Str_app_assoc. reflexivity. }
    rewrite H63.
    assert (H4head : T4 *> (T3 ^^ k') *> T2 *> T0 *> l =
      T0 *> [S1; S0; S1; S1] *> (T3 ^^ k') *> T2 *> T0 *> l) by reflexivity.
    eapply evstep_trans.
    + rewrite H4head.
      pose proof (h 0 ([S1; S0; S1; S1] *> (T3 ^^ k') *> T2 *> T0 *> l)) as H0.
      rewrite zPz, zLan in H0.
      change (0 + 1) with 1 in H0. rewrite zP1 in H0. exact H0.
    + rewrite <- H4head.
      destruct (t3_pow_t2_headZero k' (T0 *> l)) as [l' Hl'].
      eapply evstep_trans.
      * rewrite Hl'. apply step_E_t4_one.
      * rewrite <- Hl'. eapply evstep_trans.
        -- apply (rule_E_t3 k' ([S0; S1] *> T0 *> l) (T2 *> T5 *> P_out *> tail)).
        -- rewrite zPal. rewrite Str_app_assoc.
           replace (S k' + 1) with (S k' + 1) by reflexivity.
           pose proof (bounce_t5 (S k') l (P_out *> tail)) as Hb.
           exact Hb.
Qed.

Lemma rt_cons_t4 (n : nat) {P_in P_out : list Sym} {tail : Stream Sym}
    (h : RoundTrip P_in P_out tail) :
    RoundTrip ((T4 ^^ n) ++ P_in) ((T4 ^^ n) ++ P_out) tail.
Proof.
  induction n as [|n IH].
  - exact h.
  - change (T4 ^^ S n) with (T4 ++ T4 ^^ n). rewrite !append_assoc. apply rt_cons_t4_one. exact IH.
Qed.

Lemma rule_E_01_t4_t5 (k : nat) (l r : Stream Sym) :
  ((([S0; S1] ++ T4) *> (T5 ^^ k) *> T0 *> l) {{E}}> ([S0; S1] *> r)) -[ tm ]->*
  ((([S0; S1] ++ T4) *> T0 *> l) {{E}}> ([S0; S1] *> (T4 ^^ k) *> r)).
Proof.
  revert l r. induction k as [|k IH]; intros l r.
  - apply evstep_refl.
  - rewrite zPsr. destruct k as [|k'].
    + simpl lpow. rewrite !zLan. apply step_E_01_t4_t5_one.
    + assert (Hhead : (T5 ^^ S k') *> T0 *> l = T0 *> [S1; S0; S0; S1] *> (T5 ^^ k') *> T0 *> l).
      { rewrite zPsr. reflexivity. }
      eapply evstep_trans.
      * rewrite Hhead. apply step_E_01_t4_t5_one.
      * eapply evstep_trans; [apply (IH l (T4 *> r)) |].
        rewrite zPal. apply evstep_refl.
Qed.

(* ========================================================================= *)
(* Section 6-7: RoundTripQ5, Universal Pull1, and Unwind/Mid-Cell Sweeps     *)
(* ========================================================================= *)

Lemma rule_E_t3_to_Q5 (k : nat) (l r : Stream Sym) :
  (((T3 ^^ (k + 1)) *> T0 *> l) {{E}}> (T0 *> r)) -[ tm ]->*
  (([S1; S1] *> T0 *> l) {{F}}> ([S0; S1] *> (T2 ^^ k) *> r)).
Proof.
  replace (k + 1) with (S k) by lia.
  rewrite <- zPal.
  eapply evstep_trans.
  - apply (rule_E_t3 k ([S1; S1] *> T0 *> l) r).
  - apply step_E_t3_to_Q5.
Qed.

Lemma step_8A_t3_sweep (m : nat) (l r : Stream Sym) :
  (([S1; S1] *> (T3 ^^ m) *> T2 *> T0 *> l) {{F}}> (T2 *> r)) -[ tm ]->*
  (([S1; S1] *> (T3 ^^ (m + 2)) *> T0 *> l) {{F}}> r).
Proof.
  destruct (t3_pow_t2_headZero m (T0 *> l)) as [l' Hl'].
  eapply evstep_trans.
  - rewrite Hl'. apply (step_8A_head l' ([S0; S1] *> r)).
  - rewrite <- Hl'. change ([S0; S0; S0] *> [S0; S1] *> r) with (T0 *> T0 *> T2 *> r).
    eapply evstep_trans; [apply (rule_E_t3 m ([S0; S1] *> T0 *> l) (T0 *> T2 *> r)) |].
    change (T0 *> [S0; S1] *> T0 *> l) with (T2 *> T0 *> l).
    eapply evstep_trans; [apply step_E_t2_bounce |].
    eapply evstep_trans; [apply rule_C_1_t2 |].
    rewrite zPal.
    change (T1 *> T0 *> T2 *> r) with ([S1; S0] *> T2 *> r).
    eapply evstep_trans; [apply step_8A_tail |].
    rewrite <- zPsr. replace (S (S m)) with (m + 2) by lia. apply evstep_refl.
Qed.

Definition RoundTripQ5 (P_in P_out : list Sym) (tail : Stream Sym) : Prop :=
  forall (k : nat) (l : Stream Sym),
    (((T3 ^^ k) *> T2 *> T0 *> l) {{C}}> (T1 *> P_in *> tail)) -[ tm ]->*
    (([S1; S1] *> T0 *> l) {{F}}> ([S0; S1] *> (T2 ^^ k) *> P_out *> tail)).

Lemma rt5_to_rt {P_in P_out : list Sym} {tail : Stream Sym}
    (h : RoundTripQ5 P_in P_out tail) : RoundTrip P_in P_out tail.
Proof.
  intros k l.
  eapply evstep_trans; [apply h |].
  change ([S0; S1] *> (T2 ^^ k) *> P_out *> tail) with (T0 *> [S1] *> (T2 ^^ k) *> P_out *> tail).
  eapply evstep_trans; [apply step_8A_head |].
  change ([S0; S0; S0] *> [S1] *> (T2 ^^ k) *> P_out *> tail) with
    (T0 *> T2 *> (T2 ^^ k) *> P_out *> tail).
  rewrite <- zPsr. replace (S k) with (k + 1) by lia. apply evstep_refl.
Qed.

Lemma bounce_t5_to_Q5 (k : nat) (l r : Stream Sym) :
  ((T2 *> T0 *> l) {{E}}> (T0 *> (T2 ^^ k) *> T5 *> r)) -[ tm ]->*
  (([S1; S1] *> T0 *> l) {{F}}> ([S0; S1] *> (T2 ^^ k) *> T4 *> r)).
Proof.
  eapply evstep_trans; [apply step_E_t2_bounce |].
  eapply evstep_trans; [apply rule_C_1_t2 |].
  rewrite zPal.
  assert (Hhead : (T3 ^^ S k) *> T0 *> l = T0 *> [S1; S1] *> (T3 ^^ k) *> T0 *> l).
  { rewrite zPsr. reflexivity. }
  eapply evstep_trans.
  - rewrite Hhead. apply step_C_1_t5_bounce.
  - rewrite <- Hhead. replace (S k) with (k + 1) by lia. apply rule_E_t3_to_Q5.
Qed.

Lemma rt5_wall3 (tail : Stream Sym) :
  RoundTripQ5 (T0 ++ T2 ++ T2) (T2 ++ T2 ++ T0) (T0 *> tail).
Proof.
  intros k l.
  rewrite !Str_app_assoc.
  destruct (t3_pow_t2_headZero k (T0 *> l)) as [l' Hhead].
  assert (H2head : T2 *> T0 *> tail = T0 *> [S0; S1] *> T0 *> tail) by reflexivity.
  eapply evstep_trans.
  - rewrite Hhead, H2head at 1.
    change (T2 *> T0 *> [S0; S1] *> T0 *> tail) with (T2 *> T2 *> T0 *> tail).
    rewrite H2head.
    apply (step_C_1_0_t2_zero l' ([S0; S1] *> T0 *> tail)).
  - rewrite <- Hhead. change (T0 *> [S0; S1] *> T0 *> tail) with (T2 *> T0 *> tail).
    eapply evstep_trans.
    + apply (rule_E_t3 k ([S0; S1] *> T0 *> l) (T2 *> T0 *> T2 *> T0 *> tail)).
    + rewrite zPal.
      change (T0 *> [S0; S1] *> T0 *> l) with (T2 *> T0 *> l).
      eapply evstep_trans; [apply step_E_t2_bounce |].
      eapply evstep_trans; [apply rule_C_1_t2 |].
      rewrite zPal.
      assert (Hhead2 : (T3 ^^ S (S k)) *> T0 *> l = T0 *> [S1; S1] *> (T3 ^^ S k) *> T0 *> l).
      { rewrite zPsr. reflexivity. }
      eapply evstep_trans.
      * rewrite Hhead2. apply step_C_1_0_t2_zero.
      * rewrite <- Hhead2. replace (S (S k)) with ((k + 1) + 1) by lia.
        eapply evstep_trans; [apply rule_E_t3_to_Q5 |].
        replace (k + 1) with (S k) by lia.
        rewrite <- zPal. apply evstep_refl.
Qed.

Lemma rt5_cons_t2 (n : nat) {P_in P_out : list Sym} {tail : Stream Sym}
    (h : RoundTripQ5 P_in P_out tail) :
    RoundTripQ5 ((T2 ^^ n) ++ P_in) ((T2 ^^ n) ++ P_out) tail.
Proof.
  intros k l.
  rewrite Str_app_assoc.
  eapply evstep_trans; [apply rule_C_1_t2 |].
  rewrite <- pow_add_blank.
  eapply evstep_trans; [apply (h (n + k) l) |].
  rewrite Str_app_assoc, <- pow_add_blank.
  replace (n + k) with (k + n) by lia. apply evstep_refl.
Qed.

Lemma rt5_cons_t4_one {P_in P_out : list Sym} {tail : Stream Sym}
    (h : RoundTrip P_in P_out tail) :
    RoundTripQ5 (T4 ++ P_in) (T4 ++ P_out) tail.
Proof.
  intros k l.
  rewrite Str_app_assoc.
  eapply evstep_trans; [apply step_C_1_t4_one |].
  destruct k as [|k'].
  - simpl lpow. rewrite !zLan.
    assert (H62 : T6 *> T2 *> T0 *> l = T2 *> T5 *> T0 *> l).
    { rewrite <- Str_app_assoc, t6_t2_eq, Str_app_assoc. reflexivity. }
    rewrite H62.
    assert (H5head : T5 *> T0 *> l = T0 *> [S1; S0; S0; S1] *> T0 *> l) by reflexivity.
    eapply evstep_trans.
    + rewrite H5head.
      pose proof (h 0 ([S1; S0; S0; S1] *> T0 *> l)) as H0.
      rewrite zPz, zLan in H0.
      change (0 + 1) with 1 in H0. rewrite zP1 in H0. exact H0.
    + rewrite <- H5head, Str_app_assoc. apply step_E_t5_to_Q5.
  - rewrite zPsr.
    assert (H63 : T6 *> T3 *> (T3 ^^ k') *> T2 *> T0 *> l = T2 *> T4 *> (T3 ^^ k') *> T2 *> T0 *> l).
    { rewrite <- Str_app_assoc, t6_t3_eq, Str_app_assoc. reflexivity. }
    rewrite H63.
    assert (H4head : T4 *> (T3 ^^ k') *> T2 *> T0 *> l =
      T0 *> [S1; S0; S1; S1] *> (T3 ^^ k') *> T2 *> T0 *> l) by reflexivity.
    eapply evstep_trans.
    + rewrite H4head.
      pose proof (h 0 ([S1; S0; S1; S1] *> (T3 ^^ k') *> T2 *> T0 *> l)) as H0.
      rewrite zPz, zLan in H0.
      change (0 + 1) with 1 in H0. rewrite zP1 in H0. exact H0.
    + rewrite <- H4head.
      destruct (t3_pow_t2_headZero k' (T0 *> l)) as [l' Hl'].
      eapply evstep_trans.
      * rewrite Hl'. apply step_E_t4_one.
      * rewrite <- Hl'. eapply evstep_trans.
        -- apply (rule_E_t3 k' ([S0; S1] *> T0 *> l) (T2 *> T5 *> P_out *> tail)).
        -- rewrite zPal, Str_app_assoc. apply bounce_t5_to_Q5.
Qed.

Lemma rt5_cons_t4 (n : nat) {P_in P_out : list Sym} {tail : Stream Sym}
    (h : RoundTripQ5 P_in P_out tail) :
    RoundTripQ5 ((T4 ^^ n) ++ P_in) ((T4 ^^ n) ++ P_out) tail.
Proof.
  destruct n as [|n'].
  - exact h.
  - change (T4 ^^ S n') with (T4 ++ T4 ^^ n'). rewrite !append_assoc.
    apply rt5_cons_t4_one. apply rt_cons_t4. apply rt5_to_rt. exact h.
Qed.

Lemma roundTripQ5_of_t5_wall {P_in P_out : list Sym} {tail : Stream Sym}
    (hw : forall l, ((T0 *> l) {{C}}> (T1 *> P_in *> tail)) -[ tm ]->*
                    ((T0 *> l) {{E}}> (T0 *> T5 *> P_out *> tail))) :
    RoundTripQ5 P_in (T4 ++ P_out) tail.
Proof.
  intros k l.
  destruct (t3_pow_t2_headZero k (T0 *> l)) as [l' Hhead].
  eapply evstep_trans.
  - rewrite Hhead. apply hw.
  - rewrite <- Hhead. eapply evstep_trans.
    + apply (rule_E_t3 k ([S0; S1] *> T0 *> l) (T5 *> P_out *> tail)).
    + rewrite Str_app_assoc. apply bounce_t5_to_Q5.
Qed.

Lemma rt5_wall1 (tail : Stream Sym) :
  RoundTripQ5 (T3 ++ T4) (T4 ++ T3) tail.
Proof.
  apply roundTripQ5_of_t5_wall. intros l.
  rewrite Str_app_assoc.
  change (T4 *> tail) with (T0 *> [S1; S0; S1; S1] *> tail).
  change (T5 *> T3 *> tail) with ([S0; S1; S0] *> T0 *> [S1; S0; S1; S1] *> tail).
  apply step_C_1_t3_zero.
Qed.

Lemma rt5_wall2 :
  RoundTripQ5 [S0; S1; S0; S1] (T4 ++ [S0; S1; S0; S1]) b0.
Proof.
  apply roundTripQ5_of_t5_wall. apply step_C_1_end.
Qed.

Lemma rt5_wall4a (tail : Stream Sym) :
  RoundTripQ5 (T3 ++ T3) (T4 ++ T1) tail.
Proof.
  apply roundTripQ5_of_t5_wall. intros l.
  rewrite Str_app_assoc.
  change (T3 *> tail) with (T0 *> [S1; S1] *> tail).
  change (T5 *> T1 *> tail) with ([S0; S1; S0] *> T0 *> [S1; S1] *> tail).
  apply step_C_1_t3_zero.
Qed.

Lemma rt5_wall4b (tail : Stream Sym) :
  RoundTripQ5 (T1 ++ T4) (T2 ++ [S0; S1; S0]) (T0 *> tail).
Proof.
  intros k l.
  rewrite Str_app_assoc.
  destruct (t3_pow_t2_headZero k (T0 *> l)) as [l' Hhead].
  eapply evstep_trans.
  - rewrite Hhead. apply step_C_1_1_t4.
  - rewrite <- Hhead. eapply evstep_trans.
    + apply (rule_E_t3 k ([S0; S1] *> T0 *> l) (T2 *> T3 *> T0 *> tail)).
    + rewrite zPal.
      change (T0 *> [S0; S1] *> T0 *> l) with (T2 *> T0 *> l).
      eapply evstep_trans; [apply step_E_t2_bounce |].
      eapply evstep_trans; [apply rule_C_1_t2 |].
      rewrite zPal.
      assert (Hhead2 : (T3 ^^ S (S k)) *> T0 *> l = T0 *> [S1; S1] *> (T3 ^^ S k) *> T0 *> l).
      { rewrite zPsr. reflexivity. }
      eapply evstep_trans.
      * rewrite Hhead2. apply step_C_1_t3_zero.
      * rewrite <- Hhead2. replace (S (S k)) with ((k + 1) + 1) by lia.
        eapply evstep_trans; [apply rule_E_t3_to_Q5 |].
        replace (k + 1) with (S k) by lia.
        rewrite <- zPal. apply evstep_refl.
Qed.

(* Section 7.2: Atomic Micro-Lemmas *)

Lemma head0_t5_t4 (b : nat) (l : Stream Sym) :
  exists l', (T5 ^^ b) *> T4 *> l = T0 *> l'.
Proof.
  destruct b as [|b'].
  - exists ([S1; S0; S1; S1] *> l). reflexivity.
  - exists ([S1; S0; S0; S1] *> (T5 ^^ b') *> T4 *> l). rewrite zPsr. reflexivity.
Qed.

Lemma head0_t3_t0 (k : nat) (l : Stream Sym) :
  exists l', (T3 ^^ k) *> T0 *> l = T0 *> l'.
Proof.
  destruct k as [|k'].
  - exists l. reflexivity.
  - exists ([S1; S1] *> (T3 ^^ k') *> T0 *> l). rewrite zPsr. reflexivity.
Qed.

Lemma head0_t5_t0 (k : nat) (l : Stream Sym) :
  exists l', (T5 ^^ k) *> T0 *> l = T0 *> l'.
Proof.
  destruct k as [|k'].
  - exists l. reflexivity.
  - exists ([S1; S0; S0; S1] *> (T5 ^^ k') *> T0 *> l). rewrite zPsr. reflexivity.
Qed.

Lemma head0_t2_t0 (k : nat) (l : Stream Sym) :
  exists l', (T2 ^^ k) *> T0 *> l = T0 *> l'.
Proof.
  destruct k as [|k'].
  - exists l. reflexivity.
  - exists ([S0; S1] *> (T2 ^^ k') *> T0 *> l). rewrite zPsr. reflexivity.
Qed.

Lemma rule_c0_t2 (k : nat) (l r : Stream Sym) :
  (l {{C}}> ((T2 ^^ k) *> r)) -[ tm ]->* (((T2 ^^ k) *> l) {{C}}> r).
Proof. apply rule_C_t2. Qed.

Lemma rule_q0_t2 (k : nat) (l r : Stream Sym) :
  (([S1] *> l) {{A}}> ((T2 ^^ k) *> r)) -[ tm ]->* (([S1] *> (T3 ^^ k) *> l) {{A}}> r).
Proof.
  revert l. induction k as [|n IH]; intros l.
  - apply evstep_refl.
  - rewrite zPsr.
    eapply evstep_trans; [apply step_q0_t2_one |].
    eapply evstep_trans; [apply (IH (T3 *> l)) |].
    rewrite zPal. apply evstep_refl.
Qed.

Lemma rule_q0_t4_next (k : nat) (l r : Stream Sym) :
  (([S1] *> T2 *> l) {{A}}> ((T4 ^^ k) *> r)) -[ tm ]->* (([S1] *> T2 *> (T5 ^^ k) *> l) {{A}}> r).
Proof.
  revert l. induction k as [|n IH]; intros l.
  - apply evstep_refl.
  - rewrite zPsr.
    eapply evstep_trans; [apply step_q0_t4_next |].
    eapply evstep_trans; [apply (IH (T5 *> l)) |].
    rewrite zPal. apply evstep_refl.
Qed.

Lemma rule_unwind_t5 (k : nat) (l r : Stream Sym) :
  (([S1; S1] *> (T5 ^^ k) *> T0 *> l) {{F}}> ([S0; S1] *> r)) -[ tm ]->*
  (([S1; S1] *> T0 *> l) {{F}}> ([S0; S1] *> (T4 ^^ k) *> r)).
Proof.
  revert r. induction k as [|n IH]; intros r.
  - apply evstep_refl.
  - rewrite zPsr. destruct (head0_t5_t0 n l) as [l' Hl'].
    eapply evstep_trans.
    + rewrite Hl'. apply step_unwind_t5_one.
    + rewrite <- Hl'. eapply evstep_trans; [apply (IH (T4 *> r)) |].
      rewrite zPal. apply evstep_refl.
Qed.

Lemma rule_q5_t3_unwind (k : nat) (l r : Stream Sym) :
  (([S1; S1] *> (T3 ^^ k) *> T0 *> l) {{F}}> ([S0; S1] *> r)) -[ tm ]->*
  (([S1; S1] *> T0 *> l) {{F}}> ([S0; S1] *> (T2 ^^ k) *> r)).
Proof.
  destruct k as [|k'].
  - apply evstep_refl.
  - eapply evstep_trans.
    + rewrite zPsr.
      change (T3 *> (T3 ^^ k') *> T0 *> l) with (T0 *> [S1; S1] *> (T3 ^^ k') *> T0 *> l).
      change ([S0; S1] *> r) with (T0 *> [S1] *> r).
      apply step_8A_head.
    + change ([S0; S0; S0] *> [S1] *> r) with (T0 *> T2 *> r).
      change (T0 *> [S1; S1] *> (T3 ^^ k') *> T0 *> l) with (T3 *> (T3 ^^ k') *> T0 *> l).
      rewrite <- zPsr. replace (S k') with (k' + 1) by lia.
      eapply evstep_trans; [apply rule_E_t3_to_Q5 |].
      rewrite zPal. replace (S k') with (k' + 1) by lia. apply evstep_refl.
Qed.

Lemma mid_cell_h0 (a b : nat) (l r : Stream Sym) :
  (([S1] *> T2 *> l) {{A}}> ((T2 ^^ (a + 1)) *> (T4 ^^ (b + 1)) *> r)) -[ tm ]->*
  (([S1] *> T2 *> (T5 ^^ b) *> T4 *> (T3 ^^ a) *> T2 *> l) {{A}}> r).
Proof.
  eapply evstep_trans; [apply rule_q0_t2 |].
  replace (a + 1) with (S a) by lia. replace (b + 1) with (S b) by lia.
  rewrite !zPsr.
  eapply evstep_trans; [apply step_q0_t4_first |].
  apply rule_q0_t4_next.
Qed.

Lemma mid_cell_h1 (a b : nat) (l r : Stream Sym) :
  (([S1] *> T2 *> T0 *> l) {{A}}> ((T2 ^^ a) *> T5 *> (T4 ^^ b) *> r)) -[ tm ]->*
  (([S1] *> T2 *> (T5 ^^ b) *> T4 *> (T3 ^^ a) *> T0 *> l) {{A}}> r).
Proof.
  eapply evstep_trans; [apply rule_q0_t2 |].
  assert (H5 : (([S1] *> (T3 ^^ a) *> T2 *> T0 *> l) {{A}}> (T5 *> (T4 ^^ b) *> r)) -[ tm ]->*
               (([S1] *> T2 *> T4 *> (T3 ^^ a) *> T0 *> l) {{A}}> ((T4 ^^ b) *> r))).
  { destruct a as [|a'].
    - simpl lpow. rewrite !zLan. apply step_q0_t5_on_t2.
    - rewrite zPsr.
      destruct (head0_t3_t0 a' ([S0; S1] *> T0 *> l)) as [l' Hl'].
      eapply evstep_trans.
      + change (T2 *> T0 *> l) with (T0 *> [S0; S1] *> T0 *> l).
        rewrite Hl'. apply step_q0_t5_on_t3.
      + rewrite <- Hl'. eapply evstep_trans; [apply (rule_E_t3 a' ([S0; S1] *> T0 *> l) (T2 *> T4 *> (T4 ^^ b) *> r)) |].
        change (T0 *> [S0; S1] *> T0 *> l) with (T2 *> T0 *> l).
        eapply evstep_trans; [apply step_E_t2_bounce |].
        rewrite zPal.
        eapply evstep_trans; [apply rule_C_1_t2 |].
        rewrite zPal.
        eapply evstep_trans; [apply step_C_1_to_q0 |].
        rewrite zPsr. apply step_q0_t4_first. }
  eapply evstep_trans; [exact H5 |].
  apply rule_q0_t4_next.
Qed.

(* Section 7.4: Left-Pass & Unwind Theorems *)

Lemma left_noT2_b0 (k : nat) (l r : Stream Sym) :
  (([S1; S1] *> T4 *> (T3 ^^ k) *> T0 *> l) {{F}}> (T0 *> r)) -[ tm ]->*
  (([S1; S1] *> T0 *> l) {{F}}> ([S0; S1] *> (T2 ^^ k) *> [S0; S1; S0; S0] *> r)).
Proof.
  destruct (head0_t3_t0 k l) as [l' Hl'].
  eapply evstep_trans.
  - rewrite Hl'. apply step_left_t4_one.
  - rewrite <- Hl'. apply rule_q5_t3_unwind.
Qed.

Lemma left_noT2_bsucc (b k : nat) (l r : Stream Sym) :
  (([S1; S1] *> (T5 ^^ (b + 1)) *> T4 *> (T3 ^^ k) *> T0 *> l) {{F}}> (T0 *> r)) -[ tm ]->*
  (([S1; S1] *> T0 *> l) {{F}}> ([S0; S1] *> (T2 ^^ k) *> T5 *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r)).
Proof.
  replace (b + 1) with (S b) by lia. rewrite zPsr.
  destruct (head0_t5_t4 b ((T3 ^^ k) *> T0 *> l)) as [l1 Hl1].
  eapply evstep_trans.
  - rewrite Hl1. apply step_left_t5_one.
  - rewrite <- Hl1. eapply evstep_trans.
    + change (T4 *> (T3 ^^ k) *> T0 *> l) with (T0 *> [S1; S0; S1; S1] *> (T3 ^^ k) *> T0 *> l).
      apply rule_unwind_t5.
    + change (T0 *> [S1; S0; S1; S1] *> (T3 ^^ k) *> T0 *> l) with (T4 *> (T3 ^^ k) *> T0 *> l).
      destruct (head0_t3_t0 k l) as [l2 Hl2].
      eapply evstep_trans.
      * rewrite Hl2. apply step_unwind_t4_one.
      * rewrite <- Hl2. apply rule_q5_t3_unwind.
Qed.

Lemma unwind_noT2 (b k : nat) (l r : Stream Sym) :
  (([S1; S1] *> (T5 ^^ b) *> T4 *> (T3 ^^ k) *> T0 *> l) {{F}}> ([S0; S1] *> r)) -[ tm ]->*
  (([S1; S1] *> T0 *> l) {{F}}> ([S0; S1] *> (T2 ^^ k) *> T5 *> (T4 ^^ b) *> r)).
Proof.
  eapply evstep_trans.
  - change (T4 *> (T3 ^^ k) *> T0 *> l) with (T0 *> [S1; S0; S1; S1] *> (T3 ^^ k) *> T0 *> l).
    apply rule_unwind_t5.
  - change (T0 *> [S1; S0; S1; S1] *> (T3 ^^ k) *> T0 *> l) with (T4 *> (T3 ^^ k) *> T0 *> l).
    destruct (head0_t3_t0 k l) as [l2 Hl2].
    eapply evstep_trans.
    + rewrite Hl2. apply step_unwind_t4_one.
    + rewrite <- Hl2. apply rule_q5_t3_unwind.
Qed.

Lemma left_T2_blk (b k : nat) (l r : Stream Sym) :
  (([S1; S1] *> (T5 ^^ b) *> T4 *> (T3 ^^ k) *> T2 *> T0 *> l) {{F}}> (T0 *> r)) -[ tm ]->*
  (([S1; S1] *> T0 *> l) {{F}}> ([S0; S1] *> (T2 ^^ (k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r)).
Proof.
  destruct b as [|b'].
  - simpl lpow. rewrite !zLan.
    eapply evstep_trans.
    + change (T2 *> T0 *> l) with (T0 *> [S0; S1] *> T0 *> l). apply left_noT2_b0.
    + eapply evstep_trans.
      * change ([S0; S1] *> (T2 ^^ k) *> [S0; S1; S0; S0] *> r) with
          (T0 *> [S1] *> (T2 ^^ k) *> [S0; S1; S0; S0] *> r).
        apply step_8A_head.
      * change ([S0; S0; S0] *> [S1] *> (T2 ^^ k) *> [S0; S1; S0; S0] *> r) with
          (T0 *> T2 *> (T2 ^^ k) *> [S0; S1; S0; S0] *> r).
        rewrite <- zPsr.
        change (T0 *> [S0; S1] *> T0 *> l) with (T2 *> T0 *> l).
        eapply evstep_trans; [apply step_E_t2_bounce |].
        eapply evstep_trans; [apply rule_C_1_t2 |].
        rewrite zPal.
        eapply evstep_trans.
        -- rewrite zPsr.
           change (T3 *> (T3 ^^ S k) *> T0 *> l) with (T0 *> [S1; S1] *> (T3 ^^ S k) *> T0 *> l).
           apply step_ret_0100_bounce.
        -- change (T0 *> [S1; S1] *> (T3 ^^ S k) *> T0 *> l) with (T3 *> (T3 ^^ S k) *> T0 *> l).
           rewrite <- zPsr. replace (S (S k)) with ((k + 1) + 1) by lia.
           apply rule_E_t3_to_Q5.
  - replace (S b') with (b' + 1) by lia.
    eapply evstep_trans.
    + change (T2 *> T0 *> l) with (T0 *> [S0; S1] *> T0 *> l). apply left_noT2_bsucc.
    + eapply evstep_trans.
      * change ([S0; S1] *> (T2 ^^ k) *> T5 *> (T4 ^^ b') *> [S0; S1; S0; S1] *> r) with
          (T0 *> [S1] *> (T2 ^^ k) *> T5 *> (T4 ^^ b') *> [S0; S1; S0; S1] *> r).
        apply step_8A_head.
      * change ([S0; S0; S0] *> [S1] *> (T2 ^^ k) *> T5 *> (T4 ^^ b') *> [S0; S1; S0; S1] *> r) with
          (T0 *> T2 *> (T2 ^^ k) *> T5 *> (T4 ^^ b') *> [S0; S1; S0; S1] *> r).
        rewrite <- zPsr.
        change (T0 *> [S0; S1] *> T0 *> l) with (T2 *> T0 *> l).
        eapply evstep_trans; [apply bounce_t5_to_Q5 |].
        replace (S k) with (k + 1) by lia. replace (b' + 1) with (S b') by lia.
        rewrite <- zPsr. apply evstep_refl.
Qed.

Lemma unwind_T2 (b k : nat) (l r : Stream Sym) :
  (([S1; S1] *> (T5 ^^ b) *> T4 *> (T3 ^^ k) *> T2 *> T0 *> l) {{F}}> ([S0; S1] *> r)) -[ tm ]->*
  (([S1; S1] *> T0 *> l) {{F}}> ([S0; S1] *> (T2 ^^ (k + 1)) *> (T4 ^^ (b + 1)) *> r)).
Proof.
  pose proof (left_T2_blk b k l (T1 *> r)) as H.
  change ([S0; S1; S0; S1] *> T1 *> r) with (T4 *> r) in H.
  rewrite zPal in H. replace (b + 1) with (S b) by lia. exact H.
Qed.

(* Section 7.5: Universal Pull1 Predicate and Combinators *)

Definition Pull1 (L_in L_out : Stream Sym) : Prop :=
  forall r : Stream Sym,
    (([S1; S1] *> L_in) {{F}}> (T0 *> r)) -[ tm ]->* (([S0; S1] *> L_out) {{E}}> (T1 *> r)).

Lemma right_ret_t4_0101_t3 (b : nat) (l r : Stream Sym) :
  ((T3 *> l) {{C}}> (T1 *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r)) -[ tm ]->*
  (([S0; S1] *> (T5 ^^ b) *> T4 *> l) {{E}}> (T1 *> r)).
Proof.
  destruct b as [|b'].
  - simpl lpow. rewrite !zLan. apply step_ret_0101_t3.
  - rewrite zPsr.
    eapply evstep_trans; [apply step_C_1_t4_one |].
    assert (H63 : T6 *> T3 *> l = T2 *> T4 *> l).
    { rewrite <- Str_app_assoc, t6_t3_eq, Str_app_assoc. reflexivity. }
    rewrite H63.
    eapply evstep_trans; [apply rule_C_1_t4 |].
    assert (H62 : (T6 ^^ b') *> T2 *> T4 *> l = T2 *> (T5 ^^ b') *> T4 *> l).
    { rewrite <- Str_app_assoc, <- t2_t5_pow, Str_app_assoc. reflexivity. }
    rewrite H62.
    eapply evstep_trans; [apply step_ret_0101_t2 |].
    rewrite <- zPsr. apply evstep_refl.
Qed.

Lemma pull1_base (b k : nat) (l : Stream Sym) :
  Pull1 ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> T2 *> T2 *> T0 *> l)
        ((T5 ^^ b) *> T4 *> (T3 ^^ (k + 2)) *> T0 *> l).
Proof.
  intros r.
  pose proof (left_T2_blk b k ([S0; S1] *> T0 *> l) r) as H1.
  change (T2 *> T0 *> [S0; S1] *> T0 *> l) with (T2 *> T2 *> T0 *> l) in H1.
  eapply evstep_trans; [exact H1 |].
  eapply evstep_trans.
  - change (T0 *> [S0; S1] *> T0 *> l) with (T0 *> [S0; S1] *> T0 *> l).
    change ([S0; S1] *> (T2 ^^ (k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r) with
      (T0 *> [S1] *> (T2 ^^ (k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r).
    apply step_8A_head.
  - change ([S0; S0; S0] *> [S1] *> (T2 ^^ (k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r) with
      (T0 *> T2 *> (T2 ^^ (k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r).
    rewrite <- zPsr.
    change (T0 *> [S0; S1] *> T0 *> l) with (T2 *> T0 *> l).
    eapply evstep_trans; [apply step_E_t2_bounce |].
    eapply evstep_trans; [apply rule_C_1_t2 |].
    rewrite zPal, zPsr.
    replace (S (k + 1)) with (k + 2) by lia.
    apply right_ret_t4_0101_t3.
Qed.

Lemma pull1_cons_t5_one {L_in L_out l0 : Stream Sym}
    (h0 : L_in = T0 *> l0) (h : Pull1 L_in L_out) :
    Pull1 (T5 *> L_in) (T5 *> L_out).
Proof.
  intros r.
  eapply evstep_trans.
  - rewrite h0. apply step_left_t5_one.
  - rewrite <- h0.
    change ([S0; S1] *> [S0; S1; S0; S1] *> r) with (T0 *> [S1] *> [S0; S1; S0; S1] *> r).
    eapply evstep_trans; [apply h |].
    change (T1 *> [S1] *> [S0; S1; S0; S1] *> r) with ([S1; S1] *> [S0; S1; S0; S1] *> r).
    eapply evstep_trans; [apply post_pull_rt5 |].
    apply step_ret_0101_t2.
Qed.

Lemma pull1_cons_t5 (b : nat) {L_in L_out l0 : Stream Sym}
    (h0 : L_in = T0 *> l0) (h : Pull1 L_in L_out) :
    Pull1 ((T5 ^^ b) *> L_in) ((T5 ^^ b) *> L_out).
Proof.
  induction b as [|b' IH].
  - simpl lpow. rewrite !zLan. exact h.
  - rewrite !zPsr.
    destruct (head0_t5_t0 b' l0) as [l' Hl'].
    apply (pull1_cons_t5_one (l0 := l')).
    + rewrite h0, Hl'. reflexivity.
    + exact IH.
Qed.

Lemma pull1_cons_T2 (b k : nat) {L_in L_out l0 : Stream Sym}
    (h0 : L_in = T0 *> l0) (h : Pull1 L_in L_out) :
    Pull1 ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> T2 *> L_in)
          ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> T2 *> L_out).
Proof.
  intros r.
  eapply evstep_trans.
  - rewrite h0. apply left_T2_blk.
  - rewrite <- h0.
    change ([S0; S1] *> (T2 ^^ (k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r) with
      (T0 *> [S1] *> (T2 ^^ (k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r).
    eapply evstep_trans; [apply h |].
    change (T1 *> [S1] *> (T2 ^^ (k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r) with
      ([S1; S1] *> (T2 ^^ (k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r).
    eapply evstep_trans; [apply post_pull_rt5 |].
    eapply evstep_trans; [apply rule_C_1_t2 |].
    replace (k + 1) with (S k) by lia. rewrite zPsr.
    apply right_ret_t4_0101_t3.
Qed.

Lemma pull1_cons_noT2 (b k : nat) {L_in L_out l0 : Stream Sym}
    (h0 : L_in = T0 *> l0) (h : Pull1 L_in L_out) :
    Pull1 ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> L_in)
          ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> L_out).
Proof.
  intros r.
  destruct b as [|b'].
  - simpl lpow. rewrite !zLan.
    eapply evstep_trans.
    + rewrite h0. apply left_noT2_b0.
    + rewrite <- h0.
      change ([S0; S1] *> (T2 ^^ k) *> [S0; S1; S0; S0] *> r) with
        (T0 *> [S1] *> (T2 ^^ k) *> [S0; S1; S0; S0] *> r).
      eapply evstep_trans; [apply h |].
      change (T1 *> [S1] *> (T2 ^^ k) *> [S0; S1; S0; S0] *> r) with
        ([S1; S1] *> (T2 ^^ k) *> [S0; S1; S0; S0] *> r).
      eapply evstep_trans; [apply post_pull_rt5 |].
      eapply evstep_trans; [apply rule_C_1_t2 |].
      destruct k as [|k'].
      * simpl lpow. rewrite !zLan. apply step_ret_0100_t2.
      * eapply evstep_trans.
        -- rewrite zPsr.
           change (T3 *> (T3 ^^ k') *> T2 *> L_out) with (T0 *> [S1; S1] *> (T3 ^^ k') *> T2 *> L_out).
           apply step_ret_0100_bounce.
        -- change (T0 *> [S1; S1] *> (T3 ^^ k') *> T2 *> L_out) with (T3 *> (T3 ^^ k') *> T2 *> L_out).
           rewrite <- zPsr.
           change (T2 *> L_out) with (T0 *> [S0; S1] *> L_out).
           eapply evstep_trans; [apply rule_E_t3 |].
           change (T0 *> [S0; S1] *> L_out) with (T2 *> L_out).
           eapply evstep_trans; [apply step_E_t2_bounce |].
           eapply evstep_trans; [apply rule_C_1_t2 |].
           rewrite zPal, zPsr. apply step_ret_0101_t3.
  - replace (S b') with (b' + 1) by lia.
    eapply evstep_trans.
    + rewrite h0. apply left_noT2_bsucc.
    + rewrite <- h0.
      change ([S0; S1] *> (T2 ^^ k) *> T5 *> (T4 ^^ b') *> [S0; S1; S0; S1] *> r) with
        (T0 *> [S1] *> (T2 ^^ k) *> T5 *> (T4 ^^ b') *> [S0; S1; S0; S1] *> r).
      eapply evstep_trans; [apply h |].
      change (T1 *> [S1] *> (T2 ^^ k) *> T5 *> (T4 ^^ b') *> [S0; S1; S0; S1] *> r) with
        ([S1; S1] *> (T2 ^^ k) *> T5 *> (T4 ^^ b') *> [S0; S1; S0; S1] *> r).
      eapply evstep_trans; [apply post_pull_rt5 |].
      eapply evstep_trans; [apply rule_C_1_t2 |].
      destruct (t3_pow_t2_headZero k L_out) as [l' Hl'].
      eapply evstep_trans.
      * rewrite Hl'. apply step_C_1_t5_bounce.
      * rewrite <- Hl'. change (T2 *> L_out) with (T0 *> [S0; S1] *> L_out).
        eapply evstep_trans; [apply rule_E_t3 |].
        change (T0 *> [S0; S1] *> L_out) with (T2 *> L_out).
        eapply evstep_trans; [apply step_E_t2_bounce |].
        eapply evstep_trans; [apply rule_C_1_t2 |].
        rewrite zPal, zPsr.
        replace (b' + 1) with (S b') by lia.
        rewrite <- (zPsr T4 b').
        apply right_ret_t4_0101_t3.
Qed.

(* Section 7.6: Universal Pull1 Consumers *)

Lemma pull1_t4 {L_in L_out : Stream Sym} (h : Pull1 L_in L_out) (r : Stream Sym) :
  (([S1; S1] *> L_in) {{F}}> (T4 *> r)) -[ tm ]->* (([S1; S1] *> T5 *> L_out) {{F}}> r).
Proof.
  change (T4 *> r) with (T0 *> [S1; S0; S1; S1] *> r).
  eapply evstep_trans; [apply h |].
  apply post_pull_t4.
Qed.

Lemma pull1_t3_t22 (k : nat) {L_in L_out l0 l0' : Stream Sym}
    (h0 : L_in = T0 *> l0) (h0' : L_out = T0 *> l0') (h : Pull1 L_in L_out) (r : Stream Sym) :
    (([S1; S1] *> (T3 ^^ k) *> L_in) {{F}}> (T2 *> T2 *> r)) -[ tm ]->*
    (([S1; S1] *> (T3 ^^ (k + 2)) *> L_out) {{F}}> r).
Proof.
  destruct k as [|k'].
  - simpl lpow. rewrite !zLan.
    change (T2 *> T2 *> r) with (T0 *> T5 *> r).
    eapply evstep_trans; [apply h |].
    apply post_pull_t22.
  - eapply evstep_trans.
    + rewrite zPsr.
      change (T3 *> (T3 ^^ k') *> L_in) with (T0 *> [S1; S1] *> (T3 ^^ k') *> L_in).
      change (T2 *> T2 *> r) with (T0 *> [S0; S1] *> T2 *> r).
      apply step_8A_head.
    + change ([S0; S0; S0] *> [S0; S1] *> T2 *> r) with (T0 *> T0 *> T2 *> T2 *> r).
      change (T0 *> [S1; S1] *> (T3 ^^ k') *> L_in) with (T3 *> (T3 ^^ k') *> L_in).
      rewrite <- zPsr. replace (S k') with (k' + 1) by lia.
      eapply evstep_trans.
      * rewrite h0. apply rule_E_t3_to_Q5.
      * rewrite <- h0.
        change ([S0; S1] *> (T2 ^^ k') *> T0 *> T2 *> T2 *> r) with
          (T0 *> [S1] *> (T2 ^^ k') *> T0 *> T2 *> T2 *> r).
        eapply evstep_trans; [apply h |].
        change (T1 *> [S1] *> (T2 ^^ k') *> T0 *> T2 *> T2 *> r) with
          ([S1; S1] *> (T2 ^^ k') *> T0 *> T2 *> T2 *> r).
        eapply evstep_trans; [apply post_pull_rt5 |].
        eapply evstep_trans; [apply rule_C_1_t2 |].
        change (T1 *> T0 *> T2 *> T2 *> r) with ([S1; S0] *> T2 *> T2 *> r).
        eapply evstep_trans; [apply step_8A_tail |].
        rewrite <- zPsr, h0'.
        replace (k' + 1 + 2) with (S k' + 2) by lia.
        apply step_8A_t3_sweep.
Qed.

Lemma pull1_t3_t4 (k : nat) {L_in L_out l0 : Stream Sym}
    (h0 : L_in = T0 *> l0) (h : Pull1 L_in L_out) (r : Stream Sym) :
    (([S1; S1] *> (T3 ^^ (k + 1)) *> L_in) {{F}}> (T4 *> r)) -[ tm ]->*
    (([S1; S1] *> T4 *> (T3 ^^ k) *> T2 *> L_out) {{F}}> r).
Proof.
  eapply evstep_trans.
  - replace (k + 1) with (S k) by lia. rewrite zPsr.
    change (T3 *> (T3 ^^ k) *> L_in) with (T0 *> [S1; S1] *> (T3 ^^ k) *> L_in).
    change (T4 *> r) with (T0 *> [S1; S0; S1; S1] *> r).
    apply step_8A_head.
  - change ([S0; S0; S0] *> [S1; S0; S1; S1] *> r) with (T0 *> T2 *> T3 *> r).
    change (T0 *> [S1; S1] *> (T3 ^^ k) *> L_in) with (T3 *> (T3 ^^ k) *> L_in).
    rewrite <- zPsr. replace (S k) with (k + 1) by lia.
    eapply evstep_trans.
    + rewrite h0. apply rule_E_t3_to_Q5.
    + rewrite <- h0, zPal.
      change ([S0; S1] *> (T2 ^^ S k) *> T3 *> r) with (T0 *> [S1] *> (T2 ^^ S k) *> T3 *> r).
      eapply evstep_trans; [apply h |].
      change (T1 *> [S1] *> (T2 ^^ S k) *> T3 *> r) with ([S1; S1] *> (T2 ^^ S k) *> T3 *> r).
      eapply evstep_trans; [apply post_pull_rt5 |].
      eapply evstep_trans; [apply rule_C_1_t2 |].
      rewrite zPsr. apply step_8B_cap_t3.
Qed.

Lemma pull1_t3_t2_t4 (k : nat) {L_in L_out l0 : Stream Sym}
    (h0 : L_in = T0 *> l0) (h : Pull1 L_in L_out) (r : Stream Sym) :
    (([S1; S1] *> (T3 ^^ k) *> L_in) {{F}}> (T2 *> T4 *> r)) -[ tm ]->*
    (([S1; S1] *> T4 *> (T3 ^^ (k + 1)) *> L_out) {{F}}> r).
Proof.
  destruct k as [|k'].
  - rewrite zPz, zLan.
    change (T2 *> T4 *> r) with (T0 *> [S0; S1] *> T4 *> r).
    eapply evstep_trans; [apply h |].
    change (0 + 1) with 1. rewrite zP1. apply step_post_pull_t2_t4_k0.
  - eapply evstep_trans.
    + rewrite zPsr.
      change (T3 *> (T3 ^^ k') *> L_in) with (T0 *> [S1; S1] *> (T3 ^^ k') *> L_in).
      change (T2 *> T4 *> r) with (T0 *> [S0; S1] *> T4 *> r).
      apply step_8A_head.
    + change ([S0; S0; S0] *> [S0; S1] *> T4 *> r) with (T0 *> T0 *> T2 *> T4 *> r).
      change (T0 *> [S1; S1] *> (T3 ^^ k') *> L_in) with (T3 *> (T3 ^^ k') *> L_in).
      rewrite <- zPsr. replace (S k') with (k' + 1) by lia.
      eapply evstep_trans.
      * rewrite h0. apply rule_E_t3_to_Q5.
      * rewrite <- h0.
        change ([S0; S1] *> (T2 ^^ k') *> T0 *> T2 *> T4 *> r) with
          (T0 *> [S1] *> (T2 ^^ k') *> T0 *> T2 *> T4 *> r).
        eapply evstep_trans; [apply h |].
        change (T1 *> [S1] *> (T2 ^^ k') *> T0 *> T2 *> T4 *> r) with
          ([S1; S1] *> (T2 ^^ k') *> T0 *> T2 *> T4 *> r).
        eapply evstep_trans; [apply post_pull_rt5 |].
        eapply evstep_trans; [apply rule_C_1_t2 |].
        change (T1 *> T0 *> T2 *> T4 *> r) with ([S1; S0] *> T2 *> T4 *> r).
        eapply evstep_trans; [apply step_8A_tail |].
        eapply evstep_trans.
        -- change (T3 *> (T3 ^^ k') *> T2 *> L_out) with (T0 *> [S1; S1] *> (T3 ^^ k') *> T2 *> L_out).
           change (T4 *> r) with (T0 *> [S1; S0; S1; S1] *> r).
           apply step_8A_head.
        -- change ([S0; S0; S0] *> [S1; S0; S1; S1] *> r) with (T0 *> T2 *> T3 *> r).
           change (T0 *> [S1; S1] *> (T3 ^^ k') *> T2 *> L_out) with (T3 *> (T3 ^^ k') *> T2 *> L_out).
           rewrite <- zPsr.
           change (T2 *> L_out) with (T0 *> [S0; S1] *> L_out).
           eapply evstep_trans; [apply rule_E_t3 |].
           change (T0 *> [S0; S1] *> L_out) with (T2 *> L_out).
           eapply evstep_trans; [apply step_E_t2_bounce |].
           rewrite zPal.
           eapply evstep_trans; [apply rule_C_1_t2 |].
           rewrite zPal, zPsr.
           replace (S (S k')) with (k' + 1 + 1) by lia.
           apply step_8B_cap_t3.
Qed.

Lemma pull1_t3_t5 (k : nat) {L_in L_out l0 : Stream Sym}
    (h0 : L_in = T0 *> l0) (h : Pull1 L_in L_out) (r : Stream Sym) :
    (([S1; S1] *> (T3 ^^ k) *> L_in) {{F}}> (T5 *> r)) -[ tm ]->*
    (([S1] *> (T3 ^^ (k + 1)) *> T2 *> L_out) {{A}}> r).
Proof.
  destruct k as [|k'].
  - rewrite zPz, zLan.
    change (T5 *> r) with (T0 *> [S1; S0; S0; S1] *> r).
    eapply evstep_trans; [apply h |].
    change (0 + 1) with 1. rewrite zP1. apply step_post_pull_t5_k0_clean.
  - eapply evstep_trans.
    + rewrite zPsr.
      change (T3 *> (T3 ^^ k') *> L_in) with (T0 *> [S1; S1] *> (T3 ^^ k') *> L_in).
      change (T5 *> r) with (T0 *> [S1; S0; S0; S1] *> r).
      apply step_8A_head.
    + change ([S0; S0; S0] *> [S1; S0; S0; S1] *> r) with (T0 *> T2 *> T2 *> r).
      change (T0 *> [S1; S1] *> (T3 ^^ k') *> L_in) with (T3 *> (T3 ^^ k') *> L_in).
      rewrite <- zPsr. replace (S k') with (k' + 1) by lia.
      eapply evstep_trans.
      * rewrite h0. apply rule_E_t3_to_Q5.
      * rewrite <- h0, !zPal.
        change ([S0; S1] *> (T2 ^^ S (S k')) *> r) with (T0 *> [S1] *> (T2 ^^ S (S k')) *> r).
        eapply evstep_trans; [apply h |].
        change (T1 *> [S1] *> (T2 ^^ S (S k')) *> r) with ([S1; S1] *> (T2 ^^ S (S k')) *> r).
        eapply evstep_trans; [apply post_pull_q0 |].
        replace (k' + 1 + 1) with (S (S k')) by lia.
        apply rule_q0_t2.
Qed.

Lemma pull1_t3_t2_t5 (k : nat) {L_in L_out l0 : Stream Sym}
    (h0 : L_in = T0 *> l0) (h : Pull1 L_in L_out) (r : Stream Sym) :
    (([S1; S1] *> (T3 ^^ k) *> L_in) {{F}}> (T2 *> T5 *> r)) -[ tm ]->*
    (([S1] *> (T3 ^^ (k + 3)) *> L_out) {{A}}> r).
Proof.
  destruct k as [|k'].
  - simpl lpow. rewrite !zLan.
    change (T2 *> T5 *> r) with (T0 *> [S0; S1] *> T5 *> r).
    eapply evstep_trans; [apply h |].
    apply step_post_pull_t2_t5_k0.
  - eapply evstep_trans.
    + rewrite zPsr.
      change (T3 *> (T3 ^^ k') *> L_in) with (T0 *> [S1; S1] *> (T3 ^^ k') *> L_in).
      change (T2 *> T5 *> r) with (T0 *> [S0; S1] *> T5 *> r).
      apply step_8A_head.
    + change ([S0; S0; S0] *> [S0; S1] *> T5 *> r) with (T0 *> T0 *> T2 *> T5 *> r).
      change (T0 *> [S1; S1] *> (T3 ^^ k') *> L_in) with (T3 *> (T3 ^^ k') *> L_in).
      rewrite <- zPsr. replace (S k') with (k' + 1) by lia.
      eapply evstep_trans.
      * rewrite h0. apply rule_E_t3_to_Q5.
      * rewrite <- h0.
        change ([S0; S1] *> (T2 ^^ k') *> T0 *> T2 *> T5 *> r) with
          (T0 *> [S1] *> (T2 ^^ k') *> T0 *> T2 *> T5 *> r).
        eapply evstep_trans; [apply h |].
        change (T1 *> [S1] *> (T2 ^^ k') *> T0 *> T2 *> T5 *> r) with
          ([S1; S1] *> (T2 ^^ k') *> T0 *> T2 *> T5 *> r).
        eapply evstep_trans; [apply post_pull_rt5 |].
        eapply evstep_trans; [apply rule_C_1_t2 |].
        change (T1 *> T0 *> T2 *> T5 *> r) with ([S1; S0] *> T2 *> T5 *> r).
        eapply evstep_trans; [apply step_8A_tail |].
        eapply evstep_trans.
        -- change (T3 *> (T3 ^^ k') *> T2 *> L_out) with (T0 *> [S1; S1] *> (T3 ^^ k') *> T2 *> L_out).
           change (T5 *> r) with (T0 *> [S1; S0; S0; S1] *> r).
           apply step_8A_head.
        -- change ([S0; S0; S0] *> [S1; S0; S0; S1] *> r) with (T0 *> T2 *> T2 *> r).
           change (T0 *> [S1; S1] *> (T3 ^^ k') *> T2 *> L_out) with (T3 *> (T3 ^^ k') *> T2 *> L_out).
           rewrite <- zPsr.
           change (T2 *> L_out) with (T0 *> [S0; S1] *> L_out).
           eapply evstep_trans; [apply rule_E_t3 |].
           change (T0 *> [S0; S1] *> L_out) with (T2 *> L_out).
           eapply evstep_trans; [apply step_E_t2_bounce |].
           rewrite !zPal.
           eapply evstep_trans; [apply rule_C_1_t2 |].
           rewrite zPal.
           replace (k' + 1 + 3) with (S (S (S (S k')))) by lia.
           apply step_C_1_to_q0.
Qed.

Lemma pull1_rt5 {L_in L_out l0' : Stream Sym} {P_in P_out : list Sym} {tail : Stream Sym}
    (h0' : L_out = T0 *> l0') (h : Pull1 L_in L_out) (hrt : RoundTripQ5 P_in P_out tail) :
    (([S1; S1] *> L_in) {{F}}> ([S0; S1] *> P_in *> tail)) -[ tm ]->*
    (([S1; S1] *> L_out) {{F}}> ([S0; S1] *> P_out *> tail)).
Proof.
  change ([S0; S1] *> P_in *> tail) with (T0 *> [S1] *> P_in *> tail).
  eapply evstep_trans; [apply h |].
  change (T1 *> [S1] *> P_in *> tail) with ([S1; S1] *> P_in *> tail).
  eapply evstep_trans; [apply post_pull_rt5 |].
  rewrite h0'.
  pose proof (hrt 0 l0') as Hrt0.
  simpl lpow in Hrt0. rewrite !zLan in Hrt0. exact Hrt0.
Qed.

(* --- ScratchAtom2.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

Lemma step_post_pull_unzip_seg (l r : Stream Sym) :
  (([S0; S1] *> l) {{E}}> (T1 *> [S1; S1] *> T4 *> r)) -[ tm ]->*
  (([S1; S1] *> T4 *> T3 *> l) {{F}}> r).
Proof. execute. Qed.

(* --- ScratchS2A.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

(* ========================================================================= *)
(* Generic N <-> nat, Boolean, Option, List, and Blank-Tape Helpers          *)
(* ========================================================================= *)

Ltac split_andb :=
  repeat match goal with
  | H : (_ && _)%bool = true |- _ => apply Bool.andb_true_iff in H; destruct H
  | H : negb _ = true |- _ => apply Bool.negb_true_iff in H
  | H : negb _ = false |- _ => apply Bool.negb_false_iff in H
  | H : Bool.eqb ?a ?b = true |- _ => apply (proj1 (Bool.eqb_true_iff a b)) in H
  | H : N.leb _ _ = true |- _ => apply N.leb_le in H
  | H : N.ltb _ _ = true |- _ => apply N.ltb_lt in H
  | H : N.eqb _ _ = true |- _ => apply N.eqb_eq in H
  | H : N.eqb _ _ = false |- _ => apply N.eqb_neq in H
  | H : N.leb _ _ = false |- _ => apply N.leb_gt in H
  | H : N.ltb _ _ = false |- _ => apply N.ltb_ge in H
  end.

Lemma N2Nat_div (a b : N) : N.to_nat (a / b)%N = N.to_nat a / N.to_nat b.
Proof.
  destruct (N.eq_dec b 0%N) as [Hb0 | Hb0].
  - subst b. rewrite N.div_0_r, Nat.div_0_r. reflexivity.
  - pose proof (N.div_mod a b Hb0) as Hdm.
    pose proof (N.mod_lt a b Hb0) as Hlt.
    assert (Hnb : N.to_nat b <> 0) by lia.
    pose proof (Nat.div_mod (N.to_nat a) (N.to_nat b) Hnb) as Hndm.
    pose proof (Nat.mod_upper_bound (N.to_nat a) (N.to_nat b) Hnb) as Hnlt.
    apply (f_equal N.to_nat) in Hdm.
    rewrite N2Nat.inj_add, N2Nat.inj_mul in Hdm.
    nia.
Qed.

Lemma N2Nat_mod (a b : N) : N.to_nat (a mod b)%N = (N.to_nat a) mod (N.to_nat b).
Proof.
  destruct (N.eq_dec b 0%N) as [Hb0 | Hb0].
  - subst b. rewrite N.mod_0_r, Nat.mod_0_r. reflexivity.
  - pose proof (N.div_mod a b Hb0) as Hdm.
    pose proof (N.mod_lt a b Hb0) as Hlt.
    assert (Hnb : N.to_nat b <> 0) by lia.
    pose proof (Nat.div_mod (N.to_nat a) (N.to_nat b) Hnb) as Hndm.
    pose proof (Nat.mod_upper_bound (N.to_nat a) (N.to_nat b) Hnb) as Hnlt.
    apply (f_equal N.to_nat) in Hdm.
    rewrite N2Nat.inj_add, N2Nat.inj_mul in Hdm.
    nia.
Qed.

Lemma N_even_decomp (a : N) :
  (a mod 2)%N = 0%N -> N.to_nat a = 2 * N.to_nat (a / 2)%N.
Proof.
  intros Hmod. pose proof (N.div_mod a 2 ltac:(discriminate)) as Hdm.
  rewrite Hmod, N.add_0_r in Hdm.
  apply (f_equal N.to_nat) in Hdm. lia.
Qed.

Lemma N_odd_decomp (a : N) :
  (a mod 2)%N <> 0%N -> N.to_nat a = 2 * N.to_nat (a / 2)%N + 1.
Proof.
  intros Hmod. pose proof (N.div_mod a 2 ltac:(discriminate)) as Hdm.
  pose proof (N.mod_lt a 2 ltac:(discriminate)) as Hlt.
  assert (Hm1 : (a mod 2)%N = 1%N) by lia.
  rewrite Hm1 in Hdm. apply (f_equal N.to_nat) in Hdm. lia.
Qed.

Lemma N_mul_div_le (x y : N) : (x / y * y <= x)%N.
Proof.
  destruct (N.eq_dec y 0%N) as [Hy | Hy].
  - subst y. simpl. lia.
  - pose proof (N.div_mod x y Hy) as Hdm. lia.
Qed.

Lemma tok_eqb_eq (x y : Tok) : tok_eqb x y = true <-> x = y.
Proof.
  destruct x, y; simpl; split; intros H; try reflexivity; discriminate.
Qed.

Lemma isEmpty_true_iff {X : Type} (xs : list X) : isEmpty xs = true <-> xs = [].
Proof.
  destruct xs; simpl; split; intros H; try reflexivity; discriminate.
Qed.

Lemma isSome_true_iff {X : Type} (o : option X) : isSome o = true <-> exists x, o = Some x.
Proof.
  destruct o as [x|]; simpl; split; intros H.
  - exists x. reflexivity.
  - reflexivity.
  - discriminate.
  - destruct H as [? Hc]. discriminate.
Qed.

Lemma option_map_Some {X Y : Type} (f : X -> Y) (o : option X) (y : Y) :
  option_map f o = Some y <-> exists x, o = Some x /\ f x = y.
Proof.
  destruct o as [x|]; simpl; split; intros H.
  - inversion H; subst. exists x. split; reflexivity.
  - destruct H as [x' [Ho Hf]]. inversion Ho; subst. reflexivity.
  - discriminate.
  - destruct H as [x' [Ho _]]. discriminate.
Qed.

Lemma splitAtList_sound {X : Type} : forall (i : nat) (xs pref suf : list X),
  splitAtList i xs = Some (pref, suf) -> xs = pref ++ suf.
Proof.
  induction i as [|i IH]; intros xs pref suf H.
  - simpl in H. inversion H; subst. reflexivity.
  - destruct xs as [|x xs']; [simpl in H; discriminate |].
    simpl in H. apply option_map_Some in H.
    destruct H as [[p s] [Hsp Heq]]. simpl in Heq. inversion Heq; subst.
    simpl. f_equal. eapply IH; exact Hsp.
Qed.

Lemma zero_append_default : [S0] *> b0 = b0.
Proof.
  simpl. symmetry. apply const_unfold.
Qed.

Lemma zero_pow_append_default (n : nat) : (T0 ^^ n) *> b0 = b0.
Proof.
  induction n as [|n IH].
  - reflexivity.
  - rewrite zPsr, IH. exact zero_append_default.
Qed.

(* ========================================================================= *)
(* Section 8.1: stepStar_drop_one, q0_t2_rt5, and Zero-Pull Heal Helpers     *)
(* ========================================================================= *)

Lemma stepStar_trans {c1 c2 c3 : Q * tape}
    (h1 : c1 -[ tm ]->* c2) (h2 : c2 -[ tm ]->* c3) : c1 -[ tm ]->* c3.
Proof. eapply evstep_trans; [exact h1 | exact h2]. Qed.

Lemma stepStar_drop_one {ca cb cc : Q * tape}
    (h1 : ca -[ tm ]-> cb) (hstar : ca -[ tm ]->* cc) (hne : ca <> cc) :
    cb -[ tm ]->* cc.
Proof.
  inversion hstar as [Heq | x y z Hxy Hyz]; subst.
  - contradiction.
  - assert (Heq : cb = y) by (eapply step_deterministic; eauto).
    subst y. exact Hyz.
Qed.

Lemma q0_t2_rt5 (k : nat) {P_in P_out : list Sym} {tail : Stream Sym}
    (hrt : RoundTripQ5 P_in P_out tail) (l : Stream Sym) :
    (([S1] *> (T3 ^^ k) *> T2 *> T0 *> l) {{A}}> (P_in *> tail)) -[ tm ]->*
    (([S1; S1] *> T0 *> l) {{F}}> ([S0; S1] *> (T2 ^^ k) *> P_out *> tail)).
Proof.
  assert (H1 : (((T3 ^^ k) *> T2 *> T0 *> l) {{C}}> (T1 *> P_in *> tail)) -[ tm ]->
               (([S1] *> (T3 ^^ k) *> T2 *> T0 *> l) {{A}}> (P_in *> tail))).
  { apply (step_right (s' := S1) (q' := A)). reflexivity. }
  eapply stepStar_drop_one; [exact H1 | apply (hrt k l) |].
  intros Heq. discriminate Heq.
Qed.

Lemma step_heal_odd_h0 (an : nat) (l r : Stream Sym) :
  (([S1; S1] *> (T3 ^^ (an + 1)) *> T2 *> l) {{F}}> (T4 *> r)) -[ tm ]->*
  (([S1; S1] *> T4 *> (T3 ^^ (an + 2)) *> l) {{F}}> r).
Proof.
  assert (H1 : (([S1; S1] *> (T3 ^^ (an + 1)) *> T2 *> l) {{F}}> (T4 *> r)) -[ tm ]->*
               (((T3 ^^ (an + 1)) *> T2 *> l) {{E}}> (T0 *> T2 *> T3 *> r))).
  { replace (an + 1) with (S an) by lia. rewrite zPsr.
    exact (step_8A_head ([S1; S1] *> (T3 ^^ an) *> T2 *> l) ([S1; S0; S1; S1] *> r)). }
  eapply evstep_trans; [exact H1 |].
  change (T2 *> l) with (T0 *> [S0; S1] *> l).
  eapply evstep_trans; [apply (rule_E_t3 (an + 1) ([S0; S1] *> l) (T2 *> T3 *> r)) |].
  change (T0 *> [S0; S1] *> l) with (T2 *> l).
  eapply evstep_trans; [apply (step_E_t2_bounce l ((T2 ^^ (an + 1)) *> T2 *> T3 *> r)) |].
  rewrite zPal. replace (S (an + 1)) with (an + 2) by lia.
  eapply evstep_trans; [apply (rule_C_1_t2 (an + 2) (T3 *> l) (T3 *> r)) |].
  rewrite zPal, zPsr.
  apply (step_8B_cap_t3 ((T3 ^^ (an + 2)) *> l) r).
Qed.

Lemma step_heal_odd_h1 (an : nat) (l r : Stream Sym) :
  (([S1; S1] *> (T3 ^^ (an + 1)) *> T2 *> l) {{F}}> (T5 *> r)) -[ tm ]->*
  (([S1] *> (T3 ^^ (an + 4)) *> l) {{A}}> r).
Proof.
  assert (H1 : (([S1; S1] *> (T3 ^^ (an + 1)) *> T2 *> l) {{F}}> (T5 *> r)) -[ tm ]->*
               (((T3 ^^ (an + 1)) *> T2 *> l) {{E}}> (T0 *> T2 *> T2 *> r))).
  { replace (an + 1) with (S an) by lia. rewrite zPsr.
    exact (step_8A_head ([S1; S1] *> (T3 ^^ an) *> T2 *> l) ([S1; S0; S0; S1] *> r)). }
  eapply evstep_trans; [exact H1 |].
  change (T2 *> l) with (T0 *> [S0; S1] *> l).
  eapply evstep_trans; [apply (rule_E_t3 (an + 1) ([S0; S1] *> l) (T2 *> T2 *> r)) |].
  change (T0 *> [S0; S1] *> l) with (T2 *> l).
  eapply evstep_trans; [apply (step_E_t2_bounce l ((T2 ^^ (an + 1)) *> T2 *> T2 *> r)) |].
  rewrite !zPal. replace (S (S (an + 1))) with (an + 3) by lia.
  eapply evstep_trans; [apply (rule_C_1_t2 (an + 3) (T3 *> l) r) |].
  rewrite zPal. replace (S (an + 3)) with (an + 4) by lia.
  apply (step_C_1_to_q0 ((T3 ^^ (an + 4)) *> l) r).
Qed.

(* ========================================================================= *)
(* Section 8.2: The Universal PipeL Energy-Pipe Abstraction                  *)
(* ========================================================================= *)

Inductive PipeL : nat -> list Sym -> Stream Sym -> Prop :=
  | PipeL_mk0 {R_out : list Sym} {Lt l0 : Stream Sym}
      (h0 : Lt = T0 *> l0)
      (hunw : forall r : Stream Sym,
        (([S1; S1] *> Lt) {{F}}> ([S0; S1] *> r)) -[ tm ]->*
        (b0 {{E}}> (T2 *> T0 *> T1 *> R_out *> r))) :
      PipeL 0 R_out Lt
  | PipeL_mkS {En : nat} {R_out : list Sym} {Lt Lt' l0 : Stream Sym}
      (h0 : Lt = T0 *> l0)
      (hpull : Pull1 Lt Lt')
      (hnext : PipeL En R_out Lt') :
      PipeL (En + 1) R_out Lt.

Lemma PipeL_head0 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (hp : PipeL En R_out Lt) : exists l0, Lt = T0 *> l0.
Proof.
  destruct hp as [? ? l0 h0 _ | ? ? ? ? l0 h0 _ _]; exists l0; exact h0.
Qed.

Lemma PipeL_pull {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (hp : PipeL (En + 1) R_out Lt) : exists Lt', Pull1 Lt Lt' /\ PipeL En R_out Lt'.
Proof.
  inversion hp as [Heq | En0 R0 Lt0 Lt' l0 H0 Hpull Hnext Heq]; [lia |].
  assert (HE : En0 = En) by lia. subst En0.
  exists Lt'. split; assumption.
Qed.

Lemma PipeL_unwind {R_out : list Sym} {Lt : Stream Sym}
    (hp : PipeL 0 R_out Lt) (r : Stream Sym) :
    (([S1; S1] *> Lt) {{F}}> ([S0; S1] *> r)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *> R_out *> r)).
Proof.
  inversion hp as [R0 Lt0 l0 H0 Hunw | En0]; [exact (Hunw r) | lia].
Qed.

Lemma pipeL_eqR {En : nat} {R1 R2 : list Sym} {Lt : Stream Sym}
    (heq : R1 = R2) (hp : PipeL En R1 Lt) : PipeL En R2 Lt.
Proof.
  subst R2. exact hp.
Qed.

Lemma pipeL_eqE {E1 E2 : nat} {R_out : list Sym} {Lt : Stream Sym}
    (heq : E1 = E2) (hp : PipeL E1 R_out Lt) : PipeL E2 R_out Lt.
Proof.
  subst E2. exact hp.
Qed.

Lemma pipeL_eqER {E1 E2 : nat} {R1 R2 : list Sym} {Lt : Stream Sym}
    (hp : PipeL E1 R1 Lt) (hE : E1 = E2) (hR : R1 = R2) : PipeL E2 R2 Lt.
Proof.
  subst E2 R2. exact hp.
Qed.

Lemma pipeL_t5 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (b : nat) (hp : PipeL En R_out Lt) :
    PipeL En (R_out ++ (T4 ^^ b)) ((T5 ^^ b) *> Lt).
Proof.
  induction hp as [R_out Lt l0 h0 hunw | En R_out Lt Lt' l0 h0 hpull _ IH].
  - subst Lt. destruct (head0_t5_t0 b l0) as [l' hl'].
    eapply PipeL_mk0; [exact hl' |].
    intros r.
    eapply evstep_trans.
    + apply (rule_unwind_t5 b l0 r).
    + rewrite Str_app_assoc. apply (hunw ((T4 ^^ b) *> r)).
  - destruct (head0_t5_t0 b l0) as [l' hl'].
    eapply PipeL_mkS.
    + rewrite h0, hl'. reflexivity.
    + exact (pull1_cons_t5 b h0 hpull).
    + exact IH.
Qed.

Lemma pipeL_T2_blk {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (b k : nat) (hp : PipeL En R_out Lt) :
    PipeL En ((R_out ++ (T2 ^^ (k + 1))) ++ (T4 ^^ (b + 1)))
      ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> T2 *> Lt).
Proof.
  induction hp as [R_out Lt l0 h0 hunw | En R_out Lt Lt' l0 h0 hpull _ IH].
  - subst Lt. destruct (head0_t5_t4 b ((T3 ^^ k) *> T2 *> T0 *> l0)) as [l' hl'].
    eapply PipeL_mk0; [exact hl' |].
    intros r.
    eapply evstep_trans.
    + apply (unwind_T2 b k l0 r).
    + rewrite !Str_app_assoc. apply (hunw ((T2 ^^ (k + 1)) *> (T4 ^^ (b + 1)) *> r)).
  - destruct (head0_t5_t4 b ((T3 ^^ k) *> T2 *> Lt)) as [l' hl'].
    eapply PipeL_mkS; [exact hl' | exact (pull1_cons_T2 b k h0 hpull) | exact IH].
Qed.

Lemma pipeL_noT2_blk {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (b k : nat) (hp : PipeL En R_out Lt) :
    PipeL En (((R_out ++ (T2 ^^ k)) ++ T5) ++ (T4 ^^ b))
      ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> Lt).
Proof.
  induction hp as [R_out Lt l0 h0 hunw | En R_out Lt Lt' l0 h0 hpull _ IH].
  - subst Lt. destruct (head0_t5_t4 b ((T3 ^^ k) *> T0 *> l0)) as [l' hl'].
    eapply PipeL_mk0; [exact hl' |].
    intros r.
    eapply evstep_trans.
    + apply (unwind_noT2 b k l0 r).
    + rewrite !Str_app_assoc. apply (hunw ((T2 ^^ k) *> T5 *> (T4 ^^ b) *> r)).
  - destruct (head0_t5_t4 b ((T3 ^^ k) *> Lt)) as [l' hl'].
    eapply PipeL_mkS; [exact hl' | exact (pull1_cons_noT2 b k h0 hpull) | exact IH].
Qed.

Lemma pipeL_base_c0_noT2 (En b k : nat) :
  PipeL En (((T2 ^^ (k + 2 * En + 1)) ++ T5) ++ (T4 ^^ b))
    ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> (T2 ^^ (2 * En)) *> [S0; S1; S0; S1] *> b0).
Proof.
  revert k. induction En as [|En' IH]; intros k.
  - replace (2 * 0) with 0 by lia. replace (k + 0 + 1) with (S k) by lia.
    rewrite zPz, zLan.
    destruct (head0_t5_t4 b ((T3 ^^ k) *> [S0; S1; S0; S1] *> b0)) as [l' hl'].
    eapply PipeL_mk0; [exact hl' |].
    intros r.
    eapply evstep_trans; [apply (unwind_noT2 b k ([S1; S0; S1] *> b0) r) |].
    eapply evstep_trans; [apply (step_c0_unwind_rem0 ((T2 ^^ k) *> T5 *> (T4 ^^ b) *> r)) |].
    rewrite !Str_app_assoc, zPsr. apply evstep_refl.
  - replace (S En') with (En' + 1) by lia.
    destruct (head0_t5_t4 b ((T3 ^^ k) *> (T2 ^^ (2 * (En' + 1))) *> [S0; S1; S0; S1] *> b0)) as [l' hl'].
    assert (H2e : (T2 ^^ (2 * (En' + 1))) *> [S0; S1; S0; S1] *> b0 =
                  T2 *> T2 *> (T2 ^^ (2 * En')) *> [S0; S1; S0; S1] *> b0).
    { replace (2 * (En' + 1)) with (2 + 2 * En') by lia.
      rewrite pow_add_blank, !zPsr, zPz, zLan. reflexivity. }
    destruct (head0_t2_t0 (2 * En') ([S1; S0; S1] *> b0)) as [lt hlt].
    assert (Hpull : Pull1
        ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> (T2 ^^ (2 * (En' + 1))) *> [S0; S1; S0; S1] *> b0)
        ((T5 ^^ b) *> T4 *> (T3 ^^ (k + 2)) *> (T2 ^^ (2 * En')) *> [S0; S1; S0; S1] *> b0)).
    { rewrite H2e.
      change ([S0; S1; S0; S1] *> b0) with (T0 *> [S1; S0; S1] *> b0).
      rewrite hlt. exact (pull1_base b k lt). }
    pose proof (IH (k + 2)) as Hnext.
    replace (k + 2 + 2 * En' + 1) with (k + 2 * (En' + 1) + 1) in Hnext by lia.
    exact (PipeL_mkS hl' Hpull Hnext).
Qed.

Lemma pipeL_base_c0_T2 (En b k : nat) :
  PipeL En ((T2 ^^ (k + 2 * En + 2)) ++ (T4 ^^ (b + 1)))
    ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> (T2 ^^ (2 * En)) *> T2 *> [S0; S1; S0; S1] *> b0).
Proof.
  revert k. induction En as [|En' IH]; intros k.
  - replace (2 * 0) with 0 by lia. replace (k + 0 + 2) with (S (k + 1)) by lia.
    rewrite zPz, zLan.
    destruct (head0_t5_t4 b ((T3 ^^ k) *> T2 *> [S0; S1; S0; S1] *> b0)) as [l' hl'].
    eapply PipeL_mk0; [exact hl' |].
    intros r.
    eapply evstep_trans; [apply (unwind_T2 b k ([S1; S0; S1] *> b0) r) |].
    eapply evstep_trans; [apply (step_c0_unwind_rem0 ((T2 ^^ (k + 1)) *> (T4 ^^ (b + 1)) *> r)) |].
    rewrite Str_app_assoc, zPsr. apply evstep_refl.
  - replace (S En') with (En' + 1) by lia.
    destruct (head0_t5_t4 b ((T3 ^^ k) *> (T2 ^^ (2 * (En' + 1))) *> T2 *> [S0; S1; S0; S1] *> b0)) as [l' hl'].
    assert (H2e : (T2 ^^ (2 * (En' + 1))) *> T2 *> [S0; S1; S0; S1] *> b0 =
                  T2 *> T2 *> (T2 ^^ (2 * En')) *> T2 *> [S0; S1; S0; S1] *> b0).
    { replace (2 * (En' + 1)) with (2 + 2 * En') by lia.
      rewrite pow_add_blank, !zPsr, zPz, zLan. reflexivity. }
    destruct (head0_t2_t0 (2 * En') ([S0; S1] *> [S0; S1; S0; S1] *> b0)) as [lt hlt].
    assert (Hpull : Pull1
        ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> (T2 ^^ (2 * (En' + 1))) *> T2 *> [S0; S1; S0; S1] *> b0)
        ((T5 ^^ b) *> T4 *> (T3 ^^ (k + 2)) *> (T2 ^^ (2 * En')) *> T2 *> [S0; S1; S0; S1] *> b0)).
    { rewrite H2e.
      change (T2 *> [S0; S1; S0; S1] *> b0) with (T0 *> [S0; S1] *> [S0; S1; S0; S1] *> b0).
      rewrite hlt. exact (pull1_base b k lt). }
    pose proof (IH (k + 2)) as Hnext.
    replace (k + 2 + 2 * En' + 2) with (k + 2 * (En' + 1) + 2) in Hnext by lia.
    exact (PipeL_mkS hl' Hpull Hnext).
Qed.

Lemma pipeL_eat_t4 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (n : nat) (hle : n <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (En - n) (R_out ++ (T4 ^^ n)) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T4 ^^ n) *> r)) -[ tm ]->* (([S1; S1] *> Lt') {{F}}> r).
Proof.
  revert En R_out Lt hle hp. induction n as [|n' IH]; intros En R_out Lt hle hp.
  - exists Lt. split.
    + replace (En - 0) with En by lia. rewrite zPz, app_nil_r. exact hp.
    + rewrite zPz, zLan. apply evstep_refl.
  - destruct En as [|En']; [lia |].
    replace (S En') with (En' + 1) in hp by lia.
    destruct (PipeL_pull hp) as [Lt1 [hpull hp1]].
    assert (H1 : (([S1; S1] *> Lt) {{F}}> ((T4 ^^ S n') *> r)) -[ tm ]->*
                 (([S1; S1] *> T5 *> Lt1) {{F}}> ((T4 ^^ n') *> r))).
    { rewrite zPsr. exact (pull1_t4 hpull ((T4 ^^ n') *> r)). }
    pose proof (pipeL_t5 1 hp1) as hp1'.
    rewrite list_pow_one, zP1 in hp1'.
    destruct (IH En' (R_out ++ T4) (T5 *> Lt1) ltac:(lia) hp1') as [Lt' [hp' hsteps]].
    exists Lt'. split.
    + replace (S En' - S n') with (En' - n') by lia.
      eapply pipeL_eqR; [| exact hp'].
      rewrite append_assoc. reflexivity.
    + exact (stepStar_trans H1 hsteps).
Qed.

Lemma pipeL_start_c0_h0 (m b0p : nat) (hle : b0p <= m) (r : Stream Sym) :
  exists Lt, PipeL (m - b0p) (((T2 ^^ (2 * m + 4)) ++ T5) ++ (T4 ^^ b0p)) Lt /\
    (b0 {{E}}> (T2 *> T0 *> T1 *> (T2 ^^ (2 * m + 1)) *> (T4 ^^ (b0p + 2)) *> r)) -[ tm ]->*
    (([S1; S1] *> Lt) {{F}}> r).
Proof.
  assert (Hpre : (b0 {{E}}> (T2 *> T0 *> T1 *> (T2 ^^ (2 * m + 1)) *> (T4 ^^ (b0p + 2)) *> r)) -[ tm ]->*
                 ((T2 *> T2 *> (T2 ^^ (2 * m)) *> [S0; S1; S0; S1] *> b0) {{C}}>
                   (T4 *> T4 *> (T4 ^^ b0p) *> r))).
  { eapply evstep_trans; [apply step_c0_prefix |].
    eapply evstep_trans; [apply rule_c0_t2 |].
    rewrite zPal. replace (S (2 * m + 1)) with (2 + 2 * m) by lia.
    replace (b0p + 2) with (2 + b0p) by lia.
    rewrite !pow_add_blank, !zPsr, !zPz, !zLan. apply evstep_refl. }
  destruct (head0_t2_t0 (2 * m) ([S1; S0; S1] *> b0)) as [lt hlt].
  assert (Hcap : ((T2 *> T2 *> (T2 ^^ (2 * m)) *> [S0; S1; S0; S1] *> b0) {{C}}>
                   (T4 *> T4 *> (T4 ^^ b0p) *> r)) -[ tm ]->*
                 (([S1; S1] *> T4 *> (T3 ^^ 3) *> (T2 ^^ (2 * m)) *> [S0; S1; S0; S1] *> b0) {{F}}>
                   ((T4 ^^ b0p) *> r))).
  { change ([S0; S1; S0; S1] *> b0) with (T0 *> [S1; S0; S1] *> b0).
    rewrite hlt. exact (step_c0_h0_cap lt ((T4 ^^ b0p) *> r)). }
  pose proof (pipeL_base_c0_noT2 m 0 3) as hbase.
  rewrite !zPz, zLan, app_nil_r in hbase.
  destruct (pipeL_eat_t4 b0p hle hbase r) as [Lt [hp heat]].
  exists Lt. split.
  - eapply pipeL_eqR; [| exact hp]. replace (3 + 2 * m + 1) with (2 * m + 4) by lia. reflexivity.
  - exact (stepStar_trans Hpre (stepStar_trans Hcap heat)).
Qed.

Lemma pipeL_start_c0_h1 (m b0q : nat) (hle : b0q <= m) (r : Stream Sym) :
  exists Lt, PipeL (m - b0q) ((T2 ^^ (2 * m + 5)) ++ (T4 ^^ (b0q + 1))) Lt /\
    (b0 {{E}}> (T2 *> T0 *> T1 *> (T2 ^^ (2 * m + 2)) *> T5 *> (T4 ^^ (b0q + 1)) *> r)) -[ tm ]->*
    (([S1; S1] *> Lt) {{F}}> r).
Proof.
  assert (Hpre : (b0 {{E}}> (T2 *> T0 *> T1 *> (T2 ^^ (2 * m + 2)) *> T5 *> (T4 ^^ (b0q + 1)) *> r)) -[ tm ]->*
                 ((T2 *> T2 *> (T2 ^^ (2 * m)) *> T2 *> [S0; S1; S0; S1] *> b0) {{C}}>
                   (T5 *> T4 *> (T4 ^^ b0q) *> r))).
  { eapply evstep_trans; [apply step_c0_prefix |].
    eapply evstep_trans; [apply rule_c0_t2 |].
    replace (2 * m + 2) with (2 + 2 * m) by lia. replace (b0q + 1) with (S b0q) by lia.
    rewrite pow_add_blank, !zPsr, zPz, zLan. apply evstep_refl. }
  destruct (head0_t2_t0 (2 * m) ([S0; S1] *> [S0; S1; S0; S1] *> b0)) as [lt hlt].
  assert (Hcap : ((T2 *> T2 *> (T2 ^^ (2 * m)) *> T2 *> [S0; S1; S0; S1] *> b0) {{C}}>
                   (T5 *> T4 *> (T4 ^^ b0q) *> r)) -[ tm ]->*
                 (([S1; S1] *> T4 *> (T3 ^^ 3) *> (T2 ^^ (2 * m)) *> T2 *> [S0; S1; S0; S1] *> b0) {{F}}>
                   ((T4 ^^ b0q) *> r))).
  { change (T2 *> [S0; S1; S0; S1] *> b0) with (T0 *> [S0; S1] *> [S0; S1; S0; S1] *> b0).
    rewrite hlt. exact (step_c0_h1_cap lt ((T4 ^^ b0q) *> r)). }
  pose proof (pipeL_base_c0_T2 m 0 3) as hbase.
  rewrite zPz, zLan in hbase.
  destruct (pipeL_eat_t4 b0q hle hbase r) as [Lt [hp heat]].
  exists Lt. split.
  - eapply pipeL_eqR; [| exact hp].
    replace (3 + 2 * m + 2) with (2 * m + 5) by lia.
    rewrite append_assoc, <- list_pow_add. replace (0 + 1 + b0q) with (b0q + 1) by lia. reflexivity.
  - exact (stepStar_trans Hpre (stepStar_trans Hcap heat)).
Qed.

Lemma pipeL_eat_t2_even {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m k : nat) (hle : m <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (En - m) R_out Lt' /\
      (([S1; S1] *> (T3 ^^ k) *> Lt) {{F}}> ((T2 ^^ (2 * m)) *> r)) -[ tm ]->*
      (([S1; S1] *> (T3 ^^ (k + 2 * m)) *> Lt') {{F}}> r).
Proof.
  revert En k Lt hle hp. induction m as [|m' IH]; intros En k Lt hle hp.
  - exists Lt. split.
    + replace (En - 0) with En by lia. exact hp.
    + replace (2 * 0) with 0 by lia. replace (k + 0) with k by lia.
      rewrite zPz, zLan. apply evstep_refl.
  - destruct En as [|En']; [lia |].
    replace (S En') with (En' + 1) in hp by lia.
    destruct (PipeL_head0 hp) as [l0 h0].
    destruct (PipeL_pull hp) as [Lt1 [hpull hp1]].
    destruct (PipeL_head0 hp1) as [l0' h0'].
    assert (H1 : (([S1; S1] *> (T3 ^^ k) *> Lt) {{F}}> ((T2 ^^ (2 * S m')) *> r)) -[ tm ]->*
                 (([S1; S1] *> (T3 ^^ (k + 2)) *> Lt1) {{F}}> ((T2 ^^ (2 * m')) *> r))).
    { replace (2 * S m') with (2 + 2 * m') by lia.
      rewrite pow_add_blank, !zPsr, zPz, zLan.
      exact (pull1_t3_t22 k h0 h0' hpull ((T2 ^^ (2 * m')) *> r)). }
    destruct (IH En' (k + 2) Lt1 ltac:(lia) hp1) as [Lt' [hp' hsteps]].
    exists Lt'. split.
    + replace (S En' - S m') with (En' - m') by lia. exact hp'.
    + replace (k + 2 * S m') with (k + 2 + 2 * m') by lia. exact (stepStar_trans H1 hsteps).
Qed.

Lemma pipeL_transp {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m b : nat) (hle : m + b + 2 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (En - (m + b + 2)) ((R_out ++ (T2 ^^ (2 * (m + 1)))) ++ (T4 ^^ (b + 1))) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ (2 * (m + 1))) *> (T4 ^^ (b + 1)) *> r)) -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> r).
Proof.
  destruct (pipeL_eat_t2_even (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (m + 1) 0 ltac:(lia) hp ((T4 ^^ (b + 1)) *> r)) as [Lt1 [hp1 h1]].
  rewrite zPz, zLan in h1. replace (0 + 2 * (m + 1)) with (2 * (m + 1)) in h1 by lia.
  assert (HE1 : En - (m + 1) = (En - (m + 2)) + 1) by lia.
  pose proof (pipeL_eqE HE1 hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
  assert (H2 : (([S1; S1] *> (T3 ^^ (2 * (m + 1))) *> Lt1) {{F}}> ((T4 ^^ (b + 1)) *> r)) -[ tm ]->*
               (([S1; S1] *> T4 *> (T3 ^^ (2 * m + 1)) *> T2 *> Lt2) {{F}}> ((T4 ^^ b) *> r))).
  { replace (2 * (m + 1)) with ((2 * m + 1) + 1) by lia.
    replace (b + 1) with (S b) by lia. rewrite (zPsr T4).
    exact (pull1_t3_t4 (2 * m + 1) hl1 hpull ((T4 ^^ b) *> r)). }
  pose proof (pipeL_T2_blk 0 (2 * m + 1) hp2) as hp2blk.
  rewrite zPz, zLan in hp2blk.
  destruct (pipeL_eat_t4 (En := ltac:(match type of hp2blk with PipeL ?e _ _ => exact e end)) b ltac:(lia) hp2blk r) as [Lt3 [hp3 h3]].
  exists Lt3. split.
  - eapply pipeL_eqE; [| eapply pipeL_eqR; [| exact hp3]].
    + lia.
    + replace (2 * m + 1 + 1) with (2 * (m + 1)) by lia.
      rewrite append_assoc, <- list_pow_add. replace (0 + 1 + b) with (b + 1) by lia. reflexivity.
  - exact (stepStar_trans h1 (stepStar_trans H2 h3)).
Qed.

Lemma pipeL_transpRun {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m b rep : nat) (hle : rep * (m + b + 2) <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (En - rep * (m + b + 2))
        (R_out ++ (((T2 ^^ (2 * (m + 1))) ++ (T4 ^^ (b + 1))) ^^ rep)) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((((T2 ^^ (2 * (m + 1))) ++ (T4 ^^ (b + 1))) ^^ rep) *> r)) -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> r).
Proof.
  revert En R_out Lt hle hp. induction rep as [|rep' IH]; intros En R_out Lt hle hp.
  - exists Lt. split.
    + replace (En - 0 * (m + b + 2)) with En by lia. rewrite zPz, app_nil_r. exact hp.
    + rewrite zPz, zLan. apply evstep_refl.
  - assert (Hle1 : m + b + 2 <= En) by nia.
    destruct (pipeL_transp m b Hle1 hp
      ((((T2 ^^ (2 * (m + 1))) ++ (T4 ^^ (b + 1))) ^^ rep') *> r)) as [Lt1 [hp1 h1]].
    destruct (IH (En - (m + b + 2)) _ Lt1 ltac:(nia) hp1) as [Lt2 [hp2 h2]].
    exists Lt2. split.
    + eapply pipeL_eqE; [| eapply pipeL_eqR; [| exact hp2]].
      * nia.
      * simpl lpow. rewrite !append_assoc. reflexivity.
    + rewrite zPsr, Str_app_assoc. exact (stepStar_trans h1 h2).
Qed.

Lemma pipeL_odd_h0_pass {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m b : nat) (hle : m + b + 1 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (En - (m + b + 1)) (((R_out ++ (T2 ^^ (2 * m + 1))) ++ T5) ++ (T4 ^^ b)) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ (2 * m + 1)) *> (T4 ^^ (b + 1)) *> r)) -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> r).
Proof.
  destruct (pipeL_eat_t2_even (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) m 0 ltac:(lia) hp (T2 *> T4 *> (T4 ^^ b) *> r)) as [Lt1 [hp1 h1]].
  rewrite zPz, zLan in h1. replace (0 + 2 * m) with (2 * m) in h1 by lia.
  assert (HE1 : En - m = (En - (m + 1)) + 1) by lia.
  pose proof (pipeL_eqE HE1 hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
  pose proof (pull1_t3_t2_t4 (2 * m) hl1 hpull ((T4 ^^ b) *> r)) as h2.
  pose proof (pipeL_noT2_blk 0 (2 * m + 1) hp2) as hp2blk.
  rewrite !zPz, zLan, app_nil_r in hp2blk.
  destruct (pipeL_eat_t4 (En := ltac:(match type of hp2blk with PipeL ?e _ _ => exact e end)) b ltac:(lia) hp2blk r) as [Lt3 [hp3 h3]].
  exists Lt3. split.
  - apply (pipeL_eqER hp3); [lia  | reflexivity].
  - rewrite pow_add_blank, zP1. replace (b + 1) with (S b) by lia. rewrite zPsr.
    exact (stepStar_trans h1 (stepStar_trans h2 h3)).
Qed.

Lemma pipeL_odd_h0_split {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m b : nat) (hge : m + 1 <= En) (hlt : En + 1 <= m + b) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    (([S1; S1] *> Lt) {{F}}> ((T2 ^^ (2 * m + 1)) *> (T4 ^^ b) *> r)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *>
      (((((R_out ++ (T2 ^^ (2 * m + 1))) ++ T5) ++ (T4 ^^ (En - m - 1))) ++ T3) ++ (T4 ^^ (m + b - En - 1))) *> r)).
Proof.
  assert (Hb : (T4 ^^ b) *> r =
               T4 *> (T4 ^^ (En - m - 1)) *> T4 *> (T4 ^^ (m + b - En - 1)) *> r).
  { replace b with (1 + ((En - m - 1) + (1 + (m + b - En - 1)))) at 1 by lia.
    rewrite !pow_add_blank, !zP1. reflexivity. }
  rewrite pow_add_blank, zP1, Hb.
  destruct (pipeL_eat_t2_even (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) m 0 ltac:(lia) hp
    (T2 *> T4 *> (T4 ^^ (En - m - 1)) *> T4 *> (T4 ^^ (m + b - En - 1)) *> r)) as [Lt1 [hp1 h1]].
  rewrite zPz, zLan in h1. replace (0 + 2 * m) with (2 * m) in h1 by lia.
  assert (HE1 : En - m = (En - m - 1) + 1) by lia.
  pose proof (pipeL_eqE HE1 hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
  pose proof (pull1_t3_t2_t4 (2 * m) hl1 hpull
    ((T4 ^^ (En - m - 1)) *> T4 *> (T4 ^^ (m + b - En - 1)) *> r)) as h2.
  pose proof (pipeL_noT2_blk 0 (2 * m + 1) hp2) as hp2blk.
  rewrite !zPz, zLan, app_nil_r in hp2blk.
  destruct (pipeL_eat_t4 (En - m - 1) (Nat.le_refl _) hp2blk
    (T4 *> (T4 ^^ (m + b - En - 1)) *> r)) as [Lt3 [hp3 h3]].
  replace (En - m - 1 - (En - m - 1)) with 0 in hp3 by lia.
  eapply evstep_trans; [exact h1 |].
  eapply evstep_trans; [exact h2 |].
  eapply evstep_trans; [exact h3 |].
  change (T4 *> (T4 ^^ (m + b - En - 1)) *> r) with ([S0; S1] *> T3 *> (T4 ^^ (m + b - En - 1)) *> r).
  eapply evstep_trans; [apply (PipeL_unwind hp3) |].
  rewrite !Str_app_assoc. apply evstep_refl.
Qed.

Lemma pipeL_asplit_create {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (a : nat) (hE : 1 <= En) (ha : 2 * En + 1 <= a) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    (([S1; S1] *> Lt) {{F}}> ((T2 ^^ a) *> r)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *>
      (((R_out ++ (T2 ^^ (2 * En - 1))) ++ T0) ++ (T2 ^^ (a - 2 * En))) *> r)).
Proof.
  assert (Htail : (T2 ^^ (a - 2 * En)) *> r = T2 *> (T2 ^^ (a - 2 * En - 1)) *> r).
  { replace (a - 2 * En) with (S (a - 2 * En - 1)) at 1 by lia. rewrite zPsr. reflexivity. }
  assert (HR : (T2 ^^ a) *> r = (T2 ^^ (2 * En)) *> T2 *> (T2 ^^ (a - 2 * En - 1)) *> r).
  { replace a with (2 * En + (a - 2 * En)) at 1 by lia. rewrite pow_add_blank, Htail. reflexivity. }
  rewrite HR.
  destruct (pipeL_eat_t2_even En 0 (Nat.le_refl _) hp (T2 *> (T2 ^^ (a - 2 * En - 1)) *> r)) as [Lt1 [hp1 h1]].
  rewrite zPz, zLan in h1. replace (0 + 2 * En) with (2 * En) in h1 by lia.
  replace (En - En) with 0 in hp1 by lia.
  destruct (PipeL_head0 hp1) as [l1 hl1].
  assert (H2 : (([S1; S1] *> (T3 ^^ (2 * En)) *> Lt1) {{F}}> (T2 *> (T2 ^^ (a - 2 * En - 1)) *> r)) -[ tm ]->*
               (((T3 ^^ (2 * En)) *> Lt1) {{E}}> (T0 *> T0 *> T2 *> (T2 ^^ (a - 2 * En - 1)) *> r))).
  { assert (HT3 : (T3 ^^ (2 * En)) *> Lt1 = T3 *> (T3 ^^ (2 * En - 1)) *> Lt1).
    { replace (2 * En) with (S (2 * En - 1)) at 1 by lia. apply zPsr. }
    rewrite HT3.
    exact (step_8A_head ([S1; S1] *> (T3 ^^ (2 * En - 1)) *> Lt1) ([S0; S1] *> (T2 ^^ (a - 2 * En - 1)) *> r)). }
  assert (H3 : (((T3 ^^ (2 * En)) *> Lt1) {{E}}> (T0 *> T0 *> T2 *> (T2 ^^ (a - 2 * En - 1)) *> r)) -[ tm ]->*
               (([S1; S1] *> Lt1) {{F}}> ([S0; S1] *> (T2 ^^ (2 * En - 1)) *> T0 *> T2 *> (T2 ^^ (a - 2 * En - 1)) *> r))).
  { replace (2 * En) with ((2 * En - 1) + 1) at 1 by lia. rewrite hl1.
    exact (rule_E_t3_to_Q5 (2 * En - 1) l1 (T0 *> T2 *> (T2 ^^ (a - 2 * En - 1)) *> r)). }
  eapply evstep_trans; [exact h1 |].
  eapply evstep_trans; [exact H2 |].
  eapply evstep_trans; [exact H3 |].
  eapply evstep_trans; [apply (PipeL_unwind hp1) |].
  rewrite !Str_app_assoc, Htail. apply evstep_refl.
Qed.

Lemma pipeL_h1_enter_even {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m b : nat) (hle : m + 1 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (En - m - 1) ((R_out ++ (T2 ^^ (2 * m + 1))) ++ (T4 ^^ (b + 1))) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ (2 * m)) *> T5 *> (T4 ^^ (b + 1)) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  destruct (pipeL_eat_t2_even (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) m 0 ltac:(lia) hp (T5 *> (T4 ^^ (b + 1)) *> r)) as [Lt1 [hp1 h1]].
  rewrite zPz, zLan in h1. replace (0 + 2 * m) with (2 * m) in h1 by lia.
  assert (HE1 : En - m = (En - m - 1) + 1) by lia.
  pose proof (pipeL_eqE HE1 hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
  pose proof (pull1_t3_t5 (2 * m) hl1 hpull ((T4 ^^ (b + 1)) *> r)) as h2.
  assert (H3 : (([S1] *> (T3 ^^ (2 * m + 1)) *> T2 *> Lt2) {{A}}> ((T4 ^^ (b + 1)) *> r)) -[ tm ]->*
               (([S1] *> T2 *> (T5 ^^ b) *> T4 *> (T3 ^^ (2 * m)) *> T2 *> Lt2) {{A}}> r)).
  { replace (2 * m + 1) with (S (2 * m)) by lia. replace (b + 1) with (S b) by lia.
    rewrite !zPsr.
    eapply evstep_trans; [apply step_q0_t4_first |].
    apply rule_q0_t4_next. }
  exists ((T5 ^^ b) *> T4 *> (T3 ^^ (2 * m)) *> T2 *> Lt2). split.
  - exact (pipeL_T2_blk b (2 * m) hp2).
  - exact (stepStar_trans h1 (stepStar_trans h2 H3)).
Qed.

Lemma pipeL_h1_enter_odd {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m b : nat) (hle : m + 1 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (En - m - 1) (((R_out ++ (T2 ^^ (2 * m + 2))) ++ T5) ++ (T4 ^^ b)) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ (2 * m + 1)) *> T5 *> (T4 ^^ (b + 1)) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  rewrite pow_add_blank, zP1.
  destruct (pipeL_eat_t2_even (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) m 0 ltac:(lia) hp (T2 *> T5 *> (T4 ^^ (b + 1)) *> r)) as [Lt1 [hp1 h1]].
  rewrite zPz, zLan in h1. replace (0 + 2 * m) with (2 * m) in h1 by lia.
  assert (HE1 : En - m = (En - m - 1) + 1) by lia.
  pose proof (pipeL_eqE HE1 hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
  pose proof (pull1_t3_t2_t5 (2 * m) hl1 hpull ((T4 ^^ (b + 1)) *> r)) as h2.
  assert (H3 : (([S1] *> (T3 ^^ (2 * m + 3)) *> Lt2) {{A}}> ((T4 ^^ (b + 1)) *> r)) -[ tm ]->*
               (([S1] *> T2 *> (T5 ^^ b) *> T4 *> (T3 ^^ (2 * m + 2)) *> Lt2) {{A}}> r)).
  { replace (2 * m + 3) with (S (2 * m + 2)) by lia. replace (b + 1) with (S b) by lia.
    rewrite !zPsr.
    eapply evstep_trans; [apply step_q0_t4_first |].
    apply rule_q0_t4_next. }
  exists ((T5 ^^ b) *> T4 *> (T3 ^^ (2 * m + 2)) *> Lt2). split.
  - exact (pipeL_noT2_blk b (2 * m + 2) hp2).
  - exact (stepStar_trans h1 (stepStar_trans h2 H3)).
Qed.

Lemma pipeL_mid_h0 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (a b : nat) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL En ((R_out ++ (T2 ^^ (a + 1))) ++ (T4 ^^ (b + 1))) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> ((T2 ^^ (a + 1)) *> (T4 ^^ (b + 1)) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  exists ((T5 ^^ b) *> T4 *> (T3 ^^ a) *> T2 *> Lt).
  split; [exact (pipeL_T2_blk b a hp) | exact (mid_cell_h0 a b Lt r)].
Qed.

Lemma pipeL_mid_h1 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (a b : nat) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL En (((R_out ++ (T2 ^^ a)) ++ T5) ++ (T4 ^^ b)) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> ((T2 ^^ a) *> T5 *> (T4 ^^ b) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  destruct (PipeL_head0 hp) as [l0 h0].
  exists ((T5 ^^ b) *> T4 *> (T3 ^^ a) *> Lt). split.
  - exact (pipeL_noT2_blk b a hp).
  - rewrite h0. exact (mid_cell_h1 a b l0 r).
Qed.

Lemma pipeL_mid_transpRun {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (a b rep : nat) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL En (R_out ++ (((T2 ^^ (a + 1)) ++ (T4 ^^ (b + 1))) ^^ rep)) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> ((((T2 ^^ (a + 1)) ++ (T4 ^^ (b + 1))) ^^ rep) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  revert R_out Lt hp. induction rep as [|rep' IH]; intros R_out Lt hp.
  - exists Lt. split.
    + rewrite zPz, app_nil_r. exact hp.
    + rewrite zPz, zLan. apply evstep_refl.
  - destruct (pipeL_mid_h0 a b hp ((((T2 ^^ (a + 1)) ++ (T4 ^^ (b + 1))) ^^ rep') *> r)) as [Lt1 [hp1 h1]].
    destruct (IH _ Lt1 hp1) as [Lt2 [hp2 h2]].
    exists Lt2. split.
    + eapply pipeL_eqR; [| exact hp2]. simpl lpow. rewrite !append_assoc. reflexivity.
    + rewrite zPsr, Str_app_assoc. exact (stepStar_trans h1 h2).
Qed.

Lemma pipeL_mid_cell {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (a : nat) (h : bool) (b : nat) (hok : h = true \/ (1 <= a /\ 1 <= b))
    (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL En (R_out ++ (((T2 ^^ a) ++ (if h then T5 else [])) ++ (T4 ^^ b))) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> ((((T2 ^^ a) ++ (if h then T5 else [])) ++ (T4 ^^ b)) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  destruct h.
  - destruct (pipeL_mid_h1 a b hp r) as [Lt' [hp' hs]].
    exists Lt'. split.
    + eapply pipeL_eqR; [| exact hp']. rewrite !append_assoc. reflexivity.
    + rewrite !Str_app_assoc. exact hs.
  - destruct hok as [Hfalse | [ha hb]]; [discriminate |].
    replace a with ((a - 1) + 1) by lia. replace b with ((b - 1) + 1) by lia.
    destruct (pipeL_mid_h0 (a - 1) (b - 1) hp r) as [Lt' [hp' hs]].
    exists Lt'. split.
    + eapply pipeL_eqR; [| exact hp']. rewrite app_nil_r, !append_assoc. reflexivity.
    + rewrite app_nil_r, !Str_app_assoc. exact hs.
Qed.

Lemma pipeL_mid_pairRun {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (a1 : nat) (h1 : bool) (b1 a2 : nat) (h2 : bool) (b2 rep : nat)
    (hok1 : h1 = true \/ (1 <= a1 /\ 1 <= b1)) (hok2 : h2 = true \/ (1 <= a2 /\ 1 <= b2))
    (hp : PipeL En R_out Lt) (r : Stream Sym) :
    let w := (((T2 ^^ a1) ++ (if h1 then T5 else [])) ++ (T4 ^^ b1)) ++
             (((T2 ^^ a2) ++ (if h2 then T5 else [])) ++ (T4 ^^ b2)) in
    exists Lt', PipeL En (R_out ++ (w ^^ rep)) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> ((w ^^ rep) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  intros w. revert R_out Lt hp. induction rep as [|rep' IH]; intros R_out Lt hp.
  - exists Lt. split.
    + rewrite zPz, app_nil_r. exact hp.
    + rewrite zPz, zLan. apply evstep_refl.
  - destruct (pipeL_mid_cell a1 h1 b1 hok1 hp
      ((((T2 ^^ a2) ++ (if h2 then T5 else [])) ++ (T4 ^^ b2)) *> (w ^^ rep') *> r)) as [Lt1 [hp1 hs1]].
    destruct (pipeL_mid_cell a2 h2 b2 hok2 hp1 ((w ^^ rep') *> r)) as [Lt2 [hp2 hs2]].
    destruct (IH _ Lt2 hp2) as [Lt3 [hp3 hs3]].
    exists Lt3. split.
    + eapply pipeL_eqR; [| exact hp3]. unfold w. simpl lpow. rewrite !append_assoc. reflexivity.
    + assert (Hw : (w ^^ S rep') *> r =
        (((T2 ^^ a1) ++ (if h1 then T5 else [])) ++ (T4 ^^ b1)) *>
        (((T2 ^^ a2) ++ (if h2 then T5 else [])) ++ (T4 ^^ b2)) *> (w ^^ rep') *> r)
        by (rewrite zPsr; unfold w at 1; apply Str_app_assoc).
      rewrite Hw.
      exact (stepStar_trans hs1 (stepStar_trans hs2 hs3)).
Qed.

Lemma pipeL_shift_t3_loop {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (p n s1 : nat) (hnE : n <= En) (hns : n <= s1) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (En - n) R_out Lt' /\
      (([S1; S1] *> Lt) {{F}}> ([S0; S1] *> (T4 ^^ p) *> T3 *> (T4 ^^ s1) *> r)) -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> ([S0; S1] *> (T4 ^^ (p + n)) *> T3 *> (T4 ^^ (s1 - n)) *> r)).
Proof.
  revert En p s1 Lt hnE hns hp. induction n as [|n' IH]; intros En p s1 Lt hnE hns hp.
  - exists Lt. split.
    + replace (En - 0) with En by lia. exact hp.
    + replace (p + 0) with p by lia. replace (s1 - 0) with s1 by lia. apply evstep_refl.
  - destruct En as [|En']; [lia |].
    destruct s1 as [|s1']; [lia |].
    replace (S En') with (En' + 1) in hp by lia.
    destruct (PipeL_pull hp) as [Lt1 [hpull hp1]].
    destruct (PipeL_head0 hp1) as [l1 hl1].
    pose proof (rt5_cons_t4 p (rt5_wall1 ((T4 ^^ s1') *> r))) as hrt.
    pose proof (pull1_rt5 hl1 hpull hrt) as h1.
    rewrite !Str_app_assoc, <- (zPsr T4 s1'), zPal in h1.
    destruct (IH En' (S p) s1' Lt1 ltac:(lia) ltac:(lia) hp1) as [Lt' [hp' h2]].
    exists Lt'. split.
    + replace (S En' - S n') with (En' - n') by lia. exact hp'.
    + replace (p + S n') with (S p + n') by lia. replace (S s1' - S n') with (s1' - n') by lia.
      exact (stepStar_trans h1 h2).
Qed.

Lemma pipeL_dump_wall1 {E_rem : nat} {R_out : list Sym} {Lt : Stream Sym}
    (s1 : nat) (hle : E_rem + 1 <= s1) (hp : PipeL E_rem R_out Lt) (r : Stream Sym) :
    (([S1] *> T2 *> Lt) {{A}}> (T3 *> (T4 ^^ s1) *> r)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *>
      (((R_out ++ (T4 ^^ (E_rem + 1))) ++ T3) ++ (T4 ^^ (s1 - (E_rem + 1)))) *> r)).
Proof.
  destruct s1 as [|s1']; [lia |].
  destruct (PipeL_head0 hp) as [l0 h0].
  assert (H1 : (([S1] *> T2 *> Lt) {{A}}> (T3 *> (T4 ^^ S s1') *> r)) -[ tm ]->*
               (([S1; S1] *> Lt) {{F}}> ([S0; S1] *> (T4 ^^ 1) *> T3 *> (T4 ^^ s1') *> r))).
  { rewrite h0, zPsr, zP1.
    pose proof (q0_t2_rt5 0 (rt5_wall1 ((T4 ^^ s1') *> r)) l0) as hq.
    rewrite !zPz, !zLan, !Str_app_assoc in hq. exact hq. }
  destruct (pipeL_shift_t3_loop (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) 1 E_rem s1' (Nat.le_refl _) ltac:(lia) hp r) as [Lt' [hp' h2]].
  replace (E_rem - E_rem) with 0 in hp' by lia.
  eapply evstep_trans; [exact H1 |].
  eapply evstep_trans; [exact h2 |].
  eapply evstep_trans; [apply (PipeL_unwind hp') |].
  replace (1 + E_rem) with (E_rem + 1) by lia.
  replace (s1' - E_rem) with (S s1' - (E_rem + 1)) by lia.
  rewrite !Str_app_assoc. apply evstep_refl.
Qed.

Lemma pipeL_absorb_2seg {E_rem : nat} {R_out : list Sym} {Lt : Stream Sym}
    (s1 : nat) (hle : s1 + 1 <= E_rem) (hp : PipeL E_rem R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (E_rem - s1) (R_out ++ (T4 ^^ (s1 + 1))) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> (T3 *> (T4 ^^ s1) *> r)) -[ tm ]->* (([S1; S1] *> Lt') {{F}}> r).
Proof.
  destruct s1 as [|s1'].
  - rewrite zPz, zLan. replace (E_rem - 0) with E_rem by lia.
    pose proof (pipeL_t5 1 hp) as hp'. rewrite zP1 in hp'.
    exists (T5 *> Lt). split; [exact hp' | apply step_punch_t3].
  - destruct (PipeL_head0 hp) as [l0 h0].
    assert (H1 : (([S1] *> T2 *> Lt) {{A}}> (T3 *> (T4 ^^ S s1') *> r)) -[ tm ]->*
                 (([S1; S1] *> Lt) {{F}}> ([S0; S1] *> (T4 ^^ 1) *> T3 *> (T4 ^^ s1') *> r))).
    { rewrite h0, zPsr, zP1.
      pose proof (q0_t2_rt5 0 (rt5_wall1 ((T4 ^^ s1') *> r)) l0) as hq.
      rewrite !zPz, !zLan, !Str_app_assoc in hq. exact hq. }
    destruct (pipeL_shift_t3_loop (En := E_rem) 1 s1' s1' ltac:(lia) (Nat.le_refl _) hp r) as [Lt1 [hp1 h2]].
    replace (s1' - s1') with 0 in h2 by lia. rewrite zPz, zLan in h2.
    replace (1 + s1') with (s1' + 1) in h2 by lia.
    assert (HE1 : E_rem - s1' = (E_rem - S s1') + 1) by lia.
    pose proof (pipeL_eqE HE1 hp1) as hp1'.
    destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
    assert (H3 : (([S1; S1] *> Lt1) {{F}}> ([S0; S1] *> (T4 ^^ (s1' + 1)) *> T3 *> r)) -[ tm ]->*
                 (([S1] *> T2 *> Lt2) {{A}}> ((T4 ^^ (s1' + 1)) *> T3 *> r))).
    { change ([S0; S1] *> (T4 ^^ (s1' + 1)) *> T3 *> r) with (T0 *> [S1] *> (T4 ^^ (s1' + 1)) *> T3 *> r).
      eapply evstep_trans; [apply hpull |].
      apply post_pull_q0. }
    assert (H4 : (([S1] *> T2 *> Lt2) {{A}}> ((T4 ^^ (s1' + 1)) *> T3 *> r)) -[ tm ]->*
                 (([S1; S1] *> (T5 ^^ (S s1' + 1)) *> Lt2) {{F}}> r)).
    { eapply evstep_trans; [apply rule_q0_t4_next |].
      eapply evstep_trans; [apply step_punch_t3 |].
      replace (S s1' + 1) with (S (s1' + 1)) by lia. rewrite zPsr. apply evstep_refl. }
    exists ((T5 ^^ (S s1' + 1)) *> Lt2). split.
    + exact (pipeL_t5 (S s1' + 1) hp2).
    + exact (stepStar_trans H1 (stepStar_trans h2 (stepStar_trans H3 H4))).
Qed.

Lemma pipeL_grow_end_loop {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (p n : nat) (hnE : n <= En) (hp : PipeL En R_out Lt) :
    exists Lt', PipeL (En - n) R_out Lt' /\
      (([S1; S1] *> Lt) {{F}}> ([S0; S1] *> (T4 ^^ p) *> [S0; S1; S0; S1] *> b0)) -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> ([S0; S1] *> (T4 ^^ (p + n)) *> [S0; S1; S0; S1] *> b0)).
Proof.
  revert En p Lt hnE hp. induction n as [|n' IH]; intros En p Lt hnE hp.
  - exists Lt. split.
    + replace (En - 0) with En by lia. exact hp.
    + replace (p + 0) with p by lia. apply evstep_refl.
  - destruct En as [|En']; [lia |].
    replace (S En') with (En' + 1) in hp by lia.
    destruct (PipeL_pull hp) as [Lt1 [hpull hp1]].
    destruct (PipeL_head0 hp1) as [l1 hl1].
    pose proof (rt5_cons_t4 p rt5_wall2) as hrt.
    pose proof (pull1_rt5 hl1 hpull hrt) as h1.
    rewrite !Str_app_assoc, zPal in h1.
    destruct (IH En' (S p) Lt1 ltac:(lia) hp1) as [Lt' [hp' h2]].
    exists Lt'. split.
    + replace (S En' - S n') with (En' - n') by lia. exact hp'.
    + replace (p + S n') with (S p + n') by lia. exact (stepStar_trans h1 h2).
Qed.

Lemma pipeL_dump_wall2 {E_rem : nat} {R_out : list Sym} {Lt : Stream Sym}
    (hp : PipeL E_rem R_out Lt) :
    (([S1] *> T2 *> Lt) {{A}}> ([S0; S1; S0; S1] *> b0)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *> (R_out ++ (T4 ^^ (E_rem + 1))) *> [S0; S1; S0; S1] *> b0)).
Proof.
  destruct (PipeL_head0 hp) as [l0 h0].
  assert (H1 : (([S1] *> T2 *> Lt) {{A}}> ([S0; S1; S0; S1] *> b0)) -[ tm ]->*
               (([S1; S1] *> Lt) {{F}}> ([S0; S1] *> (T4 ^^ 1) *> [S0; S1; S0; S1] *> b0))).
  { rewrite h0, zP1.
    pose proof (q0_t2_rt5 0 rt5_wall2 l0) as hq.
    rewrite !zPz, !zLan, !Str_app_assoc in hq. exact hq. }
  destruct (pipeL_grow_end_loop 1 E_rem (Nat.le_refl _) hp) as [Lt' [hp' h2]].
  replace (E_rem - E_rem) with 0 in hp' by lia.
  eapply evstep_trans; [exact H1 |].
  eapply evstep_trans; [exact h2 |].
  eapply evstep_trans; [apply (PipeL_unwind hp') |].
  replace (1 + E_rem) with (E_rem + 1) by lia.
  rewrite Str_app_assoc. apply evstep_refl.
Qed.

Lemma pipeL_shift_asplit_loop {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (p n aR : nat) (hnE : n <= En) (hna : 2 * n <= aR) (hp : PipeL En R_out Lt) (tail : Stream Sym) :
    exists Lt', PipeL (En - n) R_out Lt' /\
      (([S1; S1] *> Lt) {{F}}> ([S0; S1] *> (T2 ^^ p) *> T0 *> (T2 ^^ aR) *> T0 *> tail)) -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> ([S0; S1] *> (T2 ^^ (p + 2 * n)) *> T0 *> (T2 ^^ (aR - 2 * n)) *> T0 *> tail)).
Proof.
  revert En p aR Lt hnE hna hp. induction n as [|n' IH]; intros En p aR Lt hnE hna hp.
  - exists Lt. split.
    + replace (En - 0) with En by lia. exact hp.
    + replace (p + 2 * 0) with p by lia. replace (aR - 2 * 0) with aR by lia. apply evstep_refl.
  - destruct En as [|En']; [lia |].
    replace (S En') with (En' + 1) in hp by lia.
    destruct (PipeL_pull hp) as [Lt1 [hpull hp1]].
    destruct (PipeL_head0 hp1) as [l1 hl1].
    destruct (head0_t2_t0 (aR - 2) tail) as [lt hlt].
    pose proof (rt5_cons_t2 p (rt5_wall3 lt)) as hrt.
    pose proof (pull1_rt5 hl1 hpull hrt) as h1.
    rewrite !Str_app_assoc, <- hlt, !zPal in h1.
    assert (HaR : T2 *> T2 *> (T2 ^^ (aR - 2)) *> T0 *> tail = (T2 ^^ aR) *> T0 *> tail).
    { replace aR with (2 + (aR - 2)) at 2 by lia. rewrite pow_add_blank, !zPsr, zPz, zLan. reflexivity. }
    rewrite HaR in h1.
    destruct (IH En' (S (S p)) (aR - 2) Lt1 ltac:(lia) ltac:(lia) hp1) as [Lt' [hp' h2]].
    exists Lt'. split.
    + replace (S En' - S n') with (En' - n') by lia. exact hp'.
    + replace (p + 2 * S n') with (S (S p) + 2 * n') by lia.
      replace (aR - 2 * S n') with (aR - 2 - 2 * n') by lia.
      exact (stepStar_trans h1 h2).
Qed.

Lemma pipeL_dump_wall3 {E_rem : nat} {R_out : list Sym} {Lt : Stream Sym}
    (aL aR : nat) (hle : 2 * (E_rem + 1) <= aR) (hp : PipeL E_rem R_out Lt) (tail : Stream Sym) :
    (([S1] *> T2 *> Lt) {{A}}> ((T2 ^^ aL) *> T0 *> (T2 ^^ aR) *> T0 *> tail)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *>
      (((R_out ++ (T2 ^^ (aL + 2 * (E_rem + 1)))) ++ T0) ++ (T2 ^^ (aR - 2 * (E_rem + 1)))) *> T0 *> tail)).
Proof.
  destruct (PipeL_head0 hp) as [l0 h0].
  destruct (head0_t2_t0 (aR - 2) tail) as [lt hlt].
  eapply evstep_trans; [apply rule_q0_t2 |].
  assert (H1 : (([S1] *> (T3 ^^ aL) *> T2 *> Lt) {{A}}> (T0 *> (T2 ^^ aR) *> T0 *> tail)) -[ tm ]->*
               (([S1; S1] *> Lt) {{F}}> ([S0; S1] *> (T2 ^^ (aL + 2)) *> T0 *> (T2 ^^ (aR - 2)) *> T0 *> tail))).
  { rewrite h0.
    pose proof (q0_t2_rt5 aL (rt5_wall3 lt) l0) as hq.
    rewrite !Str_app_assoc, <- hlt, !zPal in hq.
    assert (HaR : (T2 ^^ aR) *> T0 *> tail = (T2 ^^ (2 + (aR - 2))) *> T0 *> tail)
      by (replace aR with (2 + (aR - 2)) at 1 by lia; reflexivity).
    rewrite HaR.
    rewrite pow_add_blank, !zPsr, zPz, zLan.
    replace (aL + 2) with (S (S aL)) by lia. exact hq. }
  eapply evstep_trans; [exact H1 |].
  destruct (pipeL_shift_asplit_loop (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (aL + 2) E_rem (aR - 2) (Nat.le_refl _) ltac:(lia) hp tail) as [Lt' [hp' h2]].
  replace (E_rem - E_rem) with 0 in hp' by lia.
  eapply evstep_trans; [exact h2 |].
  eapply evstep_trans; [apply (PipeL_unwind hp') |].
  replace (aL + 2 + 2 * E_rem) with (aL + 2 * (E_rem + 1)) by lia.
  replace (aR - 2 - 2 * E_rem) with (aR - 2 * (E_rem + 1)) by lia.
  rewrite !Str_app_assoc. apply evstep_refl.
Qed.

Lemma pipeL_asplit_prep {E_rem : nat} {R_out : list Sym} {Lt : Stream Sym}
    (aL q_as aR_odd : nat) (hle : q_as <= E_rem) (hp : PipeL E_rem R_out Lt) (tail : Stream Sym) :
    exists Lt', PipeL (E_rem - q_as) R_out Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> ((T2 ^^ aL) *> T0 *> (T2 ^^ (2 * q_as + aR_odd)) *> T0 *> tail)) -[ tm ]->*
      (([S1] *> (T3 ^^ (aL + 2 * q_as)) *> T2 *> Lt') {{A}}> (T0 *> (T2 ^^ aR_odd) *> T0 *> tail)).
Proof.
  destruct q_as as [|q'].
  - exists Lt. split.
    + replace (E_rem - 0) with E_rem by lia. exact hp.
    + replace (2 * 0 + aR_odd) with aR_odd by lia. replace (aL + 2 * 0) with aL by lia.
      apply rule_q0_t2.
  - destruct (PipeL_head0 hp) as [l0 h0].
    destruct (head0_t2_t0 (2 * q' + aR_odd) tail) as [lt hlt].
    pose proof (rule_q0_t2 aL (T2 *> Lt) (T0 *> (T2 ^^ (2 * S q' + aR_odd)) *> T0 *> tail)) as h0_sw.
    assert (H1 : (([S1] *> (T3 ^^ aL) *> T2 *> Lt) {{A}}> (T0 *> (T2 ^^ (2 * S q' + aR_odd)) *> T0 *> tail)) -[ tm ]->*
                 (([S1; S1] *> Lt) {{F}}> ([S0; S1] *> (T2 ^^ (aL + 2)) *> T0 *> (T2 ^^ (2 * q' + aR_odd)) *> T0 *> tail))).
    { rewrite h0.
      pose proof (q0_t2_rt5 aL (rt5_wall3 lt) l0) as hq.
      rewrite !Str_app_assoc, <- hlt, !zPal in hq.
      replace (2 * S q' + aR_odd) with (2 + (2 * q' + aR_odd)) by lia.
      rewrite pow_add_blank, !zPsr, zPz, zLan.
      replace (aL + 2) with (S (S aL)) by lia. exact hq. }
    destruct (pipeL_shift_asplit_loop (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (aL + 2) q' (2 * q' + aR_odd) ltac:(lia) ltac:(lia) hp tail) as [Lt1 [hp1 h2]].
    replace (aL + 2 + 2 * q') with (aL + 2 * S q') in h2 by lia.
    replace (2 * q' + aR_odd - 2 * q') with aR_odd in h2 by lia.
    assert (HE1 : E_rem - q' = (E_rem - S q') + 1) by lia.
    pose proof (pipeL_eqE HE1 hp1) as hp1'.
    destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
    assert (H3 : (([S1; S1] *> Lt1) {{F}}> ([S0; S1] *> (T2 ^^ (aL + 2 * S q')) *> T0 *> (T2 ^^ aR_odd) *> T0 *> tail)) -[ tm ]->*
                 (([S1] *> (T3 ^^ (aL + 2 * S q')) *> T2 *> Lt2) {{A}}> (T0 *> (T2 ^^ aR_odd) *> T0 *> tail))).
    { change ([S0; S1] *> (T2 ^^ (aL + 2 * S q')) *> T0 *> (T2 ^^ aR_odd) *> T0 *> tail) with
        (T0 *> [S1] *> (T2 ^^ (aL + 2 * S q')) *> T0 *> (T2 ^^ aR_odd) *> T0 *> tail).
      eapply evstep_trans; [apply hpull |].
      eapply evstep_trans; [apply post_pull_q0 |].
      apply rule_q0_t2. }
    exists Lt2. split; [exact hp2 | exact (stepStar_trans h0_sw (stepStar_trans H1 (stepStar_trans h2 H3)))].
Qed.

Lemma pipeL_asplit_heal_h1_even {E_rem : nat} {R_out : list Sym} {Lt : Stream Sym}
    (aL q_as b : nat) (hle : q_as <= E_rem) (hp : PipeL E_rem R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (E_rem - q_as) ((R_out ++ (T2 ^^ (aL + 2 * q_as + 2))) ++ (T4 ^^ (b + 1))) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> ((T2 ^^ aL) *> T0 *> (T2 ^^ (2 * q_as)) *> T5 *> (T4 ^^ (b + 1)) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  destruct (pipeL_asplit_prep aL q_as 0 hle hp ([S1; S0; S0; S1] *> (T4 ^^ (b + 1)) *> r)) as [Lt1 [hp1 h1]].
  replace (2 * q_as + 0) with (2 * q_as) in h1 by lia. rewrite zPz, zLan in h1.
  change (T0 *> [S1; S0; S0; S1] *> (T4 ^^ (b + 1)) *> r) with (T5 *> (T4 ^^ (b + 1)) *> r) in h1.
  assert (H2 : (([S1] *> (T3 ^^ (aL + 2 * q_as)) *> T2 *> Lt1) {{A}}> (T0 *> T5 *> (T4 ^^ (b + 1)) *> r)) -[ tm ]->*
               (([S1] *> T2 *> (T5 ^^ b) *> T4 *> (T3 ^^ (aL + 2 * q_as + 1)) *> T2 *> Lt1) {{A}}> r)).
  { change (T0 *> T5 *> (T4 ^^ (b + 1)) *> r) with (T2 *> T2 *> (T4 ^^ (b + 1)) *> r).
    eapply evstep_trans; [apply step_q0_t2_one |].
    eapply evstep_trans; [apply step_q0_t2_one |].
    replace (b + 1) with (S b) by lia. rewrite (zPsr T4).
    eapply evstep_trans; [apply step_q0_t4_first |].
    rewrite <- zPsr. replace (S (aL + 2 * q_as)) with (aL + 2 * q_as + 1) by lia.
    apply rule_q0_t4_next. }
  exists ((T5 ^^ b) *> T4 *> (T3 ^^ (aL + 2 * q_as + 1)) *> T2 *> Lt1). split.
  - pose proof (pipeL_T2_blk b (aL + 2 * q_as + 1) hp1) as hp'.
    replace (aL + 2 * q_as + 1 + 1) with (aL + 2 * q_as + 2) in hp' by lia. exact hp'.
  - exact (stepStar_trans h1 H2).
Qed.

Lemma pipeL_asplit_heal_h1_odd {E_rem : nat} {R_out : list Sym} {Lt : Stream Sym}
    (aL q_as b : nat) (hle : q_as <= E_rem) (hp : PipeL E_rem R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (E_rem - q_as) (((R_out ++ (T2 ^^ (aL + 2 * q_as + 3))) ++ T5) ++ (T4 ^^ b)) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> ((T2 ^^ aL) *> T0 *> (T2 ^^ (2 * q_as + 1)) *> T5 *> (T4 ^^ (b + 1)) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  destruct (pipeL_asplit_prep aL q_as 1 hle hp ([S1; S0; S0; S1] *> (T4 ^^ (b + 1)) *> r)) as [Lt1 [hp1 h1]].
  rewrite zP1 in h1.
  change (T0 *> [S1; S0; S0; S1] *> (T4 ^^ (b + 1)) *> r) with (T5 *> (T4 ^^ (b + 1)) *> r) in h1.
  assert (H2 : (([S1] *> (T3 ^^ (aL + 2 * q_as)) *> T2 *> Lt1) {{A}}> (T0 *> T2 *> T5 *> (T4 ^^ (b + 1)) *> r)) -[ tm ]->*
               (([S1] *> T2 *> (T5 ^^ b) *> T4 *> (T3 ^^ (aL + 2 * q_as + 3)) *> Lt1) {{A}}> r)).
  { eapply evstep_trans; [apply step_heal_0_t2 |].
    rewrite <- zPsr. replace (S (aL + 2 * q_as)) with ((aL + 2 * q_as) + 1) by lia.
    eapply evstep_trans; [apply step_heal_odd_h1 |].
    replace (aL + 2 * q_as + 4) with (S (aL + 2 * q_as + 3)) by lia.
    replace (b + 1) with (S b) by lia. rewrite !zPsr.
    eapply evstep_trans; [apply step_q0_t4_first |].
    apply rule_q0_t4_next. }
  exists ((T5 ^^ b) *> T4 *> (T3 ^^ (aL + 2 * q_as + 3)) *> Lt1). split.
  - exact (pipeL_noT2_blk b (aL + 2 * q_as + 3) hp1).
  - exact (stepStar_trans h1 H2).
Qed.

Lemma pipeL_asplit_heal_h0_even {E_rem : nat} {R_out : list Sym} {Lt : Stream Sym}
    (aL q_as b : nat) (hle : q_as <= E_rem) (hp : PipeL E_rem R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (E_rem - q_as) ((R_out ++ (T2 ^^ (aL + 2 * q_as + 1))) ++ (T4 ^^ 1)) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> ((T2 ^^ aL) *> T0 *> (T2 ^^ (2 * q_as)) *> (T4 ^^ (b + 1)) *> r)) -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> ((T4 ^^ b) *> r)).
Proof.
  destruct (pipeL_asplit_prep aL q_as 0 hle hp ([S1; S0; S1; S1] *> (T4 ^^ b) *> r)) as [Lt1 [hp1 h1]].
  replace (2 * q_as + 0) with (2 * q_as) in h1 by lia. rewrite zPz, zLan in h1.
  change (T0 *> [S1; S0; S1; S1] *> (T4 ^^ b) *> r) with (T4 *> (T4 ^^ b) *> r) in h1.
  pose proof (step_heal_0_t4 ((T3 ^^ (aL + 2 * q_as)) *> T2 *> Lt1) ((T4 ^^ b) *> r)) as h2.
  pose proof (pipeL_T2_blk 0 (aL + 2 * q_as) hp1) as hp1blk.
  rewrite zPz, zLan in hp1blk.
  exists (T4 *> (T3 ^^ (aL + 2 * q_as)) *> T2 *> Lt1). split; [exact hp1blk |].
  replace (b + 1) with (S b) by lia. rewrite (zPsr T4).
  exact (stepStar_trans h1 h2).
Qed.

Lemma pipeL_asplit_heal_h0_odd {E_rem : nat} {R_out : list Sym} {Lt : Stream Sym}
    (aL q_as b : nat) (hle : q_as <= E_rem) (hp : PipeL E_rem R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (E_rem - q_as) ((R_out ++ (T2 ^^ (aL + 2 * q_as + 2))) ++ T5) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> ((T2 ^^ aL) *> T0 *> (T2 ^^ (2 * q_as + 1)) *> (T4 ^^ (b + 1)) *> r)) -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> ((T4 ^^ b) *> r)).
Proof.
  destruct (pipeL_asplit_prep aL q_as 1 hle hp ([S1; S0; S1; S1] *> (T4 ^^ b) *> r)) as [Lt1 [hp1 h1]].
  rewrite zP1 in h1.
  change (T0 *> [S1; S0; S1; S1] *> (T4 ^^ b) *> r) with (T4 *> (T4 ^^ b) *> r) in h1.
  assert (H2 : (([S1] *> (T3 ^^ (aL + 2 * q_as)) *> T2 *> Lt1) {{A}}> (T0 *> T2 *> T4 *> (T4 ^^ b) *> r)) -[ tm ]->*
               (([S1; S1] *> T4 *> (T3 ^^ (aL + 2 * q_as + 2)) *> Lt1) {{F}}> ((T4 ^^ b) *> r))).
  { eapply evstep_trans; [apply step_heal_0_t2 |].
    rewrite <- zPsr. replace (S (aL + 2 * q_as)) with ((aL + 2 * q_as) + 1) by lia.
    apply step_heal_odd_h0. }
  pose proof (pipeL_noT2_blk 0 (aL + 2 * q_as + 2) hp1) as hp1blk.
  rewrite !zPz, zLan, app_nil_r in hp1blk.
  exists (T4 *> (T3 ^^ (aL + 2 * q_as + 2)) *> Lt1). split; [exact hp1blk |].
  replace (b + 1) with (S b) by lia. rewrite (zPsr T4).
  exact (stepStar_trans h1 H2).
Qed.

Lemma pipeL_unzip_seg {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (sv : nat) (hle : sv + 1 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (En - (sv + 1)) (((R_out ++ (T2 ^^ 1)) ++ T5) ++ (T4 ^^ sv)) Lt' /\
      (([S1; S1] *> Lt) {{F}}> (T3 *> (T4 ^^ (sv + 1)) *> r)) -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> r).
Proof.
  destruct En as [|En']; [lia |].
  replace (S En') with (En' + 1) in hp by lia.
  destruct (PipeL_pull hp) as [Lt1 [hpull hp1]].
  assert (H1 : (([S1; S1] *> Lt) {{F}}> (T3 *> (T4 ^^ (sv + 1)) *> r)) -[ tm ]->*
               (([S1; S1] *> T4 *> T3 *> Lt1) {{F}}> ((T4 ^^ sv) *> r))).
  { replace (sv + 1) with (S sv) by lia. rewrite zPsr.
    change (T3 *> T4 *> (T4 ^^ sv) *> r) with (T0 *> [S1; S1] *> T4 *> (T4 ^^ sv) *> r).
    eapply evstep_trans; [apply hpull |].
    apply step_post_pull_unzip_seg. }
  pose proof (pipeL_noT2_blk 0 1 hp1) as hp1blk.
  rewrite !zPz, zLan, zP1, app_nil_r in hp1blk.
  destruct (pipeL_eat_t4 (En := ltac:(match type of hp1blk with PipeL ?e _ _ => exact e end)) sv ltac:(lia) hp1blk r) as [Lt2 [hp2 h2]].
  exists Lt2. split.
  - replace (S En' - (sv + 1)) with (En' - sv) by lia. exact hp2.
  - exact (stepStar_trans H1 h2).
Qed.

Lemma pipeL_unzip_pair {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (v1 v2 q : nat) (hle : q * (v1 + v2 + 2) <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    let w_in := ((T3 ++ (T4 ^^ (v1 + 1))) ++ T3) ++ (T4 ^^ (v2 + 1)) in
    let w_out := (((T2 ^^ 1) ++ T5) ++ (T4 ^^ v1)) ++ (((T2 ^^ 1) ++ T5) ++ (T4 ^^ v2)) in
    exists Lt', PipeL (En - q * (v1 + v2 + 2)) (R_out ++ (w_out ^^ q)) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((w_in ^^ q) *> r)) -[ tm ]->* (([S1; S1] *> Lt') {{F}}> r).
Proof.
  intros w_in w_out. revert En R_out Lt hle hp.
  induction q as [|q' IH]; intros En R_out Lt hle hp.
  - exists Lt. split.
    + replace (En - 0 * (v1 + v2 + 2)) with En by lia. rewrite zPz, app_nil_r. exact hp.
    + rewrite zPz, zLan. apply evstep_refl.
  - assert (Hle1 : v1 + 1 <= En) by nia.
    assert (Hle2 : v2 + 1 <= En - (v1 + 1)) by nia.
    destruct (pipeL_unzip_seg v1 Hle1 hp (T3 *> (T4 ^^ (v2 + 1)) *> (w_in ^^ q') *> r)) as [Lt1 [hp1 hs1]].
    destruct (pipeL_unzip_seg v2 Hle2 hp1 ((w_in ^^ q') *> r)) as [Lt2 [hp2 hs2]].
    destruct (IH (En - (v1 + 1) - (v2 + 1)) _ Lt2 ltac:(nia) hp2) as [Lt3 [hp3 hs3]].
    exists Lt3. split.
    + eapply pipeL_eqE; [| eapply pipeL_eqR; [| exact hp3]].
      * nia.
      * unfold w_out. simpl lpow. rewrite !append_assoc. reflexivity.
    + assert (Hw : (w_in ^^ S q') *> r =
        T3 *> (T4 ^^ (v1 + 1)) *> T3 *> (T4 ^^ (v2 + 1)) *> (w_in ^^ q') *> r)
        by (rewrite zPsr; unfold w_in at 1; rewrite !Str_app_assoc; reflexivity).
      rewrite Hw.
      exact (stepStar_trans hs1 (stepStar_trans hs2 hs3)).
Qed.

Lemma pipeL_unzip_stop {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (sv : nat) (hE : 1 <= En) (hlt : En + 1 <= sv) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    (([S1; S1] *> Lt) {{F}}> (T3 *> (T4 ^^ sv) *> r)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *>
      (((((R_out ++ (T2 ^^ 1)) ++ T5) ++ (T4 ^^ (En - 1))) ++ T3) ++ (T4 ^^ (sv - En - 1))) *> r)).
Proof.
  destruct En as [|En']; [lia |].
  assert (HR : T3 *> (T4 ^^ sv) *> r =
               T0 *> [S1; S1] *> T4 *> (T4 ^^ En') *> T4 *> (T4 ^^ (sv - S En' - 1)) *> r).
  { replace sv with (1 + (En' + (1 + (sv - S En' - 1)))) at 1 by lia.
    rewrite !pow_add_blank, !zP1. reflexivity. }
  rewrite HR.
  replace (S En') with (En' + 1) in hp by lia.
  destruct (PipeL_pull hp) as [Lt1 [hpull hp1]].
  pose proof (stepStar_trans
    (hpull ([S1; S1] *> T4 *> (T4 ^^ En') *> T4 *> (T4 ^^ (sv - S En' - 1)) *> r))
    (step_post_pull_unzip_seg Lt1 ((T4 ^^ En') *> T4 *> (T4 ^^ (sv - S En' - 1)) *> r))) as h1.
  pose proof (pipeL_noT2_blk 0 1 hp1) as hp1blk.
  rewrite !zPz, zLan, zP1, app_nil_r in hp1blk.
  destruct (pipeL_eat_t4 En' (Nat.le_refl _) hp1blk (T4 *> (T4 ^^ (sv - S En' - 1)) *> r)) as [Lt2 [hp2 h2]].
  replace (En' - En') with 0 in hp2 by lia.
  eapply evstep_trans; [exact h1 |].
  eapply evstep_trans; [exact h2 |].
  change (T4 *> (T4 ^^ (sv - S En' - 1)) *> r) with ([S0; S1] *> T3 *> (T4 ^^ (sv - S En' - 1)) *> r).
  eapply evstep_trans; [apply (PipeL_unwind hp2) |].
  replace (S En' - 1) with En' by lia.
  rewrite !Str_app_assoc. apply evstep_refl.
Qed.

(* ========================================================================= *)
(* Section 8.3-8.4: Tape Encodings, HubCfg, step1Hub_sound, applyNorm_sound  *)
(* ========================================================================= *)

Definition encTok (t : Tok) : list Sym :=
  match t with
  | T_0 => T0 | T_1 => T1 | T_2 => T2 | T_3 => T3
  | T_4 => T4 | T_5 => T5 | T_6 => T6
  end.

Fixpoint encSegTail (segs : list SegPiece) : list Sym :=
  match segs with
  | [] => []
  | SPsingle b :: rest => (T3 ++ (T4 ^^ N.to_nat b)) ++ encSegTail rest
  | SPpair v1 v2 rep :: rest =>
      ((((T3 ++ (T4 ^^ N.to_nat v1)) ++ T3) ++ (T4 ^^ N.to_nat v2)) ^^ N.to_nat rep) ++ encSegTail rest
  end.

Definition encSingle (a : N) (h : bool) (s0 : N) (segTail : list SegPiece) (aRight : option N) : list Sym :=
  ((((T2 ^^ N.to_nat a)
    ++ match aRight with None => [] | Some aR => T0 ++ (T2 ^^ N.to_nat aR) end)
    ++ (if h then T5 else []))
    ++ (T4 ^^ N.to_nat s0))
    ++ encSegTail segTail.

Definition encItem (it : RleItem) : list Sym :=
  match it with
  | RIsingle a h s0 segTail aRight => encSingle a h s0 segTail aRight
  | RItranspRun a b rep => ((T2 ^^ N.to_nat a) ++ (T4 ^^ N.to_nat b)) ^^ N.to_nat rep
  | RIpairRun a1 h1 b1 a2 h2 b2 rep =>
      (encSingle a1 h1 b1 [] None ++ encSingle a2 h2 b2 [] None) ^^ N.to_nat rep
  | RIraw t n => (encTok t) ^^ N.to_nat n
  end.

Fixpoint encItems (xs : list RleItem) : list Sym :=
  match xs with
  | [] => []
  | x :: xs' => encItem x ++ encItems xs'
  end.

Lemma encItems_append (xs ys : list RleItem) :
  encItems (xs ++ ys) = encItems xs ++ encItems ys.
Proof.
  induction xs as [|x xs IH]; [reflexivity | simpl; rewrite IH, append_assoc; reflexivity].
Qed.

Lemma encItems_rev_cons (x : RleItem) (xs : list RleItem) :
  encItems (List.rev (x :: xs)) = encItems (List.rev xs) ++ encItem x.
Proof.
  simpl List.rev. rewrite encItems_append. simpl encItems. rewrite app_nil_r. reflexivity.
Qed.

Definition HubCfg (items : list RleItem) : Q * tape :=
  b0 {{E}}> (T2 *> T0 *> T1 *> encItems items *> [S0; S1; S0; S1] *> b0).

Lemma HubCfg_of_encItems_eq {xs ys : list RleItem} (h : encItems xs = encItems ys) :
  HubCfg xs = HubCfg ys.
Proof.
  unfold HubCfg. rewrite h. reflexivity.
Qed.

Lemma encSingle_single_add_s0 (a : N) (h : bool) (s0 d : N) :
  encSingle a h s0 [] None ++ (T4 ^^ N.to_nat d) = encSingle a h (s0 + d)%N [] None.
Proof.
  unfold encSingle; cbn [encSegTail].
  rewrite !app_nil_r, append_assoc, <- list_pow_add.
  replace (N.to_nat s0 + N.to_nat d) with (N.to_nat (s0 + d)%N) by lia.
  reflexivity.
Qed.

Lemma encSegTail_single (b : N) (rest : list SegPiece) :
  encSegTail (SPsingle b :: rest) = (T3 ++ (T4 ^^ N.to_nat b)) ++ encSegTail rest.
Proof. reflexivity. Qed.

Lemma unpackFrontSeg_sound {segs : list SegPiece} {s1 : N} {segRest : list SegPiece}
    (hu : unpackFrontSeg segs = Some (s1, segRest)) :
    encSegTail segs = (T3 ++ (T4 ^^ N.to_nat s1)) ++ encSegTail segRest.
Proof.
  destruct segs as [|[b | v1 v2 rep] rest]; simpl in hu; try discriminate.
  - inversion hu; subst. reflexivity.
  - destruct (1 <=? rep)%N eqn:Hrep; [|discriminate].
    split_andb. inversion hu; subst.
    destruct ((rep - 1 =? 0)%N) eqn:Hrem0; split_andb.
    + assert (Hrep1 : N.to_nat rep = 1) by lia.
      cbn [encSegTail]. rewrite Hrep1, list_pow_one. simpl. rewrite ?append_assoc. reflexivity.
    + assert (HrepS : N.to_nat rep = S (N.to_nat (rep - 1)%N)) by lia.
      cbn [encSegTail]. rewrite HrepS. simpl. rewrite ?append_assoc. reflexivity.
Qed.

Lemma step1Unzip_sound : forall (segs : list SegPiece) (En : N) (revPref tail out : list RleItem) (Lt : Stream Sym),
  PipeL (N.to_nat En) (encItems (List.rev revPref)) Lt ->
  step1Unzip En revPref segs tail = Some out ->
  (([S1; S1] *> Lt) {{F}}> (encSegTail segs *> encItems tail *> [S0; S1; S0; S1] *> b0))
    -[ tm ]->* HubCfg out.
Proof.
  induction segs as [|[sv | v1 v2 rep] segRest IH]; intros En revPref tail out Lt hp hstep.
  - cbn [step1Unzip] in hstep. discriminate.
  - cbn [step1Unzip] in hstep.
    destruct (((1 <=? sv)%N && (sv + 1 <=? En)%N && negb (isEmpty segRest))%bool) eqn:Hc1.
    + split_andb.
      pose proof (pipeL_unzip_seg (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat (sv - 1)%N) ltac:(lia) hp
        (encSegTail segRest *> encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
      replace (N.to_nat (sv - 1)%N + 1) with (N.to_nat sv) in hp1, hs1 by lia.
      assert (Hp1' : PipeL (N.to_nat (En - sv)%N)
          (encItems (List.rev (RIsingle 1%N true (sv - 1)%N [] None :: revPref))) Lt1).
      { apply (pipeL_eqER hp1); [lia  |].
        rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
        rewrite ?app_nil_r, ?append_assoc. reflexivity. }
      rewrite encSegTail_single, ?Str_app_assoc.
      exact (stepStar_trans hs1 (IH _ _ tail out Lt1 Hp1' hstep)).
    + destruct (((1 <=? En)%N && (En + 1 <=? sv)%N)%bool) eqn:Hc2; [|discriminate].
      split_andb. inversion hstep; subst out.
      rewrite encSegTail_single, ?Str_app_assoc.
      eapply evstep_trans; [apply (pipeL_unzip_stop (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat sv) ltac:(lia) ltac:(lia) hp) |].
      unfold HubCfg. rewrite encItems_append. cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
      replace (N.to_nat En - 1) with (N.to_nat (En - 1)%N) by lia.
      replace (N.to_nat sv - N.to_nat En - 1) with (N.to_nat (sv - En - 1)%N) by lia.
      rewrite ?app_nil_r, ?Str_app_assoc. apply evstep_refl.
  - cbn [step1Unzip] in hstep.
    destruct (((1 <=? v1)%N && (1 <=? v2)%N && (1 <=? rep)%N)%bool) eqn:Hc1; [|discriminate].
    split_andb.
    set (pc := (v1 + v2)%N) in *.
    set (q := (if 2 + pc <=? En then N.min rep ((En - 2) / pc) else 0)%N) in *.
    set (E1 := (En - q * pc)%N) in *.
    set (rev1 := if (0 <? q)%N then RIsingle 1%N true (v1 - 1)%N [] None :: [] (* dummy *) else []) in *.
    clear rev1.
    set (rev1 := if (0 <? q)%N then RIpairRun 1%N true (v1 - 1)%N 1%N true (v2 - 1)%N q :: revPref else revPref) in *.
    assert (Hq_rep : (q <= rep)%N).
    { unfold q. destruct (2 + pc <=? En)%N; [apply N.le_min_l | lia]. }
    assert (Hq_cost : (q * pc <= En)%N).
    { unfold q. destruct (2 + pc <=? En)%N eqn:Hge; split_andb; [|lia].
      assert (Hmin : (N.min rep ((En - 2) / pc) <= (En - 2) / pc)%N) by apply N.le_min_r.
      pose proof (N_mul_div_le (En - 2)%N pc) as Hmd. nia. }
    assert (Hcost_nat : N.to_nat q * (N.to_nat (v1 - 1)%N + N.to_nat (v2 - 1)%N + 2) <= N.to_nat En) by nia.
    pose proof (pipeL_unzip_pair (N.to_nat (v1 - 1)%N) (N.to_nat (v2 - 1)%N) (N.to_nat q) Hcost_nat hp
      (((((T3 ++ (T4 ^^ N.to_nat v1)) ++ T3) ++ (T4 ^^ N.to_nat v2)) ^^ N.to_nat (rep - q)%N) *>
       encSegTail segRest *> encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
    replace (N.to_nat (v1 - 1)%N + 1) with (N.to_nat v1) in hs1 by lia.
    replace (N.to_nat (v2 - 1)%N + 1) with (N.to_nat v2) in hs1 by lia.
    assert (Hp1' : PipeL (N.to_nat E1) (encItems (List.rev rev1)) Lt1).
    { apply (pipeL_eqER hp1); [unfold E1, pc; nia  |].
      unfold rev1. destruct (0 <? q)%N eqn:Hq0; split_andb.
      - rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
        rewrite ?app_nil_r, ?append_assoc. reflexivity.
      - assert (HqZ : N.to_nat q = 0) by lia. rewrite HqZ, zPz, app_nil_r. reflexivity. }
    assert (Hseg : encSegTail (SPpair v1 v2 rep :: segRest) =
      (((((T3 ++ (T4 ^^ N.to_nat v1)) ++ T3) ++ (T4 ^^ N.to_nat v2)) ^^ N.to_nat q) ++
       ((((T3 ++ (T4 ^^ N.to_nat v1)) ++ T3) ++ (T4 ^^ N.to_nat v2)) ^^ N.to_nat (rep - q)%N)) ++
      encSegTail segRest).
    { cbn [encSegTail]. rewrite <- list_pow_add.
      replace (N.to_nat q + N.to_nat (rep - q)%N) with (N.to_nat rep) by lia. reflexivity. }
    rewrite Hseg, ?Str_app_assoc.
    eapply evstep_trans; [exact hs1 |].
    destruct ((rep - q =? 0)%N) eqn:Hrem0; split_andb.
    + assert (Hr0 : N.to_nat (rep - q)%N = 0) by lia.
      rewrite Hr0, zPz, zLan.
      exact (IH E1 rev1 tail out Lt1 Hp1' hstep).
    + set (restAfter := if (rep - q =? 1)%N then segRest else SPpair v1 v2 (rep - q - 1)%N :: segRest) in *.
      assert (Htail_eq :
        ((((T3 ++ (T4 ^^ N.to_nat v1)) ++ T3) ++ (T4 ^^ N.to_nat v2)) ^^ N.to_nat (rep - q)%N) *>
          encSegTail segRest *> encItems tail *> [S0; S1; S0; S1] *> b0 =
        T3 *> (T4 ^^ N.to_nat v1) *> T3 *> (T4 ^^ N.to_nat v2) *>
          encSegTail restAfter *> encItems tail *> [S0; S1; S0; S1] *> b0).
      { unfold restAfter. destruct ((rep - q =? 1)%N) eqn:Hr1; split_andb.
        - assert (Hr1_eq : N.to_nat (rep - q)%N = 1) by lia.
          rewrite Hr1_eq, list_pow_one, ?Str_app_assoc. reflexivity.
        - assert (HS : N.to_nat (rep - q)%N = S (N.to_nat (rep - q - 1)%N)) by lia.
          rewrite HS, zPsr, ?Str_app_assoc. cbn [encSegTail]. rewrite Str_app_assoc. reflexivity. }
      rewrite Htail_eq.
      destruct (((1 <=? E1)%N && (E1 + 1 <=? v1)%N)%bool) eqn:Hs1.
      * split_andb. inversion hstep; subst out.
        eapply evstep_trans; [apply (pipeL_unzip_stop (En := ltac:(match type of Hp1' with PipeL ?e _ _ => exact e end)) (N.to_nat v1) ltac:(lia) ltac:(lia) Hp1') |].
        unfold HubCfg. rewrite encItems_append. cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
        replace (N.to_nat E1 - 1) with (N.to_nat (E1 - 1)%N) by lia.
        replace (N.to_nat v1 - N.to_nat E1 - 1) with (N.to_nat (v1 - E1 - 1)%N) by lia.
        rewrite ?app_nil_r, ?Str_app_assoc. apply evstep_refl.
      * destruct (((v1 + 1 <=? E1)%N && (E1 - v1 + 1 <=? v2)%N)%bool) eqn:Hs2; [|discriminate].
        split_andb. inversion hstep; subst out.
        pose proof (pipeL_unzip_seg (En := ltac:(match type of Hp1' with PipeL ?e _ _ => exact e end)) (N.to_nat (v1 - 1)%N) ltac:(lia) Hp1'
          (T3 *> (T4 ^^ N.to_nat v2) *> encSegTail restAfter *> encItems tail *> [S0; S1; S0; S1] *> b0))
          as [Lt2 [hp2 hs2]].
        replace (N.to_nat (v1 - 1)%N + 1) with (N.to_nat v1) in hp2, hs2 by lia.
        eapply evstep_trans; [exact hs2 |].
        assert (Hp2' : PipeL (N.to_nat (E1 - v1)%N)
          (encItems (List.rev (RIsingle 1%N true (v1 - 1)%N [] None :: rev1))) Lt2).
        { apply (pipeL_eqER hp2); [lia  |].
          rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
          rewrite ?app_nil_r, ?append_assoc. reflexivity. }
        eapply evstep_trans; [apply (pipeL_unzip_stop (En := ltac:(match type of Hp2' with PipeL ?e _ _ => exact e end)) (N.to_nat v2) ltac:(lia) ltac:(lia) Hp2') |].
        unfold HubCfg. rewrite encItems_append. cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
        replace (N.to_nat (E1 - v1)%N - 1) with (N.to_nat (E1 - v1 - 1)%N) by lia.
        replace (N.to_nat v2 - N.to_nat (E1 - v1)%N - 1) with (N.to_nat (v2 - (E1 - v1) - 1)%N) by lia.
        rewrite ?app_nil_r, ?Str_app_assoc. apply evstep_refl.
Qed.

Lemma list_pow_add_r (u : list Sym) (m n : nat) (z : list Sym) :
  (u ^^ m) ++ ((u ^^ n) ++ z) = (u ^^ (m + n)) ++ z.
Proof.
  rewrite <- append_assoc, <- list_pow_add. reflexivity.
Qed.

Lemma step1Phases_sound (rest : list RleItem) :
  (forall (En : N) (revPref out : list RleItem) (Lt : Stream Sym),
    PipeL (N.to_nat En) (encItems (List.rev revPref)) Lt ->
    step1Phases false En revPref rest = Some out ->
    (([S1; S1] *> Lt) {{F}}> (encItems rest *> [S0; S1; S0; S1] *> b0)) -[ tm ]->* HubCfg out)
  /\
  (forall (E_rem : N) (revPref out : list RleItem) (Lt : Stream Sym),
    PipeL (N.to_nat E_rem) (encItems (List.rev revPref)) Lt ->
    step1Phases true E_rem revPref rest = Some out ->
    (([S1] *> T2 *> Lt) {{A}}> (encItems rest *> [S0; S1; S0; S1] *> b0)) -[ tm ]->* HubCfg out).
Proof.
  induction rest as [|item tail [IH1 IH2]].
  - split.
    + intros En revPref out Lt _ hstep. cbn [step1Phases] in hstep. discriminate.
    + intros E_rem revPref out Lt hp hstep. cbn [step1Phases] in hstep.
      destruct revPref as [|[a h s0 [|? ?] [?|] | | |] prev]; try discriminate.
      inversion hstep; subst out.
      cbn [encItems]. rewrite zLan.
      eapply evstep_trans; [apply (pipeL_dump_wall2 hp) |].
      unfold HubCfg. rewrite encItems_rev_cons, encItems_append. cbn [encItems].
      unfold encItem.
      rewrite ?app_nil_r, ?append_assoc.
      replace (N.to_nat E_rem + 1) with (N.to_nat (E_rem + 1)%N) by lia.
      rewrite encSingle_single_add_s0.
      replace (s0 + (E_rem + 1))%N with (s0 + E_rem + 1)%N by lia.
      apply evstep_refl.
  - assert (hDump : forall (E_rem : N) (revPref out : list RleItem) (sa : N) (sh : bool) (s0 : N)
        (segTail : list SegPiece) (Lt : Stream Sym),
      PipeL (N.to_nat E_rem) (encItems (List.rev (RIsingle sa sh s0 [] None :: revPref))) Lt ->
      step1DumpSegsAux (fun E' rev' => step1Phases false E' rev' tail) E_rem revPref sa sh s0 segTail tail = Some out ->
      (([S1] *> T2 *> Lt) {{A}}> (encSegTail segTail *> encItems tail *> [S0; S1; S0; S1] *> b0))
        -[ tm ]->* HubCfg out).
    { intros E_rem revPref out sa sh s0 segTail Lt hp hstep.
      unfold step1DumpSegsAux in hstep.
      destruct (unpackFrontSeg segTail) as [[s1 segRest]|] eqn:Hu; [|discriminate].
      rewrite (unpackFrontSeg_sound Hu), ?Str_app_assoc.
      destruct ((E_rem + 1 <? s1)%N) eqn:Hlt.
      - split_andb. inversion hstep; subst out.
        eapply evstep_trans; [apply (pipeL_dump_wall1 (E_rem := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat s1) ltac:(lia) hp) |].
        unfold HubCfg. rewrite encItems_rev_cons, encItems_append. cbn [encItems].
        unfold encItem, encSingle; cbn [encSegTail].
        rewrite ?app_nil_r, ?Str_app_assoc, <- pow_add_blank.
        replace (N.to_nat s0 + (N.to_nat E_rem + 1)) with (N.to_nat (s0 + E_rem + 1)%N) by lia.
        replace (N.to_nat s1 - (N.to_nat E_rem + 1)) with (N.to_nat (s1 - (E_rem + 1))%N) by lia.
        apply evstep_refl.
      - destruct ((s1 + 1 <=? E_rem)%N) eqn:Hge; [|discriminate].
        split_andb.
        destruct (pipeL_absorb_2seg (E_rem := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat s1) ltac:(lia) hp
          (encSegTail segRest *> encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
        assert (Hp1' : PipeL (N.to_nat (E_rem - s1)%N)
          (encItems (List.rev (RIsingle sa sh (s0 + s1 + 1)%N [] None :: revPref))) Lt1).
        { apply (pipeL_eqER hp1); [lia  |].
          rewrite !encItems_rev_cons. simpl encItem. rewrite append_assoc.
          replace (N.to_nat s1 + 1) with (N.to_nat (s1 + 1)%N) by lia.
          rewrite encSingle_single_add_s0.
          replace (s0 + (s1 + 1))%N with (s0 + s1 + 1)%N by lia. reflexivity. }
        eapply evstep_trans; [exact hs1 |].
        destruct (isEmpty segRest) eqn:Hemp.
        + apply isEmpty_true_iff in Hemp; subst segRest. cbn [encSegTail]. rewrite zLan.
          exact (IH1 _ _ out Lt1 Hp1' hstep).
        + exact (step1Unzip_sound segRest _ _ tail out Lt1 Hp1' hstep). }
    split.
    + (* Phase 1 *)
      intros En revPref out Lt hp hstep. cbn [step1Phases] in hstep.
      destruct item as [a h s0 segTail [aR|] | a b rep | a1 h1 b1 a2 h2 b2 rep | t n]; try discriminate.
      * (* RIsingle a h s0 segTail None *)
        destruct ((1 <=? a)%N) eqn:Ha1; [|discriminate]. split_andb.
        destruct ((En <=? a / 2)%N) eqn:HEj.
        -- split_andb.
           destruct (((1 <=? En)%N && (2 * En + 1 <=? a)%N)%bool) eqn:Hc; [|discriminate].
           split_andb. inversion hstep; subst out.
           cbn [encItems]. unfold encItem, encSingle. rewrite ?app_nil_r, ?Str_app_assoc.
           eapply evstep_trans; [apply (pipeL_asplit_create (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat a) ltac:(lia) ltac:(lia) hp) |].
           unfold HubCfg. rewrite encItems_append. cbn [encItems]. unfold encItem, encSingle.
           replace (2 * N.to_nat En - 1) with (N.to_nat (2 * En - 1)%N) by lia.
           replace (N.to_nat a - 2 * N.to_nat En) with (N.to_nat (a - 2 * En)%N) by lia.
           rewrite ?app_nil_r, ?Str_app_assoc. apply evstep_refl.
        -- split_andb.
           destruct h.
           ++ (* h = true *)
              simpl negb in hstep.
              destruct ((a mod 2 =? 0)%N) eqn:Ha2; split_andb.
              ** pose proof (N_even_decomp a Ha2) as Haeven.
                 destruct ((1 <=? s0)%N) eqn:Hs0; [|discriminate]. split_andb.
                 cbn [encItems]. unfold encItem, encSingle. rewrite ?Str_app_assoc.
                 rewrite Haeven. replace (N.to_nat s0) with ((N.to_nat s0 - 1) + 1) by lia.
                 destruct (pipeL_h1_enter_even (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat (a / 2)%N) (N.to_nat s0 - 1) ltac:(lia) hp
                   (encSegTail segTail *> encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
                 assert (Hp1' : PipeL (N.to_nat (En - a / 2 - 1)%N)
                   (encItems (List.rev (RIsingle (a + 1)%N false s0 [] None :: revPref))) Lt1).
                 { apply (pipeL_eqER hp1); [lia  |].
                   rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                   replace (2 * N.to_nat (a / 2)%N + 1) with (N.to_nat (a + 1)%N) by lia.
                   replace (N.to_nat s0 - 1 + 1) with (N.to_nat s0) by lia.
                   rewrite ?app_nil_r, ?append_assoc. reflexivity. }
                 eapply evstep_trans; [exact hs1 |].
                 destruct (isEmpty segTail) eqn:Hemp.
                 --- apply isEmpty_true_iff in Hemp; subst segTail. cbn [encSegTail]. rewrite zLan.
                     exact (IH2 _ _ out Lt1 Hp1' hstep).
                 --- exact (hDump _ _ out _ _ _ segTail Lt1 Hp1' hstep).
              ** pose proof (N_odd_decomp a Ha2) as Haodd.
                 destruct ((2 <=? s0)%N) eqn:Hs0; [|discriminate]. split_andb.
                 cbn [encItems]. unfold encItem, encSingle. rewrite ?Str_app_assoc.
                 rewrite Haodd. replace (N.to_nat s0) with (N.to_nat (s0 - 1)%N + 1) by lia.
                 destruct (pipeL_h1_enter_odd (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat (a / 2)%N) (N.to_nat (s0 - 1)%N) ltac:(lia) hp
                   (encSegTail segTail *> encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
                 assert (Hp1' : PipeL (N.to_nat (En - a / 2 - 1)%N)
                   (encItems (List.rev (RIsingle (a + 1)%N true (s0 - 1)%N [] None :: revPref))) Lt1).
                 { apply (pipeL_eqER hp1); [lia  |].
                   rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                   replace (2 * N.to_nat (a / 2)%N + 2) with (N.to_nat (a + 1)%N) by lia.
                   rewrite ?app_nil_r, ?append_assoc. reflexivity. }
                 eapply evstep_trans; [exact hs1 |].
                 destruct (isEmpty segTail) eqn:Hemp.
                 --- apply isEmpty_true_iff in Hemp; subst segTail. cbn [encSegTail]. rewrite zLan.
                     exact (IH2 _ _ out Lt1 Hp1' hstep).
                 --- exact (hDump _ _ out _ _ _ segTail Lt1 Hp1' hstep).
           ++ (* h = false *)
              simpl negb in hstep.
              destruct (isEmpty segTail) eqn:Hemp; [|discriminate].
              apply isEmpty_true_iff in Hemp; subst segTail.
              destruct ((a mod 2 =? 0)%N) eqn:Ha2; split_andb.
              ** pose proof (N_even_decomp a Ha2) as Haeven.
                 destruct (((2 <=? a)%N && (1 <=? s0)%N && (a / 2 + s0 <=? En)%N)%bool) eqn:Hc; [|discriminate].
                 split_andb.
                 cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
                 replace (N.to_nat a) with (2 * ((N.to_nat (a / 2)%N - 1) + 1)) by lia.
                 replace (N.to_nat s0) with ((N.to_nat s0 - 1) + 1) by lia.
                 destruct (pipeL_transp (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat (a / 2)%N - 1) (N.to_nat s0 - 1) ltac:(lia) hp
                   (encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
                 assert (Hp1' : PipeL (N.to_nat (En - (a / 2 + s0))%N)
                   (encItems (List.rev (RIsingle a false s0 [] None :: revPref))) Lt1).
                 { apply (pipeL_eqER hp1); [lia  |].
                   rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                   replace (2 * (N.to_nat (a / 2)%N - 1 + 1)) with (N.to_nat a) by lia.
                   replace (N.to_nat s0 - 1 + 1) with (N.to_nat s0) by lia.
                   rewrite ?app_nil_r, ?append_assoc. reflexivity. }
                 exact (stepStar_trans hs1 (IH1 _ _ out Lt1 Hp1' hstep)).
              ** pose proof (N_odd_decomp a Ha2) as Haodd.
                 destruct (((2 <=? s0)%N && (a / 2 + s0 <=? En)%N)%bool) eqn:Hc1.
                 --- split_andb.
                     cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
                     rewrite Haodd. replace (N.to_nat s0) with (N.to_nat (s0 - 1)%N + 1) by lia.
                     destruct (pipeL_odd_h0_pass (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat (a / 2)%N) (N.to_nat (s0 - 1)%N) ltac:(lia) hp
                       (encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
                     assert (Hp1' : PipeL (N.to_nat (En - (a / 2 + s0))%N)
                       (encItems (List.rev (RIsingle a true (s0 - 1)%N [] None :: revPref))) Lt1).
                     { apply (pipeL_eqER hp1); [lia  |].
                       rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                       rewrite <- Haodd, ?app_nil_r, ?append_assoc. reflexivity. }
                     exact (stepStar_trans hs1 (IH1 _ _ out Lt1 Hp1' hstep)).
                 --- destruct (((a / 2 + 1 <=? En)%N && (En + 1 <=? a / 2 + s0)%N)%bool) eqn:Hc2; [|discriminate].
                     split_andb. inversion hstep; subst out.
                     cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
                     rewrite Haodd.
                     eapply evstep_trans; [apply (pipeL_odd_h0_split (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat (a / 2)%N) (N.to_nat s0) ltac:(lia) ltac:(lia) hp) |].
                     unfold HubCfg. rewrite encItems_append. cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
                     rewrite <- Haodd.
                     replace (N.to_nat En - N.to_nat (a / 2)%N - 1) with (N.to_nat (En - a / 2 - 1)%N) by lia.
                     replace (N.to_nat (a / 2)%N + N.to_nat s0 - N.to_nat En - 1) with (N.to_nat (a / 2 + s0 - En - 1)%N) by lia.
                     rewrite ?app_nil_r, ?Str_app_assoc. apply evstep_refl.
      * (* RItranspRun a b rep *)
        simpl negb in hstep.
        destruct (((2 <=? a)%N && (a mod 2 =? 0)%N && (1 <=? b)%N)%bool) eqn:Hc1; [|discriminate].
        split_andb.
        destruct ((rep * (a / 2 + b) <=? En)%N) eqn:Hc2; [|discriminate].
        split_andb.
        pose proof (N_even_decomp a ltac:(lia)) as Haeven.
        cbn [encItems]. unfold encItem. rewrite Str_app_assoc.
        replace (N.to_nat a) with (2 * ((N.to_nat (a / 2)%N - 1) + 1)) by lia.
        replace (N.to_nat b) with ((N.to_nat b - 1) + 1) by lia.
        destruct (pipeL_transpRun (En := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat (a / 2)%N - 1) (N.to_nat b - 1) (N.to_nat rep) ltac:(nia) hp
          (encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
        assert (Hp1' : PipeL (N.to_nat (En - rep * (a / 2 + b))%N)
          (encItems (List.rev (RItranspRun a b rep :: revPref))) Lt1).
        { apply (pipeL_eqER hp1); [nia  |].
          rewrite encItems_rev_cons. simpl encItem.
          replace (2 * (N.to_nat (a / 2)%N - 1 + 1)) with (N.to_nat a) by lia.
          replace (N.to_nat b - 1 + 1) with (N.to_nat b) by lia. reflexivity. }
        exact (stepStar_trans hs1 (IH1 _ _ out Lt1 Hp1' hstep)).
    + (* Phase 2 *)
      intros E_rem revPref out Lt hp hstep. cbn [step1Phases] in hstep. simpl negb in hstep.
      destruct item as [a h s0 segTail [aR|] | a b rep | a1 h1 b1 a2 h2 b2 rep | t n].
      * (* RIsingle a h s0 segTail (Some aR) *)
        destruct (((h || (1 <=? s0)%N) && (2 * (E_rem + 1) <=? aR)%N)%bool) eqn:Hc1.
        -- apply Bool.andb_true_iff in Hc1. destruct Hc1 as [Hhs H2E]. split_andb.
           inversion hstep; subst out.
           assert (Htail0 : exists rt,
             (if h then T5 else []) *> (T4 ^^ N.to_nat s0) *> encSegTail segTail *>
               encItems tail *> [S0; S1; S0; S1] *> b0 = T0 *> rt).
           { destruct h.
             - exists ([S1; S0; S0; S1] *> (T4 ^^ N.to_nat s0) *> encSegTail segTail *> encItems tail *> [S0; S1; S0; S1] *> b0). reflexivity.
             - simpl in Hhs. split_andb.
               rewrite zLan.
               replace (N.to_nat s0) with (S (N.to_nat s0 - 1)) by lia.
               rewrite zPsr.
               exists ([S1; S0; S1; S1] *> (T4 ^^ (N.to_nat s0 - 1)) *> encSegTail segTail *> encItems tail *> [S0; S1; S0; S1] *> b0). reflexivity. }
           destruct Htail0 as [rt HR].
           cbn [encItems]. unfold encItem, encSingle. rewrite ?Str_app_assoc.
           rewrite HR.
           eapply evstep_trans; [apply (pipeL_dump_wall3 (E_rem := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat a) (N.to_nat aR) ltac:(lia) hp rt) |].
           unfold HubCfg. rewrite encItems_append. cbn [encItems]. unfold encItem, encSingle.
           replace (N.to_nat a + 2 * (N.to_nat E_rem + 1)) with (N.to_nat (a + 2 * (E_rem + 1))%N) by lia.
           replace (N.to_nat aR - 2 * (N.to_nat E_rem + 1)) with (N.to_nat (aR - 2 * (E_rem + 1))%N) by lia.
           rewrite ?Str_app_assoc, HR. apply evstep_refl.
        -- destruct ((isEmpty segTail && (1 <=? s0)%N && (aR / 2 <=? E_rem)%N)%bool) eqn:Hc2; [|discriminate].
           destruct segTail as [|? ?]; [|discriminate]. cbn [isEmpty] in Hc2. split_andb.
           destruct h.
           ++ destruct ((aR mod 2 =? 0)%N) eqn:HaR2; split_andb.
              ** pose proof (N_even_decomp aR HaR2) as Hev.
                 cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
                 rewrite Hev. replace (N.to_nat s0) with ((N.to_nat s0 - 1) + 1) by lia.
                 destruct (pipeL_asplit_heal_h1_even (E_rem := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat a) (N.to_nat (aR / 2)%N) (N.to_nat s0 - 1) ltac:(lia) hp
                   (encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
                 assert (Hp1' : PipeL (N.to_nat (E_rem - aR / 2)%N)
                   (encItems (List.rev (RIsingle (a + aR + 2)%N false s0 [] None :: revPref))) Lt1).
                 { apply (pipeL_eqER hp1); [lia  |].
                   rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                   replace (N.to_nat a + 2 * N.to_nat (aR / 2)%N + 2) with (N.to_nat (a + aR + 2)%N) by lia.
                   replace (N.to_nat s0 - 1 + 1) with (N.to_nat s0) by lia.
                   rewrite ?app_nil_r, ?append_assoc. reflexivity. }
                 exact (stepStar_trans hs1 (IH2 _ _ out Lt1 Hp1' hstep)).
              ** pose proof (N_odd_decomp aR HaR2) as Hodd.
                 cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
                 rewrite Hodd. replace (N.to_nat s0) with (N.to_nat (s0 - 1)%N + 1) by lia.
                 destruct (pipeL_asplit_heal_h1_odd (E_rem := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat a) (N.to_nat (aR / 2)%N) (N.to_nat (s0 - 1)%N) ltac:(lia) hp
                   (encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
                 assert (Hp1' : PipeL (N.to_nat (E_rem - aR / 2)%N)
                   (encItems (List.rev (RIsingle (a + aR + 2)%N true (s0 - 1)%N [] None :: revPref))) Lt1).
                 { apply (pipeL_eqER hp1); [lia  |].
                   rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                   replace (N.to_nat a + 2 * N.to_nat (aR / 2)%N + 3) with (N.to_nat (a + aR + 2)%N) by lia.
                   rewrite ?app_nil_r, ?append_assoc. reflexivity. }
                 exact (stepStar_trans hs1 (IH2 _ _ out Lt1 Hp1' hstep)).
           ++ destruct ((aR mod 2 =? 0)%N) eqn:HaR2; split_andb.
              ** pose proof (N_even_decomp aR HaR2) as Hev.
                 cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
                 rewrite Hev. replace (N.to_nat s0) with (N.to_nat (s0 - 1)%N + 1) by lia.
                 destruct (pipeL_asplit_heal_h0_even (E_rem := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat a) (N.to_nat (aR / 2)%N) (N.to_nat (s0 - 1)%N) ltac:(lia) hp
                   (encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
                 eapply evstep_trans; [exact hs1 |].
                 destruct ((s0 - 1 <=? E_rem - aR / 2)%N) eqn:HEr; split_andb.
                 --- destruct (pipeL_eat_t4 (En := ltac:(match type of hp1 with PipeL ?e _ _ => exact e end)) (N.to_nat (s0 - 1)%N) ltac:(lia) hp1
                       (encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt2 [hp2 hs2]].
                     assert (Hp2' : PipeL (N.to_nat (E_rem - aR / 2 - (s0 - 1))%N)
                       (encItems (List.rev (RIsingle (a + aR + 1)%N false s0 [] None :: revPref))) Lt2).
                     { apply (pipeL_eqER hp2); [lia  |].
                       rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                       replace (N.to_nat a + 2 * N.to_nat (aR / 2)%N + 1) with (N.to_nat (a + aR + 1)%N) by lia.
                       rewrite ?app_nil_r, ?append_assoc, <- list_pow_add.
                       replace (1 + N.to_nat (s0 - 1)%N) with (N.to_nat s0) by lia. reflexivity. }
                     exact (stepStar_trans hs2 (IH1 _ _ out Lt2 Hp2' hstep)).
                 --- inversion hstep; subst out.
                     set (Er := N.to_nat (E_rem - aR / 2)%N).
                     assert (Hbs : (T4 ^^ N.to_nat (s0 - 1)%N) *> encItems tail *> [S0; S1; S0; S1] *> b0 =
                                   (T4 ^^ Er) *> T4 *> (T4 ^^ (N.to_nat (s0 - 1)%N - Er - 1)) *> encItems tail *> [S0; S1; S0; S1] *> b0).
                     { replace (N.to_nat (s0 - 1)%N) with (Er + (1 + (N.to_nat (s0 - 1)%N - Er - 1))) at 1 by (unfold Er; lia).
                       rewrite !pow_add_blank, zP1. reflexivity. }
                     rewrite Hbs.
                     assert (Hp1e : PipeL Er ((encItems (List.rev revPref) ++ (T2 ^^ (N.to_nat a + 2 * N.to_nat (aR / 2)%N + 1))) ++ (T4 ^^ 1)) Lt1).
                     { apply (pipeL_eqER hp1); [unfold Er; lia  | reflexivity]. }
                     destruct (pipeL_eat_t4 Er (Nat.le_refl _) Hp1e
                       (T4 *> (T4 ^^ (N.to_nat (s0 - 1)%N - Er - 1)) *> encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt2 [hp2 hs2]].
                     replace (Er - Er) with 0 in hp2 by lia.
                     eapply evstep_trans; [exact hs2 |].
                     change (T4 *> (T4 ^^ (N.to_nat (s0 - 1)%N - Er - 1)) *> encItems tail *> [S0; S1; S0; S1] *> b0) with
                       ([S0; S1] *> T3 *> (T4 ^^ (N.to_nat (s0 - 1)%N - Er - 1)) *> encItems tail *> [S0; S1; S0; S1] *> b0).
                     eapply evstep_trans; [apply (PipeL_unwind hp2) |].
                     unfold HubCfg. rewrite encItems_append. cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
                     rewrite ?app_nil_r, ?Str_app_assoc, <- pow_add_blank.
                     replace (N.to_nat a + 2 * N.to_nat (aR / 2)%N + 1) with (N.to_nat (a + aR + 1)%N) by lia.
                     replace (1 + Er) with (N.to_nat (E_rem - aR / 2 + 1)%N) by (unfold Er; lia).
                     replace (N.to_nat (s0 - 1)%N - Er - 1) with (N.to_nat (s0 - 1 - (E_rem - aR / 2) - 1)%N) by (unfold Er; lia).
                     apply evstep_refl.
              ** pose proof (N_odd_decomp aR HaR2) as Hodd.
                 cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
                 rewrite Hodd. replace (N.to_nat s0) with (N.to_nat (s0 - 1)%N + 1) by lia.
                 destruct (pipeL_asplit_heal_h0_odd (E_rem := ltac:(match type of hp with PipeL ?e _ _ => exact e end)) (N.to_nat a) (N.to_nat (aR / 2)%N) (N.to_nat (s0 - 1)%N) ltac:(lia) hp
                   (encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
                 eapply evstep_trans; [exact hs1 |].
                 destruct ((s0 - 1 <=? E_rem - aR / 2)%N) eqn:HEr; split_andb.
                 --- destruct (pipeL_eat_t4 (En := ltac:(match type of hp1 with PipeL ?e _ _ => exact e end)) (N.to_nat (s0 - 1)%N) ltac:(lia) hp1
                       (encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt2 [hp2 hs2]].
                     assert (Hp2' : PipeL (N.to_nat (E_rem - aR / 2 - (s0 - 1))%N)
                       (encItems (List.rev (RIsingle (a + aR + 1)%N true (s0 - 1)%N [] None :: revPref))) Lt2).
                     { apply (pipeL_eqER hp2); [lia  |].
                       rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                       replace (N.to_nat a + 2 * N.to_nat (aR / 2)%N + 2) with (N.to_nat (a + aR + 1)%N) by lia.
                       rewrite ?app_nil_r, ?append_assoc. reflexivity. }
                     exact (stepStar_trans hs2 (IH1 _ _ out Lt2 Hp2' hstep)).
                 --- inversion hstep; subst out.
                     set (Er := N.to_nat (E_rem - aR / 2)%N).
                     assert (Hbs : (T4 ^^ N.to_nat (s0 - 1)%N) *> encItems tail *> [S0; S1; S0; S1] *> b0 =
                                   (T4 ^^ Er) *> T4 *> (T4 ^^ (N.to_nat (s0 - 1)%N - Er - 1)) *> encItems tail *> [S0; S1; S0; S1] *> b0).
                     { replace (N.to_nat (s0 - 1)%N) with (Er + (1 + (N.to_nat (s0 - 1)%N - Er - 1))) at 1 by (unfold Er; lia).
                       rewrite !pow_add_blank, zP1. reflexivity. }
                     rewrite Hbs.
                     assert (Hp1e : PipeL Er ((encItems (List.rev revPref) ++ (T2 ^^ (N.to_nat a + 2 * N.to_nat (aR / 2)%N + 2))) ++ T5) Lt1).
                     { apply (pipeL_eqER hp1); [unfold Er; lia  | reflexivity]. }
                     destruct (pipeL_eat_t4 Er (Nat.le_refl _) Hp1e
                       (T4 *> (T4 ^^ (N.to_nat (s0 - 1)%N - Er - 1)) *> encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt2 [hp2 hs2]].
                     replace (Er - Er) with 0 in hp2 by lia.
                     eapply evstep_trans; [exact hs2 |].
                     change (T4 *> (T4 ^^ (N.to_nat (s0 - 1)%N - Er - 1)) *> encItems tail *> [S0; S1; S0; S1] *> b0) with
                       ([S0; S1] *> T3 *> (T4 ^^ (N.to_nat (s0 - 1)%N - Er - 1)) *> encItems tail *> [S0; S1; S0; S1] *> b0).
                     eapply evstep_trans; [apply (PipeL_unwind hp2) |].
                     unfold HubCfg. rewrite encItems_append. cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
                     rewrite ?app_nil_r, ?Str_app_assoc.
                     replace (N.to_nat a + 2 * N.to_nat (aR / 2)%N + 2) with (N.to_nat (a + aR + 1)%N) by lia.
                     replace (N.to_nat (s0 - 1)%N - Er - 1) with (N.to_nat (s0 - 1 - (E_rem - aR / 2) - 1)%N) by (unfold Er; lia).
                     apply evstep_refl.
      * (* RIsingle a h s0 segTail None *)
        destruct ((h || ((1 <=? a)%N && (1 <=? s0)%N))%bool) eqn:Hc; [|discriminate].
        assert (Hok : h = true \/ (1 <= N.to_nat a /\ 1 <= N.to_nat s0)).
        { destruct h; [left; reflexivity | right; simpl in Hc; split_andb; lia]. }
        cbn [encItems]. unfold encItem, encSingle. rewrite ?app_nil_r, ?Str_app_assoc.
        destruct (pipeL_mid_cell (N.to_nat a) h (N.to_nat s0) Hok hp
          (encSegTail segTail *> encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
        assert (Hp1' : PipeL (N.to_nat E_rem) (encItems (List.rev (RIsingle a h s0 [] None :: revPref))) Lt1).
        { eapply pipeL_eqR; [| exact hp1].
          rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
          rewrite ?app_nil_r. reflexivity. }
        rewrite !Str_app_assoc in hs1.
        eapply evstep_trans; [exact hs1 |].
        destruct (isEmpty segTail) eqn:Hemp.
        -- apply isEmpty_true_iff in Hemp; subst segTail. cbn [encSegTail]. rewrite zLan.
           exact (IH2 _ _ out Lt1 Hp1' hstep).
        -- exact (hDump _ _ out _ _ _ segTail Lt1 Hp1' hstep).
      * (* RItranspRun a b rep *)
        destruct (((1 <=? a)%N && (1 <=? b)%N)%bool) eqn:Hc; [|discriminate].
        split_andb.
        cbn [encItems]. unfold encItem. rewrite Str_app_assoc.
        replace (N.to_nat a) with ((N.to_nat a - 1) + 1) by lia.
        replace (N.to_nat b) with ((N.to_nat b - 1) + 1) by lia.
        destruct (pipeL_mid_transpRun (N.to_nat a - 1) (N.to_nat b - 1) (N.to_nat rep) hp
          (encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
        assert (Hp1' : PipeL (N.to_nat E_rem) (encItems (List.rev (RItranspRun a b rep :: revPref))) Lt1).
        { eapply pipeL_eqR; [| exact hp1].
          rewrite encItems_rev_cons. simpl encItem.
          replace (N.to_nat a - 1 + 1) with (N.to_nat a) by lia.
          replace (N.to_nat b - 1 + 1) with (N.to_nat b) by lia. reflexivity. }
        exact (stepStar_trans hs1 (IH2 _ _ out Lt1 Hp1' hstep)).
      * (* RIpairRun a1 h1 b1 a2 h2 b2 rep *)
        destruct (((h1 || ((1 <=? a1)%N && (1 <=? b1)%N)) && (h2 || ((1 <=? a2)%N && (1 <=? b2)%N)))%bool) eqn:Hc; [|discriminate].
        apply Bool.andb_true_iff in Hc. destruct Hc as [Hc1 Hc2].
        assert (Hok1 : h1 = true \/ (1 <= N.to_nat a1 /\ 1 <= N.to_nat b1)).
        { destruct h1; [left; reflexivity | right; simpl in Hc1; split_andb; lia]. }
        assert (Hok2 : h2 = true \/ (1 <= N.to_nat a2 /\ 1 <= N.to_nat b2)).
        { destruct h2; [left; reflexivity | right; simpl in Hc2; split_andb; lia]. }
        destruct (pipeL_mid_pairRun (N.to_nat a1) h1 (N.to_nat b1) (N.to_nat a2) h2 (N.to_nat b2) (N.to_nat rep)
          Hok1 Hok2 hp (encItems tail *> [S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
        cbn [encItems]. unfold encItem. rewrite Str_app_assoc.
        assert (Hp1' : PipeL (N.to_nat E_rem) (encItems (List.rev (RIpairRun a1 h1 b1 a2 h2 b2 rep :: revPref))) Lt1).
        { eapply pipeL_eqR; [| exact hp1].
          rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
          rewrite ?app_nil_r. reflexivity. }
        unfold encSingle; cbn [encSegTail]. rewrite ?app_nil_r.
        exact (stepStar_trans hs1 (IH2 _ _ out Lt1 Hp1' hstep)).
      * discriminate.
Qed.

Lemma step1Hub_sound {xs ys : list RleItem} (h : step1Hub xs = Some ys) :
  (HubCfg xs) -[ tm ]->* (HubCfg ys).
Proof.
  unfold step1Hub in h.
  destruct xs as [|[a0 h0 b0_v [|? ?] [?|] | | |] rest]; try discriminate.
  destruct h0.
  - simpl negb in h.
    destruct (((2 <=? a0)%N && (a0 mod 2 =? 0)%N && (2 <=? b0_v)%N && (b0_v <=? a0 / 2)%N)%bool) eqn:Hc; [|discriminate].
    split_andb.
    pose proof (N_even_decomp a0 ltac:(lia)) as Hev.
    destruct (pipeL_start_c0_h1 (N.to_nat (a0 / 2)%N - 1) (N.to_nat b0_v - 1) ltac:(lia)
      (encItems rest *> [S0; S1; S0; S1] *> b0)) as [Lt [hp hstart]].
    assert (Hp' : PipeL (N.to_nat (a0 / 2 - b0_v)%N)
      (encItems (List.rev [RIsingle (a0 + 3)%N false b0_v [] None])) Lt).
    { apply (pipeL_eqER hp); [lia  |].
      cbn [List.rev app encItems]. unfold encItem, encSingle; cbn [encSegTail].
      replace (2 * (N.to_nat (a0 / 2)%N - 1) + 5) with (N.to_nat (a0 + 3)%N) by lia.
      replace (N.to_nat b0_v - 1 + 1) with (N.to_nat b0_v) by lia.
      rewrite ?app_nil_r. reflexivity. }
    unfold HubCfg. cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
    rewrite ?app_nil_r, ?Str_app_assoc.
    replace (N.to_nat a0) with (2 * (N.to_nat (a0 / 2)%N - 1) + 2) by lia.
    replace (N.to_nat b0_v) with (N.to_nat b0_v - 1 + 1) by lia.
    exact (stepStar_trans hstart (proj1 (step1Phases_sound rest) _ _ ys Lt Hp' h)).
  - simpl negb in h.
    destruct (((3 <=? a0)%N && (a0 mod 2 =? 1)%N && (3 <=? b0_v)%N && (b0_v - 2 <=? a0 / 2)%N)%bool) eqn:Hc; [|discriminate].
    split_andb.
    assert (Haodd_ne : (a0 mod 2)%N <> 0%N) by lia.
    pose proof (N_odd_decomp a0 Haodd_ne) as Hodd.
    destruct (pipeL_start_c0_h0 (N.to_nat (a0 / 2)%N) (N.to_nat (b0_v - 2)%N) ltac:(lia)
      (encItems rest *> [S0; S1; S0; S1] *> b0)) as [Lt [hp hstart]].
    assert (Hp' : PipeL (N.to_nat (a0 / 2 - (b0_v - 2))%N)
      (encItems (List.rev [RIsingle (a0 + 3)%N true (b0_v - 2)%N [] None])) Lt).
    { apply (pipeL_eqER hp); [lia  |].
      cbn [List.rev app encItems]. unfold encItem, encSingle; cbn [encSegTail].
      replace (2 * N.to_nat (a0 / 2)%N + 4) with (N.to_nat (a0 + 3)%N) by lia.
      rewrite ?app_nil_r. reflexivity. }
    unfold HubCfg. cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
    rewrite ?app_nil_r, ?Str_app_assoc, Hodd.
    replace (N.to_nat b0_v) with (N.to_nat (b0_v - 2)%N + 2) by lia.
    exact (stepStar_trans hstart (proj1 (step1Phases_sound rest) _ _ ys Lt Hp' h)).
Qed.

Lemma list_pow_phase_shift (u v : list Sym) (n : nat) :
  u ++ ((v ++ u) ^^ n) = ((u ++ v) ^^ n) ++ u.
Proof.
  induction n as [|n IH].
  - rewrite !list_pow_zero, app_nil_r. reflexivity.
  - replace (S n) with (n + 1) by lia.
    rewrite (list_pow_succ (v ++ u) n), (list_pow_succ (u ++ v) n).
    rewrite <- (append_assoc u (v ++ u) ((v ++ u) ^^ n)).
    rewrite <- (append_assoc u v u).
    rewrite (append_assoc (u ++ v) u ((v ++ u) ^^ n)).
    rewrite IH.
    rewrite <- (append_assoc (u ++ v) ((u ++ v) ^^ n) u).
    reflexivity.
Qed.

Lemma applyNormHead_sound {op : NormOp} {xs ys : list RleItem}
    (h : applyNormHead op xs = Some ys) : encItems xs = encItems ys.
Proof.
  destruct op as [i k | i | i]; cbn [applyNormHead] in h.
  - destruct xs as [|x rest]; [discriminate |].
    destruct x as [| a b n | |]; try discriminate.
    destruct ((k <=? n)%N) eqn:Hle; [|discriminate]. split_andb.
    inversion h; subst ys. cbn [encItems]. unfold encItem.
    rewrite <- append_assoc, <- list_pow_add.
    replace (N.to_nat k + N.to_nat (n - k)%N) with (N.to_nat n) by lia. reflexivity.
  - destruct xs as [|x rest]; [discriminate |].
    destruct x as [| a b n | |]; try discriminate.
    destruct ((n =? 1)%N) eqn:Hn1; [|discriminate]. split_andb.
    inversion h; subst ys. cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
    subst n. simpl N.to_nat. rewrite list_pow_one, ?app_nil_r. reflexivity.
  - destruct xs as [|x1 xs1]; [discriminate |].
    destruct x1 as [a1 h1 b1 seg1 aR1 | | |]; try discriminate.
    destruct seg1 as [|? ?]; [|discriminate].
    destruct aR1 as [?|]; [discriminate |].
    destruct xs1 as [|x2 rest]; [discriminate |].
    destruct x2 as [| | a2 h2 b2 u1 j1 c1 n |]; try discriminate.
    destruct (((a1 =? u1)%N && Bool.eqb h1 j1 && (b1 =? c1)%N)%bool) eqn:Heq; [|discriminate].
    split_andb. subst u1 j1 c1. inversion h; subst ys.
    cbn [encItems]. unfold encItem.
    set (U := encSingle a1 h1 b1 [] None).
    set (V := encSingle a2 h2 b2 [] None).
    rewrite <- (append_assoc U ((V ++ U) ^^ N.to_nat n) (encItems rest)).
    rewrite (list_pow_phase_shift U V (N.to_nat n)).
    rewrite (append_assoc ((U ++ V) ^^ N.to_nat n) U (encItems rest)).
    reflexivity.
Qed.

Lemma applyNorm_sound {op : NormOp} {xs ys : list RleItem}
    (h : applyNorm op xs = Some ys) : encItems xs = encItems ys.
Proof.
  unfold applyNorm in h.
  destruct (splitAtList (normOpIndex op) xs) as [[pref suf]|] eqn:Hsp; [|discriminate].
  apply option_map_Some in h. destruct h as [suf' [H1 H2]]; subst ys.
  rewrite (splitAtList_sound _ _ _ _ Hsp), !encItems_append, (applyNormHead_sound H1).
  reflexivity.
Qed.

