Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

(* ========================================================================= *)
(* Section 9.2: Fast Prefix Runner step1Pref & step1HubPrefix                *)
(* ========================================================================= *)

Lemma step1Pref_sound (rest : list RleItem) :
  (forall (En : N) (revPref : list RleItem) (isP2 : bool) (E' : N) (revOut : list RleItem)
          (Lt r : Stream Sym),
    PipeL (N.to_nat En) (encItems (List.rev revPref)) Lt ->
    step1Pref false En revPref rest = Some (isP2, E', revOut) ->
    exists Lt', PipeL (N.to_nat E') (encItems (List.rev revOut)) Lt' /\
      (([S1; S1] *> Lt) {{F}}> (encItems rest *> r)) -[ tm ]->*
        (if isP2 then (([S1] *> T2 *> Lt') {{A}}> r) else (([S1; S1] *> Lt') {{F}}> r)))
  /\
  (forall (E_rem : N) (revPref : list RleItem) (isP2 : bool) (E' : N) (revOut : list RleItem)
          (Lt r : Stream Sym),
    PipeL (N.to_nat E_rem) (encItems (List.rev revPref)) Lt ->
    step1Pref true E_rem revPref rest = Some (isP2, E', revOut) ->
    exists Lt', PipeL (N.to_nat E') (encItems (List.rev revOut)) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> (encItems rest *> r)) -[ tm ]->*
        (if isP2 then (([S1] *> T2 *> Lt') {{A}}> r) else (([S1; S1] *> Lt') {{F}}> r))).
Proof.
  induction rest as [|item tail [IH1 IH2]].
  - split.
    + intros En revPref isP2 E' revOut Lt r hp hstep.
      cbn [step1Pref] in hstep. inversion hstep; subst.
      exists Lt. split; [exact hp | cbn [encItems]; rewrite zLan; apply evstep_refl].
    + intros E_rem revPref isP2 E' revOut Lt r hp hstep.
      cbn [step1Pref] in hstep. simpl negb in hstep. inversion hstep; subst.
      exists Lt. split; [exact hp | cbn [encItems]; rewrite zLan; apply evstep_refl].
  - split.
    + intros En revPref isP2 E' revOut Lt r hp hstep.
      cbn [step1Pref] in hstep.
      destruct item as [a h s0 segTail [aR|] | a b rep | a1 h1 b1 a2 h2 b2 rep | t n]; try discriminate.
      * destruct (((1 <=? a)%N && (a / 2 <? En)%N)%bool) eqn:Hc1; [|discriminate].
        split_andb.
        destruct h.
        -- simpl negb in hstep.
           destruct ((isEmpty segTail && (1 <=? s0)%N)%bool) eqn:Hc2; [|discriminate].
           destruct segTail as [|? ?]; [|discriminate]. cbn [isEmpty] in Hc2. split_andb.
           destruct ((a mod 2 =? 0)%N) eqn:Ha2; split_andb.
           ++ pose proof (N_even_decomp a Ha2) as Hev.
              assert (Hle : N.to_nat (a / 2)%N + 1 <= N.to_nat En) by lia.
              destruct (pipeL_h1_enter_even (N.to_nat (a / 2)%N) (N.to_nat s0 - 1) Hle hp
                (encItems tail *> r)) as [Lt1 [hp1 hs1]].
              assert (Hp1' : PipeL (N.to_nat (En - a / 2 - 1)%N)
                (encItems (List.rev (RIsingle (a + 1)%N false s0 [] None :: revPref))) Lt1).
              { apply (pipeL_eqER hp1); [lia |].
                rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                replace (2 * N.to_nat (a / 2)%N + 1) with (N.to_nat (a + 1)%N) by lia.
                replace (N.to_nat s0 - 1 + 1) with (N.to_nat s0) by lia.
                rewrite ?app_nil_r, ?append_assoc. reflexivity. }
              destruct (IH2 _ _ isP2 E' revOut Lt1 r Hp1' hstep) as [Lt2 [hp2 hs2]].
              exists Lt2. split; [exact hp2 |].
              assert (HR : encItems (RIsingle a true s0 [] None :: tail) *> r =
                           (T2 ^^ (2 * N.to_nat (a / 2)%N)) *> T5 *> (T4 ^^ (N.to_nat s0 - 1 + 1)) *> encItems tail *> r).
              { cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
                rewrite Hev, ?app_nil_r, ?Str_app_assoc.
                replace (N.to_nat s0 - 1 + 1) with (N.to_nat s0) by lia. reflexivity. }
              rewrite HR. exact (stepStar_trans hs1 hs2).
           ++ pose proof (N_odd_decomp a Ha2) as Hodd.
              assert (Hle : N.to_nat (a / 2)%N + 1 <= N.to_nat En) by lia.
              destruct (pipeL_h1_enter_odd (N.to_nat (a / 2)%N) (N.to_nat (s0 - 1)%N) Hle hp
                (encItems tail *> r)) as [Lt1 [hp1 hs1]].
              assert (Hp1' : PipeL (N.to_nat (En - a / 2 - 1)%N)
                (encItems (List.rev (RIsingle (a + 1)%N true (s0 - 1)%N [] None :: revPref))) Lt1).
              { apply (pipeL_eqER hp1); [lia |].
                rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                replace (2 * N.to_nat (a / 2)%N + 2) with (N.to_nat (a + 1)%N) by lia.
                rewrite ?app_nil_r, ?append_assoc. reflexivity. }
              destruct (IH2 _ _ isP2 E' revOut Lt1 r Hp1' hstep) as [Lt2 [hp2 hs2]].
              exists Lt2. split; [exact hp2 |].
              assert (HR : encItems (RIsingle a true s0 [] None :: tail) *> r =
                           (T2 ^^ (2 * N.to_nat (a / 2)%N + 1)) *> T5 *> (T4 ^^ (N.to_nat (s0 - 1)%N + 1)) *> encItems tail *> r).
              { cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
                rewrite Hodd, ?app_nil_r, ?Str_app_assoc.
                replace (N.to_nat (s0 - 1)%N + 1) with (N.to_nat s0) by lia. reflexivity. }
              rewrite HR. exact (stepStar_trans hs1 hs2).
        -- simpl negb in hstep.
           destruct (isEmpty segTail) eqn:Hemp; [|discriminate].
           apply isEmpty_true_iff in Hemp; subst segTail.
           destruct ((a mod 2 =? 1)%N) eqn:Ha2; split_andb.
           ++ assert (Haodd_ne : (a mod 2)%N <> 0%N) by lia.
              pose proof (N_odd_decomp a Haodd_ne) as Hodd.
              destruct (((1 <=? s0)%N && (s0 <=? En - a / 2)%N)%bool) eqn:Hsb; [|discriminate].
              split_andb.
              assert (Hle : N.to_nat (a / 2)%N + N.to_nat (s0 - 1)%N + 1 <= N.to_nat En) by lia.
              destruct (pipeL_odd_h0_pass (N.to_nat (a / 2)%N) (N.to_nat (s0 - 1)%N) Hle hp
                (encItems tail *> r)) as [Lt1 [hp1 hs1]].
              assert (Hp1' : PipeL (N.to_nat (En - a / 2 - s0)%N)
                (encItems (List.rev (RIsingle a true (s0 - 1)%N [] None :: revPref))) Lt1).
              { apply (pipeL_eqER hp1); [lia |].
                rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                rewrite <- Hodd, ?app_nil_r, ?append_assoc. reflexivity. }
              destruct (IH1 _ _ isP2 E' revOut Lt1 r Hp1' hstep) as [Lt2 [hp2 hs2]].
              exists Lt2. split; [exact hp2 |].
              assert (HR : encItems (RIsingle a false s0 [] None :: tail) *> r =
                           (T2 ^^ (2 * N.to_nat (a / 2)%N + 1)) *> (T4 ^^ (N.to_nat (s0 - 1)%N + 1)) *> encItems tail *> r).
              { cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
                rewrite Hodd, ?app_nil_r, ?Str_app_assoc.
                replace (N.to_nat (s0 - 1)%N + 1) with (N.to_nat s0) by lia. reflexivity. }
              rewrite HR. exact (stepStar_trans hs1 hs2).
           ++ pose proof (N.mod_lt a 2 ltac:(discriminate)) as Hmlt.
              assert (Ha0 : (a mod 2)%N = 0%N) by lia.
              pose proof (N_even_decomp a Ha0) as Hev.
              destruct (((2 <=? a)%N && (1 <=? s0)%N && (s0 <=? En - a / 2)%N)%bool) eqn:Hsb; [|discriminate].
              split_andb.
              assert (Hle : (N.to_nat (a / 2)%N - 1) + (N.to_nat s0 - 1) + 2 <= N.to_nat En) by lia.
              destruct (pipeL_transp (N.to_nat (a / 2)%N - 1) (N.to_nat s0 - 1) Hle hp
                (encItems tail *> r)) as [Lt1 [hp1 hs1]].
              assert (Hp1' : PipeL (N.to_nat (En - a / 2 - s0)%N)
                (encItems (List.rev (RIsingle a false s0 [] None :: revPref))) Lt1).
              { apply (pipeL_eqER hp1); [lia |].
                rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                replace (2 * (N.to_nat (a / 2)%N - 1 + 1)) with (N.to_nat a) by lia.
                replace (N.to_nat s0 - 1 + 1) with (N.to_nat s0) by lia.
                rewrite ?app_nil_r, ?append_assoc. reflexivity. }
              destruct (IH1 _ _ isP2 E' revOut Lt1 r Hp1' hstep) as [Lt2 [hp2 hs2]].
              exists Lt2. split; [exact hp2 |].
              assert (HR : encItems (RIsingle a false s0 [] None :: tail) *> r =
                           (T2 ^^ (2 * ((N.to_nat (a / 2)%N - 1) + 1))) *> (T4 ^^ (N.to_nat s0 - 1 + 1)) *> encItems tail *> r).
              { cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
                rewrite ?app_nil_r, ?Str_app_assoc.
                replace (2 * (N.to_nat (a / 2)%N - 1 + 1)) with (N.to_nat a) by lia.
                replace (N.to_nat s0 - 1 + 1) with (N.to_nat s0) by lia. reflexivity. }
              rewrite HR. exact (stepStar_trans hs1 hs2).
      * simpl negb in hstep.
        destruct (((2 <=? a)%N && (a mod 2 =? 0)%N && (1 <=? b)%N)%bool) eqn:Hc1; [|discriminate].
        split_andb.
        destruct ((rep * (a / 2 + b) <=? En)%N) eqn:Hc2; [|discriminate].
        split_andb.
        pose proof (N_even_decomp a ltac:(lia)) as Hev.
        assert (Hle : N.to_nat rep * ((N.to_nat (a / 2)%N - 1) + (N.to_nat b - 1) + 2) <= N.to_nat En) by nia.
        destruct (pipeL_transpRun (N.to_nat (a / 2)%N - 1) (N.to_nat b - 1) (N.to_nat rep) Hle hp
          (encItems tail *> r)) as [Lt1 [hp1 hs1]].
        assert (Hp1' : PipeL (N.to_nat (En - rep * (a / 2 + b))%N)
          (encItems (List.rev (RItranspRun a b rep :: revPref))) Lt1).
        { apply (pipeL_eqER hp1); [nia |].
          rewrite encItems_rev_cons. simpl encItem.
          replace (2 * (N.to_nat (a / 2)%N - 1 + 1)) with (N.to_nat a) by lia.
          replace (N.to_nat b - 1 + 1) with (N.to_nat b) by lia. reflexivity. }
        destruct (IH1 _ _ isP2 E' revOut Lt1 r Hp1' hstep) as [Lt2 [hp2 hs2]].
        exists Lt2. split; [exact hp2 |].
        assert (HR : encItems (RItranspRun a b rep :: tail) *> r =
                     (((T2 ^^ (2 * ((N.to_nat (a / 2)%N - 1) + 1))) ++ (T4 ^^ (N.to_nat b - 1 + 1))) ^^ N.to_nat rep) *> encItems tail *> r).
        { cbn [encItems]. unfold encItem. rewrite Str_app_assoc.
          replace (2 * (N.to_nat (a / 2)%N - 1 + 1)) with (N.to_nat a) by lia.
          replace (N.to_nat b - 1 + 1) with (N.to_nat b) by lia. reflexivity. }
        rewrite HR. exact (stepStar_trans hs1 hs2).
    + intros E_rem revPref isP2 E' revOut Lt r hp hstep.
      cbn [step1Pref] in hstep. simpl negb in hstep.
      destruct item as [a h s0 [|? ?] [aR|] | a b rep | a1 h1 b1 a2 h2 b2 rep | t n]; try discriminate.
      * destruct (((1 <=? s0)%N && (aR / 2 <=? E_rem)%N)%bool) eqn:Hc1; [|discriminate].
        split_andb.
        assert (Hqle : N.to_nat (aR / 2)%N <= N.to_nat E_rem) by lia.
        destruct h.
        -- destruct ((aR mod 2 =? 0)%N) eqn:HaR2; split_andb.
           ++ pose proof (N_even_decomp aR HaR2) as Hev.
              destruct (pipeL_asplit_heal_h1_even (N.to_nat a) (N.to_nat (aR / 2)%N) (N.to_nat s0 - 1) Hqle hp
                (encItems tail *> r)) as [Lt1 [hp1 hs1]].
              assert (Hp1' : PipeL (N.to_nat (E_rem - aR / 2)%N)
                (encItems (List.rev (RIsingle (a + aR + 2)%N false s0 [] None :: revPref))) Lt1).
              { apply (pipeL_eqER hp1); [lia |].
                rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                replace (N.to_nat a + 2 * N.to_nat (aR / 2)%N + 2) with (N.to_nat (a + aR + 2)%N) by lia.
                replace (N.to_nat s0 - 1 + 1) with (N.to_nat s0) by lia.
                rewrite ?app_nil_r, ?append_assoc. reflexivity. }
              destruct (IH2 _ _ isP2 E' revOut Lt1 r Hp1' hstep) as [Lt2 [hp2 hs2]].
              exists Lt2. split; [exact hp2 |].
              assert (HR : encItems (RIsingle a true s0 [] (Some aR) :: tail) *> r =
                           (T2 ^^ N.to_nat a) *> T0 *> (T2 ^^ (2 * N.to_nat (aR / 2)%N)) *> T5 *> (T4 ^^ (N.to_nat s0 - 1 + 1)) *> encItems tail *> r).
              { cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
                rewrite Hev, ?app_nil_r, ?Str_app_assoc.
                replace (N.to_nat s0 - 1 + 1) with (N.to_nat s0) by lia. reflexivity. }
              rewrite HR. exact (stepStar_trans hs1 hs2).
           ++ pose proof (N_odd_decomp aR HaR2) as Hodd.
              destruct (pipeL_asplit_heal_h1_odd (N.to_nat a) (N.to_nat (aR / 2)%N) (N.to_nat (s0 - 1)%N) Hqle hp
                (encItems tail *> r)) as [Lt1 [hp1 hs1]].
              assert (Hp1' : PipeL (N.to_nat (E_rem - aR / 2)%N)
                (encItems (List.rev (RIsingle (a + aR + 2)%N true (s0 - 1)%N [] None :: revPref))) Lt1).
              { apply (pipeL_eqER hp1); [lia |].
                rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                replace (N.to_nat a + 2 * N.to_nat (aR / 2)%N + 3) with (N.to_nat (a + aR + 2)%N) by lia.
                rewrite ?app_nil_r, ?append_assoc. reflexivity. }
              destruct (IH2 _ _ isP2 E' revOut Lt1 r Hp1' hstep) as [Lt2 [hp2 hs2]].
              exists Lt2. split; [exact hp2 |].
              assert (HR : encItems (RIsingle a true s0 [] (Some aR) :: tail) *> r =
                           (T2 ^^ N.to_nat a) *> T0 *> (T2 ^^ (2 * N.to_nat (aR / 2)%N + 1)) *> T5 *> (T4 ^^ (N.to_nat (s0 - 1)%N + 1)) *> encItems tail *> r).
              { cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
                rewrite Hodd, ?app_nil_r, ?Str_app_assoc.
                replace (N.to_nat (s0 - 1)%N + 1) with (N.to_nat s0) by lia. reflexivity. }
              rewrite HR. exact (stepStar_trans hs1 hs2).
        -- destruct ((aR mod 2 =? 0)%N) eqn:HaR2; split_andb.
           ++ pose proof (N_even_decomp aR HaR2) as Hev.
              destruct ((s0 - 1 <=? E_rem - aR / 2)%N) eqn:HEr; [|discriminate]. split_andb.
              destruct (pipeL_asplit_heal_h0_even (N.to_nat a) (N.to_nat (aR / 2)%N) (N.to_nat (s0 - 1)%N) Hqle hp
                (encItems tail *> r)) as [Lt1 [hp1 hs1]].
              assert (Hle2 : N.to_nat (s0 - 1)%N <= N.to_nat E_rem - N.to_nat (aR / 2)%N) by lia.
              destruct (pipeL_eat_t4 (N.to_nat (s0 - 1)%N) Hle2 hp1 (encItems tail *> r)) as [Lt2 [hp2 hs2]].
              assert (Hp2' : PipeL (N.to_nat (E_rem - aR / 2 - (s0 - 1))%N)
                (encItems (List.rev (RIsingle (a + aR + 1)%N false s0 [] None :: revPref))) Lt2).
              { apply (pipeL_eqER hp2); [lia |].
                rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                replace (N.to_nat a + 2 * N.to_nat (aR / 2)%N + 1) with (N.to_nat (a + aR + 1)%N) by lia.
                rewrite ?app_nil_r, ?append_assoc, <- list_pow_add.
                replace (1 + N.to_nat (s0 - 1)%N) with (N.to_nat s0) by lia. reflexivity. }
              destruct (IH1 _ _ isP2 E' revOut Lt2 r Hp2' hstep) as [Lt3 [hp3 hs3]].
              exists Lt3. split; [exact hp3 |].
              assert (HR : encItems (RIsingle a false s0 [] (Some aR) :: tail) *> r =
                           (T2 ^^ N.to_nat a) *> T0 *> (T2 ^^ (2 * N.to_nat (aR / 2)%N)) *> (T4 ^^ (N.to_nat (s0 - 1)%N + 1)) *> encItems tail *> r).
              { cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
                rewrite Hev, ?app_nil_r, ?Str_app_assoc.
                replace (N.to_nat (s0 - 1)%N + 1) with (N.to_nat s0) by lia. reflexivity. }
              rewrite HR. exact (stepStar_trans hs1 (stepStar_trans hs2 hs3)).
           ++ pose proof (N_odd_decomp aR HaR2) as Hodd.
              destruct ((s0 - 1 <=? E_rem - aR / 2)%N) eqn:HEr; [|discriminate]. split_andb.
              destruct (pipeL_asplit_heal_h0_odd (N.to_nat a) (N.to_nat (aR / 2)%N) (N.to_nat (s0 - 1)%N) Hqle hp
                (encItems tail *> r)) as [Lt1 [hp1 hs1]].
              assert (Hle2 : N.to_nat (s0 - 1)%N <= N.to_nat E_rem - N.to_nat (aR / 2)%N) by lia.
              destruct (pipeL_eat_t4 (N.to_nat (s0 - 1)%N) Hle2 hp1 (encItems tail *> r)) as [Lt2 [hp2 hs2]].
              assert (Hp2' : PipeL (N.to_nat (E_rem - aR / 2 - (s0 - 1))%N)
                (encItems (List.rev (RIsingle (a + aR + 1)%N true (s0 - 1)%N [] None :: revPref))) Lt2).
              { apply (pipeL_eqER hp2); [lia |].
                rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
                replace (N.to_nat a + 2 * N.to_nat (aR / 2)%N + 2) with (N.to_nat (a + aR + 1)%N) by lia.
                rewrite ?app_nil_r, ?append_assoc. reflexivity. }
              destruct (IH1 _ _ isP2 E' revOut Lt2 r Hp2' hstep) as [Lt3 [hp3 hs3]].
              exists Lt3. split; [exact hp3 |].
              assert (HR : encItems (RIsingle a false s0 [] (Some aR) :: tail) *> r =
                           (T2 ^^ N.to_nat a) *> T0 *> (T2 ^^ (2 * N.to_nat (aR / 2)%N + 1)) *> (T4 ^^ (N.to_nat (s0 - 1)%N + 1)) *> encItems tail *> r).
              { cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail].
                rewrite Hodd, ?app_nil_r, ?Str_app_assoc.
                replace (N.to_nat (s0 - 1)%N + 1) with (N.to_nat s0) by lia. reflexivity. }
              rewrite HR. exact (stepStar_trans hs1 (stepStar_trans hs2 hs3)).
      * destruct (((1 <=? a)%N && (1 <=? s0)%N)%bool) eqn:Hc; [|discriminate]. split_andb.
        assert (Hok : h = true \/ (1 <= N.to_nat a /\ 1 <= N.to_nat s0)) by (right; lia).
        destruct (pipeL_mid_cell (N.to_nat a) h (N.to_nat s0) Hok hp (encItems tail *> r)) as [Lt1 [hp1 hs1]].
        assert (Hp1' : PipeL (N.to_nat E_rem)
          (encItems (List.rev (RIsingle a h s0 [] None :: revPref))) Lt1).
        { eapply pipeL_eqR; [| exact hp1].
          rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
          rewrite ?app_nil_r, ?append_assoc. reflexivity. }
        destruct (IH2 _ _ isP2 E' revOut Lt1 r Hp1' hstep) as [Lt2 [hp2 hs2]].
        exists Lt2. split; [exact hp2 |].
        assert (HR : encItems (RIsingle a h s0 [] None :: tail) *> r =
                     (((T2 ^^ N.to_nat a) ++ (if h then T5 else [])) ++ (T4 ^^ N.to_nat s0)) *> encItems tail *> r).
        { cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail]. rewrite ?app_nil_r, Str_app_assoc. reflexivity. }
        rewrite HR. exact (stepStar_trans hs1 hs2).
      * destruct (((1 <=? a)%N && (1 <=? b)%N)%bool) eqn:Hc; [|discriminate]. split_andb.
        destruct (pipeL_mid_transpRun (N.to_nat a - 1) (N.to_nat b - 1) (N.to_nat rep) hp
          (encItems tail *> r)) as [Lt1 [hp1 hs1]].
        assert (Hp1' : PipeL (N.to_nat E_rem)
          (encItems (List.rev (RItranspRun a b rep :: revPref))) Lt1).
        { eapply pipeL_eqR; [| exact hp1].
          rewrite encItems_rev_cons. simpl encItem.
          replace (N.to_nat a - 1 + 1) with (N.to_nat a) by lia.
          replace (N.to_nat b - 1 + 1) with (N.to_nat b) by lia. reflexivity. }
        destruct (IH2 _ _ isP2 E' revOut Lt1 r Hp1' hstep) as [Lt2 [hp2 hs2]].
        exists Lt2. split; [exact hp2 |].
        assert (HR : encItems (RItranspRun a b rep :: tail) *> r =
                     (((T2 ^^ (N.to_nat a - 1 + 1)) ++ (T4 ^^ (N.to_nat b - 1 + 1))) ^^ N.to_nat rep) *> encItems tail *> r).
        { cbn [encItems]. unfold encItem. rewrite Str_app_assoc.
          replace (N.to_nat a - 1 + 1) with (N.to_nat a) by lia.
          replace (N.to_nat b - 1 + 1) with (N.to_nat b) by lia. reflexivity. }
        rewrite HR. exact (stepStar_trans hs1 hs2).
      * destruct (((1 <=? a1)%N && (1 <=? b1)%N && (1 <=? a2)%N && (1 <=? b2)%N)%bool) eqn:Hc; [|discriminate].
        split_andb.
        assert (Hok1 : h1 = true \/ (1 <= N.to_nat a1 /\ 1 <= N.to_nat b1)) by (right; lia).
        assert (Hok2 : h2 = true \/ (1 <= N.to_nat a2 /\ 1 <= N.to_nat b2)) by (right; lia).
        destruct (pipeL_mid_pairRun (N.to_nat a1) h1 (N.to_nat b1) (N.to_nat a2) h2 (N.to_nat b2) (N.to_nat rep)
          Hok1 Hok2 hp (encItems tail *> r)) as [Lt1 [hp1 hs1]].
        assert (Hp1' : PipeL (N.to_nat E_rem)
          (encItems (List.rev (RIpairRun a1 h1 b1 a2 h2 b2 rep :: revPref))) Lt1).
        { eapply pipeL_eqR; [| exact hp1].
          rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
          rewrite ?app_nil_r. reflexivity. }
        destruct (IH2 _ _ isP2 E' revOut Lt1 r Hp1' hstep) as [Lt2 [hp2 hs2]].
        exists Lt2. split; [exact hp2 |].
        assert (HR : encItems (RIpairRun a1 h1 b1 a2 h2 b2 rep :: tail) *> r =
                     ((((((T2 ^^ N.to_nat a1) ++ (if h1 then T5 else [])) ++ (T4 ^^ N.to_nat b1)) ++
                       (((T2 ^^ N.to_nat a2) ++ (if h2 then T5 else [])) ++ (T4 ^^ N.to_nat b2))) ^^ N.to_nat rep) *> encItems tail *> r)).
        { cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail]. rewrite ?app_nil_r, Str_app_assoc. reflexivity. }
        rewrite HR. exact (stepStar_trans hs1 hs2).
Qed.

Lemma step1HubPrefix_gen_sound {pref : list RleItem} (r : Stream Sym)
    {isP2 : bool} {E' : N} {revOut : list RleItem}
    (h : step1HubPrefix pref = Some (isP2, E', revOut)) :
    exists Lt', PipeL (N.to_nat E') (encItems (List.rev revOut)) Lt' /\
      (b0 {{E}}> (T2 *> T0 *> T1 *> encItems pref *> r)) -[ tm ]->*
        (if isP2 then (([S1] *> T2 *> Lt') {{A}}> r)
         else (([S1; S1] *> Lt') {{F}}> r)).
Proof.
  unfold step1HubPrefix, step1PrefP1 in h.
  destruct pref as [|[a0 h0 b0_v [|? ?] [?|] | | |] rest]; try discriminate.
  destruct h0.
  - simpl negb in h.
    destruct (((2 <=? a0)%N && (a0 mod 2 =? 0)%N && (1 <=? b0_v)%N && (b0_v <=? a0 / 2)%N)%bool) eqn:Hc; [|discriminate].
    split_andb.
    pose proof (N_even_decomp a0 ltac:(lia)) as Hev.
    assert (Hle : N.to_nat b0_v - 1 <= N.to_nat (a0 / 2)%N - 1) by lia.
    destruct (pipeL_start_c0_h1 (N.to_nat (a0 / 2)%N - 1) (N.to_nat b0_v - 1) Hle (encItems rest *> r))
      as [Lt [hp hstart]].
    assert (Hp' : PipeL (N.to_nat (a0 / 2 - b0_v)%N)
      (encItems (List.rev [RIsingle (a0 + 3)%N false b0_v [] None])) Lt).
    { apply (pipeL_eqER hp); [lia |].
      cbn [List.rev app encItems]. unfold encItem, encSingle; cbn [encSegTail].
      replace (2 * (N.to_nat (a0 / 2)%N - 1) + 5) with (N.to_nat (a0 + 3)%N) by lia.
      replace (N.to_nat b0_v - 1 + 1) with (N.to_nat b0_v) by lia.
      rewrite ?app_nil_r. reflexivity. }
    destruct (proj1 (step1Pref_sound rest) _ _ isP2 E' revOut Lt r Hp' h) as [Lt' [hp'' hs2]].
    exists Lt'. split; [exact hp'' |].
    assert (HR : T2 *> T0 *> T1 *> encItems (RIsingle a0 true b0_v [] None :: rest) *> r =
                 T2 *> T0 *> T1 *> (T2 ^^ (2 * (N.to_nat (a0 / 2)%N - 1) + 2)) *> T5 *> (T4 ^^ (N.to_nat b0_v - 1 + 1)) *> encItems rest *> r).
    { cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
      replace (2 * (N.to_nat (a0 / 2)%N - 1) + 2) with (N.to_nat a0) by lia.
      replace (N.to_nat b0_v - 1 + 1) with (N.to_nat b0_v) by lia. reflexivity. }
    rewrite HR. exact (stepStar_trans hstart hs2).
  - simpl negb in h.
    destruct (((1 <=? a0)%N && (a0 mod 2 =? 1)%N && (2 <=? b0_v)%N && (b0_v - 2 <=? a0 / 2)%N)%bool) eqn:Hc; [|discriminate].
    split_andb.
    assert (Haodd_ne : (a0 mod 2)%N <> 0%N) by lia.
    pose proof (N_odd_decomp a0 Haodd_ne) as Hodd.
    assert (Hle : N.to_nat (b0_v - 2)%N <= N.to_nat (a0 / 2)%N) by lia.
    destruct (pipeL_start_c0_h0 (N.to_nat (a0 / 2)%N) (N.to_nat (b0_v - 2)%N) Hle (encItems rest *> r))
      as [Lt [hp hstart]].
    assert (Hp' : PipeL (N.to_nat (a0 / 2 - (b0_v - 2))%N)
      (encItems (List.rev [RIsingle (a0 + 3)%N true (b0_v - 2)%N [] None])) Lt).
    { apply (pipeL_eqER hp); [lia |].
      cbn [List.rev app encItems]. unfold encItem, encSingle; cbn [encSegTail].
      replace (2 * N.to_nat (a0 / 2)%N + 4) with (N.to_nat (a0 + 3)%N) by lia.
      rewrite ?app_nil_r. reflexivity. }
    destruct (proj1 (step1Pref_sound rest) _ _ isP2 E' revOut Lt r Hp' h) as [Lt' [hp'' hs2]].
    exists Lt'. split; [exact hp'' |].
    assert (HR : T2 *> T0 *> T1 *> encItems (RIsingle a0 false b0_v [] None :: rest) *> r =
                 T2 *> T0 *> T1 *> (T2 ^^ (2 * N.to_nat (a0 / 2)%N + 1)) *> (T4 ^^ (N.to_nat (b0_v - 2)%N + 2)) *> encItems rest *> r).
    { cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail]. rewrite Hodd, ?app_nil_r, ?Str_app_assoc.
      replace (N.to_nat (b0_v - 2)%N + 2) with (N.to_nat b0_v) by lia. reflexivity. }
    rewrite HR. exact (stepStar_trans hstart hs2).
Qed.

Lemma step1HubPrefix_sound {pref : list RleItem} (tail : list RleItem)
    {isP2 : bool} {E' : N} {revOut : list RleItem}
    (h : step1HubPrefix pref = Some (isP2, E', revOut)) :
    exists Lt', PipeL (N.to_nat E') (encItems (List.rev revOut)) Lt' /\
      (HubCfg (pref ++ tail)) -[ tm ]->*
        (if isP2 then (([S1] *> T2 *> Lt') {{A}}> (encItems tail *> [S0; S1; S0; S1] *> b0))
         else (([S1; S1] *> Lt') {{F}}> (encItems tail *> [S0; S1; S0; S1] *> b0))).
Proof.
  destruct (step1HubPrefix_gen_sound (encItems tail *> [S0; S1; S0; S1] *> b0) h) as [Lt' [hp hs]].
  exists Lt'. split; [exact hp |].
  unfold HubCfg. rewrite encItems_append, Str_app_assoc. exact hs.
Qed.

(* ========================================================================= *)
(* Section 9.3: Universal PipeL-Backed RawCfg Engine                         *)
(* ========================================================================= *)

Fixpoint encRuns (xs : list (Tok * N)) : list Sym :=
  match xs with
  | [] => []
  | (t, n) :: rest => ((encTok t) ^^ N.to_nat n) ++ encRuns rest
  end.

Lemma encRuns_append (xs ys : list (Tok * N)) :
  encRuns (xs ++ ys) = encRuns xs ++ encRuns ys.
Proof.
  induction xs as [|[t n] xs IH]; [reflexivity | simpl; rewrite IH, append_assoc; reflexivity].
Qed.

Lemma encRuns_pushRun (t : Tok) (n : N) (xs : list (Tok * N)) :
  encRuns (pushRun t n xs) = ((encTok t) ^^ N.to_nat n) ++ encRuns xs.
Proof.
  unfold pushRun.
  destruct ((n =? 0)%N) eqn:Hn0; split_andb.
  - assert (Hz : N.to_nat n = 0) by lia. rewrite Hz. reflexivity.
  - destruct xs as [|[t' m] rest].
    + simpl. rewrite app_nil_r. reflexivity.
    + destruct (tok_eqb t t') eqn:Heq.
      * apply tok_eqb_eq in Heq; subst t'.
        simpl encRuns. rewrite <- append_assoc, <- list_pow_add.
        replace (N.to_nat n + N.to_nat m) with (N.to_nat (n + m)%N) by lia. reflexivity.
      * reflexivity.
Qed.

Lemma encRuns_dropTrailingBlankL (xs : list (Tok * N)) (blankOk : bool) (base : Stream Sym)
    (hb : blankOk = true -> base = b0) :
    encRuns (dropTrailingBlankL xs blankOk) *> base = encRuns xs *> base.
Proof.
  unfold dropTrailingBlankL.
  destruct xs as [|[[| | | | | |] n] [|? ?]]; try reflexivity.
  destruct blankOk; [|reflexivity].
  rewrite (hb eq_refl). simpl encRuns. rewrite app_nil_r, zLan.
  symmetry. apply zero_pow_append_default.
Qed.

Lemma encRuns_decRun (t : Tok) (n : N) (rest : list (Tok * N)) :
  encRuns (decRun t n rest) = ((encTok t) ^^ N.to_nat n) ++ encRuns rest.
Proof.
  unfold decRun.
  destruct ((n =? 0)%N) eqn:Hn0; split_andb.
  - assert (Hz : N.to_nat n = 0) by lia. rewrite Hz. reflexivity.
  - reflexivity.
Qed.

Local Opaque pushRun decRun.

Lemma popBit_sound : forall (xs xs' : list (Tok * N)) (blankOk : bool) (sym : Sym) (base : Stream Sym),
  (blankOk = true -> base = b0) ->
  popBit xs blankOk = Some (sym, xs') ->
  encRuns xs *> base = [sym] *> encRuns xs' *> base.
Proof.
  induction xs as [|[t n] rest IH]; intros xs' blankOk sym base hb h.
  - cbn [popBit] in h. destruct blankOk; [|discriminate].
    inversion h; subst. rewrite (hb eq_refl). simpl encRuns. rewrite zLan.
    symmetry. exact zero_append_default.
  - cbn [popBit] in h. destruct ((n =? 0)%N) eqn:Hn0; split_andb.
    + assert (Hz : N.to_nat n = 0) by lia.
      simpl encRuns. rewrite Hz. simpl. exact (IH _ _ _ _ hb h).
    + assert (HS : N.to_nat n = S (N.to_nat (n - 1)%N)) by lia.
      destruct t; inversion h; subst;
        simpl encRuns; rewrite HS; simpl lpow;
        rewrite ?encRuns_pushRun, ?encRuns_decRun;
        simpl lpow; simpl encTok; rewrite ?Str_app_assoc; reflexivity.
Qed.

Lemma popZero_sound {xs xs' : list (Tok * N)} {blankOk : bool} {base : Stream Sym}
    (hb : blankOk = true -> base = b0) (h : popZero xs blankOk = Some xs') :
    encRuns xs *> base = T0 *> encRuns xs' *> base.
Proof.
  unfold popZero in h.
  destruct (popBit xs blankOk) as [[[|] r']|] eqn:Hp; try discriminate.
  inversion h; subst r'. exact (popBit_sound _ _ _ _ _ hb Hp).
Qed.

Definition LeftBaseDenote (lb : LeftBase) (L_base : Stream Sym) : Prop :=
  match lb with
  | LBblank => L_base = b0
  | LBpipe Ep rev => PipeL (N.to_nat Ep) (encItems (List.rev rev)) L_base
  end.

Lemma headStartsZero_sound : forall (xs : list (Tok * N)) (lb : LeftBase) (L_base : Stream Sym),
  LeftBaseDenote lb L_base ->
  headStartsZero xs lb = true ->
  exists l0, encRuns xs *> L_base = T0 *> l0.
Proof.
  induction xs as [|[t n] rest IH]; intros lb L_base hlb h.
  - destruct lb as [|Ep rev]; simpl in hlb.
    + subst L_base. exists b0. simpl. symmetry. exact zero_append_default.
    + simpl encRuns. rewrite zLan. exact (PipeL_head0 hlb).
  - cbn [headStartsZero] in h. destruct ((n =? 0)%N) eqn:Hn0; split_andb.
    + assert (Hz : N.to_nat n = 0) by lia.
      simpl encRuns. rewrite Hz. simpl. exact (IH _ _ hlb h).
    + assert (HS : N.to_nat n = S (N.to_nat (n - 1)%N)) by lia.
      destruct t; try discriminate;
        simpl encRuns; rewrite HS; simpl lpow; simpl encTok; rewrite ?Str_app_assoc;
        eexists; reflexivity.
Qed.

Lemma coalStepL_sound {xs ys : list (Tok * N)} (h : coalStepL xs = Some ys) :
  encRuns xs = encRuns ys.
Proof.
  unfold coalStepL in h.
  destruct xs as [|[[| | | | | |] n0] [|[[| | | | | |] m] rest]]; try discriminate.
  destruct ((n0 =? 2)%N) eqn:Hn2; split_andb.
  - destruct ((1 <=? m)%N) eqn:Hm1; [|discriminate]. split_andb.
    inversion h; subst ys.
    assert (Hn0 : N.to_nat n0 = 2) by lia.
    assert (HmS : N.to_nat m = S (N.to_nat (m - 1)%N)) by lia.
    simpl encRuns. rewrite Hn0, HmS, encRuns_pushRun, encRuns_decRun.
    simpl lpow. simpl encTok. simpl. reflexivity.
  - destruct ((n0 =? 1)%N) eqn:Hn1; [|discriminate]. split_andb.
    assert (Hn0 : N.to_nat n0 = 1) by lia.
    destruct ((2 <=? m)%N) eqn:Hm2; split_andb.
    + inversion h; subst ys.
      assert (HmS : N.to_nat m = S (S (N.to_nat (m - 2)%N))) by lia.
      simpl encRuns. rewrite Hn0, HmS, encRuns_pushRun, encRuns_decRun.
      simpl lpow. simpl encTok. simpl. reflexivity.
    + destruct ((m =? 1)%N) eqn:Hm1; [|discriminate]. split_andb.
      assert (Hm0 : N.to_nat m = 1) by lia.
      destruct rest as [|[[| | | | | |] k] rest2]; try discriminate.
      * (* T_2 *)
        destruct ((1 <=? k)%N) eqn:Hk1; [|discriminate]. split_andb.
        inversion h; subst ys.
        assert (HkS : N.to_nat k = S (N.to_nat (k - 1)%N)) by lia.
        simpl encRuns. rewrite Hn0, Hm0, HkS, encRuns_pushRun, encRuns_decRun.
        simpl lpow. simpl encTok. simpl. reflexivity.
      * (* T_3 *)
        destruct ((1 <=? k)%N) eqn:Hk1; [|discriminate]. split_andb.
        inversion h; subst ys.
        assert (HkS : N.to_nat k = S (N.to_nat (k - 1)%N)) by lia.
        simpl encRuns. rewrite Hn0, Hm0, HkS, encRuns_pushRun, encRuns_decRun.
        simpl lpow. simpl encTok. simpl. reflexivity.
      * (* T_6 *)
        inversion h; subst ys.
        simpl encRuns. rewrite Hn0, Hm0, !encRuns_pushRun, ?list_pow_one.
        simpl encTok. unfold T0, T1.
        change ([S0] ++ ([S1] ++ ((T6 ^^ N.to_nat k) ++ encRuns rest2))) with
          (([S0; S1] ++ (T6 ^^ N.to_nat k)) ++ encRuns rest2).
        rewrite t01_t6_pow, append_assoc. cbn [app]. reflexivity.
Qed.

Lemma coalL_sound : forall (fuel : nat) (xs : list (Tok * N)),
  encRuns (coalL fuel xs) = encRuns xs.
Proof.
  induction fuel as [|fuel IH]; intros xs; [reflexivity |].
  simpl. destruct (coalStepL xs) as [xs'|] eqn:Hc; [|reflexivity].
  rewrite IH, <- (coalStepL_sound Hc). reflexivity.
Qed.

Lemma coalStepR_sound {xs ys : list (Tok * N)} (h : coalStepR xs = Some ys) :
  encRuns xs = encRuns ys.
Proof.
  unfold coalStepR in h.
  destruct xs as [|[[| | | | | |] n0] [|[[| | | | | |] m] rest]]; try discriminate.
  destruct ((n0 =? 2)%N) eqn:Hn2; split_andb.
  - destruct ((1 <=? m)%N) eqn:Hm1; [|discriminate]. split_andb.
    inversion h; subst ys.
    assert (Hn0 : N.to_nat n0 = 2) by lia.
    assert (HmS : N.to_nat m = S (N.to_nat (m - 1)%N)) by lia.
    simpl encRuns. rewrite Hn0, HmS, encRuns_pushRun, encRuns_decRun.
    simpl lpow. simpl encTok. simpl. reflexivity.
  - destruct ((n0 =? 1)%N) eqn:Hn1; [|discriminate]. split_andb.
    assert (Hn0 : N.to_nat n0 = 1) by lia.
    destruct ((2 <=? m)%N) eqn:Hm2; split_andb.
    + inversion h; subst ys.
      assert (HmS : N.to_nat m = S (S (N.to_nat (m - 2)%N))) by lia.
      simpl encRuns. rewrite Hn0, HmS, encRuns_pushRun, encRuns_decRun.
      simpl lpow. simpl encTok. simpl. reflexivity.
    + destruct ((m =? 1)%N) eqn:Hm1; [|discriminate]. split_andb.
      assert (Hm0 : N.to_nat m = 1) by lia.
      destruct rest as [|[[| | | | | |] k] rest2]; try discriminate.
      destruct ((1 <=? k)%N) eqn:Hk1; [|discriminate]. split_andb.
      inversion h; subst ys.
      assert (HkS : N.to_nat k = S (N.to_nat (k - 1)%N)) by lia.
      simpl encRuns. rewrite Hn0, Hm0, HkS, encRuns_pushRun, encRuns_decRun.
      simpl lpow. simpl encTok. simpl. reflexivity.
Qed.

Lemma coalR_sound : forall (fuel : nat) (xs : list (Tok * N)),
  encRuns (coalR fuel xs) = encRuns xs.
Proof.
  induction fuel as [|fuel IH]; intros xs; [reflexivity |].
  simpl. destruct (coalStepR xs) as [xs'|] eqn:Hc; [|reflexivity].
  rewrite IH, <- (coalStepR_sound Hc). reflexivity.
Qed.

Local Opaque coalL coalR.

Lemma encItems_appendT4Rev (b : N) (rev : list RleItem) :
  encItems (List.rev (appendT4Rev b rev)) = encItems (List.rev rev) ++ (T4 ^^ N.to_nat b).
Proof.
  destruct rev as [|[a h s0 [|? ?] aR | | |] rest]; simpl appendT4Rev;
    rewrite ?encItems_rev_cons; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail];
    simpl encTok; rewrite ?app_nil_r, ?append_assoc, ?list_pow_add_r, <- ?list_pow_add;
    try (replace (N.to_nat s0 + N.to_nat b) with (N.to_nat (s0 + b)%N) by lia);
    reflexivity.
Qed.

Lemma peelRun_sound (t : Tok) (xs : list (Tok * N)) :
  encRuns xs = ((encTok t) ^^ N.to_nat (fst (peelRun t xs))) ++ encRuns (snd (peelRun t xs)).
Proof.
  destruct xs as [|[t' n] rest]; [reflexivity |].
  simpl peelRun. destruct (tok_eqb t' t) eqn:Heq.
  - apply tok_eqb_eq in Heq; subst t'. reflexivity.
  - simpl. reflexivity.
Qed.

Lemma encRuns_cons (t : Tok) (n : N) (rs : list (Tok * N)) :
  encRuns ((t, n) :: rs) = ((encTok t) ^^ N.to_nat n) ++ encRuns rs.
Proof. reflexivity. Qed.

Lemma encRuns_nil : encRuns [] = [].
Proof. reflexivity. Qed.

Lemma N_to_nat_1 : N.to_nat 1%N = 1.
Proof. reflexivity. Qed.

Lemma N_to_nat_2 : N.to_nat 2%N = 2.
Proof. reflexivity. Qed.

Lemma list_pow_two {A : Type} (xs : list A) : xs ^^ 2 = xs ++ xs.
Proof. simpl. rewrite app_nil_r. reflexivity. Qed.

Ltac norm_runs :=
  rewrite ?encRuns_cons, ?encRuns_nil, ?encRuns_pushRun, ?encRuns_decRun,
          ?encRuns_cons, ?encRuns_nil,
          ?N_to_nat_1, ?N_to_nat_2, ?list_pow_one, ?list_pow_two;
  cbn [encTok];
  rewrite ?app_nil_r, ?Str_app_assoc.

Lemma tryPromotePipe_sound {Lrest : list (Tok * N)} {lb lb' : LeftBase} {L_base : Stream Sym}
    (hlb : LeftBaseDenote lb L_base)
    (h : tryPromotePipe Lrest lb = Some lb') :
    LeftBaseDenote lb' (encRuns Lrest *> L_base).
Proof.
  destruct lb as [|Ep rev].
  - simpl in hlb; subst L_base.
    unfold tryPromotePipe in h.
    pose proof (peelRun_sound T_5 Lrest) as Hpeel1.
    destruct (peelRun T_5 Lrest) as [b r1]; simpl in Hpeel1, h.
    destruct r1 as [|[[| | | | | |] n4] r2]; try discriminate.
    destruct ((n4 =? 1)%N) eqn:Hn4; [|discriminate]. split_andb. subst n4.
    pose proof (peelRun_sound T_3 r2) as Hpeel2.
    destruct (peelRun T_3 r2) as [k r3]; simpl in Hpeel2, h.
    pose proof (peelRun_sound T_2 r3) as Hpeel3.
    destruct (peelRun T_2 r3) as [m r4]; simpl in Hpeel3, h.
    destruct r4 as [|[[| | | | | |] n_0] [|[[| | | | | |] n_1] [|[[| | | | | |] n_2] [|[[| | | | | |] n_3] [|? ?]]]]];
      try discriminate.
    destruct (((n_0 =? 1)%N && (n_1 =? 1)%N && (n_2 =? 1)%N && (n_3 =? 1)%N)%bool) eqn:Hc; [|discriminate].
    split_andb; subst n_0 n_1 n_2 n_3.
    assert (HL : encRuns Lrest *> b0 =
                 (T5 ^^ N.to_nat b) *> T4 *> (T3 ^^ N.to_nat k) *> (T2 ^^ N.to_nat m) *> [S0; S1; S0; S1] *> b0).
    { rewrite Hpeel1, encRuns_cons, Hpeel2, Hpeel3. norm_runs. reflexivity. }
    destruct ((m mod 2 =? 0)%N) eqn:Hm2; split_andb; inversion h; subst lb'; cbn [LeftBaseDenote]; rewrite HL.
    + pose proof (N_even_decomp m Hm2) as Hev. rewrite Hev.
      pose proof (pipeL_base_c0_noT2 (N.to_nat (m / 2)%N) (N.to_nat b) (N.to_nat k)) as Hbase.
      eapply pipeL_eqR; [| exact Hbase].
      cbn [List.rev app encItems]. unfold encItem, encSingle; cbn [encSegTail].
      replace (N.to_nat k + 2 * N.to_nat (m / 2)%N + 1) with (N.to_nat (k + 2 * (m / 2) + 1)%N) by lia.
      rewrite ?app_nil_r. reflexivity.
    + pose proof (N_odd_decomp m Hm2) as Hodd. rewrite Hodd, pow_add_blank, zP1.
      pose proof (pipeL_base_c0_T2 (N.to_nat (m / 2)%N) (N.to_nat b) (N.to_nat k)) as Hbase.
      eapply pipeL_eqR; [| exact Hbase].
      cbn [List.rev app encItems]. unfold encItem, encSingle; cbn [encSegTail].
      replace (N.to_nat k + 2 * N.to_nat (m / 2)%N + 2) with (N.to_nat (k + 2 * (m / 2) + 2)%N) by lia.
      replace (N.to_nat b + 1) with (N.to_nat (b + 1)%N) by lia.
      rewrite ?app_nil_r. reflexivity.
  - cbn [LeftBaseDenote] in hlb. unfold tryPromotePipe in h.
    (* Check all 9 list shapes of Lrest cleanly *)
    destruct Lrest as [|[t1 a1] [|[t2 a2] [|[t3 a3] [|[t4 a4] [|? ?]]]]]; try discriminate.
    + (* length 1 *)
      destruct t1; try discriminate.
      * (* [(T_4, a1)] *)
        destruct ((a1 =? 1)%N) eqn:Ha1; [|discriminate]. split_andb; subst a1.
        inversion h; subst lb'; cbn [LeftBaseDenote].
        norm_runs.
        pose proof (pipeL_noT2_blk 0 0 hlb) as hp. rewrite ?zPz, ?zLan, ?app_nil_r in hp.
        eapply pipeL_eqR; [| exact hp].
        rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
        rewrite ?zPz, ?app_nil_r. reflexivity.
      * (* [(T_5, a1)] *)
        destruct ((1 <=? a1)%N) eqn:Ha1; [|discriminate]. split_andb.
        inversion h; subst lb'; cbn [LeftBaseDenote].
        norm_runs.
        pose proof (pipeL_t5 (N.to_nat a1) hlb) as hp.
        eapply pipeL_eqR; [symmetry; apply encItems_appendT4Rev | exact hp].
    + (* length 2 *)
      destruct t1; try discriminate; destruct t2; try discriminate.
      * (* [(T_4, a1); (T_2, a2)] *)
        destruct (((a1 =? 1)%N && (a2 =? 1)%N)%bool) eqn:Hc; [|discriminate]. split_andb; subst a1 a2.
        inversion h; subst lb'; cbn [LeftBaseDenote].
        norm_runs.
        pose proof (pipeL_T2_blk 0 0 hlb) as hp. rewrite ?zPz, ?zLan in hp.
        eapply pipeL_eqR; [| exact hp].
        rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
        rewrite ?app_nil_r, ?append_assoc. reflexivity.
      * (* [(T_4, a1); (T_3, a2)] *)
        destruct ((a1 =? 1)%N) eqn:Hc; [|discriminate]. split_andb; subst a1.
        inversion h; subst lb'; cbn [LeftBaseDenote].
        norm_runs.
        pose proof (pipeL_noT2_blk 0 (N.to_nat a2) hlb) as hp. rewrite ?zPz, zLan, ?app_nil_r in hp.
        eapply pipeL_eqR; [| exact hp].
        rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
        rewrite ?zPz, ?app_nil_r, ?append_assoc. reflexivity.
      * (* [(T_5, a1); (T_4, a2)] *)
        destruct ((a2 =? 1)%N) eqn:Hc; [|discriminate]. split_andb; subst a2.
        inversion h; subst lb'; cbn [LeftBaseDenote].
        norm_runs.
        pose proof (pipeL_noT2_blk (N.to_nat a1) 0 hlb) as hp. rewrite ?zPz, zLan, ?app_nil_r in hp.
        eapply pipeL_eqR; [| exact hp].
        rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
        rewrite ?zPz, ?app_nil_r, ?append_assoc. reflexivity.
    + (* length 3 *)
      destruct t1; try discriminate; destruct t2; try discriminate; destruct t3; try discriminate.
      * (* [(T_4, a1); (T_3, a2); (T_2, a3)] *)
        destruct (((a1 =? 1)%N && (a3 =? 1)%N)%bool) eqn:Hc; [|discriminate]. split_andb; subst a1 a3.
        inversion h; subst lb'; cbn [LeftBaseDenote].
        norm_runs.
        pose proof (pipeL_T2_blk 0 (N.to_nat a2) hlb) as hp. rewrite zPz, zLan in hp.
        eapply pipeL_eqR; [| exact hp].
        rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
        replace (N.to_nat a2 + 1) with (N.to_nat (a2 + 1)%N) by lia.
        rewrite ?app_nil_r, ?append_assoc. reflexivity.
      * (* [(T_5, a1); (T_4, a2); (T_2, a3)] *)
        destruct (((a2 =? 1)%N && (a3 =? 1)%N)%bool) eqn:Hc; [|discriminate]. split_andb; subst a2 a3.
        inversion h; subst lb'; cbn [LeftBaseDenote].
        norm_runs.
        pose proof (pipeL_T2_blk (N.to_nat a1) 0 hlb) as hp. rewrite zPz, zLan in hp.
        eapply pipeL_eqR; [| exact hp].
        rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
        replace (N.to_nat a1 + 1) with (N.to_nat (a1 + 1)%N) by lia.
        rewrite ?app_nil_r, ?append_assoc. reflexivity.
      * (* [(T_5, a1); (T_4, a2); (T_3, a3)] *)
        destruct ((a2 =? 1)%N) eqn:Hc; [|discriminate]. split_andb; subst a2.
        inversion h; subst lb'; cbn [LeftBaseDenote].
        norm_runs.
        pose proof (pipeL_noT2_blk (N.to_nat a1) (N.to_nat a3) hlb) as hp.
        eapply pipeL_eqR; [| exact hp].
        rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
        rewrite ?app_nil_r, ?append_assoc. reflexivity.
    + (* length 4 *)
      destruct t1; try discriminate; destruct t2; try discriminate;
        destruct t3; try discriminate; destruct t4; try discriminate.
      destruct (((a2 =? 1)%N && (a4 =? 1)%N)%bool) eqn:Hc; [|discriminate]. split_andb; subst a2 a4.
      inversion h; subst lb'; cbn [LeftBaseDenote].
      norm_runs.
      pose proof (pipeL_T2_blk (N.to_nat a1) (N.to_nat a3) hlb) as hp.
      eapply pipeL_eqR; [| exact hp].
      rewrite encItems_rev_cons. simpl encItem. unfold encSingle; cbn [encSegTail].
      replace (N.to_nat a3 + 1) with (N.to_nat (a3 + 1)%N) by lia.
      replace (N.to_nat a1 + 1) with (N.to_nat (a1 + 1)%N) by lia.
      rewrite ?app_nil_r, ?append_assoc. reflexivity.
    + (* length >= 5 *)
      destruct t1, t2, t3, t4; discriminate.
Qed.

Definition RightBaseStream (R_tail : Stream Sym) (rb : RightBase) : Stream Sym :=
  match rb with
  | RBblank => b0
  | RBtail => R_tail
  end.

Definition RawDenote (R_tail : Stream Sym) (c : RawCfg) (cfg : Q * tape) : Prop :=
  exists L_base,
    LeftBaseDenote (rc_lBase c) L_base /\
    cfg = ((encRuns (rc_L c) *> L_base) {{rc_q c}}>
           (encRuns (rc_R c) *> RightBaseStream R_tail (rc_rBase c))).

Lemma step_dir_right {q q' : Q} {s w : Sym} {l r : Stream Sym}
    (h : tm (q, s) = Some (w, R, q')) :
    (l {{q}}> ([s] *> r)) -[ tm ]-> (([w] *> l) {{q'}}> r).
Proof.
  exact (step_right h).
Qed.

Lemma step_dir_left {q q' : Q} {b s w : Sym} {l r : Stream Sym}
    (h : tm (q, s) = Some (w, L, q')) :
    (([b] *> l) {{q}}> ([s] *> r)) -[ tm ]-> (l {{q'}}> ([b; w] *> r)).
Proof.
  exact (step_left h).
Qed.

Lemma step1_to_star {c1 c2 : Q * tape} (h : c1 -[ tm ]-> c2) : c1 -[ tm ]->* c2.
Proof.
  eapply evstep_step; [exact h | apply evstep_refl].
Qed.

Lemma symToTok_enc (s : Sym) : encTok (symToTok s) = [s].
Proof.
  destruct s; reflexivity.
Qed.

Lemma stepRaw1_sound {R_tail : Stream Sym} {c c' : RawCfg} {cfg : Q * tape}
    (hd : RawDenote R_tail c cfg) (h : stepRaw1 c = Some c') :
    exists cfg', RawDenote R_tail c' cfg' /\ cfg -[ tm ]->* cfg'.
Proof.
  destruct hd as [L_base [hlb Hcfg]]; subst cfg.
  destruct c as [q Lr lBase Rr rBase].
  unfold stepRaw1 in h; cbn [rc_q rc_L rc_lBase rc_R rc_rBase LeftBaseDenote] in h, hlb |- *.
  assert (Hrb_ok : isRBblank rBase = true -> RightBaseStream R_tail rBase = b0).
  { destruct rBase; simpl; intros H; [reflexivity | discriminate]. }
  assert (Hlb_ok : isLBblank lBase = true -> L_base = b0).
  { destruct lBase; simpl in *; intros H; [exact hlb | discriminate]. }
  destruct (popBit Rr (isRBblank rBase)) as [[sym R1]|] eqn:HpR; [|discriminate].
  pose proof (popBit_sound _ _ _ _ _ Hrb_ok HpR) as HR.
  destruct (tm (q, sym)) as [[[w dir] q']|] eqn:Htm; [|discriminate].
  destruct dir.
  - (* L *)
    destruct (popBit Lr (isLBblank lBase)) as [[lb_sym L1]|] eqn:HpL; [|discriminate].
    injection h as <-.
    pose proof (popBit_sound _ _ _ _ _ Hlb_ok HpL) as HL.
    eexists. split.
    + exists L_base. split; [exact hlb | reflexivity].
    + cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. rewrite HL, HR, coalL_sound.
      rewrite (encRuns_dropTrailingBlankL _ _ _ Hrb_ok), coalR_sound, !encRuns_pushRun,
        !N_to_nat_1, !list_pow_one, !symToTok_enc, ?Str_app_assoc.
      exact (step1_to_star (step_dir_left Htm)).
  - (* R *)
    injection h as <-.
    eexists. split.
    + exists L_base. split; [exact hlb | reflexivity].
    + cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. rewrite HR, coalR_sound.
      rewrite (encRuns_dropTrailingBlankL _ _ _ Hlb_ok), coalL_sound, encRuns_pushRun,
        !N_to_nat_1, !list_pow_one, symToTok_enc, ?Str_app_assoc.
      exact (step1_to_star (step_dir_right Htm)).
Qed.

Lemma t6_push_L (k : N) (hk : (1 <= k)%N) (Lr : list (Tok * N)) (L_base : Stream Sym) :
  (T6 ^^ N.to_nat k) *> encRuns Lr *> L_base =
  encRuns (match Lr with
           | (T_3, m) :: Lrest =>
               if (1 <=? m)%N then
                 pushRun T_2 1 (pushRun T_5 (k - 1) (pushRun T_4 1 (decRun T_3 (m - 1) Lrest)))
               else pushRun T_6 k Lr
           | (T_2, m) :: Lrest =>
               if (1 <=? m)%N then
                 pushRun T_2 1 (pushRun T_5 k (decRun T_2 (m - 1) Lrest))
               else pushRun T_6 k Lr
           | _ => pushRun T_6 k Lr
           end) *> L_base.
Proof.
  destruct Lr as [|[[| | | | | |] m] Lrest];
    try (rewrite encRuns_pushRun; cbn [encTok]; rewrite Str_app_assoc; reflexivity).
  - (* T_2 *)
    destruct ((1 <=? m)%N) eqn:Hm1; split_andb.
    + assert (HmS : N.to_nat m = S (N.to_nat (m - 1)%N)) by lia.
      cbn [encRuns]. rewrite HmS, !encRuns_pushRun, encRuns_decRun, ?N_to_nat_1, ?list_pow_one.
      cbn [encTok]. rewrite ?Str_app_assoc, zPsr, ?Str_app_assoc.
      rewrite <- (Str_app_assoc (T6 ^^ N.to_nat k) T2), <- t2_t5_pow, ?Str_app_assoc. reflexivity.
    + rewrite encRuns_pushRun; cbn [encTok]; rewrite Str_app_assoc; reflexivity.
  - (* T_3 *)
    destruct ((1 <=? m)%N) eqn:Hm1; split_andb.
    + assert (HmS : N.to_nat m = S (N.to_nat (m - 1)%N)) by lia.
      assert (HkS : N.to_nat k = N.to_nat (k - 1)%N + 1) by lia.
      cbn [encRuns]. rewrite HmS, HkS, list_pow_succ_right, !encRuns_pushRun, encRuns_decRun, ?N_to_nat_1, ?list_pow_one.
      cbn [encTok]. rewrite ?Str_app_assoc, zPsr, ?Str_app_assoc.
      rewrite <- (Str_app_assoc T6 T3), t6_t3_eq, ?Str_app_assoc.
      rewrite <- (Str_app_assoc (T6 ^^ N.to_nat (k - 1)%N) T2), <- t2_t5_pow, ?Str_app_assoc.
      reflexivity.
    + rewrite encRuns_pushRun; cbn [encTok]; rewrite Str_app_assoc; reflexivity.
Qed.

Lemma stepRawFast_sound {R_tail : Stream Sym} {c c' : RawCfg} {cfg : Q * tape}
    (hd : RawDenote R_tail c cfg) (h : stepRawFast c = Some c') :
    exists cfg', RawDenote R_tail c' cfg' /\ cfg -[ tm ]->* cfg'.
Proof.
  destruct hd as [L_base [hlb Hcfg]]; subst cfg.
  destruct c as [q Lr lBase Rr rBase].
  unfold stepRawFast in h; cbn [rc_q rc_L rc_lBase rc_R rc_rBase LeftBaseDenote] in h, hlb |- *.
  set (rB := RightBaseStream R_tail rBase) in *.
  assert (Hrb_ok : isRBblank rBase = true -> rB = b0).
  { unfold rB. destruct rBase; simpl; intros H; [reflexivity | discriminate]. }
  destruct q.
  - (* A *)
    destruct Lr as [|[[| | | | | |] n1] Ltail]; try discriminate.
    destruct ((n1 =? 1)%N) eqn:Hn1; [|discriminate]. split_andb; subst n1.
    assert (Hfb : forall Lrest,
      Ltail = Lrest ->
      (match Rr with
       | (T_2, k) :: R' =>
           if (1 <=? k)%N then Some (mkRawCfg A ((T_1, 1%N) :: pushRun T_3 k Lrest) lBase R' rBase)
           else None
       | _ => None
       end) = Some c' ->
      exists cfg', RawDenote R_tail c' cfg' /\
        ((encRuns ((T_1, 1%N) :: Ltail) *> L_base) {{A}}> (encRuns Rr *> rB)) -[ tm ]->* cfg').
    { intros Lrest HLt Hstep; subst Ltail.
      destruct Rr as [|[[| | | | | |] k] R']; try discriminate.
      destruct ((1 <=? k)%N) eqn:Hk1; [|discriminate]. split_andb.
      inversion Hstep; subst c'.
      eexists. split; [exists L_base; split; [exact hlb | reflexivity] |].
      cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs.
      exact (rule_q0_t2 (N.to_nat k) (encRuns Lrest *> L_base) (encRuns R' *> rB)). }
    destruct Ltail as [|[t2 n2] Lrest]; [exact (Hfb [] eq_refl h) |].
    destruct t2; try (exact (Hfb _ eq_refl h)).
    destruct ((n2 =? 1)%N) eqn:Hn2; [| exact (Hfb _ eq_refl h)].
    split_andb; subst n2.
    destruct (tryPromotePipe Lrest lBase) as [lb'|] eqn:Hpr.
    + inversion h; subst c'.
      pose proof (tryPromotePipe_sound hlb Hpr) as Hlb'.
      eexists. split; [exists (encRuns Lrest *> L_base); split; [exact Hlb' | reflexivity] |].
      cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs. apply evstep_refl.
    + destruct Rr as [|[[| | | | | |] k] R']; try discriminate.
      * (* T_2 *)
        destruct ((1 <=? k)%N) eqn:Hk1; [|discriminate]. split_andb.
        inversion h; subst c'.
        eexists. split; [exists L_base; split; [exact hlb | reflexivity] |].
        cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs.
        exact (rule_q0_t2 (N.to_nat k) (T2 *> encRuns Lrest *> L_base) (encRuns R' *> rB)).
      * (* T_4 *)
        destruct ((1 <=? k)%N) eqn:Hk1; [|discriminate]. split_andb.
        inversion h; subst c'.
        eexists. split; [exists L_base; split; [exact hlb | reflexivity] |].
        cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs.
        exact (rule_q0_t4_next (N.to_nat k) (encRuns Lrest *> L_base) (encRuns R' *> rB)).
  - (* B *) discriminate.
  - (* C *)
    destruct Rr as [|[[| | | | | |] r1] R1]; try discriminate.
    + (* (T_1, r1) :: R1 *)
      destruct R1 as [|[[| | | | | |] k] R']; try discriminate.
      * (* (T_1, r1) :: (T_2, k) :: R' *)
        destruct (((r1 =? 1)%N && (1 <=? k)%N)%bool) eqn:Hc; [|discriminate]. split_andb; subst r1.
        inversion h; subst c'.
        eexists. split; [exists L_base; split; [exact hlb | reflexivity] |].
        cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs.
        exact (rule_C_1_t2 (N.to_nat k) (encRuns Lr *> L_base) (encRuns R' *> rB)).
      * (* (T_1, r1) :: (T_4, k) :: R' *)
        destruct (((r1 =? 1)%N && (1 <=? k)%N)%bool) eqn:Hc; [|discriminate]. split_andb; subst r1.
        inversion h; subst c'.
        eexists. split; [exists L_base; split; [exact hlb | reflexivity] |].
        cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs.
        pose proof (rule_C_1_t4 (N.to_nat k) (encRuns Lr *> L_base) (encRuns R' *> rB)) as Hstep.
        rewrite (t6_push_L k ltac:(lia) Lr L_base) in Hstep. exact Hstep.
    + (* (T_2, r1) :: R1 *)
      destruct ((1 <=? r1)%N) eqn:Hc; [|discriminate]. split_andb.
      inversion h; subst c'.
      eexists. split; [exists L_base; split; [exact hlb | reflexivity] |].
      cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs.
      exact (rule_C_t2 (N.to_nat r1) (encRuns Lr *> L_base) (encRuns R1 *> rB)).
  - (* D *) discriminate.
  - (* E *)
    destruct Lr as [|[[| | | | | |] m] L']; try discriminate.
    + (* (T_0, m) :: L' *)
      destruct L' as [|[[| | | | | |] n1] [|[[| | | | | |] n4] [|[[| | | | | |] k] L2]]]; try discriminate.
      destruct (((m =? 1)%N && (n1 =? 1)%N && (n4 =? 1)%N && (1 <=? k)%N && headStartsZero L2 lBase)%bool) eqn:Hc; [|discriminate].
      split_andb; subst m n1 n4.
      destruct Rr as [|[[| | | | | |] r0] [|[[| | | | | |] r1] R']]; try discriminate.
      destruct (((r0 =? 1)%N && (r1 =? 1)%N)%bool) eqn:Hr; [|discriminate].
      split_andb; subst r0 r1.
      inversion h; subst c'.
      destruct (headStartsZero_sound L2 lBase L_base hlb ltac:(eassumption)) as [l0 Hl0].
      eexists. split; [exists L_base; split; [exact hlb | reflexivity] |].
      cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs. rewrite Hl0. norm_runs.
      change (T0 *> T1 *> T4 *> (T5 ^^ N.to_nat k) *> T0 *> l0) with (([S0; S1] ++ T4) *> (T5 ^^ N.to_nat k) *> T0 *> l0).
      change (T0 *> T1 *> T4 *> T0 *> l0) with (([S0; S1] ++ T4) *> T0 *> l0).
      change (T0 *> T1 *> encRuns R' *> rB) with ([S0; S1] *> encRuns R' *> rB).
      change (T0 *> T1 *> (T4 ^^ N.to_nat k) *> encRuns R' *> rB) with ([S0; S1] *> (T4 ^^ N.to_nat k) *> encRuns R' *> rB).
      exact (rule_E_01_t4_t5 (N.to_nat k) l0 (encRuns R' *> rB)).
    + (* (T_3, m) :: L' *)
      destruct ((2 <=? m)%N) eqn:Hm2; split_andb.
      * destruct (popZero Rr (isRBblank rBase)) as [R0|] eqn:Hp0; [|discriminate].
        inversion h; subst c'.
        pose proof (popZero_sound Hrb_ok Hp0) as HR.
        eexists. split; [exists L_base; split; [exact hlb | reflexivity] |].
        cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs. rewrite HR. norm_runs.
        assert (HL : (T3 ^^ N.to_nat m) *> encRuns L' *> L_base =
                     (T3 ^^ N.to_nat (m - 1)%N) *> T0 *> [S1; S1] *> encRuns L' *> L_base).
        { replace (N.to_nat m) with (N.to_nat (m - 1)%N + 1) by lia.
          rewrite list_pow_succ_right, Str_app_assoc. reflexivity. }
        rewrite HL.
        exact (rule_E_t3 (N.to_nat (m - 1)%N) ([S1; S1] *> encRuns L' *> L_base) (encRuns R0 *> rB)).
      * destruct ((m =? 1)%N) eqn:Hm1; [|discriminate]. split_andb; subst m.
        destruct (headStartsZero L' lBase) eqn:Hz; [|discriminate].
        destruct (popZero Rr (isRBblank rBase)) as [R0|] eqn:Hp0; [|discriminate].
        inversion h; subst c'.
        pose proof (popZero_sound Hrb_ok Hp0) as HR.
        destruct (headStartsZero_sound _ _ _ hlb Hz) as [l0 Hl0].
        eexists. split; [exists L_base; split; [exact hlb | reflexivity] |].
        cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs. rewrite HR, Hl0. norm_runs.
        pose proof (rule_E_t3_to_Q5 0 l0 (encRuns R0 *> rB)) as Hstep.
        rewrite zP1, zPz, zLan in Hstep. exact Hstep.
    + (* (T_5, m) :: L' *)
      destruct (((1 <=? m)%N && headStartsZero L' lBase)%bool) eqn:Hc; [|discriminate]. split_andb.
      destruct Rr as [|[[| | | | | |] n0] [|[[| | | | | |] k] R']]; try discriminate.
      destruct (((n0 =? 1)%N && (1 <=? k)%N)%bool) eqn:Hr; [|discriminate]. split_andb; subst n0.
      inversion h; subst c'.
      destruct (headStartsZero_sound L' lBase L_base hlb ltac:(eassumption)) as [l0 Hl0].
      eexists. split; [exists L_base; split; [exact hlb | reflexivity] |].
      cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs. rewrite Hl0. norm_runs.
      assert (HR : T0 *> (T2 ^^ N.to_nat k) *> encRuns R' *> rB =
                   T0 *> T2 *> (T2 ^^ N.to_nat (k - 1)%N) *> encRuns R' *> rB).
      { replace (N.to_nat k) with (S (N.to_nat (k - 1)%N)) by lia. rewrite zPsr. reflexivity. }
      rewrite HR.
      exact (rule_E_t5 (N.to_nat m) l0 ((T2 ^^ N.to_nat (k - 1)%N) *> encRuns R' *> rB)).
  - (* F *)
    destruct Lr as [|[[| | | | | |] n1] Lrest]; try discriminate.
    destruct ((n1 =? 2)%N) eqn:Hn1; [|discriminate]. split_andb; subst n1.
    destruct (tryPromotePipe Lrest lBase) as [lb'|] eqn:Hpr.
    + inversion h; subst c'.
      pose proof (tryPromotePipe_sound hlb Hpr) as Hlb'.
      eexists. split; [exists (encRuns Lrest *> L_base); split; [exact Hlb' | reflexivity] |].
      cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs. apply evstep_refl.
    + destruct Lrest as [|[tL k] L'].
      * (* Lrest = [] *)
        destruct lBase as [|Ep rev]; [discriminate |].
        cbn [LeftBaseDenote] in hlb.
        assert (HpullOther :
          (if (1 <=? Ep)%N then
             match popZero Rr (isRBblank rBase) with
             | Some R0 => Some (mkRawCfg E [(T_0, 1%N); (T_1, 1%N)] (LBpipe (Ep - 1)%N rev) (pushRun T_1 1 R0) rBase)
             | None => None
             end
           else None) = Some c' ->
          exists cfg', RawDenote R_tail c' cfg' /\
            ((encRuns [(T_1, 2%N)] *> L_base) {{F}}> (encRuns Rr *> rB)) -[ tm ]->* cfg').
        { intros Hpo.
          destruct ((1 <=? Ep)%N) eqn:HEp; [|discriminate]. split_andb.
          destruct (popZero Rr (isRBblank rBase)) as [R0|] eqn:Hp0; [|discriminate].
          inversion Hpo; subst c'.
          assert (HEpS : N.to_nat Ep = N.to_nat (Ep - 1)%N + 1) by lia.
          pose proof (pipeL_eqE HEpS hlb) as hlb'.
          destruct (PipeL_pull hlb') as [L1 [hpull hp1]].
          pose proof (popZero_sound Hrb_ok Hp0) as HR.
          eexists. split; [exists L1; split; [cbn [rc_lBase LeftBaseDenote]; exact hp1 | reflexivity] |].
          cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs. rewrite HR. norm_runs.
          exact (hpull (encRuns R0 *> rB)). }
        destruct Rr as [|[tR k] R']; [exact (HpullOther h) |].
        destruct tR; try (exact (HpullOther h)).
        -- (* (T_2, k) :: R' *)
           set (j := N.min (k / 2) Ep) in *.
           destruct ((1 <=? j)%N) eqn:Hj1; [| exact (HpullOther h)].
           split_andb. inversion h; subst c'.
           assert (HjE : N.to_nat j <= N.to_nat Ep) by (unfold j; pose proof (N.le_min_r (k / 2) Ep); lia).
           assert (H2jk : (2 * j <= k)%N) by (unfold j; pose proof (N.le_min_l (k / 2) Ep); pose proof (N_mul_div_le k 2); lia).
           destruct (pipeL_eat_t2_even (N.to_nat j) 0 HjE hlb ((T2 ^^ N.to_nat (k - 2 * j)%N) *> encRuns R' *> rB))
             as [L1 [hp1 hs1]].
           rewrite zPz, zLan in hs1.
           eexists. split.
           ++ exists L1. split; [cbn [rc_lBase LeftBaseDenote]; apply (pipeL_eqER hp1); [lia | reflexivity] | reflexivity].
           ++ cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs.
              replace (0 + 2 * N.to_nat j) with (N.to_nat (2 * j)%N) in hs1 by lia.
              assert (HR : (T2 ^^ N.to_nat k) *> encRuns R' *> rB =
                           (T2 ^^ (2 * N.to_nat j)) *> (T2 ^^ N.to_nat (k - 2 * j)%N) *> encRuns R' *> rB).
              { rewrite <- pow_add_blank. replace (2 * N.to_nat j + N.to_nat (k - 2 * j)%N) with (N.to_nat k) by lia. reflexivity. }
              rewrite HR. exact hs1.
        -- (* (T_4, k) :: R' *)
           set (m := N.min k Ep) in *.
           destruct ((1 <=? m)%N) eqn:Hm1; [|discriminate].
           split_andb. inversion h; subst c'.
           assert (HmE : N.to_nat m <= N.to_nat Ep) by (unfold m; pose proof (N.le_min_r k Ep); lia).
           assert (Hmk : (m <= k)%N) by (unfold m; apply N.le_min_l).
           destruct (pipeL_eat_t4 (N.to_nat m) HmE hlb ((T4 ^^ N.to_nat (k - m)%N) *> encRuns R' *> rB))
             as [L1 [hp1 hs1]].
           eexists. split.
           ++ exists L1. split; [cbn [rc_lBase LeftBaseDenote]; apply (pipeL_eqER hp1); [lia | symmetry; apply encItems_appendT4Rev] | reflexivity].
           ++ cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs.
              assert (HR : (T4 ^^ N.to_nat k) *> encRuns R' *> rB =
                           (T4 ^^ N.to_nat m) *> (T4 ^^ N.to_nat (k - m)%N) *> encRuns R' *> rB).
              { rewrite <- pow_add_blank. replace (N.to_nat m + N.to_nat (k - m)%N) with (N.to_nat k) by lia. reflexivity. }
              rewrite HR. exact hs1.
      * (* Lrest = (tL, k) :: L' *)
        destruct tL; try discriminate.
        -- (* T_3 *)
           destruct Rr as [|[[| | | | | |] r0] [|[[| | | | | |] r1] R']]; try discriminate.
           destruct (((r0 =? 1)%N && (r1 =? 1)%N && (1 <=? k)%N && headStartsZero L' lBase)%bool) eqn:Hc; [|discriminate].
           split_andb; subst r0 r1. inversion h; subst c'.
           destruct (headStartsZero_sound L' lBase L_base hlb ltac:(eassumption)) as [l0 Hl0].
           eexists. split; [exists L_base; split; [exact hlb | reflexivity] |].
           cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs. rewrite Hl0. norm_runs.
           exact (rule_q5_t3_unwind (N.to_nat k) l0 (encRuns R' *> rB)).
        -- (* T_5 *)
           destruct Rr as [|[[| | | | | |] r0] [|[[| | | | | |] r1] R']]; try discriminate.
           destruct (((r0 =? 1)%N && (r1 =? 1)%N && (1 <=? k)%N && headStartsZero L' lBase)%bool) eqn:Hc; [|discriminate].
           split_andb; subst r0 r1. inversion h; subst c'.
           destruct (headStartsZero_sound L' lBase L_base hlb ltac:(eassumption)) as [l0 Hl0].
           eexists. split; [exists L_base; split; [exact hlb | reflexivity] |].
           cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. norm_runs. rewrite Hl0. norm_runs.
           exact (rule_unwind_t5 (N.to_nat k) l0 (encRuns R' *> rB)).
Qed.

Lemma stepRaw_sound {R_tail : Stream Sym} {c c' : RawCfg} {cfg : Q * tape}
    (hd : RawDenote R_tail c cfg) (h : stepRaw c = Some c') :
    exists cfg', RawDenote R_tail c' cfg' /\ cfg -[ tm ]->* cfg'.
Proof.
  unfold stepRaw in h.
  destruct (stepRawFast c) as [c1|] eqn:Hf.
  - inversion h; subst c1. exact (stepRawFast_sound hd Hf).
  - exact (stepRaw1_sound hd h).
Qed.

Lemma runRawUntil_sound : forall (fuel : nat) (R_tail : Stream Sym) (done : RawCfg -> bool)
    (c c' : RawCfg) (cfg : Q * tape),
  RawDenote R_tail c cfg ->
  runRawUntil done fuel c = Some c' ->
  done c' = true /\ exists cfg', RawDenote R_tail c' cfg' /\ cfg -[ tm ]->* cfg'.
Proof.
  induction fuel as [|fuel IH]; intros R_tail done c c' cfg hd h; simpl in h.
  - destruct (done c) eqn:Hd; [|discriminate].
    inversion h; subst c'. split; [exact Hd | exists cfg; split; [exact hd | apply evstep_refl]].
  - destruct (done c) eqn:Hd.
    + inversion h; subst c'. split; [exact Hd | exists cfg; split; [exact hd | apply evstep_refl]].
    + destruct (stepRaw c) as [c1|] eqn:Hs; [|discriminate].
      destruct (stepRaw_sound hd Hs) as [cfg1 [hd1 hst1]].
      destruct (IH R_tail done c1 c' cfg1 hd1 h) as [Hd' [cfg2 [hd2 hst2]]].
      split; [exact Hd' | exists cfg2; split; [exact hd2 | exact (stepStar_trans hst1 hst2)]].
Qed.

(* ========================================================================= *)
(* Section 9.4: Runs <-> Items, runRawFromInit, and runPipeRawHalt           *)
(* ========================================================================= *)

Lemma segToRuns_sound : forall (segTail : list SegPiece) (rs : list (Tok * N)),
  segToRuns segTail = Some rs -> encRuns rs = encSegTail segTail.
Proof.
  induction segTail as [|[v | v1 v2 rep] rest IH]; intros rs h; cbn [segToRuns] in h.
  - inversion h; subst; reflexivity.
  - apply option_map_Some in h. destruct h as [r [hr Hrs]]; subst rs.
    rewrite encRuns_cons, N_to_nat_1, list_pow_one; cbn [encTok]; cbn [encSegTail].
    destruct ((v =? 0)%N) eqn:Hv0; split_andb.
    + assert (HvZ : N.to_nat v = 0) by lia.
      rewrite HvZ, zPz, (IH r hr). reflexivity.
    + rewrite encRuns_cons; cbn [encTok]. rewrite (IH r hr), ?append_assoc. reflexivity.
  - discriminate.
Qed.

Lemma itemToRuns_sound {x : RleItem} {rs : list (Tok * N)} (h : itemToRuns x = Some rs) :
  encRuns rs = encItem x.
Proof.
  destruct x as [a h0 s0 segTail aR | | | t n]; cbn [itemToRuns] in h; try discriminate.
  - apply option_map_Some in h. destruct h as [sr [hsr Hrs]]; subst rs.
    rewrite !encRuns_append.
    assert (Ha : encRuns (if (a =? 0)%N then [] else [(T_2, a)]) = T2 ^^ N.to_nat a).
    { destruct ((a =? 0)%N) eqn:Ha0; split_andb; [assert (Hz : N.to_nat a = 0) by lia; rewrite Hz; reflexivity | simpl; rewrite app_nil_r; reflexivity]. }
    assert (HaR : encRuns (match aR with None => [] | Some r => (T_0, 1%N) :: (if (r =? 0)%N then [] else [(T_2, r)]) end) =
                  match aR with None => [] | Some r => T0 ++ (T2 ^^ N.to_nat r) end).
    { destruct aR as [r|]; [|reflexivity].
      destruct ((r =? 0)%N) eqn:Hr0; split_andb;
        [assert (Hz : N.to_nat r = 0) by lia; rewrite Hz; reflexivity | simpl; rewrite app_nil_r; reflexivity]. }
    assert (Hh : encRuns (if h0 then [(T_0, 1%N); (T_1, 1%N); (T_2, 1%N)] else []) = (if h0 then T5 else [])).
    { destruct h0; reflexivity. }
    assert (Hs0 : encRuns (if (s0 =? 0)%N then [] else [(T_4, s0)]) = T4 ^^ N.to_nat s0).
    { destruct ((s0 =? 0)%N) eqn:Hs00; split_andb; [assert (Hz : N.to_nat s0 = 0) by lia; rewrite Hz; reflexivity | simpl; rewrite app_nil_r; reflexivity]. }
    rewrite Ha, HaR, Hh, Hs0, (segToRuns_sound _ _ hsr).
    simpl encItem; unfold encSingle. rewrite ?append_assoc. reflexivity.
  - inversion h; subst rs.
    destruct ((n =? 0)%N) eqn:Hn0; split_andb.
    + assert (Hz : N.to_nat n = 0) by lia. simpl; rewrite Hz; reflexivity.
    + simpl. rewrite app_nil_r. reflexivity.
Qed.

Lemma itemsToRuns_sound : forall (xs : list RleItem) (rs : list (Tok * N)),
  itemsToRuns xs = Some rs -> encRuns rs = encItems xs.
Proof.
  induction xs as [|x xs IH]; intros rs h; cbn [itemsToRuns] in h.
  - inversion h; subst; reflexivity.
  - destruct (itemToRuns x) as [rx|] eqn:Hx; [|discriminate].
    destruct (itemsToRuns xs) as [rxs|] eqn:Hxs; [|discriminate].
    inversion h; subst rs.
    rewrite encRuns_append, (itemToRuns_sound Hx), (IH _ eq_refl). reflexivity.
Qed.

Lemma encItems_runsToItems (rs : list (Tok * N)) :
  encItems (runsToItems rs) = encRuns rs.
Proof.
  induction rs as [|[t n] rest IH]; [reflexivity | simpl; rewrite IH; reflexivity].
Qed.

Lemma encRuns_footerRuns : encRuns footerRuns = [S0; S1; S0; S1].
Proof. reflexivity. Qed.

Lemma encRuns_shortFooterRuns : encRuns shortFooterRuns = [S0; S1].
Proof. reflexivity. Qed.

Lemma stripFooterRuns_sound {rs body : list (Tok * N)}
    (h : stripFooterRuns rs = Some body) :
    encRuns rs = encRuns body ++ [S0; S1; S0; S1].
Proof.
  unfold stripFooterRuns in h.
  destruct (List.rev rs) as [|[t1 v1] l1] eqn:Hrev; [discriminate|].
  destruct t1; try discriminate.
  destruct l1 as [|[t2 v2] l2]; [discriminate|].
  destruct t2; try discriminate.
  destruct l2 as [|[t3 v3] l3]; [discriminate|].
  destruct t3; try discriminate.
  destruct l3 as [|[t4 v4] rest]; [discriminate|].
  destruct t4; try discriminate.
  destruct (((v1 =? 1)%N && (v2 =? 1)%N && (v3 =? 1)%N && (v4 =? 1)%N)%bool) eqn:Hc; [|discriminate].
  split_andb; subst v1 v2 v3 v4.
  inversion h; subst body.
  apply (f_equal (@List.rev _)) in Hrev.
  rewrite List.rev_involutive in Hrev. simpl in Hrev. rewrite ?append_assoc in Hrev.
  rewrite Hrev, encRuns_append. reflexivity.
Qed.

Lemma stripShortFooterRuns_sound {rs body : list (Tok * N)}
    (h : stripShortFooterRuns rs = Some body) :
    encRuns rs = encRuns body ++ [S0; S1].
Proof.
  unfold stripShortFooterRuns in h.
  destruct (List.rev rs) as [|[t1 v1] l1] eqn:Hrev; [discriminate|].
  destruct t1; try discriminate.
  destruct l1 as [|[t2 v2] rest]; [discriminate|].
  destruct t2; try discriminate.
  destruct (((v1 =? 1)%N && (v2 =? 1)%N)%bool) eqn:Hc; [|discriminate].
  split_andb; subst v1 v2.
  inversion h; subst body.
  apply (f_equal (@List.rev _)) in Hrev.
  rewrite List.rev_involutive in Hrev. simpl in Hrev. rewrite ?append_assoc in Hrev.
  rewrite Hrev, encRuns_append. reflexivity.
Qed.

Lemma runRawFromInit_sound {fuel : nat} {xs : list RleItem}
    (h : runRawFromInit fuel = Some xs) :
    c0 -[ tm ]->* HubCfg xs.
Proof.
  unfold runRawFromInit in h.
  set (rc0 := mkRawCfg A [] LBblank [] RBblank) in *.
  assert (Hd0 : RawDenote b0 rc0 c0).
  { exists b0. split; [reflexivity | symmetry; exact c0_eq]. }
  destruct (runRawUntil isInitHubDone fuel rc0) as [rc1|] eqn:Hrun; [|discriminate].
  destruct (runRawUntil_sound _ _ _ _ _ _ Hd0 Hrun) as [_ [cfg1 [Hd1 Hs1]]].
  destruct Hd1 as [L1 [Hlb1 Hcfg1]]; subst cfg1.
  destruct rc1 as [q1 Lr1 lb1 Rr1 rb1]; cbn [rc_q rc_L rc_lBase rc_R rc_rBase] in h.
  destruct q1; try discriminate.
  destruct Lr1 as [|? ?]; [|discriminate].
  destruct lb1 as [|? ?]; [|discriminate].
  destruct Rr1 as [|[t2 n2] Rr2]; [discriminate|].
  destruct t2; try discriminate.
  destruct Rr2 as [|[t0 n0] Rr3]; [discriminate|].
  destruct t0; try discriminate.
  destruct Rr3 as [|[t1 n1] R_out]; [discriminate|].
  destruct t1; try discriminate.
  destruct rb1; try discriminate.
  simpl in Hlb1 |- *.
  destruct (((n2 =? 1)%N && (n0 =? 1)%N && (n1 =? 1)%N)%bool) eqn:Hc; [|discriminate].
  split_andb; subst n2 n0 n1 L1.
  apply option_map_Some in h. destruct h as [body [Hsf Hxs]]; subst xs.
  unfold HubCfg. rewrite encItems_runsToItems.
  cbn [rc_q rc_L rc_lBase rc_R rc_rBase RightBaseStream] in Hs1.
  rewrite !encRuns_cons, encRuns_nil in Hs1.
  rewrite (stripFooterRuns_sound Hsf) in Hs1.
  rewrite ?N_to_nat_1, ?list_pow_one in Hs1; cbn [encTok] in Hs1;
    rewrite ?app_nil_r, ?Str_app_assoc in Hs1.
  exact Hs1.
Qed.

Lemma pop01_sound {rs rs' : list (Tok * N)} {isBlank : bool} {rB : Stream Sym}
    (hblank : isBlank = true -> rB = b0) (h : pop01 rs isBlank = Some rs') :
    encRuns rs *> rB = [S0; S1] *> encRuns rs' *> rB.
Proof.
  unfold pop01 in h.
  destruct (popBit rs isBlank) as [[[|] r1]|] eqn:H1; try discriminate.
  destruct (popBit r1 isBlank) as [[[|] r2]|] eqn:H2; try discriminate.
  inversion h; subst r2.
  rewrite (popBit_sound _ _ _ _ _ hblank H1), (popBit_sound _ _ _ _ _ hblank H2).
  reflexivity.
Qed.

Lemma stepRawHalt1_sound {R_tail : Stream Sym} {c c' : RawCfg} {cfg : Q * tape}
    (hd : RawDenote R_tail c cfg) (h : stepRawHalt1 c = Some c') :
    exists cfg', RawDenote R_tail c' cfg' /\ cfg -[ tm ]->* cfg'.
Proof.
  unfold stepRawHalt1 in h.
  destruct c as [q Lr lBase Rr rBase]; cbn [rc_q rc_L rc_lBase rc_R rc_rBase] in h.
  destruct q; try (exact (stepRaw_sound hd h)).
  destruct Lr as [|[t1 n1] Lr']; [exact (stepRaw_sound hd h)|].
  destruct t1; try (exact (stepRaw_sound hd h)).
  destruct Lr' as [|? ?]; [|exact (stepRaw_sound hd h)].
  destruct lBase as [|Ep rev]; [exact (stepRaw_sound hd h) |].
  destruct (((n1 =? 2)%N && (Ep =? 0)%N)%bool) eqn:Hc; [| exact (stepRaw_sound hd h)].
  split_andb; subst n1 Ep.
  destruct (pop01 Rr (isRBblank rBase)) as [R'|] eqn:Hp; [| exact (stepRaw_sound hd h)].
  destruct (itemsToRuns (List.rev rev)) as [prefRuns|] eqn:Hr; [| exact (stepRaw_sound hd h)].
  inversion h; subst c'.
  destruct hd as [L_base [hlb Hcfg]]; subst cfg. simpl in hlb |- *.
  assert (Hrb_ok : isRBblank rBase = true -> RightBaseStream R_tail rBase = b0).
  { destruct rBase; simpl; intros H; [reflexivity | discriminate]. }
  pose proof (pop01_sound Hrb_ok Hp) as H01.
  eexists. split; [exists b0; split; [reflexivity | reflexivity] |].
  cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. rewrite !encRuns_cons, H01, encRuns_append, (itemsToRuns_sound _ _ Hr). norm_runs.
  exact (PipeL_unwind hlb (encRuns R' *> RightBaseStream R_tail rBase)).
Qed.

Lemma runRawHaltUntil_sound : forall (fuel : nat) (R_tail : Stream Sym) (done : RawCfg -> bool)
    (c c' : RawCfg) (cfg : Q * tape),
  RawDenote R_tail c cfg ->
  runRawHaltUntil done fuel c = Some c' ->
  done c' = true /\ exists cfg', RawDenote R_tail c' cfg' /\ cfg -[ tm ]->* cfg'.
Proof.
  induction fuel as [|fuel IH]; intros R_tail done c c' cfg hd h; simpl in h.
  - destruct (done c) eqn:Hd; [|discriminate].
    inversion h; subst c'. split; [exact Hd | exists cfg; split; [exact hd | apply evstep_refl]].
  - destruct (done c) eqn:Hd.
    + inversion h; subst c'. split; [exact Hd | exists cfg; split; [exact hd | apply evstep_refl]].
    + destruct (stepRawHalt1 c) as [c1|] eqn:Hs; [|discriminate].
      destruct (stepRawHalt1_sound hd Hs) as [cfg1 [hd1 hst1]].
      destruct (IH R_tail done c1 c' cfg1 hd1 h) as [Hd' [cfg2 [hd2 hst2]]].
      split; [exact Hd' | exists cfg2; split; [exact hd2 | exact (stepStar_trans hst1 hst2)]].
Qed.

Lemma runPipeRawHalt_sound {prefixLen winLen fuel : nat} {xs : list RleItem}
    (hreach : c0 -[ tm ]->* HubCfg xs)
    (hhalt : runPipeRawHalt prefixLen winLen fuel xs = true) :
    halts tm c0.
Proof.
  unfold runPipeRawHalt in hhalt.
  destruct (splitAtList prefixLen xs) as [[pref afterPref]|] eqn:Hsp1; [|discriminate].
  destruct (splitAtList winLen afterPref) as [[win tail]|] eqn:Hsp2; [|discriminate].
  destruct (itemsToRuns win) as [winRuns|] eqn:Hwr; [|discriminate].
  assert (Hxs : xs = pref ++ (win ++ tail)).
  { rewrite (splitAtList_sound _ _ _ _ Hsp1), (splitAtList_sound _ _ _ _ Hsp2). reflexivity. }
  pose proof (itemsToRuns_sound _ _ Hwr) as Hwin.
  set (R_tail := encItems tail *> [S0; S1; S0; S1] *> b0) in *.
  set (rBase := if isEmpty tail then RBblank else RBtail) in *.
  set (R_body := if isEmpty tail then winRuns ++ footerRuns else winRuns) in *.
  assert (HRbody : encRuns R_body *> RightBaseStream R_tail rBase =
                   encItems win *> encItems tail *> [S0; S1; S0; S1] *> b0).
  { unfold R_body, rBase. destruct tail as [|t ts]; simpl.
    - rewrite encRuns_append, encRuns_footerRuns, Hwin, Str_app_assoc. reflexivity.
    - rewrite Hwin. reflexivity. }
  assert (Hstart : exists rc0 cfg0,
    (if Nat.eqb prefixLen O then
       Some (mkRawCfg E [] LBblank ((T_2, 1%N) :: (T_0, 1%N) :: (T_1, 1%N) :: R_body) rBase)
     else
       match step1HubPrefix pref with
       | None => None
       | Some (false, Ep, revPref) => Some (mkRawCfg F [(T_1, 2%N)] (LBpipe Ep revPref) R_body rBase)
       | Some (true, Ep, revPref) => Some (mkRawCfg A [(T_1, 1%N); (T_2, 1%N)] (LBpipe Ep revPref) R_body rBase)
       end) = Some rc0 /\
    RawDenote R_tail rc0 cfg0 /\ HubCfg xs -[ tm ]->* cfg0).
  { destruct prefixLen as [|p'].
    - simpl in Hsp1. inversion Hsp1; subst pref afterPref.
      eexists _, _. split; [reflexivity |]. split.
      + exists b0. split; [reflexivity | reflexivity].
      + rewrite Hxs. simpl app. unfold HubCfg.
        cbn [rc_q rc_L rc_lBase rc_R rc_rBase].
        rewrite encItems_append, Str_app_assoc, <- HRbody.
        norm_runs. apply evstep_refl.
    - simpl Nat.eqb.
      destruct (step1HubPrefix pref) as [[[isP2 Ep] revPref]|] eqn:Hpre; [|discriminate].
      destruct (step1HubPrefix_sound (win ++ tail) Hpre) as [Lt' [hp' hreach0]].
      rewrite <- Hxs in hreach0.
      destruct isP2.
      + eexists _, _. split; [reflexivity |]. split.
        * exists Lt'. split; [exact hp' | reflexivity].
        * cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. rewrite HRbody, <- Str_app_assoc, <- encItems_append.
          norm_runs. exact hreach0.
      + eexists _, _. split; [reflexivity |]. split.
        * exists Lt'. split; [exact hp' | reflexivity].
        * cbn [rc_q rc_L rc_lBase rc_R rc_rBase]. rewrite HRbody, <- Str_app_assoc, <- encItems_append.
          norm_runs. exact hreach0. }
  destruct Hstart as [rc0 [cfg0 [Hrc0 [Hd0 Hs0]]]].
  rewrite Hrc0 in hhalt.
  apply isSome_true_iff in hhalt. destruct hhalt as [rc1 Hrun].
  destruct (runRawHaltUntil_sound _ _ _ _ _ _ Hd0 Hrun) as [Hdone [cfg1 [Hd1 Hs1]]].
  destruct Hd1 as [L1 [Hlb1 Hcfg1]]; subst cfg1.
  destruct rc1 as [[| | | | |] Lr1 lb1 Rr1 rb1]; unfold isRawHalt in Hdone; cbn [rc_q rc_R rc_rBase] in Hdone; try discriminate.
  destruct (popBit Rr1 (isRBblank rb1)) as [[[|] R1]|] eqn:Hp; try discriminate.
  assert (Hrb_ok : isRBblank rb1 = true -> RightBaseStream R_tail rb1 = b0).
  { destruct rb1; simpl; intros H; [reflexivity | discriminate]. }
  pose proof (popBit_sound _ _ _ _ _ Hrb_ok Hp) as HR1.
  eapply evstep_halts; [exact (stepStar_trans hreach (stepStar_trans Hs0 Hs1)) |].
  simpl. rewrite HR1. reflexivity.
Qed.
