(* ========================================================================= *)
(* Propositional nat Cell Helpers & List Cancellation                        *)
(* ========================================================================= *)

Ltac eq_tuple :=
  repeat match goal with
  | |- (@pair _ _ _ _) = (@pair _ _ _ _) => f_equal
  end.

Lemma app_cancel_left {X : Type} {xs ys zs : list X} (h : xs ++ ys = xs ++ zs) : ys = zs.
Proof. exact (List.app_inv_head xs ys zs h). Qed.

Lemma app_cancel_right {X : Type} {xs ys zs : list X} (h : xs ++ zs = ys ++ zs) : xs = ys.
Proof. exact (List.app_inv_tail zs xs ys h). Qed.

Fixpoint sumList (xs : list nat) : nat :=
  match xs with
  | [] => 0
  | x :: xs' => x + sumList xs'
  end.

Lemma sumList_append (xs ys : list nat) :
  sumList (xs ++ ys) = sumList xs + sumList ys.
Proof.
  induction xs as [|x xs IH]; [reflexivity | simpl; lia].
Qed.

Definition encS (a : nat) (h : bool) (s0 : nat) (segs : list SegPiece) (aR : option nat) : list Sym :=
  ((((T2 ^^ a) ++ match aR with None => [] | Some r => T0 ++ (T2 ^^ r) end)
    ++ (if h then T5 else [])) ++ (T4 ^^ s0)) ++ encSegTail segs.

Lemma encSingle_eq_encS (a : N) (h : bool) (s0 : N) (segs : list SegPiece) (aR : option N) :
  encSingle a h s0 segs aR = encS (N.to_nat a) h (N.to_nat s0) segs (option_map N.to_nat aR).
Proof.
  unfold encSingle, encS. destruct aR; reflexivity.
Qed.

Definition sp1 (s1 : nat) : list SegPiece := [SPsingle (N.of_nat s1)].

Lemma encSegTail_sp1 (s1 : nat) : encSegTail (sp1 s1) = T3 ++ (T4 ^^ s1).
Proof.
  unfold sp1; cbn [encSegTail]. rewrite Nat2N.id, app_nil_r. reflexivity.
Qed.

Lemma encSegTail_single_eq_sp1 (s1 : N) :
  encSegTail [SPsingle s1] = encSegTail (sp1 (N.to_nat s1)).
Proof.
  unfold sp1; cbn [encSegTail]. rewrite N2Nat.id. reflexivity.
Qed.

(* ========================================================================= *)
(* Section 10.1: Universal Phase-2 Sink Interface (CanDumpTail)              *)
(* ========================================================================= *)

Definition isSkipP2List (xs : list RleItem) : bool :=
  List.forallb isSkipP2Item xs.

Lemma pipeL_mid_item {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    {x : RleItem} (hx : isSkipP2Item x = true) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL En (R_out ++ encItem x) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> (encItem x *> r)) -[ tm ]->* (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  destruct x as [a h s0 segTail aR | a b rep | a1 h1 b1 a2 h2 b2 rep | t n];
    cbn [isSkipP2Item] in hx; try discriminate.
  - destruct segTail as [|? ?]; [|discriminate].
    destruct aR as [?|]; [discriminate |].
    assert (Hok : h = true \/ (1 <= N.to_nat a /\ 1 <= N.to_nat s0)).
    { destruct h; [left; reflexivity | right; simpl in hx; split_andb; lia]. }
    destruct (pipeL_mid_cell (N.to_nat a) h (N.to_nat s0) Hok hp r) as [Lt' [hp' hs]].
    exists Lt'. split.
    + eapply pipeL_eqR; [| exact hp'].
      unfold encItem, encSingle; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
    + unfold encItem, encSingle; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc.
      rewrite ?append_assoc in hs. exact hs.
  - split_andb.
    destruct (pipeL_mid_transpRun (N.to_nat a - 1) (N.to_nat b - 1) (N.to_nat rep) hp r) as [Lt' [hp' hs]].
    exists Lt'. split.
    + eapply pipeL_eqR; [| exact hp']. unfold encItem.
      replace (N.to_nat a - 1 + 1) with (N.to_nat a) by lia.
      replace (N.to_nat b - 1 + 1) with (N.to_nat b) by lia. reflexivity.
    + unfold encItem.
      replace (N.to_nat a - 1 + 1) with (N.to_nat a) in hs by lia.
      replace (N.to_nat b - 1 + 1) with (N.to_nat b) in hs by lia. exact hs.
  - apply Bool.andb_true_iff in hx. destruct hx as [hx1 hx2].
    assert (Hok1 : h1 = true \/ (1 <= N.to_nat a1 /\ 1 <= N.to_nat b1)).
    { destruct h1; [left; reflexivity | right; simpl in hx1; split_andb; lia]. }
    assert (Hok2 : h2 = true \/ (1 <= N.to_nat a2 /\ 1 <= N.to_nat b2)).
    { destruct h2; [left; reflexivity | right; simpl in hx2; split_andb; lia]. }
    destruct (pipeL_mid_pairRun (N.to_nat a1) h1 (N.to_nat b1) (N.to_nat a2) h2 (N.to_nat b2) (N.to_nat rep)
      Hok1 Hok2 hp r) as [Lt' [hp' hs]].
    exists Lt'. split.
    + eapply pipeL_eqR; [| exact hp'].
      unfold encItem, encSingle; cbn [encSegTail]. rewrite ?app_nil_r. reflexivity.
    + unfold encItem, encSingle; cbn [encSegTail]. rewrite ?app_nil_r. exact hs.
Qed.

Lemma pipeL_mid_skipList : forall (xs : list RleItem) {En : nat} {R_out : list Sym} {Lt : Stream Sym},
    isSkipP2List xs = true -> PipeL En R_out Lt -> forall (r : Stream Sym),
    exists Lt', PipeL En (R_out ++ encItems xs) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> (encItems xs *> r)) -[ tm ]->* (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  induction xs as [|x rest IH]; intros En R_out Lt hxs hp r.
  - exists Lt. split; [cbn [encItems]; rewrite app_nil_r; exact hp | cbn [encItems]; rewrite zLan; apply evstep_refl].
  - cbn [isSkipP2List List.forallb] in hxs. apply Bool.andb_true_iff in hxs. destruct hxs as [hx hrest].
    destruct (pipeL_mid_item hx hp (encItems rest *> r)) as [Lt1 [hp1 hs1]].
    destruct (IH _ _ _ hrest hp1 r) as [Lt2 [hp2 hs2]].
    exists Lt2. split.
    + eapply pipeL_eqR; [| exact hp2]. cbn [encItems]. rewrite append_assoc. reflexivity.
    + cbn [encItems]. rewrite Str_app_assoc. exact (stepStar_trans hs1 hs2).
Qed.

Definition SinkReachTail (e : nat) (W W' : list Sym) (tail : Stream Sym) : Prop :=
  forall (R_out : list Sym) (Lt : Stream Sym),
    PipeL (e - 1) R_out Lt ->
    (([S1] *> T2 *> Lt) {{A}}> (W *> tail)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *> (R_out ++ W') *> tail)).

Definition CanDumpTail (W : list Sym) (En : nat) (W' : list Sym) (tail : Stream Sym) : Prop :=
  exists f : nat -> list Sym,
    f 0 = W /\ f En = W' /\
    forall t e, 1 <= e -> t + e <= En -> SinkReachTail e (f t) (f (t + e)) tail.

Lemma CanDumpTail_zero (W : list Sym) (tail : Stream Sym) :
  CanDumpTail W 0 W tail.
Proof.
  exists (fun _ : nat => W). split; [reflexivity | split; [reflexivity | intros; lia]].
Qed.

Lemma CanDumpTail_split {W W' : list Sym} {E1 E2 : nat} {tail : Stream Sym}
    (h : CanDumpTail W (E1 + E2) W' tail) :
    exists Wm, CanDumpTail W E1 Wm tail /\ CanDumpTail Wm E2 W' tail.
Proof.
  destruct h as [f [hf0 [hfE hstep]]].
  exists (f E1). split.
  - exists f. split; [exact hf0 | split; [reflexivity | intros t e he hle; apply hstep; lia]].
  - exists (fun t => f (E1 + t)). split; [f_equal; lia | split; [exact hfE |]].
    intros t e he hle. replace (E1 + (t + e)) with ((E1 + t) + e) by lia. apply hstep; lia.
Qed.

Lemma CanDumpTail_oneHub {W W' : list Sym} {En e : nat} {tail : Stream Sym}
    (h : CanDumpTail W En W' tail) (he : 1 <= e) (hle : e <= En) :
    exists W1, SinkReachTail e W W1 tail /\ CanDumpTail W1 (En - e) W' tail.
Proof.
  destruct h as [f [hf0 [hfE hstep]]].
  exists (f e). split.
  - pose proof (hstep 0 e he ltac:(lia)) as h0. rewrite hf0 in h0. simpl in h0. exact h0.
  - exists (fun t => f (e + t)). split; [f_equal; lia | split; [replace (e + (En - e)) with En by lia; exact hfE |]].
    intros t d hd htd. replace (e + (t + d)) with ((e + t) + d) by lia. apply hstep; lia.
Qed.

Lemma CanDumpTail_skipPrefix {pref : list RleItem} {W W' : list Sym} {En : nat}
    {tail : Stream Sym} (hpref : isSkipP2List pref = true)
    (h : CanDumpTail W En W' tail) :
    CanDumpTail (encItems pref ++ W) En (encItems pref ++ W') tail.
Proof.
  destruct h as [f [hf0 [hfE hstep]]].
  exists (fun t => encItems pref ++ f t).
  split; [rewrite hf0; reflexivity | split; [rewrite hfE; reflexivity |]].
  intros t e he hle R_out Lt hp.
  rewrite Str_app_assoc.
  destruct (pipeL_mid_skipList pref hpref hp (f t *> tail)) as [Lt1 [hp1 hs1]].
  eapply evstep_trans; [exact hs1 |].
  pose proof (hstep t e he hle (R_out ++ encItems pref) Lt1 hp1) as hs2.
  rewrite append_assoc in hs2. exact hs2.
Qed.

Lemma CanDumpTail_appendSuffix {W W' S : list Sym} {En : nat} {tail : Stream Sym}
    (h : CanDumpTail W En W' (S *> tail)) :
    CanDumpTail (W ++ S) En (W' ++ S) tail.
Proof.
  destruct h as [f [hf0 [hfE hstep]]].
  exists (fun t => f t ++ S).
  split; [rewrite hf0; reflexivity | split; [rewrite hfE; reflexivity |]].
  intros t e he hle R_out Lt hp.
  rewrite Str_app_assoc.
  pose proof (hstep t e he hle R_out Lt hp) as hs.
  (rewrite ?Str_app_assoc in hs; rewrite ?Str_app_assoc). exact hs.
Qed.

Lemma canDumpTail_end (a : nat) (h : bool) (s0 En : nat) (hok : h = true \/ (1 <= a /\ 1 <= s0)) :
    CanDumpTail (encS a h s0 [] None) En (encS a h (s0 + En) [] None) ([S0; S1; S0; S1] *> b0).
Proof.
  exists (fun t => encS a h (s0 + t) [] None).
  split; [replace (s0 + 0) with s0 by lia; reflexivity | split; [reflexivity |]].
  intros t e he hle R_out Lt hp.
  assert (hok_t : h = true \/ (1 <= a /\ 1 <= s0 + t)).
  { destruct hok as [H1 | [Ha Hs]]; [left; exact H1 | right; lia]. }
  destruct (pipeL_mid_cell a h (s0 + t) hok_t hp ([S0; S1; S0; S1] *> b0)) as [Lt1 [hp1 hs1]].
  assert (hs1' : (([S1] *> T2 *> Lt) {{A}}> (encS a h (s0 + t) [] None *> [S0; S1; S0; S1] *> b0))
                   -[ tm ]->* (([S1] *> T2 *> Lt1) {{A}}> ([S0; S1; S0; S1] *> b0))).
  { unfold encS; cbn [encSegTail]. (rewrite ?app_nil_r in hs1; rewrite ?append_assoc in hs1; rewrite ?app_nil_r; rewrite ?append_assoc). exact hs1. }
  eapply evstep_trans; [exact hs1' |].
  eapply evstep_trans; [exact (pipeL_dump_wall2 hp1) |].
  assert (hEq : (R_out ++ (((T2 ^^ a) ++ (if h then T5 else [])) ++ (T4 ^^ (s0 + t)))) ++ (T4 ^^ (e - 1 + 1)) =
                R_out ++ encS a h (s0 + (t + e)) [] None).
  { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc, <- list_pow_add.
    replace (s0 + t + (e - 1 + 1)) with (s0 + (t + e)) by lia. reflexivity. }
  rewrite hEq. apply evstep_refl.
Qed.

Lemma canDumpTail_asplit (aL : nat) (h : bool) (s0 : nat) (segTail : list SegPiece) (aR En : nat)
    (hok : h = true \/ 1 <= s0) (h2E : 2 * En <= aR) (tail : Stream Sym) :
    CanDumpTail (encS aL h s0 segTail (Some aR)) En
      (encS (aL + 2 * En) h s0 segTail (Some (aR - 2 * En))) tail.
Proof.
  exists (fun t => encS (aL + 2 * t) h s0 segTail (Some (aR - 2 * t))).
  split; [replace (aL + 2 * 0) with aL by lia; replace (aR - 2 * 0) with aR by lia; reflexivity |
          split; [reflexivity |]].
  intros t e he hle R_out Lt hp.
  assert (htail0 : exists tl, (if h then T5 else []) *> (T4 ^^ s0) *> encSegTail segTail *> tail = T0 *> tl).
  { destruct h.
    - exists ([S1; S0; S0; S1] *> (T4 ^^ s0) *> encSegTail segTail *> tail). reflexivity.
    - destruct hok as [Hf | hs0]; [discriminate |].
      rewrite zLan. replace s0 with (S (s0 - 1)) by lia. rewrite zPsr.
      exists ([S1; S0; S1; S1] *> (T4 ^^ (s0 - 1)) *> encSegTail segTail *> tail). reflexivity. }
  destruct htail0 as [tl htl].
  assert (hL : encS (aL + 2 * t) h s0 segTail (Some (aR - 2 * t)) *> tail =
               (T2 ^^ (aL + 2 * t)) *> T0 *> (T2 ^^ (aR - 2 * t)) *> T0 *> tl).
  { unfold encS. rewrite ?Str_app_assoc, htl. reflexivity. }
  rewrite hL.
  eapply evstep_trans; [exact (pipeL_dump_wall3 (E_rem := ltac:(match type of hp with PipeL ?x _ _ => exact x end)) (aL + 2 * t) (aR - 2 * t) ltac:(lia) hp tl) |].
  unfold encS. rewrite ?Str_app_assoc, htl.
  replace (aL + 2 * t + 2 * (e - 1 + 1)) with (aL + 2 * (t + e)) by lia.
  replace (aR - 2 * t - 2 * (e - 1 + 1)) with (aR - 2 * (t + e)) by lia.
  apply evstep_refl.
Qed.

Lemma canDumpTail_wall1 (a : nat) (h : bool) (s0 s1 : nat) (segRest : list SegPiece) (En : nat)
    (hok : h = true \/ (1 <= a /\ 1 <= s0)) (hEs1 : En <= s1) (tail : Stream Sym) :
    CanDumpTail (encS a h s0 (SPsingle (N.of_nat s1) :: segRest) None) En
      (encS a h (s0 + En) (SPsingle (N.of_nat (s1 - En)) :: segRest) None) tail.
Proof.
  exists (fun t => encS a h (s0 + t) (SPsingle (N.of_nat (s1 - t)) :: segRest) None).
  split; [replace (s0 + 0) with s0 by lia; replace (s1 - 0) with s1 by lia; reflexivity |
          split; [reflexivity |]].
  intros t e he hle R_out Lt hp.
  assert (hok_t : h = true \/ (1 <= a /\ 1 <= s0 + t)).
  { destruct hok as [H1 | [Ha Hs]]; [left; exact H1 | right; lia]. }
  destruct (pipeL_mid_cell a h (s0 + t) hok_t hp
    (T3 *> (T4 ^^ (s1 - t)) *> encSegTail segRest *> tail)) as [Lt1 [hp1 hs1]].
  assert (hL : encS a h (s0 + t) (SPsingle (N.of_nat (s1 - t)) :: segRest) None *> tail =
               (((T2 ^^ a) ++ (if h then T5 else [])) ++ (T4 ^^ (s0 + t))) *>
                 T3 *> (T4 ^^ (s1 - t)) *> encSegTail segRest *> tail).
  { unfold encS; cbn [encSegTail]. rewrite Nat2N.id, ?app_nil_r, ?Str_app_assoc. reflexivity. }
  rewrite hL.
  eapply evstep_trans; [exact hs1 |].
  eapply evstep_trans; [exact (pipeL_dump_wall1 (E_rem := ltac:(match type of hp1 with PipeL ?x _ _ => exact x end)) (s1 - t) ltac:(lia) hp1 (encSegTail segRest *> tail)) |].
  unfold encS; cbn [encSegTail]. rewrite Nat2N.id, ?app_nil_r, ?Str_app_assoc, <- pow_add_blank.
  replace (s0 + t + (e - 1 + 1)) with (s0 + (t + e)) by lia.
  replace (s1 - t - (e - 1 + 1)) with (s1 - (t + e)) by lia.
  apply evstep_refl.
Qed.

(* ========================================================================= *)
(* Section 10.2: Exact c0 Energy Ledger & Base-3 Odometer Arithmetic         *)
(* ========================================================================= *)

Definition c0Valid_nat (a0 : nat) (h0 : bool) (b0_v : nat) : bool :=
  Nat.leb 3 a0 &&
    (if h0 then Nat.eqb (a0 mod 2) 0 && Nat.leb 2 b0_v
     else Nat.eqb (a0 mod 2) 1 && Nat.leb 3 b0_v).

Definition c0Step1_nat (a0 : nat) (h0 : bool) (b0_v : nat) : nat * bool * nat :=
  if h0 then (a0 + 3, false, b0_v) else (a0 + 3, true, b0_v - 2).

Definition c0E1_nat (a0 : nat) (h0 : bool) (b0_v : nat) : nat :=
  if h0 then a0 / 2 - b0_v else a0 / 2 + 2 - b0_v.

Definition c0StepN_nat (a0 : nat) (h0 : bool) (b0_v Nv : nat) : nat * bool * nat :=
  let nH0 := if h0 then Nv / 2 else (Nv + 1) / 2 in
  (a0 + 3 * Nv, if Nat.eqb (Nv mod 2) 1 then negb h0 else h0, b0_v - 2 * nH0).

Definition c0TotalIn_nat (a0 : nat) (h0 : bool) (b0_v Nv : nat) : nat :=
  let M := Nv / 2 in
  let ah0 := a0 / 2 in
  let eEv := if h0 then ah0 - b0_v else ah0 + 2 - b0_v in
  let eOd := if h0 then ah0 + 3 - b0_v else ah0 + 4 - b0_v in
  let tot := M * (eEv + eOd) + 5 * M * (M - 1) in
  if Nat.eqb (Nv mod 2) 1 then tot + eEv + 5 * M else tot.

Lemma c0Valid_to_nat (a0 : N) (h0 : bool) (b0_v : N) :
  c0Valid a0 h0 b0_v = true -> c0Valid_nat (N.to_nat a0) h0 (N.to_nat b0_v) = true.
Proof.
  unfold c0Valid, c0Valid_nat. intros H.
  destruct h0; split_andb;
    pose proof (N2Nat_mod a0 2) as Hmod; simpl N.to_nat in Hmod;
    repeat (apply Bool.andb_true_iff; split);
    try (apply Nat.leb_le; lia);
    try (apply Nat.eqb_eq; lia).
Qed.

Lemma c0E1_to_nat (a0 : N) (h0 : bool) (b0_v : N) :
  N.to_nat (c0E1 a0 h0 b0_v) = c0E1_nat (N.to_nat a0) h0 (N.to_nat b0_v).
Proof.
  unfold c0E1, c0E1_nat.
  pose proof (N2Nat_div a0 2) as Hdiv; simpl N.to_nat in Hdiv.
  destruct h0; lia.
Qed.

Lemma c0StepN_to_nat (a0 : N) (h0 : bool) (b0_v Nv : N) :
  let '(a', h', b') := c0StepN a0 h0 b0_v Nv in
  (N.to_nat a', h', N.to_nat b') = c0StepN_nat (N.to_nat a0) h0 (N.to_nat b0_v) (N.to_nat Nv).
Proof.
  unfold c0StepN, c0StepN_nat.
  pose proof (N2Nat_div Nv 2) as Hd1; simpl N.to_nat in Hd1.
  pose proof (N2Nat_div (Nv + 1)%N 2) as Hd2; simpl N.to_nat in Hd2.
  pose proof (N2Nat_mod Nv 2) as Hmod; simpl N.to_nat in Hmod.
  replace (N.to_nat (Nv + 1)%N) with (N.to_nat Nv + 1) in Hd2 by lia.
  destruct ((Nv mod 2 =? 1)%N) eqn:Hm; split_andb.
  - assert (Hm' : Nat.eqb (N.to_nat Nv mod 2) 1 = true) by (apply Nat.eqb_eq; lia).
    rewrite Hm'. destruct h0; eq_tuple; lia.
  - assert (Hm' : Nat.eqb (N.to_nat Nv mod 2) 1 = false) by (apply Nat.eqb_neq; lia).
    rewrite Hm'. destruct h0; eq_tuple; lia.
Qed.

Lemma c0TotalIn_to_nat (a0 : N) (h0 : bool) (b0_v Nv : N) :
  N.to_nat (c0TotalIn a0 h0 b0_v Nv) = c0TotalIn_nat (N.to_nat a0) h0 (N.to_nat b0_v) (N.to_nat Nv).
Proof.
  unfold c0TotalIn, c0TotalIn_nat.
  pose proof (N2Nat_div Nv 2) as Hd1; simpl N.to_nat in Hd1.
  pose proof (N2Nat_div a0 2) as Hd2; simpl N.to_nat in Hd2.
  pose proof (N2Nat_mod Nv 2) as Hmod; simpl N.to_nat in Hmod.
  destruct ((Nv mod 2 =? 1)%N) eqn:Hm; split_andb.
  - assert (Hm' : Nat.eqb (N.to_nat Nv mod 2) 1 = true) by (apply Nat.eqb_eq; lia).
    rewrite Hm'. destruct h0; nia.
  - assert (Hm' : Nat.eqb (N.to_nat Nv mod 2) 1 = false) by (apply Nat.eqb_neq; lia).
    rewrite Hm'. destruct h0; nia.
Qed.

Lemma c0StepN_zero (a0 : nat) (h0 : bool) (b0_v : nat) :
  c0StepN_nat a0 h0 b0_v 0 = (a0, h0, b0_v).
Proof.
  unfold c0StepN_nat. destruct h0; simpl; eq_tuple; lia.
Qed.

Lemma div2_cases (n : nat) : n = 2 * (n / 2) \/ n = 2 * (n / 2) + 1.
Proof.
  pose proof (Nat.div_mod n 2 ltac:(lia)).
  pose proof (Nat.mod_upper_bound n 2 ltac:(lia)).
  lia.
Qed.

Lemma c0StepN_succ (a0 : nat) (h0 : bool) (b0_v Nv : nat) :
  let '(a1, h1, b1) := c0Step1_nat a0 h0 b0_v in
  c0StepN_nat a0 h0 b0_v (Nv + 1) = c0StepN_nat a1 h1 b1 Nv.
Proof.
  unfold c0Step1_nat, c0StepN_nat.
  destruct (div2_cases Nv) as [Hev | Hodd].
  - assert (Hm0 : Nv mod 2 = 0) by (pose proof (Nat.div_mod Nv 2 ltac:(lia)); lia).
    assert (Hm1 : (Nv + 1) mod 2 = 1) by (pose proof (Nat.div_mod (Nv + 1) 2 ltac:(lia)); pose proof (Nat.mod_upper_bound (Nv + 1) 2 ltac:(lia)); lia).
    assert (Hd1 : (Nv + 1) / 2 = Nv / 2) by (pose proof (Nat.div_mod (Nv + 1) 2 ltac:(lia)); lia).
    assert (Hd2 : (Nv + 1 + 1) / 2 = Nv / 2 + 1) by (pose proof (Nat.div_mod (Nv + 1 + 1) 2 ltac:(lia)); pose proof (Nat.mod_upper_bound (Nv + 1 + 1) 2 ltac:(lia)); lia).
    replace (a0 + 3 * (Nv + 1)) with (a0 + 3 + 3 * Nv) by lia.
    destruct h0; cbv beta iota zeta; rewrite ?Hm0, ?Hm1, ?Hd1, ?Hd2; simpl Nat.eqb; simpl negb; cbv beta iota zeta;
      try (replace (b0_v - 2 * (Nv / 2 + 1)) with (b0_v - 2 - 2 * (Nv / 2)) by lia); reflexivity.
  - assert (Hm0 : Nv mod 2 = 1) by (pose proof (Nat.div_mod Nv 2 ltac:(lia)); lia).
    assert (Hm1 : (Nv + 1) mod 2 = 0) by (pose proof (Nat.div_mod (Nv + 1) 2 ltac:(lia)); pose proof (Nat.mod_upper_bound (Nv + 1) 2 ltac:(lia)); lia).
    assert (Hd1 : (Nv + 1) / 2 = Nv / 2 + 1) by (pose proof (Nat.div_mod (Nv + 1) 2 ltac:(lia)); lia).
    assert (Hd2 : (Nv + 1 + 1) / 2 = Nv / 2 + 1) by (pose proof (Nat.div_mod (Nv + 1 + 1) 2 ltac:(lia)); pose proof (Nat.mod_upper_bound (Nv + 1 + 1) 2 ltac:(lia)); lia).
    replace (a0 + 3 * (Nv + 1)) with (a0 + 3 + 3 * Nv) by lia.
    destruct h0; cbv beta iota zeta; rewrite ?Hm0, ?Hm1, ?Hd1, ?Hd2; simpl Nat.eqb; simpl negb; cbv beta iota zeta;
      try (replace (b0_v - 2 * (Nv / 2 + 1)) with (b0_v - 2 - 2 * (Nv / 2)) by lia); reflexivity.
Qed.

Lemma c0Valid_step1 {a0 : nat} {h0 : bool} {b0_v : nat}
    (hv : c0Valid_nat a0 h0 b0_v = true) (hb : 4 <= b0_v) :
    let '(a1, h1, b1) := c0Step1_nat a0 h0 b0_v in
    c0Valid_nat a1 h1 b1 = true.
Proof.
  unfold c0Valid_nat, c0Step1_nat in *.
  pose proof (Nat.div_mod a0 2 ltac:(lia)).
  pose proof (Nat.div_mod (a0 + 3) 2 ltac:(lia)).
  pose proof (Nat.mod_upper_bound (a0 + 3) 2 ltac:(lia)).
  destruct h0.
  - apply Bool.andb_true_iff in hv; destruct hv as [Ha Hb]; apply Bool.andb_true_iff in Hb; destruct Hb as [Hm Hb].
    apply Nat.leb_le in Ha; apply Nat.eqb_eq in Hm; apply Nat.leb_le in Hb.
    repeat (apply Bool.andb_true_iff; split); try (apply Nat.leb_le; lia); apply Nat.eqb_eq; lia.
  - apply Bool.andb_true_iff in hv; destruct hv as [Ha Hb]; apply Bool.andb_true_iff in Hb; destruct Hb as [Hm Hb].
    apply Nat.leb_le in Ha; apply Nat.eqb_eq in Hm; apply Nat.leb_le in Hb.
    repeat (apply Bool.andb_true_iff; split); try (apply Nat.leb_le; lia); apply Nat.eqb_eq; lia.
Qed.

Lemma c0TotalIn_zero (a0 : nat) (h0 : bool) (b0_v : nat) :
  c0TotalIn_nat a0 h0 b0_v 0 = 0.
Proof.
  unfold c0TotalIn_nat. destruct h0; reflexivity.
Qed.

Lemma c0TotalIn_succ {a0 : nat} {h0 : bool} {b0_v Nv : nat}
    (hv : c0Valid_nat a0 h0 b0_v = true) (he : b0_v <= a0 / 2) :
    let '(a1, h1, b1) := c0Step1_nat a0 h0 b0_v in
    c0TotalIn_nat a0 h0 b0_v (Nv + 1) = c0E1_nat a0 h0 b0_v + c0TotalIn_nat a1 h1 b1 Nv.
Proof.
  unfold c0Valid_nat, c0Step1_nat, c0E1_nat, c0TotalIn_nat in *.
  pose proof (Nat.div_mod Nv 2 ltac:(lia)) as HdmN.
  pose proof (Nat.mod_upper_bound Nv 2 ltac:(lia)) as HmodN.
  pose proof (Nat.div_mod (Nv + 1) 2 ltac:(lia)) as HdmN1.
  pose proof (Nat.mod_upper_bound (Nv + 1) 2 ltac:(lia)) as HmodN1.
  pose proof (Nat.div_mod a0 2 ltac:(lia)) as Hdma0.
  pose proof (Nat.div_mod (a0 + 3) 2 ltac:(lia)) as Hdma3.
  pose proof (Nat.mod_upper_bound (a0 + 3) 2 ltac:(lia)) as Hmoda3.
  destruct h0.
  - apply Bool.andb_true_iff in hv; destruct hv as [Ha Hb]; apply Bool.andb_true_iff in Hb; destruct Hb as [Hm Hb].
    apply Nat.leb_le in Ha; apply Nat.eqb_eq in Hm; apply Nat.leb_le in Hb.
    assert (Ha3 : (a0 + 3) / 2 = a0 / 2 + 1) by lia.
    rewrite Ha3.
    destruct (Nat.eq_dec (Nv mod 2) 0) as [Hev | Hodd].
    + assert (Hd1 : (Nv + 1) / 2 = Nv / 2) by lia.
      assert (Hm1 : (Nv + 1) mod 2 = 1) by lia.
      rewrite Hev, Hd1, Hm1. simpl Nat.eqb.
      set (M := Nv / 2); clearbody M.
      set (d := a0 / 2 - b0_v).
      assert (Hah : a0 / 2 = b0_v + d) by (unfold d; lia).
      rewrite Hah. clear - Hb.
      replace (b0_v + d - b0_v) with d by lia.
      replace (b0_v + d + 3 - b0_v) with (d + 3) by lia.
      replace (b0_v + d + 1 + 2 - b0_v) with (d + 3) by lia.
      replace (b0_v + d + 1 + 4 - b0_v) with (d + 5) by lia.
      destruct M as [|m]; simpl; lia.
    + assert (Hm0 : Nv mod 2 = 1) by lia.
      assert (Hd1 : (Nv + 1) / 2 = Nv / 2 + 1) by lia.
      assert (Hm1 : (Nv + 1) mod 2 = 0) by lia.
      rewrite Hm0, Hd1, Hm1. simpl Nat.eqb.
      set (M := Nv / 2); clearbody M.
      set (d := a0 / 2 - b0_v).
      assert (Hah : a0 / 2 = b0_v + d) by (unfold d; lia).
      rewrite Hah. clear - Hb.
      replace (b0_v + d - b0_v) with d by lia.
      replace (b0_v + d + 3 - b0_v) with (d + 3) by lia.
      replace (b0_v + d + 1 + 2 - b0_v) with (d + 3) by lia.
      replace (b0_v + d + 1 + 4 - b0_v) with (d + 5) by lia.
      replace (M + 1 - 1) with M by lia.
      destruct M as [|m]; [simpl; lia | replace (S m - 1) with m by lia; nia].
  - apply Bool.andb_true_iff in hv; destruct hv as [Ha Hb]; apply Bool.andb_true_iff in Hb; destruct Hb as [Hm Hb].
    apply Nat.leb_le in Ha; apply Nat.eqb_eq in Hm; apply Nat.leb_le in Hb.
    assert (Ha3 : (a0 + 3) / 2 = a0 / 2 + 2) by lia.
    rewrite Ha3.
    destruct (Nat.eq_dec (Nv mod 2) 0) as [Hev | Hodd].
    + assert (Hd1 : (Nv + 1) / 2 = Nv / 2) by lia.
      assert (Hm1 : (Nv + 1) mod 2 = 1) by lia.
      rewrite Hev, Hd1, Hm1. simpl Nat.eqb.
      set (M := Nv / 2); clearbody M.
      set (d := a0 / 2 - b0_v).
      assert (Hah : a0 / 2 = b0_v + d) by (unfold d; lia).
      rewrite Hah. clear - Hb.
      replace (b0_v + d + 2 - b0_v) with (d + 2) by lia.
      replace (b0_v + d + 4 - b0_v) with (d + 4) by lia.
      replace (b0_v + d + 2 - (b0_v - 2)) with (d + 4) by lia.
      replace (b0_v + d + 2 + 3 - (b0_v - 2)) with (d + 7) by lia.
      destruct M as [|m]; simpl; lia.
    + assert (Hm0 : Nv mod 2 = 1) by lia.
      assert (Hd1 : (Nv + 1) / 2 = Nv / 2 + 1) by lia.
      assert (Hm1 : (Nv + 1) mod 2 = 0) by lia.
      rewrite Hm0, Hd1, Hm1. simpl Nat.eqb.
      set (M := Nv / 2); clearbody M.
      set (d := a0 / 2 - b0_v).
      assert (Hah : a0 / 2 = b0_v + d) by (unfold d; lia).
      rewrite Hah. clear - Hb.
      replace (b0_v + d + 2 - b0_v) with (d + 2) by lia.
      replace (b0_v + d + 4 - b0_v) with (d + 4) by lia.
      replace (b0_v + d + 2 - (b0_v - 2)) with (d + 4) by lia.
      replace (b0_v + d + 2 + 3 - (b0_v - 2)) with (d + 7) by lia.
      replace (M + 1 - 1) with M by lia.
      destruct M as [|m]; [simpl; lia | replace (S m - 1) with m by lia; nia].
Qed.

Lemma c0E1_step1_ge {a0 : nat} {h0 : bool} {b0_v : nat}
    (hv : c0Valid_nat a0 h0 b0_v = true) (he : b0_v <= a0 / 2) :
    let '(a1, h1, b1) := c0Step1_nat a0 h0 b0_v in
    c0E1_nat a0 h0 b0_v + 2 <= c0E1_nat a1 h1 b1.
Proof.
  unfold c0Valid_nat, c0Step1_nat, c0E1_nat in *.
  pose proof (Nat.div_mod a0 2 ltac:(lia)).
  pose proof (Nat.div_mod (a0 + 3) 2 ltac:(lia)).
  pose proof (Nat.mod_upper_bound (a0 + 3) 2 ltac:(lia)).
  destruct h0;
    apply Bool.andb_true_iff in hv; destruct hv as [Ha Hb];
    apply Bool.andb_true_iff in Hb; destruct Hb as [Hm Hb];
    apply Nat.leb_le in Ha; apply Nat.eqb_eq in Hm; apply Nat.leb_le in Hb; lia.
Qed.

Definition transpItemCost_nat (it : RleItem) : nat := N.to_nat (transpItemCost it).
Definition transpListCost_nat (xs : list RleItem) : nat := N.to_nat (transpListCost xs).

Lemma transpListCost_nat_cons (x : RleItem) (xs : list RleItem) :
  transpListCost_nat (x :: xs) = transpItemCost_nat x + transpListCost_nat xs.
Proof.
  unfold transpListCost_nat, transpItemCost_nat. cbn [transpListCost]. lia.
Qed.

Definition digState_nat (a : nat) (h : bool) : option nat :=
  if h then
    if Nat.eqb (a mod 2) 1 then Some 0 else if Nat.leb 2 a then Some 1 else None
  else
    if Nat.eqb (a mod 2) 1 then Some 2 else None.

Lemma digState_to_nat (a : N) (h : bool) :
  option_map N.to_nat (digState a h) = digState_nat (N.to_nat a) h.
Proof.
  unfold digState, digState_nat.
  pose proof (N2Nat_mod a 2) as Hmod; simpl N.to_nat in Hmod.
  destruct h.
  - destruct ((a mod 2 =? 1)%N) eqn:Hm; split_andb.
    + assert (Hm' : Nat.eqb (N.to_nat a mod 2) 1 = true) by (apply Nat.eqb_eq; lia).
      rewrite Hm'. reflexivity.
    + assert (Hm' : Nat.eqb (N.to_nat a mod 2) 1 = false) by (apply Nat.eqb_neq; lia).
      rewrite Hm'.
      destruct ((2 <=? a)%N) eqn:Ha; split_andb.
      * assert (Ha' : Nat.leb 2 (N.to_nat a) = true) by (apply Nat.leb_le; lia).
        rewrite Ha'. reflexivity.
      * assert (Ha' : Nat.leb 2 (N.to_nat a) = false) by (apply Nat.leb_gt; lia).
        rewrite Ha'. reflexivity.
  - destruct ((a mod 2 =? 1)%N) eqn:Hm; split_andb.
    + assert (Hm' : Nat.eqb (N.to_nat a mod 2) 1 = true) by (apply Nat.eqb_eq; lia).
      rewrite Hm'. reflexivity.
    + assert (Hm' : Nat.eqb (N.to_nat a mod 2) 1 = false) by (apply Nat.eqb_neq; lia).
      rewrite Hm'. reflexivity.
Qed.

Lemma digState_isSome_to_nat (a : N) (h : bool) :
  isSome (digState a h) = isSome (digState_nat (N.to_nat a) h).
Proof.
  rewrite <- digState_to_nat. destruct (digState a h); reflexivity.
Qed.

Definition digStep1_nat (a : nat) (h : bool) (b : nat) : nat * bool * nat * nat * bool :=
  if h then
    if Nat.eqb (a mod 2) 1 then (a + 1, true, b - 1, a / 2, false)
    else (a + 1, false, b, a / 2, false)
  else
    (a, true, b - 1, a / 2 + b, true).

Definition digCycleCost_nat (a : nat) (h : bool) (b Qv : nat) : nat :=
  let base := 3 * (a / 2) + b + (if h && Nat.eqb (a mod 2) 0 then 0 else 1) in
  Qv * base + (Qv * (Qv - 1)) / 2.

Fixpoint digStepN_nat (Cv a : nat) (h : bool) (b : nat) : nat * bool * nat * nat * nat :=
  match Cv with
  | 0 => (a, h, b, 0, 0)
  | S C' =>
      let '(a1, h1, b1, c1, k1) := digStep1_nat a h b in
      let '(a2, h2, b2, c2, k2) := digStepN_nat C' a1 h1 b1 in
      (a2, h2, b2, c1 + c2, (if k1 then 1 else 0) + k2)
  end.

Lemma digStep1_to_nat (a : N) (h : bool) (b : N) :
  let '(a', h', b', c', cry) := digStep1 a h b in
  (N.to_nat a', h', N.to_nat b', N.to_nat c', cry) = digStep1_nat (N.to_nat a) h (N.to_nat b).
Proof.
  unfold digStep1, digStep1_nat.
  pose proof (N2Nat_div a 2) as Hdiv; simpl N.to_nat in Hdiv.
  pose proof (N2Nat_mod a 2) as Hmod; simpl N.to_nat in Hmod.
  destruct h; [| eq_tuple; lia].
  destruct ((a mod 2 =? 1)%N) eqn:Hm; split_andb.
  - assert (Hm' : Nat.eqb (N.to_nat a mod 2) 1 = true) by (apply Nat.eqb_eq; lia).
    rewrite Hm'. eq_tuple; lia.
  - assert (Hm' : Nat.eqb (N.to_nat a mod 2) 1 = false) by (apply Nat.eqb_neq; lia).
    rewrite Hm'. eq_tuple; lia.
Qed.

Lemma digCycleCost_to_nat (a : N) (h : bool) (b Qv : N) :
  N.to_nat (digCycleCost a h b Qv) = digCycleCost_nat (N.to_nat a) h (N.to_nat b) (N.to_nat Qv).
Proof.
  unfold digCycleCost, digCycleCost_nat; cbv beta zeta.
  pose proof (N2Nat_div a 2) as Hdiv; simpl N.to_nat in Hdiv.
  pose proof (N2Nat_mod a 2) as Hmod; simpl N.to_nat in Hmod.
  pose proof (N2Nat_div (Qv * (Qv - 1))%N 2) as Htri; simpl N.to_nat in Htri.
  replace (N.to_nat (Qv * (Qv - 1))%N) with (N.to_nat Qv * (N.to_nat Qv - 1)) in Htri by nia.
  destruct h; cbn [andb].
  - destruct ((a mod 2 =? 0)%N) eqn:Hm; split_andb.
    + assert (Hm' : Nat.eqb (N.to_nat a mod 2) 0 = true) by (apply Nat.eqb_eq; lia).
      rewrite Hm'. nia.
    + assert (Hm' : Nat.eqb (N.to_nat a mod 2) 0 = false) by (apply Nat.eqb_neq; lia).
      rewrite Hm'. nia.
  - nia.
Qed.

Lemma digStep1_3cycles (a : nat) (h : bool) (b : nat) (_ha : 1 <= a) (hb : 2 <= b)
    (hs : isSome (digState_nat a h) = true) :
    let '(a1, h1, b1, c1, k1) := digStep1_nat a h b in
    let '(a2, h2, b2, c2, k2) := digStep1_nat a1 h1 b1 in
    let '(a3, h3, b3, c3, k3) := digStep1_nat a2 h2 b2 in
    a3 = a + 2 /\ h3 = h /\ b3 = b - 2 /\
    c1 + c2 + c3 = digCycleCost_nat a h b 1 /\
    (if k1 then 1 else 0) + (if k2 then 1 else 0) + (if k3 then 1 else 0) = 1.
Proof.
  unfold digState_nat, digStep1_nat, digCycleCost_nat in *.
  pose proof (Nat.div_mod a 2 ltac:(lia)).
  pose proof (Nat.mod_upper_bound a 2 ltac:(lia)).
  pose proof (Nat.div_mod (a + 1) 2 ltac:(lia)).
  pose proof (Nat.mod_upper_bound (a + 1) 2 ltac:(lia)).
  pose proof (Nat.div_mod (a + 1 + 1) 2 ltac:(lia)).
  pose proof (Nat.mod_upper_bound (a + 1 + 1) 2 ltac:(lia)).
  replace ((1 * (1 - 1)) / 2) with 0 by reflexivity.
  destruct h.
  - destruct (Nat.eqb (a mod 2) 1) eqn:Hm1.
    + pose proof (proj1 (Nat.eqb_eq _ _) Hm1) as Hm1v.
      assert (Hm2 : Nat.eqb ((a + 1) mod 2) 1 = false) by (apply Nat.eqb_neq; lia).
      assert (Hm0 : Nat.eqb (a mod 2) 0 = false) by (apply Nat.eqb_neq; lia).
      cbn [andb]; rewrite Hm2, Hm0. cbv beta iota zeta. repeat split; lia.
    + pose proof (proj1 (Nat.eqb_neq _ _) Hm1) as Hm1v.
      assert (Hm0 : Nat.eqb (a mod 2) 0 = true) by (apply Nat.eqb_eq; lia).
      assert (Hm2 : Nat.eqb ((a + 1) mod 2) 1 = true) by (apply Nat.eqb_eq; lia).
      cbn [andb]; rewrite Hm2, Hm0. cbv beta iota zeta. repeat split; lia.
  - destruct (Nat.eqb (a mod 2) 1) eqn:Hm1; [| simpl in hs; discriminate].
    pose proof (proj1 (Nat.eqb_eq _ _) Hm1) as Hm1v.
    assert (Hm2 : Nat.eqb ((a + 1) mod 2) 1 = false) by (apply Nat.eqb_neq; lia).
    cbn [andb]; rewrite Hm2. cbv beta iota zeta. repeat split; lia.
Qed.

Lemma digCycleCost_succ (a : nat) (h : bool) (b Qv : nat) (hb : 2 <= b) :
  digCycleCost_nat a h b (Qv + 1) = digCycleCost_nat a h b 1 + digCycleCost_nat (a + 2) h (b - 2) Qv.
Proof.
  unfold digCycleCost_nat; cbv beta zeta.
  assert (Hdiv : (a + 2) / 2 = a / 2 + 1).
  { pose proof (Nat.div_mod a 2 ltac:(lia)).
    pose proof (Nat.mod_upper_bound a 2 ltac:(lia)).
    pose proof (Nat.div_mod (a + 2) 2 ltac:(lia)).
    pose proof (Nat.mod_upper_bound (a + 2) 2 ltac:(lia)).
    lia. }
  assert (Hmod : (a + 2) mod 2 = a mod 2).
  { pose proof (Nat.div_mod a 2 ltac:(lia)).
    pose proof (Nat.mod_upper_bound a 2 ltac:(lia)).
    pose proof (Nat.div_mod (a + 2) 2 ltac:(lia)).
    pose proof (Nat.mod_upper_bound (a + 2) 2 ltac:(lia)).
    lia. }
  rewrite Hdiv, Hmod; clear Hdiv Hmod.
  assert (Htri : ((Qv + 1) * (Qv + 1 - 1)) / 2 = Qv + (Qv * (Qv - 1)) / 2).
  { clear. destruct Qv as [|q]; [reflexivity |].
    replace (S q + 1 - 1) with (S q) by lia.
    replace (S q - 1) with q by lia.
    assert (Hev : (S q * q) mod 2 = 0).
    { destruct (div2_cases q) as [He | Ho].
      - replace (S q * q) with ((S q * (q / 2)) * 2) by nia.
        apply Nat.Div0.mod_mul.
      - replace (S q * q) with (((q / 2 + 1) * q) * 2) by nia.
        apply Nat.Div0.mod_mul. }
    pose proof (Nat.div_mod (S q * q) 2 ltac:(lia)) as Hq.
    pose proof (Nat.div_mod ((S q + 1) * S q) 2 ltac:(lia)) as Hq1.
    pose proof (Nat.mod_upper_bound ((S q + 1) * S q) 2 ltac:(lia)) as Hqm1.
    assert (Hstep : (S q + 1) * S q = S q * q + 2 * S q)
      by (rewrite Nat.add_comm; simpl; lia).
    lia. }
  rewrite Htri; clear Htri.
  replace ((1 * (1 - 1)) / 2) with 0 by reflexivity.
  destruct (h && Nat.eqb (a mod 2) 0); nia.
Qed.

Lemma digStepN_add : forall (C1 C2 a : nat) (h : bool) (b : nat),
  let '(a1, h1, b1, c1, k1) := digStepN_nat C1 a h b in
  let '(a2, h2, b2, c2, k2) := digStepN_nat C2 a1 h1 b1 in
  digStepN_nat (C1 + C2) a h b = (a2, h2, b2, c1 + c2, k1 + k2).
Proof.
  induction C1 as [|n IH]; intros C2 a h b; [simpl; destruct (digStepN_nat C2 a h b) as [[[[? ?] ?] ?] ?]; reflexivity |].
  simpl digStepN_nat.
  destruct (digStep1_nat a h b) as [[[[a1 h1] b1] c1] k1].
  pose proof (IH C2 a1 h1 b1) as Hrec.
  destruct (digStepN_nat n a1 h1 b1) as [[[[am hm] bm] cm] km].
  destruct (digStepN_nat C2 am hm bm) as [[[[a2 h2] b2] c2] k2].
  rewrite Hrec. eq_tuple; lia.
Qed.

Lemma digStepN_3Q : forall (Qv a : nat) (h : bool) (b : nat),
  1 <= a -> 2 * Qv <= b -> isSome (digState_nat a h) = true ->
  digStepN_nat (3 * Qv) a h b = (a + 2 * Qv, h, b - 2 * Qv, digCycleCost_nat a h b Qv, Qv).
Proof.
  induction Qv as [|q IH]; intros a h b ha hb hs.
  - simpl. unfold digCycleCost_nat. simpl. eq_tuple; lia.
  - replace (3 * S q) with (3 + 3 * q) by lia.
    pose proof (digStepN_add 3 (3 * q) a h b) as Hadd.
    pose proof (digStep1_3cycles a h b ha ltac:(lia) hs) as Hcyc.
    assert (H3 : digStepN_nat 3 a h b = (a + 2, h, b - 2, digCycleCost_nat a h b 1, 1)).
    { cbn [digStepN_nat].
      destruct (digStep1_nat a h b) as [[[[a1 h1] b1] c1] k1].
      destruct (digStep1_nat a1 h1 b1) as [[[[a2 h2] b2] c2] k2].
      destruct (digStep1_nat a2 h2 b2) as [[[[a3 h3] b3] c3] k3].
      destruct Hcyc as [Ha3 [Hh3 [Hb3 [Hc3 Hk3]]]].
      subst a3 h3 b3.
      eq_tuple; try reflexivity;
        [ rewrite <- Hc3; lia
        | destruct k1, k2, k3; lia ]. }
    rewrite H3 in Hadd.
    assert (Hs2 : isSome (digState_nat (a + 2) h) = true).
    { unfold digState_nat in hs |- *.
      pose proof (Nat.div_mod a 2 ltac:(lia)).
      pose proof (Nat.div_mod (a + 2) 2 ltac:(lia)).
      pose proof (Nat.mod_upper_bound a 2 ltac:(lia)).
      pose proof (Nat.mod_upper_bound (a + 2) 2 ltac:(lia)).
      assert (Hmod : (a + 2) mod 2 = a mod 2) by lia.
      rewrite Hmod. destruct h; [| exact hs].
      destruct (Nat.eqb (a mod 2) 1); [reflexivity |].
      destruct (Nat.leb 2 a) eqn:Hleb2; [| simpl in hs; discriminate].
      apply Nat.leb_le in Hleb2.
      assert (H2' : Nat.leb 2 (a + 2) = true) by (apply Nat.leb_le; lia).
      rewrite H2'. reflexivity. }
    rewrite (IH (a + 2) h (b - 2) ltac:(lia) ltac:(lia) Hs2) in Hadd.
    rewrite Hadd.
    replace (S q) with (q + 1) by lia.
    rewrite (digCycleCost_succ a h b q ltac:(lia)).
    eq_tuple; lia.
Qed.

Lemma digStepGo_to_nat : forall (u : nat) (aa : N) (hh : bool) (bb cc co : N),
  let '(a', h', b', c', k') := digStepGo u aa hh bb cc co in
  let '(a2, h2, b2, c2, k2) := digStepN_nat u (N.to_nat aa) hh (N.to_nat bb) in
  (N.to_nat a', h', N.to_nat b', N.to_nat c', N.to_nat k') =
  (a2, h2, b2, N.to_nat cc + c2, N.to_nat co + k2).
Proof.
  induction u as [|u' IH]; intros aa hh bb cc co.
  - simpl. eq_tuple; lia.
  - simpl digStepGo; simpl digStepN_nat.
    pose proof (digStep1_to_nat aa hh bb) as Hd1.
    destruct (digStep1 aa hh bb) as [[[[aa' hh'] bb'] dc] cry].
    rewrite <- Hd1; clear Hd1.
    pose proof (IH aa' hh' bb' (cc + dc)%N (co + (if cry then 1 else 0))%N) as Hrec.
    destruct (digStepGo u' aa' hh' bb' (cc + dc)%N (co + (if cry then 1 else 0))%N) as [[[[af hf] bf] cf] kf].
    destruct (digStepN_nat u' (N.to_nat aa') hh' (N.to_nat bb')) as [[[[a2 h2] b2] c2] k2].
    injection Hrec as ? ? ? ? ?.
    eq_tuple; try assumption; destruct cry; lia.
Qed.

Lemma digStepFast_eq_digStepN (a : N) (h : bool) (b Cv : N)
    (ha : (1 <= a)%N) (hb : (2 * (Cv / 3) <= b)%N) (hs : isSome (digState a h) = true) :
    let '(a', h', b', c', k') := digStepFast a h b Cv in
    (N.to_nat a', h', N.to_nat b', N.to_nat c', N.to_nat k') =
    digStepN_nat (N.to_nat Cv) (N.to_nat a) h (N.to_nat b).
Proof.
  unfold digStepFast.
  pose proof (N2Nat_div Cv 3) as Hdiv; simpl N.to_nat in Hdiv.
  pose proof (N2Nat_mod Cv 3) as Hmod; simpl N.to_nat in Hmod.
  set (Qv := (Cv / 3)%N).
  set (rem := N.to_nat (Cv mod 3)%N).
  assert (HCv : N.to_nat Cv = 3 * N.to_nat Qv + rem).
  { unfold Qv, rem. rewrite Hdiv, Hmod. apply (Nat.div_mod (N.to_nat Cv) 3 ltac:(lia)). }
  rewrite HCv.
  pose proof (digStepN_add (3 * N.to_nat Qv) rem (N.to_nat a) h (N.to_nat b)) as Hadd.
  rewrite digState_isSome_to_nat in hs.
  rewrite (digStepN_3Q (N.to_nat Qv) (N.to_nat a) h (N.to_nat b) ltac:(lia) ltac:(lia) hs) in Hadd.
  pose proof (digStepGo_to_nat rem (a + 2 * Qv)%N h (b - 2 * Qv)%N (digCycleCost a h b Qv) Qv) as Hgo.
  destruct (digStepGo rem (a + 2 * Qv)%N h (b - 2 * Qv)%N (digCycleCost a h b Qv) Qv) as [[[[af hf] bf] cf] kf].
  replace (N.to_nat (a + 2 * Qv)%N) with (N.to_nat a + 2 * N.to_nat Qv) in Hgo by lia.
  replace (N.to_nat (b - 2 * Qv)%N) with (N.to_nat b - 2 * N.to_nat Qv) in Hgo by lia.
  rewrite digCycleCost_to_nat in Hgo.
  destruct (digStepN_nat rem (N.to_nat a + 2 * N.to_nat Qv) h (N.to_nat b - 2 * N.to_nat Qv)) as [[[[a2 h2] b2] c2] k2].
  rewrite Hgo, Hadd. reflexivity.
Qed.

(* ========================================================================= *)
(* Section 10.3a: PipeL1, P1Entry, HubP2B, HubP1, PureP2, OneBlock           *)
(* ========================================================================= *)

Definition PipeL1 (e : nat) (R_out : list Sym) (Lt : Stream Sym) : Prop :=
  PipeL e R_out Lt /\
    (e = 0 -> exists R_pre L_pre, R_out = R_pre ++ T4 /\ Lt = T5 *> L_pre /\ PipeL 0 R_pre L_pre).

Lemma pipeL1_eqR {e : nat} {R1 R2 : list Sym} {Lt : Stream Sym}
    (heq : R1 = R2) (h : PipeL1 e R1 Lt) : PipeL1 e R2 Lt.
Proof. subst R2. exact h. Qed.

Lemma pipeL1_t5_succ {e : nat} {R_out : list Sym} {Lt : Stream Sym}
    (k : nat) (hp : PipeL e R_out Lt) :
    PipeL1 e (R_out ++ (T4 ^^ (k + 1))) ((T5 ^^ (k + 1)) *> Lt).
Proof.
  split; [exact (pipeL_t5 (k + 1) hp) | intros he0; subst e].
  exists (R_out ++ (T4 ^^ k)), ((T5 ^^ k) *> Lt).
  split; [rewrite list_pow_succ_right, append_assoc; reflexivity |].
  split; [replace (k + 1) with (S k) by lia; rewrite zPsr; reflexivity | exact (pipeL_t5 k hp)].
Qed.

Lemma pipeL_eat_t4_pipeL1 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (n : nat) (hle : n + 1 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL1 (En - (n + 1)) (R_out ++ (T4 ^^ (n + 1))) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T4 ^^ (n + 1)) *> r)) -[ tm ]->* (([S1; S1] *> Lt') {{F}}> r).
Proof.
  destruct (pipeL_eat_t4 (En := ltac:(match type of hp with PipeL ?x _ _ => exact x end)) n ltac:(lia) hp (T4 *> r)) as [Lt1 [hp1 hs1]].
  assert (HE1 : En - n = (En - (n + 1)) + 1) by lia.
  pose proof (pipeL_eqE HE1 hp1) as hp1'.
  destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
  pose proof (pull1_t4 hpull r) as hs2.
  exists (T5 *> Lt2). split.
  - pose proof (pipeL1_t5_succ 0 hp2) as h1.
    rewrite zP1, list_pow_one in h1.
    eapply pipeL1_eqR; [| exact h1].
    rewrite list_pow_succ_right, append_assoc. reflexivity.
  - rewrite list_pow_succ_right, Str_app_assoc. exact (stepStar_trans hs1 hs2).
Qed.

Lemma pipeL_absorb_2seg_exact {E_rem : nat} {R_out : list Sym} {Lt : Stream Sym}
    (s1 : nat) (hle : s1 <= E_rem) (hp : PipeL E_rem R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL1 (E_rem - s1) (R_out ++ (T4 ^^ (s1 + 1))) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> (T3 *> (T4 ^^ s1) *> r)) -[ tm ]->* (([S1; S1] *> Lt') {{F}}> r).
Proof.
  destruct s1 as [|s1'].
  - rewrite zPz, zLan. replace (E_rem - 0) with E_rem by lia.
    pose proof (pipeL1_t5_succ 0 hp) as hp1. rewrite zP1 in hp1.
    exists (T5 *> Lt). split; [exact hp1 | exact (step_punch_t3 Lt r)].
  - destruct (PipeL_head0 hp) as [l0 h0].
    assert (h1 : (([S1] *> T2 *> Lt) {{A}}> (T3 *> (T4 ^^ S s1') *> r)) -[ tm ]->*
                 (([S1; S1] *> Lt) {{F}}> ([S0; S1] *> (T4 ^^ 1) *> T3 *> (T4 ^^ s1') *> r))).
    { rewrite h0, zPsr, zP1.
      pose proof (q0_t2_rt5 0 (rt5_wall1 ((T4 ^^ s1') *> r)) l0) as hq.
      rewrite zPz, zLan, ?Str_app_assoc in hq. exact hq. }
    destruct (pipeL_shift_t3_loop (En := ltac:(match type of hp with PipeL ?x _ _ => exact x end)) 1 s1' s1' ltac:(lia) (Nat.le_refl _) hp r) as [Lt1 [hp1 h2]].
    replace (s1' - s1') with 0 in h2 by lia. rewrite zPz, zLan in h2.
    replace (1 + s1') with (s1' + 1) in h2 by lia.
    assert (HE1 : E_rem - s1' = (E_rem - S s1') + 1) by lia.
    pose proof (pipeL_eqE HE1 hp1) as hp1'.
    destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
    assert (h3 : (([S1; S1] *> Lt1) {{F}}> ([S0; S1] *> (T4 ^^ (s1' + 1)) *> T3 *> r)) -[ tm ]->*
                 (([S1] *> T2 *> Lt2) {{A}}> ((T4 ^^ (s1' + 1)) *> T3 *> r))).
    { change ([S0; S1] *> (T4 ^^ (s1' + 1)) *> T3 *> r) with (T0 *> [S1] *> (T4 ^^ (s1' + 1)) *> T3 *> r).
      eapply evstep_trans; [apply hpull | apply post_pull_q0]. }
    assert (h4 : (([S1] *> T2 *> Lt2) {{A}}> ((T4 ^^ (s1' + 1)) *> T3 *> r)) -[ tm ]->*
                 (([S1; S1] *> (T5 ^^ (S s1' + 1)) *> Lt2) {{F}}> r)).
    { eapply evstep_trans; [apply rule_q0_t4_next |].
      eapply evstep_trans; [apply step_punch_t3 |].
      replace (S s1' + 1) with (S (s1' + 1)) by lia. rewrite zPsr. apply evstep_refl. }
    exists ((T5 ^^ (S s1' + 1)) *> Lt2). split.
    + exact (pipeL1_t5_succ (S s1') hp2).
    + exact (stepStar_trans h1 (stepStar_trans h2 (stepStar_trans h3 h4))).
Qed.

Definition P1Entry (e : nat) (R_out : list Sym) (W : list Sym) (r : Stream Sym) (cfg : Q * tape) : Prop :=
  (exists Lt, PipeL1 e R_out Lt /\ cfg = (([S1; S1] *> Lt) {{F}}> (W *> r))) \/
  (exists Lt W', 1 <= e /\ W = T2 ++ W' /\ PipeL (e - 1) R_out Lt /\
     cfg = (([S1; S1] *> T2 *> Lt) {{F}}> (W' *> r))).

Lemma p1Entry_eat_t2_even {e : nat} {R_out rest : list Sym} {r : Stream Sym} {cfg : Q * tape}
    (m : nat) (hm : 1 <= m) (hle : m <= e)
    (h : P1Entry e R_out ((T2 ^^ (2 * m)) ++ rest) r cfg) :
    exists Lt', PipeL (e - m) R_out Lt' /\
      cfg -[ tm ]->* (([S1; S1] *> (T3 ^^ (2 * m)) *> Lt') {{F}}> (rest *> r)).
Proof.
  destruct h as [[Lt [[hp _] Hcfg]] | [Lt [W' [_ [hW [hp Hcfg]]]]]]; subst cfg.
  - rewrite Str_app_assoc.
    destruct (pipeL_eat_t2_even m 0 hle hp (rest *> r)) as [Lt' [hp' hs]].
    rewrite zPz, zLan in hs. simpl Nat.add in hs.
    exists Lt'. split; [exact hp' | exact hs].
  - assert (h2m : (T2 ^^ (2 * m)) ++ rest = T2 ++ (T2 ++ ((T2 ^^ (2 * (m - 1))) ++ rest))).
    { replace (2 * m) with (2 + 2 * (m - 1)) by lia.
      rewrite list_pow_add, ?append_assoc. reflexivity. }
    rewrite h2m in hW. symmetry in hW. apply app_cancel_left in hW; subst W'.
    rewrite ?Str_app_assoc.
    pose proof (step_t2L_eat_t2 Lt ((T2 ^^ (2 * (m - 1))) *> rest *> r)) as h1.
    destruct (pipeL_eat_t2_even (En := ltac:(match type of hp with PipeL ?x _ _ => exact x end)) (m - 1) 2 ltac:(lia) hp (rest *> r)) as [Lt' [hp' h2]].
    replace (e - 1 - (m - 1)) with (e - m) in hp' by lia.
    replace (2 + 2 * (m - 1)) with (2 * m) in h2 by lia.
    exists Lt'. split; [exact hp' | exact (stepStar_trans h1 h2)].
Qed.

Lemma p1Entry_asplit_create {e : nat} {R_out rest : list Sym} {r : Stream Sym} {cfg : Q * tape}
    (a : nat) (hE : 1 <= e) (ha : 2 * e + 1 <= a)
    (h : P1Entry e R_out ((T2 ^^ a) ++ rest) r cfg) :
    cfg -[ tm ]->*
      (b0 {{E}}> (T2 *> T0 *> T1 *>
        ((((R_out ++ (T2 ^^ (2 * e - 1))) ++ T0) ++ (T2 ^^ (a - 2 * e))) ++ rest) *> r)).
Proof.
  assert (hsplit : (T2 ^^ a) ++ rest = (T2 ^^ (2 * e)) ++ ((T2 ^^ (a - 2 * e)) ++ rest)).
  { replace a with (2 * e + (a - 2 * e)) at 1 by lia. rewrite list_pow_add, append_assoc. reflexivity. }
  rewrite hsplit in h.
  destruct (p1Entry_eat_t2_even e hE (Nat.le_refl _) h) as [Lt1 [hp1 h1]].
  replace (e - e) with 0 in hp1 by lia.
  destruct (PipeL_head0 hp1) as [l1 hl1].
  eapply evstep_trans; [exact h1 |].
  assert (htail : ((T2 ^^ (a - 2 * e)) ++ rest) *> r = T2 *> (T2 ^^ (a - 2 * e - 1)) *> rest *> r).
  { rewrite Str_app_assoc. replace (a - 2 * e) with (S (a - 2 * e - 1)) at 1 by lia.
    rewrite zPsr. reflexivity. }
  rewrite htail.
  assert (h2 : (([S1; S1] *> (T3 ^^ (2 * e)) *> Lt1) {{F}}> (T2 *> (T2 ^^ (a - 2 * e - 1)) *> rest *> r))
                 -[ tm ]->* (((T3 ^^ (2 * e)) *> Lt1) {{E}}> (T0 *> T0 *> T2 *> (T2 ^^ (a - 2 * e - 1)) *> rest *> r))).
  { assert (HT3 : (T3 ^^ (2 * e)) *> Lt1 = T3 *> (T3 ^^ (2 * e - 1)) *> Lt1)
      by (replace (2 * e) with (S (2 * e - 1)) at 1 by lia; apply zPsr).
    rewrite HT3.
    exact (step_8A_head ([S1; S1] *> (T3 ^^ (2 * e - 1)) *> Lt1) ([S0; S1] *> (T2 ^^ (a - 2 * e - 1)) *> rest *> r)). }
  assert (h3 : (((T3 ^^ (2 * e)) *> Lt1) {{E}}> (T0 *> T0 *> T2 *> (T2 ^^ (a - 2 * e - 1)) *> rest *> r))
                 -[ tm ]->* (([S1; S1] *> Lt1) {{F}}> ([S0; S1] *> (T2 ^^ (2 * e - 1)) *> T0 *> T2 *> (T2 ^^ (a - 2 * e - 1)) *> rest *> r))).
  { rewrite hl1. replace (2 * e) with ((2 * e - 1) + 1) at 1 by lia.
    exact (rule_E_t3_to_Q5 (2 * e - 1) l1 (T0 *> T2 *> (T2 ^^ (a - 2 * e - 1)) *> rest *> r)). }
  eapply evstep_trans; [exact h2 |].
  eapply evstep_trans; [exact h3 |].
  eapply evstep_trans; [apply (PipeL_unwind hp1) |].
  rewrite ?Str_app_assoc, <- zPsr.
  replace (S (a - 2 * e - 1)) with (a - 2 * e) by lia.
  apply evstep_refl.
Qed.

Lemma p1Entry_eat_t2_odd_t4 {e : nat} {R_out rest : list Sym} {r : Stream Sym} {cfg : Q * tape}
    (m b : nat) (hle : m + 1 <= e)
    (h : P1Entry e R_out (((T2 ^^ (2 * m + 1)) ++ (T4 ^^ (b + 1))) ++ rest) r cfg) :
    exists Lt', PipeL (e - m - 1) ((R_out ++ (T2 ^^ (2 * m + 1))) ++ T5) Lt' /\
      cfg -[ tm ]->* (([S1; S1] *> Lt') {{F}}> ((T4 ^^ b) *> rest *> r)).
Proof.
  destruct m as [|m'].
  - simpl Nat.mul in h |- *; simpl Nat.add in h |- *. (try rewrite list_pow_one in h; try rewrite list_pow_one).
    replace (e - 0 - 1) with (e - 1) by lia.
    destruct h as [[Lt [[hp _] Hcfg]] | [Lt [W' [_ [hW [hp Hcfg]]]]]]; subst cfg.
    + assert (HE1 : e = (e - 1) + 1) by lia.
      pose proof (pipeL_eqE HE1 hp) as hp1.
      destruct (PipeL_head0 hp1) as [l0 hl0].
      destruct (PipeL_pull hp1) as [Lt1 [hpull hp']].
      pose proof (pull1_t3_t2_t4 0 hl0 hpull ((T4 ^^ b) *> rest *> r)) as h1.
      rewrite zPz, zLan in h1. simpl Nat.add in h1.
      pose proof (pipeL_noT2_blk 0 1 hp') as hblk.
      rewrite ?zPz, ?zLan, ?app_nil_r in hblk.
      exists (T4 *> (T3 ^^ 1) *> Lt1). split; [exact hblk |].
      rewrite ?Str_app_assoc. replace (b + 1) with (S b) by lia. rewrite zPsr. exact h1.
    + rewrite append_assoc in hW. symmetry in hW. apply app_cancel_left in hW; subst W'.
      rewrite ?Str_app_assoc. replace (b + 1) with (S b) by lia. rewrite zPsr.
      pose proof (pipeL_noT2_blk 0 1 hp) as hblk.
      rewrite ?zPz, ?zLan, ?app_nil_r, list_pow_one, zP1 in hblk.
      exists (T4 *> T3 *> Lt). split; [exact hblk | exact (step_t2L_eat_t4 Lt ((T4 ^^ b) *> rest *> r))].
  - assert (hsplit : ((T2 ^^ (2 * S m' + 1)) ++ (T4 ^^ (b + 1))) ++ rest =
                     (T2 ^^ (2 * S m')) ++ ((T2 ++ (T4 ^^ (b + 1))) ++ rest)).
    { rewrite list_pow_succ_right, ?append_assoc. reflexivity. }
    rewrite hsplit in h.
    destruct (p1Entry_eat_t2_even (e := ltac:(match type of h with P1Entry ?x _ _ _ _ => exact x end)) (S m') ltac:(lia) ltac:(lia) h) as [Lt1 [hp1 h1]].
    assert (HE1 : e - S m' = (e - S m' - 1) + 1) by lia.
    pose proof (pipeL_eqE HE1 hp1) as hp1'.
    destruct (PipeL_head0 hp1') as [l1 hl1].
    destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
    pose proof (pull1_t3_t2_t4 (2 * S m') hl1 hpull ((T4 ^^ b) *> rest *> r)) as h2.
    pose proof (pipeL_noT2_blk 0 (2 * S m' + 1) hp2) as hblk.
    rewrite ?zPz, ?zLan, ?app_nil_r in hblk.
    exists (T4 *> (T3 ^^ (2 * S m' + 1)) *> Lt2). split; [exact hblk |].
    eapply evstep_trans; [exact h1 |].
    rewrite ?Str_app_assoc. replace (b + 1) with (S b) by lia. rewrite zPsr. exact h2.
Qed.

Lemma p1Entry_h1_enter_odd {e : nat} {R_out rest : list Sym} {r : Stream Sym} {cfg : Q * tape}
    (m b : nat) (hle : m + 1 <= e)
    (h : P1Entry e R_out ((((T2 ^^ (2 * m + 1)) ++ T5) ++ (T4 ^^ (b + 1))) ++ rest) r cfg) :
    exists Lt', PipeL (e - m - 1) (((R_out ++ (T2 ^^ (2 * m + 2))) ++ T5) ++ (T4 ^^ b)) Lt' /\
      cfg -[ tm ]->* (([S1] *> T2 *> Lt') {{A}}> (rest *> r)).
Proof.
  destruct m as [|m'].
  - simpl Nat.mul in h |- *; simpl Nat.add in h |- *. rewrite list_pow_one in h.
    replace (e - 0 - 1) with (e - 1) by lia.
    destruct h as [[Lt [[hp _] Hcfg]] | [Lt [W' [_ [hW [hp Hcfg]]]]]]; subst cfg.
    + destruct (pipeL_h1_enter_odd 0 b hle hp (rest *> r)) as [Lt' [hp' h1]].
      simpl Nat.mul in h1, hp'; simpl Nat.add in h1, hp'.
      replace (e - 0 - 1) with (e - 1) in hp' by lia.
      rewrite zP1 in h1. rewrite ?Str_app_assoc.
      exists Lt'. split; [exact hp' | exact h1].
    + rewrite ?append_assoc in hW. symmetry in hW. apply app_cancel_left in hW; subst W'.
      rewrite ?Str_app_assoc. replace (b + 1) with (S b) by lia. rewrite zPsr.
      pose proof (step_t2L_eat_t5_t4 Lt ((T4 ^^ b) *> rest *> r)) as h1.
      pose proof (rule_q0_t4_next b (T4 *> (T3 ^^ 2) *> Lt) (rest *> r)) as h2.
      exists ((T5 ^^ b) *> T4 *> (T3 ^^ 2) *> Lt).
      split; [exact (pipeL_noT2_blk b 2 hp) | exact (stepStar_trans h1 h2)].
  - assert (hsplit : (((T2 ^^ (2 * S m' + 1)) ++ T5) ++ (T4 ^^ (b + 1))) ++ rest =
                     (T2 ^^ (2 * S m')) ++ (((T2 ++ T5) ++ (T4 ^^ (b + 1))) ++ rest)).
    { rewrite list_pow_succ_right, ?append_assoc. reflexivity. }
    rewrite hsplit in h.
    destruct (p1Entry_eat_t2_even (e := ltac:(match type of h with P1Entry ?x _ _ _ _ => exact x end)) (S m') ltac:(lia) ltac:(lia) h) as [Lt1 [hp1 h1]].
    assert (HE1 : e - S m' = (e - S m' - 1) + 1) by lia.
    pose proof (pipeL_eqE HE1 hp1) as hp1'.
    destruct (PipeL_head0 hp1') as [l1 hl1].
    destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
    pose proof (pull1_t3_t2_t5 (2 * S m') hl1 hpull ((T4 ^^ (b + 1)) *> rest *> r)) as h2.
    assert (h3 : (([S1] *> (T3 ^^ (2 * S m' + 3)) *> Lt2) {{A}}> ((T4 ^^ (b + 1)) *> rest *> r)) -[ tm ]->*
                 (([S1] *> T2 *> (T5 ^^ b) *> T4 *> (T3 ^^ (2 * S m' + 2)) *> Lt2) {{A}}> (rest *> r))).
    { replace (2 * S m' + 3) with (S (2 * S m' + 2)) by lia.
      replace (b + 1) with (S b) by lia. rewrite !zPsr.
      eapply evstep_trans; [apply step_q0_t4_first | apply rule_q0_t4_next]. }
    exists ((T5 ^^ b) *> T4 *> (T3 ^^ (2 * S m' + 2)) *> Lt2). split.
    + exact (pipeL_noT2_blk b (2 * S m' + 2) hp2).
    + eapply evstep_trans; [exact h1 |].
      rewrite ?Str_app_assoc. exact (stepStar_trans h2 h3).
Qed.

Lemma p1Entry_h1_enter_even {e : nat} {R_out rest : list Sym} {r : Stream Sym} {cfg : Q * tape}
    (m b : nat) (hm : 1 <= m) (hle : m + 1 <= e)
    (h : P1Entry e R_out ((((T2 ^^ (2 * m)) ++ T5) ++ (T4 ^^ (b + 1))) ++ rest) r cfg) :
    exists Lt', PipeL (e - m - 1) ((R_out ++ (T2 ^^ (2 * m + 1))) ++ (T4 ^^ (b + 1))) Lt' /\
      cfg -[ tm ]->* (([S1] *> T2 *> Lt') {{A}}> (rest *> r)).
Proof.
  rewrite ?append_assoc in h.
  destruct (p1Entry_eat_t2_even (e := ltac:(match type of h with P1Entry ?x _ _ _ _ => exact x end)) m hm ltac:(lia) h) as [Lt1 [hp1 h1]].
  assert (HE1 : e - m = (e - m - 1) + 1) by lia.
  pose proof (pipeL_eqE HE1 hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
  pose proof (pull1_t3_t5 (2 * m) hl1 hpull ((T4 ^^ (b + 1)) *> rest *> r)) as h2.
  assert (h3 : (([S1] *> (T3 ^^ (2 * m + 1)) *> T2 *> Lt2) {{A}}> ((T4 ^^ (b + 1)) *> rest *> r)) -[ tm ]->*
               (([S1] *> T2 *> (T5 ^^ b) *> T4 *> (T3 ^^ (2 * m)) *> T2 *> Lt2) {{A}}> (rest *> r))).
  { replace (2 * m + 1) with (S (2 * m)) by lia.
    replace (b + 1) with (S b) by lia. rewrite !zPsr.
    eapply evstep_trans; [apply step_q0_t4_first | apply rule_q0_t4_next]. }
  exists ((T5 ^^ b) *> T4 *> (T3 ^^ (2 * m)) *> T2 *> Lt2). split.
  - exact (pipeL_T2_blk b (2 * m) hp2).
  - eapply evstep_trans; [exact h1 |].
    rewrite ?Str_app_assoc. exact (stepStar_trans h2 h3).
Qed.

Lemma p1Entry_s1_exact {R_out rest : list Sym} {r : Stream Sym} {cfg : Q * tape}
    (m b : nat) (hm : 1 <= m)
    (h : P1Entry m R_out ((((T2 ^^ (2 * m)) ++ T5) ++ (T4 ^^ b)) ++ rest) r cfg) :
    cfg -[ tm ]->*
      (b0 {{E}}> (T2 *> T0 *> T1 *> (((R_out ++ (T2 ^^ (2 * m + 1))) ++ (T4 ^^ b)) ++ rest) *> r)).
Proof.
  rewrite ?append_assoc in h.
  destruct (p1Entry_eat_t2_even m hm (Nat.le_refl _) h) as [Lt1 [hp1 h1]].
  replace (m - m) with 0 in hp1 by lia.
  destruct (PipeL_head0 hp1) as [l1 hl1].
  eapply evstep_trans; [exact h1 |].
  rewrite ?Str_app_assoc.
  change (T5 *> (T4 ^^ b) *> rest *> r) with (T0 *> [S1; S0; S0; S1] *> (T4 ^^ b) *> rest *> r).
  assert (h2 : (([S1; S1] *> (T3 ^^ (2 * m)) *> Lt1) {{F}}> (T0 *> [S1; S0; S0; S1] *> (T4 ^^ b) *> rest *> r))
                 -[ tm ]->* (((T3 ^^ (2 * m)) *> Lt1) {{E}}> (T0 *> T2 *> T2 *> (T4 ^^ b) *> rest *> r))).
  { replace (2 * m) with (S (2 * m - 1)) by lia. rewrite !zPsr.
    exact (step_8A_head ([S1; S1] *> (T3 ^^ (2 * m - 1)) *> Lt1) ([S1; S0; S0; S1] *> (T4 ^^ b) *> rest *> r)). }
  assert (h3 : (((T3 ^^ (2 * m)) *> Lt1) {{E}}> (T0 *> T2 *> T2 *> (T4 ^^ b) *> rest *> r))
                 -[ tm ]->* (([S1; S1] *> Lt1) {{F}}> ([S0; S1] *> (T2 ^^ (2 * m + 1)) *> (T4 ^^ b) *> rest *> r))).
  { rewrite hl1. replace (2 * m) with ((2 * m - 1) + 1) at 1 by lia.
    eapply evstep_trans; [apply rule_E_t3_to_Q5 |].
    rewrite !zPal. replace (S (S (2 * m - 1))) with (2 * m + 1) by lia. apply evstep_refl. }
  eapply evstep_trans; [exact h2 |].
  eapply evstep_trans; [exact h3 |].
  eapply evstep_trans; [apply (PipeL_unwind hp1) |].
  rewrite ?Str_app_assoc. apply evstep_refl.
Qed.

Lemma p1Entry_transp_exact_m {R_out rest : list Sym} {r : Stream Sym} {cfg : Q * tape}
    (m b : nat) (hm : 1 <= m)
    (h : P1Entry m R_out (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 1))) ++ rest) r cfg) :
    cfg -[ tm ]->*
      (b0 {{E}}> (T2 *> T0 *> T1 *> ((((R_out ++ (T2 ^^ (2 * m))) ++ T3) ++ (T4 ^^ b)) ++ rest) *> r)).
Proof.
  rewrite ?append_assoc in h.
  destruct (p1Entry_eat_t2_even m hm (Nat.le_refl _) h) as [Lt1 [hp1 h1]].
  replace (m - m) with 0 in hp1 by lia.
  destruct (PipeL_head0 hp1) as [l1 hl1].
  eapply evstep_trans; [exact h1 |].
  rewrite ?Str_app_assoc. replace (b + 1) with (S b) by lia. rewrite zPsr.
  change (T4 *> (T4 ^^ b) *> rest *> r) with (T0 *> [S1; S0; S1; S1] *> (T4 ^^ b) *> rest *> r).
  assert (h2 : (([S1; S1] *> (T3 ^^ (2 * m)) *> Lt1) {{F}}> (T0 *> [S1; S0; S1; S1] *> (T4 ^^ b) *> rest *> r))
                 -[ tm ]->* (((T3 ^^ (2 * m)) *> Lt1) {{E}}> (T0 *> T2 *> T3 *> (T4 ^^ b) *> rest *> r))).
  { replace (2 * m) with (S (2 * m - 1)) by lia. rewrite !zPsr.
    exact (step_8A_head ([S1; S1] *> (T3 ^^ (2 * m - 1)) *> Lt1) ([S1; S0; S1; S1] *> (T4 ^^ b) *> rest *> r)). }
  assert (h3 : (((T3 ^^ (2 * m)) *> Lt1) {{E}}> (T0 *> T2 *> T3 *> (T4 ^^ b) *> rest *> r))
                 -[ tm ]->* (([S1; S1] *> Lt1) {{F}}> ([S0; S1] *> (T2 ^^ (2 * m)) *> T3 *> (T4 ^^ b) *> rest *> r))).
  { rewrite hl1. replace (2 * m) with ((2 * m - 1) + 1) at 1 by lia.
    eapply evstep_trans; [apply rule_E_t3_to_Q5 |].
    rewrite zPal. replace (S (2 * m - 1)) with (2 * m) by lia. apply evstep_refl. }
  eapply evstep_trans; [exact h2 |].
  eapply evstep_trans; [exact h3 |].
  eapply evstep_trans; [apply (PipeL_unwind hp1) |].
  rewrite ?Str_app_assoc. apply evstep_refl.
Qed.

(* --- ScratchS3A.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

Lemma p1Entry_transp_pass {e : nat} {R_out rest : list Sym} {r : Stream Sym} {cfg : Q * tape}
    (m b : nat) (hm : 1 <= m) (hle : m + b + 2 <= e)
    (h : P1Entry e R_out (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ++ rest) r cfg) :
    exists Lt', PipeL1 (e - (m + b + 2)) ((R_out ++ (T2 ^^ (2 * m))) ++ (T4 ^^ (b + 2))) Lt' /\
      cfg -[ tm ]->* (([S1; S1] *> Lt') {{F}}> (rest *> r)).
Proof.
  rewrite ?append_assoc in h.
  destruct (p1Entry_eat_t2_even (e := ltac:(match type of h with P1Entry ?x _ _ _ _ => exact x end)) m hm ltac:(lia) h) as [Lt1 [hp1 h1]].
  assert (HE1 : e - m = (e - m - 1) + 1) by lia.
  pose proof (pipeL_eqE HE1 hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
  assert (h2 : (([S1; S1] *> (T3 ^^ (2 * m)) *> Lt1) {{F}}> (((T4 ^^ (b + 2)) ++ rest) *> r))
                 -[ tm ]->* (([S1; S1] *> T4 *> (T3 ^^ (2 * m - 1)) *> T2 *> Lt2) {{F}}> ((T4 ^^ (b + 1)) *> rest *> r))).
  { rewrite Str_app_assoc. replace (2 * m) with ((2 * m - 1) + 1) at 1 by lia.
    replace (b + 2) with (S (b + 1)) by lia. rewrite (zPsr T4).
    exact (pull1_t3_t4 (2 * m - 1) hl1 hpull ((T4 ^^ (b + 1)) *> rest *> r)). }
  pose proof (pipeL_T2_blk 0 (2 * m - 1) hp2) as hp2blk.
  rewrite zPz, zLan in hp2blk.
  destruct (pipeL_eat_t4_pipeL1 (En := ltac:(match type of hp2blk with PipeL ?x _ _ => exact x end)) b ltac:(lia) hp2blk (rest *> r)) as [Lt3 [hp3 h3]].
  replace (e - m - 1 - (b + 1)) with (e - (m + b + 2)) in hp3 by lia.
  exists Lt3. split.
  - eapply pipeL1_eqR; [| exact hp3].
    replace (2 * m - 1 + 1) with (2 * m) by lia.
    rewrite append_assoc, ?list_pow_add_r, <- ?list_pow_add.
    replace (0 + 1 + (b + 1)) with (b + 2) by lia. reflexivity.
  - exact (stepStar_trans h1 (stepStar_trans h2 h3)).
Qed.

Lemma p1Entry_transp_split {e : nat} {R_out rest : list Sym} {r : Stream Sym} {cfg : Q * tape}
    (m b : nat) (hm : 1 <= m) (hge : m + 1 <= e) (hlt : e + 1 <= m + b + 2)
    (h : P1Entry e R_out (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ++ rest) r cfg) :
    cfg -[ tm ]->*
      (b0 {{E}}> (T2 *> T0 *> T1 *>
        (((((R_out ++ (T2 ^^ (2 * m))) ++ (T4 ^^ (e - m))) ++ T3) ++ (T4 ^^ (m + b + 1 - e))) ++ rest) *> r)).
Proof.
  rewrite ?append_assoc in h.
  destruct (p1Entry_eat_t2_even (e := ltac:(match type of h with P1Entry ?x _ _ _ _ => exact x end)) m hm ltac:(lia) h) as [Lt1 [hp1 h1]].
  assert (HE1 : e - m = (e - m - 1) + 1) by lia.
  pose proof (pipeL_eqE HE1 hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
  assert (h2 : (([S1; S1] *> (T3 ^^ (2 * m)) *> Lt1) {{F}}> (((T4 ^^ (b + 2)) ++ rest) *> r))
                 -[ tm ]->* (([S1; S1] *> T4 *> (T3 ^^ (2 * m - 1)) *> T2 *> Lt2) {{F}}> ((T4 ^^ (b + 1)) *> rest *> r))).
  { rewrite Str_app_assoc. replace (2 * m) with ((2 * m - 1) + 1) at 1 by lia.
    replace (b + 2) with (S (b + 1)) by lia. rewrite (zPsr T4).
    exact (pull1_t3_t4 (2 * m - 1) hl1 hpull ((T4 ^^ (b + 1)) *> rest *> r)). }
  pose proof (pipeL_T2_blk 0 (2 * m - 1) hp2) as hp2blk.
  rewrite zPz, zLan in hp2blk.
  set (E1 := e - m - 1).
  assert (hR : (T4 ^^ (b + 1)) *> rest *> r = (T4 ^^ E1) *> T4 *> (T4 ^^ (m + b + 1 - e)) *> rest *> r).
  { replace (b + 1) with (E1 + (1 + (m + b + 1 - e))) at 1 by (unfold E1; lia).
    rewrite !pow_add_blank, zP1. reflexivity. }
  destruct (pipeL_eat_t4 E1 (Nat.le_refl _) hp2blk (T4 *> (T4 ^^ (m + b + 1 - e)) *> rest *> r)) as [Lt3 [hp3 h3]].
  replace (E1 - E1) with 0 in hp3 by lia.
  eapply evstep_trans; [exact h1 |].
  eapply evstep_trans; [exact h2 |].
  rewrite hR.
  eapply evstep_trans; [exact h3 |].
  change (T4 *> (T4 ^^ (m + b + 1 - e)) *> rest *> r) with ([S0; S1] *> T3 *> (T4 ^^ (m + b + 1 - e)) *> rest *> r).
  eapply evstep_trans; [apply (PipeL_unwind hp3) |].
  rewrite ?Str_app_assoc, <- pow_add_blank.
  replace (2 * m - 1 + 1) with (2 * m) by lia.
  replace (0 + 1 + E1) with (e - m) by (unfold E1; lia).
  apply evstep_refl.
Qed.


(* ========================================================================= *)
(* HubP2B, HubP1, PureP2, OneBlock & Cell/Block Lifters                      *)
(* ========================================================================= *)

Definition HubP2B (e : nat) (W W1 : list Sym) : Prop :=
  1 <= e /\
  (forall r : Stream Sym, exists Lt, PipeL (e - 1) W1 Lt /\
    (b0 {{E}}> (T2 *> T0 *> T1 *> W *> r)) -[ tm ]->* (([S1] *> T2 *> Lt) {{A}}> r)) /\
  (forall Wp : list Sym, W = Wp ++ T4 ->
    exists W1p, W1 = W1p ++ T4 /\
      forall r : Stream Sym, exists Lt, PipeL (e - 1) W1p Lt /\
        (b0 {{E}}> (T2 *> T0 *> T1 *> Wp *> r)) -[ tm ]->* (([S1] *> T2 *> Lt) {{A}}> r)).

Definition HubP1 (e : nat) (W W1 : list Sym) : Prop :=
  forall (W_next : list Sym) (r : Stream Sym),
    exists cfg, P1Entry e W1 W_next r cfg /\
      (b0 {{E}}> (T2 *> T0 *> T1 *> (W ++ W_next) *> r)) -[ tm ]->* cfg.

Inductive PureP2 : list Sym -> list Sym -> list nat -> Prop :=
  | PureP2_nil (W : list Sym) : PureP2 W W []
  | PureP2_cons {W W1 W' : list Sym} {e : nat} {es : list nat}
      (h1 : HubP2B e W W1) (hrest : PureP2 W1 W' es) : PureP2 W W' (e :: es).

Definition OneBlock (W W' : list Sym) (e0 : nat) (es : list nat) : Prop :=
  exists W1, HubP1 e0 W W1 /\ PureP2 W1 W' es.

Lemma PureP2_append {W1 W2 W3 : list Sym} {es1 es2 : list nat}
    (h1 : PureP2 W1 W2 es1) (h2 : PureP2 W2 W3 es2) : PureP2 W1 W3 (es1 ++ es2).
Proof.
  induction h1 as [W | Wa Wb Wc e es h1 hrest IH].
  - exact h2.
  - exact (PureP2_cons h1 (IH h2)).
Qed.

Lemma PureP2_uncons {W W' : list Sym} {es : list nat}
    (hp : PureP2 W W' es) (hpos : 1 <= sumList es) :
    exists W1 e es', es = e :: es' /\ HubP2B e W W1 /\ PureP2 W1 W' es'.
Proof.
  destruct hp as [W | Wa Wb Wc e es' h1 hrest].
  - cbn [sumList] in hpos; lia.
  - exists Wb, e, es'. split; [reflexivity | split; [exact h1 | exact hrest]].
Qed.

Lemma OneBlock_appendP2 {W1 W2 W3 : list Sym} {e0 : nat} {es1 es2 : list nat}
    (hb : OneBlock W1 W2 e0 es1) (hp : PureP2 W2 W3 es2) :
    OneBlock W1 W3 e0 (es1 ++ es2).
Proof.
  destruct hb as [Wm [h1 h2]].
  exists Wm. split; [exact h1 | exact (PureP2_append h2 hp)].
Qed.

Lemma PureP2_dump {W W' S S' : list Sym} {es : list nat} {tail : Stream Sym}
    (hp : PureP2 W W' es) :
    forall (hd : CanDumpTail S (sumList es) S' tail),
    (b0 {{E}}> (T2 *> T0 *> T1 *> (W ++ S) *> tail)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *> (W' ++ S') *> tail)).
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 hrest IH] in S |- *; intros hd.
  - destruct hd as [f [hf0 [hfE _]]].
    cbn [sumList] in hfE.
    assert (hEq : S = S') by congruence. rewrite <- hEq. apply evstep_refl.
  - cbn [sumList] in hd.
    destruct (CanDumpTail_oneHub hd (proj1 h1) ltac:(lia)) as [S1 [hsink hd1]].
    destruct (proj1 (proj2 h1) (S *> tail)) as [Lt [hpL hs1]].
    rewrite Str_app_assoc.
    eapply evstep_trans; [exact hs1 |].
    eapply evstep_trans; [exact (hsink Wb Lt hpL) |].
    replace (e + sumList es' - e) with (sumList es') in hd1 by lia.
    exact (IH S1 hd1).
Qed.

Lemma HubP2B_liftT4 {e : nat} {W W1 : list Sym} (k : nat) (h : HubP2B e W W1) :
    HubP2B e (W ++ (T4 ^^ (k + 1))) (W1 ++ (T4 ^^ (k + 1))).
Proof.
  destruct h as [he [hfull hstrip]].
  split; [exact he | split].
  - intros r. destruct (hfull ((T4 ^^ (k + 1)) *> r)) as [Lt [hp hs]].
    rewrite Str_app_assoc.
    exists ((T5 ^^ (k + 1)) *> Lt).
    split; [exact (pipeL_t5 (k + 1) hp) | exact (stepStar_trans hs (rule_q0_t4_next (k + 1) Lt r))].
  - intros Wp hWp.
    assert (hW : W ++ (T4 ^^ (k + 1)) = (W ++ (T4 ^^ k)) ++ T4).
    { rewrite (list_pow_succ_right T4), append_assoc. reflexivity. }
    assert (hWpEq : Wp = W ++ (T4 ^^ k)).
    { apply (@app_cancel_right _ _ _ T4). congruence. }
    subst Wp.
    exists (W1 ++ (T4 ^^ k)). split.
    + rewrite (list_pow_succ_right T4), append_assoc. reflexivity.
    + intros r. destruct (hfull ((T4 ^^ k) *> r)) as [Lt [hp hs]].
      rewrite Str_app_assoc.
      exists ((T5 ^^ k) *> Lt).
      split; [exact (pipeL_t5 k hp) | exact (stepStar_trans hs (rule_q0_t4_next k Lt r))].
Qed.

Lemma PureP2_liftT4 {W W' : list Sym} {es : list nat} (k : nat) (hp : PureP2 W W' es) :
    PureP2 (W ++ (T4 ^^ (k + 1))) (W' ++ (T4 ^^ (k + 1))) es.
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 hrest IH].
  - exact (PureP2_nil _).
  - exact (PureP2_cons (HubP2B_liftT4 k h1) IH).
Qed.

Lemma HubP2B_liftCell {e : nat} {W W1 : list Sym} (a : nat) (hc : bool) (b : nat)
    (hok : hc = true \/ (1 <= a /\ 2 <= b)) (hb : 1 <= b) (h : HubP2B e W W1) :
    HubP2B e (W ++ encS a hc b [] None) (W1 ++ encS a hc b [] None).
Proof.
  assert (hok_full : hc = true \/ (1 <= a /\ 1 <= b)).
  { destruct hok as [H | [Ha Hb2]]; [left; exact H | right; lia]. }
  assert (hok_pre : hc = true \/ (1 <= a /\ 1 <= b - 1)).
  { destruct hok as [H | [Ha Hb2]]; [left; exact H | right; lia]. }
  assert (hsplit : encS a hc b [] None = encS a hc (b - 1) [] None ++ T4).
  { replace b with ((b - 1) + 1) at 1 by lia.
    unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity. }
  destruct h as [he [hfull hstrip]].
  split; [exact he | split].
  - intros r.
    destruct (hfull (encS a hc b [] None *> r)) as [Lt [hp hs]].
    destruct (pipeL_mid_cell a hc b hok_full hp r) as [Lt' [hp' hs']].
    exists Lt'. split.
    + eapply pipeL_eqR; [| exact hp'].
      unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
    + rewrite Str_app_assoc. eapply evstep_trans; [exact hs |].
      unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. rewrite ?append_assoc in hs'. exact hs'.
  - intros Wp hWp.
    assert (hWpEq : Wp = W ++ encS a hc (b - 1) [] None).
    { apply (@app_cancel_right _ _ _ T4). rewrite <- hWp, hsplit, append_assoc. reflexivity. }
    subst Wp.
    exists (W1 ++ encS a hc (b - 1) [] None). split.
    + rewrite hsplit, append_assoc. reflexivity.
    + intros r.
      destruct (hfull (encS a hc (b - 1) [] None *> r)) as [Lt [hp hs]].
      destruct (pipeL_mid_cell a hc (b - 1) hok_pre hp r) as [Lt' [hp' hs']].
      exists Lt'. split.
      * eapply pipeL_eqR; [| exact hp'].
        unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
      * rewrite Str_app_assoc. eapply evstep_trans; [exact hs |].
        unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. rewrite ?append_assoc in hs'. exact hs'.
Qed.

Lemma PureP2_liftCell {W W' : list Sym} {es : list nat} (a : nat) (hc : bool) (b : nat)
    (hok : hc = true \/ (1 <= a /\ 2 <= b)) (hb : 1 <= b) (hp : PureP2 W W' es) :
    PureP2 (W ++ encS a hc b [] None) (W' ++ encS a hc b [] None) es.
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 hrest IH].
  - exact (PureP2_nil _).
  - exact (PureP2_cons (HubP2B_liftCell a hc b hok hb h1) IH).
Qed.

Lemma hubP1_zero_merge {W W1 W2 C_rest : list Sym} {e1 : nat}
    (h0 : HubP1 0 W W1) (h1 : HubP2B e1 W1 W2) (r : Stream Sym) :
    exists cfg, P1Entry e1 W2 (T2 ++ C_rest) r cfg /\
      (b0 {{E}}> (T2 *> T0 *> T1 *> (W ++ (T2 ++ C_rest)) *> r)) -[ tm ]->* cfg.
Proof.
  destruct (h0 (T2 ++ C_rest) r) as [cfg0 [hp0 hs0]].
  destruct hp0 as [[L0 [[_ hzero] Hcfg]] | [_ [_ [hge _]]]]; [subst cfg0 | lia].
  destruct (hzero eq_refl) as [W1p [L0p [hW1p [hL0 hpp]]]]; subst L0.
  destruct (PipeL_head0 hpp) as [l0p hl0p].
  assert (hpark : (([S1; S1] *> T5 *> L0p) {{F}}> ((T2 ++ C_rest) *> r)) -[ tm ]->*
                  (([S1; S1] *> L0p) {{F}}> ([S0; S1] *> B0 *> C_rest *> r))).
  { rewrite hl0p, Str_app_assoc.
    change (T2 *> C_rest *> r) with (T0 *> [S0; S1] *> C_rest *> r).
    eapply evstep_trans; [exact (step_left_t5_one l0p ([S0; S1] *> C_rest *> r)) |].
    unfold B0. rewrite ?Str_app_assoc. apply evstep_refl. }
  pose proof (PipeL_unwind hpp (B0 *> C_rest *> r)) as hunw.
  destruct (proj2 (proj2 h1) W1p hW1p) as [W2p [hW2p hstep1]].
  destruct (hstep1 (B0 *> C_rest *> r)) as [L1 [hpL1 hs1]].
  assert (hheal : (([S1] *> T2 *> L1) {{A}}> (B0 *> C_rest *> r)) -[ tm ]->*
                  (([S1; S1] *> T2 *> T5 *> L1) {{F}}> (C_rest *> r))).
  { change ([S1] *> T2 *> L1) with ([S1; S0] *> [S0; S1] *> L1).
    change ([S1; S1] *> T2 *> T5 *> L1) with ([S1; S1] *> T2 *> [S0; S1; S0] *> [S0; S1] *> L1).
    exact (step_heal_bdry0 ([S0; S1] *> L1) (C_rest *> r)). }
  assert (hpL1' : PipeL (e1 - 1) W2 (T5 *> L1)).
  { rewrite hW2p. pose proof (pipeL_t5 1 hpL1) as ht. rewrite list_pow_one, zP1 in ht. exact ht. }
  exists (([S1; S1] *> T2 *> T5 *> L1) {{F}}> (C_rest *> r)). split.
  - right. exists (T5 *> L1), C_rest.
    split; [exact (proj1 h1) | split; [reflexivity | split; [exact hpL1' | reflexivity]]].
  - exact (stepStar_trans hs0 (stepStar_trans hpark (stepStar_trans hunw (stepStar_trans hs1 hheal)))).
Qed.

Lemma PureP2_lift2Seg_dump {W W' : list Sym} {es : list nat}
    (p s1 : nat) (hp : PureP2 W W' es) :
    forall (hle : sumList es <= s1) (r : Stream Sym),
    (b0 {{E}}> (T2 *> T0 *> T1 *> (((W ++ (T4 ^^ p)) ++ T3) ++ (T4 ^^ s1)) *> r)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *> (((W' ++ (T4 ^^ (p + sumList es))) ++ T3) ++ (T4 ^^ (s1 - sumList es))) *> r)).
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 hrest IH] in p, s1 |- *; intros hle r.
  - cbn [sumList]. replace (p + 0) with p by lia. replace (s1 - 0) with s1 by lia. apply evstep_refl.
  - cbn [sumList] in hle |- *.
    pose proof (proj1 h1) as he1.
    set (e' := e - 1). assert (he_eq : e = e' + 1) by lia.
    destruct (proj1 (proj2 h1) ((T4 ^^ p) *> T3 *> (T4 ^^ s1) *> r)) as [Lt [hpL hs1]].
    replace (e - 1) with e' in hpL by lia.
    pose proof (rule_q0_t4_next p Lt (T3 *> (T4 ^^ s1) *> r)) as hs_t4.
    pose proof (pipeL_t5 p hpL) as hpL'.
    pose proof (pipeL_dump_wall1 (E_rem := ltac:(match type of hpL' with PipeL ?x _ _ => exact x end)) s1 ltac:(lia) hpL' r) as hd.
    rewrite ?Str_app_assoc.
    eapply evstep_trans; [exact hs1 |].
    eapply evstep_trans; [exact hs_t4 |].
    eapply evstep_trans; [exact hd |].
    pose proof (IH (p + (e' + 1)) (s1 - (e' + 1)) ltac:(lia) r) as hrec.
    (rewrite ?Str_app_assoc in hrec; rewrite ?Str_app_assoc).
    rewrite <- pow_add_blank.
    replace (p + (e' + 1) + sumList es') with (p + (e + sumList es')) in hrec by lia.
    replace (s1 - (e' + 1) - sumList es') with (s1 - (e + sumList es')) in hrec by lia.
    exact hrec.
Qed.

Lemma PureP2_lift2Seg_heal {W W' : list Sym} {es : list nat}
    (p s1 : nat) (hp : PureP2 W W' es) :
    forall (hge : s1 + 1 <= sumList es),
    exists e0' es', OneBlock (((W ++ (T4 ^^ p)) ++ T3) ++ (T4 ^^ s1)) (W' ++ (T4 ^^ (p + s1 + 1))) e0' es' /\
      e0' + sumList es' = sumList es - (s1 + 1).
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 hrest IH] in p, s1 |- *; intros hge.
  - cbn [sumList] in hge; lia.
  - cbn [sumList] in hge |- *.
    pose proof (proj1 h1) as he1.
    destruct (Compare_dec.le_dec e s1) as [hlt | hgt].
    + destruct (IH (p + e) (s1 - e) ltac:(lia)) as [e0' [es_out [[Wm [hp1 hpp]] hsum]]].
      replace (p + e + (s1 - e) + 1) with (p + s1 + 1) in hpp by lia.
      exists e0', es_out. split; [| lia].
      exists Wm. split; [| exact hpp].
      intros W_next r.
      pose proof (PureP2_lift2Seg_dump p s1 (PureP2_cons h1 (PureP2_nil Wb)) ltac:(cbn [sumList]; lia) (W_next *> r)) as hd.
      cbn [sumList] in hd. replace (e + 0) with e in hd by lia.
      destruct (hp1 W_next r) as [cfg [hpe hst]].
      exists cfg. split; [exact hpe |].
      (rewrite ?Str_app_assoc in hd; rewrite ?Str_app_assoc in hst; rewrite ?Str_app_assoc).
      exact (stepStar_trans hd hst).
    + set (e' := e - 1).
      assert (hle : s1 <= e') by lia.
      exists (e' - s1), es'. split; [| lia].
      exists (Wb ++ (T4 ^^ (p + s1 + 1))). split.
      * intros W_next r.
        destruct (proj1 (proj2 h1) ((T4 ^^ p) *> T3 *> (T4 ^^ s1) *> W_next *> r)) as [Lt [hpL hs1]].
        replace (e - 1) with e' in hpL by lia.
        pose proof (rule_q0_t4_next p Lt (T3 *> (T4 ^^ s1) *> W_next *> r)) as hs_t4.
        pose proof (pipeL_t5 p hpL) as hpL'.
        destruct (pipeL_absorb_2seg_exact s1 hle hpL' (W_next *> r)) as [Lt' [hp1' hs2]].
        assert (hp1'' : PipeL1 (e' - s1) (Wb ++ (T4 ^^ (p + s1 + 1))) Lt').
        { eapply pipeL1_eqR; [| exact hp1'].
          rewrite append_assoc, ?list_pow_add_r, <- ?list_pow_add.
          replace (p + (s1 + 1)) with (p + s1 + 1) by lia. reflexivity. }
        exists (([S1; S1] *> Lt') {{F}}> (W_next *> r)). split.
        -- left. exists Lt'. split; [exact hp1'' | reflexivity].
        -- rewrite ?Str_app_assoc. exact (stepStar_trans hs1 (stepStar_trans hs_t4 hs2)).
      * replace (p + s1 + 1) with ((p + s1) + 1) by lia.
        exact (PureP2_liftT4 (p + s1) hrest).
Qed.

Lemma PureP2_liftASplitH1Odd {W W' : list Sym} {es : list nat}
    (aL q b : nat) (hb : 1 <= b) (hp : PureP2 W W' es) :
    forall (hge : q + 1 <= sumList es),
    exists es', PureP2 (W ++ encS aL true (b + 1) [] (Some (2 * q + 1)))
        (W' ++ encS (aL + 2 * q + 3) true b [] None) es' /\
      sumList es' = sumList es - q.
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 hrest IH] in aL, q |- *; intros hge.
  - cbn [sumList] in hge; lia.
  - cbn [sumList] in hge |- *.
    pose proof (proj1 h1) as he1.
    set (e' := e - 1). assert (he_eq : e = e' + 1) by lia.
    destruct (Compare_dec.le_dec e q) as [hlt | hgt].
    + destruct (IH (aL + 2 * e) (q - e) ltac:(lia)) as [es_out [hpp hsum]].
      replace (aL + 2 * e + 2 * (q - e) + 3) with (aL + 2 * q + 3) in hpp by lia.
      assert (hdump : forall bb r,
        (b0 {{E}}> (T2 *> T0 *> T1 *> (Wa ++ encS aL true bb [] (Some (2 * q + 1))) *> r)) -[ tm ]->*
        (b0 {{E}}> (T2 *> T0 *> T1 *> (Wb ++ encS (aL + 2 * e) true bb [] (Some (2 * (q - e) + 1))) *> r))).
      { intros bb r.
        destruct (proj1 (proj2 h1) (encS aL true bb [] (Some (2 * q + 1)) *> r)) as [Lt [hpL hs1]].
        replace (e - 1) with e' in hpL by lia.
        rewrite Str_app_assoc. eapply evstep_trans; [exact hs1 |].
        assert (hT5 : encS aL true bb [] (Some (2 * q + 1)) *> r =
                      (T2 ^^ aL) *> T0 *> (T2 ^^ (2 * q + 1)) *> T0 *> [S1; S0; S0; S1] *> (T4 ^^ bb) *> r).
        { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc. reflexivity. }
        rewrite hT5.
        eapply evstep_trans; [exact (pipeL_dump_wall3 (E_rem := ltac:(match type of hpL with PipeL ?x _ _ => exact x end)) aL (2 * q + 1) ltac:(lia) hpL ([S1; S0; S0; S1] *> (T4 ^^ bb) *> r)) |].
        unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
        replace (aL + 2 * (e' + 1)) with (aL + 2 * e) by lia.
        replace (2 * q + 1 - 2 * (e' + 1)) with (2 * (q - e) + 1) by lia.
        apply evstep_refl. }
      destruct (PureP2_uncons hpp ltac:(lia)) as [Wmid [e_f [es_f [hEqf [hfirst htail]]]]].
      subst es_out. cbn [sumList] in hsum.
      assert (hfirst' : HubP2B e_f (Wa ++ encS aL true (b + 1) [] (Some (2 * q + 1))) Wmid).
      { split; [exact (proj1 hfirst) | split].
        - intros r. destruct (proj1 (proj2 hfirst) r) as [Lt [hpL hs]].
          exists Lt. split; [exact hpL | exact (stepStar_trans (hdump (b + 1) r) hs)].
        - intros Wp hWp.
          assert (hsplit : Wa ++ encS aL true (b + 1) [] (Some (2 * q + 1)) =
                           (Wa ++ encS aL true b [] (Some (2 * q + 1))) ++ T4).
          { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity. }
          assert (hWpEq : Wp = Wa ++ encS aL true b [] (Some (2 * q + 1))).
          { apply (@app_cancel_right _ _ _ T4). congruence. }
          subst Wp.
          assert (hsplitB : Wb ++ encS (aL + 2 * e) true (b + 1) [] (Some (2 * (q - e) + 1)) =
                            (Wb ++ encS (aL + 2 * e) true b [] (Some (2 * (q - e) + 1))) ++ T4).
          { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity. }
          destruct (proj2 (proj2 hfirst) _ hsplitB) as [Wmp [hWmp hf2]].
          exists Wmp. split; [exact hWmp |].
          intros r. destruct (hf2 r) as [Lf [hpLf hsf]].
          exists Lf. split; [exact hpLf | exact (stepStar_trans (hdump b r) hsf)]. }
      exists (e_f :: es_f). split; [exact (PureP2_cons hfirst' htail) | cbn [sumList]; lia].
    + assert (hle : q <= e') by lia.
      assert (hheal1 : HubP2B (e - q) (Wa ++ encS aL true (b + 1) [] (Some (2 * q + 1)))
                        (Wb ++ encS (aL + 2 * q + 3) true b [] None)).
      { split; [lia | split].
        - intros r.
          destruct (proj1 (proj2 h1) (encS aL true (b + 1) [] (Some (2 * q + 1)) *> r)) as [Lt [hpL hs1]].
          replace (e - 1) with e' in hpL by lia.
          destruct (pipeL_asplit_heal_h1_odd aL q b hle hpL r) as [Lt' [hpL' hs2]].
          replace (e - q - 1) with (e' - q) by lia.
          exists Lt'. split.
          + eapply pipeL_eqR; [| exact hpL'].
            unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
          + rewrite Str_app_assoc. eapply evstep_trans; [exact hs1 |].
            unfold encS; cbn [encSegTail]. (rewrite ?app_nil_r in hs2; rewrite ?Str_app_assoc in hs2; rewrite ?app_nil_r; rewrite ?Str_app_assoc). exact hs2.
        - intros Wp hWp.
          assert (hsplit : Wa ++ encS aL true (b + 1) [] (Some (2 * q + 1)) =
                           (Wa ++ encS aL true b [] (Some (2 * q + 1))) ++ T4).
          { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity. }
          assert (hWpEq : Wp = Wa ++ encS aL true b [] (Some (2 * q + 1))).
          { apply (@app_cancel_right _ _ _ T4). congruence. }
          subst Wp.
          set (b' := b - 1).
          exists (Wb ++ encS (aL + 2 * q + 3) true b' [] None). split.
          + replace b with (b' + 1) at 1 by lia.
            unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity.
          + intros r.
            replace b with (b' + 1) by lia.
            destruct (proj1 (proj2 h1) (encS aL true (b' + 1) [] (Some (2 * q + 1)) *> r)) as [Lt [hpL hs1]].
            replace (e - 1) with e' in hpL by lia.
            destruct (pipeL_asplit_heal_h1_odd aL q b' hle hpL r) as [Lt' [hpL' hs2]].
            replace (e - q - 1) with (e' - q) by lia.
            exists Lt'. split.
            * eapply pipeL_eqR; [| exact hpL'].
              unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
            * rewrite Str_app_assoc. eapply evstep_trans; [exact hs1 |].
              unfold encS; cbn [encSegTail]. (rewrite ?app_nil_r in hs2; rewrite ?Str_app_assoc in hs2; rewrite ?app_nil_r; rewrite ?Str_app_assoc). exact hs2. }
      exists ((e - q) :: es'). split.
      * exact (PureP2_cons hheal1 (PureP2_liftCell (aL + 2 * q + 3) true b (or_introl eq_refl) hb hrest)).
      * cbn [sumList]; lia.
Qed.

Lemma PureP2_liftASplitH1Even {W W' : list Sym} {es : list nat}
    (aL q b : nat) (hb : 1 <= b) (hp : PureP2 W W' es) :
    forall (hge : q + 1 <= sumList es),
    exists es', PureP2 (W ++ encS aL true (b + 1) [] (Some (2 * q)))
        (W' ++ encS (aL + 2 * q + 2) false (b + 1) [] None) es' /\
      sumList es' = sumList es - q.
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 hrest IH] in aL, q |- *; intros hge.
  - cbn [sumList] in hge; lia.
  - cbn [sumList] in hge |- *.
    pose proof (proj1 h1) as he1.
    set (e' := e - 1). assert (he_eq : e = e' + 1) by lia.
    destruct (Compare_dec.le_dec e q) as [hlt | hgt].
    + destruct (IH (aL + 2 * e) (q - e) ltac:(lia)) as [es_out [hpp hsum]].
      replace (aL + 2 * e + 2 * (q - e) + 2) with (aL + 2 * q + 2) in hpp by lia.
      assert (hdump : forall bb r,
        (b0 {{E}}> (T2 *> T0 *> T1 *> (Wa ++ encS aL true bb [] (Some (2 * q))) *> r)) -[ tm ]->*
        (b0 {{E}}> (T2 *> T0 *> T1 *> (Wb ++ encS (aL + 2 * e) true bb [] (Some (2 * (q - e)))) *> r))).
      { intros bb r.
        destruct (proj1 (proj2 h1) (encS aL true bb [] (Some (2 * q)) *> r)) as [Lt [hpL hs1]].
        replace (e - 1) with e' in hpL by lia.
        rewrite Str_app_assoc. eapply evstep_trans; [exact hs1 |].
        assert (hT5 : encS aL true bb [] (Some (2 * q)) *> r =
                      (T2 ^^ aL) *> T0 *> (T2 ^^ (2 * q)) *> T0 *> [S1; S0; S0; S1] *> (T4 ^^ bb) *> r).
        { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc. reflexivity. }
        rewrite hT5.
        eapply evstep_trans; [exact (pipeL_dump_wall3 (E_rem := ltac:(match type of hpL with PipeL ?x _ _ => exact x end)) aL (2 * q) ltac:(lia) hpL ([S1; S0; S0; S1] *> (T4 ^^ bb) *> r)) |].
        unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
        replace (aL + 2 * (e' + 1)) with (aL + 2 * e) by lia.
        replace (2 * q - 2 * (e' + 1)) with (2 * (q - e)) by lia.
        apply evstep_refl. }
      destruct (PureP2_uncons hpp ltac:(lia)) as [Wmid [e_f [es_f [hEqf [hfirst htail]]]]].
      subst es_out. cbn [sumList] in hsum.
      assert (hfirst' : HubP2B e_f (Wa ++ encS aL true (b + 1) [] (Some (2 * q))) Wmid).
      { split; [exact (proj1 hfirst) | split].
        - intros r. destruct (proj1 (proj2 hfirst) r) as [Lt [hpL hs]].
          exists Lt. split; [exact hpL | exact (stepStar_trans (hdump (b + 1) r) hs)].
        - intros Wp hWp.
          assert (hsplit : Wa ++ encS aL true (b + 1) [] (Some (2 * q)) =
                           (Wa ++ encS aL true b [] (Some (2 * q))) ++ T4).
          { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity. }
          assert (hWpEq : Wp = Wa ++ encS aL true b [] (Some (2 * q))).
          { apply (@app_cancel_right _ _ _ T4). congruence. }
          subst Wp.
          assert (hsplitB : Wb ++ encS (aL + 2 * e) true (b + 1) [] (Some (2 * (q - e))) =
                            (Wb ++ encS (aL + 2 * e) true b [] (Some (2 * (q - e)))) ++ T4).
          { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity. }
          destruct (proj2 (proj2 hfirst) _ hsplitB) as [Wmp [hWmp hf2]].
          exists Wmp. split; [exact hWmp |].
          intros r. destruct (hf2 r) as [Lf [hpLf hsf]].
          exists Lf. split; [exact hpLf | exact (stepStar_trans (hdump b r) hsf)]. }
      exists (e_f :: es_f). split; [exact (PureP2_cons hfirst' htail) | cbn [sumList]; lia].
    + assert (hle : q <= e') by lia.
      assert (hheal1 : HubP2B (e - q) (Wa ++ encS aL true (b + 1) [] (Some (2 * q)))
                        (Wb ++ encS (aL + 2 * q + 2) false (b + 1) [] None)).
      { split; [lia | split].
        - intros r.
          destruct (proj1 (proj2 h1) (encS aL true (b + 1) [] (Some (2 * q)) *> r)) as [Lt [hpL hs1]].
          replace (e - 1) with e' in hpL by lia.
          destruct (pipeL_asplit_heal_h1_even aL q b hle hpL r) as [Lt' [hpL' hs2]].
          replace (e - q - 1) with (e' - q) by lia.
          exists Lt'. split.
          + eapply pipeL_eqR; [| exact hpL'].
            unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
          + rewrite Str_app_assoc. eapply evstep_trans; [exact hs1 |].
            unfold encS; cbn [encSegTail]. (rewrite ?app_nil_r in hs2; rewrite ?Str_app_assoc in hs2; rewrite ?app_nil_r; rewrite ?Str_app_assoc). exact hs2.
        - intros Wp hWp.
          assert (hsplit : Wa ++ encS aL true (b + 1) [] (Some (2 * q)) =
                           (Wa ++ encS aL true b [] (Some (2 * q))) ++ T4).
          { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity. }
          assert (hWpEq : Wp = Wa ++ encS aL true b [] (Some (2 * q))).
          { apply (@app_cancel_right _ _ _ T4). congruence. }
          subst Wp.
          set (b' := b - 1).
          exists (Wb ++ encS (aL + 2 * q + 2) false (b' + 1) [] None). split.
          + replace b with (b' + 1) at 1 by lia.
            unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity.
          + intros r.
            replace b with (b' + 1) by lia.
            destruct (proj1 (proj2 h1) (encS aL true (b' + 1) [] (Some (2 * q)) *> r)) as [Lt [hpL hs1]].
            replace (e - 1) with e' in hpL by lia.
            destruct (pipeL_asplit_heal_h1_even aL q b' hle hpL r) as [Lt' [hpL' hs2]].
            replace (e - q - 1) with (e' - q) by lia.
            exists Lt'. split.
            * eapply pipeL_eqR; [| exact hpL'].
              unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
            * rewrite Str_app_assoc. eapply evstep_trans; [exact hs1 |].
              unfold encS; cbn [encSegTail]. (rewrite ?app_nil_r in hs2; rewrite ?Str_app_assoc in hs2; rewrite ?app_nil_r; rewrite ?Str_app_assoc). exact hs2. }
      exists ((e - q) :: es'). split.
      * exact (PureP2_cons hheal1 (PureP2_liftCell (aL + 2 * q + 2) false (b + 1) ltac:(right; split; lia) ltac:(lia) hrest)).
      * cbn [sumList]; lia.
Qed.

Lemma PureP2_lift2SegCell_dump {W W' : list Sym} {es : list nat}
    (a : nat) (hc : bool) (s0 s1 : nat) (hp : PureP2 W W' es) :
    forall (hok : hc = true \/ (1 <= a /\ 1 <= s0)) (hle : sumList es <= s1) (r : Stream Sym),
    (b0 {{E}}> (T2 *> T0 *> T1 *> (W ++ encS a hc s0 (sp1 s1) None) *> r)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *> (W' ++ encS a hc (s0 + sumList es) (sp1 (s1 - sumList es)) None) *> r)).
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 hrest IH] in s0, s1 |- *; intros hok hle r.
  - cbn [sumList]. replace (s0 + 0) with s0 by lia. replace (s1 - 0) with s1 by lia. apply evstep_refl.
  - cbn [sumList] in hle |- *.
    pose proof (proj1 h1) as he1.
    set (e' := e - 1). assert (he_eq : e = e' + 1) by lia.
    destruct (proj1 (proj2 h1) (encS a hc s0 (sp1 s1) None *> r)) as [Lt [hpL hs1]].
    replace (e - 1) with e' in hpL by lia.
    destruct (pipeL_mid_cell a hc s0 hok hpL (T3 *> (T4 ^^ s1) *> r)) as [Lt1 [hpL1 hs2]].
    pose proof (pipeL_dump_wall1 (E_rem := ltac:(match type of hpL1 with PipeL ?x _ _ => exact x end)) s1 ltac:(lia) hpL1 r) as hd.
    rewrite Str_app_assoc. eapply evstep_trans; [exact hs1 |].
    assert (hstart2 : encS a hc s0 (sp1 s1) None *> r =
                      (((T2 ^^ a) ++ (if hc then T5 else [])) ++ (T4 ^^ s0)) *> T3 *> (T4 ^^ s1) *> r).
    { unfold encS; rewrite encSegTail_sp1, ?app_nil_r, ?Str_app_assoc. reflexivity. }
    rewrite hstart2.
    eapply evstep_trans; [exact hs2 |].
    eapply evstep_trans; [exact hd |].
    assert (hok' : hc = true \/ (1 <= a /\ 1 <= s0 + e)).
    { destruct hok as [H | [Ha Hs]]; [left; exact H | right; lia]. }
    pose proof (IH (s0 + e) (s1 - e) hok' ltac:(lia) r) as hrec.
    assert (hmid : ((((Wb ++ (((T2 ^^ a) ++ (if hc then T5 else [])) ++ (T4 ^^ s0))) ++ (T4 ^^ (e' + 1))) ++ T3) ++ (T4 ^^ (s1 - (e' + 1)))) *> r =
                   (Wb ++ encS a hc (s0 + e) (sp1 (s1 - e)) None) *> r).
    { unfold encS; rewrite encSegTail_sp1, ?app_nil_r, ?append_assoc, ?list_pow_add_r, <- ?list_pow_add, ?append_assoc.
      replace (e' + 1) with e by lia. reflexivity. }
    rewrite hmid.
    replace (s0 + e + sumList es') with (s0 + (e + sumList es')) in hrec by lia.
    replace (s1 - e - sumList es') with (s1 - (e + sumList es')) in hrec by lia.
    exact hrec.
Qed.

Lemma PureP2_lift2SegCell {W W' : list Sym} {es : list nat}
    (a : nat) (hc : bool) (s0 s1 : nat) (hp : PureP2 W W' es) :
    forall (hok : hc = true \/ (1 <= a /\ 1 <= s0)) (hge : s1 + 1 <= sumList es),
    exists e0' es', OneBlock (W ++ encS a hc s0 (sp1 s1) None)
        (W' ++ encS a hc (s0 + s1 + 1) [] None) e0' es' /\
      e0' + sumList es' = sumList es - (s1 + 1).
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 hrest IH] in s0, s1 |- *; intros hok hge.
  - cbn [sumList] in hge; lia.
  - cbn [sumList] in hge |- *.
    pose proof (proj1 h1) as he1.
    set (e' := e - 1).
    destruct (Compare_dec.le_dec e s1) as [hlt | hgt].
    + assert (hok' : hc = true \/ (1 <= a /\ 1 <= s0 + e)).
      { destruct hok as [H | [Ha Hs]]; [left; exact H | right; lia]. }
      destruct (IH (s0 + e) (s1 - e) hok' ltac:(lia)) as [e0' [es_out [[Wm [hp1 hpp]] hsum]]].
      replace (s0 + e + (s1 - e) + 1) with (s0 + s1 + 1) in hpp by lia.
      exists e0', es_out. split; [| lia].
      exists Wm. split; [| exact hpp].
      intros W_next r.
      pose proof (PureP2_lift2SegCell_dump a hc s0 s1 (PureP2_cons h1 (PureP2_nil Wb)) hok ltac:(cbn [sumList]; lia) (W_next *> r)) as hd.
      cbn [sumList] in hd. replace (e + 0) with e in hd by lia.
      destruct (hp1 W_next r) as [cfg [hpe hst]].
      exists cfg. split; [exact hpe |].
      (rewrite ?Str_app_assoc in hd; rewrite ?Str_app_assoc in hst; rewrite ?Str_app_assoc).
      exact (stepStar_trans hd hst).
    + assert (hle : s1 <= e') by lia.
      assert (hok_after : hc = true \/ (1 <= a /\ 2 <= s0 + s1 + 1)).
      { destruct hok as [H | [Ha Hs]]; [left; exact H | right; lia]. }
      exists (e' - s1), es'. split; [| lia].
      exists (Wb ++ encS a hc (s0 + s1 + 1) [] None). split.
      * intros W_next r.
        destruct (proj1 (proj2 h1) (encS a hc s0 (sp1 s1) None *> W_next *> r)) as [Lt [hpL hs1]].
        replace (e - 1) with e' in hpL by lia.
        destruct (pipeL_mid_cell a hc s0 hok hpL (T3 *> (T4 ^^ s1) *> W_next *> r)) as [Lt1 [hpL1 hs2]].
        destruct (pipeL_absorb_2seg_exact s1 hle hpL1 (W_next *> r)) as [Lt2 [hpL2 hs3]].
        assert (hpL2' : PipeL1 (e' - s1) (Wb ++ encS a hc (s0 + s1 + 1) [] None) Lt2).
        { eapply pipeL1_eqR; [| exact hpL2].
          unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc, ?list_pow_add_r, <- ?list_pow_add.
          replace (s0 + (s1 + 1)) with (s0 + s1 + 1) by lia. reflexivity. }
        exists (([S1; S1] *> Lt2) {{F}}> (W_next *> r)). split.
        -- left. exists Lt2. split; [exact hpL2' | reflexivity].
        -- rewrite ?Str_app_assoc. eapply evstep_trans; [exact hs1 |].
           assert (hstart2 : encS a hc s0 (sp1 s1) None *> W_next *> r =
                             (((T2 ^^ a) ++ (if hc then T5 else [])) ++ (T4 ^^ s0)) *> T3 *> (T4 ^^ s1) *> W_next *> r).
           { unfold encS; rewrite encSegTail_sp1, ?app_nil_r, ?Str_app_assoc. reflexivity. }
           rewrite hstart2. exact (stepStar_trans hs2 hs3).
      * exact (PureP2_liftCell a hc (s0 + s1 + 1) hok_after ltac:(lia) hrest).
Qed.

Lemma PureP2_liftASplitH0Even {W W' : list Sym} {es : list nat}
    (aL q b : nat) (hp : PureP2 W W' es) :
    forall (hge : q + b + 2 <= sumList es),
    exists e0' es', OneBlock (W ++ encS aL false (b + 2) [] (Some (2 * q)))
        (W' ++ encS (aL + 2 * q + 1) false (b + 2) [] None) e0' es' /\
      e0' + sumList es' = sumList es - (q + b + 2).
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 hrest IH] in aL, q |- *; intros hge.
  - cbn [sumList] in hge; lia.
  - cbn [sumList] in hge |- *.
    pose proof (proj1 h1) as he1.
    set (e' := e - 1). assert (he_eq : e = e' + 1) by lia.
    destruct (Compare_dec.le_dec e q) as [hlt | hgt].
    + destruct (IH (aL + 2 * e) (q - e) ltac:(lia)) as [e0' [es_out [[Wm [hp1 hpp]] hsum]]].
      replace (aL + 2 * e + 2 * (q - e) + 1) with (aL + 2 * q + 1) in hpp by lia.
      exists e0', es_out. split; [| lia].
      exists Wm. split; [| exact hpp].
      intros W_next r.
      destruct (proj1 (proj2 h1) (encS aL false (b + 2) [] (Some (2 * q)) *> W_next *> r)) as [Lt [hpL hs1]].
      replace (e - 1) with e' in hpL by lia.
      destruct (hp1 W_next r) as [cfg [hpe hst]].
      exists cfg. split; [exact hpe |].
      rewrite ?Str_app_assoc. eapply evstep_trans; [exact hs1 |].
      assert (hT4 : encS aL false (b + 2) [] (Some (2 * q)) *> W_next *> r =
                    (T2 ^^ aL) *> T0 *> (T2 ^^ (2 * q)) *> T0 *> [S1; S0; S1; S1] *> (T4 ^^ (b + 1)) *> W_next *> r).
      { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
        replace (b + 2) with (S (b + 1)) by lia. rewrite zPsr. reflexivity. }
      rewrite hT4.
      eapply evstep_trans; [exact (pipeL_dump_wall3 (E_rem := ltac:(match type of hpL with PipeL ?x _ _ => exact x end)) aL (2 * q) ltac:(lia) hpL ([S1; S0; S1; S1] *> (T4 ^^ (b + 1)) *> W_next *> r)) |].
      assert (hR : (((Wb ++ (T2 ^^ (aL + 2 * (e' + 1)))) ++ T0) ++ (T2 ^^ (2 * q - 2 * (e' + 1)))) *> T0 *> [S1; S0; S1; S1] *> (T4 ^^ (b + 1)) *> W_next *> r =
                   ((Wb ++ encS (aL + 2 * e) false (b + 2) [] (Some (2 * (q - e)))) ++ W_next) *> r).
      { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
        replace (aL + 2 * (e' + 1)) with (aL + 2 * e) by lia.
        replace (2 * q - 2 * (e' + 1)) with (2 * (q - e)) by lia.
        replace (b + 2) with (S (b + 1)) by lia. rewrite zPsr. reflexivity. }
      rewrite hR. exact hst.
    + assert (hle : q <= e') by lia.
      destruct (Compare_dec.le_dec (b + 1) (e' - q)) as [hfull | hpart].
      * exists (e' - q - (b + 1)), es'. split; [| lia].
        exists (Wb ++ encS (aL + 2 * q + 1) false (b + 2) [] None). split.
        -- intros W_next r.
           destruct (proj1 (proj2 h1) (encS aL false (b + 2) [] (Some (2 * q)) *> W_next *> r)) as [Lt [hpL hs1]].
           replace (e - 1) with e' in hpL by lia.
           destruct (pipeL_asplit_heal_h0_even aL q (b + 1) hle hpL (W_next *> r)) as [Lt1 [hpL1 hs2]].
           destruct (pipeL_eat_t4_pipeL1 b hfull hpL1 (W_next *> r)) as [Lt2 [hpL2 hs3]].
           assert (hpL2' : PipeL1 (e' - q - (b + 1)) (Wb ++ encS (aL + 2 * q + 1) false (b + 2) [] None) Lt2).
           { eapply pipeL1_eqR; [| exact hpL2].
             unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc, ?list_pow_add_r, <- ?list_pow_add.
             replace (1 + (b + 1)) with (b + 2) by lia. reflexivity. }
           exists (([S1; S1] *> Lt2) {{F}}> (W_next *> r)). split.
           ++ left. exists Lt2. split; [exact hpL2' | reflexivity].
           ++ rewrite ?Str_app_assoc. eapply evstep_trans; [exact hs1 |].
              assert (hs2' : (([S1] *> T2 *> Lt) {{A}}> (encS aL false (b + 2) [] (Some (2 * q)) *> W_next *> r))
                               -[ tm ]->* (([S1; S1] *> Lt1) {{F}}> ((T4 ^^ (b + 1)) *> W_next *> r))).
              { unfold encS; cbn [encSegTail]. replace (b + 2) with ((b + 1) + 1) by lia. (rewrite ?app_nil_r in hs2; rewrite ?Str_app_assoc in hs2; rewrite ?app_nil_r; rewrite ?Str_app_assoc). exact hs2. }
              exact (stepStar_trans hs2' hs3).
        -- exact (PureP2_liftCell (aL + 2 * q + 1) false (b + 2) ltac:(right; split; lia) ltac:(lia) hrest).
      * set (Er := e' - q).
        destruct (PureP2_lift2SegCell (aL + 2 * q + 1) false (Er + 1) (b - Er) hrest
          ltac:(right; split; lia) ltac:(lia)) as [e0' [es_out [[Wm [hp1 hpp]] hsum]]].
        replace (Er + 1 + (b - Er) + 1) with (b + 2) in hpp by lia.
        exists e0', es_out. split; [| lia].
        exists Wm. split; [| exact hpp].
        intros W_next r.
        destruct (proj1 (proj2 h1) (encS aL false (b + 2) [] (Some (2 * q)) *> W_next *> r)) as [Lt [hpL hs1]].
        replace (e - 1) with e' in hpL by lia.
        destruct (pipeL_asplit_heal_h0_even aL q (b + 1) hle hpL (W_next *> r)) as [Lt1 [hpL1 hs2]].
        assert (hR : (T4 ^^ (b + 1)) *> W_next *> r = (T4 ^^ Er) *> T4 *> (T4 ^^ (b - Er)) *> W_next *> r).
        { replace (b + 1) with (Er + (1 + (b - Er))) at 1 by lia. rewrite !pow_add_blank, zP1. reflexivity. }
        destruct (pipeL_eat_t4 Er (Nat.le_refl Er) hpL1 (T4 *> (T4 ^^ (b - Er)) *> W_next *> r)) as [Lt2 [hpL2 hs3]].
        replace (Er - Er) with 0 in hpL2 by lia.
        destruct (hp1 W_next r) as [cfg [hpe hst]].
        exists cfg. split; [exact hpe |].
        rewrite ?Str_app_assoc. eapply evstep_trans; [exact hs1 |].
        assert (hs2' : (([S1] *> T2 *> Lt) {{A}}> (encS aL false (b + 2) [] (Some (2 * q)) *> W_next *> r))
                         -[ tm ]->* (([S1; S1] *> Lt1) {{F}}> ((T4 ^^ (b + 1)) *> W_next *> r))).
        { unfold encS; cbn [encSegTail]. replace (b + 2) with ((b + 1) + 1) by lia. (rewrite ?app_nil_r in hs2; rewrite ?Str_app_assoc in hs2; rewrite ?app_nil_r; rewrite ?Str_app_assoc). exact hs2. }
        eapply evstep_trans; [exact hs2' |].
        rewrite hR. eapply evstep_trans; [exact hs3 |].
        change (T4 *> (T4 ^^ (b - Er)) *> W_next *> r) with ([S0; S1] *> T3 *> (T4 ^^ (b - Er)) *> W_next *> r).
        eapply evstep_trans; [exact (PipeL_unwind hpL2 (T3 *> (T4 ^^ (b - Er)) *> W_next *> r)) |].
        assert (hEq : (((Wb ++ (T2 ^^ (aL + 2 * q + 1))) ++ (T4 ^^ 1)) ++ (T4 ^^ Er)) *> T3 *> (T4 ^^ (b - Er)) *> W_next *> r =
                      ((Wb ++ encS (aL + 2 * q + 1) false (Er + 1) (sp1 (b - Er)) None) ++ W_next) *> r).
        { unfold encS; rewrite encSegTail_sp1, ?app_nil_r, ?Str_app_assoc, <- pow_add_blank.
          replace (1 + Er) with (Er + 1) by lia. reflexivity. }
        rewrite hEq. exact hst.
Qed.

Lemma PureP2_liftASplitH0Odd {W W' : list Sym} {es : list nat}
    (aL q b : nat) (hp : PureP2 W W' es) :
    forall (hge : q + b + 2 <= sumList es),
    exists e0' es', OneBlock (W ++ encS aL false (b + 2) [] (Some (2 * q + 1)))
        (W' ++ encS (aL + 2 * q + 2) true (b + 1) [] None) e0' es' /\
      e0' + sumList es' = sumList es - (q + b + 2).
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 hrest IH] in aL, q |- *; intros hge.
  - cbn [sumList] in hge; lia.
  - cbn [sumList] in hge |- *.
    pose proof (proj1 h1) as he1.
    set (e' := e - 1). assert (he_eq : e = e' + 1) by lia.
    destruct (Compare_dec.le_dec e q) as [hlt | hgt].
    + destruct (IH (aL + 2 * e) (q - e) ltac:(lia)) as [e0' [es_out [[Wm [hp1 hpp]] hsum]]].
      replace (aL + 2 * e + 2 * (q - e) + 2) with (aL + 2 * q + 2) in hpp by lia.
      exists e0', es_out. split; [| lia].
      exists Wm. split; [| exact hpp].
      intros W_next r.
      destruct (proj1 (proj2 h1) (encS aL false (b + 2) [] (Some (2 * q + 1)) *> W_next *> r)) as [Lt [hpL hs1]].
      replace (e - 1) with e' in hpL by lia.
      destruct (hp1 W_next r) as [cfg [hpe hst]].
      exists cfg. split; [exact hpe |].
      rewrite ?Str_app_assoc. eapply evstep_trans; [exact hs1 |].
      assert (hT4 : encS aL false (b + 2) [] (Some (2 * q + 1)) *> W_next *> r =
                    (T2 ^^ aL) *> T0 *> (T2 ^^ (2 * q + 1)) *> T0 *> [S1; S0; S1; S1] *> (T4 ^^ (b + 1)) *> W_next *> r).
      { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
        replace (b + 2) with (S (b + 1)) by lia. rewrite zPsr. reflexivity. }
      rewrite hT4.
      eapply evstep_trans; [exact (pipeL_dump_wall3 (E_rem := ltac:(match type of hpL with PipeL ?x _ _ => exact x end)) aL (2 * q + 1) ltac:(lia) hpL ([S1; S0; S1; S1] *> (T4 ^^ (b + 1)) *> W_next *> r)) |].
      assert (hR : (((Wb ++ (T2 ^^ (aL + 2 * (e' + 1)))) ++ T0) ++ (T2 ^^ (2 * q + 1 - 2 * (e' + 1)))) *> T0 *> [S1; S0; S1; S1] *> (T4 ^^ (b + 1)) *> W_next *> r =
                   ((Wb ++ encS (aL + 2 * e) false (b + 2) [] (Some (2 * (q - e) + 1))) ++ W_next) *> r).
      { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
        replace (aL + 2 * (e' + 1)) with (aL + 2 * e) by lia.
        replace (2 * q + 1 - 2 * (e' + 1)) with (2 * (q - e) + 1) by lia.
        replace (b + 2) with (S (b + 1)) by lia. rewrite zPsr. reflexivity. }
      rewrite hR. exact hst.
    + assert (hle : q <= e') by lia.
      destruct (Compare_dec.le_dec (b + 1) (e' - q)) as [hfull | hpart].
      * exists (e' - q - (b + 1)), es'. split; [| lia].
        exists (Wb ++ encS (aL + 2 * q + 2) true (b + 1) [] None). split.
        -- intros W_next r.
           destruct (proj1 (proj2 h1) (encS aL false (b + 2) [] (Some (2 * q + 1)) *> W_next *> r)) as [Lt [hpL hs1]].
           replace (e - 1) with e' in hpL by lia.
           destruct (pipeL_asplit_heal_h0_odd aL q (b + 1) hle hpL (W_next *> r)) as [Lt1 [hpL1 hs2]].
           destruct (pipeL_eat_t4_pipeL1 b hfull hpL1 (W_next *> r)) as [Lt2 [hpL2 hs3]].
           assert (hpL2' : PipeL1 (e' - q - (b + 1)) (Wb ++ encS (aL + 2 * q + 2) true (b + 1) [] None) Lt2).
           { eapply pipeL1_eqR; [| exact hpL2].
             unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity. }
           exists (([S1; S1] *> Lt2) {{F}}> (W_next *> r)). split.
           ++ left. exists Lt2. split; [exact hpL2' | reflexivity].
           ++ rewrite ?Str_app_assoc. eapply evstep_trans; [exact hs1 |].
              assert (hs2' : (([S1] *> T2 *> Lt) {{A}}> (encS aL false (b + 2) [] (Some (2 * q + 1)) *> W_next *> r))
                               -[ tm ]->* (([S1; S1] *> Lt1) {{F}}> ((T4 ^^ (b + 1)) *> W_next *> r))).
              { unfold encS; cbn [encSegTail]. replace (b + 2) with ((b + 1) + 1) by lia. (rewrite ?app_nil_r in hs2; rewrite ?Str_app_assoc in hs2; rewrite ?app_nil_r; rewrite ?Str_app_assoc). exact hs2. }
              exact (stepStar_trans hs2' hs3).
        -- exact (PureP2_liftCell (aL + 2 * q + 2) true (b + 1) (or_introl eq_refl) ltac:(lia) hrest).
      * set (Er := e' - q).
        destruct (PureP2_lift2SegCell (aL + 2 * q + 2) true Er (b - Er) hrest
          (or_introl eq_refl) ltac:(lia)) as [e0' [es_out [[Wm [hp1 hpp]] hsum]]].
        replace (Er + (b - Er) + 1) with (b + 1) in hpp by lia.
        exists e0', es_out. split; [| lia].
        exists Wm. split; [| exact hpp].
        intros W_next r.
        destruct (proj1 (proj2 h1) (encS aL false (b + 2) [] (Some (2 * q + 1)) *> W_next *> r)) as [Lt [hpL hs1]].
        replace (e - 1) with e' in hpL by lia.
        destruct (pipeL_asplit_heal_h0_odd aL q (b + 1) hle hpL (W_next *> r)) as [Lt1 [hpL1 hs2]].
        assert (hR : (T4 ^^ (b + 1)) *> W_next *> r = (T4 ^^ Er) *> T4 *> (T4 ^^ (b - Er)) *> W_next *> r).
        { replace (b + 1) with (Er + (1 + (b - Er))) at 1 by lia. rewrite !pow_add_blank, zP1. reflexivity. }
        destruct (pipeL_eat_t4 Er (Nat.le_refl Er) hpL1 (T4 *> (T4 ^^ (b - Er)) *> W_next *> r)) as [Lt2 [hpL2 hs3]].
        replace (Er - Er) with 0 in hpL2 by lia.
        destruct (hp1 W_next r) as [cfg [hpe hst]].
        exists cfg. split; [exact hpe |].
        rewrite ?Str_app_assoc. eapply evstep_trans; [exact hs1 |].
        assert (hs2' : (([S1] *> T2 *> Lt) {{A}}> (encS aL false (b + 2) [] (Some (2 * q + 1)) *> W_next *> r))
                         -[ tm ]->* (([S1; S1] *> Lt1) {{F}}> ((T4 ^^ (b + 1)) *> W_next *> r))).
        { unfold encS; cbn [encSegTail]. replace (b + 2) with ((b + 1) + 1) by lia. (rewrite ?app_nil_r in hs2; rewrite ?Str_app_assoc in hs2; rewrite ?app_nil_r; rewrite ?Str_app_assoc). exact hs2. }
        eapply evstep_trans; [exact hs2' |].
        rewrite hR. eapply evstep_trans; [exact hs3 |].
        change (T4 *> (T4 ^^ (b - Er)) *> W_next *> r) with ([S0; S1] *> T3 *> (T4 ^^ (b - Er)) *> W_next *> r).
        eapply evstep_trans; [exact (PipeL_unwind hpL2 (T3 *> (T4 ^^ (b - Er)) *> W_next *> r)) |].
        assert (hEq : (((Wb ++ (T2 ^^ (aL + 2 * q + 2))) ++ T5) ++ (T4 ^^ Er)) *> T3 *> (T4 ^^ (b - Er)) *> W_next *> r =
                      ((Wb ++ encS (aL + 2 * q + 2) true Er (sp1 (b - Er)) None) ++ W_next) *> r).
        { unfold encS; rewrite encSegTail_sp1, ?app_nil_r, ?Str_app_assoc. reflexivity. }
        rewrite hEq. exact hst.
Qed.

Lemma PureP2_liftASplitH0Odd_park {W W' : list Sym} {es : list nat}
    (aL q b : nat) (hp : PureP2 W W' es) :
    forall (hge : q + 1 <= sumList es) (hlt : sumList es < q + b + 2) (r : Stream Sym),
    (b0 {{E}}> (T2 *> T0 *> T1 *> (W ++ encS aL false (b + 2) [] (Some (2 * q + 1))) *> r)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *>
      (W' ++ encS (aL + 2 * q + 2) true (sumList es - (q + 1)) (sp1 (q + b + 1 - sumList es)) None) *> r)).
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 hrest IH] in aL, q |- *; intros hge hlt r.
  - cbn [sumList] in hge; lia.
  - cbn [sumList] in hge, hlt |- *.
    pose proof (proj1 h1) as he1.
    set (e' := e - 1).
    destruct (Compare_dec.le_dec e q) as [hq | hgt].
    + destruct (proj1 (proj2 h1) (encS aL false (b + 2) [] (Some (2 * q + 1)) *> r)) as [Lt [hpL hs1]].
      replace (e - 1) with e' in hpL by lia.
      rewrite Str_app_assoc. eapply evstep_trans; [exact hs1 |].
      assert (hT4 : encS aL false (b + 2) [] (Some (2 * q + 1)) *> r =
                    (T2 ^^ aL) *> T0 *> (T2 ^^ (2 * q + 1)) *> T0 *> [S1; S0; S1; S1] *> (T4 ^^ (b + 1)) *> r).
      { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
        replace (b + 2) with (S (b + 1)) by lia. rewrite zPsr. reflexivity. }
      rewrite hT4.
      eapply evstep_trans; [exact (pipeL_dump_wall3 (E_rem := ltac:(match type of hpL with PipeL ?x _ _ => exact x end)) aL (2 * q + 1) ltac:(lia) hpL ([S1; S0; S1; S1] *> (T4 ^^ (b + 1)) *> r)) |].
      assert (hR : (((Wb ++ (T2 ^^ (aL + 2 * (e' + 1)))) ++ T0) ++ (T2 ^^ (2 * q + 1 - 2 * (e' + 1)))) *> T0 *> [S1; S0; S1; S1] *> (T4 ^^ (b + 1)) *> r =
                   (Wb ++ encS (aL + 2 * e) false (b + 2) [] (Some (2 * (q - e) + 1))) *> r).
      { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
        replace (aL + 2 * (e' + 1)) with (aL + 2 * e) by lia.
        replace (2 * q + 1 - 2 * (e' + 1)) with (2 * (q - e) + 1) by lia.
        replace (b + 2) with (S (b + 1)) by lia. rewrite zPsr. reflexivity. }
      rewrite hR.
      pose proof (IH (aL + 2 * e) (q - e) ltac:(lia) ltac:(lia) r) as hrec.
      replace (aL + 2 * e + 2 * (q - e) + 2) with (aL + 2 * q + 2) in hrec by lia.
      replace (sumList es' - (q - e + 1)) with (e + sumList es' - (q + 1)) in hrec by lia.
      replace (q - e + b + 1 - sumList es') with (q + b + 1 - (e + sumList es')) in hrec by lia.
      exact hrec.
    + assert (hle : q <= e') by lia.
      set (Er := e' - q).
      destruct (proj1 (proj2 h1) (encS aL false (b + 2) [] (Some (2 * q + 1)) *> r)) as [Lt [hpL hs1]].
      replace (e - 1) with e' in hpL by lia.
      destruct (pipeL_asplit_heal_h0_odd aL q (b + 1) hle hpL r) as [Lt1 [hpL1 hs2]].
      assert (hR : (T4 ^^ (b + 1)) *> r = (T4 ^^ Er) *> T4 *> (T4 ^^ (b - Er)) *> r).
      { replace (b + 1) with (Er + (1 + (b - Er))) at 1 by lia. rewrite !pow_add_blank, zP1. reflexivity. }
      destruct (pipeL_eat_t4 Er (Nat.le_refl Er) hpL1 (T4 *> (T4 ^^ (b - Er)) *> r)) as [Lt2 [hpL2 hs3]].
      replace (Er - Er) with 0 in hpL2 by lia.
      rewrite Str_app_assoc. eapply evstep_trans; [exact hs1 |].
      assert (hs2' : (([S1] *> T2 *> Lt) {{A}}> (encS aL false (b + 2) [] (Some (2 * q + 1)) *> r))
                       -[ tm ]->* (([S1; S1] *> Lt1) {{F}}> ((T4 ^^ (b + 1)) *> r))).
      { unfold encS; cbn [encSegTail]. replace (b + 2) with ((b + 1) + 1) by lia. (rewrite ?app_nil_r in hs2; rewrite ?Str_app_assoc in hs2; rewrite ?app_nil_r; rewrite ?Str_app_assoc). exact hs2. }
      eapply evstep_trans; [exact hs2' |].
      rewrite hR. eapply evstep_trans; [exact hs3 |].
      change (T4 *> (T4 ^^ (b - Er)) *> r) with ([S0; S1] *> T3 *> (T4 ^^ (b - Er)) *> r).
      eapply evstep_trans; [exact (PipeL_unwind hpL2 (T3 *> (T4 ^^ (b - Er)) *> r)) |].
      assert (hEq : (((Wb ++ (T2 ^^ (aL + 2 * q + 2))) ++ T5) ++ (T4 ^^ Er)) *> T3 *> (T4 ^^ (b - Er)) *> r =
                    (Wb ++ encS (aL + 2 * q + 2) true Er (sp1 (b - Er)) None) *> r).
      { unfold encS; rewrite encSegTail_sp1, ?app_nil_r, ?Str_app_assoc. reflexivity. }
      rewrite hEq.
      pose proof (PureP2_lift2SegCell_dump (aL + 2 * q + 2) true Er (b - Er) hrest (or_introl eq_refl) ltac:(lia) r) as hd.
      replace (Er + sumList es') with (e + sumList es' - (q + 1)) in hd by lia.
      replace (b - Er - sumList es') with (q + b + 1 - (e + sumList es')) in hd by lia.
      exact hd.
Qed.

Lemma PureP2_lift2SegS0Zero {W W' : list Sym} {es : list nat}
    (m b : nat) (hm : 1 <= m) (hp : PureP2 W W' es) (hge : b + 2 <= sumList es) :
    exists e0' es', OneBlock (((W ++ (T2 ^^ (2 * m))) ++ T3) ++ (T4 ^^ (b + 1)))
        (W' ++ encS (2 * m) false (b + 2) [] None) e0' es' /\
      e0' + sumList es' = sumList es - (b + 2).
Proof.
  destruct hp as [W | Wa Wb Wc e es' h1 hrest].
  - cbn [sumList] in hge; lia.
  - cbn [sumList] in hge |- *.
    pose proof (proj1 h1) as he1.
    set (e' := e - 1).
    destruct (Compare_dec.le_dec (b + 1) e') as [hfull | hpart].
    + exists (e' - (b + 1)), es'. split; [| lia].
      exists (Wb ++ encS (2 * m) false (b + 2) [] None). split.
      * intros W_next r.
        destruct (proj1 (proj2 h1) ((T2 ^^ (2 * m)) *> T3 *> (T4 ^^ (b + 1)) *> W_next *> r)) as [Lt [hpL hs1]].
        replace (e - 1) with e' in hpL by lia.
        pose proof (rule_q0_t2 (2 * m) (T2 *> Lt) (T3 *> (T4 ^^ (b + 1)) *> W_next *> r)) as hs2.
        assert (hT3s : (T3 ^^ (2 * m)) *> T2 *> Lt = T3 *> (T3 ^^ (2 * m - 1)) *> T2 *> Lt).
        { replace (2 * m) with (S (2 * m - 1)) at 1 by lia. rewrite zPsr. reflexivity. }
        pose proof (step_q0_t3_punch ((T3 ^^ (2 * m - 1)) *> T2 *> Lt) ((T4 ^^ (b + 1)) *> W_next *> r)) as hs3.
        pose proof (pipeL_T2_blk 0 (2 * m - 1) hpL) as hpblk.
        rewrite zPz, zLan in hpblk; replace (0 + 1) with 1 in hpblk by lia.
        destruct (pipeL_eat_t4_pipeL1 b hfull hpblk (W_next *> r)) as [Lt2 [hpL2 hs4]].
        assert (hpL2' : PipeL1 (e' - (b + 1)) (Wb ++ encS (2 * m) false (b + 2) [] None) Lt2).
        { eapply pipeL1_eqR; [| exact hpL2].
          unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc, ?list_pow_add_r, <- ?list_pow_add.
          replace (2 * m - 1 + 1) with (2 * m) by lia.
          replace (1 + (b + 1)) with (b + 2) by lia. reflexivity. }
        exists (([S1; S1] *> Lt2) {{F}}> (W_next *> r)). split.
        -- left. exists Lt2. split; [exact hpL2' | reflexivity].
        -- rewrite ?Str_app_assoc. eapply evstep_trans; [exact hs1 |].
           eapply evstep_trans; [exact hs2 |].
           rewrite hT3s. exact (stepStar_trans hs3 hs4).
      * exact (PureP2_liftCell (2 * m) false (b + 2) ltac:(right; split; lia) ltac:(lia) hrest).
    + destruct (PureP2_lift2SegCell (2 * m) false (e' + 1) (b - e') hrest
        ltac:(right; split; lia) ltac:(lia)) as [e0' [es_out [[Wm [hp1 hpp]] hsum]]].
      replace (e' + 1 + (b - e') + 1) with (b + 2) in hpp by lia.
      exists e0', es_out. split; [| lia].
      exists Wm. split; [| exact hpp].
      intros W_next r.
      destruct (proj1 (proj2 h1) ((T2 ^^ (2 * m)) *> T3 *> (T4 ^^ (b + 1)) *> W_next *> r)) as [Lt [hpL hs1]].
      replace (e - 1) with e' in hpL by lia.
      pose proof (rule_q0_t2 (2 * m) (T2 *> Lt) (T3 *> (T4 ^^ (b + 1)) *> W_next *> r)) as hs2.
      assert (hT3s : (T3 ^^ (2 * m)) *> T2 *> Lt = T3 *> (T3 ^^ (2 * m - 1)) *> T2 *> Lt).
      { replace (2 * m) with (S (2 * m - 1)) at 1 by lia. rewrite zPsr. reflexivity. }
      pose proof (step_q0_t3_punch ((T3 ^^ (2 * m - 1)) *> T2 *> Lt) ((T4 ^^ (b + 1)) *> W_next *> r)) as hs3.
      pose proof (pipeL_T2_blk 0 (2 * m - 1) hpL) as hpblk.
      rewrite zPz, zLan in hpblk; replace (0 + 1) with 1 in hpblk by lia.
      assert (hR : (T4 ^^ (b + 1)) *> W_next *> r = (T4 ^^ e') *> T4 *> (T4 ^^ (b - e')) *> W_next *> r).
      { replace (b + 1) with (e' + (1 + (b - e'))) at 1 by lia. rewrite !pow_add_blank, zP1. reflexivity. }
      destruct (pipeL_eat_t4 e' (Nat.le_refl e') hpblk (T4 *> (T4 ^^ (b - e')) *> W_next *> r)) as [Lt2 [hpL2 hs4]].
      replace (e' - e') with 0 in hpL2 by lia.
      destruct (hp1 W_next r) as [cfg [hpe hst]].
      exists cfg. split; [exact hpe |].
      rewrite ?Str_app_assoc. eapply evstep_trans; [exact hs1 |].
      eapply evstep_trans; [exact hs2 |].
      rewrite hT3s. eapply evstep_trans; [exact hs3 |].
      rewrite hR. eapply evstep_trans; [exact hs4 |].
      change (T4 *> (T4 ^^ (b - e')) *> W_next *> r) with ([S0; S1] *> T3 *> (T4 ^^ (b - e')) *> W_next *> r).
      eapply evstep_trans; [exact (PipeL_unwind hpL2 (T3 *> (T4 ^^ (b - e')) *> W_next *> r)) |].
      assert (hEq : (((Wb ++ (T2 ^^ (2 * m - 1 + 1))) ++ (T4 ^^ 1)) ++ (T4 ^^ e')) *> T3 *> (T4 ^^ (b - e')) *> W_next *> r =
                    ((Wb ++ encS (2 * m) false (e' + 1) (sp1 (b - e')) None) ++ W_next) *> r).
      { unfold encS; rewrite encSegTail_sp1, ?app_nil_r, ?Str_app_assoc, <- pow_add_blank.
        replace (2 * m - 1 + 1) with (2 * m) by lia.
        replace (1 + e') with (e' + 1) by lia. reflexivity. }
      rewrite hEq. exact hst.
Qed.

Lemma HubP2B_liftTranspRun {e : nat} {W W1 : list Sym} (a b rep : nat)
    (ha : 1 <= a) (hb : 2 <= b) (hrep : 1 <= rep) (h : HubP2B e W W1) :
    HubP2B e (W ++ (((T2 ^^ a) ++ (T4 ^^ b)) ^^ rep)) (W1 ++ (((T2 ^^ a) ++ (T4 ^^ b)) ^^ rep)).
Proof.
  assert (hpre : forall k, HubP2B e (W ++ (((T2 ^^ a) ++ (T4 ^^ b)) ^^ k))
                            (W1 ++ (((T2 ^^ a) ++ (T4 ^^ b)) ^^ k))).
  { induction k as [|k IH].
    - rewrite !list_pow_zero, ?app_nil_r. exact h.
    - pose proof (HubP2B_liftCell a false b (or_intror (conj ha hb)) ltac:(lia) IH) as hk.
      replace (S k) with (k + 1) by lia.
      rewrite list_pow_succ_right, <- !append_assoc.
      unfold encS in hk; cbn [encSegTail] in hk. rewrite ?app_nil_r, <- !append_assoc in hk.
      exact hk. }
  exact (hpre rep).
Qed.

Lemma PureP2_liftTranspItem {W W' : list Sym} {es : list nat} (x : RleItem)
    (hx : isTranspItem x = true) (hp : PureP2 W W' es) :
    PureP2 (W ++ encItem x) (W' ++ encItem x) es.
Proof.
  destruct x as [a hc b seg aR | a b rep | |]; cbn [isTranspItem] in hx; try discriminate.
  - destruct hc; [discriminate |].
    destruct seg; [|discriminate].
    destruct aR; [discriminate |].
    split_andb.
    unfold encItem; rewrite encSingle_eq_encS; simpl option_map.
    exact (PureP2_liftCell (N.to_nat a) false (N.to_nat b) ltac:(right; split; lia) ltac:(lia) hp).
  - split_andb. unfold encItem.
    induction hp as [W | Wa Wb Wc e es' h1 hrest IH].
    + exact (PureP2_nil _).
    + exact (PureP2_cons (HubP2B_liftTranspRun (N.to_nat a) (N.to_nat b) (N.to_nat rep) ltac:(lia) ltac:(lia) ltac:(lia) h1) IH).
Qed.

Lemma PureP2_liftTranspList : forall (xs : list RleItem) {W W' : list Sym} {es : list nat},
    isTranspList xs = true -> PureP2 W W' es ->
    PureP2 (W ++ encItems xs) (W' ++ encItems xs) es.
Proof.
  induction xs as [|x xs' IH]; intros W W' es hxs hp.
  - cbn [encItems]; rewrite ?app_nil_r. exact hp.
  - cbn [isTranspList List.forallb] in hxs. apply Bool.andb_true_iff in hxs. destruct hxs as [hx hxs'].
    pose proof (IH _ _ _ hxs' (PureP2_liftTranspItem x hx hp)) as h2.
    cbn [encItems]; rewrite <- !append_assoc. exact h2.
Qed.

Lemma oneBlock_posT2 {W W' : list Sym} {e0 : nat} {es : list nat}
    (hb : OneBlock W W' e0 es) (hpos : 1 <= e0 + sumList es) :
    exists Wm e1 es1, 1 <= e1 /\ e1 + sumList es1 = e0 + sumList es /\ PureP2 Wm W' es1 /\
      (forall (C_rest : list Sym) (r : Stream Sym),
        exists cfg, P1Entry e1 Wm (T2 ++ C_rest) r cfg /\
          (b0 {{E}}> (T2 *> T0 *> T1 *> (W ++ (T2 ++ C_rest)) *> r)) -[ tm ]->* cfg).
Proof.
  destruct hb as [W1 [h1 hp]].
  destruct e0 as [|e0'].
  - destruct hp as [W1 | W1 W2 W' e1 es1 h2 hrest].
    + cbn [sumList] in hpos; lia.
    + exists W2, e1, es1. split; [exact (proj1 h2) | split; [cbn [sumList]; lia | split; [exact hrest |]]].
      intros C_rest r. exact (hubP1_zero_merge h1 h2 r).
  - exists W1, (S e0'), es. split; [lia | split; [reflexivity | split; [exact hp |]]].
    intros C_rest r. exact (h1 (T2 ++ C_rest) r).
Qed.

Lemma t2_cons_pow (n : nat) (xs : list Sym) :
    T2 ++ ((T2 ^^ n) ++ xs) = (T2 ^^ (n + 1)) ++ xs.
Proof.
  rewrite <- append_assoc, <- list_pow_succ. reflexivity.
Qed.

Lemma t2_cons_pow_pred {n : nat} (hn : 1 <= n) (xs : list Sym) :
    T2 ++ ((T2 ^^ (n - 1)) ++ xs) = (T2 ^^ n) ++ xs.
Proof.
  rewrite <- append_assoc, <- list_pow_succ. replace (n - 1 + 1) with n by lia. reflexivity.
Qed.

Lemma OneBlock_liftTransp {W W' : list Sym} {e0 : nat} {es : list nat}
    (m b : nat) (hm : 1 <= m) (hb : OneBlock W W' e0 es) (hge : m + b + 2 <= e0 + sumList es) :
    exists e0' es', OneBlock (W ++ encS (2 * m) false (b + 2) [] None)
        (W' ++ encS (2 * m) false (b + 2) [] None) e0' es' /\
      e0' + sumList es' = e0 + sumList es - (m + b + 2).
Proof.
  destruct (oneBlock_posT2 hb ltac:(lia)) as [Wm [e1 [es1 [he1 [hsum [hp hP1]]]]]].
  assert (h2m_split : encS (2 * m) false (b + 2) [] None = T2 ++ ((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2)))).
  { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r.
    replace (2 * m) with ((2 * m - 1) + 1) at 1 by lia.
    rewrite list_pow_succ, append_assoc. reflexivity. }
  destruct (Compare_dec.lt_dec e1 m) as [hlt_m | hge_m].
  - destruct (PureP2_liftASplitH0Even (2 * e1 - 1) (m - e1) b hp ltac:(lia)) as [e0' [es' [[Wf [hWf1 hWf2]] hsum']]].
    replace (2 * e1 - 1 + 2 * (m - e1) + 1) with (2 * m) in hWf2 by lia.
    exists e0', es'. split; [| lia].
    exists Wf. split; [| exact hWf2].
    intros W_next r.
    destruct (hP1 (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next) r) as [cfg0 [hpe0 hs0]].
    assert (hpe0' : P1Entry e1 Wm ((T2 ^^ (2 * m)) ++ ((T4 ^^ (b + 2)) ++ W_next)) r cfg0).
    { rewrite ?append_assoc in hpe0. rewrite t2_cons_pow_pred in hpe0; [| lia]. exact hpe0. }
    pose proof (p1Entry_asplit_create (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) (2 * m) he1 ltac:(lia) hpe0') as has.
    destruct (hWf1 W_next r) as [cfgf [hpef hsf]].
    exists cfgf. split; [exact hpef |].
    (try rewrite h2m_split in hs0; rewrite ?Str_app_assoc in hs0; try rewrite h2m_split; rewrite ?Str_app_assoc).
    eapply evstep_trans; [exact hs0 |].
    eapply evstep_trans; [exact has |].
    unfold encS in hsf; cbn [encSegTail] in hsf.
    replace (2 * m - 2 * e1) with (2 * (m - e1)) by lia.
    (rewrite ?app_nil_r in hsf; rewrite ?Str_app_assoc in hsf; rewrite ?app_nil_r; rewrite ?Str_app_assoc). exact hsf.
  - destruct (Nat.eq_dec e1 m) as [heq_m | hne_m].
    + subst e1.
      destruct (PureP2_lift2SegS0Zero m b hm hp ltac:(lia)) as [e0' [es' [[Wf [hWf1 hWf2]] hsum']]].
      exists e0', es'. split; [| lia].
      exists Wf. split; [| exact hWf2].
      intros W_next r.
      destruct (hP1 (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next) r) as [cfg0 [hpe0 hs0]].
      assert (hpe0' : P1Entry m Wm (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ++ W_next) r cfg0).
      { (rewrite ?append_assoc in hpe0; rewrite ?append_assoc). rewrite t2_cons_pow_pred in hpe0; [| lia]. exact hpe0. }
      replace (b + 2) with ((b + 1) + 1) in hpe0' by lia.
      pose proof (p1Entry_transp_exact_m m (b + 1) hm hpe0') as hex.
      destruct (hWf1 W_next r) as [cfgf [hpef hsf]].
      exists cfgf. split; [exact hpef |].
      (try rewrite h2m_split in hs0; rewrite ?Str_app_assoc in hs0; try rewrite h2m_split; rewrite ?Str_app_assoc).
      eapply evstep_trans; [exact hs0 |].
      eapply evstep_trans; [exact hex |].
      (rewrite ?Str_app_assoc in hsf; rewrite ?Str_app_assoc). exact hsf.
    + destruct (Compare_dec.le_dec (m + b + 2) e1) as [hfull | hpart].
      * exists (e1 - (m + b + 2)), es1. split; [| lia].
        exists (Wm ++ encS (2 * m) false (b + 2) [] None). split.
        -- intros W_next r.
           destruct (hP1 (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next) r) as [cfg0 [hpe0 hs0]].
           assert (hpe0' : P1Entry e1 Wm (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ++ W_next) r cfg0).
           { (rewrite ?append_assoc in hpe0; rewrite ?append_assoc). rewrite t2_cons_pow_pred in hpe0; [| lia]. exact hpe0. }
           destruct (p1Entry_transp_pass m b hm hfull hpe0') as [Lt' [hpL' hs1]].
           assert (hpL'' : PipeL1 (e1 - (m + b + 2)) (Wm ++ encS (2 * m) false (b + 2) [] None) Lt').
           { eapply pipeL1_eqR; [| exact hpL'].
             unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity. }
           exists (([S1; S1] *> Lt') {{F}}> (W_next *> r)). split.
           ++ left. exists Lt'. split; [exact hpL'' | reflexivity].
           ++ (try rewrite h2m_split in hs0; rewrite ?Str_app_assoc in hs0; try rewrite h2m_split; rewrite ?Str_app_assoc). exact (stepStar_trans hs0 hs1).
        -- exact (PureP2_liftCell (2 * m) false (b + 2) ltac:(right; split; lia) ltac:(lia) hp).
      * destruct (PureP2_lift2SegCell (2 * m) false (e1 - m) (m + b + 1 - e1) hp
          ltac:(right; split; lia) ltac:(lia)) as [e0' [es' [[Wf [hWf1 hWf2]] hsum']]].
        replace (e1 - m + (m + b + 1 - e1) + 1) with (b + 2) in hWf2 by lia.
        exists e0', es'. split; [| lia].
        exists Wf. split; [| exact hWf2].
        intros W_next r.
        destruct (hP1 (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next) r) as [cfg0 [hpe0 hs0]].
        assert (hpe0' : P1Entry e1 Wm (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ++ W_next) r cfg0).
        { (rewrite ?append_assoc in hpe0; rewrite ?append_assoc). rewrite t2_cons_pow_pred in hpe0; [| lia]. exact hpe0. }
        pose proof (p1Entry_transp_split (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) m b hm ltac:(lia) ltac:(lia) hpe0') as hsp.
        destruct (hWf1 W_next r) as [cfgf [hpef hsf]].
        exists cfgf. split; [exact hpef |].
        (try rewrite h2m_split in hs0; rewrite ?Str_app_assoc in hs0; try rewrite h2m_split; rewrite ?Str_app_assoc).
        eapply evstep_trans; [exact hs0 |].
        eapply evstep_trans; [exact hsp |].
        unfold encS in hsf; (try rewrite encSegTail_sp1 in hsf; rewrite ?app_nil_r in hsf; rewrite ?Str_app_assoc in hsf; try rewrite encSegTail_sp1; rewrite ?app_nil_r; rewrite ?Str_app_assoc). exact hsf.
Qed.

Lemma OneBlock_liftTranspRun : forall (rep m b : nat) {W W' : list Sym} {e0 : nat} {es : list nat},
    1 <= m -> OneBlock W W' e0 es -> rep * (m + b + 2) <= e0 + sumList es ->
    exists e0' es', OneBlock (W ++ (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ^^ rep))
        (W' ++ (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ^^ rep)) e0' es' /\
      e0' + sumList es' = e0 + sumList es - rep * (m + b + 2).
Proof.
  induction rep as [|k IH]; intros m b W W' e0 es hm hb hge.
  - exists e0, es. rewrite !list_pow_zero, ?app_nil_r. split; [exact hb | lia].
  - assert (hmul : S k * (m + b + 2) = (m + b + 2) + k * (m + b + 2)) by nia.
    destruct (OneBlock_liftTransp m b hm hb ltac:(lia)) as [e1 [es1 [hb1 hsum1]]].
    destruct (IH m b _ _ _ _ hm hb1 ltac:(lia)) as [e2 [es2 [hb2 hsum2]]].
    exists e2, es2. split; [| lia].
    replace (S k) with (k + 1) by lia.
    rewrite list_pow_succ.
    assert (hcell : (T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2)) = encS (2 * m) false (b + 2) [] None).
    { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r. reflexivity. }
    rewrite hcell in hb2.
    rewrite hcell, <- !append_assoc. exact hb2.
Qed.

Lemma OneBlock_liftTranspItem {W W' : list Sym} {e0 : nat} {es : list nat} (x : RleItem)
    (hx : isTranspItem x = true) (hb : OneBlock W W' e0 es)
    (hge : transpItemCost_nat x <= e0 + sumList es) :
    exists e0' es', OneBlock (W ++ encItem x) (W' ++ encItem x) e0' es' /\
      e0' + sumList es' = e0 + sumList es - transpItemCost_nat x.
Proof.
  destruct x as [a hc b seg aR | a b rep | |]; cbn [isTranspItem] in hx; try discriminate.
  - destruct hc; [discriminate |].
    destruct seg; [|discriminate].
    destruct aR; [discriminate |].
    split_andb.
    pose proof (N_even_decomp a ltac:(lia)) as Ha.
    set (m := N.to_nat (a / 2)%N) in *.
    set (b' := N.to_nat b - 2).
    assert (hcost : transpItemCost_nat (RIsingle a false b [] None) = m + b' + 2).
    { unfold transpItemCost_nat; cbn [transpItemCost]. lia. }
    (try rewrite hcost in hge; try rewrite hcost).
    unfold encItem; rewrite encSingle_eq_encS; simpl option_map.
    rewrite Ha. replace (N.to_nat b) with (b' + 2) by lia.
    exact (OneBlock_liftTransp m b' ltac:(lia) hb hge).
  - split_andb.
    pose proof (N_even_decomp a ltac:(lia)) as Ha.
    set (m := N.to_nat (a / 2)%N) in *.
    set (b' := N.to_nat b - 2).
    assert (hcost : transpItemCost_nat (RItranspRun a b rep) = N.to_nat rep * (m + b' + 2)).
    { unfold transpItemCost_nat; cbn [transpItemCost]. rewrite N2Nat.inj_mul. f_equal; lia. }
    (try rewrite hcost in hge; try rewrite hcost).
    unfold encItem. rewrite Ha. replace (N.to_nat b) with (b' + 2) by lia.
    exact (OneBlock_liftTranspRun (N.to_nat rep) m b' ltac:(lia) hb hge).
Qed.

Lemma OneBlock_liftTranspList : forall (xs : list RleItem) {W W' : list Sym} {e0 : nat} {es : list nat},
    isTranspList xs = true -> OneBlock W W' e0 es ->
    transpListCost_nat xs <= e0 + sumList es ->
    exists e0' es', OneBlock (W ++ encItems xs) (W' ++ encItems xs) e0' es' /\
      e0' + sumList es' = e0 + sumList es - transpListCost_nat xs.
Proof.
  induction xs as [|x xs' IH]; intros W W' e0 es hxs hb hge.
  - exists e0, es. cbn [encItems]; rewrite ?app_nil_r.
    unfold transpListCost_nat; cbn [transpListCost]; simpl N.to_nat. split; [exact hb | lia].
  - cbn [isTranspList List.forallb] in hxs. apply Bool.andb_true_iff in hxs. destruct hxs as [hx hxs'].
    (try rewrite transpListCost_nat_cons in hge; try rewrite transpListCost_nat_cons).
    destruct (OneBlock_liftTranspItem x hx hb ltac:(lia)) as [e1 [es1 [hb1 hsum1]]].
    destruct (IH _ _ _ _ hxs' hb1 ltac:(lia)) as [e2 [es2 [hb2 hsum2]]].
    exists e2, es2. split; [cbn [encItems]; rewrite <- !append_assoc; exact hb2 | lia].
Qed.

Lemma OneBlock_liftS0 {W W' : list Sym} {e0 : nat} {es : list nat}
    (m b : nat) (hb_pos : 1 <= b) (hb : OneBlock W W' e0 es) (hge : m + 1 <= e0 + sumList es) :
    exists es', PureP2 (W ++ encS (2 * m + 1) true (b + 1) [] None)
        (W' ++ encS (2 * m + 2) true b [] None) es' /\
      sumList es' = e0 + sumList es - m.
Proof.
  destruct (oneBlock_posT2 hb ltac:(lia)) as [Wm [e1 [es1 [he1 [hsum [hp hP1]]]]]].
  assert (hT2s : forall bb, encS (2 * m + 1) true bb [] None = T2 ++ (((T2 ^^ (2 * m)) ++ T5) ++ (T4 ^^ bb))).
  { intros bb. unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, list_pow_succ, ?append_assoc. reflexivity. }
  destruct (Compare_dec.le_dec (m + 1) e1) as [hle | hgt].
  - assert (hhub : HubP2B (e1 - m) (W ++ encS (2 * m + 1) true (b + 1) [] None)
                     (Wm ++ encS (2 * m + 2) true b [] None)).
    { split; [lia | split].
      - intros r.
        destruct (hP1 (((T2 ^^ (2 * m)) ++ T5) ++ (T4 ^^ (b + 1))) r) as [cfg0 [hpe0 hs0]].
        assert (hpe0' : P1Entry e1 Wm ((((T2 ^^ (2 * m + 1)) ++ T5) ++ (T4 ^^ (b + 1))) ++ []) r cfg0).
        { (try rewrite app_nil_r in hpe0; rewrite ?append_assoc in hpe0; try rewrite app_nil_r; rewrite ?append_assoc). rewrite t2_cons_pow in hpe0. exact hpe0. }
        destruct (p1Entry_h1_enter_odd m b hle hpe0') as [Lt' [hpL' hs1]].
        exists Lt'. split.
        + eapply pipeL_eqR; [| exact hpL'].
          unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
        + rewrite (hT2s (b + 1)). rewrite zLan in hs1. exact (stepStar_trans hs0 hs1).
      - intros Wp hWp.
        assert (hsplit : W ++ encS (2 * m + 1) true (b + 1) [] None =
                         (W ++ encS (2 * m + 1) true b [] None) ++ T4).
        { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity. }
        assert (hWpEq : Wp = W ++ encS (2 * m + 1) true b [] None).
        { apply (@app_cancel_right _ _ _ T4). congruence. }
        subst Wp.
        set (b' := b - 1).
        exists (Wm ++ encS (2 * m + 2) true b' [] None). split.
        + replace b with (b' + 1) at 1 by lia.
          unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity.
        + intros r.
          replace b with (b' + 1) by lia.
          destruct (hP1 (((T2 ^^ (2 * m)) ++ T5) ++ (T4 ^^ (b' + 1))) r) as [cfg0 [hpe0 hs0]].
          assert (hpe0' : P1Entry e1 Wm ((((T2 ^^ (2 * m + 1)) ++ T5) ++ (T4 ^^ (b' + 1))) ++ []) r cfg0).
          { (try rewrite app_nil_r in hpe0; rewrite ?append_assoc in hpe0; try rewrite app_nil_r; rewrite ?append_assoc). rewrite t2_cons_pow in hpe0. exact hpe0. }
          destruct (p1Entry_h1_enter_odd m b' hle hpe0') as [Lt' [hpL' hs1]].
          exists Lt'. split.
          * eapply pipeL_eqR; [| exact hpL'].
            unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
          * rewrite (hT2s (b' + 1)). rewrite zLan in hs1. exact (stepStar_trans hs0 hs1). }
    exists ((e1 - m) :: es1). split.
    + exact (PureP2_cons hhub (PureP2_liftCell (2 * m + 2) true b (or_introl eq_refl) hb_pos hp)).
    + cbn [sumList]; lia.
  - destruct (PureP2_liftASplitH1Odd (2 * e1 - 1) (m - e1) b hb_pos hp ltac:(lia)) as [es_out [hpp hsum']].
    replace (2 * e1 - 1 + 2 * (m - e1) + 3) with (2 * m + 2) in hpp by lia.
    assert (has_step : forall bb r,
      (b0 {{E}}> (T2 *> T0 *> T1 *> (W ++ encS (2 * m + 1) true bb [] None) *> r)) -[ tm ]->*
      (b0 {{E}}> (T2 *> T0 *> T1 *> (Wm ++ encS (2 * e1 - 1) true bb [] (Some (2 * (m - e1) + 1))) *> r))).
    { intros bb r.
      destruct (hP1 (((T2 ^^ (2 * m)) ++ T5) ++ (T4 ^^ bb)) r) as [cfg0 [hpe0 hs0]].
      assert (hpe0' : P1Entry e1 Wm ((T2 ^^ (2 * m + 1)) ++ (T5 ++ (T4 ^^ bb))) r cfg0).
      { (rewrite ?append_assoc in hpe0; rewrite ?append_assoc). rewrite t2_cons_pow in hpe0. exact hpe0. }
      pose proof (p1Entry_asplit_create (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) (2 * m + 1) he1 ltac:(lia) hpe0') as has.
      rewrite (hT2s bb). eapply evstep_trans; [exact hs0 |].
      eapply evstep_trans; [exact has |].
      unfold encS; cbn [encSegTail].
      replace (2 * m + 1 - 2 * e1) with (2 * (m - e1) + 1) by lia.
      rewrite ?app_nil_r, ?Str_app_assoc. apply evstep_refl. }
    destruct (PureP2_uncons hpp ltac:(lia)) as [Wmid [e_f [es_f [hEqf [hfirst htail]]]]].
    subst es_out. cbn [sumList] in hsum'.
    assert (hfirst' : HubP2B e_f (W ++ encS (2 * m + 1) true (b + 1) [] None) Wmid).
    { split; [exact (proj1 hfirst) | split].
      - intros r. destruct (proj1 (proj2 hfirst) r) as [Lt [hpL hs]].
        exists Lt. split; [exact hpL | exact (stepStar_trans (has_step (b + 1) r) hs)].
      - intros Wp hWp.
        assert (hsplit : W ++ encS (2 * m + 1) true (b + 1) [] None =
                         (W ++ encS (2 * m + 1) true b [] None) ++ T4).
        { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity. }
        assert (hWpEq : Wp = W ++ encS (2 * m + 1) true b [] None).
        { apply (@app_cancel_right _ _ _ T4). congruence. }
        subst Wp.
        assert (hsplitM : Wm ++ encS (2 * e1 - 1) true (b + 1) [] (Some (2 * (m - e1) + 1)) =
                          (Wm ++ encS (2 * e1 - 1) true b [] (Some (2 * (m - e1) + 1))) ++ T4).
        { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity. }
        destruct (proj2 (proj2 hfirst) _ hsplitM) as [Wmp [hWmp hf2]].
        exists Wmp. split; [exact hWmp |].
        intros r. destruct (hf2 r) as [Lf [hpLf hsf]].
        exists Lf. split; [exact hpLf | exact (stepStar_trans (has_step b r) hsf)]. }
    exists (e_f :: es_f). split; [exact (PureP2_cons hfirst' htail) | cbn [sumList]; lia].
Qed.

Lemma OneBlock_liftS1 {W W' : list Sym} {e0 : nat} {es : list nat}
    (m b : nat) (hm : 1 <= m) (hb_pos : 1 <= b) (hb : OneBlock W W' e0 es) (hge : m + 1 <= e0 + sumList es) :
    exists es', PureP2 (W ++ encS (2 * m) true (b + 1) [] None)
        (W' ++ encS (2 * m + 1) false (b + 1) [] None) es' /\
      sumList es' = e0 + sumList es - m.
Proof.
  destruct (oneBlock_posT2 hb ltac:(lia)) as [Wm [e1 [es1 [he1 [hsum [hp hP1]]]]]].
  assert (hT2s : forall bb, encS (2 * m) true bb [] None = T2 ++ (((T2 ^^ (2 * m - 1)) ++ T5) ++ (T4 ^^ bb))).
  { intros bb. unfold encS; cbn [encSegTail]. rewrite ?app_nil_r.
    replace (2 * m) with ((2 * m - 1) + 1) at 1 by lia.
    rewrite list_pow_succ, ?append_assoc. reflexivity. }
  destruct (Compare_dec.le_dec (m + 1) e1) as [hle | hgt].
  - assert (hhub : HubP2B (e1 - m) (W ++ encS (2 * m) true (b + 1) [] None)
                     (Wm ++ encS (2 * m + 1) false (b + 1) [] None)).
    { split; [lia | split].
      - intros r.
        destruct (hP1 (((T2 ^^ (2 * m - 1)) ++ T5) ++ (T4 ^^ (b + 1))) r) as [cfg0 [hpe0 hs0]].
        assert (hpe0' : P1Entry e1 Wm ((((T2 ^^ (2 * m)) ++ T5) ++ (T4 ^^ (b + 1))) ++ []) r cfg0).
        { (try rewrite app_nil_r in hpe0; rewrite ?append_assoc in hpe0; try rewrite app_nil_r; rewrite ?append_assoc). rewrite t2_cons_pow_pred in hpe0; [| lia]. exact hpe0. }
        destruct (p1Entry_h1_enter_even m b hm hle hpe0') as [Lt' [hpL' hs1]].
        exists Lt'. split.
        + eapply pipeL_eqR; [| exact hpL'].
          unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
        + rewrite (hT2s (b + 1)). rewrite zLan in hs1. exact (stepStar_trans hs0 hs1).
      - intros Wp hWp.
        assert (hsplit : W ++ encS (2 * m) true (b + 1) [] None =
                         (W ++ encS (2 * m) true b [] None) ++ T4).
        { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity. }
        assert (hWpEq : Wp = W ++ encS (2 * m) true b [] None).
        { apply (@app_cancel_right _ _ _ T4). congruence. }
        subst Wp.
        set (b' := b - 1).
        exists (Wm ++ encS (2 * m + 1) false (b' + 1) [] None). split.
        + replace b with (b' + 1) at 1 by lia.
          unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity.
        + intros r.
          replace b with (b' + 1) by lia.
          destruct (hP1 (((T2 ^^ (2 * m - 1)) ++ T5) ++ (T4 ^^ (b' + 1))) r) as [cfg0 [hpe0 hs0]].
          assert (hpe0' : P1Entry e1 Wm ((((T2 ^^ (2 * m)) ++ T5) ++ (T4 ^^ (b' + 1))) ++ []) r cfg0).
          { (try rewrite app_nil_r in hpe0; rewrite ?append_assoc in hpe0; try rewrite app_nil_r; rewrite ?append_assoc). rewrite t2_cons_pow_pred in hpe0; [| lia]. exact hpe0. }
          destruct (p1Entry_h1_enter_even m b' hm hle hpe0') as [Lt' [hpL' hs1]].
          exists Lt'. split.
          * eapply pipeL_eqR; [| exact hpL'].
            unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
          * rewrite (hT2s (b' + 1)). rewrite zLan in hs1. exact (stepStar_trans hs0 hs1). }
    exists ((e1 - m) :: es1). split.
    + exact (PureP2_cons hhub (PureP2_liftCell (2 * m + 1) false (b + 1) ltac:(right; split; lia) ltac:(lia) hp)).
    + cbn [sumList]; lia.
  - destruct (Nat.eq_dec e1 m) as [heq_m | hne_m].
    + subst e1.
      pose proof (PureP2_liftCell (2 * m + 1) false (b + 1) ltac:(right; split; lia) ltac:(lia) hp) as hpp.
      assert (hex_step : forall bb r,
        (b0 {{E}}> (T2 *> T0 *> T1 *> (W ++ encS (2 * m) true bb [] None) *> r)) -[ tm ]->*
        (b0 {{E}}> (T2 *> T0 *> T1 *> (Wm ++ encS (2 * m + 1) false bb [] None) *> r))).
      { intros bb r.
        destruct (hP1 (((T2 ^^ (2 * m - 1)) ++ T5) ++ (T4 ^^ bb)) r) as [cfg0 [hpe0 hs0]].
        assert (hpe0' : P1Entry m Wm ((((T2 ^^ (2 * m)) ++ T5) ++ (T4 ^^ bb)) ++ []) r cfg0).
        { (try rewrite app_nil_r in hpe0; rewrite ?append_assoc in hpe0; try rewrite app_nil_r; rewrite ?append_assoc). rewrite t2_cons_pow_pred in hpe0; [| lia]. exact hpe0. }
        pose proof (p1Entry_s1_exact m bb hm hpe0') as hex.
        rewrite (hT2s bb). eapply evstep_trans; [exact hs0 |].
        unfold encS; cbn [encSegTail]. (rewrite ?app_nil_r in hex; rewrite ?Str_app_assoc in hex; rewrite ?app_nil_r; rewrite ?Str_app_assoc). exact hex. }
      destruct (PureP2_uncons hpp ltac:(lia)) as [Wmid [e_f [es_f [hEqf [hfirst htail]]]]].
      subst es1. cbn [sumList] in hsum.
      assert (hfirst' : HubP2B e_f (W ++ encS (2 * m) true (b + 1) [] None) Wmid).
      { split; [exact (proj1 hfirst) | split].
        - intros r. destruct (proj1 (proj2 hfirst) r) as [Lt [hpL hs]].
          exists Lt. split; [exact hpL | exact (stepStar_trans (hex_step (b + 1) r) hs)].
        - intros Wp hWp.
          assert (hsplit : W ++ encS (2 * m) true (b + 1) [] None =
                           (W ++ encS (2 * m) true b [] None) ++ T4).
          { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity. }
          assert (hWpEq : Wp = W ++ encS (2 * m) true b [] None).
          { apply (@app_cancel_right _ _ _ T4). congruence. }
          subst Wp.
          assert (hsplitM : Wm ++ encS (2 * m + 1) false (b + 1) [] None =
                            (Wm ++ encS (2 * m + 1) false b [] None) ++ T4).
          { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity. }
          destruct (proj2 (proj2 hfirst) _ hsplitM) as [Wmp [hWmp hf2]].
          exists Wmp. split; [exact hWmp |].
          intros r. destruct (hf2 r) as [Lf [hpLf hsf]].
          exists Lf. split; [exact hpLf | exact (stepStar_trans (hex_step b r) hsf)]. }
      exists (e_f :: es_f). split; [exact (PureP2_cons hfirst' htail) | cbn [sumList]; lia].
    + destruct (PureP2_liftASplitH1Even (2 * e1 - 1) (m - e1) b hb_pos hp ltac:(lia)) as [es_out [hpp hsum']].
      replace (2 * e1 - 1 + 2 * (m - e1) + 2) with (2 * m + 1) in hpp by lia.
      assert (has_step : forall bb r,
        (b0 {{E}}> (T2 *> T0 *> T1 *> (W ++ encS (2 * m) true bb [] None) *> r)) -[ tm ]->*
        (b0 {{E}}> (T2 *> T0 *> T1 *> (Wm ++ encS (2 * e1 - 1) true bb [] (Some (2 * (m - e1)))) *> r))).
      { intros bb r.
        destruct (hP1 (((T2 ^^ (2 * m - 1)) ++ T5) ++ (T4 ^^ bb)) r) as [cfg0 [hpe0 hs0]].
        assert (hpe0' : P1Entry e1 Wm ((T2 ^^ (2 * m)) ++ (T5 ++ (T4 ^^ bb))) r cfg0).
        { (rewrite ?append_assoc in hpe0; rewrite ?append_assoc). rewrite t2_cons_pow_pred in hpe0; [| lia]. exact hpe0. }
        pose proof (p1Entry_asplit_create (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) (2 * m) he1 ltac:(lia) hpe0') as has.
        rewrite (hT2s bb). eapply evstep_trans; [exact hs0 |].
        eapply evstep_trans; [exact has |].
        unfold encS; cbn [encSegTail].
        replace (2 * m - 2 * e1) with (2 * (m - e1)) by lia.
        rewrite ?app_nil_r, ?Str_app_assoc. apply evstep_refl. }
      destruct (PureP2_uncons hpp ltac:(lia)) as [Wmid [e_f [es_f [hEqf [hfirst htail]]]]].
      subst es_out. cbn [sumList] in hsum'.
      assert (hfirst' : HubP2B e_f (W ++ encS (2 * m) true (b + 1) [] None) Wmid).
      { split; [exact (proj1 hfirst) | split].
        - intros r. destruct (proj1 (proj2 hfirst) r) as [Lt [hpL hs]].
          exists Lt. split; [exact hpL | exact (stepStar_trans (has_step (b + 1) r) hs)].
        - intros Wp hWp.
          assert (hsplit : W ++ encS (2 * m) true (b + 1) [] None =
                           (W ++ encS (2 * m) true b [] None) ++ T4).
          { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity. }
          assert (hWpEq : Wp = W ++ encS (2 * m) true b [] None).
          { apply (@app_cancel_right _ _ _ T4). congruence. }
          subst Wp.
          assert (hsplitM : Wm ++ encS (2 * e1 - 1) true (b + 1) [] (Some (2 * (m - e1))) =
                            (Wm ++ encS (2 * e1 - 1) true b [] (Some (2 * (m - e1)))) ++ T4).
          { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, (list_pow_succ_right T4), ?append_assoc. reflexivity. }
          destruct (proj2 (proj2 hfirst) _ hsplitM) as [Wmp [hWmp hf2]].
          exists Wmp. split; [exact hWmp |].
          intros r. destruct (hf2 r) as [Lf [hpLf hsf]].
          exists Lf. split; [exact hpLf | exact (stepStar_trans (has_step b r) hsf)]. }
      exists (e_f :: es_f). split; [exact (PureP2_cons hfirst' htail) | cbn [sumList]; lia].
Qed.

Lemma OneBlock_liftS2 {W W' : list Sym} {e0 : nat} {es : list nat}
    (m b : nat) (hb : OneBlock W W' e0 es) (hge : m + b + 2 <= e0 + sumList es) :
    exists e0' es', OneBlock (W ++ encS (2 * m + 1) false (b + 2) [] None)
        (W' ++ encS (2 * m + 1) true (b + 1) [] None) e0' es' /\
      e0' + sumList es' = e0 + sumList es - (m + b + 2).
Proof.
  destruct (oneBlock_posT2 hb ltac:(lia)) as [Wm [e1 [es1 [he1 [hsum [hp hP1]]]]]].
  assert (hT2s : encS (2 * m + 1) false (b + 2) [] None = T2 ++ ((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2)))).
  { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, list_pow_succ, append_assoc. reflexivity. }
  destruct (Compare_dec.le_dec e1 m) as [hlt_m | hgt_m].
  - destruct (PureP2_liftASplitH0Odd (2 * e1 - 1) (m - e1) b hp ltac:(lia)) as [e0' [es' [[Wf [hWf1 hWf2]] hsum']]].
    replace (2 * e1 - 1 + 2 * (m - e1) + 2) with (2 * m + 1) in hWf2 by lia.
    exists e0', es'. split; [| lia].
    exists Wf. split; [| exact hWf2].
    intros W_next r.
    destruct (hP1 (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ++ W_next) r) as [cfg0 [hpe0 hs0]].
    assert (hpe0' : P1Entry e1 Wm ((T2 ^^ (2 * m + 1)) ++ ((T4 ^^ (b + 2)) ++ W_next)) r cfg0).
    { (rewrite ?append_assoc in hpe0; rewrite ?append_assoc). rewrite t2_cons_pow in hpe0. exact hpe0. }
    pose proof (p1Entry_asplit_create (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) (2 * m + 1) he1 ltac:(lia) hpe0') as has.
    destruct (hWf1 W_next r) as [cfgf [hpef hsf]].
    exists cfgf. split; [exact hpef |].
    (try rewrite hT2s in hs0; rewrite ?Str_app_assoc in hs0; try rewrite hT2s; rewrite ?Str_app_assoc).
    eapply evstep_trans; [exact hs0 |].
    eapply evstep_trans; [exact has |].
    unfold encS in hsf; cbn [encSegTail] in hsf.
    replace (2 * m + 1 - 2 * e1) with (2 * (m - e1) + 1) by lia.
    (rewrite ?app_nil_r in hsf; rewrite ?Str_app_assoc in hsf; rewrite ?app_nil_r; rewrite ?Str_app_assoc). exact hsf.
  - destruct (Compare_dec.le_dec (m + b + 2) e1) as [hfull | hpart].
    + exists (e1 - (m + b + 2)), es1. split; [| lia].
      exists (Wm ++ encS (2 * m + 1) true (b + 1) [] None). split.
      * intros W_next r.
        destruct (hP1 (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ++ W_next) r) as [cfg0 [hpe0 hs0]].
        assert (hpe0' : P1Entry e1 Wm (((T2 ^^ (2 * m + 1)) ++ (T4 ^^ (b + 2))) ++ W_next) r cfg0).
        { (rewrite ?append_assoc in hpe0; rewrite ?append_assoc). rewrite t2_cons_pow in hpe0. exact hpe0. }
        replace (b + 2) with ((b + 1) + 1) in hpe0' by lia.
        destruct (p1Entry_eat_t2_odd_t4 (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) m (b + 1) ltac:(lia) hpe0') as [Lt1 [hpL1 hs1]].
        destruct (pipeL_eat_t4_pipeL1 (En := ltac:(match type of hpL1 with PipeL ?x _ _ => exact x end)) b ltac:(lia) hpL1 (W_next *> r)) as [Lt2 [hpL2 hs2]].
        assert (hpL2' : PipeL1 (e1 - (m + b + 2)) (Wm ++ encS (2 * m + 1) true (b + 1) [] None) Lt2).
        { replace (e1 - m - 1 - (b + 1)) with (e1 - (m + b + 2)) in hpL2 by lia.
          eapply pipeL1_eqR; [| exact hpL2].
          unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity. }
        exists (([S1; S1] *> Lt2) {{F}}> (W_next *> r)). split.
        -- left. exists Lt2. split; [exact hpL2' | reflexivity].
        -- (try rewrite hT2s in hs0; rewrite ?Str_app_assoc in hs0; try rewrite hT2s; rewrite ?Str_app_assoc).
           exact (stepStar_trans hs0 (stepStar_trans hs1 hs2)).
      * exact (PureP2_liftCell (2 * m + 1) true (b + 1) (or_introl eq_refl) ltac:(lia) hp).
    + set (Er := e1 - m - 1).
      destruct (PureP2_lift2SegCell (2 * m + 1) true Er (b - Er) hp (or_introl eq_refl) ltac:(lia))
        as [e0' [es' [[Wf [hWf1 hWf2]] hsum']]].
      replace (Er + (b - Er) + 1) with (b + 1) in hWf2 by lia.
      exists e0', es'. split; [| lia].
      exists Wf. split; [| exact hWf2].
      intros W_next r.
      destruct (hP1 (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ++ W_next) r) as [cfg0 [hpe0 hs0]].
      assert (hpe0' : P1Entry e1 Wm (((T2 ^^ (2 * m + 1)) ++ (T4 ^^ (b + 2))) ++ W_next) r cfg0).
      { (rewrite ?append_assoc in hpe0; rewrite ?append_assoc). rewrite t2_cons_pow in hpe0. exact hpe0. }
      replace (b + 2) with ((b + 1) + 1) in hpe0' by lia.
      destruct (p1Entry_eat_t2_odd_t4 (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) m (b + 1) ltac:(lia) hpe0') as [Lt1 [hpL1 hs1]].
      assert (hR : (T4 ^^ (b + 1)) *> W_next *> r = (T4 ^^ Er) *> T4 *> (T4 ^^ (b - Er)) *> W_next *> r).
      { replace (b + 1) with (Er + (1 + (b - Er))) at 1 by lia. rewrite !pow_add_blank, zP1. reflexivity. }
      destruct (pipeL_eat_t4 Er (Nat.le_refl Er) hpL1 (T4 *> (T4 ^^ (b - Er)) *> W_next *> r)) as [Lt2 [hpL2 hs2]].
      replace (Er - Er) with 0 in hpL2 by lia.
      destruct (hWf1 W_next r) as [cfgf [hpef hsf]].
      exists cfgf. split; [exact hpef |].
      (try rewrite hT2s in hs0; rewrite ?Str_app_assoc in hs0; try rewrite hT2s; rewrite ?Str_app_assoc).
      eapply evstep_trans; [exact hs0 |].
      eapply evstep_trans; [exact hs1 |].
      rewrite hR. eapply evstep_trans; [exact hs2 |].
      change (T4 *> (T4 ^^ (b - Er)) *> W_next *> r) with ([S0; S1] *> T3 *> (T4 ^^ (b - Er)) *> W_next *> r).
      eapply evstep_trans; [exact (PipeL_unwind hpL2 (T3 *> (T4 ^^ (b - Er)) *> W_next *> r)) |].
      unfold encS in hsf; (try rewrite encSegTail_sp1 in hsf; rewrite ?app_nil_r in hsf; rewrite ?Str_app_assoc in hsf; try rewrite encSegTail_sp1; rewrite ?app_nil_r; rewrite ?Str_app_assoc). exact hsf.
Qed.

Lemma OneBlock_liftS2_park {W W' : list Sym} {e0 : nat} {es : list nat}
    (m b : nat) (hb : OneBlock W W' e0 es)
    (hge : m + 1 <= e0 + sumList es) (hlt : e0 + sumList es < m + b + 2) (r : Stream Sym) :
    (b0 {{E}}> (T2 *> T0 *> T1 *> (W ++ encS (2 * m + 1) false (b + 2) [] None) *> r)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *>
      (W' ++ encS (2 * m + 1) true (e0 + sumList es - (m + 1)) (sp1 (m + b + 1 - (e0 + sumList es))) None) *> r)).
Proof.
  destruct (oneBlock_posT2 hb ltac:(lia)) as [Wm [e1 [es1 [he1 [hsum [hp hP1]]]]]].
  assert (hT2s : encS (2 * m + 1) false (b + 2) [] None = T2 ++ ((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2)))).
  { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, list_pow_succ, append_assoc. reflexivity. }
  destruct (Compare_dec.le_dec e1 m) as [hlt_m | hgt_m].
  - destruct (hP1 ((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) r) as [cfg0 [hpe0 hs0]].
    assert (hpe0' : P1Entry e1 Wm ((T2 ^^ (2 * m + 1)) ++ (T4 ^^ (b + 2))) r cfg0).
    { rewrite t2_cons_pow in hpe0. exact hpe0. }
    pose proof (p1Entry_asplit_create (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) (2 * m + 1) he1 ltac:(lia) hpe0') as has.
    rewrite hT2s. eapply evstep_trans; [exact hs0 |].
    eapply evstep_trans; [exact has |].
    pose proof (PureP2_liftASplitH0Odd_park (2 * e1 - 1) (m - e1) b hp ltac:(lia) ltac:(lia) r) as hpk.
    replace (2 * e1 - 1 + 2 * (m - e1) + 2) with (2 * m + 1) in hpk by lia.
    replace (sumList es1 - (m - e1 + 1)) with (e0 + sumList es - (m + 1)) in hpk by lia.
    replace (m - e1 + b + 1 - sumList es1) with (m + b + 1 - (e0 + sumList es)) in hpk by lia.
    assert (hM : ((((Wm ++ (T2 ^^ (2 * e1 - 1))) ++ T0) ++ (T2 ^^ (2 * m + 1 - 2 * e1))) ++ (T4 ^^ (b + 2))) *> r =
                 (Wm ++ encS (2 * e1 - 1) false (b + 2) [] (Some (2 * (m - e1) + 1))) *> r).
    { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
      replace (2 * m + 1 - 2 * e1) with (2 * (m - e1) + 1) by lia. reflexivity. }
    rewrite hM. exact hpk.
  - set (Er := e1 - m - 1).
    destruct (hP1 ((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) r) as [cfg0 [hpe0 hs0]].
    assert (hpe0' : P1Entry e1 Wm (((T2 ^^ (2 * m + 1)) ++ (T4 ^^ (b + 2))) ++ []) r cfg0).
    { (try rewrite app_nil_r in hpe0; try rewrite t2_cons_pow in hpe0; try rewrite app_nil_r; try rewrite t2_cons_pow). exact hpe0. }
    replace (b + 2) with ((b + 1) + 1) in hpe0' by lia.
    destruct (p1Entry_eat_t2_odd_t4 (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) m (b + 1) ltac:(lia) hpe0') as [Lt1 [hpL1 hs1]].
    assert (hR : (T4 ^^ (b + 1)) *> [] *> r = (T4 ^^ Er) *> T4 *> (T4 ^^ (b - Er)) *> r).
    { rewrite zLan. replace (b + 1) with (Er + (1 + (b - Er))) at 1 by lia. rewrite !pow_add_blank, zP1. reflexivity. }
    destruct (pipeL_eat_t4 Er (Nat.le_refl Er) hpL1 (T4 *> (T4 ^^ (b - Er)) *> r)) as [Lt2 [hpL2 hs2]].
    replace (Er - Er) with 0 in hpL2 by lia.
    rewrite hT2s. eapply evstep_trans; [exact hs0 |].
    eapply evstep_trans; [exact hs1 |].
    rewrite hR. eapply evstep_trans; [exact hs2 |].
    change (T4 *> (T4 ^^ (b - Er)) *> r) with ([S0; S1] *> T3 *> (T4 ^^ (b - Er)) *> r).
    eapply evstep_trans; [exact (PipeL_unwind hpL2 (T3 *> (T4 ^^ (b - Er)) *> r)) |].
    pose proof (PureP2_lift2SegCell_dump (2 * m + 1) true Er (b - Er) hp (or_introl eq_refl) ltac:(lia) r) as hd.
    replace (Er + sumList es1) with (e0 + sumList es - (m + 1)) in hd by lia.
    replace (b - Er - sumList es1) with (m + b + 1 - (e0 + sumList es)) in hd by lia.
    assert (hM : (((Wm ++ (T2 ^^ (2 * m + 1))) ++ T5) ++ (T4 ^^ Er)) *> T3 *> (T4 ^^ (b - Er)) *> r =
                 (Wm ++ encS (2 * m + 1) true Er (sp1 (b - Er)) None) *> r).
    { unfold encS; rewrite encSegTail_sp1, ?app_nil_r, ?Str_app_assoc. reflexivity. }
    rewrite hM. exact hd.
Qed.

Lemma OneBlock_liftS0_2seg_dump {W W' : list Sym} {e0 : nat} {es : list nat}
    (m s0 s1 : nat) (hs0 : 2 <= s0) (hb : OneBlock W W' e0 es)
    (hge : m + 1 <= e0 + sumList es) (hle : e0 + sumList es - m <= s1) (r : Stream Sym) :
    (b0 {{E}}> (T2 *> T0 *> T1 *> (W ++ encS (2 * m + 1) true s0 (sp1 s1) None) *> r)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *>
      (W' ++ encS (2 * m + 2) true (s0 - 1 + (e0 + sumList es - m)) (sp1 (s1 - (e0 + sumList es - m))) None) *> r)).
Proof.
  set (s0' := s0 - 1).
  assert (hs0_eq : s0 = s0' + 1) by lia.
  destruct (OneBlock_liftS0 m s0' ltac:(lia) hb hge) as [es' [hp hsum]].
  pose proof (PureP2_lift2Seg_dump 0 s1 hp ltac:(lia) r) as hd.
  rewrite hs0_eq.
  assert (hL : (W ++ encS (2 * m + 1) true (s0' + 1) (sp1 s1) None) *> r =
               ((((W ++ encS (2 * m + 1) true (s0' + 1) [] None) ++ (T4 ^^ 0)) ++ T3) ++ (T4 ^^ s1)) *> r).
  { unfold encS; rewrite encSegTail_sp1; cbn [encSegTail]. rewrite list_pow_zero, ?app_nil_r, ?Str_app_assoc. reflexivity. }
  assert (hR : ((((W' ++ encS (2 * m + 2) true s0' [] None) ++ (T4 ^^ (0 + sumList es'))) ++ T3) ++ (T4 ^^ (s1 - sumList es'))) *> r =
               (W' ++ encS (2 * m + 2) true (s0' + (e0 + sumList es - m)) (sp1 (s1 - (e0 + sumList es - m))) None) *> r).
  { rewrite hsum. unfold encS; rewrite encSegTail_sp1; cbn [encSegTail].
    rewrite ?app_nil_r, ?Str_app_assoc, <- pow_add_blank.
    replace (0 + (e0 + sumList es - m)) with (e0 + sumList es - m) by lia.
    reflexivity. }
  rewrite hL, <- hR. exact hd.
Qed.

Lemma OneBlock_liftS0_2seg_heal {W W' : list Sym} {e0 : nat} {es : list nat}
    (m s0 s1 : nat) (hs0 : 2 <= s0) (hb : OneBlock W W' e0 es) (hge : m + s1 + 1 <= e0 + sumList es) :
    exists e0' es', OneBlock (W ++ encS (2 * m + 1) true s0 (sp1 s1) None)
        (W' ++ encS (2 * m + 2) true (s0 + s1) [] None) e0' es' /\
      e0' + sumList es' = e0 + sumList es - (m + s1 + 1).
Proof.
  set (s0' := s0 - 1).
  destruct (OneBlock_liftS0 m s0' ltac:(lia) hb ltac:(lia)) as [es' [hp hsum]].
  destruct (PureP2_lift2Seg_heal 0 s1 hp ltac:(lia)) as [e0' [es_out [hblk hsum']]].
  exists e0', es_out. split; [| lia].
  assert (hL : (((W ++ encS (2 * m + 1) true (s0' + 1) [] None) ++ (T4 ^^ 0)) ++ T3) ++ (T4 ^^ s1) =
               W ++ encS (2 * m + 1) true s0 (sp1 s1) None).
  { replace (s0' + 1) with s0 by lia.
    unfold encS; rewrite encSegTail_sp1; cbn [encSegTail]. rewrite list_pow_zero, ?app_nil_r, ?append_assoc. reflexivity. }
  assert (hR : (W' ++ encS (2 * m + 2) true s0' [] None) ++ (T4 ^^ (0 + s1 + 1)) =
               W' ++ encS (2 * m + 2) true (s0 + s1) [] None).
  { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc, ?list_pow_add_r, <- ?list_pow_add.
    replace (s0' + (0 + s1 + 1)) with (s0 + s1) by lia. reflexivity. }
  rewrite hL, hR in hblk. exact hblk.
Qed.

Lemma OneBlock_liftS1_2seg_heal {W W' : list Sym} {e0 : nat} {es : list nat}
    (m s0 s1 : nat) (hm : 1 <= m) (hs0 : 2 <= s0) (hb : OneBlock W W' e0 es)
    (hge : m + s1 + 1 <= e0 + sumList es) :
    exists e0' es', OneBlock (W ++ encS (2 * m) true s0 (sp1 s1) None)
        (W' ++ encS (2 * m + 1) false (s0 + s1 + 1) [] None) e0' es' /\
      e0' + sumList es' = e0 + sumList es - (m + s1 + 1).
Proof.
  set (s0' := s0 - 1).
  destruct (OneBlock_liftS1 m s0' hm ltac:(lia) hb ltac:(lia)) as [es' [hp hsum]].
  destruct (PureP2_lift2Seg_heal 0 s1 hp ltac:(lia)) as [e0' [es_out [hblk hsum']]].
  exists e0', es_out. split; [| lia].
  assert (hL : (((W ++ encS (2 * m) true (s0' + 1) [] None) ++ (T4 ^^ 0)) ++ T3) ++ (T4 ^^ s1) =
               W ++ encS (2 * m) true s0 (sp1 s1) None).
  { replace (s0' + 1) with s0 by lia.
    unfold encS; rewrite encSegTail_sp1; cbn [encSegTail]. rewrite list_pow_zero, ?app_nil_r, ?append_assoc. reflexivity. }
  assert (hR : (W' ++ encS (2 * m + 1) false (s0' + 1) [] None) ++ (T4 ^^ (0 + s1 + 1)) =
               W' ++ encS (2 * m + 1) false (s0 + s1 + 1) [] None).
  { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc, ?list_pow_add_r, <- ?list_pow_add.
    replace (s0' + 1 + (0 + s1 + 1)) with (s0 + s1 + 1) by lia. reflexivity. }
  rewrite hL, hR in hblk. exact hblk.
Qed.

Lemma c0_oneBlock (a0 : nat) (h0 : bool) (b0_v : nat)
    (hv : c0Valid_nat a0 h0 b0_v = true) (hpos : 1 <= c0E1_nat a0 h0 b0_v) :
    let '(a1, h1, b1) := c0Step1_nat a0 h0 b0_v in
    OneBlock (encS a0 h0 b0_v [] None) (encS a1 h1 b1 [] None) (c0E1_nat a0 h0 b0_v) [].
Proof.
  unfold c0Valid_nat, c0Step1_nat, c0E1_nat in hv, hpos |- *.
  destruct h0.
  - apply Bool.andb_true_iff in hv; destruct hv as [Ha Hb].
    apply Bool.andb_true_iff in Hb; destruct Hb as [Hm Hb].
    apply Nat.leb_le in Ha; apply Nat.eqb_eq in Hm; apply Nat.leb_le in Hb.
    pose proof (Nat.div_mod a0 2 ltac:(lia)).
    set (m := a0 / 2 - 1).
    set (b0q := b0_v - 1).
    exists (encS (a0 + 3) false b0_v [] None). split; [| exact (PureP2_nil _)].
    intros W_next r.
    destruct (pipeL_start_c0_h1 m b0q ltac:(lia) (W_next *> r)) as [Lt [hpL hs]].
    assert (hpL1 : PipeL1 (a0 / 2 - b0_v) (encS (a0 + 3) false b0_v [] None) Lt).
    { split; [| lia].
      replace (a0 / 2 - b0_v) with (m - b0q) by lia.
      eapply pipeL_eqR; [| exact hpL].
      unfold encS; cbn [encSegTail]. rewrite ?app_nil_r.
      replace (2 * m + 5) with (a0 + 3) by lia.
      replace (b0q + 1) with b0_v by lia. reflexivity. }
    exists (([S1; S1] *> Lt) {{F}}> (W_next *> r)). split.
    + left. exists Lt. split; [exact hpL1 | reflexivity].
    + unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
      replace a0 with (2 * m + 2) by lia.
      replace b0_v with (b0q + 1) by lia. exact hs.
  - apply Bool.andb_true_iff in hv; destruct hv as [Ha Hb].
    apply Bool.andb_true_iff in Hb; destruct Hb as [Hm Hb].
    apply Nat.leb_le in Ha; apply Nat.eqb_eq in Hm; apply Nat.leb_le in Hb.
    pose proof (Nat.div_mod a0 2 ltac:(lia)).
    set (m := a0 / 2).
    set (b0p := b0_v - 2).
    exists (encS (a0 + 3) true (b0_v - 2) [] None). split; [| exact (PureP2_nil _)].
    intros W_next r.
    destruct (pipeL_start_c0_h0 m b0p ltac:(lia) (W_next *> r)) as [Lt [hpL hs]].
    assert (hpL1 : PipeL1 (a0 / 2 + 2 - b0_v) (encS (a0 + 3) true (b0_v - 2) [] None) Lt).
    { split; [| lia].
      replace (a0 / 2 + 2 - b0_v) with (m - b0p) by lia.
      eapply pipeL_eqR; [| exact hpL].
      unfold encS; cbn [encSegTail]. rewrite ?app_nil_r.
      replace (2 * m + 4) with (a0 + 3) by lia. reflexivity. }
    exists (([S1; S1] *> Lt) {{F}}> (W_next *> r)). split.
    + left. exists Lt. split; [exact hpL1 | reflexivity].
    + unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?Str_app_assoc.
      replace a0 with (2 * m + 1) by lia.
      replace b0_v with (b0p + 2) by lia. exact hs.
Qed.

(* ========================================================================= *)
(* Section 11.1: CanRT5 Semigroup Sink Dump (NORM + TOK1 + Pair-Run)         *)
(* ========================================================================= *)

Lemma step_E_t4_to_Q5_local (l r : Stream Sym) :
  ((T4 *> T0 *> l) {{E}}> (T0 *> T2 *> r)) -[ tm ]->*
  (([S1; S1] *> T0 *> l) {{F}}> ([S0; S1] *> T5 *> r)).
Proof. execute. Qed.

Lemma rt5_cons_t5 {P_in P_out : list Sym} {tail : Stream Sym}
    (h : RoundTrip P_in P_out tail) :
    RoundTripQ5 (T5 ++ P_in) (T5 ++ P_out) tail.
Proof.
  intros k l.
  rewrite Str_app_assoc.
  destruct (t3_pow_t2_headZero k (T0 *> l)) as [l' hl'].
  assert (h1 : (((T3 ^^ k) *> T2 *> T0 *> l) {{C}}> (T1 *> T5 *> P_in *> tail)) -[ tm ]->*
               (((T3 ^^ k) *> T2 *> T0 *> l) {{E}}> (T0 *> T4 *> P_in *> tail))).
  { rewrite hl'. exact (step_C_1_t5_bounce l' (P_in *> tail)). }
  eapply evstep_trans; [exact h1 |].
  eapply evstep_trans; [exact (rule_E_t3 k ([S0; S1] *> T0 *> l) (T4 *> P_in *> tail)) |].
  eapply evstep_trans; [exact (step_E_t2_bounce (T0 *> l) ((T2 ^^ k) *> T4 *> P_in *> tail)) |].
  eapply evstep_trans; [exact (rule_C_1_t2 k (T3 *> T0 *> l) (T4 *> P_in *> tail)) |].
  rewrite zPal.
  eapply evstep_trans; [exact (step_C_1_t4_one ((T3 ^^ S k) *> T0 *> l) (P_in *> tail)) |].
  rewrite zPsr.
  assert (h63 : T6 *> T3 *> (T3 ^^ k) *> T0 *> l = T2 *> T4 *> (T3 ^^ k) *> T0 *> l).
  { rewrite <- Str_app_assoc, t6_t3_eq, Str_app_assoc. reflexivity. }
  rewrite h63.
  assert (h4head : T4 *> (T3 ^^ k) *> T0 *> l = T0 *> [S1; S0; S1; S1] *> (T3 ^^ k) *> T0 *> l) by reflexivity.
  assert (h3 : ((T2 *> T4 *> (T3 ^^ k) *> T0 *> l) {{C}}> (T1 *> P_in *> tail)) -[ tm ]->*
               ((T4 *> (T3 ^^ k) *> T0 *> l) {{E}}> (T0 *> T2 *> P_out *> tail))).
  { rewrite h4head. pose proof (h 0 ([S1; S0; S1; S1] *> (T3 ^^ k) *> T0 *> l)) as h0.
    rewrite zPz, zLan in h0. simpl Nat.add in h0. rewrite zP1 in h0. exact h0. }
  eapply evstep_trans; [exact h3 |].
  destruct k as [|k'].
  - rewrite ?zPz, ?zLan, Str_app_assoc. exact (step_E_t4_to_Q5_local l (P_out *> tail)).
  - assert (hhead3 : (T3 ^^ S k') *> T0 *> l = T0 *> [S1; S1] *> (T3 ^^ k') *> T0 *> l).
    { rewrite zPsr. reflexivity. }
    assert (h4 : ((T4 *> (T3 ^^ S k') *> T0 *> l) {{E}}> (T0 *> T2 *> P_out *> tail)) -[ tm ]->*
                 (((T3 ^^ S k') *> T0 *> l) {{E}}> (T0 *> T2 *> T5 *> P_out *> tail))).
    { rewrite hhead3. exact (step_E_t4_one ([S1; S1] *> (T3 ^^ k') *> T0 *> l) (P_out *> tail)). }
    eapply evstep_trans; [exact h4 |].
    replace (S k') with (k' + 1) at 1 by lia.
    eapply evstep_trans; [exact (rule_E_t3_to_Q5 k' l (T2 *> T5 *> P_out *> tail)) |].
    rewrite zPal, Str_app_assoc. apply evstep_refl.
Qed.

Definition CanRT5 (W : list Sym) (En : nat) (W' : list Sym) (tail : Stream Sym) : Prop :=
  exists f : nat -> list Sym,
    f 0 = W /\ f En = W' /\
    forall t, t < En -> RoundTripQ5 (f t) (f (t + 1)) tail.

Lemma CanRT5_zero (W : list Sym) (tail : Stream Sym) :
  CanRT5 W 0 W tail.
Proof.
  exists (fun _ : nat => W). split; [reflexivity | split; [reflexivity | intros _unused_t h; lia]].
Qed.

Lemma CanRT5_one {W W' : list Sym} {tail : Stream Sym}
    (h : RoundTripQ5 W W' tail) : CanRT5 W 1 W' tail.
Proof.
  exists (fun t => if Nat.eqb t 0 then W else W').
  split; [reflexivity | split; [reflexivity |]].
  intros t ht. assert (ht0 : t = 0) by lia. subst t. simpl. exact h.
Qed.

Lemma CanRT5_trans {W Wm W' : list Sym} {E1 E2 : nat} {tail : Stream Sym}
    (h1 : CanRT5 W E1 Wm tail) (h2 : CanRT5 Wm E2 W' tail) :
    CanRT5 W (E1 + E2) W' tail.
Proof.
  destruct h1 as [f1 [hf10 [hf1E hs1]]].
  destruct h2 as [f2 [hf20 [hf2E hs2]]].
  exists (fun t => if Nat.leb t E1 then f1 t else f2 (t - E1)).
  split.
  - assert (Hz : Nat.leb 0 E1 = true) by (apply Nat.leb_le; lia). rewrite Hz; exact hf10.
  - split.
    + destruct (Nat.eq_dec E2 0) as [h0 | hne].
      * subst E2. replace (E1 + 0) with E1 by lia.
        rewrite Nat.leb_refl, hf1E, <- hf20, hf2E. reflexivity.
      * assert (Hg : Nat.leb (E1 + E2) E1 = false) by (apply Nat.leb_gt; lia).
        rewrite Hg. replace (E1 + E2 - E1) with E2 by lia. exact hf2E.
    + intros t ht.
      destruct (Compare_dec.lt_dec t E1) as [hlt | hge].
      * assert (H1 : Nat.leb t E1 = true) by (apply Nat.leb_le; lia).
        assert (H2 : Nat.leb (t + 1) E1 = true) by (apply Nat.leb_le; lia).
        rewrite H1, H2. exact (hs1 t hlt).
      * destruct (Nat.eq_dec t E1) as [heq | hne].
        -- subst t. rewrite Nat.leb_refl.
           assert (H2 : Nat.leb (E1 + 1) E1 = false) by (apply Nat.leb_gt; lia).
           rewrite H2, hf1E, <- hf20.
           replace (E1 + 1 - E1) with 1 by lia. exact (hs2 0 ltac:(lia)).
        -- assert (H1 : Nat.leb t E1 = false) by (apply Nat.leb_gt; lia).
           assert (H2 : Nat.leb (t + 1) E1 = false) by (apply Nat.leb_gt; lia).
           rewrite H1, H2. replace (t + 1 - E1) with ((t - E1) + 1) by lia.
           exact (hs2 (t - E1) ltac:(lia)).
Qed.

Lemma CanRT5_appendSuffix {W W' S : list Sym} {En : nat} {tail : Stream Sym}
    (h : CanRT5 W En W' (S *> tail)) : CanRT5 (W ++ S) En (W' ++ S) tail.
Proof.
  destruct h as [f [hf0 [hfE hstep]]].
  exists (fun t => f t ++ S).
  split; [rewrite hf0; reflexivity | split; [rewrite hfE; reflexivity |]].
  intros t ht k l. rewrite ?Str_app_assoc. exact (hstep t ht k l).
Qed.

Lemma CanRT5_consT2 (n : nat) {W W' : list Sym} {En : nat} {tail : Stream Sym}
    (h : CanRT5 W En W' tail) : CanRT5 ((T2 ^^ n) ++ W) En ((T2 ^^ n) ++ W') tail.
Proof.
  destruct h as [f [hf0 [hfE hstep]]].
  exists (fun t => (T2 ^^ n) ++ f t).
  split; [rewrite hf0; reflexivity | split; [rewrite hfE; reflexivity |]].
  intros t ht. exact (rt5_cons_t2 n (hstep t ht)).
Qed.

Lemma CanRT5_consT5 {W W' : list Sym} {En : nat} {tail : Stream Sym}
    (h : CanRT5 W En W' tail) : CanRT5 (T5 ++ W) En (T5 ++ W') tail.
Proof.
  destruct h as [f [hf0 [hfE hstep]]].
  exists (fun t => T5 ++ f t).
  split; [rewrite hf0; reflexivity | split; [rewrite hfE; reflexivity |]].
  intros t ht. exact (rt5_cons_t5 (rt5_to_rt (hstep t ht))).
Qed.

Lemma CanRT5_consT4 (n : nat) {W W' : list Sym} {En : nat} {tail : Stream Sym}
    (h : CanRT5 W En W' tail) : CanRT5 ((T4 ^^ n) ++ W) En ((T4 ^^ n) ++ W') tail.
Proof.
  destruct h as [f [hf0 [hfE hstep]]].
  exists (fun t => (T4 ^^ n) ++ f t).
  split; [rewrite hf0; reflexivity | split; [rewrite hfE; reflexivity |]].
  intros t ht. exact (rt5_cons_t4 n (hstep t ht)).
Qed.

Lemma CanRT5_consCell11 (b : N) {W W' : list Sym} {En : nat} {tail : Stream Sym}
    (h : CanRT5 W En W' tail) :
    CanRT5 (encSingle 1%N true b [] None ++ W) En (encSingle 1%N true b [] None ++ W') tail.
Proof.
  pose proof (CanRT5_consT2 1 (CanRT5_consT5 (CanRT5_consT4 (N.to_nat b) h))) as h1.
  unfold encSingle; cbn [encSegTail]; simpl N.to_nat.
  (rewrite ?app_nil_r in h1; rewrite ?append_assoc in h1; rewrite ?app_nil_r; rewrite ?append_assoc). exact h1.
Qed.

Lemma CanRT5_consPairRun11_nat (b1 b2 : N) : forall (qn : nat) {W W' : list Sym} {En : nat} {tail : Stream Sym},
    CanRT5 W En W' tail ->
    CanRT5 (((encSingle 1%N true b1 [] None ++ encSingle 1%N true b2 [] None) ^^ qn) ++ W) En
      (((encSingle 1%N true b1 [] None ++ encSingle 1%N true b2 [] None) ^^ qn) ++ W') tail.
Proof.
  induction qn as [|k IH]; intros W W' En tail h.
  - rewrite !list_pow_zero, ?app_nil_l. exact h.
  - pose proof (CanRT5_consCell11 b1 (CanRT5_consCell11 b2 (IH _ _ _ _ h))) as h1.
    replace (S k) with (k + 1) by lia.
    (rewrite ?list_pow_succ in h1; rewrite ?append_assoc in h1; rewrite ?list_pow_succ; rewrite ?append_assoc). exact h1.
Qed.

Lemma CanRT5_consPairRun11 (b1 b2 q : N) {W W' : list Sym} {En : nat} {tail : Stream Sym}
    (h : CanRT5 W En W' tail) :
    CanRT5 (encItem (RIpairRun 1%N true b1 1%N true b2 q) ++ W) En
      (encItem (RIpairRun 1%N true b1 1%N true b2 q) ++ W') tail.
Proof.
  unfold encItem. exact (CanRT5_consPairRun11_nat b1 b2 (N.to_nat q) h).
Qed.

Lemma CanRT5_toCanDumpTail {W W' : list Sym} {En : nat} {tail : Stream Sym}
    (h : CanRT5 W En W' tail) : CanDumpTail W En W' tail.
Proof.
  destruct h as [f [hf0 [hfE hstep]]].
  exists f. split; [exact hf0 | split; [exact hfE |]].
  intros t e he hle R_out Lt hp.
  set (e' := e - 1).
  replace (e - 1) with e' in hp by lia.
  destruct (PipeL_head0 hp) as [l0 hl0].
  assert (h1 : (([S1] *> T2 *> Lt) {{A}}> (f t *> tail)) -[ tm ]->*
               (([S1; S1] *> Lt) {{F}}> ([S0; S1] *> f (t + 1) *> tail))).
  { rewrite hl0. pose proof (q0_t2_rt5 0 (hstep t ltac:(lia)) l0) as hq.
    rewrite zPz, zLan in hq. exact hq. }
  assert (hloop : forall k (t0 : nat) (Lk : Stream Sym),
    t0 + k <= En -> PipeL k R_out Lk ->
    (([S1; S1] *> Lk) {{F}}> ([S0; S1] *> f t0 *> tail)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *> (R_out ++ f (t0 + k)) *> tail))).
  { induction k as [|k' IH]; intros t0 Lk htk hpk.
    - replace (t0 + 0) with t0 by lia. rewrite Str_app_assoc. exact (PipeL_unwind hpk (f t0 *> tail)).
    - replace (S k') with (k' + 1) in hpk by lia.
      destruct (PipeL_pull hpk) as [L1 [hpull hp1]].
      destruct (PipeL_head0 hp1) as [l1 hl1].
      eapply evstep_trans; [exact (pull1_rt5 hl1 hpull (hstep t0 ltac:(lia))) |].
      pose proof (IH (t0 + 1) L1 ltac:(lia) hp1) as hrec.
      replace (t0 + 1 + k') with (t0 + S k') in hrec by lia. exact hrec. }
  eapply evstep_trans; [exact h1 |].
  pose proof (hloop e' (t + 1) Lt ltac:(lia) hp) as hfin.
  replace (t + 1 + e') with (t + e) in hfin by lia. exact hfin.
Qed.

Lemma rt5_wall4b_t4 (tail : Stream Sym) :
    RoundTripQ5 ((T1 ++ T4) ++ T4) ((T2 ++ T5) ++ T3) tail.
Proof.
  intros k l.
  assert (hIn : ((T1 ++ T4) ++ T4) *> tail = (T1 ++ T4) *> T0 *> [S1; S0; S1; S1] *> tail).
  { rewrite ?Str_app_assoc. reflexivity. }
  assert (hOut : (T2 ++ [S0; S1; S0]) *> T0 *> [S1; S0; S1; S1] *> tail = ((T2 ++ T5) ++ T3) *> tail).
  { rewrite ?Str_app_assoc. reflexivity. }
  rewrite hIn, <- hOut. exact (rt5_wall4b ([S1; S0; S1; S1] *> tail) k l).
Qed.

Lemma canRT5_wall1_n : forall (n : nat) (tail : Stream Sym),
    CanRT5 (T3 ++ (T4 ^^ n)) n ((T4 ^^ n) ++ T3) tail.
Proof.
  induction n as [|k IH]; intros tail.
  - rewrite !list_pow_zero, app_nil_r, app_nil_l. exact (CanRT5_zero T3 tail).
  - pose proof (CanRT5_appendSuffix (CanRT5_one (rt5_wall1 ((T4 ^^ k) *> tail)))) as h1.
    pose proof (CanRT5_consT4 1 (IH tail)) as h2.
    rewrite list_pow_one in h2.
    rewrite ?append_assoc in h1; rewrite ?append_assoc in h2.
    pose proof (CanRT5_trans h1 h2) as htr.
    replace (S k) with (1 + k) at 2 by lia.
    replace (S k) with (k + 1) by lia.
    rewrite !list_pow_succ, ?append_assoc. exact htr.
Qed.

Lemma canRT5_tok1_partial (k s_rem : nat) (tail : Stream Sym) :
    CanRT5 (T1 ++ (T4 ^^ (k + s_rem + 2))) (k + 1)
      ((((T2 ++ T5) ++ (T4 ^^ k)) ++ T3) ++ (T4 ^^ s_rem)) tail.
Proof.
  pose proof (CanRT5_appendSuffix (CanRT5_one (rt5_wall4b_t4 ((T4 ^^ (k + s_rem)) *> tail)))) as h1.
  pose proof (CanRT5_consT2 1 (CanRT5_consT5 (CanRT5_appendSuffix (canRT5_wall1_n k ((T4 ^^ s_rem) *> tail))))) as h2.
  rewrite list_pow_one in h2.
  assert (h1' : CanRT5 (T1 ++ (T4 ^^ (k + s_rem + 2))) 1
                  ((T2 ++ (T5 ++ (T3 ++ ((T4 ^^ k) ++ (T4 ^^ s_rem))))) ) tail).
  { replace (k + s_rem + 2) with (2 + (k + s_rem)) by lia.
    rewrite list_pow_add. change (T4 ^^ 2) with (T4 ++ (T4 ++ [])).
    rewrite app_nil_r, <- list_pow_add.
    (rewrite ?append_assoc in h1; rewrite ?append_assoc). exact h1. }
  (rewrite ?append_assoc in h2; rewrite ?append_assoc).
  replace (k + 1) with (1 + k) by lia.
  exact (CanRT5_trans h1' h2).
Qed.

Lemma canRT5_tok1_seg (v : N) (hv : (2 <= v)%N) (tail : Stream Sym) :
    CanRT5 ((T1 ++ (T4 ^^ N.to_nat v)) ++ T3) (N.to_nat v)
      (encSingle 1%N true (v - 1)%N [] None ++ T1) tail.
Proof.
  set (k := N.to_nat v - 2).
  pose proof (CanRT5_appendSuffix (canRT5_tok1_partial k 0 (T3 *> tail))) as h1.
  pose proof (CanRT5_consT2 1 (CanRT5_consT5 (CanRT5_consT4 k (CanRT5_one (rt5_wall4a tail))))) as h2.
  rewrite list_pow_one in h2. rewrite list_pow_zero, app_nil_r in h1.
  replace (k + 0 + 2) with (N.to_nat v) in h1 by lia.
  rewrite ?append_assoc in h1; rewrite ?append_assoc in h2.
  pose proof (CanRT5_trans h1 h2) as htr.
  replace (k + 1 + 1) with (N.to_nat v) in htr by lia.
  unfold encSingle; cbn [encSegTail]; simpl N.to_nat.
  replace (N.to_nat (v - 1)%N) with (k + 1) by lia.
  rewrite list_pow_succ_right, ?app_nil_r, ?append_assoc. exact htr.
Qed.

Lemma canRT5_tok1_pairRun_nat (v1 v2 : N) (hv1 : (2 <= v1)%N) (hv2 : (2 <= v2)%N) :
    forall (qn : nat) (tail : Stream Sym),
    CanRT5 (T1 ++ (((((T4 ^^ N.to_nat v1) ++ T3) ++ (T4 ^^ N.to_nat v2)) ++ T3) ^^ qn))
      (qn * (N.to_nat v1 + N.to_nat v2))
      (((encSingle 1%N true (v1 - 1)%N [] None ++ encSingle 1%N true (v2 - 1)%N [] None) ^^ qn) ++ T1) tail.
Proof.
  set (P := (((T4 ^^ N.to_nat v1) ++ T3) ++ (T4 ^^ N.to_nat v2)) ++ T3).
  induction qn as [|k IH]; intros tail.
  - simpl Nat.mul. rewrite !list_pow_zero, app_nil_r, app_nil_l. exact (CanRT5_zero T1 tail).
  - pose proof (CanRT5_appendSuffix (canRT5_tok1_seg v1 hv1 (((T4 ^^ N.to_nat v2) ++ (T3 ++ (P ^^ k))) *> tail))) as h1.
    pose proof (CanRT5_consCell11 (v1 - 1)%N
      (CanRT5_appendSuffix (canRT5_tok1_seg v2 hv2 ((P ^^ k) *> tail)))) as h2.
    pose proof (CanRT5_consCell11 (v1 - 1)%N (CanRT5_consCell11 (v2 - 1)%N (IH tail))) as h3.
    rewrite ?append_assoc in h1; rewrite ?append_assoc in h2; rewrite ?append_assoc in h3.
    pose proof (CanRT5_trans h1 (CanRT5_trans h2 h3)) as h123.
    replace (S k * (N.to_nat v1 + N.to_nat v2)) with
      (N.to_nat v1 + (N.to_nat v2 + k * (N.to_nat v1 + N.to_nat v2))) by nia.
    replace (S k) with (k + 1) by lia.
    rewrite !list_pow_succ. unfold P at 1. rewrite ?append_assoc. exact h123.
Qed.

Lemma canRT5_tok1_pairRun (v1 v2 q : N) (hv1 : (2 <= v1)%N) (hv2 : (2 <= v2)%N) (tail : Stream Sym) :
    CanRT5 (T1 ++ (((((T4 ^^ N.to_nat v1) ++ T3) ++ (T4 ^^ N.to_nat v2)) ++ T3) ^^ N.to_nat q))
      (N.to_nat (q * (v1 + v2))%N)
      (encItem (RIpairRun 1%N true (v1 - 1)%N 1%N true (v2 - 1)%N q) ++ T1) tail.
Proof.
  unfold encItem.
  replace (N.to_nat (q * (v1 + v2))%N) with (N.to_nat q * (N.to_nat v1 + N.to_nat v2)) by lia.
  exact (canRT5_tok1_pairRun_nat v1 v2 hv1 hv2 (N.to_nat q) tail).
Qed.

Lemma pow_cyclic_shift (u v : list Sym) : forall (q : nat),
    ((u ++ v) ^^ q) ++ u = u ++ ((v ++ u) ^^ q).
Proof.
  induction q as [|k IH].
  - rewrite !list_pow_zero, app_nil_l, app_nil_r. reflexivity.
  - replace (S k) with (k + 1) by lia.
    rewrite !list_pow_succ, ?append_assoc, IH, ?append_assoc. reflexivity.
Qed.

Fixpoint encT1Segs (segs : list SegPiece) : list Sym :=
  match segs with
  | [] => []
  | SPsingle s1 :: rest => (T4 ^^ N.to_nat s1) ++ encSegTail rest
  | SPpair v1 v2 rep :: rest =>
      if (rep =? 0)%N then encT1Segs rest
      else (((T4 ^^ N.to_nat v1) ++ T3) ++ (T4 ^^ N.to_nat v2)) ++
             encSegTail (SPpair v1 v2 (rep - 1)%N :: rest)
  end.

Lemma encSegTail_eq_t3_encT1Segs : forall {segs : list SegPiece},
    hasPosSeg segs = true -> encSegTail segs = T3 ++ encT1Segs segs.
Proof.
  induction segs as [|sp rest IH]; intros h.
  - cbn [hasPosSeg] in h; discriminate.
  - destruct sp as [s1 | v1 v2 rep].
    + cbn [encSegTail encT1Segs]. rewrite ?append_assoc. reflexivity.
    + cbn [encSegTail encT1Segs].
      destruct ((rep =? 0)%N) eqn:Hr0; split_andb.
      * subst rep. cbn [hasPosSeg] in h. simpl in h.
        simpl N.to_nat. rewrite list_pow_zero, app_nil_l. exact (IH h).
      * replace (N.to_nat rep) with (N.to_nat (rep - 1)%N + 1) by lia.
        rewrite list_pow_succ, ?append_assoc. reflexivity.
Qed.

Lemma encT1Segs_unpack {segs : list SegPiece} {s1 : N} {segRest : list SegPiece}
    (hu : unpackFrontSeg segs = Some (s1, segRest)) :
    encT1Segs segs = (T4 ^^ N.to_nat s1) ++ encSegTail segRest.
Proof.
  assert (hpos : hasPosSeg segs = true).
  { destruct segs as [|[? | v1 v2 rep] rest]; cbn [unpackFrontSeg] in hu; try discriminate.
    - reflexivity.
    - destruct ((1 <=? rep)%N) eqn:Hr; [cbn [hasPosSeg]; rewrite Hr; reflexivity | discriminate]. }
  pose proof (encSegTail_eq_t3_encT1Segs hpos) as h1.
  pose proof (unpackFrontSeg_sound hu) as h2.
  rewrite h1 in h2. rewrite ?append_assoc in h2.
  exact (app_cancel_left h2).
Qed.

Lemma encT1Segs_pair_split (v1 v2 q rem : N) (rest : list SegPiece)
    (hpos : hasPosSeg (SPpair v1 v2 rem :: rest) = true) :
    encT1Segs (SPpair v1 v2 (q + rem)%N :: rest) =
      (((((T4 ^^ N.to_nat v1) ++ T3) ++ (T4 ^^ N.to_nat v2)) ++ T3) ^^ N.to_nat q) ++
        encT1Segs (SPpair v1 v2 rem :: rest).
Proof.
  assert (hposQ : hasPosSeg (SPpair v1 v2 (q + rem)%N :: rest) = true).
  { cbn [hasPosSeg] in hpos |- *.
    apply Bool.orb_true_iff in hpos; apply Bool.orb_true_iff.
    destruct hpos as [Hr | Hrest]; [left; apply N.leb_le in Hr; apply N.leb_le; lia | right; exact Hrest]. }
  pose proof (eq_sym (encSegTail_eq_t3_encT1Segs hposQ)) as h1.
  assert (h2 : encSegTail (SPpair v1 v2 (q + rem)%N :: rest) =
               ((((T3 ++ (T4 ^^ N.to_nat v1)) ++ T3) ++ (T4 ^^ N.to_nat v2)) ^^ N.to_nat q) ++
                 encSegTail (SPpair v1 v2 rem :: rest)).
  { cbn [encSegTail]. replace (N.to_nat (q + rem)%N) with (N.to_nat q + N.to_nat rem) by lia.
    rewrite list_pow_add, ?append_assoc. reflexivity. }
  rewrite (encSegTail_eq_t3_encT1Segs hpos) in h2.
  pose proof (pow_cyclic_shift T3 (((T4 ^^ N.to_nat v1) ++ T3) ++ (T4 ^^ N.to_nat v2)) (N.to_nat q)) as h3.
  rewrite ?append_assoc in h1; rewrite ?append_assoc in h2; rewrite ?append_assoc in h3.
  assert (h4 : T3 ++ encT1Segs (SPpair v1 v2 (q + rem)%N :: rest) =
               T3 ++ ((((((T4 ^^ N.to_nat v1) ++ T3) ++ (T4 ^^ N.to_nat v2)) ++ T3) ^^ N.to_nat q) ++
                 encT1Segs (SPpair v1 v2 rem :: rest))).
  { rewrite h1, h2, <- (append_assoc _ T3 _), h3, ?append_assoc. reflexivity. }
  exact (app_cancel_left h4).
Qed.

Lemma dumpFromT1Aux_sound : forall (fuel : nat) (Ev : N) {segs : list SegPiece} {out : list RleItem}
    (tail : Stream Sym),
    dumpFromT1Aux fuel Ev segs = Some out ->
    CanRT5 (T1 ++ encT1Segs segs) (N.to_nat Ev) (encItems out) tail.
Proof.
  induction fuel as [|fuel' IH]; intros Ev segs out tail h.
  - cbn [dumpFromT1Aux] in h; discriminate.
  - cbn [dumpFromT1Aux] in h.
    destruct ((Ev =? 0)%N) eqn:hE0; split_andb.
    + subst Ev. simpl N.to_nat.
      destruct (unpackFrontSeg segs) as [[s1 rest]|] eqn:hu; [|discriminate].
      inversion h; subst out; clear h.
      rewrite (encT1Segs_unpack hu).
      assert (hEq : encItems [RIraw T_1 1%N; RIsingle 0%N false s1 rest None] =
                    T1 ++ ((T4 ^^ N.to_nat s1) ++ encSegTail rest)).
      { cbn [encItems]. unfold encItem, encTok, encSingle. simpl N.to_nat.
        rewrite list_pow_one, list_pow_zero, ?app_nil_l, ?app_nil_r, ?append_assoc. reflexivity. }
      rewrite hEq. exact (CanRT5_zero _ _).
    + destruct (matchPairSeg Ev segs) as [[[[v1 v2] q] segs']|] eqn:hpr.
      * destruct ((Ev - q * (v1 + v2) <? Ev)%N) eqn:hlt; [|discriminate]. split_andb.
        apply option_map_Some in h. destruct h as [out' [hout' hEqOut]]; subst out.
        destruct segs as [|[? | pv1 pv2 rep] rest]; cbn [matchPairSeg] in hpr; try discriminate.
        destruct (((2 <=? pv1)%N && (2 <=? pv2)%N && (1 <=? rep)%N && (pv1 + pv2 <=? Ev)%N)%bool) eqn:hcond;
          [|discriminate].
        split_andb.
        set (maxQ := if hasPosSeg rest then rep else (rep - 1)%N) in hpr.
        set (q0 := N.min (Ev / (pv1 + pv2))%N maxQ) in hpr.
        destruct ((1 <=? q0)%N) eqn:hq1; [|discriminate]. split_andb.
        inversion hpr; subst pv1 pv2 q segs'; clear hpr.
        assert (hq_div : (q0 <= Ev / (v1 + v2))%N) by apply N.le_min_l.
        assert (hq_max : (q0 <= maxQ)%N) by apply N.le_min_r.
        assert (hq_rep : (q0 <= rep)%N).
        { unfold maxQ in hq_max. destruct (hasPosSeg rest); lia. }
        assert (hqmul : (q0 * (v1 + v2) <= Ev)%N).
        { apply N.le_trans with (m := ((Ev / (v1 + v2)) * (v1 + v2))%N).
          - apply N.mul_le_mono_nonneg_r; lia.
          - exact (N_mul_div_le Ev (v1 + v2)). }
        assert (hposRem : hasPosSeg (SPpair v1 v2 (rep - q0)%N :: rest) = true).
        { cbn [hasPosSeg]. unfold maxQ in hq_max.
          destruct (hasPosSeg rest) eqn:hr.
          - rewrite Bool.orb_true_r. reflexivity.
          - assert (Hrem1 : (1 <=? rep - q0)%N = true) by (apply N.leb_le; lia).
            rewrite Hrem1. reflexivity. }
        set (segs_next := if (rep =? q0)%N then rest else SPpair v1 v2 (rep - q0)%N :: rest) in *.
        assert (hsegs'Eq : encT1Segs segs_next = encT1Segs (SPpair v1 v2 (rep - q0)%N :: rest)).
        { unfold segs_next. destruct ((rep =? q0)%N) eqn:heq; split_andb; [|reflexivity].
          unfold q0 in *; cbn [encT1Segs]. rewrite <- heq. replace (rep - rep)%N with 0%N by lia. reflexivity. }
        assert (hsplit : encT1Segs (SPpair v1 v2 rep :: rest) =
                         (((((T4 ^^ N.to_nat v1) ++ T3) ++ (T4 ^^ N.to_nat v2)) ++ T3) ^^ N.to_nat q0) ++
                           encT1Segs segs_next).
        { rewrite hsegs'Eq. replace rep with (q0 + (rep - q0))%N at 1 by lia.
          exact (encT1Segs_pair_split v1 v2 q0 (rep - q0)%N rest hposRem). }
        pose proof (CanRT5_appendSuffix (canRT5_tok1_pairRun v1 v2 q0 ltac:(lia) ltac:(lia) (encT1Segs segs_next *> tail))) as hstep1.
        pose proof (CanRT5_consPairRun11 (v1 - 1)%N (v2 - 1)%N q0 (IH (Ev - q0 * (v1 + v2))%N _ _ tail hout')) as hstep2.
        rewrite ?append_assoc in hstep1; rewrite ?append_assoc in hstep2.
        pose proof (CanRT5_trans hstep1 hstep2) as htr.
        replace (N.to_nat (q0 * (v1 + v2))%N + N.to_nat (Ev - q0 * (v1 + v2))%N) with (N.to_nat Ev) in htr by lia.
        rewrite hsplit. cbn [encItems]. rewrite ?append_assoc. exact htr.
      * destruct (unpackFrontSeg segs) as [[s1 segRest]|] eqn:hu; [|discriminate].
        destruct ((2 <=? s1)%N) eqn:hs1; [|discriminate]. split_andb.
        pose proof (encT1Segs_unpack hu) as hT1eq.
        destruct ((Ev <=? s1 - 1)%N) eqn:hEle; split_andb.
        -- inversion h; subst out; clear h.
           pose proof (CanRT5_appendSuffix (canRT5_tok1_partial (N.to_nat Ev - 1) (N.to_nat (s1 - 1 - Ev)%N) (encSegTail segRest *> tail))) as hpart.
           replace (N.to_nat Ev - 1 + N.to_nat (s1 - 1 - Ev)%N + 2) with (N.to_nat s1) in hpart by lia.
           replace (N.to_nat Ev - 1 + 1) with (N.to_nat Ev) in hpart by lia.
           rewrite hT1eq. cbn [encItems]. unfold encItem, encSingle; cbn [encSegTail]; simpl N.to_nat.
           replace (N.to_nat (Ev - 1)%N) with (N.to_nat Ev - 1) by lia.
           (try rewrite list_pow_one in hpart; rewrite ?app_nil_r in hpart; rewrite ?append_assoc in hpart; try rewrite list_pow_one; rewrite ?app_nil_r; rewrite ?append_assoc). exact hpart.
        -- destruct (hasPosSeg segRest) eqn:hposRest; [|discriminate].
           destruct ((Ev - s1 <? Ev)%N) eqn:hlt; [|discriminate]. split_andb.
           apply option_map_Some in h. destruct h as [out' [hout' hEqOut]]; subst out.
           pose proof (CanRT5_appendSuffix (canRT5_tok1_seg s1 ltac:(lia) (encT1Segs segRest *> tail))) as hstep1.
           pose proof (CanRT5_consCell11 (s1 - 1)%N (IH (Ev - s1)%N _ _ tail hout')) as hstep2.
           rewrite ?append_assoc in hstep1; rewrite ?append_assoc in hstep2.
           pose proof (CanRT5_trans hstep1 hstep2) as htr.
           replace (N.to_nat s1 + N.to_nat (Ev - s1)%N) with (N.to_nat Ev) in htr by lia.
           rewrite hT1eq, (encSegTail_eq_t3_encT1Segs hposRest).
           cbn [encItems]. unfold encItem at 1. rewrite ?append_assoc. exact htr.
Qed.

Lemma dumpFromT1_sound (Ev : N) {segs : list SegPiece} {out : list RleItem}
    (tail : Stream Sym) (h : dumpFromT1 Ev segs = Some out) :
    CanRT5 (T1 ++ encT1Segs segs) (N.to_nat Ev) (encItems out) tail.
Proof.
  unfold dumpFromT1 in h. exact (dumpFromT1Aux_sound _ Ev tail h).
Qed.

Lemma applySinkDumpBig_sound {Ev : N} : forall {items items' : list RleItem},
    applySinkDumpBig Ev items = Some items' ->
    CanDumpTail (encItems items) (N.to_nat Ev) (encItems items') ([S0; S1; S0; S1] *> b0).
Proof.
  induction items as [|x rest IH]; intros items' h; cbn [applySinkDumpBig] in h.
  - destruct ((Ev =? 0)%N) eqn:hE0; [|discriminate]. split_andb.
    subst Ev. inversion h; subst items'. simpl N.to_nat. exact (CanDumpTail_zero _ _).
  - destruct ((Ev =? 0)%N) eqn:hE0; split_andb.
    + subst Ev. inversion h; subst items'. simpl N.to_nat. exact (CanDumpTail_zero _ _).
    + destruct x as [a h0 s0 segTail aRight | a b rep | a1 h1 b1 a2 h2 b2 rep | tk cnt].
      * destruct aRight as [aR|].
        -- destruct (((h0 || (1 <=? s0)%N) && (2 * Ev <=? aR)%N)%bool) eqn:hcond; [|discriminate].
           apply Bool.andb_true_iff in hcond; destruct hcond as [h0s h2E].
           apply N.leb_le in h2E.
           assert (hok : h0 = true \/ 1 <= N.to_nat s0).
           { destruct h0; [left; reflexivity | right; simpl in h0s; apply N.leb_le in h0s; lia]. }
           inversion h; subst items'; clear h.
           pose proof (CanDumpTail_appendSuffix
             (canDumpTail_asplit (N.to_nat a) h0 (N.to_nat s0) segTail (N.to_nat aR) (N.to_nat Ev)
               hok ltac:(lia) (encItems rest *> [S0; S1; S0; S1] *> b0))) as hd.
           cbn [encItems]. unfold encItem. rewrite !encSingle_eq_encS. simpl option_map.
           change (match Ev with 0%N => 0%N | N.pos q => N.pos q~0 end) with (2 * Ev)%N.
           replace (N.to_nat (a + 2 * Ev)%N) with (N.to_nat a + 2 * N.to_nat Ev) by lia.
           replace (N.to_nat (aR - 2 * Ev)%N) with (N.to_nat aR - 2 * N.to_nat Ev) by lia.
           exact hd.
        -- destruct segTail as [|sp segRest0].
           ++ destruct rest as [|r1 rrest]; cbn [isEmpty] in h; simpl andb in h.
              ** destruct ((h0 || ((1 <=? a)%N && (1 <=? s0)%N))%bool) eqn:hcond; [|discriminate].
                 assert (hok : h0 = true \/ (1 <= N.to_nat a /\ 1 <= N.to_nat s0)).
                 { destruct h0; [left; reflexivity | right; simpl in hcond; split_andb; lia]. }
                 inversion h; subst items'; clear h.
                 cbn [encItems]. rewrite ?app_nil_r. unfold encItem. rewrite !encSingle_eq_encS; simpl option_map.
                 replace (N.to_nat (s0 + Ev)%N) with (N.to_nat s0 + N.to_nat Ev) by lia.
                 exact (canDumpTail_end (N.to_nat a) h0 (N.to_nat s0) (N.to_nat Ev) hok).
              ** destruct ((h0 || ((1 <=? a)%N && (1 <=? s0)%N))%bool) eqn:hcond; [|discriminate].
                 apply option_map_Some in h. destruct h as [ys [hys hEq]]; subst items'.
                 assert (hsk : isSkipP2List [RIsingle a h0 s0 [] None] = true).
                 { cbn [isSkipP2List List.forallb isSkipP2Item]. rewrite hcond. reflexivity. }
                 pose proof (CanDumpTail_skipPrefix hsk (IH _ hys)) as hd.
                 cbn [encItems] in hd |- *. rewrite ?app_nil_r in hd. exact hd.
           ++ cbn [isEmpty] in h; simpl andb in h.
              destruct (unpackFrontSeg (sp :: segRest0)) as [[s1 segRest]|] eqn:hu; [|discriminate].
              assert (hseg : encSingle a h0 s0 (sp :: segRest0) None =
                             encS (N.to_nat a) h0 (N.to_nat s0) (SPsingle (N.of_nat (N.to_nat s1)) :: segRest) None).
              { rewrite encSingle_eq_encS; simpl option_map. unfold encS.
                rewrite (unpackFrontSeg_sound hu). cbn [encSegTail]. rewrite Nat2N.id. reflexivity. }
              destruct ((Ev <=? s1)%N) eqn:hEs1; split_andb.
              ** destruct ((h0 || ((1 <=? a)%N && (1 <=? s0)%N))%bool) eqn:hcond; [|discriminate].
                 assert (hok : h0 = true \/ (1 <= N.to_nat a /\ 1 <= N.to_nat s0)).
                 { destruct h0; [left; reflexivity | right; simpl in hcond; split_andb; lia]. }
                 inversion h; subst items'; clear h.
                 pose proof (CanDumpTail_appendSuffix
                   (canDumpTail_wall1 (N.to_nat a) h0 (N.to_nat s0) (N.to_nat s1) segRest (N.to_nat Ev)
                     hok ltac:(lia) (encItems rest *> [S0; S1; S0; S1] *> b0))) as hd.
                 cbn [encItems]. unfold encItem at 1 2. rewrite hseg.
                 rewrite encSingle_eq_encS; simpl option_map.
                 replace (N.to_nat (s0 + Ev)%N) with (N.to_nat s0 + N.to_nat Ev) by lia.
                 replace (N.of_nat (N.to_nat s1 - N.to_nat Ev)) with (s1 - Ev)%N in hd by lia.
                 exact hd.
              ** destruct (((a =? 1)%N && h0 && hasPosSeg segRest)%bool) eqn:hcond; [|discriminate].
                 apply Bool.andb_true_iff in hcond; destruct hcond as [hah hposRest].
                 apply Bool.andb_true_iff in hah; destruct hah as [ha1 hh0].
                 apply N.eqb_eq in ha1; subst a h0.
                 apply option_map_Some in h. destruct h as [emitted [hem hEq]]; subst items'.
                 set (tail := encItems rest *> [S0; S1; S0; S1] *> b0).
                 pose proof (CanRT5_consT2 1 (CanRT5_consT5 (CanRT5_consT4 (N.to_nat s0)
                   (CanRT5_appendSuffix (canRT5_wall1_n (N.to_nat s1) ((T3 ++ encT1Segs segRest) *> tail)))))) as h1.
                 rewrite list_pow_one in h1.
                 pose proof (CanRT5_consT2 1 (CanRT5_consT5 (CanRT5_consT4 (N.to_nat s0 + N.to_nat s1)
                   (CanRT5_appendSuffix (CanRT5_one (rt5_wall4a (encT1Segs segRest *> tail))))))) as h2.
                 rewrite list_pow_one, list_pow_add in h2.
                 pose proof (CanRT5_consCell11 (s0 + s1 + 1)%N
                   (dumpFromT1_sound (Ev - (s1 + 1))%N tail hem)) as h3.
                 rewrite ?append_assoc in h1; rewrite ?append_assoc in h2.
                 pose proof (CanRT5_trans h1 h2) as h12.
                 assert (h3' : CanRT5 (T2 ++ (T5 ++ ((T4 ^^ N.to_nat s0) ++ ((T4 ^^ N.to_nat s1) ++ (T4 ++ (T1 ++ encT1Segs segRest))))))
                                 (N.to_nat (Ev - (s1 + 1))%N)
                                 (encSingle 1%N true (s0 + s1 + 1)%N [] None ++ encItems emitted) tail).
                 { unfold encSingle in h3 |- *; cbn [encSegTail] in h3 |- *.
                   replace (N.to_nat 1%N) with 1 in h3 |- * by lia.
                   replace (N.to_nat (s0 + s1 + 1)%N) with ((N.to_nat s0 + N.to_nat s1) + 1) in h3 |- * by lia.
                   rewrite list_pow_one, (list_pow_succ_right T4), list_pow_add, ?app_nil_r in h3 |- *.
                   repeat rewrite append_assoc in h3; repeat rewrite append_assoc.
                   exact h3. }
                 pose proof (CanRT5_trans h12 h3') as h123.
                 replace (N.to_nat s1 + 1 + N.to_nat (Ev - (s1 + 1))%N) with (N.to_nat Ev) in h123 by lia.
                 pose proof (CanDumpTail_appendSuffix (CanRT5_toCanDumpTail h123)) as hd.
                 assert (hL : encSingle 1%N true s0 (sp :: segRest0) None =
                              T2 ++ (T5 ++ ((T4 ^^ N.to_nat s0) ++ (T3 ++ ((T4 ^^ N.to_nat s1) ++ (T3 ++ encT1Segs segRest)))))).
                 { unfold encSingle; rewrite (unpackFrontSeg_sound hu), (encSegTail_eq_t3_encT1Segs hposRest).
                   simpl N.to_nat; rewrite list_pow_one, ?app_nil_r; repeat rewrite append_assoc. reflexivity. }
                 cbn [encItems]. unfold encItem at 1 2.
                 try rewrite hL in hd; try rewrite encItems_append in hd; repeat rewrite append_assoc in hd.
                 try rewrite hL; try rewrite encItems_append; repeat rewrite append_assoc.
                 exact hd.
      * destruct (isSkipP2Item (RItranspRun a b rep)) eqn:hsk; [|discriminate].
        apply option_map_Some in h. destruct h as [ys [hys hEq]]; subst items'.
        assert (hskL : isSkipP2List [RItranspRun a b rep] = true) by (cbn [isSkipP2List List.forallb]; rewrite hsk; reflexivity).
        pose proof (CanDumpTail_skipPrefix hskL (IH _ hys)) as hd.
        cbn [encItems] in hd |- *. rewrite app_nil_r in hd. exact hd.
      * destruct (isSkipP2Item (RIpairRun a1 h1 b1 a2 h2 b2 rep)) eqn:hsk; [|discriminate].
        apply option_map_Some in h. destruct h as [ys [hys hEq]]; subst items'.
        assert (hskL : isSkipP2List [RIpairRun a1 h1 b1 a2 h2 b2 rep] = true) by (cbn [isSkipP2List List.forallb]; rewrite hsk; reflexivity).
        pose proof (CanDumpTail_skipPrefix hskL (IH _ hys)) as hd.
        cbn [encItems] in hd |- *. rewrite app_nil_r in hd. exact hd.
      * destruct tk; try (cbn [isSkipP2Item] in h; discriminate).
        destruct ((cnt =? 1)%N) eqn:hcnt; [|discriminate]. split_andb; subst cnt.
        destruct rest as [|[a2 [|] s1 segRest [?|] | | |] rest']; try discriminate.
        destruct ((a2 =? 0)%N) eqn:ha2; [|discriminate]. split_andb; subst a2.
        apply option_map_Some in h. destruct h as [ys [hys hEq]]; subst items'.
        pose proof (CanDumpTail_appendSuffix
          (CanRT5_toCanDumpTail (dumpFromT1_sound Ev (encItems rest' *> [S0; S1; S0; S1] *> b0) hys))) as hd.
        cbn [encItems encT1Segs] in hd |- *. unfold encItem, encTok, encSingle; simpl N.to_nat.
        try rewrite list_pow_one in hd; try rewrite list_pow_zero in hd; repeat rewrite app_nil_l in hd; repeat rewrite app_nil_r in hd; try rewrite encItems_append in hd; repeat rewrite append_assoc in hd.
        try rewrite list_pow_one; try rewrite list_pow_zero; repeat rewrite app_nil_l; repeat rewrite app_nil_r; try rewrite encItems_append; repeat rewrite append_assoc.
        exact hd.
Qed.

(* --- ScratchS3B1.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

Lemma some_eq {A : Type} {x y : A} (h : Some x = Some y) : x = y.
Proof. exact (f_equal (fun o => match o with Some v => v | None => x end) h). Qed.

Lemma pair_eq {A B : Type} {a1 a2 : A} {b1 b2 : B} (h : (a1, b1) = (a2, b2)) : a1 = a2 /\ b1 = b2.
Proof. exact (conj (f_equal fst h) (f_equal snd h)). Qed.

Ltac inv_some H :=
  try apply some_eq in H;
  repeat match goal with
  | Hpq : (_, _) = (_, _) |- _ =>
      apply pair_eq in Hpq; cbn [fst snd] in Hpq; destruct Hpq
  end.


Ltac simp_sumList :=
  repeat match goal with
  | |- context [sumList (?a ++ ?b)] => rewrite (sumList_append a b)
  | H : context [sumList (?a ++ ?b)] |- _ => rewrite (sumList_append a b) in H
  end.

Ltac simp_len_app :=
  repeat match goal with
  | |- context [List.length (?a ++ ?b)] => rewrite (List.length_app a b)
  | H : context [List.length (?a ++ ?b)] |- _ => rewrite (List.length_app a b) in H
  end.

Ltac simp_encItems_app :=
  repeat match goal with
  | |- context [encItems (?a ++ ?b)] => rewrite (encItems_append a b)
  end.

Ltac simp_N2Nat :=
  repeat match goal with
  | |- context [N.to_nat (?a + ?b)%N] => rewrite (N2Nat.inj_add a b)
  | |- context [N.to_nat (?a * ?b)%N] => rewrite (N2Nat.inj_mul a b)
  | |- context [N.to_nat (?a - ?b)%N] => rewrite (N2Nat.inj_sub a b)
  end.

Ltac simp_pow_add :=
  repeat match goal with
  | |- context [(?w ^^ (?m + ?n)) *> ?b] => rewrite (pow_add_blank w m n b)
  | |- context [?w ^^ (?m + ?n)] => rewrite (list_pow_add w m n)
  end.

Ltac fold_pow_add :=
  repeat match goal with
  | |- context [(?u ^^ ?m) ++ ((?u ^^ ?n) ++ ?z)] => rewrite (list_pow_add_r u m n z)
  | |- context [(?u ^^ ?m) ++ (?u ^^ ?n)] => rewrite <- (list_pow_add u m n)
  end.

(* ========================================================================= *)
(* Section 11.2: BlockList, BlockStream, BlockLB, stepOdoRelay, stepOdoD0    *)
(* ========================================================================= *)

Lemma In_nth_zero : forall (bs : list nat) (x : nat),
  List.In x bs -> exists i, i < List.length bs /\ List.nth i bs 0 = x.
Proof.
  induction bs as [|b bs IH]; intros x hin; simpl in hin.
  - contradiction.
  - destruct hin as [<- | hin].
    + exists 0; simpl; split; [lia | reflexivity].
    + destruct (IH x hin) as [i [hi heq]].
      exists (S i); simpl; split; [lia | exact heq].
Qed.

Lemma nth_append_left : forall (l1 l2 : list nat) (i : nat),
  i < List.length l1 -> List.nth i (l1 ++ l2) 0 = List.nth i l1 0.
Proof.
  induction l1 as [|x l1 IH]; intros l2 i hi; simpl in hi; [lia |].
  destruct i as [|i]; simpl; [reflexivity | apply IH; lia].
Qed.

Lemma nth_append_right : forall (l1 l2 : list nat) (i : nat),
  List.length l1 <= i -> List.nth i (l1 ++ l2) 0 = List.nth (i - List.length l1) l2 0.
Proof.
  induction l1 as [|x l1 IH]; intros l2 i hle; simpl in hle |- *.
  - replace (i - 0) with i by lia; reflexivity.
  - destruct i as [|i]; [lia | apply IH; lia].
Qed.

Lemma nth_map_sub : forall (bs : list nat) (c i : nat),
  List.nth i (List.map (fun x => x - c) bs) 0 = List.nth i bs 0 - c.
Proof.
  induction bs as [|b bs IH]; intros c i; destruct i as [|i]; simpl; try lia; apply IH.
Qed.

Lemma N_pow3_of_nat (k : nat) : N.to_nat (3 ^ N.of_nat k)%N = Nat.pow 3 k.
Proof.
  induction k as [|k IH].
  - reflexivity.
  - replace (N.of_nat (S k)) with (1 + N.of_nat k)%N by lia.
    rewrite N.pow_add_r. simpl (3 ^ 1)%N. simpl (Nat.pow 3 (S k)). lia.
Qed.

Inductive BlockList : list Sym -> list Sym -> list nat -> Prop :=
  | BlockList_nil (W : list Sym) : BlockList W W []
  | BlockList_cons {W W1 W' : list Sym} {e0 : nat} {es bs : list nat}
      (hb : OneBlock W W1 e0 es) (hrest : BlockList W1 W' bs) :
      BlockList W W' ((e0 + sumList es) :: bs).

Definition BlockStream (W W' : list Sym) (p2_pre : nat) (bs : list nat) : Prop :=
  exists Wm es_pre, PureP2 W Wm es_pre /\ sumList es_pre = p2_pre /\ BlockList Wm W' bs.

Lemma BlockStream_nil (W : list Sym) : BlockStream W W 0 [].
Proof.
  exists W, (@nil nat). split; [exact (PureP2_nil W) | split; [reflexivity | exact (BlockList_nil W)]].
Qed.

Lemma BlockStream_consPureP2 {W0 W1 W' : list Sym} {es : list nat} {p2 : nat} {bs : list nat}
    (hp : PureP2 W0 W1 es) (h : BlockStream W1 W' p2 bs) :
    BlockStream W0 W' (sumList es + p2) bs.
Proof.
  destruct h as [Wm [es_pre [hp_pre [hsum hbl]]]].
  exists Wm, (es ++ es_pre).
  split; [exact (PureP2_append hp hp_pre) |].
  split; [rewrite sumList_append, hsum; reflexivity | exact hbl].
Qed.

Lemma BlockStream_consBlock {W0 W1 W' : list Sym} {e0 : nat} {es : list nat} {p2 : nat} {bs : list nat}
    (hb : OneBlock W0 W1 e0 es) (h : BlockStream W1 W' p2 bs) :
    BlockStream W0 W' 0 ((e0 + sumList es + p2) :: bs).
Proof.
  destruct h as [Wm [es_pre [hp_pre [hsum hbl]]]].
  exists W0, (@nil nat). split; [exact (PureP2_nil W0) | split; [reflexivity |]].
  pose proof (BlockList_cons (OneBlock_appendP2 hb hp_pre) hbl) as hc.
  rewrite sumList_append, hsum, Nat.add_assoc in hc.
  exact hc.
Qed.

Lemma BlockList_append {W1 W2 W3 : list Sym} {bs1 bs2 : list nat}
    (h1 : BlockList W1 W2 bs1) (h2 : BlockList W2 W3 bs2) :
    BlockList W1 W3 (bs1 ++ bs2).
Proof.
  induction h1 as [W0 | W0 Wa Wb e0 es bs hb _ IH].
  - exact h2.
  - simpl. exact (BlockList_cons hb (IH h2)).
Qed.

Lemma BlockList_liftTranspList {W W' : list Sym} {bs : list nat} (xs : list RleItem)
    (hxs : isTranspList xs = true) (hbl : BlockList W W' bs) :
    (forall b, List.In b bs -> transpListCost_nat xs <= b) ->
    BlockList (W ++ encItems xs) (W' ++ encItems xs) (List.map (fun b => b - transpListCost_nat xs) bs).
Proof.
  induction hbl as [W0 | W0 W1 W2 e0 es bs' hb hrest IH]; intros hge.
  - simpl. exact (BlockList_nil _).
  - assert (hge0 : transpListCost_nat xs <= e0 + sumList es).
    { apply hge; simpl; left; reflexivity. }
    assert (hgeRest : forall b, List.In b bs' -> transpListCost_nat xs <= b).
    { intros b hm; apply hge; simpl; right; exact hm. }
    destruct (OneBlock_liftTranspList xs hxs hb hge0) as [e0' [es' [hb' hsum']]].
    simpl List.map. rewrite <- hsum'.
    exact (BlockList_cons hb' (IH hgeRest)).
Qed.

Lemma BlockStream_liftTranspList {W W' : list Sym} {p2 : nat} {bs : list nat} (xs : list RleItem)
    (hxs : isTranspList xs = true) (h : BlockStream W W' p2 bs)
    (hge : forall b, List.In b bs -> transpListCost_nat xs <= b) :
    BlockStream (W ++ encItems xs) (W' ++ encItems xs) p2 (List.map (fun b => b - transpListCost_nat xs) bs).
Proof.
  destruct h as [Wm [es_pre [hp [hsum hbl]]]].
  exists (Wm ++ encItems xs), es_pre.
  split; [exact (PureP2_liftTranspList xs hxs hp) |].
  split; [exact hsum | exact (BlockList_liftTranspList xs hxs hbl hge)].
Qed.

Lemma BlockStream_toPureP2 {W W' : list Sym} {p2 : nat}
    (h : BlockStream W W' p2 []) :
    exists es, PureP2 W W' es /\ sumList es = p2.
Proof.
  destruct h as [Wm [es_pre [hp [hsum hbl]]]].
  inversion hbl; subst.
  exists es_pre; split; (assumption || reflexivity).
Qed.

Lemma BlockStream_dumpNil {W W' S S' : list Sym} {p2 : nat} {tail : Stream Sym}
    (h : BlockStream W W' p2 []) (hd : CanDumpTail S p2 S' tail) :
    (b0 {{E}}> (T2 *> T0 *> T1 *> (W ++ S) *> tail)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *> (W' ++ S') *> tail)).
Proof.
  destruct (BlockStream_toPureP2 h) as [es [hp hsum]].
  subst p2. exact (PureP2_dump hp hd).
Qed.

Definition BlockLB (bs : list nat) (B D B_last : nat) : Prop :=
  forall i, i < List.length bs ->
    (if Nat.eqb (i + 1) (List.length bs) then B_last else B + D * i) <= List.nth i bs 0.

Lemma BlockLB_mem_ge {bs : list nat} {B D B_last c : nat}
    (hlb : BlockLB bs B D B_last) (hB : c <= B) (hLast : c <= B_last) :
    forall b, List.In b bs -> c <= b.
Proof.
  intros b hb.
  destruct (In_nth_zero bs b hb) as [i [hi heq]].
  subst b. specialize (hlb i hi).
  destruct (Nat.eqb (i + 1) (List.length bs)); lia.
Qed.

Lemma BlockLB_map_sub {bs : list nat} {B D B_last c : nat}
    (hlb : BlockLB bs B D B_last) (hB : c <= B) (hLast : c <= B_last) :
    BlockLB (List.map (fun b => b - c) bs) (B - c) D (B_last - c).
Proof.
  intros i hi. rewrite ?List.length_map in hi; rewrite ?List.length_map.
  rewrite nth_map_sub. specialize (hlb i hi).
  destruct (Nat.eqb (i + 1) (List.length bs)); lia.
Qed.

Lemma list_len_mul_le_sum : forall (bs : list nat) (c : nat),
  (forall b, List.In b bs -> c <= b) -> List.length bs * c <= sumList bs.
Proof.
  induction bs as [|y ys IH]; intros c hge; simpl; [lia |].
  assert (hy : c <= y) by (apply hge; simpl; left; reflexivity).
  assert (hys : List.length ys * c <= sumList ys).
  { apply IH. intros b hm; apply hge; simpl; right; exact hm. }
  lia.
Qed.

Lemma sum_map_sub : forall (bs : list nat) (c : nat),
  (forall b, List.In b bs -> c <= b) ->
  sumList (List.map (fun b => b - c) bs) = sumList bs - List.length bs * c.
Proof.
  induction bs as [|x xs IH]; intros c hge; simpl; [lia |].
  assert (hx : c <= x) by (apply hge; simpl; left; reflexivity).
  assert (hxs : forall b, List.In b xs -> c <= b) by (intros b hm; apply hge; simpl; right; exact hm).
  pose proof (list_len_mul_le_sum xs c hxs) as hle.
  rewrite (IH c hxs). lia.
Qed.

Lemma c0_blockList : forall (Nv a0 : nat) (h0 : bool) (b0_v : nat),
  c0Valid_nat a0 h0 b0_v = true ->
  Nv + (if h0 then 4 else 5) <= b0_v ->
  b0_v + 1 <= a0 / 2 ->
  let '(aN, hN, bN) := c0StepN_nat a0 h0 b0_v Nv in
  exists bs, BlockList (encS a0 h0 b0_v [] None) (encS aN hN bN [] None) bs /\
    List.length bs = Nv /\
    sumList bs = c0TotalIn_nat a0 h0 b0_v Nv /\
    BlockLB bs (c0E1_nat a0 h0 b0_v) 2 (c0E1_nat a0 h0 b0_v + 2 * (Nv - 1)).
Proof.
  induction Nv as [|n IH]; intros a0 h0 b0_v hv hb he.
  - rewrite c0StepN_zero, c0TotalIn_zero.
    exists (@nil nat). split; [exact (BlockList_nil _) |].
    split; [reflexivity | split; [reflexivity | intros i hi; simpl in hi; lia]].
  - assert (hpos : 1 <= c0E1_nat a0 h0 b0_v).
    { unfold c0E1_nat; destruct h0; lia. }
    pose proof (c0_oneBlock a0 h0 b0_v hv hpos) as hb1.
    pose proof (c0Valid_step1 hv ltac:(destruct h0; lia)) as hv1.
    pose proof (c0E1_step1_ge hv ltac:(lia)) as hge1.
    pose proof (c0StepN_succ a0 h0 b0_v n) as hst.
    pose proof (@c0TotalIn_succ a0 h0 b0_v n hv ltac:(lia)) as htot.
    replace (S n) with (n + 1) by lia.
    destruct (c0Step1_nat a0 h0 b0_v) as [[a1 h1] b1] eqn:Hc1.
    assert (hbb1 : n + (if h1 then 4 else 5) <= b1).
    { unfold c0Step1_nat in Hc1. destruct h0; inversion Hc1; subst; lia. }
    assert (he1 : b1 + 1 <= a1 / 2).
    { unfold c0Step1_nat in Hc1.
      destruct h0; inversion Hc1; subst.
      - pose proof (Nat.Div0.div_le_mono a0 (a0 + 3) 2 ltac:(lia)); lia.
      - pose proof (Nat.Div0.div_le_mono a0 (a0 + 3) 2 ltac:(lia)); lia. }
    rewrite hst, htot.
    specialize (IH a1 h1 b1 hv1 hbb1 he1).
    destruct (c0StepN_nat a1 h1 b1 n) as [[aN hN] bN].
    destruct IH as [bs' [hbl' [hlen' [hsum' hlb']]]].
    exists (c0E1_nat a0 h0 b0_v :: bs').
    split.
    + pose proof (BlockList_cons hb1 hbl') as hc.
      simpl sumList in hc. rewrite Nat.add_0_r in hc. exact hc.
    + split; [simpl; lia |].
      split; [simpl; lia |].
      intros i hi; cbn [List.length List.nth] in hi |- *.
      destruct i as [|j].
      * change (0 + 1) with 1.
        destruct (Nat.eqb 1 (S (List.length bs'))) eqn:He1;
          [apply Nat.eqb_eq in He1 | apply Nat.eqb_neq in He1]; lia.
      * specialize (hlb' j ltac:(lia)).
        replace (S j + 1) with (S (j + 1)) by lia.
        change (Nat.eqb (S (j + 1)) (S (List.length bs'))) with (Nat.eqb (j + 1) (List.length bs')).
        destruct (Nat.eqb (j + 1) (List.length bs')) eqn:Hej;
          [apply Nat.eqb_eq in Hej | apply Nat.eqb_neq in Hej]; lia.
Qed.

Lemma c0_blockStream (a0 : nat) (h0 : bool) (b0_v Nv : nat)
    (hv : c0Valid_nat a0 h0 b0_v = true)
    (hb : Nv + (if h0 then 4 else 5) <= b0_v)
    (he : b0_v + 1 <= a0 / 2) :
    let '(aN, hN, bN) := c0StepN_nat a0 h0 b0_v Nv in
    exists bs, BlockStream (encS a0 h0 b0_v [] None) (encS aN hN bN [] None) 0 bs /\
      List.length bs = Nv /\
      sumList bs = c0TotalIn_nat a0 h0 b0_v Nv /\
      BlockLB bs (c0E1_nat a0 h0 b0_v) 2 (c0E1_nat a0 h0 b0_v + 2 * (Nv - 1)).
Proof.
  pose proof (c0_blockList Nv a0 h0 b0_v hv hb he) as H.
  destruct (c0StepN_nat a0 h0 b0_v Nv) as [[aN hN] bN].
  destruct H as [bs [hbl [hlen [hsum hlb]]]].
  exists bs. split; [| split; [exact hlen | split; [exact hsum | exact hlb]]].
  exists (encS a0 h0 b0_v [] None), (@nil nat).
  split; [exact (PureP2_nil _) | split; [reflexivity | exact hbl]].
Qed.

Lemma OneBlock_prependStep {W0 W1 W2 : list Sym} {e0 : nat} {es : list nat}
    (hstep : forall r : Stream Sym,
      (b0 {{E}}> (T2 *> T0 *> T1 *> W0 *> r)) -[ tm ]->*
      (b0 {{E}}> (T2 *> T0 *> T1 *> W1 *> r)))
    (hb : OneBlock W1 W2 e0 es) : OneBlock W0 W2 e0 es.
Proof.
  destruct hb as [Wm [hp1 hpp]].
  exists Wm. split; [| exact hpp].
  intros W_next r.
  destruct (hp1 W_next r) as [cfg [hpe hs]].
  exists cfg. split; [exact hpe |].
  rewrite Str_app_assoc. rewrite Str_app_assoc in hs.
  exact (stepStar_trans (hstep (W_next *> r)) hs).
Qed.

Lemma liftDigitCycle {W0 W1 W2 W3 : list Sym} {e0_1 e0_2 e0_3 : nat} {es_1 es_2 es_3 : list nat}
    (m b : nat) (hb2_pos : 2 <= b)
    (hb1 : OneBlock W0 W1 e0_1 es_1)
    (hb2 : OneBlock W1 W2 e0_2 es_2)
    (hb3 : OneBlock W2 W3 e0_3 es_3)
    (hE1 : m + 3 <= e0_1 + sumList es_1)
    (hE2 : m + 1 <= e0_2 + sumList es_2)
    (hE3 : m + 2 <= e0_3 + sumList es_3)
    (hTot : 3 * m + b + 3 <= (e0_1 + sumList es_1) + (e0_2 + sumList es_2) + (e0_3 + sumList es_3)) :
    exists e0' es', OneBlock (W0 ++ encS (2 * m + 1) false (b + 2) [] None)
        (W3 ++ encS (2 * m + 3) false b [] None) e0' es' /\
      e0' + sumList es' = (e0_1 + sumList es_1) + (e0_2 + sumList es_2) + (e0_3 + sumList es_3) - (3 * m + b + 3).
Proof.
  set (E1 := e0_1 + sumList es_1) in *.
  set (E2 := e0_2 + sumList es_2) in *.
  set (E3 := e0_3 + sumList es_3) in *.
  destruct (OneBlock_liftS1 (m + 1) (b - 1) ltac:(lia) ltac:(lia) hb3 ltac:(lia)) as [es3 [hp3 hsum3]].
  replace (2 * (m + 1)) with (2 * m + 2) in hp3 by lia.
  replace (2 * m + 2 + 1) with (2 * m + 3) in hp3 by lia.
  replace (b - 1 + 1) with b in hp3 by lia.
  destruct (Nat.leb (m + b + 2) E1) eqn:HA.
  - apply Nat.leb_le in HA.
    destruct (OneBlock_liftS2 m b hb1 HA) as [e1' [es1' [hb1' hsum1']]].
    destruct (OneBlock_liftS0 m b ltac:(lia) hb2 hE2) as [es2 [hp2 hsum2]].
    exists e1', ((es1' ++ es2) ++ es3).
    split; [exact (OneBlock_appendP2 (OneBlock_appendP2 hb1' hp2) hp3) |].
    simp_sumList; lia.
  - apply Nat.leb_gt in HA.
    set (s0 := E1 - (m + 1)).
    set (s1 := m + b + 1 - E1).
    assert (hpark1 : forall r : Stream Sym,
      (b0 {{E}}> (T2 *> T0 *> T1 *> (W0 ++ encS (2 * m + 1) false (b + 2) [] None) *> r)) -[ tm ]->*
      (b0 {{E}}> (T2 *> T0 *> T1 *> (W1 ++ encS (2 * m + 1) true s0 (sp1 s1) None) *> r))).
    { intros r. pose proof (OneBlock_liftS2_park m b hb1 ltac:(lia) HA r) as hp.
      exact hp. }
    destruct (Nat.leb (2 * m + b + 2) (E1 + E2)) eqn:HB.
    + apply Nat.leb_le in HB.
      destruct (OneBlock_liftS0_2seg_heal m s0 s1 ltac:(unfold s0; lia) hb2 ltac:(unfold s1; lia))
        as [e2' [es2' [hb2' hsum2']]].
      replace (s0 + s1) with b in hb2' by (unfold s0, s1; lia).
      exists e2', (es2' ++ es3).
      split; [exact (OneBlock_appendP2 (OneBlock_prependStep hpark1 hb2') hp3) |].
      rewrite sumList_append; unfold s1 in hsum2'; lia.
    + apply Nat.leb_gt in HB.
      set (s0' := s0 - 1 + (E2 - m)).
      set (s1' := s1 - (E2 - m)).
      assert (hdump2 : forall r : Stream Sym,
        (b0 {{E}}> (T2 *> T0 *> T1 *> (W1 ++ encS (2 * m + 1) true s0 (sp1 s1) None) *> r)) -[ tm ]->*
        (b0 {{E}}> (T2 *> T0 *> T1 *> (W2 ++ encS (2 * m + 2) true s0' (sp1 s1') None) *> r))).
      { intros r. exact (OneBlock_liftS0_2seg_dump m s0 s1 ltac:(unfold s0; lia) hb2 hE2 ltac:(unfold s1; lia) r). }
      destruct (OneBlock_liftS1_2seg_heal (m + 1) s0' s1' ltac:(lia) ltac:(unfold s0', s0; lia) hb3
                  ltac:(unfold s1', s1; lia)) as [e3' [es3' [hb3' hsum3']]].
      replace (2 * (m + 1)) with (2 * m + 2) in hb3' by lia.
      replace (2 * m + 2 + 1) with (2 * m + 3) in hb3' by lia.
      replace (s0' + s1' + 1) with b in hb3' by (unfold s0', s1', s0, s1; lia).
      exists e3', es3'.
      split; [exact (OneBlock_prependStep (fun r => stepStar_trans (hpark1 r) (hdump2 r)) hb3') |].
      unfold s1', s1 in hsum3'; lia.
Qed.

Lemma liftDigit2Tail {W0 W1 W2 : list Sym} {e0_1 e0_2 : nat} {es_1 es_2 : list nat}
    (m b : nat) (hb2_pos : 2 <= b)
    (hb1 : OneBlock W0 W1 e0_1 es_1)
    (hb2 : OneBlock W1 W2 e0_2 es_2)
    (hE1 : m + 3 <= e0_1 + sumList es_1)
    (hE2 : m + 1 <= e0_2 + sumList es_2)
    (hTot : 2 * m + b + 2 <= (e0_1 + sumList es_1) + (e0_2 + sumList es_2)) :
    exists e0' es', OneBlock (W0 ++ encS (2 * m + 1) false (b + 2) [] None)
        (W2 ++ encS (2 * m + 2) true b [] None) e0' es' /\
      e0' + sumList es' = (e0_1 + sumList es_1) + (e0_2 + sumList es_2) - (2 * m + b + 2).
Proof.
  set (E1 := e0_1 + sumList es_1) in *.
  set (E2 := e0_2 + sumList es_2) in *.
  destruct (Nat.leb (m + b + 2) E1) eqn:HA.
  - apply Nat.leb_le in HA.
    destruct (OneBlock_liftS2 m b hb1 HA) as [e1' [es1' [hb1' hsum1']]].
    destruct (OneBlock_liftS0 m b ltac:(lia) hb2 hE2) as [es2 [hp2 hsum2]].
    exists e1', (es1' ++ es2).
    split; [exact (OneBlock_appendP2 hb1' hp2) | rewrite sumList_append; lia].
  - apply Nat.leb_gt in HA.
    set (s0 := E1 - (m + 1)).
    set (s1 := m + b + 1 - E1).
    assert (hpark1 : forall r : Stream Sym,
      (b0 {{E}}> (T2 *> T0 *> T1 *> (W0 ++ encS (2 * m + 1) false (b + 2) [] None) *> r)) -[ tm ]->*
      (b0 {{E}}> (T2 *> T0 *> T1 *> (W1 ++ encS (2 * m + 1) true s0 (sp1 s1) None) *> r))).
    { intros r. exact (OneBlock_liftS2_park m b hb1 ltac:(lia) HA r). }
    destruct (OneBlock_liftS0_2seg_heal m s0 s1 ltac:(unfold s0; lia) hb2 ltac:(unfold s1; lia))
      as [e2' [es2' [hb2' hsum2']]].
    replace (s0 + s1) with b in hb2' by (unfold s0, s1; lia).
    exists e2', es2'.
    split; [exact (OneBlock_prependStep hpark1 hb2') | unfold s1 in hsum2'; lia].
Qed.

Lemma BlockLB_drop3 {x1 x2 x3 : nat} {l : list nat} {B D B_last : nat}
    (hlb : BlockLB (x1 :: x2 :: x3 :: l) B D B_last) :
    BlockLB l (B + 3 * D) D B_last.
Proof.
  intros i hi.
  specialize (hlb (S (S (S i))) ltac:(simpl; lia)).
  simpl List.nth in hlb. simpl List.length in hlb.
  replace (Nat.eqb (S (S (S i)) + 1) (S (S (S (List.length l)))))
    with (Nat.eqb (i + 1) (List.length l)) in hlb by reflexivity.
  destruct (Nat.eqb (i + 1) (List.length l)); lia.
Qed.

Lemma digCycleCost_s2_one (m0 b0 : nat) :
  digCycleCost_nat (2 * m0 + 1) false b0 1 = 3 * m0 + b0 + 1.
Proof.
  unfold digCycleCost_nat. simpl (false && _)%bool.
  replace ((2 * m0 + 1) / 2) with m0 by lia.
  simpl ((1 * (1 - 1)) / 2). lia.
Qed.

Lemma digCycleCost_s2_le_sum (D B_last : nat) (hD : 1 <= D) :
  forall (r m0 b0 B0 : nat) (l : list nat),
    List.length l = 3 * r -> 2 * r + 2 <= b0 -> BlockLB l B0 D B_last ->
    (r <= 1 \/ 3 * m0 + b0 + 1 <= 3 * B0 + 3 * D) ->
    (r = 0 \/ 3 * m0 + b0 + r <= 2 * B0 + D * (6 * r - 5) + B_last) ->
    digCycleCost_nat (2 * m0 + 1) false b0 r <= sumList l.
Proof.
  induction r as [|r' IH]; intros m0 b0 B0 l hl hb0 hlb0 hc0 ht0.
  - unfold digCycleCost_nat; simpl; lia.
  - destruct l as [|x1 [|x2 [|x3 l3]]]; simpl in hl; try lia.
    simpl sumList.
    assert (hx1 : B0 <= x1).
    { specialize (hlb0 0 ltac:(simpl; lia)). simpl in hlb0. lia. }
    assert (hx2 : B0 + D <= x2).
    { specialize (hlb0 1 ltac:(simpl; lia)). simpl in hlb0. lia. }
    destruct r' as [|r''].
    + destruct l3; [| simpl in hl; lia].
      assert (hx3 : B_last <= x3).
      { specialize (hlb0 2 ltac:(simpl; lia)). simpl in hlb0. lia. }
      rewrite digCycleCost_s2_one. simpl sumList. lia.
    + assert (hx3 : B0 + 2 * D <= x3).
      { specialize (hlb0 2 ltac:(simpl; lia)). cbn [List.length List.nth] in hlb0.
        change (2 + 1) with 3 in hlb0.
        destruct (Nat.eqb 3 (S (S (S (List.length l3))))) eqn:He3;
          [apply Nat.eqb_eq in He3; simpl in hl; lia | lia]. }
      pose proof (BlockLB_drop3 hlb0) as hlb3.
      assert (ht3 : S r'' = 0 \/ 3 * (m0 + 1) + (b0 - 2) + S r'' <= 2 * (B0 + 3 * D) + D * (6 * S r'' - 5) + B_last).
      { right. assert (h6 : D * (6 * S (S r'') - 5) = 6 * D + D * (6 * S r'' - 5)).
        { replace (6 * S (S r'') - 5) with (6 + (6 * S r'' - 5)) by lia. lia. }
        lia. }
      pose proof (IH (m0 + 1) (b0 - 2) (B0 + 3 * D) l3 ltac:(lia) ltac:(lia) hlb3 ltac:(lia) ht3) as hrec.
      replace (S (S r'')) with (S r'' + 1) by lia.
      rewrite (digCycleCost_succ (2 * m0 + 1) false b0 (S r'') ltac:(lia)), digCycleCost_s2_one.
      replace (2 * m0 + 1 + 2) with (2 * (m0 + 1) + 1) by lia. lia.
Qed.

Lemma BlockList_liftCyclesS2 (D : nat) (hD : 1 <= D) :
  forall (Qv : nat) {W W' : list Sym} {bs : list nat} (m b B B_last : nat),
    BlockList W W' bs -> List.length bs = 3 * Qv ->
    2 * Qv + 2 <= b -> BlockLB bs B D B_last ->
    m + 3 <= B ->
    (Qv = 0 \/ m + Qv + 1 <= B_last) ->
    (Qv <= 1 \/ 3 * m + b + 1 <= 3 * B + 3 * D) ->
    (Qv = 0 \/ 3 * m + b + Qv <= 2 * B + D * (6 * Qv - 5) + B_last) ->
    exists bs', BlockList (W ++ encS (2 * m + 1) false b [] None)
        (W' ++ encS (2 * (m + Qv) + 1) false (b - 2 * Qv) [] None) bs' /\
      List.length bs' = Qv /\
      sumList bs' = sumList bs - digCycleCost_nat (2 * m + 1) false b Qv /\
      BlockLB bs' (3 * B + 3 * D - (3 * m + b + 1)) (9 * D - 1)
        (2 * B + D * (6 * Qv - 5) + B_last - (3 * m + b + Qv)).
Proof.
  induction Qv as [|q IH]; intros W W' bs m b B B_last hbl hlen hb hlb hB hLast hCyc hTail.
  - inversion hbl; subst; [| simpl in hlen; lia].
    replace (m + 0) with m by lia. replace (b - 2 * 0) with b by lia.
    exists (@nil nat). split; [exact (BlockList_nil _) |].
    split; [reflexivity | split; [unfold digCycleCost_nat; simpl; lia | intros i hi; simpl in hi; lia]].
  - inversion hbl as [| W_0 W1 W_a e1 es1 bs1 hb1 hbl1]; subst; [simpl in hlen; lia |].
    inversion hbl1 as [| W_1 W2 W_b e2 es2 bs2 hb2 hbl2]; subst; [simpl in hlen; lia |].
    inversion hbl2 as [| W_2 W3 W_c e3 es3 bs_rest hb3 hbl3]; subst; [simpl in hlen; lia |].
    set (E1 := e1 + sumList es1) in *.
    set (E2 := e2 + sumList es2) in *.
    set (E3 := e3 + sumList es3) in *.
    simpl List.length in hlen.
    assert (hlenR : List.length bs_rest = 3 * q) by lia.
    assert (hE1_lb : B <= E1).
    { specialize (hlb 0 ltac:(simpl; lia)); simpl in hlb; lia. }
    assert (hE2_lb : B + D <= E2).
    { specialize (hlb 1 ltac:(simpl; lia)); simpl in hlb; lia. }
    destruct q as [|q'].
    + inversion hbl3; subst; [| simpl in hlenR; lia].
      assert (hE3_lb : B_last <= E3).
      { specialize (hlb 2 ltac:(simpl; lia)); simpl in hlb; lia. }
      destruct (liftDigitCycle m (b - 2) ltac:(lia) hb1 hb2 hb3 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia))
        as [e0' [es' [hbc hsumc]]].
      replace (b - 2 + 2) with b in hbc by lia.
      replace (2 * (m + 1) + 1) with (2 * m + 3) by lia.
      replace (b - 2 * 1) with (b - 2) by lia.
      exists [e0' + sumList es'].
      split; [exact (BlockList_cons hbc (BlockList_nil _)) |].
      split; [reflexivity |].
      split; [rewrite digCycleCost_s2_one; simpl sumList; lia |].
      intros i hi; simpl in hi |- *; assert (i = 0) by lia; subst i; simpl; lia.
    + assert (hE3_lb : B + 2 * D <= E3).
      { specialize (hlb 2 ltac:(simpl; lia)); cbn [List.length List.nth] in hlb.
        change (2 + 1) with 3 in hlb.
        destruct (Nat.eqb 3 (S (S (S (List.length bs_rest))))) eqn:He3;
          [apply Nat.eqb_eq in He3; simpl in hlenR; lia | lia]. }
      destruct (liftDigitCycle m (b - 2) ltac:(lia) hb1 hb2 hb3 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia))
        as [e0' [es' [hbc hsumc]]].
      replace (b - 2 + 2) with b in hbc by lia.
      pose proof (BlockLB_drop3 hlb) as hlbR.
      assert (h6 : D * (6 * S (S q') - 5) = 6 * D + D * (6 * S q' - 5)).
      { replace (6 * S (S q') - 5) with (6 + (6 * S q' - 5)) by lia; lia. }
      assert (hTailR : S q' = 0 \/ 3 * (m + 1) + (b - 2) + S q' <= 2 * (B + 3 * D) + D * (6 * S q' - 5) + B_last)
        by lia.
      destruct (IH W3 W' bs_rest (m + 1) (b - 2) (B + 3 * D) B_last hbl3 hlenR ltac:(lia) hlbR
                  ltac:(lia) ltac:(lia) ltac:(lia) hTailR)
        as [bsR [hblR [hlenR' [hsumR' hlbR']]]].
      replace (2 * (m + 1) + 1) with (2 * m + 3) in hblR, hsumR' by lia.
      replace (2 * (m + 1 + S q') + 1) with (2 * (m + S (S q')) + 1) in hblR by lia.
      replace (b - 2 - 2 * S q') with (b - 2 * S (S q')) in hblR by lia.
      pose proof (digCycleCost_s2_le_sum D B_last hD (S q') (m + 1) (b - 2) (B + 3 * D) bs_rest hlenR
                    ltac:(lia) hlbR ltac:(lia) hTailR) as hgeR.
      replace (2 * (m + 1) + 1) with (2 * m + 3) in hgeR by lia.
      assert (hdc_succ : digCycleCost_nat (2 * m + 1) false b (S (S q')) =
                         (3 * m + b + 1) + digCycleCost_nat (2 * m + 3) false (b - 2) (S q')).
      { replace (S (S q')) with (S q' + 1) by lia.
        rewrite (digCycleCost_succ (2 * m + 1) false b (S q') ltac:(lia)), digCycleCost_s2_one.
        replace (2 * m + 1 + 2) with (2 * m + 3) by lia. reflexivity. }
      exists ((e0' + sumList es') :: bsR).
      split; [exact (BlockList_cons hbc hblR) |].
      split; [simpl; lia |].
      split; [simpl sumList; lia |].
      intros i hi; cbn [List.length List.nth] in hi |- *.
      destruct i as [|j].
      * change (0 + 1) with 1.
        assert (H : Nat.eqb 1 (S (List.length bsR)) = false) by (apply Nat.eqb_neq; lia).
        rewrite H; lia.
      * specialize (hlbR' j ltac:(lia)).
        replace (S j + 1) with (S (j + 1)) by lia.
        change (Nat.eqb (S (j + 1)) (S (List.length bsR))) with (Nat.eqb (j + 1) (List.length bsR)).
        destruct (Nat.eqb (j + 1) (List.length bsR)) eqn:Hej; [lia |].
        replace ((9 * D - 1) * S j) with ((9 * D - 1) * j + (9 * D - 1)) by lia.
        lia.
Qed.

Lemma BlockList_liftCyclesAllAffine (D : nat) (hD : 1 <= D) :
  forall (q : nat) {W W' : list Sym} {bs : list nat} (m b B : nat),
    BlockList W W' bs -> List.length bs = 3 * q ->
    2 * q + 2 <= b ->
    (forall i, i < List.length bs -> B + D * i <= List.nth i bs 0) ->
    m + 3 <= B ->
    (q = 0 \/ 3 * m + b + 1 <= 3 * B + 3 * D) ->
    exists bs', BlockList (W ++ encS (2 * m + 1) false b [] None)
        (W' ++ encS (2 * (m + q) + 1) false (b - 2 * q) [] None) bs' /\
      List.length bs' = q /\
      sumList bs' = sumList bs - digCycleCost_nat (2 * m + 1) false b q /\
      digCycleCost_nat (2 * m + 1) false b q <= sumList bs /\
      (forall i, i < List.length bs' -> (3 * B + 3 * D - (3 * m + b + 1)) + (9 * D - 1) * i <= List.nth i bs' 0).
Proof.
  induction q as [|q' IH]; intros W W' bs m b B hbl hlen hb hlb hB hCyc.
  - inversion hbl; subst; [| simpl in hlen; lia].
    replace (m + 0) with m by lia. replace (b - 2 * 0) with b by lia.
    exists (@nil nat). split; [exact (BlockList_nil _) |].
    split; [reflexivity | split; [unfold digCycleCost_nat; simpl; lia |
      split; [unfold digCycleCost_nat; simpl; lia | intros i hi; simpl in hi; lia]]].
  - inversion hbl as [| W_0 W1 W_a e1 es1 bs1 hb1 hbl1]; subst; [simpl in hlen; lia |].
    inversion hbl1 as [| W_1 W2 W_b e2 es2 bs2 hb2 hbl2]; subst; [simpl in hlen; lia |].
    inversion hbl2 as [| W_2 W3 W_c e3 es3 bs_rest hb3 hbl3]; subst; [simpl in hlen; lia |].
    set (E1 := e1 + sumList es1) in *.
    set (E2 := e2 + sumList es2) in *.
    set (E3 := e3 + sumList es3) in *.
    simpl List.length in hlen.
    assert (hE1_lb : B <= E1) by (specialize (hlb 0 ltac:(simpl; lia)); simpl in hlb; lia).
    assert (hE2_lb : B + D <= E2) by (specialize (hlb 1 ltac:(simpl; lia)); simpl in hlb; lia).
    assert (hE3_lb : B + 2 * D <= E3) by (specialize (hlb 2 ltac:(simpl; lia)); simpl in hlb; lia).
    destruct (liftDigitCycle m (b - 2) ltac:(lia) hb1 hb2 hb3 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia))
      as [e0' [es' [hbc hsumc]]].
    replace (b - 2 + 2) with b in hbc by lia.
    assert (hlbR : forall i, i < List.length bs_rest -> (B + 3 * D) + D * i <= List.nth i bs_rest 0).
    { intros i hi. specialize (hlb (S (S (S i))) ltac:(simpl; lia)). simpl in hlb. lia. }
    destruct (IH W3 W' bs_rest (m + 1) (b - 2) (B + 3 * D) hbl3 ltac:(lia) ltac:(lia) hlbR ltac:(lia) ltac:(lia))
      as [bsR [hblR [hlenR [hsumR [hgeR hlbR']]]]].
    replace (2 * (m + 1) + 1) with (2 * m + 3) in hblR, hsumR, hgeR by lia.
    replace (2 * (m + 1 + q') + 1) with (2 * (m + S q') + 1) in hblR by lia.
    replace (b - 2 - 2 * q') with (b - 2 * S q') in hblR by lia.
    assert (hcs : digCycleCost_nat (2 * m + 1) false b (S q') =
                  (3 * m + b + 1) + digCycleCost_nat (2 * m + 3) false (b - 2) q').
    { replace (S q') with (q' + 1) by lia.
      rewrite (digCycleCost_succ (2 * m + 1) false b q' ltac:(lia)), digCycleCost_s2_one.
      replace (2 * m + 1 + 2) with (2 * m + 3) by lia. reflexivity. }
    exists ((e0' + sumList es') :: bsR).
    split; [exact (BlockList_cons hbc hblR) |].
    split; [simpl; lia |].
    split; [simpl sumList; lia |].
    split; [simpl sumList; lia |].
    intros i hi; simpl in hi |- *.
    destruct i as [|j]; [simpl; lia |].
    specialize (hlbR' j ltac:(lia)).
    replace ((9 * D - 1) * S j) with ((9 * D - 1) * j + (9 * D - 1)) by lia.
    lia.
Qed.

Lemma BlockList_splitAt : forall (n : nat) {W W' : list Sym} {bs : list nat},
  BlockList W W' bs -> n <= List.length bs ->
  exists Wm bs1 bs2, bs = bs1 ++ bs2 /\ List.length bs1 = n /\ BlockList W Wm bs1 /\ BlockList Wm W' bs2.
Proof.
  induction n as [|n' IH]; intros W W' bs hbl hle.
  - exists W, (@nil nat), bs. split; [reflexivity | split; [reflexivity | split; [exact (BlockList_nil W) | exact hbl]]].
  - inversion hbl as [| W0 W1 W2 e0 es bs' hb hrest]; subst; [simpl in hle; lia |].
    simpl in hle.
    destruct (IH W1 W' bs' hrest ltac:(lia)) as [Wm [bs1 [bs2 [heq [hlen1 [hbl1 hbl2]]]]]].
    exists Wm, ((e0 + sumList es) :: bs1), bs2.
    split; [simpl; rewrite heq; reflexivity |].
    split; [simpl; lia | split; [exact (BlockList_cons hb hbl1) | exact hbl2]].
Qed.

Lemma tri_succ_div2 (q : nat) : ((q + 1) * q) / 2 = q + (q * (q - 1)) / 2.
Proof.
  destruct q as [|q']; [reflexivity |].
  replace (S q' - 1) with q' by lia.
  pose proof (Nat.div_mod (S q' * q') 2 ltac:(lia)) as H1.
  pose proof (Nat.mod_upper_bound (S q' * q') 2 ltac:(lia)) as H2.
  pose proof (Nat.div_mod ((S q' + 1) * S q') 2 ltac:(lia)) as H3.
  pose proof (Nat.mod_upper_bound ((S q' + 1) * S q') 2 ltac:(lia)) as H4.
  nia.
Qed.

Lemma liftDigitRelay_s0 {W Wm W' : list Sym} {es_pre bs : list nat} {p2 : nat}
    (m b Qv B D B_last : nat)
    (hp_pre : PureP2 W Wm es_pre) (hsum_pre : sumList es_pre = p2)
    (hbl : BlockList Wm W' bs) (hlen : List.length bs = 3 * Qv) (hlb : BlockLB bs B D B_last)
    (hQpos : 1 <= Qv) (hb2Q : 2 * Qv + 2 <= b) (hD1 : 1 <= D)
    (hB : m + 1 <= B) (hBD : m + 2 <= B + D) (hB2D : m + 4 <= B + 2 * D)
    (hCyc : Qv <= 1 \/ 3 * m + b + 3 <= 3 * B + 9 * D)
    (hLast : m + Qv + (b - 2 * Qv + 1) + 1 <= B_last) :
    exists p2' bs', BlockStream (W ++ encS (2 * m + 1) true b [] None)
        (W' ++ encS (2 * m + 1 + 2 * Qv) true (b - 2 * Qv) [] None) p2' bs' /\
      List.length bs' = Qv /\
      p2' + sumList bs' = p2 + sumList bs - digCycleCost_nat (2 * m + 1) true b Qv /\
      digCycleCost_nat (2 * m + 1) true b Qv <= sumList bs /\
      BlockLB bs' (3 * B + 9 * D - (3 * m + b + 3)) (9 * D - 1) (B_last - (m + Qv + (b - 2 * Qv + 1))).
Proof.
  revert hsum_pre.
  inversion hbl as [| W_0 W1 W_a e0 es0 bs1 hb0 hbl1]; subst; [simpl in hlen; lia |].
  inversion hbl1 as [| W_1 W2 W_b e1 es1 bs2 hb1 hbl2]; subst; [simpl in hlen; lia |].
  intros hsum_pre.
  simpl List.length in hlen.
  set (E0 := e0 + sumList es0) in *.
  set (E1 := e1 + sumList es1) in *.
  assert (hE0_lb : B <= E0).
  { specialize (hlb 0 ltac:(simpl; lia)); cbn [List.length List.nth] in hlb.
    change (0 + 1) with 1 in hlb.
    destruct (Nat.eqb 1 (S (S (List.length bs2)))) eqn:He0;
      [apply Nat.eqb_eq in He0; lia | lia]. }
  assert (hE1_lb : B + D <= E1).
  { specialize (hlb 1 ltac:(simpl; lia)); cbn [List.length List.nth] in hlb.
    change (1 + 1) with 2 in hlb.
    destruct (Nat.eqb 2 (S (S (List.length bs2)))) eqn:He1;
      [apply Nat.eqb_eq in He1; lia | lia]. }
  destruct (OneBlock_liftS0 m (b - 1) ltac:(lia) hb0 ltac:(lia)) as [es0' [hp0 hsum0]].
  replace (b - 1 + 1) with b in hp0 by lia.
  destruct (OneBlock_liftS1 (m + 1) (b - 2) ltac:(lia) ltac:(lia) hb1 ltac:(lia)) as [es1' [hp1 hsum1]].
  replace (2 * (m + 1)) with (2 * m + 2) in hp1 by lia.
  replace (2 * m + 2 + 1) with (2 * m + 3) in hp1 by lia.
  replace (b - 2 + 1) with (b - 1) in hp1 by lia.
  destruct (BlockList_splitAt (3 * (Qv - 1)) hbl2 ltac:(lia))
    as [Wmid [bsM [bsL [hbs2Eq [hlenM [hblM hblL]]]]]].
  assert (hlenL : List.length bsL = 1).
  { pose proof (f_equal (@List.length nat) hbs2Eq) as Hlen; rewrite List.length_app in Hlen; lia. }
  revert hbs2Eq hsum_pre.
  inversion hblL as [| W_m W_l W_e eL esL bsEnd hbLast hblEnd]; subst; [simpl in hlenL; lia |].
  inversion hblEnd; subst; [| simpl in hlenL; lia].
  intros hbs2Eq hsum_pre.
  set (EL := eL + sumList esL) in *.
  assert (hEL_lb : B_last <= EL).
  { specialize (hlb (3 * Qv - 1) ltac:(simpl; lia)).
    replace (Nat.eqb (3 * Qv - 1 + 1) (List.length (E0 :: E1 :: bs2))) with true in hlb
      by (symmetry; apply Nat.eqb_eq; simpl; lia).
    replace (3 * Qv - 1) with (S (S (3 * (Qv - 1)))) in hlb by lia.
    cbn [List.nth] in hlb. rewrite hbs2Eq, nth_append_right in hlb by lia.
    replace (3 * (Qv - 1) - List.length bsM) with 0 in hlb by lia. cbn [List.nth] in hlb; exact hlb. }
  assert (hlbM : forall i, i < List.length bsM -> (B + 2 * D) + D * i <= List.nth i bsM 0).
  { intros i hi. specialize (hlb (S (S i)) ltac:(simpl; lia)).
    cbn [List.nth List.length] in hlb.
    assert (HeqF : Nat.eqb (S (S i) + 1) (S (S (List.length bs2))) = false) by (apply Nat.eqb_neq; lia).
    rewrite HeqF in hlb. rewrite hbs2Eq, nth_append_left in hlb by lia. lia. }
  destruct (BlockList_liftCyclesAllAffine D hD1 (Qv - 1) (m + 1) (b - 1) (B + 2 * D)
              hblM hlenM ltac:(lia) hlbM ltac:(lia) ltac:(lia))
    as [bsC [hblC [hlenC [hsumC [hgeC hlbC]]]]].
  destruct (OneBlock_liftS2 (m + Qv) (b - 2 * Qv - 1) hbLast ltac:(lia))
    as [eL' [esL' [hbL' hsumL']]].
  fold EL in hsumL'.
  replace (2 * (m + 1) + 1) with (2 * m + 3) in hblC by lia.
  replace (2 * (m + 1 + (Qv - 1)) + 1) with (2 * (m + Qv) + 1) in hblC by lia.
  replace (b - 1 - 2 * (Qv - 1)) with ((b - 2 * Qv - 1) + 2) in hblC by lia.
  replace (b - 2 * Qv - 1 + 1) with (b - 2 * Qv) in hbL' by lia.
  pose proof (BlockList_append hblC (BlockList_cons hbL' (BlockList_nil _))) as hblFull.
  replace (2 * (m + Qv) + 1) with (2 * m + 1 + 2 * Qv) in hblFull by lia.
  pose proof (PureP2_append (PureP2_liftCell (2 * m + 1) true b (or_introl eq_refl) ltac:(lia) hp_pre)
                            (PureP2_append hp0 hp1)) as hpAll.
  assert (hcostEq : digCycleCost_nat (2 * m + 1) true b Qv =
                    m + (m + 1) + digCycleCost_nat (2 * (m + 1) + 1) false (b - 1) (Qv - 1) +
                    (m + Qv + (b - 2 * Qv - 1) + 2)).
  { clear - hQpos hb2Q. unfold digCycleCost_nat.
    replace ((2 * m + 1) mod 2) with 1 by lia.
    replace ((2 * m + 1) / 2) with m by lia.
    replace ((2 * (m + 1) + 1) / 2) with (m + 1) by lia.
    simpl (true && Nat.eqb 1 0)%bool. simpl (false && _)%bool.
    set (q := Qv - 1). replace Qv with (q + 1) by lia.
    replace (q + 1 - 1) with q by lia.
    rewrite (tri_succ_div2 q). nia. }
  exists (p2 + (E0 - m) + (E1 - (m + 1))), (bsC ++ [eL' + sumList esL']).
  split.
  - exists (W2 ++ encS (2 * m + 3) false (b - 1) [] None), (es_pre ++ (es0' ++ es1')).
    split; [exact hpAll |].
    split; [clear - E0 E1 hsum_pre hsum0 hsum1 hE0_lb hE1_lb hB hBD hD1; simp_sumList; lia | exact hblFull].
  - split; [clear - hlenC hQpos; rewrite List.length_app; simpl; lia |].
    assert (hbsSum : sumList bs2 = sumList bsM + EL).
    { clear - EL hbs2Eq; rewrite hbs2Eq, sumList_append; simpl; lia. }
    split.
    + rewrite sumList_append; simpl sumList.
      clear - E0 E1 EL hE0_lb hE1_lb hEL_lb hB hBD hD1 hLast hsumC hgeC hsumL' hcostEq hbsSum hQpos hb2Q; lia.
    + split; [simpl sumList; clear - E0 E1 EL hE0_lb hE1_lb hEL_lb hB hBD hD1 hLast hgeC hcostEq hbsSum hQpos hb2Q; lia |].
      intros i hi. simp_len_app; simpl List.length in hi |- *.
      destruct (Nat.ltb i (Qv - 1)) eqn:Hlt.
      * apply Nat.ltb_lt in Hlt.
        assert (HeqF : Nat.eqb (i + 1) (List.length bsC + 1) = false) by (clear - hlenC Hlt; apply Nat.eqb_neq; lia).
        rewrite HeqF, nth_append_left by (clear - hlenC Hlt; lia).
        specialize (hlbC i ltac:(clear - hlenC Hlt; lia)).
        clear - hlbC hb2Q; lia.
      * apply Nat.ltb_ge in Hlt. assert (i = Qv - 1) by (clear - hlenC hi Hlt; lia); subst i.
        assert (HeqT : Nat.eqb (Qv - 1 + 1) (List.length bsC + 1) = true) by (clear - hlenC; apply Nat.eqb_eq; lia).
        rewrite HeqT, nth_append_right by (clear - hlenC; lia).
        replace (Qv - 1 - List.length bsC) with 0 by (clear - hlenC; lia); simpl List.nth.
        clear - EL hEL_lb hsumL' hLast hb2Q hQpos; lia.
Qed.

Lemma liftDigitRelay_s1 {W Wm W' : list Sym} {es_pre bs : list nat} {p2 : nat}
    (m b Qv B D B_last : nat) (hm1 : 1 <= m)
    (hp_pre : PureP2 W Wm es_pre) (hsum_pre : sumList es_pre = p2)
    (hbl : BlockList Wm W' bs) (hlen : List.length bs = 3 * Qv) (hlb : BlockLB bs B D B_last)
    (hQpos : 1 <= Qv) (hb2Q : 2 * Qv + 2 <= b) (hD1 : 1 <= D)
    (hB : m + 1 <= B) (hBD : m + 3 <= B + D)
    (hLast : m + Qv <= B_last)
    (hCyc : Qv <= 1 \/ 3 * m + b + 1 <= 3 * B + 6 * D)
    (hTail : 2 * m + b + 1 <= B + D * (3 * Qv - 2) + B_last) :
    exists p2' bs', BlockStream (W ++ encS (2 * m) true b [] None)
        (W' ++ encS (2 * m + 2 * Qv) true (b - 2 * Qv) [] None) p2' bs' /\
      List.length bs' = Qv /\
      p2' + sumList bs' = p2 + sumList bs - digCycleCost_nat (2 * m) true b Qv /\
      digCycleCost_nat (2 * m) true b Qv <= sumList bs /\
      BlockLB bs' (3 * B + 6 * D - (3 * m + b + 1)) (9 * D - 1) (B + D * (3 * Qv - 2) + B_last - (2 * m + b)).
Proof.
  revert hsum_pre.
  inversion hbl as [| W_0 W1 W_a e0 es0 bs1 hb0 hbl1]; subst; [simpl in hlen; lia |].
  intros hsum_pre.
  simpl List.length in hlen.
  set (E0 := e0 + sumList es0) in *.
  assert (hE0_lb : B <= E0).
  { specialize (hlb 0 ltac:(simpl; lia)); cbn [List.length List.nth] in hlb.
    change (0 + 1) with 1 in hlb.
    destruct (Nat.eqb 1 (S (List.length bs1))) eqn:He0;
      [apply Nat.eqb_eq in He0; lia | lia]. }
  destruct (OneBlock_liftS1 m (b - 1) hm1 ltac:(lia) hb0 ltac:(lia)) as [es0' [hp0 hsum0]].
  replace (b - 1 + 1) with b in hp0 by lia.
  destruct (BlockList_splitAt (3 * (Qv - 1)) hbl1 ltac:(lia))
    as [Wmid [bsM [bsL [hbs1Eq [hlenM [hblM hblL]]]]]].
  assert (hlenL : List.length bsL = 2).
  { pose proof (f_equal (@List.length nat) hbs1Eq) as Hlen; rewrite List.length_app in Hlen; lia. }
  revert hbs1Eq hsum_pre.
  inversion hblL as [| W_m WT W_e eT1 esT1 bsL1 hbT1 hblL1]; subst; [simpl in hlenL; lia |].
  inversion hblL1 as [| W_t W_l W_f eT2 esT2 bsEnd hbT2 hblEnd]; subst; [simpl in hlenL; lia |].
  inversion hblEnd; subst; [| simpl in hlenL; lia].
  intros hbs1Eq hsum_pre.
  set (ET1 := eT1 + sumList esT1) in *.
  set (ET2 := eT2 + sumList esT2) in *.
  assert (hET1_lb : B + D * (3 * Qv - 2) <= ET1).
  { specialize (hlb (3 * Qv - 2) ltac:(simpl; lia)).
    assert (HeqF : Nat.eqb (3 * Qv - 2 + 1) (List.length (E0 :: bs1)) = false)
      by (apply Nat.eqb_neq; simpl; lia).
    rewrite HeqF in hlb.
    replace (3 * Qv - 2) with (S (3 * (Qv - 1))) in hlb at 2 by lia.
    cbn [List.nth] in hlb. rewrite hbs1Eq, nth_append_right in hlb by lia.
    replace (3 * (Qv - 1) - List.length bsM) with 0 in hlb by lia; cbn [List.nth] in hlb; exact hlb. }
  assert (hET2_lb : B_last <= ET2).
  { specialize (hlb (3 * Qv - 1) ltac:(simpl; lia)).
    assert (HeqT : Nat.eqb (3 * Qv - 1 + 1) (List.length (E0 :: bs1)) = true)
      by (apply Nat.eqb_eq; simpl; lia).
    rewrite HeqT in hlb.
    replace (3 * Qv - 1) with (S (3 * (Qv - 1) + 1)) in hlb by lia.
    cbn [List.nth] in hlb. rewrite hbs1Eq, nth_append_right in hlb by lia.
    replace (3 * (Qv - 1) + 1 - List.length bsM) with 1 in hlb by lia; cbn [List.nth] in hlb; exact hlb. }
  assert (hlbM : forall i, i < List.length bsM -> (B + D) + D * i <= List.nth i bsM 0).
  { intros i hi. specialize (hlb (S i) ltac:(simpl; lia)).
    cbn [List.nth List.length] in hlb.
    assert (HeqF : Nat.eqb (S i + 1) (S (List.length bs1)) = false) by (apply Nat.eqb_neq; lia).
    rewrite HeqF in hlb. rewrite hbs1Eq, nth_append_left in hlb by lia. lia. }
  destruct (BlockList_liftCyclesAllAffine D hD1 (Qv - 1) m b (B + D)
              hblM hlenM ltac:(lia) hlbM hBD ltac:(lia))
    as [bsC [hblC [hlenC [hsumC [hgeC hlbC]]]]].
  assert (hDq : D + (Qv - 1) <= D * (3 * Qv - 2)).
  { clear - hD1 hQpos. replace (3 * Qv - 2) with (1 + 3 * (Qv - 1)) by lia. nia. }
  destruct (liftDigit2Tail (m + (Qv - 1)) (b - 2 * Qv) ltac:(lia) hbT1 hbT2
              ltac:(lia) ltac:(lia) ltac:(lia))
    as [eT' [esT' [hbT' hsumT']]].
  fold ET1 ET2 in hsumT'.
  replace (b - 2 * Qv + 2) with (b - 2 * (Qv - 1)) in hbT' by lia.
  replace (2 * (m + (Qv - 1)) + 2) with (2 * m + 2 * Qv) in hbT' by lia.
  pose proof (BlockList_append hblC (BlockList_cons hbT' (BlockList_nil _))) as hblFull.
  pose proof (PureP2_append (PureP2_liftCell (2 * m) true b (or_introl eq_refl) ltac:(lia) hp_pre) hp0) as hpAll.
  assert (hcostEq : digCycleCost_nat (2 * m) true b Qv =
                    m + digCycleCost_nat (2 * m + 1) false b (Qv - 1) +
                    (2 * (m + (Qv - 1)) + (b - 2 * Qv) + 2)).
  { clear - hQpos hb2Q. unfold digCycleCost_nat.
    replace ((2 * m) mod 2) with 0 by lia.
    replace ((2 * m) / 2) with m by lia.
    replace ((2 * m + 1) / 2) with m by lia.
    simpl (true && Nat.eqb 0 0)%bool. simpl (false && _)%bool.
    set (q := Qv - 1). replace Qv with (q + 1) by lia.
    replace (q + 1 - 1) with q by lia.
    rewrite (tri_succ_div2 q). nia. }
  exists (p2 + (E0 - m)), (bsC ++ [eT' + sumList esT']).
  split.
  - exists (W1 ++ encS (2 * m + 1) false b [] None), (es_pre ++ es0').
    split; [exact hpAll | split; [clear - E0 hsum_pre hsum0 hE0_lb hB; rewrite sumList_append; lia | exact hblFull]].
  - split; [clear - hlenC hQpos; rewrite List.length_app; simpl; lia |].
    assert (hbsSum : sumList bs1 = sumList bsM + ET1 + ET2).
    { clear - ET1 ET2 hbs1Eq; rewrite hbs1Eq, sumList_append; simpl; lia. }
    split.
    + rewrite sumList_append; simpl sumList.
      clear - E0 ET1 ET2 hE0_lb hET1_lb hET2_lb hB hTail hLast hDq hsumC hgeC hsumT' hcostEq hbsSum hQpos hb2Q; lia.
    + split; [simpl sumList; clear - E0 ET1 ET2 hE0_lb hET1_lb hET2_lb hB hTail hLast hDq hgeC hcostEq hbsSum hQpos hb2Q; lia |].
      intros i hi. simp_len_app; simpl List.length in hi |- *.
      destruct (Nat.ltb i (Qv - 1)) eqn:Hlt.
      * apply Nat.ltb_lt in Hlt.
        assert (HeqF : Nat.eqb (i + 1) (List.length bsC + 1) = false) by (clear - hlenC Hlt; apply Nat.eqb_neq; lia).
        rewrite HeqF, nth_append_left by (clear - hlenC Hlt; lia).
        specialize (hlbC i ltac:(clear - hlenC Hlt; lia)).
        clear - hlbC hb2Q; lia.
      * apply Nat.ltb_ge in Hlt. assert (i = Qv - 1) by (clear - hlenC hi Hlt; lia); subst i.
        assert (HeqT : Nat.eqb (Qv - 1 + 1) (List.length bsC + 1) = true) by (clear - hlenC; apply Nat.eqb_eq; lia).
        rewrite HeqT, nth_append_right by (clear - hlenC; lia).
        replace (Qv - 1 - List.length bsC) with 0 by (clear - hlenC; lia); simpl List.nth.
        clear - ET1 ET2 hET1_lb hET2_lb hsumT' hTail hLast hDq hb2Q hQpos; lia.
Qed.

Lemma BlockLB_eq {bs : list nat} {B1 D1 L1 B2 D2 L2 : nat}
    (hB : B1 = B2) (hD : D1 = D2) (hL : L1 = L2) (h : BlockLB bs B1 D1 L1) :
    BlockLB bs B2 D2 L2.
Proof. subst; exact h. Qed.

Lemma digState_cases (a : N) (h : bool) (st : N) (hds : digState a h = Some st) :
  (st = 0%N /\ h = true /\ N.to_nat a = 2 * (N.to_nat a / 2) + 1) \/
  (st = 1%N /\ h = true /\ 1 <= N.to_nat a / 2 /\ N.to_nat a = 2 * (N.to_nat a / 2)) \/
  (st = 2%N /\ h = false /\ N.to_nat a = 2 * (N.to_nat a / 2) + 1).
Proof.
  unfold digState in hds.
  pose proof (N2Nat_div a 2) as Hdiv. change (N.to_nat 2%N) with 2 in Hdiv.
  pose proof (N2Nat_mod a 2) as Hmod. change (N.to_nat 2%N) with 2 in Hmod.
  pose proof (div2_cases (N.to_nat a)) as Hcases.
  destruct h.
  - destruct ((a mod 2 =? 1)%N) eqn:Hodd.
    + apply N.eqb_eq in Hodd. inv_some hds; subst st.
      left; split; [reflexivity | split; [reflexivity | lia]].
    + apply N.eqb_neq in Hodd.
      destruct ((2 <=? a)%N) eqn:Ha2; [| discriminate].
      apply N.leb_le in Ha2. inv_some hds; subst st.
      right; left; split; [reflexivity | split; [reflexivity | split; lia]].
  - destruct ((a mod 2 =? 1)%N) eqn:Hodd; [| discriminate].
    apply N.eqb_eq in Hodd. inv_some hds; subst st.
    right; right; split; [reflexivity | split; [reflexivity | lia]].
Qed.

Lemma BlockStream_liftDigitRelay {W W' : list Sym} {p2 : nat} {bs : list nat}
    (a : N) (h : bool) (b Qv Bv Dv B_last B' D' B_last' : N)
    (hs : BlockStream W W' p2 bs)
    (hlen : List.length bs = 3 * N.to_nat Qv)
    (hlb : BlockLB bs (N.to_nat Bv) (N.to_nat Dv) (N.to_nat B_last))
    (hcheck : liftDigitRelayLB a h b Qv Bv Dv B_last = Some (B', D', B_last')) :
    exists p2' bs', BlockStream (W ++ encSingle a h b [] None)
        (W' ++ encSingle (a + 2 * Qv)%N h (b - 2 * Qv)%N [] None) p2' bs' /\
      List.length bs' = N.to_nat Qv /\
      p2' + sumList bs' = p2 + sumList bs - N.to_nat (digCycleCost a h b Qv) /\
      N.to_nat (digCycleCost a h b Qv) <= sumList bs /\
      BlockLB bs' (N.to_nat B') (N.to_nat D') (N.to_nat B_last').
Proof.
  unfold liftDigitRelayLB in hcheck.
  destruct (((Qv =? 0)%N || (b <? 2 * Qv + 2)%N || (Dv <? 1)%N)%bool) eqn:Hbad; [discriminate |].
  apply orb_false_elim in Hbad; destruct Hbad as [Hbad1 Hbad2].
  apply orb_false_elim in Hbad1; destruct Hbad1 as [HQ0 Hb2Q].
  apply N.eqb_neq in HQ0. apply N.ltb_ge in Hb2Q. apply N.ltb_ge in Hbad2.
  destruct (digState a h) as [st|] eqn:Hds; [| discriminate].
  pose proof (N2Nat_div a 2) as Hmdiv. change (N.to_nat 2%N) with 2 in Hmdiv.
  rewrite !encSingle_eq_encS; simpl option_map.
  rewrite digCycleCost_to_nat.
  destruct hs as [Wm [es_pre [hp_pre [hsum_pre hbl]]]].
  destruct (digState_cases a h st Hds) as [[Hst [Hh Ha]] | [[Hst [Hh [Hm1 Ha]]] | [Hst [Hh Ha]]]];
    subst st h.
  - (* st = 0 *)
    simpl ((0 =? 2)%N) in hcheck; simpl ((0 =? 1)%N) in hcheck; simpl ((0 =? 0)%N) in hcheck.
    destruct ((((a / 2 + 1 <=? Bv)%N && (a / 2 + 2 <=? Bv + Dv)%N && (a / 2 + 4 <=? Bv + 2 * Dv)%N &&
               ((Qv <=? 1)%N || (3 * (a / 2) + b + 3 <=? 3 * Bv + 9 * Dv)%N) &&
               (a / 2 + Qv + (b - 2 * Qv + 1) + 1 <=? B_last)%N))%bool) eqn:Hcond; [| discriminate].
    inv_some hcheck; subst B' D' B_last'.
    split_andb.
    assert (HCyc : N.to_nat Qv <= 1 \/ 3 * (N.to_nat a / 2) + N.to_nat b + 3 <= 3 * N.to_nat Bv + 9 * N.to_nat Dv).
    { match goal with Hor : (_ || _)%bool = true |- _ =>
        apply Bool.orb_true_iff in Hor; destruct Hor as [Hor|Hor]; apply N.leb_le in Hor; [left | right]; lia
      end. }
    destruct (liftDigitRelay_s0 (N.to_nat a / 2) (N.to_nat b) (N.to_nat Qv)
                (N.to_nat Bv) (N.to_nat Dv) (N.to_nat B_last)
                hp_pre hsum_pre hbl hlen hlb ltac:(lia) ltac:(lia) ltac:(lia)
                ltac:(lia) ltac:(lia) ltac:(lia) HCyc ltac:(lia))
      as [p2' [bs' [hs' [hlen' [hsum' [hge' hlb']]]]]].
    try (rewrite <- Ha in hs'); try (rewrite <- Ha in hsum'); try (rewrite <- Ha in hge').
    replace (N.to_nat a + 2 * N.to_nat Qv) with (N.to_nat (a + 2 * Qv)%N) in hs' by lia.
    replace (N.to_nat b - 2 * N.to_nat Qv) with (N.to_nat (b - 2 * Qv)%N) in hs' by lia.
    exists p2', bs'.
    split; [exact hs' | split; [exact hlen' | split; [exact hsum' | split; [exact hge' |]]]].
    eapply BlockLB_eq; [.. | exact hlb']; lia.
  - (* st = 1 *)
    simpl ((1 =? 2)%N) in hcheck; simpl ((1 =? 1)%N) in hcheck.
    destruct ((((a / 2 + 1 <=? Bv)%N && (a / 2 + 3 <=? Bv + Dv)%N && (a / 2 + Qv <=? B_last)%N &&
               ((Qv <=? 1)%N || (3 * (a / 2) + b + 1 <=? 3 * Bv + 6 * Dv)%N) &&
               (2 * (a / 2) + b + 1 <=? Bv + Dv * (3 * Qv - 2) + B_last)%N))%bool) eqn:Hcond; [| discriminate].
    inv_some hcheck; subst B' D' B_last'.
    split_andb.
    assert (HCyc : N.to_nat Qv <= 1 \/ 3 * (N.to_nat a / 2) + N.to_nat b + 1 <= 3 * N.to_nat Bv + 6 * N.to_nat Dv).
    { match goal with Hor : (_ || _)%bool = true |- _ =>
        apply Bool.orb_true_iff in Hor; destruct Hor as [Hor|Hor]; apply N.leb_le in Hor; [left | right]; lia
      end. }
    assert (HTail : 2 * (N.to_nat a / 2) + N.to_nat b + 1 <=
                    N.to_nat Bv + N.to_nat Dv * (3 * N.to_nat Qv - 2) + N.to_nat B_last) by nia.
    destruct (liftDigitRelay_s1 (N.to_nat a / 2) (N.to_nat b) (N.to_nat Qv)
                (N.to_nat Bv) (N.to_nat Dv) (N.to_nat B_last) Hm1
                hp_pre hsum_pre hbl hlen hlb ltac:(lia) ltac:(lia) ltac:(lia)
                ltac:(lia) ltac:(lia) ltac:(lia) HCyc HTail)
      as [p2' [bs' [hs' [hlen' [hsum' [hge' hlb']]]]]].
    try (rewrite <- Ha in hs'); try (rewrite <- Ha in hsum'); try (rewrite <- Ha in hge').
    replace (N.to_nat a + 2 * N.to_nat Qv) with (N.to_nat (a + 2 * Qv)%N) in hs' by lia.
    replace (N.to_nat b - 2 * N.to_nat Qv) with (N.to_nat (b - 2 * Qv)%N) in hs' by lia.
    exists p2', bs'.
    split; [exact hs' | split; [exact hlen' | split; [exact hsum' | split; [exact hge' |]]]].
    eapply BlockLB_eq; [.. | exact hlb']; nia.
  - (* st = 2 *)
    simpl ((2 =? 2)%N) in hcheck.
    destruct ((((a / 2 + 3 <=? Bv)%N && (a / 2 + Qv + 1 <=? B_last)%N &&
               ((Qv <=? 1)%N || (3 * (a / 2) + b + 1 <=? 3 * Bv + 3 * Dv)%N) &&
               (3 * (a / 2) + b + Qv <=? 2 * Bv + Dv * (6 * Qv - 5) + B_last)%N))%bool) eqn:Hcond; [| discriminate].
    inv_some hcheck; subst B' D' B_last'.
    split_andb.
    assert (HCyc : N.to_nat Qv <= 1 \/ 3 * (N.to_nat a / 2) + N.to_nat b + 1 <= 3 * N.to_nat Bv + 3 * N.to_nat Dv).
    { match goal with Hor : (_ || _)%bool = true |- _ =>
        apply Bool.orb_true_iff in Hor; destruct Hor as [Hor|Hor]; apply N.leb_le in Hor; [left | right]; lia
      end. }
    assert (HTail : N.to_nat Qv = 0 \/
                    3 * (N.to_nat a / 2) + N.to_nat b + N.to_nat Qv <=
                    2 * N.to_nat Bv + N.to_nat Dv * (6 * N.to_nat Qv - 5) + N.to_nat B_last)
      by (right; nia).
    destruct (BlockList_liftCyclesS2 (N.to_nat Dv) ltac:(lia) (N.to_nat Qv)
                (N.to_nat a / 2) (N.to_nat b) (N.to_nat Bv) (N.to_nat B_last)
                hbl hlen ltac:(lia) hlb ltac:(lia) ltac:(lia) HCyc HTail)
      as [bs' [hbl' [hlen' [hsum' hlb']]]].
    pose proof (digCycleCost_s2_le_sum (N.to_nat Dv) (N.to_nat B_last) ltac:(lia) (N.to_nat Qv)
                  (N.to_nat a / 2) (N.to_nat b) (N.to_nat Bv) bs hlen ltac:(lia) hlb HCyc HTail) as hge'.
    replace (2 * (N.to_nat a / 2 + N.to_nat Qv) + 1) with (N.to_nat (a + 2 * Qv)%N) in hbl' by lia.
    replace (N.to_nat b - 2 * N.to_nat Qv) with (N.to_nat (b - 2 * Qv)%N) in hbl' by lia.
    try (rewrite <- Ha in hbl'); try (rewrite <- Ha in hsum'); try (rewrite <- Ha in hge').
    exists p2, bs'.
    split.
    + exists (Wm ++ encS (N.to_nat a) false (N.to_nat b) [] None), es_pre.
      split; [exact (PureP2_liftCell (N.to_nat a) false (N.to_nat b) ltac:(right; split; lia) ltac:(lia) hp_pre) |].
      split; [exact hsum_pre | exact hbl'].
    + split; [exact hlen' | split; [lia | split; [exact hge' |]]].
      eapply BlockLB_eq; [.. | exact hlb']; nia.
Qed.

Definition ActiveGroupOk (g : ActiveGroup) : Prop :=
  let '(sp, a, h, _) := g in isTranspList sp = true /\ isSome (digState a h) = true.

Fixpoint encActiveGroups (gs : list ActiveGroup) : list Sym :=
  match gs with
  | [] => []
  | (sp, a, h, b) :: gs' => (encItems sp ++ encSingle a h b [] None) ++ encActiveGroups gs'
  end.

Lemma encActiveGroups_append : forall (l1 l2 : list ActiveGroup),
  encActiveGroups (l1 ++ l2) = encActiveGroups l1 ++ encActiveGroups l2.
Proof.
  induction l1 as [|[[[sp a] h] b] l1 IH]; intros l2; [reflexivity |].
  simpl. rewrite IH, ?append_assoc. reflexivity.
Qed.

Lemma encItems_itemsOfActiveGroups : forall (gs : list ActiveGroup),
  encItems (itemsOfActiveGroups gs) = encActiveGroups gs.
Proof.
  induction gs as [|[[[sp a] h] b] gs' IH]; [reflexivity |].
  simpl itemsOfActiveGroups; simpl encActiveGroups.
  simp_encItems_app; simpl encItems; simpl encItem.
  rewrite IH, ?app_nil_r, ?append_assoc. reflexivity.
Qed.

Lemma isTranspList_rev : forall (xs : list RleItem),
  isTranspList (List.rev xs) = isTranspList xs.
Proof.
  unfold isTranspList.
  induction xs as [|x xs IH]; [reflexivity |].
  simpl. rewrite List.forallb_app, IH; simpl.
  rewrite andb_true_r, andb_comm. reflexivity.
Qed.

Lemma splitActivePrefixAux_sound : forall (items : list RleItem) (k : nat)
    (revSp : list RleItem) (gs : list ActiveGroup) (suf : list RleItem),
  isTranspList revSp = true ->
  splitActivePrefixAux revSp k items = Some (gs, suf) ->
  List.length gs = k /\
  (forall g, List.In g gs -> ActiveGroupOk g) /\
  encItems (List.rev revSp) ++ encItems items = encActiveGroups gs ++ encItems suf.
Proof.
  induction items as [|x rest IH]; intros k revSp gs suf htr h.
  - destruct k as [|k']; simpl in h; [| discriminate].
    destruct revSp; simpl in h; [| discriminate].
    inv_some h; subst gs suf.
    split; [reflexivity | split; [intros _unused_x hm; contradiction | reflexivity]].
  - destruct k as [|k'].
    + simpl in h. destruct revSp; simpl in h; [| discriminate].
      inv_some h; subst gs suf.
      split; [reflexivity | split; [intros _unused_x hm; contradiction | reflexivity]].
    + cbn [splitActivePrefixAux] in h.
      destruct (isTranspItem x) eqn:Htx.
      * assert (htr' : isTranspList (x :: revSp) = true).
        { unfold isTranspList in htr |- *; simpl; rewrite Htx; exact htr. }
        destruct (IH (S k') (x :: revSp) gs suf htr' h) as [hlen [hall henc]].
        split; [exact hlen | split; [exact hall |]].
        simpl List.rev in henc. rewrite encItems_append in henc; simpl encItems in henc.
        rewrite app_nil_r, append_assoc in henc. exact henc.
      * destruct x as [a hc b [|? ?] [?|] | | |]; try discriminate.
        destruct (isSome (digState a hc)) eqn:Hds; [| discriminate].
        apply option_map_Some in h.
        destruct h as [[gs' suf'] [hrec hpair]].
        inv_some hpair; subst gs suf.
        destruct (IH k' [] gs' suf' eq_refl hrec) as [hlen [hall henc]].
        simpl in henc.
        split; [simpl; lia | split].
        -- intros g [<- | hg]; [simpl; split; [rewrite isTranspList_rev; exact htr | exact Hds] | exact (hall g hg)].
        -- simpl encItems; simpl encItem; simpl encActiveGroups.
           rewrite <- append_assoc, (append_assoc (encItems (List.rev revSp))), henc, ?append_assoc.
           reflexivity.
Qed.

Lemma runRelayDigits_sound (mult : N) : forall (gs : list ActiveGroup)
    {W W' : list Sym} {p2 : nat} {Bv Dv B_last : N} {bs : list nat}
    {gs' : list ActiveGroup} {totCost Bf Df Lf : N},
  (forall g, List.In g gs -> ActiveGroupOk g) ->
  BlockStream W W' p2 bs ->
  List.length bs = N.to_nat mult * Nat.pow 3 (List.length gs) ->
  BlockLB bs (N.to_nat Bv) (N.to_nat Dv) (N.to_nat B_last) ->
  runRelayDigits mult Bv Dv B_last gs = Some (gs', totCost, Bf, Df, Lf) ->
  exists p2' bs', BlockStream (W ++ encActiveGroups gs) (W' ++ encActiveGroups gs') p2' bs' /\
    List.length bs' = N.to_nat mult /\
    p2' + sumList bs' = p2 + sumList bs - N.to_nat totCost /\
    N.to_nat totCost <= p2 + sumList bs /\
    BlockLB bs' (N.to_nat Bf) (N.to_nat Df) (N.to_nat Lf).
Proof.
  induction gs as [|[[[sp a] h] b] gs_rest IH];
    intros W W' p2 Bv Dv B_last bs gs' totCost Bf Df Lf hall hs hlen hlb hrun.
  - simpl in hrun. inv_some hrun; subst.
    simpl List.length in hlen; rewrite Nat.mul_1_r in hlen.
    simpl encActiveGroups; rewrite ?app_nil_r.
    exists p2, bs.
    split; [exact hs | split; [exact hlen | split; [lia | split; [lia | exact hlb]]]].
  - assert (hg : ActiveGroupOk (sp, a, h, b)) by (apply hall; simpl; left; reflexivity).
    destruct hg as [htr_sp hds_a].
    assert (hrest : forall x, List.In x gs_rest -> ActiveGroupOk x)
      by (intros x hx; apply hall; simpl; right; exact hx).
    cbn [runRelayDigits] in hrun.
    set (sc := transpListCost sp) in *.
    destruct (((Bv <? sc)%N || (B_last <? sc)%N)%bool) eqn:Hsc; [discriminate |].
    apply orb_false_elim in Hsc; destruct Hsc as [HBsc HLsc].
    apply N.ltb_ge in HBsc; apply N.ltb_ge in HLsc.
    set (Qv := (mult * 3 ^ N.of_nat (List.length gs_rest))%N) in *.
    assert (HQv_nat : N.to_nat Qv = N.to_nat mult * Nat.pow 3 (List.length gs_rest)).
    { unfold Qv. rewrite N2Nat.inj_mul, N_pow3_of_nat. reflexivity. }
    destruct (liftDigitRelayLB a h b Qv (Bv - sc) Dv (B_last - sc)) as [[[B2 D2] L2]|] eqn:Hlift; [| discriminate].
    apply option_map_Some in hrun.
    destruct hrun as [[[[[gsOut cRest] Bf'] Df'] Lf'] [hrec heq]].
    inv_some heq; subst gs' totCost Bf Df Lf.
    assert (hmem : forall e, List.In e bs -> transpListCost_nat sp <= e).
    { unfold transpListCost_nat; fold sc.
      eapply (BlockLB_mem_ge hlb); lia. }
    pose proof (BlockStream_liftTranspList sp htr_sp hs hmem) as hs1.
    pose proof (BlockLB_map_sub hlb (c := transpListCost_nat sp)
                  ltac:(unfold transpListCost_nat; fold sc; lia)
                  ltac:(unfold transpListCost_nat; fold sc; lia)) as hlb1.
    replace (N.to_nat Bv - transpListCost_nat sp) with (N.to_nat (Bv - sc)%N) in hlb1
      by (unfold transpListCost_nat; fold sc; lia).
    replace (N.to_nat B_last - transpListCost_nat sp) with (N.to_nat (B_last - sc)%N) in hlb1
      by (unfold transpListCost_nat; fold sc; lia).
    assert (hlen3 : List.length bs = 3 * N.to_nat Qv).
    { rewrite HQv_nat. cbn [List.length Nat.pow] in hlen. lia. }
    assert (hlen1 : List.length (List.map (fun x => x - transpListCost_nat sp) bs) = 3 * N.to_nat Qv).
    { rewrite List.length_map; exact hlen3. }
    pose proof (sum_map_sub bs (transpListCost_nat sp) hmem) as hsum1.
    pose proof (list_len_mul_le_sum bs (transpListCost_nat sp) hmem) as hgeSc.
    destruct (BlockStream_liftDigitRelay a h b Qv (Bv - sc) Dv (B_last - sc) B2 D2 L2 hs1 hlen1 hlb1 Hlift)
      as [p2_2 [bs2 [hs2 [hlen2 [hsum2 [hge2 hlb2]]]]]].
    try (rewrite hsum1 in hsum2); try (rewrite hsum1 in hge2); try (rewrite hlen3 in hsum2); try (rewrite hlen3 in hge2).
    destruct (IH _ _ _ _ _ _ _ _ _ _ _ _ hrest hs2
                ltac:(rewrite hlen2, HQv_nat; reflexivity) hlb2 hrec)
      as [p2_3 [bs3 [hs3 [hlen3' [hsum3 [hge3 hlb3]]]]]].
    exists p2_3, bs3.
    split; [simpl encActiveGroups; (rewrite ?append_assoc in hs3; rewrite ?append_assoc); exact hs3 |].
    split; [exact hlen3' |].
    assert (Hsc_eq : transpListCost_nat sp = N.to_nat sc) by reflexivity.
    try (rewrite Hsc_eq in hsum2); try (rewrite Hsc_eq in hge2); try (rewrite Hsc_eq in hgeSc).
    rewrite hlen3 in hgeSc.
    split; [clear - hsum3 hge3 hsum2 hge2 hgeSc; nia | split; [clear - hsum3 hge3 hsum2 hge2 hgeSc; nia | exact hlb3]].
Qed.

Lemma stepOdoRelay_sound {k : nat} {mult : N} {items items' : list RleItem}
    (h : stepOdoRelay k mult items = Some items') :
    HubCfg items -[ tm ]->* HubCfg items'.
Proof.
  unfold stepOdoRelay in h.
  destruct ((negb (mult =? 1)%N && negb (mult =? 2)%N)%bool) eqn:Hmult; [discriminate |].
  assert (hm12 : mult = 1%N \/ mult = 2%N).
  { destruct ((mult =? 1)%N) eqn:Hm1; [apply N.eqb_eq in Hm1; left; exact Hm1 |].
    destruct ((mult =? 2)%N) eqn:Hm2; [apply N.eqb_eq in Hm2; right; exact Hm2 | discriminate]. }
  destruct items as [|[a0 h0 b0_v [|? ?] [?|] | | |] rest]; try discriminate.
  set (Nv := (mult * 3 ^ N.of_nat k)%N) in *.
  destruct (negb (c0Valid a0 h0 b0_v && (Nv + (if h0 then 4 else 5) <=? b0_v)%N && (b0_v + 1 <=? a0 / 2)%N)) eqn:Hc0;
    [discriminate |].
  apply negb_false_iff in Hc0.
  apply andb_prop in Hc0; destruct Hc0 as [Hc0a He0].
  apply andb_prop in Hc0a; destruct Hc0a as [Hv0 Hb0].
  apply N.leb_le in Hb0; apply N.leb_le in He0.
  pose proof (N2Nat_div a0 2) as Ha0div. change (N.to_nat 2%N) with 2 in Ha0div.
  pose proof (c0Valid_to_nat a0 h0 b0_v Hv0) as hv0_nat.
  destruct (splitActivePrefix (S k) rest) as [[allGs suf]|] eqn:Hsp; [| discriminate].
  destruct (splitActivePrefixAux_sound rest (S k) [] allGs suf eq_refl Hsp)
    as [hallLen [hallOk hallEnc]].
  simpl in hallEnc.
  destruct (List.rev allGs) as [|[[[spF aF] hF] bF] revMid] eqn:Hrev; [discriminate |].
  set (midGs := List.rev revMid) in *.
  assert (hallEq : allGs = midGs ++ [(spF, aF, hF, bF)]).
  { apply (f_equal (@List.rev ActiveGroup)) in Hrev.
    rewrite List.rev_involutive in Hrev; simpl in Hrev; exact Hrev. }
  assert (hmidLen : List.length midGs = k).
  { pose proof (f_equal (@List.length ActiveGroup) hallEq) as Hlen; rewrite List.length_app in Hlen; simpl in Hlen; lia. }
  assert (hmidOk : forall g, List.In g midGs -> ActiveGroupOk g).
  { intros g hg; apply hallOk; rewrite hallEq; apply List.in_or_app; left; exact hg. }
  assert (hFOk : ActiveGroupOk (spF, aF, hF, bF)).
  { apply hallOk; rewrite hallEq; apply List.in_or_app; right; simpl; left; reflexivity. }
  destruct hFOk as [htr_spF hds_aF].
  set (e0 := c0E1 a0 h0 b0_v) in *.
  destruct (runRelayDigits mult e0 2 (e0 + 2 * (Nv - 1)) midGs)
    as [[[[[midGs' midCost] Bf] Df] Lf]|] eqn:Hrun; [| discriminate].
  set (scF := transpListCost spF) in *.
  destruct (((Bf <? scF)%N || (Lf <? scF)%N)%bool) eqn:HscF; [discriminate |].
  apply orb_false_elim in HscF; destruct HscF as [HBf HLf].
  apply N.ltb_ge in HBf; apply N.ltb_ge in HLf.
  set (B1 := (Bf - scF)%N) in *.
  set (L1 := (Lf - scF)%N) in *.
  destruct (relayFinalOk mult aF hF bF scF B1 L1) as [[[[aF' hF'] bF'] fCost]|] eqn:Hfin; [| discriminate].
  set (totIn := c0TotalIn a0 h0 b0_v Nv) in *.
  set (totCost := (midCost + fCost)%N) in *.
  destruct ((totCost <=? totIn)%N) eqn:Htot; [| discriminate].
  apply N.leb_le in Htot.
  pose proof (c0StepN_to_nat a0 h0 b0_v Nv) as Hc0N.
  destruct (c0StepN a0 h0 b0_v Nv) as [[a0' h0'] b0'] eqn:Hc0Step.
  apply option_map_Some in h.
  destruct h as [suf' [hsuf' hitems']]; subst items'.
  assert (HNv_pos : 1 <= N.to_nat Nv).
  { unfold Nv. rewrite N2Nat.inj_mul, N_pow3_of_nat.
    assert (1 <= Nat.pow 3 k) by (clear; induction k; simpl; lia).
    destruct hm12 as [-> | ->]; cbn [N.to_nat Pos.to_nat Pos.iter_op Nat.add]; nia. }
  pose proof (c0_blockStream (N.to_nat a0) h0 (N.to_nat b0_v) (N.to_nat Nv) hv0_nat
                ltac:(destruct h0; lia) ltac:(lia)) as Hbs0.
  rewrite <- Hc0N in Hbs0.
  destruct Hbs0 as [bs0 [hs0 [hlen0 [hsum0 hlb0]]]].
  assert (hlenN : List.length bs0 = N.to_nat mult * Nat.pow 3 (List.length midGs)).
  { rewrite hmidLen, <- N_pow3_of_nat, <- N2Nat.inj_mul; exact hlen0. }
  assert (hlb0' : BlockLB bs0 (N.to_nat e0) (N.to_nat 2%N) (N.to_nat (e0 + 2 * (Nv - 1))%N)).
  { unfold e0. eapply BlockLB_eq; [.. | exact hlb0]; rewrite ?N2Nat.inj_add, ?c0E1_to_nat; try reflexivity; lia. }
  destruct (runRelayDigits_sound mult midGs hmidOk hs0 hlenN hlb0' Hrun)
    as [p2_m [bs_m [hs_m [hlen_m [hsum_m [hge_m hlb_m]]]]]].
  assert (hmemF : forall e, List.In e bs_m -> transpListCost_nat spF <= e).
  { unfold transpListCost_nat; fold scF.
    eapply (BlockLB_mem_ge hlb_m); lia. }
  pose proof (BlockStream_liftTranspList spF htr_spF hs_m hmemF) as hs_sp.
  pose proof (BlockLB_map_sub hlb_m (c := transpListCost_nat spF)
                ltac:(unfold transpListCost_nat; fold scF; lia)
                ltac:(unfold transpListCost_nat; fold scF; lia)) as hlb_sp.
  replace (N.to_nat Bf - transpListCost_nat spF) with (N.to_nat B1) in hlb_sp
    by (unfold B1, transpListCost_nat; fold scF; lia).
  replace (N.to_nat Lf - transpListCost_nat spF) with (N.to_nat L1) in hlb_sp
    by (unfold L1, transpListCost_nat; fold scF; lia).
  pose proof (sum_map_sub bs_m (transpListCost_nat spF) hmemF) as hsum_sp.
  pose proof (list_len_mul_le_sum bs_m (transpListCost_nat spF) hmemF) as hgeScF.
  assert (hlen_sp : List.length (List.map (fun x => x - transpListCost_nat spF) bs_m) = N.to_nat mult)
    by (rewrite List.length_map; exact hlen_m).
  assert (hFinalP2 : exists esF,
    PureP2 (((encS (N.to_nat a0) h0 (N.to_nat b0_v) [] None ++ encActiveGroups midGs) ++ encItems spF) ++
             encS (N.to_nat aF) hF (N.to_nat bF) [] None)
           (((encS (N.to_nat a0') h0' (N.to_nat b0') [] None ++ encActiveGroups midGs') ++ encItems spF) ++
             encS (N.to_nat aF') hF' (N.to_nat bF') [] None) esF /\
    sumList esF = N.to_nat totIn - N.to_nat totCost).
  { destruct hs_sp as [Wm [es_pre [hp_pre [hsum_pre hbl_sp]]]].
    remember (List.map (fun x => x - transpListCost_nat spF) bs_m) as bs_sp eqn:Hbs_sp; clear Hbs_sp.
    unfold relayFinalOk in Hfin.
    destruct (digState aF hF) as [stF|] eqn:HdsF; [| discriminate].
    pose proof (N2Nat_div aF 2) as HmFdiv. change (N.to_nat 2%N) with 2 in HmFdiv.
    assert (HtotIn_eq : sumList bs0 = N.to_nat totIn).
    { unfold totIn; rewrite c0TotalIn_to_nat; exact hsum0. }
    assert (HscF_eq : transpListCost_nat spF = N.to_nat scF) by reflexivity.
    destruct (digState_cases aF hF stF HdsF) as [[Hst [Hh Ha]] | [[Hst [Hh [Hm1 Ha]]] | [Hst [Hh Ha]]]];
      subst stF hF.
    - (* stF = 0 *)
      simpl ((0 =? 0)%N) in Hfin.
      destruct hm12 as [-> | ->].
      + simpl ((1 =? 1)%N) in Hfin.
        destruct (((2 <=? bF)%N && (aF / 2 + 1 <=? L1)%N)%bool) eqn:Hfc; [| discriminate].
        apply andb_prop in Hfc; destruct Hfc as [Hb2 HL1]; apply N.leb_le in Hb2; apply N.leb_le in HL1.
        inv_some Hfin; subst aF' hF' bF' fCost.
        change (N.to_nat 2%N) with 2 in hlen_sp, hlen_m.
        inversion hbl_sp as [| W_0 W_1 W_2 e1 es1 bsEnd hb1 hblEnd]; subst; [simpl in hlen_sp; lia |].
        inversion hblEnd; subst; [| simpl in hlen_sp; lia].
        assert (hE1 : N.to_nat L1 <= e1 + sumList es1)
          by (specialize (hlb_sp 0 ltac:(simpl; lia)); simpl in hlb_sp; lia).
        destruct (OneBlock_liftS0 (N.to_nat aF / 2) (N.to_nat bF - 1) ltac:(lia) hb1 ltac:(lia))
          as [es1' [hp1 hsum1]].
        replace (N.to_nat bF - 1 + 1) with (N.to_nat bF) in hp1 by lia.
        replace (2 * (N.to_nat aF / 2) + 2) with (N.to_nat (aF + 1)%N) in hp1 by lia.
        rewrite <- Ha in hp1.
        replace (N.to_nat bF - 1) with (N.to_nat (bF - 1)%N) in hp1 by lia.
        exists (es_pre ++ es1').
        split.
        * exact (PureP2_append (PureP2_liftCell (N.to_nat aF) true (N.to_nat bF) (or_introl eq_refl) ltac:(lia) hp_pre) hp1).
        * rewrite sumList_append. simpl sumList in hsum_sp.
          try (rewrite hlen_m in hsum_sp); try (rewrite hlen_m in hgeScF); try (rewrite HscF_eq in hsum_sp); try (rewrite HscF_eq in hgeScF). unfold totCost; lia.
      + simpl ((2 =? 1)%N) in Hfin.
        destruct (((3 <=? bF)%N && (aF / 2 + 1 <=? B1)%N && (aF / 2 + 2 <=? L1)%N)%bool) eqn:Hfc; [| discriminate].
        apply andb_prop in Hfc; destruct Hfc as [Hfc1 HL1]; apply andb_prop in Hfc1; destruct Hfc1 as [Hb3 HB1].
        apply N.leb_le in Hb3; apply N.leb_le in HB1; apply N.leb_le in HL1.
        inv_some Hfin; subst aF' hF' bF' fCost.
        change (N.to_nat 2%N) with 2 in hlen_sp, hlen_m.
        inversion hbl_sp as [| W_0 W_1 W_2 e1 es1 bs1 hb1 hbl1]; subst; [simpl in hlen_sp; clear - hlen_sp; lia |].
        inversion hbl1 as [| W_a W_b W_c e2 es2 bsEnd hb2 hblEnd]; subst; [simpl in hlen_sp; clear - hlen_sp; lia |].
        inversion hblEnd; subst; [| simpl in hlen_sp; clear - hlen_sp; lia].
        assert (hE1 : N.to_nat B1 <= e1 + sumList es1)
          by (specialize (hlb_sp 0 ltac:(simpl; lia)); simpl in hlb_sp; clear - B1 hlb_sp; lia).
        assert (hE2 : N.to_nat L1 <= e2 + sumList es2)
          by (specialize (hlb_sp 1 ltac:(simpl; lia)); simpl in hlb_sp; clear - L1 hlb_sp; lia).
        destruct (OneBlock_liftS0 (N.to_nat aF / 2) (N.to_nat bF - 1) ltac:(clear - Hb3; lia) hb1 ltac:(clear - B1 HmFdiv HB1 hE1; lia))
          as [es1' [hp1 hsum1]].
        replace (N.to_nat bF - 1 + 1) with (N.to_nat bF) in hp1 by (clear - Hb3; lia).
        destruct (OneBlock_liftS1 (N.to_nat aF / 2 + 1) (N.to_nat bF - 2) ltac:(clear; lia) ltac:(clear - Hb3; lia) hb2 ltac:(clear - L1 HmFdiv HL1 hE2; lia))
          as [es2' [hp2 hsum2]].
        replace (2 * (N.to_nat aF / 2 + 1)) with (2 * (N.to_nat aF / 2) + 2) in hp2 by (clear; lia).
        replace (2 * (N.to_nat aF / 2) + 2 + 1) with (N.to_nat (aF + 2)%N) in hp2 by (clear - Ha; lia).
        replace (N.to_nat bF - 2 + 1) with (N.to_nat (bF - 1)%N) in hp2 by (clear - Hb3; lia).
        replace (N.to_nat bF - 1) with (N.to_nat (bF - 1)%N) in hp1 by (clear - Hb3; lia).
        rewrite <- Ha in hp1.
        exists ((es_pre ++ es1') ++ es2').
        split.
        * exact (PureP2_append
                  (PureP2_append (PureP2_liftCell (N.to_nat aF) true (N.to_nat bF) (or_introl eq_refl) ltac:(clear - Hb3; lia) hp_pre) hp1)
                  hp2).
        * simp_sumList. simpl sumList in hsum_sp.
          try (rewrite hlen_m in hsum_sp); try (rewrite hlen_m in hgeScF); try (rewrite HscF_eq in hsum_sp); try (rewrite HscF_eq in hgeScF).
          clear - B1 L1 totIn totCost HmFdiv HB1 HL1 hE1 hE2 hsum1 hsum2 hsum_sp hgeScF hsum_m hge_m HtotIn_eq Htot; unfold totCost; lia.
    - (* stF = 1 *)
      simpl ((1 =? 0)%N) in Hfin; simpl ((1 =? 1)%N) in Hfin.
      destruct (((mult =? 1)%N && (2 <=? bF)%N && (aF / 2 + 1 <=? L1)%N)%bool) eqn:Hfc; [| discriminate].
      apply andb_prop in Hfc; destruct Hfc as [Hfc1 HL1]; apply andb_prop in Hfc1; destruct Hfc1 as [Hm1eq Hb2].
      apply N.eqb_eq in Hm1eq; subst mult; apply N.leb_le in Hb2; apply N.leb_le in HL1.
      inv_some Hfin; subst aF' hF' bF' fCost.
      change (N.to_nat 2%N) with 2 in hlen_sp, hlen_m.
      inversion hbl_sp as [| W_0 W_1 W_2 e1 es1 bsEnd hb1 hblEnd]; subst; [simpl in hlen_sp; clear - hlen_sp; lia |].
      inversion hblEnd; subst; [| simpl in hlen_sp; clear - hlen_sp; lia].
      assert (hE1 : N.to_nat L1 <= e1 + sumList es1)
        by (specialize (hlb_sp 0 ltac:(simpl; lia)); simpl in hlb_sp; clear - L1 hlb_sp; lia).
      destruct (OneBlock_liftS1 (N.to_nat aF / 2) (N.to_nat bF - 1) Hm1 ltac:(clear - Hb2; lia) hb1 ltac:(clear - L1 HmFdiv HL1 hE1; lia))
        as [es1' [hp1 hsum1]].
      replace (N.to_nat bF - 1 + 1) with (N.to_nat bF) in hp1 by (clear - Hb2; lia).
      replace (2 * (N.to_nat aF / 2) + 1) with (N.to_nat (aF + 1)%N) in hp1 by (clear - Ha; lia).
      rewrite <- Ha in hp1.
      exists (es_pre ++ es1').
      split.
      + exact (PureP2_append (PureP2_liftCell (N.to_nat aF) true (N.to_nat bF) (or_introl eq_refl) ltac:(clear - Hb2; lia) hp_pre) hp1).
      + rewrite sumList_append. simpl sumList in hsum_sp.
        try (rewrite hlen_m in hsum_sp); try (rewrite hlen_m in hgeScF); try (rewrite HscF_eq in hsum_sp); try (rewrite HscF_eq in hgeScF).
        clear - L1 totIn totCost HmFdiv HL1 hE1 hsum1 hsum_sp hgeScF hsum_m hge_m HtotIn_eq Htot; unfold totCost; lia.
    - (* stF = 2 *)
      simpl ((2 =? 0)%N) in Hfin; simpl ((2 =? 1)%N) in Hfin; discriminate. }
  destruct hFinalP2 as [esF [hpF hsumF]].
  pose proof (applySinkDumpBig_sound hsuf') as hd.
  replace (N.to_nat (totIn - totCost)%N) with (sumList esF) in hd by (clear - totIn totCost Htot hsumF; lia).
  pose proof (PureP2_dump hpF hd) as hstep.
  unfold HubCfg.
  assert (hL : encItems (RIsingle a0 h0 b0_v [] None :: rest) =
               ((((encS (N.to_nat a0) h0 (N.to_nat b0_v) [] None ++ encActiveGroups midGs) ++ encItems spF) ++
                 encS (N.to_nat aF) hF (N.to_nat bF) [] None) ++ encItems suf)).
  { simpl encItems; simpl encItem.
    rewrite hallEnc, hallEq, encActiveGroups_append; simpl encActiveGroups.
    rewrite !encSingle_eq_encS; simpl option_map.
    rewrite ?app_nil_r, ?append_assoc. reflexivity. }
  assert (hR : encItems (RIsingle a0' h0' b0' [] None ::
                 itemsOfActiveGroups midGs' ++ spF ++ [RIsingle aF' hF' bF' [] None] ++ suf') =
               ((((encS (N.to_nat a0') h0' (N.to_nat b0') [] None ++ encActiveGroups midGs') ++ encItems spF) ++
                 encS (N.to_nat aF') hF' (N.to_nat bF') [] None) ++ encItems suf')).
  { simpl encItems; simp_encItems_app; rewrite encItems_itemsOfActiveGroups; simpl encItems; simpl encItem.
    rewrite !encSingle_eq_encS; simpl option_map.
    rewrite ?app_nil_r, ?append_assoc. reflexivity. }
  rewrite hL, hR. exact hstep.
Qed.

(* --- ScratchS3B2.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

Lemma encSingle_none_eq_encS (a : N) (h : bool) (b : N) :
  encSingle a h b [] None = encS (N.to_nat a) h (N.to_nat b) [] None.
Proof. exact (encSingle_eq_encS a h b [] None). Qed.

(* ========================================================================= *)
(* Arbitrary-N d0 = 0 Base-3 Odometer (stepOdoD0)                            *)
(* ========================================================================= *)

Definition digBLoss (C s : nat) : nat :=
  2 * (C / 3) +
    if Nat.eqb s 0 then (if Nat.eqb (C mod 3) 0 then 0 else 1)
    else if Nat.eqb s 1 then (if Nat.eqb (C mod 3) 2 then 1 else 0)
    else C mod 3.

Lemma digBLoss_le (C s : nat) : digBLoss C s <= 2 * (C / 3) + 2.
Proof.
  unfold digBLoss.
  pose proof (Nat.mod_upper_bound C 3 ltac:(lia)).
  destruct (Nat.eqb s 0), (Nat.eqb s 1), (Nat.eqb (C mod 3) 0), (Nat.eqb (C mod 3) 2); lia.
Qed.

Lemma digBLoss_s0 (C : nat) : digBLoss (C + 1) 0 = 1 + digBLoss C 1.
Proof.
  unfold digBLoss.
  pose proof (Nat.div_mod C 3 ltac:(lia)).
  pose proof (Nat.mod_upper_bound C 3 ltac:(lia)).
  pose proof (Nat.div_mod (C + 1) 3 ltac:(lia)).
  pose proof (Nat.mod_upper_bound (C + 1) 3 ltac:(lia)).
  simpl (Nat.eqb 0 0); simpl (Nat.eqb 1 0); simpl (Nat.eqb 1 1).
  destruct (Nat.eqb ((C + 1) mod 3) 0) eqn:E1;
    [apply Nat.eqb_eq in E1 | apply Nat.eqb_neq in E1];
  (destruct (Nat.eqb (C mod 3) 2) eqn:E2;
    [apply Nat.eqb_eq in E2 | apply Nat.eqb_neq in E2]); lia.
Qed.

Lemma digBLoss_s1 (C : nat) : digBLoss (C + 1) 1 = digBLoss C 2.
Proof.
  unfold digBLoss.
  pose proof (Nat.div_mod C 3 ltac:(lia)).
  pose proof (Nat.mod_upper_bound C 3 ltac:(lia)).
  pose proof (Nat.div_mod (C + 1) 3 ltac:(lia)).
  pose proof (Nat.mod_upper_bound (C + 1) 3 ltac:(lia)).
  simpl (Nat.eqb 1 0); simpl (Nat.eqb 1 1); simpl (Nat.eqb 2 0); simpl (Nat.eqb 2 1).
  destruct (Nat.eqb ((C + 1) mod 3) 2) eqn:E1;
    [apply Nat.eqb_eq in E1 | apply Nat.eqb_neq in E1]; lia.
Qed.

Lemma digBLoss_s2 (C : nat) : digBLoss (C + 1) 2 = 1 + digBLoss C 0.
Proof.
  unfold digBLoss.
  pose proof (Nat.div_mod C 3 ltac:(lia)).
  pose proof (Nat.mod_upper_bound C 3 ltac:(lia)).
  pose proof (Nat.div_mod (C + 1) 3 ltac:(lia)).
  pose proof (Nat.mod_upper_bound (C + 1) 3 ltac:(lia)).
  simpl (Nat.eqb 2 0); simpl (Nat.eqb 2 1); simpl (Nat.eqb 0 0).
  destruct (Nat.eqb (C mod 3) 0) eqn:E1;
    [apply Nat.eqb_eq in E1 | apply Nat.eqb_neq in E1]; lia.
Qed.

Lemma digState_nat_cases (aa : nat) (hh : bool) (s : nat) (hds : digState_nat aa hh = Some s) :
  (s = 0 /\ hh = true /\ aa = 2 * (aa / 2) + 1) \/
  (s = 1 /\ hh = true /\ 1 <= aa / 2 /\ aa = 2 * (aa / 2)) \/
  (s = 2 /\ hh = false /\ aa = 2 * (aa / 2) + 1).
Proof.
  unfold digState_nat in hds.
  pose proof (Nat.div_mod aa 2 ltac:(lia)).
  pose proof (Nat.mod_upper_bound aa 2 ltac:(lia)).
  destruct hh.
  - destruct (Nat.eqb (aa mod 2) 1) eqn:Hodd.
    + apply Nat.eqb_eq in Hodd. inv_some hds; subst s.
      left; split; [reflexivity | split; [reflexivity | lia]].
    + apply Nat.eqb_neq in Hodd.
      destruct (Nat.leb 2 aa) eqn:Ha2; [| discriminate].
      apply Nat.leb_le in Ha2. inv_some hds; subst s.
      right; left; split; [reflexivity | split; [reflexivity | split; lia]].
  - destruct (Nat.eqb (aa mod 2) 1) eqn:Hodd; [| discriminate].
    apply Nat.eqb_eq in Hodd. inv_some hds; subst s.
    right; right; split; [reflexivity | split; [reflexivity | lia]].
Qed.

Lemma BlockList_liftDigitD0_aux : forall {Wa Wb : list Sym} {l : list nat}
    (hbl0 : BlockList Wa Wb l) (aa : nat) (hh : bool) (bb s M : nat),
  digState_nat aa hh = Some s ->
  digBLoss (List.length l) s + 2 <= bb ->
  aa / 2 + bb + 2 <= M ->
  (forall e, List.In e l -> M <= e) ->
  let '(aR, hR, bR, cR, CR) := digStepN_nat (List.length l) aa hh bb in
  exists p2' bs', BlockStream (Wa ++ encS aa hh bb [] None)
      (Wb ++ encS aR hR bR [] None) p2' bs' /\
    List.length bs' = CR /\
    p2' + sumList bs' = sumList l - cR /\
    cR <= sumList l /\
    (forall e, List.In e bs' -> M - (aa / 2 + bb) <= e).
Proof.
  intros Wa Wb l hbl0.
  induction hbl0 as [W0 | W0 W1 W2 e0 es0 l' hb0 hrest IH];
    intros aa hh bb s M hds0 hb0_ge hM0 hfl0.
  - cbn [List.length digStepN_nat]; cbv beta iota zeta.
    exists 0, (@nil nat); cbn [List.length sumList].
    split; [exact (BlockStream_nil _) |].
    split; [reflexivity | split; [lia | split; [lia | intros _unused_x hm; contradiction]]].
  - set (E0 := e0 + sumList es0) in *.
    assert (hE0 : M <= E0) by (apply hfl0; simpl; left; reflexivity).
    assert (hfl' : forall e, List.In e l' -> M <= e)
      by (intros e he; apply hfl0; simpl; right; exact he).
    assert (hlenS : List.length (E0 :: l') = List.length l' + 1) by (simpl; lia).
    destruct (digState_nat_cases aa hh s hds0) as
      [[Hs [Hh Haa]] | [[Hs [Hh [Hm1 Haa]]] | [Hs [Hh Haa]]]]; subst s hh.
    + (* s = 0 *)
      set (m := aa / 2) in *.
      pose proof (digBLoss_s0 (List.length l')) as hbl_eq.
      rewrite hlenS, hbl_eq in hb0_ge.
      assert (hds1 : digState_nat (2 * m + 2) true = Some 1).
      { unfold digState_nat.
        assert (Hev : Nat.eqb ((2 * m + 2) mod 2) 1 = false).
        { apply Nat.eqb_neq. pose proof (Nat.div_mod (2 * m + 2) 2 ltac:(lia)); lia. }
        assert (Hge2 : Nat.leb 2 (2 * m + 2) = true) by (apply Nat.leb_le; lia).
        rewrite Hev, Hge2; reflexivity. }
      assert (hdiv1 : (2 * m + 2) / 2 = m + 1).
      { pose proof (Nat.div_mod (2 * m + 2) 2 ltac:(lia));
        pose proof (Nat.mod_upper_bound (2 * m + 2) 2 ltac:(lia)); lia. }
      destruct (OneBlock_liftS0 m (bb - 1) ltac:(lia) hb0 ltac:(lia)) as [es' [hp hsum']].
      replace (bb - 1 + 1) with bb in hp by lia.
      rewrite <- Haa in hp.
      pose proof (IH (2 * m + 2) true (bb - 1) 1 M hds1 ltac:(lia) ltac:(lia) hfl') as Hrec.
      assert (hstep1 : digStep1_nat aa true bb = (2 * m + 2, true, bb - 1, m, false)).
      { unfold digStep1_nat.
        assert (Hodd : Nat.eqb (aa mod 2) 1 = true).
        { apply Nat.eqb_eq. pose proof (Nat.div_mod aa 2 ltac:(lia)); lia. }
        rewrite Hodd. eq_tuple; lia. }
      cbn [List.length digStepN_nat]; rewrite hstep1; cbv beta iota zeta.
      destruct (digStepN_nat (List.length l') (2 * m + 2) true (bb - 1)) as [[[[aR hR] bR] cR] CR]. cbv beta iota zeta.
      destruct Hrec as [p2' [bs' [hs' [hlen' [hsum1 [hle1 hfl1]]]]]].
      exists (sumList es' + p2'), bs'.
      split; [exact (BlockStream_consPureP2 hp hs') |].
      split; [lia |].
      simpl sumList; fold E0.
      split; [lia | split; [lia |]].
      intros e he; specialize (hfl1 e he); lia.
    + (* s = 1 *)
      set (m := aa / 2) in *.
      pose proof (digBLoss_s1 (List.length l')) as hbl_eq.
      rewrite hlenS, hbl_eq in hb0_ge.
      assert (hds1 : digState_nat (2 * m + 1) false = Some 2).
      { unfold digState_nat.
        assert (Hodd : Nat.eqb ((2 * m + 1) mod 2) 1 = true).
        { apply Nat.eqb_eq. pose proof (Nat.div_mod (2 * m + 1) 2 ltac:(lia));
          pose proof (Nat.mod_upper_bound (2 * m + 1) 2 ltac:(lia)); lia. }
        rewrite Hodd; reflexivity. }
      assert (hdiv1 : (2 * m + 1) / 2 = m).
      { pose proof (Nat.div_mod (2 * m + 1) 2 ltac:(lia));
        pose proof (Nat.mod_upper_bound (2 * m + 1) 2 ltac:(lia)); lia. }
      destruct (OneBlock_liftS1 m (bb - 1) Hm1 ltac:(lia) hb0 ltac:(lia)) as [es' [hp hsum']].
      replace (bb - 1 + 1) with bb in hp by lia.
      replace (W0 ++ encS (2 * m) true bb [] None) with (W0 ++ encS aa true bb [] None) in hp
        by (rewrite <- Haa; reflexivity).
      pose proof (IH (2 * m + 1) false bb 2 M hds1 ltac:(lia) ltac:(lia) hfl') as Hrec.
      assert (hstep1 : digStep1_nat aa true bb = (2 * m + 1, false, bb, m, false)).
      { unfold digStep1_nat.
        assert (Hev : Nat.eqb (aa mod 2) 1 = false).
        { apply Nat.eqb_neq. pose proof (Nat.div_mod aa 2 ltac:(lia)); lia. }
        rewrite Hev. eq_tuple; lia. }
      cbn [List.length digStepN_nat]; rewrite hstep1; cbv beta iota zeta.
      destruct (digStepN_nat (List.length l') (2 * m + 1) false bb) as [[[[aR hR] bR] cR] CR].
      cbv beta iota zeta in Hrec |- *.
      destruct Hrec as [p2' [bs' [hs' [hlen' [hsum1 [hle1 hfl1]]]]]].
      exists (sumList es' + p2'), bs'.
      split; [exact (BlockStream_consPureP2 hp hs') |].
      split; [lia |].
      simpl sumList; fold E0.
      split; [lia | split; [lia |]].
      intros e he; specialize (hfl1 e he); lia.
    + (* s = 2 *)
      set (m := aa / 2) in *.
      pose proof (digBLoss_s2 (List.length l')) as hbl_eq.
      rewrite hlenS, hbl_eq in hb0_ge.
      assert (hds1 : digState_nat (2 * m + 1) true = Some 0).
      { unfold digState_nat.
        assert (Hodd : Nat.eqb ((2 * m + 1) mod 2) 1 = true).
        { apply Nat.eqb_eq. pose proof (Nat.div_mod (2 * m + 1) 2 ltac:(lia));
          pose proof (Nat.mod_upper_bound (2 * m + 1) 2 ltac:(lia)); lia. }
        rewrite Hodd; reflexivity. }
      assert (hdiv1 : (2 * m + 1) / 2 = m).
      { pose proof (Nat.div_mod (2 * m + 1) 2 ltac:(lia));
        pose proof (Nat.mod_upper_bound (2 * m + 1) 2 ltac:(lia)); lia. }
      destruct (OneBlock_liftS2 m (bb - 2) hb0 ltac:(lia)) as [e0' [es' [hblk' hsum']]].
      replace (bb - 2 + 2) with bb in hblk' by lia.
      replace (bb - 2 + 1) with (bb - 1) in hblk' by lia.
      replace (W0 ++ encS (2 * m + 1) false bb [] None) with (W0 ++ encS aa false bb [] None) in hblk'
        by (rewrite <- Haa; reflexivity).
      pose proof (IH (2 * m + 1) true (bb - 1) 0 M hds1 ltac:(lia) ltac:(lia) hfl') as Hrec.
      assert (hstep1 : digStep1_nat aa false bb = (2 * m + 1, true, bb - 1, m + bb, true)).
      { unfold digStep1_nat. eq_tuple; lia. }
      cbn [List.length digStepN_nat]; rewrite hstep1; cbv beta iota zeta.
      destruct (digStepN_nat (List.length l') (2 * m + 1) true (bb - 1)) as [[[[aR hR] bR] cR] CR].
      cbv beta iota zeta in Hrec |- *.
      destruct Hrec as [p2' [bs' [hs' [hlen' [hsum1 [hle1 hfl1]]]]]].
      exists 0, ((e0' + sumList es' + p2') :: bs').
      split; [exact (BlockStream_consBlock hblk' hs') |].
      simpl List.length; simpl sumList; fold E0.
      split; [lia | split; [lia | split; [lia |]]].
      intros e [<- | he]; [lia | specialize (hfl1 e he); lia].
Qed.

Lemma BlockStream_liftDigitD0 {W W' : list Sym} {p2 : nat} {bs : list nat}
    (a : nat) (h : bool) (b M : nat)
    (hs : BlockStream W W' p2 bs)
    (hds : isSome (digState_nat a h) = true)
    (hb : 2 * (List.length bs / 3) + 4 <= b)
    (hM : a / 2 + b + 2 <= M)
    (hfloor : forall e, List.In e bs -> M <= e) :
    let '(aR, hR, bR, cR, CR) := digStepN_nat (List.length bs) a h b in
    exists p2' bs', BlockStream (W ++ encS a h b [] None)
        (W' ++ encS aR hR bR [] None) p2' bs' /\
      List.length bs' = CR /\
      p2' + sumList bs' = p2 + sumList bs - cR /\
      cR <= sumList bs /\
      (forall e, List.In e bs' -> M - (a / 2 + b) <= e).
Proof.
  destruct hs as [Wm [es_pre [hp_pre [hsum_pre hbl]]]].
  destruct (digState_nat a h) as [s0|] eqn:HdsE; [| simpl in hds; discriminate].
  pose proof (digBLoss_le (List.length bs) s0) as Hloss.
  pose proof (BlockList_liftDigitD0_aux hbl a h b s0 M HdsE ltac:(lia) hM hfloor) as Haux.
  assert (hcellOk : h = true \/ (1 <= a /\ 2 <= b)).
  { destruct (digState_nat_cases a h s0 HdsE) as [[_ [-> _]] | [[_ [-> _]] | [_ [-> Ha]]]];
      [left; reflexivity | left; reflexivity | right; lia]. }
  pose proof (PureP2_liftCell a h b hcellOk ltac:(lia) hp_pre) as hp_pre'.
  destruct (digStepN_nat (List.length bs) a h b) as [[[[aR hR] bR] cR] CR].
  cbv beta iota zeta in Haux |- *.
  destruct Haux as [p2' [bs' [hs' [hlen' [hsum' [hle' hfl']]]]]].
  exists (p2 + p2'), bs'.
  pose proof (BlockStream_consPureP2 hp_pre' hs') as Hcs.
  rewrite hsum_pre in Hcs.
  split; [exact Hcs | split; [exact hlen' | split; [lia | split; [exact hle' | exact hfl']]]].
Qed.

Lemma runD0Digits_sound : forall (gs : list ActiveGroup)
    {W W' : list Sym} {p2 : nat} {Cv Mv : N} {bs : list nat}
    {gs' : list ActiveGroup} {totCost Cf Mf : N},
  (forall g, List.In g gs -> ActiveGroupOk g) ->
  BlockStream W W' p2 bs ->
  List.length bs = N.to_nat Cv ->
  (forall e, List.In e bs -> N.to_nat Mv <= e) ->
  runD0Digits Cv Mv gs = Some (gs', totCost, Cf, Mf) ->
  exists p2' bs', BlockStream (W ++ encActiveGroups gs) (W' ++ encActiveGroups gs') p2' bs' /\
    List.length bs' = N.to_nat Cf /\
    p2' + sumList bs' = p2 + sumList bs - N.to_nat totCost /\
    N.to_nat totCost <= p2 + sumList bs /\
    (forall e, List.In e bs' -> N.to_nat Mf <= e).
Proof.
  induction gs as [|[[[sp a] h] b] gs_rest IH];
    intros W W' p2 Cv Mv bs gs' totCost Cf Mf hall hs hlen hfl hrun.
  - simpl in hrun. inv_some hrun; subst.
    simpl encActiveGroups; rewrite ?app_nil_r.
    exists p2, bs.
    split; [exact hs | split; [exact hlen | split; [lia | split; [lia | exact hfl]]]].
  - assert (hg : ActiveGroupOk (sp, a, h, b)) by (apply hall; simpl; left; reflexivity).
    destruct hg as [htr_sp hds_a].
    assert (hrest : forall x, List.In x gs_rest -> ActiveGroupOk x)
      by (intros x hx; apply hall; simpl; right; exact hx).
    cbn [runD0Digits] in hrun.
    set (sc := transpListCost sp) in *.
    destruct ((Mv <? sc)%N) eqn:HMsc; [discriminate |].
    apply N.ltb_ge in HMsc.
    set (M1 := (Mv - sc)%N) in *.
    destruct (((a <? 1)%N || (b <? 2 * (Cv / 3) + 4)%N || (M1 <? a / 2 + b + 2)%N)%bool) eqn:Hbad;
      [discriminate |].
    apply orb_false_elim in Hbad; destruct Hbad as [Hbad1 HM1].
    apply orb_false_elim in Hbad1; destruct Hbad1 as [Ha1 Hb4].
    apply N.ltb_ge in Ha1; apply N.ltb_ge in Hb4; apply N.ltb_ge in HM1.
    pose proof (N2Nat_div Cv 3) as HCdiv; change (N.to_nat 3%N) with 3 in HCdiv.
    pose proof (N2Nat_div a 2) as Hadiv; change (N.to_nat 2%N) with 2 in Hadiv.
    pose proof (digStepFast_eq_digStepN a h b Cv Ha1 ltac:(lia) hds_a) as Hfast.
    destruct (digStepFast a h b Cv) as [[[[aF hF] bF] costF] CF] eqn:Hdf.
    set (M2 := (M1 - (a / 2 + b))%N) in *.
    apply option_map_Some in hrun.
    destruct hrun as [[[[gsR' cRest] Cf'] Mf'] [hrec heq]].
    inv_some heq; subst gs' totCost Cf Mf.
    assert (Hsc_eq : transpListCost_nat sp = N.to_nat sc) by reflexivity.
    assert (hmemSc : forall e, List.In e bs -> transpListCost_nat sp <= e).
    { intros e he; specialize (hfl e he); rewrite Hsc_eq; lia. }
    pose proof (BlockStream_liftTranspList sp htr_sp hs hmemSc) as hs1.
    assert (hfl1 : forall e, List.In e (List.map (fun x => x - transpListCost_nat sp) bs) -> N.to_nat M1 <= e).
    { intros e he. apply List.in_map_iff in he. destruct he as [x [<- hx]].
      specialize (hfl x hx); unfold M1; rewrite Hsc_eq; lia. }
    assert (hlen1 : List.length (List.map (fun x => x - transpListCost_nat sp) bs) = N.to_nat Cv)
      by (rewrite List.length_map; exact hlen).
    pose proof (sum_map_sub bs (transpListCost_nat sp) hmemSc) as hsum1.
    pose proof (list_len_mul_le_sum bs (transpListCost_nat sp) hmemSc) as hgeSc.
    assert (hds_nat : isSome (digState_nat (N.to_nat a) h) = true)
      by (rewrite <- digState_isSome_to_nat; exact hds_a).
    pose proof (BlockStream_liftDigitD0 (N.to_nat a) h (N.to_nat b) (N.to_nat M1)
                  hs1 hds_nat ltac:(rewrite hlen1; lia) ltac:(lia) hfl1) as Hlift.
    rewrite hlen1, <- Hfast in Hlift; cbv beta iota zeta in Hlift.
    destruct Hlift as [p2_2 [bs2 [hs2 [hlen2 [hsum2 [hle2 hfl2]]]]]].
    rewrite hsum1 in hsum2, hle2.
    rewrite hlen, Hsc_eq in hsum2, hle2, hgeSc.
    assert (hfl2' : forall e, List.In e bs2 -> N.to_nat M2 <= e).
    { intros e he; specialize (hfl2 e he); unfold M2; lia. }
    rewrite <- !encSingle_none_eq_encS in hs2.
    destruct (IH _ _ _ _ _ _ _ _ _ _ hrest hs2 hlen2 hfl2' hrec)
      as [p2_3 [bs3 [hs3 [hlen3 [hsum3 [hle3 hfl3]]]]]].
    exists p2_3, bs3.
    split; [simpl encActiveGroups; (rewrite ?append_assoc in hs3; rewrite ?append_assoc); exact hs3 |].
    clearbody sc.
    split; [exact hlen3 | split; [clear - hsum3 hle3 hsum2 hle2 hgeSc; nia | split; [clear - hsum3 hle3 hsum2 hle2 hgeSc; nia | exact hfl3]]].
Qed.

Lemma stepOdoD0_sound {k : nat} {Nv : N} {items items' : list RleItem}
    (h : stepOdoD0 k Nv items = Some items') :
    HubCfg items -[ tm ]->* HubCfg items'.
Proof.
  unfold stepOdoD0 in h.
  destruct ((Nv =? 0)%N) eqn:HN0; [discriminate |].
  apply N.eqb_neq in HN0.
  destruct items as [|[a0 h0 b0_v [|? ?] [?|] | | |] rest]; try discriminate.
  destruct (negb (c0Valid a0 h0 b0_v && (Nv + (if h0 then 4 else 5) <=? b0_v)%N && (b0_v + 1 <=? a0 / 2)%N)) eqn:Hc0;
    [discriminate |].
  apply negb_false_iff in Hc0.
  apply andb_prop in Hc0; destruct Hc0 as [Hc0a He0].
  apply andb_prop in Hc0a; destruct Hc0a as [Hv0 Hb0].
  apply N.leb_le in Hb0; apply N.leb_le in He0.
  pose proof (N2Nat_div a0 2) as Ha0div. change (N.to_nat 2%N) with 2 in Ha0div.
  pose proof (c0Valid_to_nat a0 h0 b0_v Hv0) as hv0_nat.
  destruct (splitActivePrefix k rest) as [[gs suf]|] eqn:Hsp; [| discriminate].
  destruct (splitActivePrefixAux_sound rest k [] gs suf eq_refl Hsp) as [_ [hall henc]].
  simpl in henc.
  set (M0 := c0E1 a0 h0 b0_v) in *.
  destruct (runD0Digits Nv M0 gs) as [[[[gs' totCost] Cf] Mf]|] eqn:Hrun; [| discriminate].
  destruct (negb (Cf =? 0)%N) eqn:HCf; [discriminate |].
  apply negb_false_iff in HCf; apply N.eqb_eq in HCf; subst Cf.
  set (totIn := c0TotalIn a0 h0 b0_v Nv) in *.
  destruct ((totIn <? totCost)%N) eqn:Htot; [discriminate |].
  apply N.ltb_ge in Htot.
  set (E_rem := (totIn - totCost)%N) in *.
  destruct (applySinkDumpBig E_rem suf) as [suf'|] eqn:Hsuf'; [| discriminate].
  pose proof (c0StepN_to_nat a0 h0 b0_v Nv) as Hc0N.
  destruct (c0StepN a0 h0 b0_v Nv) as [[aN hN] bN].
  inv_some h; subst items'.
  pose proof (c0_blockStream (N.to_nat a0) h0 (N.to_nat b0_v) (N.to_nat Nv)
                hv0_nat ltac:(destruct h0; lia) ltac:(lia)) as Hbs0.
  rewrite <- Hc0N in Hbs0; cbv beta iota zeta in Hbs0.
  destruct Hbs0 as [bs0 [hs0 [hlen0 [hsum0 hlb0]]]].
  assert (hfl0 : forall e, List.In e bs0 -> N.to_nat M0 <= e).
  { unfold M0; rewrite c0E1_to_nat.
    eapply (BlockLB_mem_ge hlb0); lia. }
  destruct (runD0Digits_sound gs hall hs0 hlen0 hfl0 Hrun)
    as [p2' [bs' [hs' [hlen' [hsum' [hle' _]]]]]].
  destruct bs' as [|? ?]; [| simpl in hlen'; lia].
  simpl sumList in hsum'.
  pose proof (applySinkDumpBig_sound Hsuf') as hd.
  assert (hp2_eq : N.to_nat E_rem = p2').
  { unfold E_rem, totIn; rewrite N2Nat.inj_sub, c0TotalIn_to_nat; lia. }
  rewrite hp2_eq in hd.
  rewrite <- !encSingle_none_eq_encS in hs'.
  pose proof (BlockStream_dumpNil hs' hd) as hstep.
  unfold HubCfg.
  assert (hL : encItems (RIsingle a0 h0 b0_v [] None :: rest) =
               ((encSingle a0 h0 b0_v [] None ++ encActiveGroups gs) ++ encItems suf)).
  { simpl encItems; simpl encItem; rewrite henc, ?append_assoc; reflexivity. }
  assert (hR : encItems (RIsingle aN hN bN [] None :: itemsOfActiveGroups gs' ++ suf') =
               ((encSingle aN hN bN [] None ++ encActiveGroups gs') ++ encItems suf')).
  { simpl encItems; rewrite encItems_append, encItems_itemsOfActiveGroups; simpl encItem;
      rewrite ?append_assoc; reflexivity. }
  rewrite hL, hR. exact hstep.
Qed.

(* ========================================================================= *)
(* Section 11.3: Universal TRANSP_RUN Eater Engine (stepEater)               *)
(* ========================================================================= *)

Definition DirectBlock (W W' : list Sym) (e : nat) : Prop := HubP1 e W W'.

Lemma PureP2_nil_eq {W W' : list Sym} (h : PureP2 W W' []) : W = W'.
Proof. inversion h; reflexivity. Qed.

Lemma DirectBlock_toOneBlock {W W' : list Sym} {e : nat} (h : DirectBlock W W' e) :
    OneBlock W W' e [].
Proof.
  exists W'. split; [exact h | exact (PureP2_nil W')].
Qed.

Lemma OneBlock_toDirect {W W' : list Sym} {e : nat} (h : OneBlock W W' e []) :
    DirectBlock W W' e.
Proof.
  destruct h as [Wm [hp1 hpp]].
  rewrite <- (PureP2_nil_eq hpp). exact hp1.
Qed.

Lemma c0_directBlock (a0 : nat) (h0 : bool) (b0_v : nat)
    (hv : c0Valid_nat a0 h0 b0_v = true) (hpos : 1 <= c0E1_nat a0 h0 b0_v) :
    let '(a1, h1, b1) := c0Step1_nat a0 h0 b0_v in
    DirectBlock (encS a0 h0 b0_v [] None) (encS a1 h1 b1 [] None) (c0E1_nat a0 h0 b0_v).
Proof.
  pose proof (c0_oneBlock a0 h0 b0_v hv hpos) as hc.
  destruct (c0Step1_nat a0 h0 b0_v) as [[a1 h1] b1].
  cbv beta iota zeta in hc |- *.
  exact (OneBlock_toDirect hc).
Qed.

Inductive DirectBlockList : list Sym -> list Sym -> list nat -> Prop :=
  | DirectBlockList_nil (W : list Sym) : DirectBlockList W W []
  | DirectBlockList_cons {W W1 W' : list Sym} {e : nat} {bs : list nat}
      (hb : DirectBlock W W1 e) (hrest : DirectBlockList W1 W' bs) :
      DirectBlockList W W' (e :: bs).

Lemma DirectBlockList_toBlockList {W W' : list Sym} {bs : list nat}
    (h : DirectBlockList W W' bs) : BlockList W W' bs.
Proof.
  induction h as [W0 | W0 W1 W2 e bs hb _ IH].
  - exact (BlockList_nil W0).
  - pose proof (BlockList_cons (DirectBlock_toOneBlock hb) IH) as hc.
    simpl sumList in hc; rewrite Nat.add_0_r in hc. exact hc.
Qed.

Lemma DirectBlockList_splitAt : forall (n : nat) {W W' : list Sym} {bs : list nat},
  DirectBlockList W W' bs -> n <= List.length bs ->
  exists Wm bs1 bs2, DirectBlockList W Wm bs1 /\ DirectBlockList Wm W' bs2 /\
    bs = bs1 ++ bs2 /\ List.length bs1 = n.
Proof.
  induction n as [|n' IH]; intros W W' bs h hn.
  - exists W, (@nil nat), bs.
    split; [exact (DirectBlockList_nil W) | split; [exact h | split; reflexivity]].
  - inversion h as [| W0 W1 W2 e bs' hb hrest]; subst; [simpl in hn; lia |].
    destruct (IH _ _ _ hrest ltac:(simpl in hn; lia))
      as [Wm [bs1 [bs2 [h1 [h2 [heq hlen]]]]]].
    exists Wm, (e :: bs1), bs2.
    split; [exact (DirectBlockList_cons hb h1) |].
    split; [exact h2 | split; [simpl; congruence | simpl; lia]].
Qed.

Lemma c0_directBlockList : forall (Nv a0 : nat) (h0 : bool) (b0_v : nat),
  c0Valid_nat a0 h0 b0_v = true ->
  Nv + (if h0 then 4 else 5) <= b0_v ->
  b0_v + 1 <= a0 / 2 ->
  let '(aN, hN, bN) := c0StepN_nat a0 h0 b0_v Nv in
  exists bs, DirectBlockList (encS a0 h0 b0_v [] None) (encS aN hN bN [] None) bs /\
    List.length bs = Nv /\
    sumList bs = c0TotalIn_nat a0 h0 b0_v Nv /\
    (forall e, List.In e bs -> c0E1_nat a0 h0 b0_v <= e).
Proof.
  induction Nv as [|n IH]; intros a0 h0 b0_v hv hb he.
  - rewrite c0StepN_zero, c0TotalIn_zero; cbv beta iota zeta.
    exists (@nil nat).
    split; [exact (DirectBlockList_nil _) |].
    split; [reflexivity | split; [reflexivity | intros _unused_x hm; contradiction]].
  - assert (hpos : 1 <= c0E1_nat a0 h0 b0_v) by (unfold c0E1_nat; destruct h0; lia).
    pose proof (c0_directBlock a0 h0 b0_v hv hpos) as hblk.
    pose proof (c0Valid_step1 hv ltac:(destruct h0; lia)) as hv1.
    pose proof (c0E1_step1_ge hv ltac:(lia)) as hge1.
    pose proof (c0StepN_succ a0 h0 b0_v n) as hstepN.
    pose proof (@c0TotalIn_succ a0 h0 b0_v n hv ltac:(lia)) as htot.
    destruct (c0Step1_nat a0 h0 b0_v) as [[a1 h1] b1] eqn:Hs1;
      cbv beta iota zeta in hblk, hv1, hge1, hstepN, htot.
    assert (hb_next : n + (if h1 then 4 else 5) <= b1).
    { unfold c0Step1_nat in Hs1; destruct h0; inversion Hs1; subst; lia. }
    assert (he_next : b1 + 1 <= a1 / 2).
    { unfold c0Step1_nat in Hs1; destruct h0; inversion Hs1; subst;
      pose proof (Nat.div_mod a0 2 ltac:(lia));
      pose proof (Nat.div_mod (a0 + 3) 2 ltac:(lia));
      pose proof (Nat.mod_upper_bound a0 2 ltac:(lia));
      pose proof (Nat.mod_upper_bound (a0 + 3) 2 ltac:(lia)); lia. }
    pose proof (IH a1 h1 b1 hv1 hb_next he_next) as Hrec.
    replace (S n) with (n + 1) by lia.
    rewrite hstepN, htot.
    destruct (c0StepN_nat a1 h1 b1 n) as [[aN hN] bN]; cbv beta iota zeta in Hrec |- *.
    destruct Hrec as [bs' [hbl' [hlen' [hsum' hfl']]]].
    exists (c0E1_nat a0 h0 b0_v :: bs').
    split; [exact (DirectBlockList_cons hblk hbl') |].
    split; [simpl; lia | split; [simpl; lia |]].
    intros e [<- | hm]; [lia | specialize (hfl' e hm); lia].
Qed.

Lemma BlockList_liftCyclesS2_floor : forall (Qv : nat) {W W' : list Sym} {bs : list nat}
    (m b E0 : nat),
  BlockList W W' bs ->
  List.length bs = 3 * Qv ->
  2 * Qv + 2 <= b ->
  m + b + 3 <= E0 ->
  (forall e, List.In e bs -> E0 <= e) ->
  exists bs', BlockList (W ++ encS (2 * m + 1) false b [] None)
      (W' ++ encS (2 * (m + Qv) + 1) false (b - 2 * Qv) [] None) bs' /\
    List.length bs' = Qv /\
    sumList bs' = sumList bs - digCycleCost_nat (2 * m + 1) false b Qv /\
    digCycleCost_nat (2 * m + 1) false b Qv <= sumList bs /\
    (forall e, List.In e bs' -> 3 * E0 - (3 * m + b + Qv) <= e).
Proof.
  induction Qv as [|q IH]; intros W W' bs m b E0 hbl hlen hb hE0 hfl.
  - inversion hbl; subst; [| simpl in hlen; lia].
    replace (m + 0) with m by lia.
    replace (b - 2 * 0) with b by lia.
    exists (@nil nat).
    split; [exact (BlockList_nil _) |].
    unfold digCycleCost_nat; simpl.
    split; [reflexivity | split; [lia | split; [lia | intros _unused_x hm; contradiction]]].
  - inversion hbl as [| Wa W1 Wz e1 es1 l1 hb1 hbl1]; subst; [simpl in hlen; lia |].
    inversion hbl1 as [| Wb W2 Wz2 e2 es2 l2 hb2 hbl2]; subst; [simpl in hlen; lia |].
    inversion hbl2 as [| Wc W3 Wz3 e3 es3 bs_rest hb3 hbl3]; subst; [simpl in hlen; lia |].
    set (E1 := e1 + sumList es1) in *.
    set (E2 := e2 + sumList es2) in *.
    set (E3 := e3 + sumList es3) in *.
    assert (hE1 : E0 <= E1) by (apply hfl; simpl; left; reflexivity).
    assert (hE2 : E0 <= E2) by (apply hfl; simpl; right; left; reflexivity).
    assert (hE3 : E0 <= E3) by (apply hfl; simpl; right; right; left; reflexivity).
    assert (hflR : forall e, List.In e bs_rest -> E0 <= e)
      by (intros e he; apply hfl; simpl; right; right; right; exact he).
    destruct (liftDigitCycle m (b - 2) ltac:(lia) hb1 hb2 hb3 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia))
      as [e0' [es' [hbc hsumc]]].
    replace (b - 2 + 2) with b in hbc by lia.
    destruct (IH _ _ _ (m + 1) (b - 2) E0 hbl3 ltac:(simpl in hlen; lia) ltac:(lia) ltac:(lia) hflR)
      as [bsR [hblR [hlenR [hsumR [hleR hflR']]]]].
    replace (2 * (m + 1) + 1) with (2 * m + 3) in hblR, hsumR, hleR by lia.
    replace (2 * (m + 1 + q) + 1) with (2 * (m + S q) + 1) in hblR by lia.
    replace (b - 2 - 2 * q) with (b - 2 * S q) in hblR by lia.
    assert (hdc_succ : digCycleCost_nat (2 * m + 1) false b (S q) =
                       (3 * m + b + 1) + digCycleCost_nat (2 * m + 3) false (b - 2) q).
    { replace (S q) with (q + 1) by lia.
      rewrite (digCycleCost_succ (2 * m + 1) false b q ltac:(lia)).
      rewrite digCycleCost_s2_one.
      replace (2 * m + 1 + 2) with (2 * m + 3) by lia. reflexivity. }
    exists ((e0' + sumList es') :: bsR).
    split; [exact (BlockList_cons hbc hblR) |].
    simpl List.length; simpl sumList; fold E1 E2 E3.
    split; [lia | split; [lia | split; [lia |]]].
    intros e [<- | he]; [lia | specialize (hflR' e he); lia].
Qed.

Lemma pow_pred_succ_sym (T : list Sym) {n : nat} (hn : 1 <= n) :
    T ^^ n = (T ^^ (n - 1)) ++ T.
Proof.
  rewrite <- list_pow_succ_right. replace (n - 1 + 1) with n by lia. reflexivity.
Qed.

Lemma eater_hub2_p2 {W1 W2 : list Sym} {E2 : nat}
    (m' k B_tr : nat) (hk : 1 <= k) (hB : 2 <= B_tr)
    (hb2 : DirectBlock W1 W2 E2) (hE2 : m' + 1 <= E2) :
    HubP2B (E2 - m')
      ((W1 ++ encS (2 * m' + 1) true 1 [] None) ++ encS (2 * k) false B_tr [] None)
      ((W2 ++ encS (2 * m' + 2) true 0 [] None) ++ encS (2 * k) false B_tr [] None).
Proof.
  assert (hstep : forall (bb : nat), 1 <= bb -> forall (r : Stream Sym),
    exists L', PipeL (E2 - m' - 1)
        ((W2 ++ encS (2 * m' + 2) true 0 [] None) ++ encS (2 * k) false bb [] None) L' /\
      (b0 {{E}}> (T2 *> T0 *> T1 *>
        ((W1 ++ encS (2 * m' + 1) true 1 [] None) ++ encS (2 * k) false bb [] None) *> r))
        -[ tm ]->* (([S1] *> T2 *> L') {{A}}> r)).
  { intros bb hbb r.
    destruct (hb2 (encS (2 * m' + 1) true 1 [] None ++ encS (2 * k) false bb [] None) r)
      as [cfg0 [hpe0 hs0]].
    assert (hpe0' : P1Entry E2 W2
        ((((T2 ^^ (2 * m' + 1)) ++ T5) ++ (T4 ^^ (0 + 1))) ++ encS (2 * k) false bb [] None) r cfg0).
    { unfold encS in hpe0 |- *; cbn [encSegTail] in hpe0 |- *.
      (rewrite ?app_nil_r in hpe0; rewrite ?list_pow_one in hpe0; rewrite ?append_assoc in hpe0; rewrite ?app_nil_r; rewrite ?list_pow_one; rewrite ?append_assoc). exact hpe0. }
    destruct (p1Entry_h1_enter_odd m' 0 hE2 hpe0') as [L1 [hpL1 hs1]].
    destruct (pipeL_mid_h0 (2 * k - 1) (bb - 1) hpL1 r) as [L2 [hpL2 hs2]].
    exists L2.
    split.
    - eapply pipeL_eqR; [| exact hpL2].
      unfold encS; cbn [encSegTail].
      replace (2 * k - 1 + 1) with (2 * k) by lia.
      replace (bb - 1 + 1) with bb by lia.
      rewrite ?list_pow_zero, ?app_nil_r, ?append_assoc. reflexivity.
    - rewrite append_assoc.
      eapply evstep_trans; [exact hs0 |].
      eapply evstep_trans; [exact hs1 |].
      assert (hM : encS (2 * k) false bb [] None *> r =
                   (T2 ^^ (2 * k - 1 + 1)) *> (T4 ^^ (bb - 1 + 1)) *> r).
      { unfold encS; cbn [encSegTail].
        replace (2 * k - 1 + 1) with (2 * k) by lia.
        replace (bb - 1 + 1) with bb by lia.
        rewrite ?app_nil_r, Str_app_assoc. reflexivity. }
      rewrite hM. exact hs2. }
  split; [lia | split; [exact (hstep B_tr ltac:(lia)) |]].
  intros Wp hWp.
  assert (hsplit : (W1 ++ encS (2 * m' + 1) true 1 [] None) ++ encS (2 * k) false B_tr [] None =
                   ((W1 ++ encS (2 * m' + 1) true 1 [] None) ++ encS (2 * k) false (B_tr - 1) [] None) ++ T4).
  { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r; rewrite (@pow_pred_succ_sym T4 B_tr ltac:(lia)); rewrite ?append_assoc.
    reflexivity. }
  assert (hWpEq : Wp = (W1 ++ encS (2 * m' + 1) true 1 [] None) ++ encS (2 * k) false (B_tr - 1) [] None).
  { apply (@app_cancel_right _ _ _ T4). congruence. }
  subst Wp.
  exists ((W2 ++ encS (2 * m' + 2) true 0 [] None) ++ encS (2 * k) false (B_tr - 1) [] None).
  split.
  - unfold encS; cbn [encSegTail]. rewrite ?app_nil_r; rewrite (@pow_pred_succ_sym T4 B_tr ltac:(lia)); rewrite ?append_assoc.
    reflexivity.
  - exact (hstep (B_tr - 1) ltac:(lia)).
Qed.

Lemma eater_hub3_p2 {W2 W3 : list Sym} {E3 : nat}
    (m' k B_tr : nat) (_hk : 1 <= k) (hB : 2 <= B_tr)
    (hb3 : DirectBlock W2 W3 E3) (hE3 : m' + 2 <= E3) :
    HubP2B (E3 - (m' + 1))
      ((W2 ++ encS (2 * m' + 2) true 0 [] None) ++ encS (2 * k) false B_tr [] None)
      (W3 ++ encS (2 * (m' + k + 1) + 1) false B_tr [] None).
Proof.
  assert (hstep : forall (bb : nat), 1 <= bb -> forall (r : Stream Sym),
    exists L', PipeL (E3 - (m' + 1) - 1)
        (W3 ++ encS (2 * (m' + k + 1) + 1) false bb [] None) L' /\
      (b0 {{E}}> (T2 *> T0 *> T1 *>
        ((W2 ++ encS (2 * m' + 2) true 0 [] None) ++ encS (2 * k) false bb [] None) *> r))
        -[ tm ]->* (([S1] *> T2 *> L') {{A}}> r)).
  { intros bb hbb r.
    destruct (hb3 (encS (2 * m' + 2) true 0 [] None ++ encS (2 * k) false bb [] None) r)
      as [cfg0 [hpe0 hs0]].
    assert (hpe0' : P1Entry E3 W3
        ((T2 ^^ (2 * (m' + 1))) ++ (T5 ++ (T2 ^^ (2 * k)) ++ (T4 ^^ bb))) r cfg0).
    { unfold encS in hpe0 |- *; cbn [encSegTail] in hpe0 |- *.
      replace (2 * (m' + 1)) with (2 * m' + 2) by lia.
      (rewrite ?list_pow_zero in hpe0; rewrite ?app_nil_r in hpe0; rewrite ?append_assoc in hpe0; rewrite ?list_pow_zero; rewrite ?app_nil_r; rewrite ?append_assoc). exact hpe0. }
    destruct (p1Entry_eat_t2_even (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) (m' + 1) ltac:(lia) ltac:(lia) hpe0') as [L1 [hp1 hs1]].
    assert (hE1eq : E3 - (m' + 1) = (E3 - (m' + 1) - 1) + 1) by lia.
    pose proof (pipeL_eqE hE1eq hp1) as hp1'.
    destruct (PipeL_head0 hp1') as [l1 hl1].
    destruct (PipeL_pull hp1') as [L2 [hpull hp2]].
    pose proof (pull1_t3_t5 (2 * (m' + 1)) hl1 hpull (((T2 ^^ (2 * k)) ++ (T4 ^^ bb)) *> r)) as hs2.
    pose proof (rule_q0_t2 (2 * k) ((T3 ^^ (2 * (m' + 1) + 1)) *> T2 *> L2) ((T4 ^^ bb) *> r)) as hs3.
    assert (hT3pow : (T3 ^^ (2 * k)) *> (T3 ^^ (2 * (m' + 1) + 1)) *> T2 *> L2 =
                     (T3 ^^ (2 * (m' + k + 1) + 1)) *> T2 *> L2).
    { rewrite <- pow_add_blank. replace (2 * k + (2 * (m' + 1) + 1)) with (2 * (m' + k + 1) + 1) by lia.
      reflexivity. }
    assert (hs4 : (([S1] *> (T3 ^^ (2 * (m' + k + 1) + 1)) *> T2 *> L2) {{A}}> ((T4 ^^ bb) *> r))
                    -[ tm ]->*
                  (([S1] *> T2 *> (T5 ^^ (bb - 1)) *> T4 *> (T3 ^^ (2 * (m' + k + 1))) *> T2 *> L2) {{A}}> r)).
    { replace (2 * (m' + k + 1) + 1) with (S (2 * (m' + k + 1))) by lia.
      replace (T4 ^^ bb) with (T4 ^^ S (bb - 1)) by (f_equal; lia).
      rewrite !zPsr.
      eapply evstep_trans; [apply step_q0_t4_first | apply rule_q0_t4_next]. }
    pose proof (pipeL_T2_blk (bb - 1) (2 * (m' + k + 1)) hp2) as hblk.
    exists ((T5 ^^ (bb - 1)) *> T4 *> (T3 ^^ (2 * (m' + k + 1))) *> T2 *> L2).
    split.
    - eapply pipeL_eqR; [| exact hblk].
      unfold encS; cbn [encSegTail].
      replace (bb - 1 + 1) with bb by lia.
      rewrite ?app_nil_r, ?append_assoc. reflexivity.
    - rewrite append_assoc.
      eapply evstep_trans; [exact hs0 |].
      eapply evstep_trans; [exact hs1 |].
      (rewrite ?Str_app_assoc in hs2; rewrite ?Str_app_assoc).
      eapply evstep_trans; [exact hs2 |].
      eapply evstep_trans; [exact hs3 |].
      rewrite hT3pow. exact hs4. }
  split; [lia | split; [exact (hstep B_tr ltac:(lia)) |]].
  intros Wp hWp.
  assert (hsplit : (W2 ++ encS (2 * m' + 2) true 0 [] None) ++ encS (2 * k) false B_tr [] None =
                   ((W2 ++ encS (2 * m' + 2) true 0 [] None) ++ encS (2 * k) false (B_tr - 1) [] None) ++ T4).
  { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r; rewrite (@pow_pred_succ_sym T4 B_tr ltac:(lia)); rewrite ?append_assoc.
    reflexivity. }
  assert (hWpEq : Wp = (W2 ++ encS (2 * m' + 2) true 0 [] None) ++ encS (2 * k) false (B_tr - 1) [] None).
  { apply (@app_cancel_right _ _ _ T4). congruence. }
  subst Wp.
  exists (W3 ++ encS (2 * (m' + k + 1) + 1) false (B_tr - 1) [] None).
  split.
  - unfold encS; cbn [encSegTail]. rewrite ?app_nil_r; rewrite (@pow_pred_succ_sym T4 B_tr ltac:(lia)); rewrite ?append_assoc.
    reflexivity.
  - exact (hstep (B_tr - 1) ltac:(lia)).
Qed.

Lemma eater_absorb_3hubs {W0 W1 W2 W3 : list Sym} {E1 E2 E3 : nat}
    (m' k B_tr : nat) (hk : 1 <= k) (hB : 2 <= B_tr)
    (hb1 : DirectBlock W0 W1 E1) (hb2 : DirectBlock W1 W2 E2) (hb3 : DirectBlock W2 W3 E3)
    (hE1 : m' + 2 + (k + B_tr) <= E1) (hE2 : m' + 1 <= E2) (hE3 : m' + 2 <= E3) :
    exists e0' es', OneBlock
        ((W0 ++ encS (2 * m' + 1) false 2 [] None) ++ encS (2 * k) false B_tr [] None)
        (W3 ++ encS (2 * (m' + k + 1) + 1) false B_tr [] None) e0' es' /\
      e0' + sumList es' = E1 + E2 + E3 - (3 * m' + 3 + (k + B_tr)).
Proof.
  destruct (OneBlock_liftS2 m' 0 (DirectBlock_toOneBlock hb1) ltac:(simpl; lia))
    as [e1 [es1 [h1 hs1]]].
  simpl sumList in hs1.
  destruct (OneBlock_liftTransp k (B_tr - 2) hk h1 ltac:(lia))
    as [e1' [es1' [h1' hs1']]].
  replace (B_tr - 2 + 2) with B_tr in h1' by lia.
  pose proof (PureP2_cons (eater_hub2_p2 m' k B_tr hk hB hb2 hE2) (PureP2_nil _)) as hp2.
  pose proof (PureP2_cons (eater_hub3_p2 m' k B_tr hk hB hb3 hE3) (PureP2_nil _)) as hp3.
  pose proof (OneBlock_appendP2 (OneBlock_appendP2 h1' hp2) hp3) as h123.
  exists e1', ((es1' ++ [E2 - m']) ++ [E3 - (m' + 1)]).
  split; [exact h123 |].
  simp_sumList; simpl sumList; lia.
Qed.

Definition eaterConst_nat (B_tr : nat) : nat :=
  let q := B_tr / 2 - 1 in
  q * (B_tr + 1) + (q * (q - 1)) / 2 + 3 * q + 3.

Definition eaterC1Cost_nat (ah1 d_ah1 B_tr Mv : nat) : nat :=
  let N_eat := 3 * (B_tr / 2) in
  Mv * (ah1 * N_eat + eaterConst_nat B_tr) + (d_ah1 * N_eat) * (Mv * (Mv - 1) / 2).

Definition eaterC2Cost_nat (T_tr B_tr rep Mv : nat) : nat :=
  let C_eat := B_tr / 2 in
  (T_tr * C_eat) * (Mv * rep - Mv * (Mv - 1) / 2).

Lemma eaterConst_to_nat (B_tr : N) :
  N.to_nat (eaterConst B_tr) = eaterConst_nat (N.to_nat B_tr).
Proof.
  unfold eaterConst, eaterConst_nat; cbv beta zeta.
  pose proof (N2Nat_div B_tr 2) as Hdiv; change (N.to_nat 2%N) with 2 in Hdiv.
  set (qN := (B_tr / 2 - 1)%N).
  pose proof (N2Nat_div (qN * (qN - 1))%N 2) as Htri; change (N.to_nat 2%N) with 2 in Htri.
  replace (N.to_nat (qN * (qN - 1))%N) with (N.to_nat qN * (N.to_nat qN - 1)) in Htri by nia.
  assert (Hq : N.to_nat qN = N.to_nat B_tr / 2 - 1) by (unfold qN; lia).
  nia.
Qed.

Lemma eaterC1Cost_to_nat (ah1 d_ah1 B_tr Mv : N) :
  N.to_nat (eaterC1Cost ah1 d_ah1 B_tr Mv) =
  eaterC1Cost_nat (N.to_nat ah1) (N.to_nat d_ah1) (N.to_nat B_tr) (N.to_nat Mv).
Proof.
  unfold eaterC1Cost, eaterC1Cost_nat; cbv beta zeta.
  pose proof (N2Nat_div B_tr 2) as Hdiv; change (N.to_nat 2%N) with 2 in Hdiv.
  pose proof (N2Nat_div (Mv * (Mv - 1))%N 2) as Htri; change (N.to_nat 2%N) with 2 in Htri.
  replace (N.to_nat (Mv * (Mv - 1))%N) with (N.to_nat Mv * (N.to_nat Mv - 1)) in Htri by nia.
  simp_N2Nat; rewrite eaterConst_to_nat, Hdiv, Htri.
  reflexivity.
Qed.

Lemma eaterC2Cost_to_nat (T_tr B_tr rep Mv : N) :
  N.to_nat (eaterC2Cost T_tr B_tr rep Mv) =
  eaterC2Cost_nat (N.to_nat T_tr) (N.to_nat B_tr) (N.to_nat rep) (N.to_nat Mv).
Proof.
  unfold eaterC2Cost, eaterC2Cost_nat; cbv beta zeta.
  pose proof (N2Nat_div B_tr 2) as Hdiv; change (N.to_nat 2%N) with 2 in Hdiv.
  pose proof (N2Nat_div (Mv * (Mv - 1))%N 2) as Htri; change (N.to_nat 2%N) with 2 in Htri.
  replace (N.to_nat (Mv * (Mv - 1))%N) with (N.to_nat Mv * (N.to_nat Mv - 1)) in Htri by nia.
  simp_N2Nat; rewrite Hdiv, Htri.
  reflexivity.
Qed.

Lemma eater_1cycle_c1cost (ah1 B_tr : nat) (hB4 : 4 <= B_tr) (hBev : B_tr mod 2 = 0) :
    digCycleCost_nat (2 * ah1 + 1) false B_tr (B_tr / 2 - 1) + (3 * (ah1 + (B_tr / 2 - 1)) + 3) =
    ah1 * (3 * (B_tr / 2)) + eaterConst_nat B_tr.
Proof.
  unfold digCycleCost_nat, eaterConst_nat; cbv beta zeta; cbn [andb].
  pose proof (Nat.div_mod B_tr 2 ltac:(lia)).
  pose proof (Nat.div_mod (2 * ah1 + 1) 2 ltac:(lia)).
  pose proof (Nat.mod_upper_bound (2 * ah1 + 1) 2 ltac:(lia)).
  assert (Hdiv : (2 * ah1 + 1) / 2 = ah1) by lia.
  rewrite Hdiv.
  set (q := B_tr / 2 - 1).
  assert (HB : B_tr = 2 * (q + 1)) by lia.
  assert (HB2 : B_tr / 2 = q + 1) by lia.
  rewrite HB2; replace (q + 1 - 1) with q by lia.
  nia.
Qed.

Definition encTranspRun_nat (a b rep : nat) : list Sym :=
  ((T2 ^^ a) ++ (T4 ^^ b)) ^^ rep.

Lemma encItem_transpRun_eq (a b rep : N) :
  encItem (RItranspRun a b rep) = encTranspRun_nat (N.to_nat a) (N.to_nat b) (N.to_nat rep).
Proof. reflexivity. Qed.

Lemma eater_1cycle {W0 W1 : list Sym} {bs : list nat}
    (ah1 k B_tr rep E0 : nat) (hk : 1 <= k) (hB4 : 4 <= B_tr) (hBev : B_tr mod 2 = 0) (hrep : 1 <= rep)
    (hdbl : DirectBlockList W0 W1 bs) (hlen : List.length bs = 3 * (B_tr / 2))
    (hE0 : ah1 + B_tr + 3 + rep * (k + B_tr) <= E0) (hfl : forall e, List.In e bs -> E0 <= e) :
    let C_eat := B_tr / 2 in
    let T_tr := k + B_tr in
    let c1_cost := ah1 * (3 * C_eat) + eaterConst_nat B_tr in
    let c2_cost := C_eat * rep * T_tr in
    exists bs', BlockList
        ((W0 ++ encS (2 * ah1 + 1) false B_tr [] None) ++ encTranspRun_nat (2 * k) B_tr rep)
        ((W1 ++ encS (2 * (ah1 + k + C_eat) + 1) false B_tr [] None) ++ encTranspRun_nat (2 * k) B_tr (rep - 1))
        bs' /\
      List.length bs' = C_eat /\
      sumList bs' = sumList bs - (c1_cost + c2_cost) /\
      c1_cost + c2_cost <= sumList bs /\
      (forall e, List.In e bs' -> E0 - (ah1 + B_tr + 3 + rep * T_tr) <= e).
Proof.
  set (C_eat := B_tr / 2) in *.
  set (q_eat := C_eat - 1) in *.
  set (T_tr := k + B_tr) in *.
  pose proof (Nat.div_mod B_tr 2 ltac:(lia)) as HBdiv.
  assert (HC_pos : 2 <= C_eat) by (unfold C_eat; lia).
  destruct (DirectBlockList_splitAt (3 * q_eat) hdbl ltac:(lia))
    as [Wm [bs_q [bs_3 [hdbl_q [hdbl_3 [hbs_eq hlen_q]]]]]].
  assert (hlen_3 : List.length bs_3 = 3).
  { pose proof (f_equal (@List.length nat) hbs_eq) as H; rewrite List.length_app in H; lia. }
  assert (hfl_q : forall e, List.In e bs_q -> E0 <= e)
    by (intros e he; apply hfl; rewrite hbs_eq; apply List.in_or_app; left; exact he).
  assert (hfl_3 : forall e, List.In e bs_3 -> E0 <= e)
    by (intros e he; apply hfl; rewrite hbs_eq; apply List.in_or_app; right; exact he).
  destruct (BlockList_liftCyclesS2_floor q_eat ah1 B_tr E0
              (DirectBlockList_toBlockList hdbl_q) hlen_q ltac:(lia) ltac:(lia) hfl_q)
    as [bs_q1 [hbl_q1 [hlen_q1 [hsum_q1 [hle_q1 hfl_q1]]]]].
  set (trItem := RItranspRun (N.of_nat (2 * k)) (N.of_nat B_tr) (N.of_nat rep)).
  assert (htc : transpListCost_nat [trItem] = rep * T_tr).
  { unfold transpListCost_nat, transpListCost, transpItemCost, trItem.
    pose proof (N2Nat_div (N.of_nat (2 * k)) 2) as Hd; change (N.to_nat 2%N) with 2 in Hd.
    rewrite ?Nat2N.id in Hd; rewrite ?Nat2N.id.
    simp_N2Nat; rewrite !Nat2N.id, Hd.
    pose proof (Nat.div_mod (2 * k) 2 ltac:(lia));
    pose proof (Nat.mod_upper_bound (2 * k) 2 ltac:(lia)); unfold T_tr; lia. }
  assert (hrep_ge : forall e, List.In e bs_q1 -> transpListCost_nat [trItem] <= e).
  { intros e he; specialize (hfl_q1 e he); rewrite htc; lia. }
  assert (htr_rep : isTranspList [trItem] = true).
  { unfold isTranspList, isTranspItem, trItem; simpl List.forallb; rewrite Bool.andb_true_r.
    pose proof (N2Nat_mod (N.of_nat (2 * k)) 2) as Hm; change (N.to_nat 2%N) with 2 in Hm; rewrite Nat2N.id in Hm.
    pose proof (Nat.div_mod (2 * k) 2 ltac:(lia));
    pose proof (Nat.mod_upper_bound (2 * k) 2 ltac:(lia)).
    repeat (apply andb_true_intro; split);
      try (apply N.leb_le; lia);
      apply N.eqb_eq; lia. }
  pose proof (BlockList_liftTranspList [trItem] htr_rep hbl_q1 hrep_ge) as hbl_q2.
  assert (henc_tr : encItems [trItem] = encTranspRun_nat (2 * k) B_tr rep).
  { unfold trItem; cbn [encItems]; rewrite app_nil_r, encItem_transpRun_eq, !Nat2N.id; reflexivity. }
  rewrite henc_tr in hbl_q2.
  replace (B_tr - 2 * q_eat) with 2 in hbl_q2 by lia.
  revert hbs_eq.
  inversion hdbl_3 as [| Wa W_a Wz1 E1 l3_1 hb1 h3_1]; subst; [simpl in hlen_3; lia |].
  inversion h3_1 as [| Wb W_b Wz2 E2 l3_2 hb2 h3_2]; subst; [simpl in hlen_3; lia |].
  inversion h3_2 as [| Wc W_c Wz3 E3 l3_3 hb3 h3_3]; subst; [simpl in hlen_3; lia |].
  inversion h3_3; subst; [| simpl in hlen_3; lia].
  intros hbs_eq.
  assert (hE1 : E0 <= E1) by (apply hfl_3; simpl; left; reflexivity).
  assert (hE2 : E0 <= E2) by (apply hfl_3; simpl; right; left; reflexivity).
  assert (hE3 : E0 <= E3) by (apply hfl_3; simpl; right; right; left; reflexivity).
  assert (hTtr_le : T_tr <= rep * T_tr) by nia.
  destruct (eater_absorb_3hubs (ah1 + q_eat) k B_tr hk ltac:(lia) hb1 hb2 hb3 ltac:(lia) ltac:(lia) ltac:(lia))
    as [e3 [es3 [hblk3 hsum3]]].
  destruct (OneBlock_liftTranspRun (rep - 1) k (B_tr - 2) hk hblk3 ltac:(nia))
    as [e3' [es3' [hblk3' hsum3']]].
  replace (B_tr - 2 + 2) with B_tr in hblk3' by lia.
  replace (k + (B_tr - 2) + 2) with T_tr in hsum3' by (unfold T_tr; lia).
  replace (ah1 + q_eat + k + 1) with (ah1 + k + C_eat) in hblk3' by lia.
  assert (hLmid : ((Wm ++ encS (2 * (ah1 + q_eat) + 1) false 2 [] None) ++ encS (2 * k) false B_tr [] None) ++
                    (((T2 ^^ (2 * k)) ++ (T4 ^^ B_tr)) ^^ (rep - 1)) =
                  (Wm ++ encS (2 * (ah1 + q_eat) + 1) false 2 [] None) ++ encTranspRun_nat (2 * k) B_tr rep).
  { rewrite <- List.app_assoc; f_equal.
    replace rep with ((rep - 1) + 1) at 2 by lia.
    unfold encTranspRun_nat; rewrite list_pow_succ; f_equal.
    unfold encS; cbn [encSegTail]; rewrite ?list_pow_zero, ?app_nil_r, ?append_assoc; reflexivity. }
  rewrite hLmid in hblk3'.
  fold (encTranspRun_nat (2 * k) B_tr (rep - 1)) in hblk3'.
  pose proof (BlockList_append hbl_q2 (BlockList_cons hblk3' (BlockList_nil _))) as hcomb.
  pose proof (sum_map_sub bs_q1 (transpListCost_nat [trItem]) hrep_ge) as hsum_q2.
  pose proof (list_len_mul_le_sum bs_q1 (transpListCost_nat [trItem]) hrep_ge) as hq_rep_le.
  rewrite hlen_q1, htc in hq_rep_le.
  pose proof (eater_1cycle_c1cost ah1 B_tr hB4 hBev) as hc1_eq.
  fold C_eat q_eat in hc1_eq.
  assert (hbs_sum : sumList bs = sumList bs_q + (E1 + E2 + E3)).
  { rewrite hbs_eq, sumList_append; simpl sumList; lia. }
  fold T_tr in hsum3.
  assert (hrT : T_tr + (rep - 1) * T_tr = rep * T_tr).
  { assert (hr : rep = (rep - 1) + 1) by lia. clear - hr; rewrite hr at 2; clear hr; nia. }
  assert (hc2_eq : q_eat * (rep * T_tr) + rep * T_tr = C_eat * rep * T_tr).
  { rewrite <- (Nat.mul_assoc C_eat rep T_tr).
    assert (hq : C_eat = q_eat + 1) by lia. rewrite hq; set (RT := rep * T_tr); clear; nia. }
  assert (he3_ge : 3 * (ah1 + q_eat) + 3 + rep * T_tr <= E1 + E2 + E3).
  { clear - hE0 hE1 hE2 hE3 HBdiv hBev HC_pos; fold C_eat in HBdiv; lia. }
  assert (he3_eq : e3' + sumList es3' = (E1 + E2 + E3) - (3 * (ah1 + q_eat) + 3 + rep * T_tr)).
  { clear - hsum3 hsum3' hrT he3_ge; lia. }
  exists (List.map (fun b => b - transpListCost_nat [trItem]) bs_q1 ++ [e3' + sumList es3']).
  split; [exact hcomb |].
  rewrite List.length_app, List.length_map, sumList_append, hsum_q2, hlen_q1, htc; simpl List.length; simpl sumList.
  split; [clear - HC_pos; lia |
    split; [clear - hsum_q1 hle_q1 hq_rep_le hc1_eq hc2_eq hbs_sum he3_eq he3_ge; clearbody C_eat q_eat T_tr; lia |
    split; [clear - hsum_q1 hle_q1 hq_rep_le hc1_eq hc2_eq hbs_sum he3_ge; clearbody C_eat q_eat T_tr; lia |]]].
  intros e he. apply List.in_app_iff in he.
  destruct he as [he | [<- | []]].
  - apply List.in_map_iff in he. destruct he as [x [<- hx]].
    specialize (hfl_q1 x hx); clear - hfl_q1 hE0 HBdiv hBev HC_pos; fold C_eat in HBdiv; lia.
  - clear - he3_eq he3_ge hE0 hE1 hE2 hE3 HBdiv hBev HC_pos; fold C_eat in HBdiv; lia.
Qed.

Lemma eater_tri_succ (m : nat) : ((m + 1) * (m + 1 - 1)) / 2 = m + (m * (m - 1)) / 2.
Proof.
  destruct m as [|m']; [reflexivity |].
  replace (S m' + 1 - 1) with (S m') by lia.
  replace (S m' - 1) with m' by lia.
  pose proof (Nat.div_mod (S m' * m') 2 ltac:(lia)) as Hq.
  pose proof (Nat.mod_upper_bound (S m' * m') 2 ltac:(lia)) as Hqm.
  pose proof (Nat.div_mod ((S m' + 1) * S m') 2 ltac:(lia)) as Hq1.
  pose proof (Nat.mod_upper_bound ((S m' + 1) * S m') 2 ltac:(lia)) as Hqm1.
  assert (Hev : (S m' * m') mod 2 = 0) by (destruct (div2_cases m'); nia).
  nia.
Qed.

Lemma eaterC1Cost_succ (ah1 d_ah1 B_tr m : nat) :
    eaterC1Cost_nat ah1 d_ah1 B_tr (m + 1) =
    (ah1 * (3 * (B_tr / 2)) + eaterConst_nat B_tr) + eaterC1Cost_nat (ah1 + d_ah1) d_ah1 B_tr m.
Proof.
  unfold eaterC1Cost_nat; cbv beta zeta. rewrite eater_tri_succ.
  set (N_eat := 3 * (B_tr / 2)).
  set (DN := d_ah1 * N_eat).
  set (AN := ah1 * N_eat).
  set (EC := eaterConst_nat B_tr).
  set (tri := (m * (m - 1)) / 2).
  assert (ha : (ah1 + d_ah1) * N_eat = AN + DN) by (unfold AN, DN; apply Nat.mul_add_distr_r).
  rewrite ha; clear - ha; clear ha; clearbody N_eat DN AN EC tri; nia.
Qed.

Lemma eaterC2Cost_succ (T_tr B_tr rep m : nat) (hrep : m + 1 <= rep) :
    eaterC2Cost_nat T_tr B_tr rep (m + 1) =
    (B_tr / 2) * rep * T_tr + eaterC2Cost_nat T_tr B_tr (rep - 1) m.
Proof.
  unfold eaterC2Cost_nat; cbv beta zeta. rewrite eater_tri_succ.
  assert (hm_le : (m * (m - 1)) / 2 <= m * (rep - 1)).
  { pose proof (Nat.div_mod (m * (m - 1)) 2 ltac:(lia)); nia. }
  set (C_eat := B_tr / 2).
  set (TC := T_tr * C_eat).
  assert (hcomm : C_eat * rep * T_tr = TC * rep).
  { unfold TC; rewrite (Nat.mul_comm T_tr C_eat), <- !(Nat.mul_assoc C_eat); f_equal; apply Nat.mul_comm. }
  assert (hinner : (m + 1) * rep - (m + (m * (m - 1)) / 2) = rep + (m * (rep - 1) - (m * (m - 1)) / 2)).
  { set (tri := (m * (m - 1)) / 2) in *.
    assert (hr : rep = (rep - 1) + 1) by lia.
    clear - hm_le hr; clearbody tri; rewrite hr at 1 2; clear hr; nia. }
  rewrite hinner, hcomm; apply Nat.mul_add_distr_l.
Qed.

Lemma eater_Mcycles : forall (Mv : nat) {W0 W1 : list Sym} {bs : list nat}
    (ah1 k B_tr rep E0 : nat),
  1 <= k -> 4 <= B_tr -> B_tr mod 2 = 0 -> Mv <= rep ->
  DirectBlockList W0 W1 bs ->
  List.length bs = Mv * (3 * (B_tr / 2)) ->
  ah1 + B_tr + 3 + rep * (k + B_tr) <= E0 ->
  (forall e, List.In e bs -> E0 <= e) ->
  let C_eat := B_tr / 2 in
  let T_tr := k + B_tr in
  let d_ah1 := k + C_eat in
  let c1_cost := eaterC1Cost_nat ah1 d_ah1 B_tr Mv in
  let c2_cost := eaterC2Cost_nat T_tr B_tr rep Mv in
  exists bs', BlockList
      ((W0 ++ encS (2 * ah1 + 1) false B_tr [] None) ++ encTranspRun_nat (2 * k) B_tr rep)
      ((W1 ++ encS (2 * (ah1 + Mv * d_ah1) + 1) false B_tr [] None) ++ encTranspRun_nat (2 * k) B_tr (rep - Mv))
      bs' /\
    List.length bs' = Mv * C_eat /\
    sumList bs' = sumList bs - (c1_cost + c2_cost) /\
    c1_cost + c2_cost <= sumList bs /\
    (forall e, List.In e bs' -> E0 - (ah1 + B_tr + 3 + rep * T_tr) <= e).
Proof.
  induction Mv as [|m IH]; intros W0 W1 bs ah1 k B_tr rep E0 hk hB4 hBev hrep hdbl hlen hE0 hfl.
  - inversion hdbl; subst; [| simpl in hlen; lia].
    cbv zeta.
    replace (ah1 + 0 * (k + B_tr / 2)) with ah1 by lia.
    replace (rep - 0) with rep by lia.
    exists (@nil nat).
    split; [exact (BlockList_nil _) |].
    unfold eaterC1Cost_nat, eaterC2Cost_nat; simpl.
    split; [reflexivity | split; [lia | split; [lia | intros _unused_x hm; contradiction]]].
  - set (C_eat := B_tr / 2) in *.
    set (T_tr := k + B_tr) in *.
    set (d_ah1 := k + C_eat) in *.
    destruct (DirectBlockList_splitAt (3 * C_eat) hdbl ltac:(simpl in hlen; lia))
      as [Wm [bs1 [bs_rest [hdbl1 [hdblR [hbs_eq hlen1]]]]]].
    assert (hlenR : List.length bs_rest = m * (3 * C_eat)).
    { pose proof (f_equal (@List.length nat) hbs_eq) as H; rewrite List.length_app in H; simpl in hlen; lia. }
    assert (hfl1 : forall e, List.In e bs1 -> E0 <= e)
      by (intros e he; apply hfl; rewrite hbs_eq; apply List.in_or_app; left; exact he).
    assert (hflR : forall e, List.In e bs_rest -> E0 <= e)
      by (intros e he; apply hfl; rewrite hbs_eq; apply List.in_or_app; right; exact he).
    destruct (eater_1cycle ah1 k B_tr rep E0 hk hB4 hBev ltac:(lia) hdbl1 hlen1 hE0 hfl1)
      as [bs1' [hbl1' [hlen1' [hsum1' [hle1' hfl1']]]]].
    assert (hmono : (ah1 + d_ah1) + B_tr + 3 + (rep - 1) * T_tr <= ah1 + B_tr + 3 + rep * T_tr).
    { assert (hrT : T_tr + (rep - 1) * T_tr = rep * T_tr)
        by (assert (hr : rep = (rep - 1) + 1) by lia; clear - hr; rewrite hr at 2; clear hr; nia).
      pose proof (Nat.div_mod B_tr 2 ltac:(lia)) as HBdiv.
      clear - hrT HBdiv hBev; unfold d_ah1, T_tr, C_eat in *; lia. }
    destruct (IH _ _ _ (ah1 + d_ah1) k B_tr (rep - 1) E0 hk hB4 hBev ltac:(lia) hdblR hlenR ltac:(lia) hflR)
      as [bsR' [hblR' [hlenR' [hsumR' [hleR' hflR']]]]].
    fold C_eat T_tr in hbl1', hlen1', hsum1', hle1', hfl1', hblR', hlenR', hsumR', hleR', hflR'.
    fold d_ah1 in hblR', hsumR', hleR', hflR'.
    replace (ah1 + k + C_eat) with (ah1 + d_ah1) in hbl1' by lia.
    replace (ah1 + d_ah1 + m * d_ah1) with (ah1 + S m * d_ah1) in hblR' by (simpl; lia).
    replace (rep - 1 - m) with (rep - S m) in hblR' by lia.
    replace (S m) with (m + 1) in * by lia.
    pose proof (eaterC1Cost_succ ah1 d_ah1 B_tr m) as hc1_step; fold C_eat in hc1_step.
    pose proof (eaterC2Cost_succ T_tr B_tr rep m hrep) as hc2_step; fold C_eat in hc2_step.
    assert (hbs_sum : sumList bs = sumList bs1 + sumList bs_rest)
      by (rewrite hbs_eq, sumList_append; reflexivity).
    exists (bs1' ++ bsR').
    fold C_eat T_tr; fold d_ah1.
    split; [exact (BlockList_append hbl1' hblR') |].
    rewrite List.length_app, sumList_append, hlen1', hlenR', hc1_step, hc2_step.
    split; [clear; nia | split; [clear - hbs_sum hsum1' hle1' hsumR' hleR'; clearbody C_eat T_tr d_ah1; lia |
      split; [clear - hbs_sum hsum1' hle1' hleR'; clearbody C_eat T_tr d_ah1; lia |]]].
    intros e he. apply List.in_app_iff in he.
    destruct he as [h1 | h2]; [exact (hfl1' e h1) | specialize (hflR' e h2); clear - hflR' hmono; clearbody C_eat T_tr d_ah1; lia].
Qed.

Lemma stepEater_sound {k : nat} {Mv : N} {items items' : list RleItem}
    (h : stepEater k Mv items = Some items') :
    HubCfg items -[ tm ]->* HubCfg items'.
Proof.
  unfold stepEater in h.
  destruct ((Mv =? 0)%N) eqn:HM0; [discriminate |].
  apply N.eqb_neq in HM0.
  destruct items as [|it0 items1]; [discriminate|].
  destruct it0 as [a0 h0 b0_v [|? ?] [?|] | | |]; try discriminate.
  destruct items1 as [|it1 items2]; [discriminate|].
  destruct it1 as [a1 [|] B_tr [|? ?] [?|] | | |]; try discriminate.
  destruct items2 as [|it2 rest]; [discriminate|].
  destruct it2 as [| A_tr B_tr2 rep | |]; try discriminate.
  destruct (negb ((4 <=? B_tr)%N && (B_tr mod 2 =? 0)%N && (B_tr2 =? B_tr)%N &&
                  (2 <=? A_tr)%N && (A_tr mod 2 =? 0)%N &&
                  (3 <=? a1)%N && (a1 mod 2 =? 1)%N && (Mv + 1 <=? rep)%N)) eqn:Hpar; [discriminate |].
  apply negb_false_iff in Hpar.
  split_andb; subst B_tr2.
  assert (hpar_facts :
    1 <= N.to_nat A_tr / 2 /\
    4 <= N.to_nat B_tr /\
    N.to_nat B_tr mod 2 = 0 /\
    N.to_nat Mv <= N.to_nat rep /\
    2 * N.to_nat (a1 / 2)%N + 1 = N.to_nat a1 /\
    2 * (N.to_nat A_tr / 2) = N.to_nat A_tr /\
    2 * (N.to_nat B_tr / 2) = N.to_nat B_tr /\
    N.to_nat rep - N.to_nat Mv = N.to_nat (rep - Mv)%N).
  { pose proof (N2Nat_div B_tr 2) as HBdiv0; change (N.to_nat 2%N) with 2 in HBdiv0.
    pose proof (N2Nat_mod B_tr 2) as HBmod0; change (N.to_nat 2%N) with 2 in HBmod0.
    pose proof (N2Nat_div A_tr 2) as HAdiv0; change (N.to_nat 2%N) with 2 in HAdiv0.
    pose proof (N2Nat_mod A_tr 2) as HAmod0; change (N.to_nat 2%N) with 2 in HAmod0.
    pose proof (N2Nat_div a1 2) as Ha1div0; change (N.to_nat 2%N) with 2 in Ha1div0.
    pose proof (N2Nat_mod a1 2) as Ha1mod0; change (N.to_nat 2%N) with 2 in Ha1mod0.
    pose proof (Nat.div_mod (N.to_nat B_tr) 2 ltac:(lia)).
    pose proof (Nat.div_mod (N.to_nat A_tr) 2 ltac:(lia)).
    pose proof (Nat.div_mod (N.to_nat a1) 2 ltac:(lia)).
    lia. }
  destruct hpar_facts as [hA2_pos [hB4_nat [hBev_nat [hMv_rep [ha1_eq [hA_eq [hB_eq hrep_sub]]]]]]].
  set (C_eat := (B_tr / 2)%N) in *.
  set (Nv := (Mv * (3 * C_eat))%N) in *.
  destruct (negb (c0Valid a0 h0 b0_v && (Nv + (if h0 then 4 else 5) <=? b0_v)%N && (b0_v + 1 <=? a0 / 2)%N)) eqn:Hc0;
    [discriminate |].
  apply negb_false_iff in Hc0.
  apply andb_prop in Hc0; destruct Hc0 as [Hc0a He0]; apply andb_prop in Hc0a; destruct Hc0a as [Hv0 Hb0].
  apply N.leb_le in Hb0; apply N.leb_le in He0.
  set (ah1 := (a1 / 2)%N) in *.
  set (T_tr := (A_tr / 2 + B_tr)%N) in *.
  set (d_ah1 := (A_tr / 2 + C_eat)%N) in *.
  set (E0 := c0E1 a0 h0 b0_v) in *.
  set (floorCost := (ah1 + B_tr + 3 + rep * T_tr)%N) in *.
  destruct ((E0 <? floorCost)%N) eqn:HE0; [discriminate |].
  apply N.ltb_ge in HE0.
  destruct (splitActivePrefix k rest) as [[gs suf]|] eqn:Hsp; [| discriminate].
  destruct (splitActivePrefixAux_sound rest k [] gs suf eq_refl Hsp) as [_ [hall henc]].
  simpl in henc.
  set (M_out := (E0 - floorCost)%N) in *.
  set (C_out := (Mv * C_eat)%N) in *.
  destruct (runD0Digits C_out M_out gs) as [[[[gs' c3_cost] Cf] Mf]|] eqn:Hrun; [| discriminate].
  destruct (negb (Cf =? 0)%N) eqn:HCf; [discriminate |].
  apply negb_false_iff in HCf; apply N.eqb_eq in HCf; subst Cf.
  set (totIn := c0TotalIn a0 h0 b0_v Nv) in *.
  set (c12_cost := (eaterC1Cost ah1 d_ah1 B_tr Mv + eaterC2Cost T_tr B_tr rep Mv)%N) in *.
  set (totCost := (c12_cost + c3_cost)%N) in *.
  destruct ((totIn <? totCost)%N) eqn:Htot; [discriminate |].
  apply N.ltb_ge in Htot.
  destruct (applySinkDumpBig (totIn - totCost) suf) as [suf'|] eqn:Hsuf'; [| discriminate].
  pose proof (c0StepN_to_nat a0 h0 b0_v Nv) as Hc0N.
  destruct (c0StepN a0 h0 b0_v Nv) as [[aN hN] bN].
  inv_some h; subst items'.
  pose proof (N2Nat_div a0 2) as Ha0div; change (N.to_nat 2%N) with 2 in Ha0div.
  pose proof (N2Nat_div B_tr 2) as HBdiv; change (N.to_nat 2%N) with 2 in HBdiv.
  pose proof (N2Nat_mod B_tr 2) as HBmod; change (N.to_nat 2%N) with 2 in HBmod.
  pose proof (N2Nat_div A_tr 2) as HAdiv; change (N.to_nat 2%N) with 2 in HAdiv.
  pose proof (N2Nat_mod A_tr 2) as HAmod; change (N.to_nat 2%N) with 2 in HAmod.
  pose proof (N2Nat_div a1 2) as Ha1div; change (N.to_nat 2%N) with 2 in Ha1div.
  pose proof (N2Nat_mod a1 2) as Ha1mod; change (N.to_nat 2%N) with 2 in Ha1mod.
  pose proof (c0Valid_to_nat a0 h0 b0_v Hv0) as hv0_nat.
  pose proof (c0_directBlockList (N.to_nat Nv) (N.to_nat a0) h0 (N.to_nat b0_v)
                hv0_nat ltac:(clear - Hb0; destruct h0; lia) ltac:(clear - He0 Ha0div; lia)) as Hdbl0.
  rewrite <- Hc0N in Hdbl0; cbv beta iota zeta in Hdbl0.
  destruct Hdbl0 as [bs0 [hdbl0 [hlen0 [hsum0 hfl0]]]].
  assert (hlen0' : List.length bs0 = N.to_nat Mv * (3 * (N.to_nat B_tr / 2))).
  { unfold Nv, C_eat in hlen0; rewrite !N2Nat.inj_mul, HBdiv in hlen0; exact hlen0. }
  assert (hfl0' : forall e, List.In e bs0 -> N.to_nat E0 <= e).
  { intros e he; unfold E0; rewrite c0E1_to_nat; exact (hfl0 e he). }
  assert (hE0_ok : N.to_nat ah1 + N.to_nat B_tr + 3 + N.to_nat rep * (N.to_nat A_tr / 2 + N.to_nat B_tr) <= N.to_nat E0).
  { clear - HE0 HAdiv; unfold floorCost, T_tr, ah1 in *; rewrite <- HAdiv; clear HAdiv; nia. }
  destruct (eater_Mcycles (N.to_nat Mv) (N.to_nat ah1) (N.to_nat A_tr / 2) (N.to_nat B_tr)
              (N.to_nat rep) (N.to_nat E0)
              hA2_pos hB4_nat hBev_nat hMv_rep hdbl0 hlen0' hE0_ok hfl0')
    as [bs1 [hbl1 [hlen1 [hsum1 [hle1 hfl1]]]]].
  fold ah1 in ha1_eq.
  assert (ha1_fin : 2 * (N.to_nat ah1 + N.to_nat Mv * (N.to_nat A_tr / 2 + N.to_nat B_tr / 2)) + 1 =
                    N.to_nat (a1 + Mv * (A_tr + B_tr))%N).
  { clear - ha1_eq hA_eq hB_eq; clearbody ah1; rewrite N2Nat.inj_add, N2Nat.inj_mul, N2Nat.inj_add; nia. }
  rewrite ha1_eq, hA_eq, ha1_fin, hrep_sub in hbl1.
  rewrite <- !encSingle_none_eq_encS, <- !encItem_transpRun_eq in hbl1.
  assert (hstream1 : BlockStream
      ((encSingle a0 h0 b0_v [] None ++ encSingle a1 false B_tr [] None) ++ encItem (RItranspRun A_tr B_tr rep))
      ((encSingle aN hN bN [] None ++ encSingle (a1 + Mv * (A_tr + B_tr)) false B_tr [] None) ++
        encItem (RItranspRun A_tr B_tr (rep - Mv)))
      0 bs1).
  { exists ((encSingle a0 h0 b0_v [] None ++ encSingle a1 false B_tr [] None) ++ encItem (RItranspRun A_tr B_tr rep)), (@nil nat).
    split; [exact (PureP2_nil _) | split; [reflexivity | exact hbl1]]. }
  assert (hlen1' : List.length bs1 = N.to_nat C_out)
    by (unfold C_out, C_eat; rewrite N2Nat.inj_mul, HBdiv; exact hlen1).
  assert (hfl1' : forall e, List.In e bs1 -> N.to_nat M_out <= e).
  { intros e he; specialize (hfl1 e he);
    clear - hfl1 HE0 HAdiv; unfold M_out, floorCost, T_tr in *; rewrite <- HAdiv in *; clear HAdiv; nia. }
  destruct (runD0Digits_sound gs hall hstream1 hlen1' hfl1' Hrun)
    as [p2' [bs' [hs' [hlen' [hsum' [hle' _]]]]]].
  destruct bs' as [|? ?]; [| simpl in hlen'; lia].
  simpl sumList in hsum'.
  assert (hc12_eq : N.to_nat c12_cost =
                    eaterC1Cost_nat (N.to_nat ah1) (N.to_nat A_tr / 2 + N.to_nat B_tr / 2) (N.to_nat B_tr) (N.to_nat Mv) +
                    eaterC2Cost_nat (N.to_nat A_tr / 2 + N.to_nat B_tr) (N.to_nat B_tr) (N.to_nat rep) (N.to_nat Mv)).
  { unfold c12_cost; rewrite N2Nat.inj_add, eaterC1Cost_to_nat, eaterC2Cost_to_nat.
    replace (N.to_nat d_ah1) with (N.to_nat A_tr / 2 + N.to_nat B_tr / 2)
      by (unfold d_ah1, C_eat; rewrite N2Nat.inj_add, HAdiv, HBdiv; reflexivity).
    replace (N.to_nat T_tr) with (N.to_nat A_tr / 2 + N.to_nat B_tr)
      by (unfold T_tr; rewrite N2Nat.inj_add, HAdiv; reflexivity).
    reflexivity. }
  assert (hp2eq : N.to_nat (totIn - totCost)%N = p2').
  { unfold totIn, totCost in *;
    clear - Htot hsum0 hsum1 hle1 hsum' hle' hc12_eq;
    clearbody Nv ah1 c12_cost;
    rewrite N2Nat.inj_sub, N2Nat.inj_add, c0TotalIn_to_nat, hc12_eq; lia. }
  pose proof (applySinkDumpBig_sound Hsuf') as hd.
  rewrite hp2eq in hd.
  pose proof (BlockStream_dumpNil hs' hd) as hstep.
  unfold HubCfg.
  assert (hL : encItems (RIsingle a0 h0 b0_v [] None :: RIsingle a1 false B_tr [] None ::
                 RItranspRun A_tr B_tr rep :: rest) =
               ((((encSingle a0 h0 b0_v [] None ++ encSingle a1 false B_tr [] None) ++
                   encItem (RItranspRun A_tr B_tr rep)) ++ encActiveGroups gs) ++ encItems suf)).
  { cbn [encItems encItem]; rewrite henc, ?append_assoc; reflexivity. }
  assert (hR : encItems (RIsingle aN hN bN [] None ::
                 RIsingle (a1 + Mv * (A_tr + B_tr)) false B_tr [] None ::
                 RItranspRun A_tr B_tr (rep - Mv) :: itemsOfActiveGroups gs' ++ suf') =
               ((((encSingle aN hN bN [] None ++ encSingle (a1 + Mv * (A_tr + B_tr)) false B_tr [] None) ++
                   encItem (RItranspRun A_tr B_tr (rep - Mv))) ++ encActiveGroups gs') ++ encItems suf')).
  { cbn [encItems]; rewrite encItems_append, encItems_itemsOfActiveGroups; cbn [encItem];
      rewrite ?append_assoc; reflexivity. }
  rewrite hL, hR. exact hstep.
Qed.

(* --- ScratchS4A.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

(* ========================================================================= *)
(* Section 12.1: Universal Mirror-Boost PipeL Engine                         *)
(* ========================================================================= *)

Lemma rule_mirror_t2 (k : nat) (l r : Stream Sym) :
  (l {{C}}> ((T2 ^^ k) *> r)) -[ tm ]->* (((T2 ^^ k) *> l) {{C}}> r).
Proof.
  revert l; induction k as [|k' IH]; intros l.
  - rewrite zPz, zLan. apply evstep_refl.
  - rewrite zPsr.
    eapply evstep_trans; [exact (step_mirror_t2_one l ((T2 ^^ k') *> r)) |].
    eapply evstep_trans; [exact (IH (T2 *> l)) |].
    rewrite zPal. apply evstep_refl.
Qed.

Lemma step_t3_t2_eat_t2 (k : nat) (l r : Stream Sym) :
  (([S1; S1] *> (T3 ^^ k) *> T2 *> l) {{F}}> (T2 *> r)) -[ tm ]->*
  (([S1; S1] *> (T3 ^^ (k + 2)) *> l) {{F}}> r).
Proof.
  destruct k as [|k'].
  - rewrite zPz, zLan. simpl. exact (step_t2L_eat_t2 l r).
  - assert (h1 : (([S1; S1] *> (T3 ^^ S k') *> T2 *> l) {{F}}> (T2 *> r)) -[ tm ]->*
                 (((T3 ^^ S k') *> T2 *> l) {{E}}> (T0 *> T0 *> T2 *> r))).
    { rewrite !zPsr. exact (step_8A_head ([S1; S1] *> (T3 ^^ k') *> T2 *> l) ([S0; S1] *> r)). }
    eapply evstep_trans; [exact h1 |].
    eapply evstep_trans; [exact (rule_E_t3 (S k') ([S0; S1] *> l) (T0 *> T2 *> r)) |].
    eapply evstep_trans; [exact (step_E_t2_bounce l ((T2 ^^ S k') *> T0 *> T2 *> r)) |].
    eapply evstep_trans; [exact (rule_C_1_t2 (S k') (T3 *> l) (T0 *> T2 *> r)) |].
    rewrite zPal.
    change (T1 *> T0 *> T2 *> r) with ([S1; S0] *> T2 *> r).
    eapply evstep_trans; [exact (step_8A_tail ((T3 ^^ S (S k')) *> l) r) |].
    rewrite <- zPsr.
    replace (S (S (S k'))) with (S k' + 2) by lia.
    apply evstep_refl.
Qed.

Lemma rule_t3_t2_eat_t2 (n k : nat) (l r : Stream Sym) :
  (([S1; S1] *> (T3 ^^ k) *> (T2 ^^ n) *> l) {{F}}> ((T2 ^^ n) *> r)) -[ tm ]->*
  (([S1; S1] *> (T3 ^^ (k + 2 * n)) *> l) {{F}}> r).
Proof.
  revert k l; induction n as [|n' IH]; intros k l.
  - rewrite ?zPz, ?zLan. replace (k + 2 * 0) with k by lia. apply evstep_refl.
  - rewrite !zPsr.
    eapply evstep_trans; [exact (step_t3_t2_eat_t2 k ((T2 ^^ n') *> l) ((T2 ^^ n') *> r)) |].
    eapply evstep_trans; [exact (IH (k + 2) l) |].
    replace (k + 2 + 2 * n') with (k + 2 * S n') by lia.
    apply evstep_refl.
Qed.

Lemma step_t3_t2_eat_t4 (k : nat) (l r : Stream Sym) :
  (([S1; S1] *> (T3 ^^ k) *> T2 *> l) {{F}}> (T4 *> r)) -[ tm ]->*
  (([S1; S1] *> T4 *> (T3 ^^ (k + 1)) *> l) {{F}}> r).
Proof.
  destruct k as [|k'].
  - rewrite zPz, zLan. replace (0 + 1) with 1 by lia. rewrite zP1.
    exact (step_t2_eat_t4 l r).
  - replace (S k') with (k' + 1) by lia.
    replace (k' + 1 + 1) with (k' + 2) by lia.
    exact (step_heal_odd_h0 k' l r).
Qed.

Lemma step_t3_t2_eat_t5 (k : nat) (l r : Stream Sym) :
  (([S1; S1] *> (T3 ^^ k) *> T2 *> l) {{F}}> (T5 *> r)) -[ tm ]->*
  (([S1] *> (T3 ^^ (k + 3)) *> l) {{A}}> r).
Proof.
  destruct k as [|k'].
  - rewrite zPz, zLan. simpl. exact (step_t2_eat_t5 l r).
  - replace (S k') with (k' + 1) by lia.
    replace (k' + 1 + 3) with (k' + 4) by lia.
    exact (step_heal_odd_h1 k' l r).
Qed.

Lemma step_q5_t0_double_asplit (k : nat) (l r : Stream Sym) :
  (([S1; S1] *> (T3 ^^ k) *> T2 *> l) {{F}}> (T0 *> r)) -[ tm ]->*
  (([S1] *> (T3 ^^ (k + 1)) *> l) {{A}}> (T0 *> T0 *> r)).
Proof.
  destruct k as [|k'].
  - rewrite zPz, zLan. replace (0 + 1) with 1 by lia. rewrite zP1.
    exact (step_t2_q5_t0_k0 l r).
  - assert (h1 : (([S1; S1] *> (T3 ^^ S k') *> T2 *> l) {{F}}> (T0 *> r)) -[ tm ]->*
                 (((T3 ^^ S k') *> T2 *> l) {{E}}> (T0 *> T0 *> T0 *> r))).
    { rewrite !zPsr. exact (step_8A_head ([S1; S1] *> (T3 ^^ k') *> T2 *> l) r). }
    eapply evstep_trans; [exact h1 |].
    eapply evstep_trans; [exact (rule_E_t3 (S k') ([S0; S1] *> l) (T0 *> T0 *> r)) |].
    eapply evstep_trans; [exact (step_E_t2_bounce l ((T2 ^^ S k') *> T0 *> T0 *> r)) |].
    eapply evstep_trans; [exact (rule_C_1_t2 (S k') (T3 *> l) (T0 *> T0 *> r)) |].
    rewrite zPal.
    replace (S k' + 1) with (S (S k')) by lia.
    exact (step_C_1_to_q0 ((T3 ^^ S (S k')) *> l) (T0 *> T0 *> r)).
Qed.

Lemma pull1_t3_t2_t0 (k : nat) {L_in L_out l0 : Stream Sym}
    (h0 : L_in = T0 *> l0) (h : Pull1 L_in L_out) (r : Stream Sym) :
    (([S1; S1] *> (T3 ^^ k) *> L_in) {{F}}> (T2 *> T0 *> r)) -[ tm ]->*
    (([S1] *> (T3 ^^ (k + 1)) *> L_out) {{A}}> (T0 *> T0 *> r)).
Proof.
  destruct k as [|k'].
  - rewrite zPz, zLan.
    change (T2 *> T0 *> r) with (T0 *> [S0; S1] *> T0 *> r).
    eapply evstep_trans; [exact (h ([S0; S1] *> T0 *> r)) |].
    replace (0 + 1) with 1 by lia. rewrite zP1.
    exact (step_post_pull_t2_t0_k0 L_out r).
  - assert (hs1 : (([S1; S1] *> (T3 ^^ S k') *> L_in) {{F}}> (T2 *> T0 *> r)) -[ tm ]->*
                  (((T3 ^^ S k') *> L_in) {{E}}> (T0 *> T0 *> T2 *> T0 *> r))).
    { rewrite !zPsr. exact (step_8A_head ([S1; S1] *> (T3 ^^ k') *> L_in) ([S0; S1] *> T0 *> r)). }
    eapply evstep_trans; [exact hs1 |].
    assert (hs2 : (((T3 ^^ S k') *> L_in) {{E}}> (T0 *> T0 *> T2 *> T0 *> r)) -[ tm ]->*
                  (([S1; S1] *> L_in) {{F}}> ([S0; S1] *> (T2 ^^ k') *> T0 *> T2 *> T0 *> r))).
    { rewrite h0. replace (S k') with (k' + 1) by lia.
      exact (rule_E_t3_to_Q5 k' l0 (T0 *> T2 *> T0 *> r)). }
    eapply evstep_trans; [exact hs2 |].
    change ([S0; S1] *> (T2 ^^ k') *> T0 *> T2 *> T0 *> r)
      with (T0 *> [S1] *> (T2 ^^ k') *> T0 *> T2 *> T0 *> r).
    eapply evstep_trans; [exact (h ([S1] *> (T2 ^^ k') *> T0 *> T2 *> T0 *> r)) |].
    change (T1 *> [S1] *> (T2 ^^ k') *> T0 *> T2 *> T0 *> r)
      with ([S1; S1] *> (T2 ^^ k') *> T0 *> T2 *> T0 *> r).
    eapply evstep_trans; [exact (post_pull_rt5 L_out ((T2 ^^ k') *> T0 *> T2 *> T0 *> r)) |].
    eapply evstep_trans; [exact (rule_C_1_t2 k' (T2 *> L_out) (T0 *> T2 *> T0 *> r)) |].
    change (T1 *> T0 *> T2 *> T0 *> r) with ([S1; S0] *> T2 *> T0 *> r).
    eapply evstep_trans; [exact (step_8A_tail ((T3 ^^ k') *> T2 *> L_out) (T0 *> r)) |].
    rewrite <- zPsr.
    eapply evstep_trans; [exact (step_q5_t0_double_asplit (S k') L_out r) |].
    apply evstep_refl.
Qed.

Lemma pipeL_mirror_noT2 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (b k q A_cnt : nat) (hp : PipeL En R_out Lt) :
    PipeL (En + q) (((R_out ++ (T2 ^^ (k + 2 * q + A_cnt))) ++ T5) ++ (T4 ^^ b))
      ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> (T2 ^^ (2 * q)) *> (T3 ^^ A_cnt) *> Lt).
Proof.
  revert k; induction q as [|q' IH]; intros k.
  - replace (En + 0) with En by lia.
    replace (2 * 0) with 0 by lia.
    rewrite zPz, zLan.
    replace (k + 0 + A_cnt) with (k + A_cnt) by lia.
    assert (hpow : (T3 ^^ k) *> (T3 ^^ A_cnt) *> Lt = (T3 ^^ (k + A_cnt)) *> Lt).
    { rewrite <- pow_add_blank. reflexivity. }
    rewrite hpow.
    exact (pipeL_noT2_blk b (k + A_cnt) hp).
  - destruct (PipeL_head0 hp) as [l0 hl0].
    destruct (head0_t3_t0 A_cnt l0) as [lA hlA].
    destruct (head0_t2_t0 (2 * q') lA) as [lT hlT].
    destruct (head0_t5_t4 b ((T3 ^^ k) *> (T2 ^^ (2 * S q')) *> (T3 ^^ A_cnt) *> Lt)) as [lH hlH].
    assert (h2q : (T2 ^^ (2 * S q')) *> (T3 ^^ A_cnt) *> Lt = T2 *> T2 *> T0 *> lT).
    { replace (2 * S q') with (2 + 2 * q') by lia.
      rewrite pow_add_blank, zPsr, zP1, hl0, hlA, hlT. reflexivity. }
    assert (hpull : Pull1 ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> (T2 ^^ (2 * S q')) *> (T3 ^^ A_cnt) *> Lt)
                          ((T5 ^^ b) *> T4 *> (T3 ^^ (k + 2)) *> (T2 ^^ (2 * q')) *> (T3 ^^ A_cnt) *> Lt)).
    { assert (hR : (T2 ^^ (2 * q')) *> (T3 ^^ A_cnt) *> Lt = T0 *> lT).
      { rewrite hl0, hlA, hlT. reflexivity. }
      rewrite h2q, hR. exact (pull1_base b k lT). }
    pose proof (IH (k + 2)) as hnext.
    replace (k + 2 + 2 * q' + A_cnt) with (k + 2 * S q' + A_cnt) in hnext by lia.
    replace (En + S q') with ((En + q') + 1) by lia.
    exact (PipeL_mkS hlH hpull hnext).
Qed.

Lemma pipeL_mirror_T2_q0 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (b k A_cnt : nat) (hp : PipeL En R_out Lt) :
    PipeL En ((R_out ++ (T2 ^^ (k + A_cnt + 1))) ++ (T4 ^^ (b + 1)))
      ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> T2 *> (T3 ^^ A_cnt) *> Lt).
Proof.
  destruct A_cnt as [|A'].
  - replace (k + 0 + 1) with (k + 1) by lia.
    rewrite zPz, zLan.
    exact (pipeL_T2_blk b k hp).
  - destruct hp as [R0 L0 l0 h0 hunw | E' R0 L0 L' l0 h0 hpull hnext].
    + destruct (head0_t5_t4 b ((T3 ^^ k) *> T2 *> (T3 ^^ S A') *> L0)) as [lH hlH].
      refine (PipeL_mk0 hlH (fun r => _)).
      destruct (head0_t3_t0 (S A') l0) as [lA hlA].
      assert (h1 : (([S1; S1] *> (T5 ^^ b) *> T4 *> (T3 ^^ k) *> T2 *> (T3 ^^ S A') *> L0) {{F}}> ([S0; S1] *> r)) -[ tm ]->*
                   (([S1; S1] *> (T3 ^^ S A') *> L0) {{F}}> ([S0; S1] *> (T2 ^^ (k + 1)) *> (T4 ^^ (b + 1)) *> r))).
      { rewrite h0, hlA. exact (unwind_T2 b k lA r). }
      eapply evstep_trans; [exact h1 |].
      assert (h2 : (([S1; S1] *> (T3 ^^ S A') *> L0) {{F}}> ([S0; S1] *> (T2 ^^ (k + 1)) *> (T4 ^^ (b + 1)) *> r)) -[ tm ]->*
                   (([S1; S1] *> L0) {{F}}> ([S0; S1] *> (T2 ^^ S A') *> (T2 ^^ (k + 1)) *> (T4 ^^ (b + 1)) *> r))).
      { rewrite h0. exact (rule_q5_t3_unwind (S A') l0 ((T2 ^^ (k + 1)) *> (T4 ^^ (b + 1)) *> r)). }
      eapply evstep_trans; [exact h2 |].
      assert (hpow : (T2 ^^ S A') *> (T2 ^^ (k + 1)) *> (T4 ^^ (b + 1)) *> r =
                     (T2 ^^ (k + S A' + 1)) *> (T4 ^^ (b + 1)) *> r).
      { rewrite <- pow_add_blank. replace (S A' + (k + 1)) with (k + S A' + 1) by lia. reflexivity. }
      rewrite hpow, ?Str_app_assoc.
      exact (hunw ((T2 ^^ (k + S A' + 1)) *> (T4 ^^ (b + 1)) *> r)).
    + destruct (head0_t5_t4 b ((T3 ^^ k) *> T2 *> (T3 ^^ S A') *> L0)) as [lH hlH].
      destruct (head0_t3_t0 (S A') l0) as [lA hlA].
      assert (hP : Pull1 ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> T2 *> (T3 ^^ S A') *> L0)
                         ((T5 ^^ b) *> T4 *> (T3 ^^ (k + S A')) *> T2 *> L')).
      { intros r.
        assert (h1 : (([S1; S1] *> (T5 ^^ b) *> T4 *> (T3 ^^ k) *> T2 *> (T3 ^^ S A') *> L0) {{F}}> (T0 *> r)) -[ tm ]->*
                     (([S1; S1] *> (T3 ^^ S A') *> L0) {{F}}> ([S0; S1] *> (T2 ^^ (k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r))).
        { rewrite h0, hlA. exact (left_T2_blk b k lA r). }
        eapply evstep_trans; [exact h1 |].
        assert (h2 : (([S1; S1] *> (T3 ^^ S A') *> L0) {{F}}> ([S0; S1] *> (T2 ^^ (k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r)) -[ tm ]->*
                     (((T3 ^^ S A') *> L0) {{E}}> (T0 *> T2 *> (T2 ^^ (k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r))).
        { rewrite !zPsr.
          exact (step_8A_head ([S1; S1] *> (T3 ^^ A') *> L0) ([S1] *> (T2 ^^ (k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r)). }
        eapply evstep_trans; [exact h2 |].
        assert (h3 : (((T3 ^^ S A') *> L0) {{E}}> (T0 *> T2 *> (T2 ^^ (k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r)) -[ tm ]->*
                     (([S1; S1] *> L0) {{F}}> ([S0; S1] *> (T2 ^^ (S A' + (k + 1))) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r))).
        { rewrite h0. replace (S A') with (A' + 1) by lia.
          eapply evstep_trans; [exact (rule_E_t3_to_Q5 A' l0 (T2 *> (T2 ^^ (k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r)) |].
          rewrite zPal, <- pow_add_blank.
          replace (S A') with (A' + 1) by lia. apply evstep_refl. }
        eapply evstep_trans; [exact h3 |].
        change ([S0; S1] *> (T2 ^^ (S A' + (k + 1))) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r)
          with (T0 *> [S1] *> (T2 ^^ (S A' + (k + 1))) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r).
        eapply evstep_trans; [exact (hpull ([S1] *> (T2 ^^ (S A' + (k + 1))) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r)) |].
        change (T1 *> [S1] *> (T2 ^^ (S A' + (k + 1))) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r)
          with ([S1; S1] *> (T2 ^^ (S A' + (k + 1))) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r).
        eapply evstep_trans; [exact (post_pull_rt5 L' ((T2 ^^ (S A' + (k + 1))) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r)) |].
        eapply evstep_trans; [exact (rule_C_1_t2 (S A' + (k + 1)) (T2 *> L') ((T4 ^^ b) *> [S0; S1; S0; S1] *> r)) |].
        replace (S A' + (k + 1)) with (S (k + S A')) by lia.
        rewrite zPsr.
        exact (right_ret_t4_0101_t3 b ((T3 ^^ (k + S A')) *> T2 *> L') r). }
      exact (PipeL_mkS hlH hP (pipeL_T2_blk b (k + S A') hnext)).
Qed.

Lemma pipeL_mirror_T2 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (b k q A_cnt : nat) (hp : PipeL En R_out Lt) :
    PipeL (En + q) ((R_out ++ (T2 ^^ (k + 2 * q + A_cnt + 1))) ++ (T4 ^^ (b + 1)))
      ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> (T2 ^^ (2 * q + 1)) *> (T3 ^^ A_cnt) *> Lt).
Proof.
  revert k; induction q as [|q' IH]; intros k.
  - replace (En + 0) with En by lia.
    replace (2 * 0 + 1) with 1 by lia.
    replace (k + 2 * 0 + A_cnt + 1) with (k + A_cnt + 1) by lia.
    rewrite zP1.
    exact (pipeL_mirror_T2_q0 b k A_cnt hp).
  - destruct (PipeL_head0 hp) as [l0 hl0].
    destruct (head0_t3_t0 A_cnt l0) as [lA hlA].
    destruct (head0_t2_t0 (2 * q' + 1) lA) as [lT hlT].
    destruct (head0_t5_t4 b ((T3 ^^ k) *> (T2 ^^ (2 * S q' + 1)) *> (T3 ^^ A_cnt) *> Lt)) as [lH hlH].
    assert (h2q : (T2 ^^ (2 * S q' + 1)) *> (T3 ^^ A_cnt) *> Lt = T2 *> T2 *> T0 *> lT).
    { replace (2 * S q' + 1) with (2 + (2 * q' + 1)) by lia.
      rewrite pow_add_blank, zPsr, zP1, hl0, hlA, hlT. reflexivity. }
    assert (hpull : Pull1 ((T5 ^^ b) *> T4 *> (T3 ^^ k) *> (T2 ^^ (2 * S q' + 1)) *> (T3 ^^ A_cnt) *> Lt)
                          ((T5 ^^ b) *> T4 *> (T3 ^^ (k + 2)) *> (T2 ^^ (2 * q' + 1)) *> (T3 ^^ A_cnt) *> Lt)).
    { assert (hR : (T2 ^^ (2 * q' + 1)) *> (T3 ^^ A_cnt) *> Lt = T0 *> lT).
      { rewrite hl0, hlA, hlT. reflexivity. }
      rewrite h2q, hR. exact (pull1_base b k lT). }
    pose proof (IH (k + 2)) as hnext.
    replace (k + 2 + 2 * q' + A_cnt + 1) with (k + 2 * S q' + A_cnt + 1) in hnext by lia.
    replace (En + S q') with ((En + q') + 1) by lia.
    exact (PipeL_mkS hlH hpull hnext).
Qed.

Lemma OneBlock_enterASplit {W W' : list Sym} {e0 : nat} {es : list nat}
    (a : nat) (h : bool) (s0 : nat) (segTail : list SegPiece)
    (hok : h = true \/ 1 <= s0) (hb : OneBlock W W' e0 es)
    (hpos : 1 <= e0 + sumList es) (ha : 2 * (e0 + sumList es) + 1 <= a) (r : Stream Sym) :
    (b0 {{E}}> (T2 *> T0 *> T1 *> (W ++ encS a h s0 segTail None) *> r)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *>
      (W' ++ encS (2 * (e0 + sumList es) - 1) h s0 segTail (Some (a - 2 * (e0 + sumList es)))) *> r)).
Proof.
  destruct (oneBlock_posT2 hb hpos) as [Wm [e1 [es1 [he1 [hsum [hp hP1]]]]]].
  assert (ha1 : 2 * e1 + 1 <= a) by lia.
  assert (hT2s : encS a h s0 segTail None =
                 T2 ++ ((T2 ^^ (a - 1)) ++ (((if h then T5 else []) ++ (T4 ^^ s0)) ++ encSegTail segTail))).
  { unfold encS. replace a with (1 + (a - 1)) at 1 by lia.
    rewrite list_pow_add, list_pow_one, ?append_assoc. reflexivity. }
  destruct (hP1 ((T2 ^^ (a - 1)) ++ (((if h then T5 else []) ++ (T4 ^^ s0)) ++ encSegTail segTail)) r)
    as [cfg0 [hpe0 hs0]].
  assert (hpe0' : P1Entry e1 Wm ((T2 ^^ a) ++ (((if h then T5 else []) ++ (T4 ^^ s0)) ++ encSegTail segTail)) r cfg0).
  { assert (hEq : T2 ++ ((T2 ^^ (a - 1)) ++ (((if h then T5 else []) ++ (T4 ^^ s0)) ++ encSegTail segTail)) =
                  (T2 ^^ a) ++ (((if h then T5 else []) ++ (T4 ^^ s0)) ++ encSegTail segTail)).
    { replace a with (1 + (a - 1)) at 2 by lia. rewrite list_pow_add, list_pow_one, ?append_assoc. reflexivity. }
    rewrite hEq in hpe0. exact hpe0. }
  pose proof (p1Entry_asplit_create a he1 ha1 hpe0') as has.
  pose proof (PureP2_dump hp (canDumpTail_asplit (2 * e1 - 1) h s0 segTail (a - 2 * e1) (sumList es1) hok ltac:(lia) r)) as hd.
  replace (2 * e1 - 1 + 2 * sumList es1) with (2 * (e0 + sumList es) - 1) in hd by lia.
  replace (a - 2 * e1 - 2 * sumList es1) with (a - 2 * (e0 + sumList es)) in hd by lia.
  rewrite hT2s.
  eapply evstep_trans; [exact hs0 |].
  eapply evstep_trans; [exact has |].
  assert (hM : ((((Wm ++ (T2 ^^ (2 * e1 - 1))) ++ T0) ++ (T2 ^^ (a - 2 * e1))) ++
                 (((if h then T5 else []) ++ (T4 ^^ s0)) ++ encSegTail segTail)) *> r =
               (Wm ++ encS (2 * e1 - 1) h s0 segTail (Some (a - 2 * e1))) *> r).
  { unfold encS. rewrite ?append_assoc. reflexivity. }
  rewrite hM. exact hd.
Qed.

Lemma p1Entry_enterMirrorBoost {e : nat} {R_out rest : list Sym} {r : Stream Sym} {cfg : Q * tape}
    (u aR : nat) (hge : u + 1 <= e)
    (h : P1Entry e R_out ((((T2 ^^ (2 * u + 1)) ++ T0) ++ (T2 ^^ aR)) ++ rest) r cfg) :
    exists Lt, PipeL (e - (u + 1)) R_out Lt /\
      cfg -[ tm ]->* (((T2 ^^ aR) *> (T3 ^^ (2 * u + 2)) *> Lt) {{C}}> (rest *> r)).
Proof.
  destruct h as [[Lt [hp1 hcfg]] | [Lt [W' [he [hW [hp hcfg]]]]]]; subst cfg.
  - assert (hsplit : ((((T2 ^^ (2 * u + 1)) ++ T0) ++ (T2 ^^ aR)) ++ rest) *> r =
                     (T2 ^^ (2 * u)) *> T2 *> T0 *> (T2 ^^ aR) *> rest *> r).
    { rewrite list_pow_add, list_pow_one, ?append_assoc, ?Str_app_assoc. reflexivity. }
    rewrite hsplit.
    destruct (pipeL_eat_t2_even (En := ltac:(match type of (proj1 hp1) with PipeL ?x _ _ => exact x end)) u 0 ltac:(lia) (proj1 hp1) (T2 *> T0 *> (T2 ^^ aR) *> rest *> r))
      as [Lt1 [hp1' hs1]].
    simpl in hs1.
    assert (he' : e - u = (e - (u + 1)) + 1) by lia.
    pose proof (pipeL_eqE he' hp1') as hp1''.
    destruct (PipeL_head0 hp1'') as [l1 hl1].
    destruct (PipeL_pull hp1'') as [Lt2 [hpull hp2]].
    pose proof (pull1_t3_t2_t0 (2 * u) hl1 hpull ((T2 ^^ aR) *> rest *> r)) as hs2.
    pose proof (step_mirror_enter ((T3 ^^ (2 * u + 1)) *> Lt2) ((T2 ^^ aR) *> rest *> r)) as hs3.
    pose proof (rule_mirror_t2 aR ((T3 ^^ (2 * u + 2)) *> Lt2) (rest *> r)) as hs4.
    exists Lt2. split; [exact hp2 |].
    eapply evstep_trans; [exact hs1 |].
    eapply evstep_trans; [exact hs2 |].
    eapply evstep_trans; [exact hs3 |].
    assert (hT3 : T3 *> (T3 ^^ (2 * u + 1)) *> Lt2 = (T3 ^^ (2 * u + 2)) *> Lt2)
      by (rewrite <- zPsr; replace (S (2 * u + 1)) with (2 * u + 2) by lia; reflexivity).
    rewrite hT3. exact hs4.
  - destruct u as [|u'].
    + assert (hW0 : (((T2 ^^ (2 * 0 + 1)) ++ T0) ++ (T2 ^^ aR)) ++ rest =
                    T2 ++ ((T0 ++ (T2 ^^ aR)) ++ rest)).
      { simpl. rewrite ?append_assoc. reflexivity. }
      rewrite hW0 in hW.
      assert (hW' : W' = (T0 ++ (T2 ^^ aR)) ++ rest).
      { apply (@app_cancel_left _ T2). symmetry; exact hW. }
      subst W'. rewrite ?Str_app_assoc.
      replace (e - (0 + 1)) with (e - 1) by lia.
      replace (2 * 0 + 2) with 2 by lia.
      exists Lt. split; [exact hp |].
      eapply evstep_trans; [exact (step_t2_q5_t0_k0 Lt ((T2 ^^ aR) *> rest *> r)) |].
      eapply evstep_trans; [exact (step_mirror_enter (T3 *> Lt) ((T2 ^^ aR) *> rest *> r)) |].
      assert (h2 : T3 *> T3 *> Lt = (T3 ^^ 2) *> Lt).
      { rewrite zPsr, zP1. reflexivity. }
      rewrite h2.
      exact (rule_mirror_t2 aR ((T3 ^^ 2) *> Lt) (rest *> r)).
    + assert (hWs : (((T2 ^^ (2 * S u' + 1)) ++ T0) ++ (T2 ^^ aR)) ++ rest =
                    T2 ++ (T2 ++ ((T2 ^^ (2 * u')) ++ (T2 ++ T0 ++ (T2 ^^ aR) ++ rest)))).
      { replace (2 * S u' + 1) with (1 + (1 + (2 * u' + 1))) by lia.
        simp_pow_add; rewrite !list_pow_one, ?append_assoc. reflexivity. }
      rewrite hWs in hW.
      assert (hW' : W' = T2 ++ ((T2 ^^ (2 * u')) ++ (T2 ++ T0 ++ (T2 ^^ aR) ++ rest))).
      { apply (@app_cancel_left _ T2). symmetry; exact hW. }
      subst W'. rewrite ?append_assoc, ?Str_app_assoc.
      pose proof (step_t2L_eat_t2 Lt ((T2 ^^ (2 * u')) *> T2 *> T0 *> (T2 ^^ aR) *> rest *> r)) as hs0.
      destruct (pipeL_eat_t2_even (En := ltac:(match type of hp with PipeL ?x _ _ => exact x end)) u' 2 ltac:(lia) hp (T2 *> T0 *> (T2 ^^ aR) *> rest *> r))
        as [Lt1 [hp1' hs1]].
      assert (he' : e - 1 - u' = (e - (S u' + 1)) + 1) by lia.
      pose proof (pipeL_eqE he' hp1') as hp1''.
      destruct (PipeL_head0 hp1'') as [l1 hl1].
      destruct (PipeL_pull hp1'') as [Lt2 [hpull hp2]].
      pose proof (pull1_t3_t2_t0 (2 + 2 * u') hl1 hpull ((T2 ^^ aR) *> rest *> r)) as hs2.
      pose proof (step_mirror_enter ((T3 ^^ (2 + 2 * u' + 1)) *> Lt2) ((T2 ^^ aR) *> rest *> r)) as hs3.
      exists Lt2. split; [exact hp2 |].
      eapply evstep_trans; [exact hs0 |].
      eapply evstep_trans; [exact hs1 |].
      eapply evstep_trans; [exact hs2 |].
      eapply evstep_trans; [exact hs3 |].
      assert (hT3 : T3 *> (T3 ^^ (2 + 2 * u' + 1)) *> Lt2 = (T3 ^^ (2 * S u' + 2)) *> Lt2).
      { rewrite <- zPsr. replace (S (2 + 2 * u' + 1)) with (2 * S u' + 2) by lia. reflexivity. }
      rewrite hT3.
      exact (rule_mirror_t2 aR ((T3 ^^ (2 * S u' + 2)) *> Lt2) (rest *> r)).
Qed.

Lemma PureP2_enterMirrorBoost {W W' : list Sym} {es : list nat}
    (aL q aR : nat) (rest : list Sym) (hp : PureP2 W W' es) :
    forall (hE : q + 1 <= sumList es),
    exists Wm e_m es_rem,
      PureP2 Wm W' es_rem /\
      e_m + sumList es_rem = sumList es - (q + 1) /\
      forall (r : Stream Sym),
        exists Lt, PipeL e_m Wm Lt /\
          (b0 {{E}}> (T2 *> T0 *> T1 *>
            ((((((W ++ (T2 ^^ aL)) ++ T0) ++ (T2 ^^ (2 * q + 1))) ++ T0) ++ (T2 ^^ aR)) ++ rest) *> r)) -[ tm ]->*
          (((T2 ^^ aR) *> (T3 ^^ (aL + 2 * q + 3)) *> Lt) {{C}}> (rest *> r)).
Proof.
  induction hp as [W | W0 W1 W2 e1 es1 h1 htail IH] in aL, q |- *; intros hE.
  - cbn [sumList] in hE; lia.
  - pose proof (proj1 h1) as he1pos.
    cbn [sumList] in hE.
    destruct (Nat.leb_spec0 e1 q) as [hle | hgt].
    + destruct (IH (aL + 2 * e1) (q - e1) ltac:(lia)) as [Wm [e_m [es_rem [hp_rem [hsum_rem hgo]]]]].
      exists Wm, e_m, es_rem.
      split; [exact hp_rem | split; [cbn [sumList]; lia |]].
      intros r.
      destruct (hgo r) as [Lt [hpL hstep]].
      exists Lt. split; [exact hpL |].
      destruct (proj1 (proj2 h1) (((((((T2 ^^ aL) ++ T0) ++ (T2 ^^ (2 * q + 1))) ++ T0) ++ (T2 ^^ aR)) ++ rest) *> r))
        as [Lt0 [hpL0 hs0]].
      pose proof (pipeL_dump_wall3 (E_rem := ltac:(match type of hpL0 with PipeL ?x _ _ => exact x end)) aL (2 * q + 1) ltac:(lia) hpL0 ((T2 ^^ aR) *> rest *> r)) as hsh.
      replace (e1 - 1 + 1) with e1 in hsh by lia.
      replace (2 * q + 1 - 2 * e1) with (2 * (q - e1) + 1) in hsh by lia.
      replace (aL + 2 * e1 + 2 * (q - e1) + 3) with (aL + 2 * q + 3) in hstep by lia.
      rewrite ?append_assoc, ?Str_app_assoc.
      rewrite ?append_assoc, ?Str_app_assoc in hs0.
      rewrite ?append_assoc, ?Str_app_assoc in hsh.
      rewrite ?append_assoc, ?Str_app_assoc in hstep.
      exact (stepStar_trans hs0 (stepStar_trans hsh hstep)).
    + exists W1, (e1 - (q + 1)), es1.
      split; [exact htail | split; [cbn [sumList]; lia |]].
      intros r.
      destruct (proj1 (proj2 h1) (((((((T2 ^^ aL) ++ T0) ++ (T2 ^^ (2 * q + 1))) ++ T0) ++ (T2 ^^ aR)) ++ rest) *> r))
        as [Lt0 [hpL0 hs0]].
      destruct (pipeL_asplit_prep (E_rem := ltac:(match type of hpL0 with PipeL ?x _ _ => exact x end)) aL q 1 ltac:(lia) hpL0 ((T2 ^^ aR) *> rest *> r))
        as [Lt1 [hpL1 hs1]].
      assert (hsub : e1 - 1 - q = e1 - (q + 1)) by lia.
      pose proof (pipeL_eqE hsub hpL1) as hpL1'.
      exists Lt1. split; [exact hpL1' |].
      rewrite ?append_assoc, ?Str_app_assoc.
      rewrite ?append_assoc, ?Str_app_assoc in hs0.
      rewrite ?append_assoc, ?Str_app_assoc in hs1.
      eapply evstep_trans; [exact hs0 |].
      eapply evstep_trans; [exact hs1 |].
      rewrite zP1.
      eapply evstep_trans; [exact (step_heal_0_t2 ((T3 ^^ (aL + 2 * q)) *> T2 *> Lt1) (T0 *> (T2 ^^ aR) *> rest *> r)) |].
      rewrite <- zPsr.
      replace (S (aL + 2 * q)) with (aL + 2 * q + 1) by lia.
      eapply evstep_trans; [exact (step_q5_t0_double_asplit (aL + 2 * q + 1) Lt1 ((T2 ^^ aR) *> rest *> r)) |].
      eapply evstep_trans; [exact (step_mirror_enter ((T3 ^^ (aL + 2 * q + 1 + 1)) *> Lt1) ((T2 ^^ aR) *> rest *> r)) |].
      rewrite <- zPsr.
      replace (S (aL + 2 * q + 1 + 1)) with (aL + 2 * q + 3) by lia.
      exact (rule_mirror_t2 aR ((T3 ^^ (aL + 2 * q + 3)) *> Lt1) (rest *> r)).
Qed.

Lemma OneBlock_enterMirrorBoost {W W' : list Sym} {e0 : nat} {es : list nat}
    (u aR : nat) (rest : list Sym) (hb : OneBlock W W' e0 es) (hE : u + 1 <= e0 + sumList es) :
    exists Wm e_m es_rem,
      PureP2 Wm W' es_rem /\
      e_m + sumList es_rem = e0 + sumList es - (u + 1) /\
      forall (r : Stream Sym),
        exists Lt, PipeL e_m Wm Lt /\
          (b0 {{E}}> (T2 *> T0 *> T1 *>
            ((((W ++ (T2 ^^ (2 * u + 1))) ++ T0) ++ (T2 ^^ aR)) ++ rest) *> r)) -[ tm ]->*
          (((T2 ^^ aR) *> (T3 ^^ (2 * u + 2)) *> Lt) {{C}}> (rest *> r)).
Proof.
  destruct (oneBlock_posT2 hb ltac:(lia)) as [Wm1 [e1 [es1 [he1 [hsum [hp1 hP1]]]]]].
  assert (hsplit : (((T2 ^^ (2 * u + 1)) ++ T0) ++ (T2 ^^ aR)) ++ rest =
                   T2 ++ ((((T2 ^^ (2 * u)) ++ T0) ++ (T2 ^^ aR)) ++ rest)).
  { replace (2 * u + 1) with (1 + 2 * u) by lia.
    rewrite list_pow_add, list_pow_one, ?append_assoc. reflexivity. }
  destruct (Nat.leb_spec0 (u + 1) e1) as [hge | hlt].
  - exists Wm1, (e1 - (u + 1)), es1.
    split; [exact hp1 | split; [lia |]].
    intros r.
    destruct (hP1 ((((T2 ^^ (2 * u)) ++ T0) ++ (T2 ^^ aR)) ++ rest) r) as [cfg0 [hpe0 hs0]].
    rewrite <- hsplit in hpe0.
    destruct (p1Entry_enterMirrorBoost u aR hge hpe0) as [Lt [hpL hs1]].
    exists Lt. split; [exact hpL |].
    assert (hEqW : (((W ++ (T2 ^^ (2 * u + 1))) ++ T0) ++ (T2 ^^ aR)) ++ rest =
                   W ++ (T2 ++ ((((T2 ^^ (2 * u)) ++ T0) ++ (T2 ^^ aR)) ++ rest))).
    { (rewrite ?append_assoc in hsplit; rewrite ?append_assoc). rewrite hsplit. reflexivity. }
    rewrite hEqW. exact (stepStar_trans hs0 hs1).
  - destruct (PureP2_enterMirrorBoost (2 * e1 - 1) (u - e1) aR rest hp1 ltac:(lia))
      as [Wm [e_m [es_rem [hp_rem [hsum_rem hgo]]]]].
    exists Wm, e_m, es_rem.
    split; [exact hp_rem | split; [lia |]].
    intros r.
    destruct (hgo r) as [Lt [hpL hstep]].
    replace (2 * e1 - 1 + 2 * (u - e1) + 3) with (2 * u + 2) in hstep by lia.
    exists Lt. split; [exact hpL |].
    destruct (hP1 ((((T2 ^^ (2 * u)) ++ T0) ++ (T2 ^^ aR)) ++ rest) r) as [cfg0 [hpe0 hs0]].
    assert (hpe0' : P1Entry e1 Wm1 ((T2 ^^ (2 * u + 1)) ++ ((T0 ++ (T2 ^^ aR)) ++ rest)) r cfg0).
    { assert (hspl2 : T2 ++ ((((T2 ^^ (2 * u)) ++ T0) ++ (T2 ^^ aR)) ++ rest) =
                      (T2 ^^ (2 * u + 1)) ++ ((T0 ++ (T2 ^^ aR)) ++ rest)).
      { rewrite <- hsplit, ?append_assoc. reflexivity. }
      rewrite <- hspl2. exact hpe0. }
    pose proof (p1Entry_asplit_create (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) (2 * u + 1) he1 ltac:(lia) hpe0') as has.
    replace (2 * u + 1 - 2 * e1) with (2 * (u - e1) + 1) in has by lia.
    assert (hEqW : (((W ++ (T2 ^^ (2 * u + 1))) ++ T0) ++ (T2 ^^ aR)) ++ rest =
                   W ++ (T2 ++ ((((T2 ^^ (2 * u)) ++ T0) ++ (T2 ^^ aR)) ++ rest))).
    { (rewrite ?append_assoc in hsplit; rewrite ?append_assoc). rewrite hsplit. reflexivity. }
    rewrite hEqW.
    eapply evstep_trans; [exact hs0 |].
    eapply evstep_trans; [exact has |].
    (rewrite ?append_assoc in hstep; rewrite ?append_assoc). exact hstep.
Qed.

(* ========================================================================= *)
(* Section 12.2: Unified SLICER12 Engine (d0 = 2 AND d0 = 0)                 *)
(* ========================================================================= *)

Lemma slicer_4blocks {W0 W1 W2 W3 W4 : list Sym}
    {e1 e2 e3 e4 : nat} {es1 es2 es3 es4 : list nat}
    (m Dv : nat) (segTail : list SegPiece)
    (hD : 85 <= Dv) (hE1pos : 1 <= m - Dv) (hDm : Dv + 1 <= m)
    (hb1 : OneBlock W0 W1 e1 es1) (hsum1 : e1 + sumList es1 = m - Dv)
    (hb2 : OneBlock W1 W2 e2 es2) (hsum2 : e2 + sumList es2 = m - Dv + 22)
    (hb3 : OneBlock W2 W3 e3 es3) (hsum3 : e3 + sumList es3 = m - Dv + 43)
    (hb4 : OneBlock W3 W4 e4 es4) (hsum4 : e4 + sumList es4 = m - Dv + 65)
    (r : Stream Sym) :
    (b0 {{E}}> (T2 *> T0 *> T1 *>
      (W0 ++ encS (2 * m) false (Dv + 64) segTail None) *> r)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *>
      (W4 ++ encS (2 * (m + 1)) false (Dv - 85 + 64) (SPsingle 41%N :: SPsingle 40%N :: segTail) None) *> r)).
Proof.
  set (E1 := m - Dv) in *.
  pose proof (OneBlock_enterASplit (2 * m) false (Dv + 64) segTail ltac:(right; lia) hb1 ltac:(lia) ltac:(lia) r) as hB1.
  rewrite hsum1 in hB1.
  replace (2 * m - 2 * E1) with (2 * Dv) in hB1 by lia.
  assert (hB2 : (b0 {{E}}> (T2 *> T0 *> T1 *>
                  (W1 ++ encS (2 * E1 - 1) false (Dv + 64) segTail (Some (2 * Dv))) *> r)) -[ tm ]->*
                (b0 {{E}}> (T2 *> T0 *> T1 *>
                  (W2 ++ encS (2 * m + 1) true (Dv + 21) (SPsingle 40%N :: segTail) None) *> r))).
  { destruct (OneBlock_enterMirrorBoost (E1 - 1) (2 * Dv) ((T4 ^^ (Dv + 64)) ++ encSegTail segTail) hb2 ltac:(lia))
      as [Wm [e_m [es_rem [hp_rem [hsum_rem hgo]]]]].
    destruct (hgo r) as [Lt [hpL hstep]].
    assert (hEqIn : W1 ++ encS (2 * E1 - 1) false (Dv + 64) segTail (Some (2 * Dv)) =
                    (((W1 ++ (T2 ^^ (2 * (E1 - 1) + 1))) ++ T0) ++ (T2 ^^ (2 * Dv))) ++
                      ((T4 ^^ (Dv + 64)) ++ encSegTail segTail)).
    { unfold encS. replace (2 * (E1 - 1) + 1) with (2 * E1 - 1) by lia.
      rewrite ?append_assoc. reflexivity. }
    rewrite hEqIn.
    eapply evstep_trans; [exact hstep |].
    assert (hT4s : ((T4 ^^ (Dv + 64)) ++ encSegTail segTail) *> r =
                   T4 *> T4 *> (T4 ^^ (Dv + 62)) *> encSegTail segTail *> r).
    { rewrite Str_app_assoc. replace (Dv + 64) with (1 + (1 + (Dv + 62))) by lia.
      simp_pow_add; rewrite !zP1. reflexivity. }
    rewrite hT4s.
    assert (hL2 : (T2 ^^ (2 * Dv)) *> (T3 ^^ (2 * (E1 - 1) + 2)) *> Lt =
                  T2 *> T2 *> (T2 ^^ (2 * (Dv - 1))) *> (T3 ^^ (2 * E1)) *> Lt).
    { replace (2 * Dv) with (2 + 2 * (Dv - 1)) by lia.
      replace (2 * (E1 - 1) + 2) with (2 * E1) by lia.
      rewrite pow_add_blank, zPsr, zP1. reflexivity. }
    rewrite hL2.
    eapply evstep_trans; [exact (step_mirror_t2_t2_t4 _ _) |].
    eapply evstep_trans; [exact (step_q1_t4_to_q5 _ _) |].
    pose proof (pipeL_mirror_noT2 0 3 (Dv - 1) (2 * E1) hpL) as hpM.
    rewrite zPz, zLan in hpM.
    assert (hR4 : (T4 ^^ (Dv + 62)) *> encSegTail segTail *> r =
                  (T4 ^^ (e_m + (Dv - 1))) *> T4 *> (T4 ^^ (62 - e_m)) *> encSegTail segTail *> r).
    { replace (Dv + 62) with ((e_m + (Dv - 1)) + (1 + (62 - e_m))) by lia.
      simp_pow_add; rewrite zP1. reflexivity. }
    rewrite hR4.
    destruct (pipeL_eat_t4 (e_m + (Dv - 1)) (Nat.le_refl _) hpM
                (T4 *> (T4 ^^ (62 - e_m)) *> encSegTail segTail *> r)) as [Lt2 [hpL2 hEat]].
    assert (hsub0 : e_m + (Dv - 1) - (e_m + (Dv - 1)) = 0) by lia.
    pose proof (pipeL_eqE hsub0 hpL2) as hpL2'.
    eapply evstep_trans; [exact hEat |].
    change (T4 *> (T4 ^^ (62 - e_m)) *> encSegTail segTail *> r)
      with ([S0; S1] *> T3 *> (T4 ^^ (62 - e_m)) *> encSegTail segTail *> r).
    eapply evstep_trans; [exact (PipeL_unwind hpL2' _) |].
    assert (hM2 : ((((Wm ++ (T2 ^^ (3 + 2 * (Dv - 1) + 2 * E1))) ++ T5) ++ []) ++ (T4 ^^ (e_m + (Dv - 1))))
                    *> T3 *> (T4 ^^ (62 - e_m)) *> encSegTail segTail *> r =
                  (Wm ++ encS (2 * m + 1) true (e_m + (Dv - 1)) (SPsingle (N.of_nat (62 - e_m)) :: segTail) None) *> r).
    { unfold encS; cbn [encSegTail]. rewrite Nat2N.id.
      replace (3 + 2 * (Dv - 1) + 2 * E1) with (2 * m + 1) by lia.
      rewrite ?app_nil_r, ?append_assoc, ?Str_app_assoc. reflexivity. }
    rewrite hM2.
    pose proof (PureP2_dump hp_rem
      (canDumpTail_wall1 (2 * m + 1) true (e_m + (Dv - 1)) (62 - e_m) segTail (sumList es_rem)
        (or_introl eq_refl) ltac:(lia) r)) as hd.
    replace (e_m + (Dv - 1) + sumList es_rem) with (Dv + 21) in hd by lia.
    replace (62 - e_m - sumList es_rem) with 40 in hd by lia.
    exact hd. }
  pose proof (OneBlock_enterASplit (2 * m + 1) true (Dv + 21) (SPsingle 40%N :: segTail)
    (or_introl eq_refl) hb3 ltac:(lia) ltac:(lia) r) as hB3.
  rewrite hsum3 in hB3.
  replace (2 * m + 1 - 2 * (E1 + 43)) with (2 * (Dv - 43) + 1) in hB3 by lia.
  assert (hB4 : (b0 {{E}}> (T2 *> T0 *> T1 *>
                  (W3 ++ encS (2 * (E1 + 43) - 1) true (Dv + 21) (SPsingle 40%N :: segTail) (Some (2 * (Dv - 43) + 1))) *> r)) -[ tm ]->*
                (b0 {{E}}> (T2 *> T0 *> T1 *>
                  (W4 ++ encS (2 * (m + 1)) false (Dv - 85 + 64) (SPsingle 41%N :: SPsingle 40%N :: segTail) None) *> r))).
  { destruct (OneBlock_enterMirrorBoost (E1 + 42) (2 * (Dv - 43) + 1)
                ((T5 ++ (T4 ^^ (Dv + 21))) ++ encSegTail (SPsingle 40%N :: segTail)) hb4 ltac:(lia))
      as [Wm [e_m [es_rem [hp_rem [hsum_rem hgo]]]]].
    destruct (hgo r) as [Lt [hpL hstep]].
    assert (hEqIn : W3 ++ encS (2 * (E1 + 43) - 1) true (Dv + 21) (SPsingle 40%N :: segTail) (Some (2 * (Dv - 43) + 1)) =
                    (((W3 ++ (T2 ^^ (2 * (E1 + 42) + 1))) ++ T0) ++ (T2 ^^ (2 * (Dv - 43) + 1))) ++
                      ((T5 ++ (T4 ^^ (Dv + 21))) ++ encSegTail (SPsingle 40%N :: segTail))).
    { unfold encS. replace (2 * (E1 + 42) + 1) with (2 * (E1 + 43) - 1) by lia.
      rewrite ?append_assoc. reflexivity. }
    rewrite hEqIn.
    eapply evstep_trans; [exact hstep |].
    assert (hR5 : ((T5 ++ (T4 ^^ (Dv + 21))) ++ encSegTail (SPsingle 40%N :: segTail)) *> r =
                  T5 *> T4 *> (T4 ^^ (Dv + 20)) *> encSegTail (SPsingle 40%N :: segTail) *> r).
    { rewrite ?Str_app_assoc. replace (Dv + 21) with (1 + (Dv + 20)) by lia.
      rewrite pow_add_blank, zP1. reflexivity. }
    rewrite hR5.
    eapply evstep_trans; [exact (step_mirror_cap_t5 _ _) |].
    assert (hL2 : (T2 ^^ (2 * (Dv - 43) + 1)) *> (T3 ^^ (2 * (E1 + 42) + 2)) *> Lt =
                  T2 *> T2 *> (T2 ^^ (2 * (Dv - 44) + 1)) *> (T3 ^^ (2 * (E1 + 43))) *> Lt).
    { replace (2 * (Dv - 43) + 1) with (2 + (2 * (Dv - 44) + 1)) by lia.
      replace (2 * (E1 + 42) + 2) with (2 * (E1 + 43)) by lia.
      rewrite pow_add_blank, zPsr, zP1. reflexivity. }
    rewrite hL2.
    eapply evstep_trans; [exact (step_t2L_eat_t2 _ _) |].
    eapply evstep_trans; [exact (step_t3_t2_eat_t4 2 _ _) |].
    pose proof (pipeL_mirror_T2 0 3 (Dv - 44) (2 * (E1 + 43)) hpL) as hpM.
    rewrite zPz, zLan in hpM.
    replace (0 + 1) with 1 in hpM by lia.
    assert (hR4 : (T4 ^^ (Dv + 20)) *> encSegTail (SPsingle 40%N :: segTail) *> r =
                  (T4 ^^ (e_m + (Dv - 44))) *> T4 *> (T4 ^^ (63 - e_m)) *> encSegTail (SPsingle 40%N :: segTail) *> r).
    { replace (Dv + 20) with ((e_m + (Dv - 44)) + (1 + (63 - e_m))) by lia.
      simp_pow_add; rewrite zP1. reflexivity. }
    rewrite hR4.
    destruct (pipeL_eat_t4 (e_m + (Dv - 44)) (Nat.le_refl _) hpM
                (T4 *> (T4 ^^ (63 - e_m)) *> encSegTail (SPsingle 40%N :: segTail) *> r)) as [Lt2 [hpL2 hEat]].
    assert (hsub0 : e_m + (Dv - 44) - (e_m + (Dv - 44)) = 0) by lia.
    pose proof (pipeL_eqE hsub0 hpL2) as hpL2'.
    eapply evstep_trans; [exact hEat |].
    change (T4 *> (T4 ^^ (63 - e_m)) *> encSegTail (SPsingle 40%N :: segTail) *> r)
      with ([S0; S1] *> T3 *> (T4 ^^ (63 - e_m)) *> encSegTail (SPsingle 40%N :: segTail) *> r).
    eapply evstep_trans; [exact (PipeL_unwind hpL2' _) |].
    assert (hM4 : (((Wm ++ (T2 ^^ (3 + 2 * (Dv - 44) + 2 * (E1 + 43) + 1))) ++ (T4 ^^ 1)) ++ (T4 ^^ (e_m + (Dv - 44))))
                    *> T3 *> (T4 ^^ (63 - e_m)) *> encSegTail (SPsingle 40%N :: segTail) *> r =
                  (Wm ++ encS (2 * (m + 1)) false (e_m + (Dv - 44) + 1)
                    (SPsingle (N.of_nat (63 - e_m)) :: SPsingle 40%N :: segTail) None) *> r).
    { unfold encS; cbn [encSegTail]. rewrite Nat2N.id.
          replace (3 + 2 * (Dv - 44) + 2 * (E1 + 43) + 1) with (2 * (m + 1)) by lia.
          replace (e_m + (Dv - 44) + 1) with (1 + (e_m + (Dv - 44))) by lia.
          rewrite (list_pow_add T4 1 (e_m + (Dv - 44))), ?app_nil_r, ?append_assoc, ?Str_app_assoc. reflexivity. }
    rewrite hM4.
    pose proof (PureP2_dump hp_rem
      (canDumpTail_wall1 (2 * (m + 1)) false (e_m + (Dv - 44) + 1) (63 - e_m)
        (SPsingle 40%N :: segTail) (sumList es_rem) ltac:(right; split; lia) ltac:(lia) r)) as hd.
    replace (e_m + (Dv - 44) + 1 + sumList es_rem) with (Dv - 85 + 64) in hd by lia.
    replace (63 - e_m - sumList es_rem) with 41 in hd by lia.
    exact hd. }
  exact (stepStar_trans hB1 (stepStar_trans hB2 (stepStar_trans hB3 hB4))).
Qed.

Lemma BlockList_uncons {W W' : list Sym} {b : nat} {bs : list nat}
    (h : BlockList W W' (b :: bs)) :
    exists W1 e0 es, OneBlock W W1 e0 es /\ e0 + sumList es = b /\ BlockList W1 W' bs.
Proof.
  inversion h as [| Wa W1 Wb e0 es bs' hb hrest]; subst.
  exists W1, e0, es. split; [exact hb | split; [reflexivity | exact hrest]].
Qed.

Lemma BlockList_nil_eq {W W' : list Sym} (h : BlockList W W' []) : W = W'.
Proof. inversion h. reflexivity. Qed.

Lemma c0_blockList_12 (m0 b0_v : nat) (hb0 : 14 <= b0_v) (hle : b0_v + 1 <= m0) :
    let Ev := m0 - b0_v in
    BlockList (encS (2 * m0) true b0_v [] None)
      (encS (2 * (m0 + 18)) true (b0_v - 12) [] None)
      [Ev; Ev + 3; Ev + 5; Ev + 8; Ev + 10; Ev + 13; Ev + 15; Ev + 18; Ev + 20; Ev + 23; Ev + 25; Ev + 28].
Proof.
  intros Ev.
  assert (hstep2 : forall k : nat, 3 <= b0_v - 2 * k ->
      BlockList (encS (2 * (m0 + 3 * k)) true (b0_v - 2 * k) [] None)
        (encS (2 * (m0 + 3 * (k + 1))) true (b0_v - 2 * (k + 1)) [] None)
        [Ev + 5 * k; Ev + 5 * k + 3]).
  { intros k hk.
    assert (hv1 : c0Valid_nat (2 * (m0 + 3 * k)) true (b0_v - 2 * k) = true).
    { unfold c0Valid_nat. apply Bool.andb_true_iff. split; [apply Nat.leb_le; lia |].
      apply Bool.andb_true_iff. split; [apply Nat.eqb_eq; lia | apply Nat.leb_le; lia]. }
    assert (hp1 : 1 <= c0E1_nat (2 * (m0 + 3 * k)) true (b0_v - 2 * k)).
    { unfold c0E1_nat. pose proof (Nat.div_mod (2 * (m0 + 3 * k)) 2 ltac:(lia)); lia. }
    pose proof (c0_oneBlock (2 * (m0 + 3 * k)) true (b0_v - 2 * k) hv1 hp1) as hb1.
    cbn [c0Step1_nat c0E1_nat] in hb1.
    assert (hv2 : c0Valid_nat (2 * (m0 + 3 * k) + 3) false (b0_v - 2 * k) = true).
    { unfold c0Valid_nat. apply Bool.andb_true_iff. split; [apply Nat.leb_le; lia |].
      apply Bool.andb_true_iff. split; [apply Nat.eqb_eq; lia | apply Nat.leb_le; lia]. }
    assert (hp2 : 1 <= c0E1_nat (2 * (m0 + 3 * k) + 3) false (b0_v - 2 * k)).
    { unfold c0E1_nat. pose proof (Nat.div_mod (2 * (m0 + 3 * k) + 3) 2 ltac:(lia)); lia. }
    pose proof (c0_oneBlock (2 * (m0 + 3 * k) + 3) false (b0_v - 2 * k) hv2 hp2) as hb2.
    cbn [c0Step1_nat c0E1_nat] in hb2.
    replace ((2 * (m0 + 3 * k)) / 2 - (b0_v - 2 * k)) with (Ev + 5 * k) in hb1
      by (unfold Ev; pose proof (Nat.div_mod (2 * (m0 + 3 * k)) 2 ltac:(lia)); lia).
    replace ((2 * (m0 + 3 * k) + 3) / 2 + 2 - (b0_v - 2 * k)) with (Ev + 5 * k + 3) in hb2
      by (unfold Ev; pose proof (Nat.div_mod (2 * (m0 + 3 * k) + 3) 2 ltac:(lia)); lia).
    replace (2 * (m0 + 3 * k) + 3 + 3) with (2 * (m0 + 3 * (k + 1))) in hb2 by lia.
    replace (b0_v - 2 * k - 2) with (b0_v - 2 * (k + 1)) in hb2 by lia.
    pose proof (BlockList_cons hb1 (BlockList_cons hb2 (BlockList_nil _))) as h12.
    cbn [sumList] in h12.
    replace (Ev + 5 * k + 0) with (Ev + 5 * k) in h12 by lia.
    replace (Ev + 5 * k + 3 + 0) with (Ev + 5 * k + 3) in h12 by lia.
    exact h12. }
  pose proof (hstep2 0 ltac:(lia)) as s0.
  pose proof (hstep2 1 ltac:(lia)) as s1.
  pose proof (hstep2 2 ltac:(lia)) as s2.
  pose proof (hstep2 3 ltac:(lia)) as s3.
  pose proof (hstep2 4 ltac:(lia)) as s4.
  pose proof (hstep2 5 ltac:(lia)) as s5.
  replace (m0 + 3 * 0) with m0 in s0 by lia.
  replace (b0_v - 2 * 0) with b0_v in s0 by lia.
  replace (m0 + 3 * (5 + 1)) with (m0 + 18) in s5 by lia.
  replace (b0_v - 2 * (5 + 1)) with (b0_v - 12) in s5 by lia.
  pose proof (BlockList_append s0 (BlockList_append s1 (BlockList_append s2
               (BlockList_append s3 (BlockList_append s4 s5))))) as hall.
  cbn [app] in hall.
  replace (Ev + 5 * 0 + 3) with (Ev + 3) in hall by lia.
  replace (Ev + 5 * 0) with Ev in hall by lia.
  replace (Ev + 5 * 1 + 3) with (Ev + 8) in hall by lia.
  replace (Ev + 5 * 1) with (Ev + 5) in hall by lia.
  replace (Ev + 5 * 2 + 3) with (Ev + 13) in hall by lia.
  replace (Ev + 5 * 2) with (Ev + 10) in hall by lia.
  replace (Ev + 5 * 3 + 3) with (Ev + 18) in hall by lia.
  replace (Ev + 5 * 3) with (Ev + 15) in hall by lia.
  replace (Ev + 5 * 4 + 3) with (Ev + 23) in hall by lia.
  replace (Ev + 5 * 4) with (Ev + 20) in hall by lia.
  replace (Ev + 5 * 5 + 3) with (Ev + 28) in hall by lia.
  replace (Ev + 5 * 5) with (Ev + 25) in hall by lia.
  exact hall.
Qed.

Lemma slicer_3blocks
    {W0 W_end : list Sym} {E_a E_b E_c : nat} {rest : list nat}
    (m1 b1 : nat) (sp_list : list RleItem) (hsp1 : isTranspList sp_list = true)
    (hbl : BlockList W0 W_end (E_a :: E_b :: E_c :: rest))
    (hb1 : 4 <= b1) (hEa : m1 + 3 <= E_a) (hEb : m1 + 1 <= E_b) (hEc : m1 + 2 <= E_c)
    (hSum : 3 * m1 + b1 + 1 + transpListCost_nat sp_list + 1 <= E_a + E_b + E_c) :
    exists W3 e es, OneBlock ((W0 ++ encS (2 * m1 + 1) false b1 [] None) ++ encItems sp_list)
        ((W3 ++ encS (2 * (m1 + 1) + 1) false (b1 - 2) [] None) ++ encItems sp_list) e es /\
      e + sumList es = E_a + E_b + E_c - (3 * m1 + b1 + 1) - transpListCost_nat sp_list /\
      BlockList W3 W_end rest.
Proof.
  destruct (BlockList_uncons hbl) as [W1 [e0a [esa [hb0 [he0 hbl1]]]]].
  destruct (BlockList_uncons hbl1) as [W2 [e0b [esb [hb1' [he1 hbl2]]]]].
  destruct (BlockList_uncons hbl2) as [W3 [e0c [esc_0 [hb2 [he2 hrest]]]]].
  destruct (liftDigitCycle m1 (b1 - 2) ltac:(lia) hb0 hb1' hb2 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia))
    as [ec [esc [hbc hsc]]].
  replace (b1 - 2 + 2) with b1 in hbc by lia.
  replace (2 * m1 + 3) with (2 * (m1 + 1) + 1) in hbc by lia.
  destruct (OneBlock_liftTranspList sp_list hsp1 hbc ltac:(lia)) as [ed [esd [hbd hsd]]].
  exists W3, ed, esd. split; [exact hbd | split; [lia | exact hrest]].
Qed.

Lemma slicer_1cycle
    (m0 b0_v m1 b1 m Dv : nat) (sp0 sp_list : list RleItem) (segTail : list SegPiece)
    (hsp0 : isTranspList sp0 = true) (hsp1 : isTranspList sp_list = true)
    (hb0 : 14 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + m1 + 3 <= m0)
    (hb1 : 10 <= b1) (hD : 85 <= Dv) (hDm : Dv + 1 <= m)
    (hE1 : 3 * (m0 - b0_v - transpListCost_nat sp0) + 8 =
           (3 * m1 + b1 + 1) + transpListCost_nat sp_list + (m - Dv))
    (r : Stream Sym) :
    (b0 {{E}}> (T2 *> T0 *> T1 *>
      ((((encS (2 * m0) true b0_v [] None ++ encItems sp0)
        ++ encS (2 * m1 + 1) false b1 [] None) ++ encItems sp_list)
        ++ encS (2 * m) false (Dv + 64) segTail None) *> r)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *>
      ((((encS (2 * (m0 + 18)) true (b0_v - 12) [] None ++ encItems sp0)
        ++ encS (2 * (m1 + 4) + 1) false (b1 - 8) [] None) ++ encItems sp_list)
        ++ encS (2 * (m + 1)) false (Dv - 85 + 64) (SPsingle 41%N :: SPsingle 40%N :: segTail) None) *> r)).
Proof.
  assert (hge_all : forall x, List.In x
      [m0 - b0_v; m0 - b0_v + 3; m0 - b0_v + 5; m0 - b0_v + 8; m0 - b0_v + 10;
       m0 - b0_v + 13; m0 - b0_v + 15; m0 - b0_v + 18; m0 - b0_v + 20; m0 - b0_v + 23;
       m0 - b0_v + 25; m0 - b0_v + 28] -> transpListCost_nat sp0 <= x).
  { intros x hx. simpl in hx. lia. }
  pose proof (c0_blockList_12 m0 b0_v hb0 ltac:(lia)) as hbl0.
  cbv zeta in hbl0.
  pose proof (BlockList_liftTranspList sp0 hsp0 hbl0 hge_all) as hbl1.
  set (E0 := m0 - b0_v - transpListCost_nat sp0) in *.
  assert (hE0_ge : m1 + 3 <= E0) by (clear - hle0; unfold E0; lia).
  assert (hmap_eq : List.map (fun b => b - transpListCost_nat sp0)
      [m0 - b0_v; m0 - b0_v + 3; m0 - b0_v + 5; m0 - b0_v + 8; m0 - b0_v + 10;
       m0 - b0_v + 13; m0 - b0_v + 15; m0 - b0_v + 18; m0 - b0_v + 20; m0 - b0_v + 23;
       m0 - b0_v + 25; m0 - b0_v + 28] =
      [E0; E0 + 3; E0 + 5; E0 + 8; E0 + 10; E0 + 13; E0 + 15; E0 + 18; E0 + 20;
       E0 + 23; E0 + 25; E0 + 28]).
  { clear - hle0; unfold E0; cbn [List.map]; repeat (f_equal; try lia). }
  rewrite hmap_eq in hbl1; clear hmap_eq.
  remember (m - Dv) as E1 eqn:hE1_def.
  assert (hE1_pos : 1 <= E1) by (clear - hDm hE1_def; lia).
  revert hE1_def; clearbody E0; intros hE1_def.
  destruct (slicer_3blocks m1 b1 sp_list hsp1 hbl1
    ltac:(clear - hb1; lia) ltac:(clear - hE0_ge; lia) ltac:(clear - hE0_ge; lia) ltac:(clear - hE0_ge; lia)
    ltac:(clear - hE1 hE1_pos; lia))
    as [Wa [ed1 [esd1 [hbd1 [hsd1 hbl2]]]]].
  assert (hs1 : ed1 + sumList esd1 = E1) by (clear - hsd1 hE1; lia); clear hsd1.
  destruct (slicer_3blocks (m1 + 1) (b1 - 2) sp_list hsp1 hbl2
    ltac:(clear - hb1; lia) ltac:(clear - hE0_ge; lia) ltac:(clear - hE0_ge; lia) ltac:(clear - hE0_ge; lia)
    ltac:(clear - hE1 hE1_pos hb1; lia))
    as [Wb [ed2 [esd2 [hbd2 [hsd2 hbl3]]]]].
  assert (hs2 : ed2 + sumList esd2 = E1 + 22) by (clear - hsd2 hE1 hb1; lia); clear hsd2.
  destruct (slicer_3blocks (m1 + 2) (b1 - 4) sp_list hsp1 hbl3
    ltac:(clear - hb1; lia) ltac:(clear - hE0_ge; lia) ltac:(clear - hE0_ge; lia) ltac:(clear - hE0_ge; lia)
    ltac:(clear - hE1 hE1_pos hb1; lia))
    as [Wc [ed3 [esd3 [hbd3 [hsd3 hbl4]]]]].
  assert (hs3 : ed3 + sumList esd3 = E1 + 43) by (clear - hsd3 hE1 hb1; lia); clear hsd3.
  destruct (slicer_3blocks (m1 + 3) (b1 - 6) sp_list hsp1 hbl4
    ltac:(clear - hb1; lia) ltac:(clear - hE0_ge; lia) ltac:(clear - hE0_ge; lia) ltac:(clear - hE0_ge; lia)
    ltac:(clear - hE1 hE1_pos hb1; lia))
    as [Wd [ed4 [esd4 [hbd4 [hsd4 hbl5]]]]].
  assert (hs4 : ed4 + sumList esd4 = E1 + 65) by (clear - hsd4 hE1 hb1; lia); clear hsd4.
  pose proof (BlockList_nil_eq hbl5) as hnil; subst Wd.
  replace (b1 - 2 - 2) with (b1 - 4) in hbd2 by (clear - hb1; lia).
  replace (m1 + 1 + 1) with (m1 + 2) in hbd2 by (clear; lia).
  replace (b1 - 4 - 2) with (b1 - 6) in hbd3 by (clear - hb1; lia).
  replace (m1 + 2 + 1) with (m1 + 3) in hbd3 by (clear; lia).
  replace (b1 - 6 - 2) with (b1 - 8) in hbd4 by (clear - hb1; lia).
  replace (m1 + 3 + 1) with (m1 + 4) in hbd4 by (clear; lia).
  subst E1.
  exact (slicer_4blocks m Dv segTail hD hE1_pos hDm hbd1 hs1 hbd2 hs2 hbd3 hs3 hbd4 hs4 r).
Qed.

Lemma slicer_Mcycles (Mv : nat) :
    forall (m0 b0_v m1 b1 m Dv : nat) (sp0 sp_list : list RleItem) (segTail : list SegPiece)
    (hsp0 : isTranspList sp0 = true) (hsp1 : isTranspList sp_list = true)
    (hb0 : 12 * Mv + 2 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + m1 + 3 <= m0)
    (hb1 : 8 * Mv + 2 <= b1) (hD : 85 * Mv <= Dv) (hDm : Dv + 1 <= m)
    (hE1 : 3 * (m0 - b0_v - transpListCost_nat sp0) + 8 =
           (3 * m1 + b1 + 1) + transpListCost_nat sp_list + (m - Dv))
    (r : Stream Sym),
    (b0 {{E}}> (T2 *> T0 *> T1 *>
      ((((encS (2 * m0) true b0_v [] None ++ encItems sp0)
        ++ encS (2 * m1 + 1) false b1 [] None) ++ encItems sp_list)
        ++ encS (2 * m) false (Dv + 64) segTail None) *> r)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *>
      ((((encS (2 * (m0 + 18 * Mv)) true (b0_v - 12 * Mv) [] None ++ encItems sp0)
        ++ encS (2 * (m1 + 4 * Mv) + 1) false (b1 - 8 * Mv) [] None) ++ encItems sp_list)
        ++ encS (2 * (m + Mv)) false (Dv - 85 * Mv + 64) (SPpair 41%N 40%N (N.of_nat Mv) :: segTail) None) *> r)).
Proof.
  induction Mv as [|M' IH]; intros m0 b0_v m1 b1 m Dv sp0 sp_list segTail hsp0 hsp1 hb0 hle0 hb1 hD hDm hE1 r.
  - replace (m0 + 18 * 0) with m0 by lia.
    replace (b0_v - 12 * 0) with b0_v by lia.
    replace (m1 + 4 * 0) with m1 by lia.
    replace (b1 - 8 * 0) with b1 by lia.
    replace (m + 0) with m by lia.
    replace (Dv - 85 * 0 + 64) with (Dv + 64) by lia.
    unfold encS; cbn [N.of_nat encSegTail N.to_nat].
    rewrite zPz; simpl app. apply evstep_refl.
  - pose proof (slicer_1cycle m0 b0_v m1 b1 m Dv sp0 sp_list segTail hsp0 hsp1
      ltac:(lia) hle0 ltac:(lia) ltac:(lia) hDm hE1 r) as h1.
    pose proof (IH (m0 + 18) (b0_v - 12) (m1 + 4) (b1 - 8) (m + 1) (Dv - 85) sp0 sp_list
      (SPsingle 41%N :: SPsingle 40%N :: segTail) hsp0 hsp1
      ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) r) as h2.
    eapply evstep_trans; [exact h1 |].
    assert (hEnd : encS (2 * (m + 1 + M')) false (Dv - 85 - 85 * M' + 64)
                     (SPpair 41%N 40%N (N.of_nat M') :: SPsingle 41%N :: SPsingle 40%N :: segTail) None =
                   encS (2 * (m + S M')) false (Dv - 85 * S M' + 64)
                     (SPpair 41%N 40%N (N.of_nat (S M')) :: segTail) None).
    { unfold encS; cbn [encSegTail]. rewrite !Nat2N.id.
      assert (hpow : forall u : list Sym, u ^^ S M' = (u ^^ M') ++ u)
        by (intros u; replace (S M') with (M' + 1) by lia; apply list_pow_succ_right).
      rewrite hpow.
      replace (2 * (m + 1 + M')) with (2 * (m + S M')) by lia.
      replace (Dv - 85 - 85 * M' + 64) with (Dv - 85 * S M' + 64) by lia.
      rewrite ?append_assoc. reflexivity. }
    replace (2 * (m0 + 18 + 18 * M')) with (2 * (m0 + 18 * S M')) in h2 by lia.
    replace (b0_v - 12 - 12 * M') with (b0_v - 12 * S M') in h2 by lia.
    replace (2 * (m1 + 4 + 4 * M') + 1) with (2 * (m1 + 4 * S M') + 1) in h2 by lia.
    replace (b1 - 8 - 8 * M') with (b1 - 8 * S M') in h2 by lia.
    rewrite hEnd in h2. exact h2.
Qed.

Lemma stepSlicer12_sound (k0 k1 : nat) (Mv : N) (items items' : list RleItem)
    (h : stepSlicer12 k0 k1 Mv items = Some items') :
    HubCfg items -[ tm ]->* HubCfg items'.
Proof.
  unfold stepSlicer12 in h.
  destruct items as [|it0 rest0]; [discriminate |].
  destruct it0 as [a0 [|] b0_v [|? ?] [?|] | | |]; try discriminate.
  destruct ((negb (a0 mod 2 =? 0)%N || (b0_v <? 12 * Mv + 2)%N)%bool) eqn:hc0; [discriminate |].
  apply Bool.orb_false_iff in hc0; destruct hc0 as [ha0_ev hb0_ge].
  apply Bool.negb_false_iff in ha0_ev; apply N.eqb_eq in ha0_ev.
  apply N.ltb_ge in hb0_ge.
  destruct (splitAtList k0 rest0) as [[sp0 rest1]|] eqn:hs0; [| discriminate].
  destruct (negb (isTranspList sp0)) eqn:hsp0; [discriminate |].
  apply Bool.negb_false_iff in hsp0.
  destruct rest1 as [|it1 rest2]; [discriminate |].
  destruct it1 as [a1 [|] b1 [|? ?] [?|] | | |]; try discriminate.
  destruct ((negb (a1 mod 2 =? 1)%N || (b1 <? 8 * Mv + 2)%N)%bool) eqn:hc1; [discriminate |].
  apply Bool.orb_false_iff in hc1; destruct hc1 as [ha1_odd hb1_ge].
  apply Bool.negb_false_iff in ha1_odd; apply N.eqb_eq in ha1_odd.
  apply N.ltb_ge in hb1_ge.
  destruct (splitAtList k1 rest2) as [[sp_list rest3]|] eqn:hs1; [| discriminate].
  destruct (negb (isTranspList sp_list)) eqn:hsp1; [discriminate |].
  apply Bool.negb_false_iff in hsp1.
  destruct rest3 as [|itj rest4]; [discriminate |].
  destruct itj as [aj [|] sj segTail [?|] | | |]; try discriminate.
  destruct ((negb (aj mod 2 =? 0)%N || (sj <? 64)%N)%bool) eqn:hcj; [discriminate |].
  apply Bool.orb_false_iff in hcj; destruct hcj as [haj_ev hsj_ge].
  apply Bool.negb_false_iff in haj_ev; apply N.eqb_eq in haj_ev.
  apply N.ltb_ge in hsj_ge.
  cbv zeta in h.
  destruct (((b0_v + transpListCost sp0 + a1 / 2 + 3 <=? a0 / 2)%N &&
             (85 * Mv <=? sj - 64)%N && (sj - 64 + 1 <=? aj / 2)%N &&
             (3 * (a0 / 2 - b0_v - transpListCost sp0) + 8 =?
               (3 * (a1 / 2) + b1 + 1) + transpListCost sp_list + (aj / 2 - (sj - 64)))%N)%bool)
    eqn:hcond; [| discriminate].
  split_andb.
  inv_some h; subst items'.
  pose proof (splitAtList_sound _ _ _ _ hs0) as hr0; subst rest0.
  pose proof (splitAtList_sound _ _ _ _ hs1) as hr1; subst rest2.
  pose proof (N2Nat_div a0 2) as Ha0div; change (N.to_nat 2%N) with 2 in Ha0div.
  pose proof (N2Nat_mod a0 2) as Ha0mod; change (N.to_nat 2%N) with 2 in Ha0mod.
  pose proof (N2Nat_div a1 2) as Ha1div; change (N.to_nat 2%N) with 2 in Ha1div.
  pose proof (N2Nat_mod a1 2) as Ha1mod; change (N.to_nat 2%N) with 2 in Ha1mod.
  pose proof (N2Nat_div aj 2) as Hajdiv; change (N.to_nat 2%N) with 2 in Hajdiv.
  pose proof (N2Nat_mod aj 2) as Hajmod; change (N.to_nat 2%N) with 2 in Hajmod.
  assert (ha0_par : N.to_nat a0 = 2 * (N.to_nat a0 / 2))
    by (clear - ha0_ev Ha0mod; pose proof (Nat.div_mod (N.to_nat a0) 2 ltac:(lia)); lia).
  assert (ha1_par : N.to_nat a1 = 2 * (N.to_nat a1 / 2) + 1)
    by (clear - ha1_odd Ha1mod; pose proof (Nat.div_mod (N.to_nat a1) 2 ltac:(lia)); lia).
  assert (haj_par : N.to_nat aj = 2 * (N.to_nat aj / 2))
    by (clear - haj_ev Hajmod; pose proof (Nat.div_mod (N.to_nat aj) 2 ltac:(lia)); lia).
  clear Ha0mod Ha1mod Hajmod ha0_ev ha1_odd haj_ev hs0 hs1.
  pose proof (slicer_Mcycles (N.to_nat Mv) (N.to_nat a0 / 2) (N.to_nat b0_v)
    (N.to_nat a1 / 2) (N.to_nat b1) (N.to_nat aj / 2) (N.to_nat sj - 64)
    sp0 sp_list segTail hsp0 hsp1
    ltac:(clear - hb0_ge; lia) ltac:(unfold transpListCost_nat; lia) ltac:(clear - hb1_ge; lia)
    ltac:(lia) ltac:(lia) ltac:(unfold transpListCost_nat; lia)
    (encItems rest4 *> [S0; S1; S0; S1] *> b0)) as hstep.
  assert (hsj_ge_nat : 85 * N.to_nat Mv + 64 <= N.to_nat sj) by lia.
  clear - hstep ha0_par ha1_par haj_par hsj_ge_nat.
  rewrite N2Nat.id in hstep.
  replace (2 * (N.to_nat a0 / 2)) with (N.to_nat a0) in hstep by lia.
  replace (2 * (N.to_nat a1 / 2) + 1) with (N.to_nat a1) in hstep by lia.
  replace (2 * (N.to_nat aj / 2)) with (N.to_nat aj) in hstep by lia.
  replace (N.to_nat sj - 64 + 64) with (N.to_nat sj) in hstep by lia.
  replace (2 * (N.to_nat a0 / 2 + 18 * N.to_nat Mv)) with (N.to_nat (a0 + 36 * Mv)%N) in hstep by lia.
  replace (N.to_nat b0_v - 12 * N.to_nat Mv) with (N.to_nat (b0_v - 12 * Mv)%N) in hstep by lia.
  replace (2 * (N.to_nat a1 / 2 + 4 * N.to_nat Mv) + 1) with (N.to_nat (a1 + 8 * Mv)%N) in hstep by lia.
  replace (N.to_nat b1 - 8 * N.to_nat Mv) with (N.to_nat (b1 - 8 * Mv)%N) in hstep by lia.
  replace (2 * (N.to_nat aj / 2 + N.to_nat Mv)) with (N.to_nat (aj + 2 * Mv)%N) in hstep by lia.
  replace (N.to_nat sj - 64 - 85 * N.to_nat Mv + 64) with (N.to_nat (sj - 85 * Mv)%N) in hstep by lia.
  unfold HubCfg.
  repeat (cbn [encItems app]; simp_encItems_app); cbn [encItems encItem];
    rewrite !encSingle_eq_encS; cbn [option_map].
  rewrite ?append_assoc, ?Str_app_assoc.
  rewrite ?append_assoc, ?Str_app_assoc in hstep.
  exact hstep.
Qed.

(* ========================================================================= *)
(* Section 12.3: Weak Phase-2 (PureP2W)                                      *)
(* ========================================================================= *)

Definition HubP2W (e : nat) (W W1 : list Sym) : Prop :=
  1 <= e /\
  forall r : Stream Sym, exists Lt, PipeL (e - 1) W1 Lt /\
    (b0 {{E}}> (T2 *> T0 *> T1 *> W *> r)) -[ tm ]->* (([S1] *> T2 *> Lt) {{A}}> r).

Inductive PureP2W : list Sym -> list Sym -> list nat -> Prop :=
  | PureP2W_nil (W : list Sym) : PureP2W W W []
  | PureP2W_cons {W W1 W' : list Sym} {e : nat} {es : list nat}
      (h1 : HubP2W e W W1) (hrest : PureP2W W1 W' es) : PureP2W W W' (e :: es).

Lemma HubP2B_toWeak {e : nat} {W W1 : list Sym} (h : HubP2B e W W1) : HubP2W e W W1.
Proof. exact (conj (proj1 h) (proj1 (proj2 h))). Qed.

Lemma PureP2_toWeak {W W' : list Sym} {es : list nat} (hp : PureP2 W W' es) : PureP2W W W' es.
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 _ IH].
  - exact (PureP2W_nil W).
  - exact (PureP2W_cons (HubP2B_toWeak h1) IH).
Qed.

Lemma PureP2W_append {W1 W2 W3 : list Sym} {es1 es2 : list nat}
    (h1 : PureP2W W1 W2 es1) (h2 : PureP2W W2 W3 es2) : PureP2W W1 W3 (es1 ++ es2).
Proof.
  induction h1 as [W | Wa Wb Wc e es' ha _ IH].
  - exact h2.
  - exact (PureP2W_cons ha (IH h2)).
Qed.

Lemma PureP2W_prependStep {W0 W1 W2 : list Sym} {es : list nat}
    (hpos : 1 <= sumList es)
    (hstep : forall r : Stream Sym,
      (b0 {{E}}> (T2 *> T0 *> T1 *> W0 *> r)) -[ tm ]->*
      (b0 {{E}}> (T2 *> T0 *> T1 *> W1 *> r)))
    (hp : PureP2W W1 W2 es) : PureP2W W0 W2 es.
Proof.
  destruct hp as [W | Wa Wb Wc e es' h1 hrest].
  - cbn [sumList] in hpos; lia.
  - refine (PureP2W_cons (conj (proj1 h1) (fun r => _)) hrest).
    destruct (proj2 h1 r) as [Lt [hpL hs]].
    exists Lt. split; [exact hpL | exact (stepStar_trans (hstep r) hs)].
Qed.

Lemma PureP2W_dump {W W' S_in S_out : list Sym} {es : list nat} {tail : Stream Sym}
    (hp : PureP2W W W' es) :
    forall (hd : CanDumpTail S_in (sumList es) S_out tail),
    (b0 {{E}}> (T2 *> T0 *> T1 *> (W ++ S_in) *> tail)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *> (W' ++ S_out) *> tail)).
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 _ IH] in S_in |- *; intros hd.
  - destruct hd as [f [hf0 [hfE _]]].
    cbn [sumList] in hfE.
    assert (hEq : S_in = S_out) by congruence. rewrite <- hEq. apply evstep_refl.
  - cbn [sumList] in hd.
    destruct (CanDumpTail_oneHub hd (proj1 h1) ltac:(lia)) as [S1 [hsink hd1]].
    destruct (proj2 h1 (S_in *> tail)) as [Lt [hpL hs1]].
    rewrite Str_app_assoc.
    eapply evstep_trans; [exact hs1 |].
    eapply evstep_trans; [exact (hsink Wb Lt hpL) |].
    replace (e + sumList es' - e) with (sumList es') in hd1 by lia.
    exact (IH S1 hd1).
Qed.

Lemma HubP2W_liftCell {e : nat} {W W1 : list Sym} (a : nat) (hc : bool) (b : nat)
    (hok : hc = true \/ (1 <= a /\ 1 <= b)) (h : HubP2W e W W1) :
    HubP2W e (W ++ encS a hc b [] None) (W1 ++ encS a hc b [] None).
Proof.
  split; [exact (proj1 h) | intros r].
  destruct (proj2 h (encS a hc b [] None *> r)) as [Lt [hpL hs1]].
  rewrite Str_app_assoc.
  destruct hc.
  - destruct (pipeL_mid_h1 a b hpL r) as [Lt' [hpL' hs2]].
    exists Lt'. split.
    + eapply pipeL_eqR; [| exact hpL'].
      unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
    + eapply evstep_trans; [exact hs1 |].
      unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc, ?Str_app_assoc. exact hs2.
  - destruct hok as [hf | [ha hb]]; [discriminate |].
    destruct (pipeL_mid_h0 (a - 1) (b - 1) hpL r) as [Lt' [hpL' hs2]].
    replace (a - 1 + 1) with a in hpL' by lia.
    replace (b - 1 + 1) with b in hpL' by lia.
    replace (a - 1 + 1) with a in hs2 by lia.
    replace (b - 1 + 1) with b in hs2 by lia.
    exists Lt'. split.
    + eapply pipeL_eqR; [| exact hpL'].
      unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
    + eapply evstep_trans; [exact hs1 |].
      unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc, ?Str_app_assoc. exact hs2.
Qed.

Lemma PureP2W_liftCell {W W' : list Sym} {es : list nat} (a : nat) (hc : bool) (b : nat)
    (hok : hc = true \/ (1 <= a /\ 1 <= b)) (hp : PureP2W W W' es) :
    PureP2W (W ++ encS a hc b [] None) (W' ++ encS a hc b [] None) es.
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 _ IH].
  - exact (PureP2W_nil _).
  - exact (PureP2W_cons (HubP2W_liftCell a hc b hok h1) IH).
Qed.

Definition encPairRun_nat (a1 : nat) (h1 : bool) (b1 a2 : nat) (h2 : bool) (b2 rep : nat) : list Sym :=
  (encS a1 h1 b1 [] None ++ encS a2 h2 b2 [] None) ^^ rep.

Lemma encItem_pairRun_eq (a1 : N) (h1 : bool) (b1 a2 : N) (h2 : bool) (b2 rep : N) :
  encItem (RIpairRun a1 h1 b1 a2 h2 b2 rep) =
  encPairRun_nat (N.to_nat a1) h1 (N.to_nat b1) (N.to_nat a2) h2 (N.to_nat b2) (N.to_nat rep).
Proof.
  unfold encItem, encPairRun_nat, encSingle, encS; cbn [encSegTail].
  rewrite ?app_nil_r, ?append_assoc. reflexivity.
Qed.

Lemma PureP2W_liftPairRun {W W' : list Sym} {es : list nat}
    (a1 b1 a2 b2 rep : nat) (hp : PureP2W W W' es) :
    PureP2W (W ++ encPairRun_nat a1 true b1 a2 true b2 rep)
      (W' ++ encPairRun_nat a1 true b1 a2 true b2 rep) es.
Proof.
  revert W W' hp; induction rep as [|rep' IH]; intros W W' hp.
  - unfold encPairRun_nat; rewrite zPz, ?app_nil_r. exact hp.
  - pose proof (PureP2W_liftCell a1 true b1 (or_introl eq_refl) hp) as h1.
    pose proof (PureP2W_liftCell a2 true b2 (or_introl eq_refl) h1) as h2.
    pose proof (IH _ _ h2) as h3.
    unfold encPairRun_nat in h3 |- *.
    replace (S rep') with (rep' + 1) by lia.
    rewrite (list_pow_succ (encS a1 true b1 [] None ++ encS a2 true b2 [] None) rep'), ?append_assoc.
    rewrite ?append_assoc in h3. exact h3.
Qed.

Lemma pipeL_q0_b0_finish {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (k a2 : nat) (h2 : bool) (b2 : nat) (hb2 : h2 = true \/ 1 <= b2)
    (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL En (R_out ++ encS (k + a2 + 1) h2 b2 [] None) Lt' /\
      (([S1] *> (T3 ^^ (k + 1)) *> T2 *> Lt) {{A}}> (encS a2 h2 b2 [] None *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  destruct h2.
  - destruct (PipeL_head0 hp) as [l0 hl0].
    assert (h1 : (([S1] *> (T3 ^^ (k + 1)) *> T2 *> Lt) {{A}}> (encS a2 true b2 [] None *> r)) -[ tm ]->*
                 (([S1] *> (T3 ^^ (k + 1 + a2)) *> T2 *> Lt) {{A}}> (T5 *> (T4 ^^ b2) *> r))).
    { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc, ?Str_app_assoc.
      eapply evstep_trans; [exact (rule_q0_t2 a2 ((T3 ^^ (k + 1)) *> T2 *> Lt) (T5 *> (T4 ^^ b2) *> r)) |].
      rewrite <- pow_add_blank. replace (a2 + (k + 1)) with (k + 1 + a2) by lia. apply evstep_refl. }
    exists ((T5 ^^ b2) *> T4 *> (T3 ^^ (k + a2 + 1)) *> Lt). split.
    + eapply pipeL_eqR; [| exact (pipeL_noT2_blk b2 (k + a2 + 1) hp)].
      unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
    + eapply evstep_trans; [exact h1 |].
      replace (k + 1 + a2) with (S (k + a2)) by lia. rewrite zPsr.
      destruct (head0_t3_t0 (k + a2) ([S0; S1] *> T0 *> l0)) as [l' hl'].
      assert (hs1 : (([S1] *> T3 *> (T3 ^^ (k + a2)) *> T2 *> Lt) {{A}}> (T5 *> (T4 ^^ b2) *> r)) -[ tm ]->*
                    (((T3 ^^ (k + a2)) *> T2 *> Lt) {{E}}> (T0 *> T2 *> T4 *> (T4 ^^ b2) *> r))).
      { rewrite hl0. change (T2 *> T0 *> l0) with (T0 *> [S0; S1] *> T0 *> l0).
        rewrite hl'. exact (step_q0_t5_on_t3 l' ((T4 ^^ b2) *> r)). }
      eapply evstep_trans; [exact hs1 |].
      rewrite hl0.
      change (T2 *> T0 *> l0) with (T0 *> [S0; S1] *> T0 *> l0).
      eapply evstep_trans; [exact (rule_E_t3 (k + a2) ([S0; S1] *> T0 *> l0) (T2 *> T4 *> (T4 ^^ b2) *> r)) |].
      change (T0 *> [S0; S1] *> T0 *> l0) with (T2 *> T0 *> l0).
      eapply evstep_trans; [exact (step_E_t2_bounce (T0 *> l0) ((T2 ^^ (k + a2)) *> T2 *> T4 *> (T4 ^^ b2) *> r)) |].
      rewrite zPal.
      eapply evstep_trans; [exact (rule_C_1_t2 (S (k + a2)) (T3 *> T0 *> l0) (T4 *> (T4 ^^ b2) *> r)) |].
      rewrite zPal.
      eapply evstep_trans; [exact (step_C_1_to_q0 ((T3 ^^ S (S (k + a2))) *> T0 *> l0) (T4 *> (T4 ^^ b2) *> r)) |].
      rewrite zPsr.
      replace (S (k + a2)) with (k + a2 + 1) by lia.
      eapply evstep_trans; [exact (step_q0_t4_first ((T3 ^^ (k + a2 + 1)) *> T0 *> l0) ((T4 ^^ b2) *> r)) |].
      exact (rule_q0_t4_next b2 (T4 *> (T3 ^^ (k + a2 + 1)) *> T0 *> l0) r).
  - destruct hb2 as [hf | hb2p]; [discriminate |].
    set (b2' := b2 - 1).
    assert (hb2_eq : b2 = b2' + 1) by lia.
    rewrite hb2_eq.
    assert (h1 : (([S1] *> (T3 ^^ (k + 1)) *> T2 *> Lt) {{A}}> (encS a2 false (b2' + 1) [] None *> r)) -[ tm ]->*
                 (([S1] *> (T3 ^^ (k + 1 + a2)) *> T2 *> Lt) {{A}}> ((T4 ^^ (b2' + 1)) *> r))).
    { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc, ?Str_app_assoc.
      eapply evstep_trans; [exact (rule_q0_t2 a2 ((T3 ^^ (k + 1)) *> T2 *> Lt) ((T4 ^^ (b2' + 1)) *> r)) |].
      rewrite <- pow_add_blank. replace (a2 + (k + 1)) with (k + 1 + a2) by lia. apply evstep_refl. }
    exists ((T5 ^^ b2') *> T4 *> (T3 ^^ (k + a2)) *> T2 *> Lt). split.
    + eapply pipeL_eqR; [| exact (pipeL_T2_blk b2' (k + a2) hp)].
      unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
    + eapply evstep_trans; [exact h1 |].
      replace (k + 1 + a2) with (S (k + a2)) by lia.
      replace (b2' + 1) with (S b2') by lia.
      rewrite !zPsr.
      eapply evstep_trans; [exact (step_q0_t4_first ((T3 ^^ (k + a2)) *> T2 *> Lt) ((T4 ^^ b2') *> r)) |].
      exact (rule_q0_t4_next b2' (T4 *> (T3 ^^ (k + a2)) *> T2 *> Lt) r).
Qed.

(* ========================================================================= *)
(* Section 13.1: Prefix-Sum SuffixShift & Transparent/Active Lifters         *)
(* ========================================================================= *)

Lemma my_firstn_skipn (n : nat) (l : list nat) :
  List.firstn n l ++ List.skipn n l = l.
Proof.
  revert l; induction n as [|n' IH]; intros [|x xs]; simpl; [reflexivity | reflexivity | reflexivity |].
  f_equal. exact (IH xs).
Qed.

Lemma my_skipn_skipn (a b : nat) (l : list nat) :
  List.skipn b (List.skipn a l) = List.skipn (a + b) l.
Proof.
  revert l; induction a as [|a' IH]; intros [|x xs]; simpl; try reflexivity.
  - destruct b; reflexivity.
  - exact (IH xs).
Qed.

Lemma my_length_skipn (n : nat) (l : list nat) :
  List.length (List.skipn n l) = List.length l - n.
Proof.
  revert l; induction n as [|n' IH]; intros [|x xs]; simpl; try lia.
  exact (IH xs).
Qed.

Lemma sumList_firstn_add (l : list nat) (a b : nat) :
  sumList (List.firstn (a + b) l) =
  sumList (List.firstn a l) + sumList (List.firstn b (List.skipn a l)).
Proof.
  revert l; induction a as [|a' IH]; intros [|x xs]; simpl; try lia.
  - destruct b; simpl; lia.
  - rewrite (IH xs). lia.
Qed.

Definition SuffixShift (c : nat) (l_in l_out : list nat) : Prop :=
  exists k, k < List.length l_in /\ (k = 0 \/ sumList (List.firstn k l_in) < c) /\
    c <= sumList (List.firstn (k + 1) l_in) /\
    l_out = (sumList (List.firstn (k + 1) l_in) - c) :: List.skipn (k + 1) l_in.

Lemma SuffixShift_zero (e0 : nat) (es : list nat) :
  SuffixShift 0 (e0 :: es) (e0 :: es).
Proof.
  exists 0. simpl. split; [lia | split; [left; reflexivity | split; [lia | f_equal; lia]]].
Qed.

Lemma SuffixShift_head_ge {c e0 : nat} {es : list nat} (hle : c <= e0) :
  SuffixShift c (e0 :: es) ((e0 - c) :: es).
Proof.
  exists 0. simpl. split; [lia | split; [left; reflexivity | split; [lia | f_equal; lia]]].
Qed.

Lemma SuffixShift_cons_lt {c e0 : nat} {es l_out : list nat}
    (hlt : e0 < c) (h : SuffixShift (c - e0) es l_out) :
    SuffixShift c (e0 :: es) l_out.
Proof.
  destruct h as [k [hk [hlt_k [hge_k hout]]]].
  exists (S k). simpl.
  split; [lia | split].
  - right. destruct hlt_k as [hk0 | hlt']; [subst k; simpl; lia | lia].
  - replace (k + 1) with (S k) in * by lia. simpl in *.
    split; [lia | rewrite hout; f_equal; lia].
Qed.

Lemma SuffixShift_trans {c1 c2 : nat} {l0 l1 l2 : list nat}
    (h1 : SuffixShift c1 l0 l1) (h2 : SuffixShift c2 l1 l2) :
    SuffixShift (c1 + c2) l0 l2.
Proof.
  destruct h1 as [k1 [hk1 [hlt1 [hge1 hl1]]]]; subst l1.
  destruct h2 as [k2 [hk2 [hlt2 [hge2 hout]]]].
  cbn [List.length] in hk2; rewrite my_length_skipn in hk2.
  exists (k1 + k2).
  split; [lia | split].
  - destruct k2 as [|k2'].
    + replace (k1 + 0) with k1 by lia.
      destruct hlt1 as [hk0 | hlt1']; [left; exact hk0 | right; lia].
    + right. destruct hlt2 as [h0 | hlt2']; [discriminate |].
      cbn [List.firstn sumList] in hlt2'.
      pose proof (sumList_firstn_add l0 (k1 + 1) k2') as hsum.
      replace (k1 + S k2') with ((k1 + 1) + k2') by lia.
      rewrite hsum. lia.
  - pose proof (sumList_firstn_add l0 (k1 + 1) k2) as hsum.
    replace (k2 + 1) with (S k2) in hge2, hout by lia.
    cbn [List.firstn List.skipn sumList] in hge2, hout.
    rewrite my_skipn_skipn in hout.
    replace (k1 + k2 + 1) with ((k1 + 1) + k2) by lia.
    rewrite hsum.
    split; [lia | rewrite hout; f_equal; lia].
Qed.

Lemma SuffixShift_sum_eq {c : nat} {l_in l_out : list nat}
    (h : SuffixShift c l_in l_out) : sumList l_out = sumList l_in - c.
Proof.
  destruct h as [k [_ [_ [hge hout]]]]; subst l_out.
  pose proof (my_firstn_skipn (k + 1) l_in) as hsplit.
  assert (hsum : sumList l_in = sumList (List.firstn (k + 1) l_in) + sumList (List.skipn (k + 1) l_in)).
  { rewrite <- hsplit at 1. apply sumList_append. }
  cbn [sumList]. lia.
Qed.

(* --- ScratchS4B1.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

Lemma SuffixShift_head_ge_of_gap {c Kv e0' : nat} {l_in es' : list nat}
    (h : SuffixShift c l_in (e0' :: es'))
    (hgap : forall j, j < List.length l_in ->
      sumList (List.firstn (j + 1) l_in) < c \/ c + Kv <= sumList (List.firstn (j + 1) l_in)) :
    Kv <= e0'.
Proof.
  destruct h as [k [hk [_ [hge hout]]]].
  inversion hout; subst e0' es'; clear hout.
  destruct (hgap k hk); lia.
Qed.

Lemma SuffixShift_singleton {c e0 e0' : nat} {es' : list nat}
    (h : SuffixShift c [e0] (e0' :: es')) : e0' = e0 - c /\ es' = [].
Proof.
  destruct h as [k [hk [_ [_ hout]]]].
  simpl in hk. assert (k = 0) by lia; subst k.
  simpl in hout. inversion hout. split; [lia | reflexivity].
Qed.

Lemma PureP2_lift2SegCell_shift {W W' : list Sym} {es : list nat}
    (a : nat) (hc : bool) (s0 s1 : nat) (hok : hc = true \/ (1 <= a /\ 1 <= s0))
    (hp : PureP2 W W' es) :
    forall (hge : s1 + 1 <= sumList es),
    exists e0' es', OneBlock (W ++ encS a hc s0 (sp1 s1) None)
        (W' ++ encS a hc (s0 + s1 + 1) [] None) e0' es' /\
      SuffixShift (s1 + 1) es (e0' :: es').
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 hrest IH] in s0, s1, hok |- *; intros hge.
  - cbn [sumList] in hge; lia.
  - cbn [sumList] in hge.
    pose proof (proj1 h1) as he1.
    destruct (Nat.leb_spec0 e s1) as [hlt | hgt].
    + assert (hok' : hc = true \/ (1 <= a /\ 1 <= s0 + e)).
      { destruct hok as [hh | [ha hs]]; [left; exact hh | right; lia]. }
      destruct (IH (s0 + e) (s1 - e) hok' ltac:(lia)) as [e0' [es_out [[Wm [hp1 hpp]] hsh]]].
      replace (s0 + e + (s1 - e) + 1) with (s0 + s1 + 1) in hpp by lia.
      assert (hsh' : SuffixShift (s1 + 1) (e :: es') (e0' :: es_out)).
      { apply SuffixShift_cons_lt; [lia |].
        replace (s1 + 1 - e) with (s1 - e + 1) by lia. exact hsh. }
      exists e0', es_out. split; [| exact hsh'].
      exists Wm. split; [| exact hpp].
      intros W_next r.
      pose proof (PureP2_lift2SegCell_dump a hc s0 s1 (PureP2_cons h1 (PureP2_nil Wb)) hok
        ltac:(cbn [sumList]; lia) (W_next *> r)) as hd.
      cbn [sumList] in hd. replace (e + 0) with e in hd by lia.
      destruct (hp1 W_next r) as [cfg [hpe hst]].
      exists cfg. split; [exact hpe |].
      rewrite ?Str_app_assoc.
      rewrite ?Str_app_assoc in hd; rewrite ?Str_app_assoc in hst.
      exact (stepStar_trans hd hst).
    + assert (hle : s1 <= e - 1) by lia.
      assert (hok_after : hc = true \/ (1 <= a /\ 2 <= s0 + s1 + 1)).
      { destruct hok as [hh | [ha hs]]; [left; exact hh | right; lia]. }
      assert (hsh' : SuffixShift (s1 + 1) (e :: es') ((e - 1 - s1) :: es')).
      { pose proof (SuffixShift_head_ge (es := es') (c := s1 + 1) (e0 := e) ltac:(lia)) as hh.
        replace (e - (s1 + 1)) with (e - 1 - s1) in hh by lia. exact hh. }
      exists (e - 1 - s1), es'. split; [| exact hsh'].
      exists (Wb ++ encS a hc (s0 + s1 + 1) [] None). split.
      * intros W_next r.
        destruct (proj1 (proj2 h1) (encS a hc s0 (sp1 s1) None *> W_next *> r)) as [Lt [hpL hs1]].
        destruct (pipeL_mid_cell a hc s0 hok hpL (T3 *> (T4 ^^ s1) *> W_next *> r)) as [Lt1 [hpL1 hs2]].
        destruct (pipeL_absorb_2seg_exact s1 hle hpL1 (W_next *> r)) as [Lt2 [hpL2 hs3]].
        assert (hpL2' : PipeL1 (e - 1 - s1) (Wb ++ encS a hc (s0 + s1 + 1) [] None) Lt2).
        { eapply pipeL1_eqR; [| exact hpL2].
          unfold encS; cbn [encSegTail].
          replace (s0 + s1 + 1) with (s0 + (s1 + 1)) by lia.
          rewrite (list_pow_add T4 s0 (s1 + 1)), ?app_nil_r, ?append_assoc. reflexivity. }
        exists (([S1; S1] *> Lt2) {{F}}> (W_next *> r)).
        split; [left; exists Lt2; split; [exact hpL2' | reflexivity] |].
        rewrite ?Str_app_assoc.
        eapply evstep_trans; [exact hs1 |].
        assert (hstart2 : encS a hc s0 (sp1 s1) None *> W_next *> r =
                          (((T2 ^^ a) ++ (if hc then T5 else [])) ++ (T4 ^^ s0)) *> T3 *> (T4 ^^ s1) *> W_next *> r).
        { unfold encS; rewrite encSegTail_sp1, ?append_assoc, ?Str_app_assoc. reflexivity. }
        rewrite hstart2. exact (stepStar_trans hs2 hs3).
      * exact (PureP2_liftCell a hc (s0 + s1 + 1) hok_after ltac:(lia) hrest).
Qed.

Lemma PureP2_lift2SegS0Zero_shift {W W' : list Sym} {es : list nat}
    (m b : nat) (hm : 1 <= m) (hp : PureP2 W W' es) (hge : b + 2 <= sumList es) :
    exists e0' es', OneBlock (((W ++ (T2 ^^ (2 * m))) ++ T3) ++ (T4 ^^ (b + 1)))
        (W' ++ encS (2 * m) false (b + 2) [] None) e0' es' /\
      SuffixShift (b + 2) es (e0' :: es').
Proof.
  destruct hp as [W | W Wb W' e es' h1 hrest].
  - cbn [sumList] in hge; lia.
  - cbn [sumList] in hge.
    pose proof (proj1 h1) as he1.
    destruct (Nat.leb_spec0 (b + 1) (e - 1)) as [hfull | hnfull].
    + assert (hsh' : SuffixShift (b + 2) (e :: es') ((e - 1 - (b + 1)) :: es')).
      { pose proof (SuffixShift_head_ge (es := es') (c := b + 2) (e0 := e) ltac:(lia)) as hh.
        replace (e - (b + 2)) with (e - 1 - (b + 1)) in hh by lia. exact hh. }
      exists (e - 1 - (b + 1)), es'. split; [| exact hsh'].
      exists (Wb ++ encS (2 * m) false (b + 2) [] None). split.
      * intros W_next r.
        destruct (proj1 (proj2 h1) ((T2 ^^ (2 * m)) *> T3 *> (T4 ^^ (b + 1)) *> W_next *> r))
          as [Lt [hpL hs1]].
        pose proof (rule_q0_t2 (2 * m) (T2 *> Lt) (T3 *> (T4 ^^ (b + 1)) *> W_next *> r)) as hs2.
        assert (hT3s : (T3 ^^ (2 * m)) *> T2 *> Lt = T3 *> (T3 ^^ (2 * m - 1)) *> T2 *> Lt).
        { replace (2 * m) with (S (2 * m - 1)) at 1 by lia. rewrite zPsr. reflexivity. }
        pose proof (step_q0_t3_punch ((T3 ^^ (2 * m - 1)) *> T2 *> Lt) ((T4 ^^ (b + 1)) *> W_next *> r)) as hs3.
        pose proof (pipeL_T2_blk 0 (2 * m - 1) hpL) as hpblk.
        rewrite zPz, zLan in hpblk; replace (0 + 1) with 1 in hpblk by lia.
        destruct (pipeL_eat_t4_pipeL1 b hfull hpblk (W_next *> r)) as [Lt2 [hpL2 hs4]].
        assert (hpL2' : PipeL1 (e - 1 - (b + 1)) (Wb ++ encS (2 * m) false (b + 2) [] None) Lt2).
        { eapply pipeL1_eqR; [| exact hpL2].
          unfold encS; cbn [encSegTail].
          replace (2 * m - 1 + 1) with (2 * m) by lia.
          replace (b + 2) with (1 + (b + 1)) by lia.
          rewrite (list_pow_add T4 1 (b + 1)), ?app_nil_r, ?append_assoc. reflexivity. }
        exists (([S1; S1] *> Lt2) {{F}}> (W_next *> r)).
        split; [left; exists Lt2; split; [exact hpL2' | reflexivity] |].
        rewrite ?Str_app_assoc.
        eapply evstep_trans; [exact hs1 |].
        eapply evstep_trans; [exact hs2 |].
        rewrite hT3s. exact (stepStar_trans hs3 hs4).
      * exact (PureP2_liftCell (2 * m) false (b + 2) ltac:(right; split; lia) ltac:(lia) hrest).
    + destruct (PureP2_lift2SegCell_shift (2 * m) false e (b - (e - 1))
                  ltac:(right; split; lia) hrest ltac:(lia))
        as [e0' [es_out [[Wm [hp1 hpp]] hsh]]].
      replace (e + (b - (e - 1)) + 1) with (b + 2) in hpp by lia.
      assert (hsh' : SuffixShift (b + 2) (e :: es') (e0' :: es_out)).
      { apply SuffixShift_cons_lt; [lia |].
        replace (b + 2 - e) with (b - (e - 1) + 1) by lia. exact hsh. }
      exists e0', es_out. split; [| exact hsh'].
      exists Wm. split; [| exact hpp].
      intros W_next r.
      destruct (proj1 (proj2 h1) ((T2 ^^ (2 * m)) *> T3 *> (T4 ^^ (b + 1)) *> W_next *> r))
        as [Lt [hpL hs1]].
      pose proof (rule_q0_t2 (2 * m) (T2 *> Lt) (T3 *> (T4 ^^ (b + 1)) *> W_next *> r)) as hs2.
      assert (hT3s : (T3 ^^ (2 * m)) *> T2 *> Lt = T3 *> (T3 ^^ (2 * m - 1)) *> T2 *> Lt).
      { replace (2 * m) with (S (2 * m - 1)) at 1 by lia. rewrite zPsr. reflexivity. }
      pose proof (step_q0_t3_punch ((T3 ^^ (2 * m - 1)) *> T2 *> Lt) ((T4 ^^ (b + 1)) *> W_next *> r)) as hs3.
      pose proof (pipeL_T2_blk 0 (2 * m - 1) hpL) as hpblk.
      rewrite zPz, zLan in hpblk; replace (0 + 1) with 1 in hpblk by lia.
      assert (hR : (T4 ^^ (b + 1)) *> W_next *> r =
                   (T4 ^^ (e - 1)) *> T4 *> (T4 ^^ (b - (e - 1))) *> W_next *> r).
      { replace (b + 1) with ((e - 1) + (1 + (b - (e - 1)))) by lia.
        simp_pow_add; rewrite zP1. reflexivity. }
      destruct (pipeL_eat_t4 (e - 1) (Nat.le_refl _) hpblk (T4 *> (T4 ^^ (b - (e - 1))) *> W_next *> r))
        as [Lt2 [hpL2 hs4]].
      assert (hsub0 : (e - 1) - (e - 1) = 0) by lia.
      pose proof (pipeL_eqE hsub0 hpL2) as hpL2'.
      destruct (hp1 W_next r) as [cfg [hpe hst]].
      exists cfg. split; [exact hpe |].
      rewrite ?Str_app_assoc.
      eapply evstep_trans; [exact hs1 |].
      eapply evstep_trans; [exact hs2 |].
      rewrite hT3s. eapply evstep_trans; [exact hs3 |].
      rewrite hR. eapply evstep_trans; [exact hs4 |].
      change (T4 *> (T4 ^^ (b - (e - 1))) *> W_next *> r)
        with ([S0; S1] *> T3 *> (T4 ^^ (b - (e - 1))) *> W_next *> r).
      eapply evstep_trans; [exact (PipeL_unwind hpL2' _) |].
      assert (hM : (((Wb ++ (T2 ^^ (2 * m - 1 + 1))) ++ (T4 ^^ 1)) ++ (T4 ^^ (e - 1)))
                     *> T3 *> (T4 ^^ (b - (e - 1))) *> W_next *> r =
                   ((Wb ++ encS (2 * m) false e (sp1 (b - (e - 1))) None) ++ W_next) *> r).
      { unfold encS; rewrite encSegTail_sp1.
        replace (2 * m - 1 + 1) with (2 * m) by lia.
        assert (hT4e : (T4 ^^ e) = (T4 ^^ 1) ++ (T4 ^^ (e - 1)))
          by (replace e with (1 + (e - 1)) at 1 by lia; apply list_pow_add).
        rewrite hT4e, ?app_nil_r, ?append_assoc, ?Str_app_assoc. reflexivity. }
      rewrite hM. exact hst.
Qed.

Lemma PureP2_liftASplitH0Even_shift {W W' : list Sym} {es : list nat}
    (aL q b : nat) (hp : PureP2 W W' es) :
    forall (hge : q + b + 2 <= sumList es),
    exists e0' es', OneBlock (W ++ encS aL false (b + 2) [] (Some (2 * q)))
        (W' ++ encS (aL + 2 * q + 1) false (b + 2) [] None) e0' es' /\
      SuffixShift (q + b + 2) es (e0' :: es').
Proof.
  induction hp as [W | Wa Wb Wc e es' h1 hrest IH] in aL, q |- *; intros hge.
  - cbn [sumList] in hge; lia.
  - cbn [sumList] in hge.
    pose proof (proj1 h1) as he1.
    destruct (Nat.leb_spec0 e q) as [hlt | hgt].
    + destruct (IH (aL + 2 * e) (q - e) ltac:(lia)) as [e0' [es_out [[Wm [hp1 hpp]] hsh]]].
      replace (aL + 2 * e + 2 * (q - e) + 1) with (aL + 2 * q + 1) in hpp by lia.
      assert (hsh' : SuffixShift (q + b + 2) (e :: es') (e0' :: es_out)).
      { apply SuffixShift_cons_lt; [lia |].
        replace (q + b + 2 - e) with (q - e + b + 2) by lia. exact hsh. }
      exists e0', es_out. split; [| exact hsh'].
      exists Wm. split; [| exact hpp].
      intros W_next r.
      destruct (proj1 (proj2 h1) (encS aL false (b + 2) [] (Some (2 * q)) *> W_next *> r))
        as [Lt [hpL hs1]].
      assert (hT4 : encS aL false (b + 2) [] (Some (2 * q)) *> W_next *> r =
                    (T2 ^^ aL) *> T0 *> (T2 ^^ (2 * q)) *> T0 *> [S1; S0; S1; S1] *> (T4 ^^ (b + 1)) *> W_next *> r).
      { unfold encS; cbn [encSegTail]. replace (b + 2) with (S (b + 1)) by lia.
        rewrite ?app_nil_r, ?append_assoc, ?Str_app_assoc, zPsr. reflexivity. }
      destruct (hp1 W_next r) as [cfg [hpe hst]].
      exists cfg. split; [exact hpe |].
      rewrite ?Str_app_assoc.
      eapply evstep_trans; [exact hs1 |].
      rewrite hT4.
      pose proof (pipeL_dump_wall3 (E_rem := ltac:(match type of hpL with PipeL ?x _ _ => exact x end)) aL (2 * q) ltac:(lia) hpL ([S1; S0; S1; S1] *> (T4 ^^ (b + 1)) *> W_next *> r)) as hdw.
      replace (e - 1 + 1) with e in hdw by lia.
      replace (2 * q - 2 * e) with (2 * (q - e)) in hdw by lia.
      eapply evstep_trans; [exact hdw |].
      assert (hR : (((Wb ++ (T2 ^^ (aL + 2 * e))) ++ T0) ++ (T2 ^^ (2 * (q - e))))
                     *> T0 *> [S1; S0; S1; S1] *> (T4 ^^ (b + 1)) *> W_next *> r =
                   ((Wb ++ encS (aL + 2 * e) false (b + 2) [] (Some (2 * (q - e)))) ++ W_next) *> r).
      { unfold encS; cbn [encSegTail]. replace (b + 2) with (S (b + 1)) by lia.
        rewrite ?app_nil_r, ?append_assoc, ?Str_app_assoc, zPsr. reflexivity. }
      rewrite hR. exact hst.
    + assert (hle : q <= e - 1) by lia.
      destruct (Nat.leb_spec0 (b + 1) (e - 1 - q)) as [hfull | hnfull].
      * assert (hsh' : SuffixShift (q + b + 2) (e :: es') ((e - 1 - q - (b + 1)) :: es')).
        { pose proof (SuffixShift_head_ge (es := es') (c := q + b + 2) (e0 := e) ltac:(lia)) as hh.
          replace (e - (q + b + 2)) with (e - 1 - q - (b + 1)) in hh by lia. exact hh. }
        exists (e - 1 - q - (b + 1)), es'. split; [| exact hsh'].
        exists (Wb ++ encS (aL + 2 * q + 1) false (b + 2) [] None). split.
        -- intros W_next r.
           destruct (proj1 (proj2 h1) (encS aL false (b + 2) [] (Some (2 * q)) *> W_next *> r))
             as [Lt [hpL hs1]].
           destruct (pipeL_asplit_heal_h0_even aL q (b + 1) hle hpL (W_next *> r)) as [Lt1 [hpL1 hs2]].
           destruct (pipeL_eat_t4_pipeL1 b hfull hpL1 (W_next *> r)) as [Lt2 [hpL2 hs3]].
           assert (hpL2' : PipeL1 (e - 1 - q - (b + 1)) (Wb ++ encS (aL + 2 * q + 1) false (b + 2) [] None) Lt2).
           { eapply pipeL1_eqR; [| exact hpL2].
             unfold encS; cbn [encSegTail]. replace (b + 2) with (1 + (b + 1)) by lia.
             rewrite (list_pow_add T4 1 (b + 1)), ?app_nil_r, ?append_assoc. reflexivity. }
           exists (([S1; S1] *> Lt2) {{F}}> (W_next *> r)).
           split; [left; exists Lt2; split; [exact hpL2' | reflexivity] |].
           rewrite ?Str_app_assoc.
           eapply evstep_trans; [exact hs1 |].
           assert (hs2' : (([S1] *> T2 *> Lt) {{A}}> (encS aL false (b + 2) [] (Some (2 * q)) *> W_next *> r)) -[ tm ]->*
                          (([S1; S1] *> Lt1) {{F}}> ((T4 ^^ (b + 1)) *> W_next *> r))).
           { unfold encS; cbn [encSegTail]. replace (b + 2) with (b + 1 + 1) by lia.
             rewrite ?app_nil_r, ?append_assoc, ?Str_app_assoc. exact hs2. }
           exact (stepStar_trans hs2' hs3).
        -- exact (PureP2_liftCell (aL + 2 * q + 1) false (b + 2) ltac:(right; split; lia) ltac:(lia) hrest).
      * set (Er := e - 1 - q).
        destruct (PureP2_lift2SegCell_shift (aL + 2 * q + 1) false (Er + 1) (b - Er)
                    ltac:(right; split; lia) hrest ltac:(lia))
          as [e0' [es_out [[Wm [hp1 hpp]] hsh]]].
        replace (Er + 1 + (b - Er) + 1) with (b + 2) in hpp by lia.
        assert (hsh' : SuffixShift (q + b + 2) (e :: es') (e0' :: es_out)).
        { apply SuffixShift_cons_lt; [lia |].
          replace (q + b + 2 - e) with (b - Er + 1) by lia. exact hsh. }
        exists e0', es_out. split; [| exact hsh'].
        exists Wm. split; [| exact hpp].
        intros W_next r.
        destruct (proj1 (proj2 h1) (encS aL false (b + 2) [] (Some (2 * q)) *> W_next *> r))
          as [Lt [hpL hs1]].
        destruct (pipeL_asplit_heal_h0_even aL q (b + 1) hle hpL (W_next *> r)) as [Lt1 [hpL1 hs2]].
        assert (hR : (T4 ^^ (b + 1)) *> W_next *> r =
                     (T4 ^^ Er) *> T4 *> (T4 ^^ (b - Er)) *> W_next *> r).
        { replace (b + 1) with (Er + (1 + (b - Er))) by lia.
          simp_pow_add; rewrite zP1. reflexivity. }
        destruct (pipeL_eat_t4 Er (Nat.le_refl _) hpL1 (T4 *> (T4 ^^ (b - Er)) *> W_next *> r))
          as [Lt2 [hpL2 hs3]].
        assert (hsub0 : Er - Er = 0) by lia.
        pose proof (pipeL_eqE hsub0 hpL2) as hpL2'.
        destruct (hp1 W_next r) as [cfg [hpe hst]].
        exists cfg. split; [exact hpe |].
        rewrite ?Str_app_assoc.
        eapply evstep_trans; [exact hs1 |].
        assert (hs2' : (([S1] *> T2 *> Lt) {{A}}> (encS aL false (b + 2) [] (Some (2 * q)) *> W_next *> r)) -[ tm ]->*
                       (([S1; S1] *> Lt1) {{F}}> ((T4 ^^ (b + 1)) *> W_next *> r))).
        { unfold encS; cbn [encSegTail]. replace (b + 2) with (b + 1 + 1) by lia.
          rewrite ?app_nil_r, ?append_assoc, ?Str_app_assoc. exact hs2. }
        eapply evstep_trans; [exact hs2' |].
        rewrite hR. eapply evstep_trans; [exact hs3 |].
        change (T4 *> (T4 ^^ (b - Er)) *> W_next *> r)
          with ([S0; S1] *> T3 *> (T4 ^^ (b - Er)) *> W_next *> r).
        eapply evstep_trans; [exact (PipeL_unwind hpL2' _) |].
        assert (hM : (((Wb ++ (T2 ^^ (aL + 2 * q + 1))) ++ (T4 ^^ 1)) ++ (T4 ^^ Er))
                       *> T3 *> (T4 ^^ (b - Er)) *> W_next *> r =
                     ((Wb ++ encS (aL + 2 * q + 1) false (Er + 1) (sp1 (b - Er)) None) ++ W_next) *> r).
        { unfold encS; rewrite encSegTail_sp1.
          replace (Er + 1) with (1 + Er) by lia.
          rewrite (list_pow_add T4 1 Er), ?app_nil_r, ?append_assoc, ?Str_app_assoc. reflexivity. }
        rewrite hM. exact hst.
Qed.

Lemma oneBlock_posT2_exact {W W' : list Sym} {e0 : nat} {es : list nat}
    (hb : OneBlock W W' e0 es) (hpos : 1 <= e0 + sumList es) :
    exists Wm e1 es1, 1 <= e1 /\ PureP2 Wm W' es1 /\
      (e0 :: es = e1 :: es1 \/ e0 :: es = 0 :: e1 :: es1) /\
      (forall (C_rest : list Sym) (r : Stream Sym),
        exists cfg, P1Entry e1 Wm (T2 ++ C_rest) r cfg /\
          (b0 {{E}}> (T2 *> T0 *> T1 *> (W ++ (T2 ++ C_rest)) *> r)) -[ tm ]->* cfg).
Proof.
  destruct hb as [W1 [h1 hp]].
  destruct e0 as [|e0'].
  - destruct hp as [W0 | Wa W2 Wb e1 es1 h2 hrest].
    + cbn [sumList] in hpos; lia.
    + exists W2, e1, es1.
      split; [exact (proj1 h2) | split; [exact hrest | split; [right; reflexivity |]]].
      intros C_rest r. exact (hubP1_zero_merge h1 h2 r).
  - exists W1, (S e0'), es.
    split; [lia | split; [exact hp | split; [left; reflexivity |]]].
    intros C_rest r. exact (h1 (T2 ++ C_rest) r).
Qed.

Lemma suffixShift_of_posT2 {c e0 e1 : nat} {es es1 l_out : list nat}
    (hc : 1 <= c) (heq : e0 :: es = e1 :: es1 \/ e0 :: es = 0 :: e1 :: es1)
    (h : SuffixShift c (e1 :: es1) l_out) : SuffixShift c (e0 :: es) l_out.
Proof.
  destruct heq as [h1 | h2].
  - rewrite h1. exact h.
  - rewrite h2. apply SuffixShift_cons_lt; [lia |].
    replace (c - 0) with c by lia. exact h.
Qed.

Lemma OneBlock_liftTransp_shift {W W' : list Sym} {e0 : nat} {es : list nat}
    (m b : nat) (hm : 1 <= m) (hb : OneBlock W W' e0 es) (hge : m + b + 2 <= e0 + sumList es) :
    exists e0' es', OneBlock (W ++ encS (2 * m) false (b + 2) [] None)
        (W' ++ encS (2 * m) false (b + 2) [] None) e0' es' /\
      SuffixShift (m + b + 2) (e0 :: es) (e0' :: es').
Proof.
  destruct (oneBlock_posT2_exact hb ltac:(lia)) as [Wm [e1 [es1 [he1 [hp [heq hP1]]]]]].
  assert (hsum1 : e1 + sumList es1 = e0 + sumList es).
  { destruct heq as [h1 | h2]; inversion h1 || inversion h2; subst; cbn [sumList]; lia. }
  assert (h2m_split : encS (2 * m) false (b + 2) [] None =
                      T2 ++ ((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2)))).
  { unfold encS; cbn [encSegTail]. replace (2 * m) with (1 + (2 * m - 1)) at 1 by lia.
    rewrite (list_pow_add T2 1 (2 * m - 1)), list_pow_one, ?app_nil_r, ?append_assoc. reflexivity. }
  destruct (Nat.ltb_spec0 e1 m) as [hlt_m | hge_m].
  - destruct (PureP2_liftASplitH0Even_shift (2 * e1 - 1) (m - e1) b hp ltac:(lia))
      as [e0' [es' [[Wf [hWf1 hWf2]] hsh]]].
    replace (2 * e1 - 1 + 2 * (m - e1) + 1) with (2 * m) in hWf2 by lia.
    assert (hsh1 : SuffixShift (m + b + 2) (e1 :: es1) (e0' :: es')).
    { apply SuffixShift_cons_lt; [lia |].
      replace (m + b + 2 - e1) with (m - e1 + b + 2) by lia. exact hsh. }
    exists e0', es'. split; [| eapply suffixShift_of_posT2; [lia | exact heq | exact hsh1]].
    exists Wf. split; [| exact hWf2].
    intros W_next r.
    destruct (hP1 (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next) r) as [cfg0 [hpe0 hs0]].
    assert (hpe0' : P1Entry e1 Wm ((T2 ^^ (2 * m)) ++ ((T4 ^^ (b + 2)) ++ W_next)) r cfg0).
    { assert (hEq : T2 ++ (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next) =
                    (T2 ^^ (2 * m)) ++ ((T4 ^^ (b + 2)) ++ W_next)).
      { replace (2 * m) with (1 + (2 * m - 1)) at 2 by lia.
        rewrite (list_pow_add T2 1 (2 * m - 1)), list_pow_one, ?append_assoc. reflexivity. }
      rewrite <- hEq. exact hpe0. }
    pose proof (p1Entry_asplit_create (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) (2 * m) he1 ltac:(lia) hpe0') as has.
    destruct (hWf1 W_next r) as [cfgf [hpef hsf]].
    exists cfgf. split; [exact hpef |].
    assert (hL : ((W ++ encS (2 * m) false (b + 2) [] None) ++ W_next) *> r =
                 (W ++ (T2 ++ (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next))) *> r).
    { rewrite h2m_split, ?append_assoc. reflexivity. }
    rewrite hL.
    eapply evstep_trans; [exact hs0 |].
    eapply evstep_trans; [exact has |].
    assert (hM : ((((Wm ++ (T2 ^^ (2 * e1 - 1))) ++ T0) ++ (T2 ^^ (2 * m - 2 * e1))) ++ ((T4 ^^ (b + 2)) ++ W_next)) *> r =
                 ((Wm ++ encS (2 * e1 - 1) false (b + 2) [] (Some (2 * (m - e1)))) ++ W_next) *> r).
    { unfold encS; cbn [encSegTail]. replace (2 * m - 2 * e1) with (2 * (m - e1)) by lia.
      rewrite ?app_nil_r, ?append_assoc. reflexivity. }
    rewrite hM. exact hsf.
  - destruct (Nat.eq_dec e1 m) as [heq_m | hne_m].
    + subst e1.
      destruct (PureP2_lift2SegS0Zero_shift m b hm hp ltac:(lia))
        as [e0' [es' [[Wf [hWf1 hWf2]] hsh]]].
      assert (hsh1 : SuffixShift (m + b + 2) (m :: es1) (e0' :: es')).
      { apply SuffixShift_cons_lt; [lia |].
        replace (m + b + 2 - m) with (b + 2) by lia. exact hsh. }
      exists e0', es'. split; [| eapply suffixShift_of_posT2; [lia | exact heq | exact hsh1]].
      exists Wf. split; [| exact hWf2].
      intros W_next r.
      destruct (hP1 (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next) r) as [cfg0 [hpe0 hs0]].
      assert (hpe0' : P1Entry m Wm (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ++ W_next) r cfg0).
      { assert (hEq : T2 ++ (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next) =
                      ((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ++ W_next).
        { replace (2 * m) with (1 + (2 * m - 1)) at 2 by lia.
          rewrite (list_pow_add T2 1 (2 * m - 1)), list_pow_one, ?append_assoc. reflexivity. }
        rewrite <- hEq. exact hpe0. }
      replace (b + 2) with ((b + 1) + 1) in hpe0' by lia.
      pose proof (p1Entry_transp_exact_m m (b + 1) hm hpe0') as hex.
      destruct (hWf1 W_next r) as [cfgf [hpef hsf]].
      exists cfgf. split; [exact hpef |].
      assert (hL : ((W ++ encS (2 * m) false (b + 2) [] None) ++ W_next) *> r =
                   (W ++ (T2 ++ (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next))) *> r).
      { rewrite h2m_split, ?append_assoc. reflexivity. }
      rewrite hL.
      eapply evstep_trans; [exact hs0 |].
      eapply evstep_trans; [exact hex |].
      (rewrite ?append_assoc in hsf; rewrite ?append_assoc). exact hsf.
    + destruct (Nat.leb_spec0 (m + b + 2) e1) as [hfull | hnfull].
      * pose proof (SuffixShift_head_ge (es := es1) hfull) as hsh1.
        exists (e1 - (m + b + 2)), es1.
        split; [| eapply suffixShift_of_posT2; [lia | exact heq | exact hsh1]].
        exists (Wm ++ encS (2 * m) false (b + 2) [] None). split.
        -- intros W_next r.
           destruct (hP1 (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next) r) as [cfg0 [hpe0 hs0]].
           assert (hpe0' : P1Entry e1 Wm (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ++ W_next) r cfg0).
           { assert (hEq : T2 ++ (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next) =
                           ((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ++ W_next).
             { replace (2 * m) with (1 + (2 * m - 1)) at 2 by lia.
               rewrite (list_pow_add T2 1 (2 * m - 1)), list_pow_one, ?append_assoc. reflexivity. }
             rewrite <- hEq. exact hpe0. }
           destruct (p1Entry_transp_pass m b hm hfull hpe0') as [Lt' [hpL' hs1]].
           assert (hpL'' : PipeL1 (e1 - (m + b + 2)) (Wm ++ encS (2 * m) false (b + 2) [] None) Lt').
           { eapply pipeL1_eqR; [| exact hpL'].
             unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity. }
           exists (([S1; S1] *> Lt') {{F}}> (W_next *> r)).
           split; [left; exists Lt'; split; [exact hpL'' | reflexivity] |].
           assert (hL : ((W ++ encS (2 * m) false (b + 2) [] None) ++ W_next) *> r =
                        (W ++ (T2 ++ (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next))) *> r).
           { rewrite h2m_split, ?append_assoc. reflexivity. }
           rewrite hL. exact (stepStar_trans hs0 hs1).
        -- exact (PureP2_liftCell (2 * m) false (b + 2) ltac:(right; split; lia) ltac:(lia) hp).
      * destruct (PureP2_lift2SegCell_shift (2 * m) false (e1 - m) (m + b + 1 - e1)
                    ltac:(right; split; lia) hp ltac:(lia))
          as [e0' [es' [[Wf [hWf1 hWf2]] hsh]]].
        replace (e1 - m + (m + b + 1 - e1) + 1) with (b + 2) in hWf2 by lia.
        assert (hsh1 : SuffixShift (m + b + 2) (e1 :: es1) (e0' :: es')).
        { apply SuffixShift_cons_lt; [lia |].
          replace (m + b + 2 - e1) with (m + b + 1 - e1 + 1) by lia. exact hsh. }
        exists e0', es'. split; [| eapply suffixShift_of_posT2; [lia | exact heq | exact hsh1]].
        exists Wf. split; [| exact hWf2].
        intros W_next r.
        destruct (hP1 (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next) r) as [cfg0 [hpe0 hs0]].
        assert (hpe0' : P1Entry e1 Wm (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ++ W_next) r cfg0).
        { assert (hEq : T2 ++ (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next) =
                        ((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ++ W_next).
          { replace (2 * m) with (1 + (2 * m - 1)) at 2 by lia.
            rewrite (list_pow_add T2 1 (2 * m - 1)), list_pow_one, ?append_assoc. reflexivity. }
          rewrite <- hEq. exact hpe0. }
        pose proof (p1Entry_transp_split (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) m b hm ltac:(lia) ltac:(lia) hpe0') as hsp.
        destruct (hWf1 W_next r) as [cfgf [hpef hsf]].
        exists cfgf. split; [exact hpef |].
        assert (hL : ((W ++ encS (2 * m) false (b + 2) [] None) ++ W_next) *> r =
                     (W ++ (T2 ++ (((T2 ^^ (2 * m - 1)) ++ (T4 ^^ (b + 2))) ++ W_next))) *> r).
        { rewrite h2m_split, ?append_assoc. reflexivity. }
        rewrite hL.
        eapply evstep_trans; [exact hs0 |].
        eapply evstep_trans; [exact hsp |].
        assert (hM : (((((Wm ++ (T2 ^^ (2 * m))) ++ (T4 ^^ (e1 - m))) ++ T3) ++ (T4 ^^ (m + b + 1 - e1))) ++ W_next) *> r =
                     ((Wm ++ encS (2 * m) false (e1 - m) (sp1 (m + b + 1 - e1)) None) ++ W_next) *> r).
        { unfold encS; rewrite encSegTail_sp1, ?append_assoc. reflexivity. }
        rewrite hM. exact hsf.
Qed.

Lemma OneBlock_liftTranspRun_shift (rep : nat) :
    forall {W W' : list Sym} {e0 : nat} {es : list nat}
    (m b : nat) (hm : 1 <= m) (hb : OneBlock W W' e0 es)
    (hge : rep * (m + b + 2) <= e0 + sumList es),
    exists e0' es', OneBlock (W ++ (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ^^ rep))
        (W' ++ (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ^^ rep)) e0' es' /\
      SuffixShift (rep * (m + b + 2)) (e0 :: es) (e0' :: es').
Proof.
  induction rep as [|k IH]; intros W W' e0 es m b hm hb hge.
  - exists e0, es. rewrite zPz, ?app_nil_r.
    split; [exact hb | simpl; exact (SuffixShift_zero e0 es)].
  - assert (hk : S k * (m + b + 2) = (m + b + 2) + k * (m + b + 2)) by lia.
    destruct (OneBlock_liftTransp_shift m b hm hb ltac:(lia)) as [e1 [es1 [hb1 hsh1]]].
    pose proof (SuffixShift_sum_eq hsh1) as hsum1; cbn [sumList] in hsum1.
    destruct (IH _ _ _ _ m b hm hb1 ltac:(lia)) as [e2 [es2 [hb2 hsh2]]].
    exists e2, es2. split.
    + unfold encS in hb2; cbn [encSegTail] in hb2.
      replace (S k) with (k + 1) by lia.
      rewrite (list_pow_succ ((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) k), ?append_assoc.
      rewrite ?app_nil_r, ?append_assoc in hb2. exact hb2.
    + rewrite hk. exact (SuffixShift_trans hsh1 hsh2).
Qed.

Lemma OneBlock_liftTranspItem_shift {W W' : list Sym} {e0 : nat} {es : list nat} (x : RleItem)
    (hx : isTranspItem x = true) (hb : OneBlock W W' e0 es) (hge : transpItemCost_nat x <= e0 + sumList es) :
    exists e0' es', OneBlock (W ++ encItem x) (W' ++ encItem x) e0' es' /\
      SuffixShift (transpItemCost_nat x) (e0 :: es) (e0' :: es').
Proof.
  destruct x as [a [|] b [|? ?] [?|] | a b rep | |]; cbn [isTranspItem] in hx; try discriminate.
  - split_andb.
    pose proof (N2Nat_div a 2) as Hadiv; change (N.to_nat 2%N) with 2 in Hadiv.
    pose proof (N2Nat_mod a 2) as Hamod; change (N.to_nat 2%N) with 2 in Hamod.
    set (m := N.to_nat a / 2).
    set (b' := N.to_nat b - 2).
    assert (ha_eq : N.to_nat a = 2 * m) by (unfold m; pose proof (Nat.div_mod (N.to_nat a) 2 ltac:(lia)); lia).
    assert (hb_eq : N.to_nat b = b' + 2) by (unfold b'; lia).
    assert (hcost : transpItemCost_nat (RIsingle a false b [] None) = m + b' + 2).
    { unfold transpItemCost_nat, transpItemCost. lia. }
    (try rewrite hcost in hge; try rewrite hcost).
    destruct (OneBlock_liftTransp_shift m b' ltac:(lia) hb hge) as [e0' [es' [hb' hsh']]].
    exists e0', es'. split; [| exact hsh'].
    cbn [encItem]; rewrite encSingle_eq_encS; cbn [option_map].
    rewrite ha_eq, hb_eq. exact hb'.
  - split_andb.
    pose proof (N2Nat_div a 2) as Hadiv; change (N.to_nat 2%N) with 2 in Hadiv.
    pose proof (N2Nat_mod a 2) as Hamod; change (N.to_nat 2%N) with 2 in Hamod.
    set (m := N.to_nat a / 2).
    set (b' := N.to_nat b - 2).
    assert (ha_eq : N.to_nat a = 2 * m) by (unfold m; pose proof (Nat.div_mod (N.to_nat a) 2 ltac:(lia)); lia).
    assert (hb_eq : N.to_nat b = b' + 2) by (unfold b'; lia).
    assert (hcost : transpItemCost_nat (RItranspRun a b rep) = N.to_nat rep * (m + b' + 2)).
    { unfold transpItemCost_nat, transpItemCost; rewrite N2Nat.inj_mul, N2Nat.inj_add, Hadiv; fold m; clear - hb_eq; clearbody m b'; nia. }
    (try rewrite hcost in hge; try rewrite hcost).
    destruct (OneBlock_liftTranspRun_shift (N.to_nat rep) m b' ltac:(lia) hb hge) as [e0' [es' [hb' hsh']]].
    exists e0', es'. split; [| exact hsh'].
    unfold encItem; rewrite ha_eq, hb_eq. exact hb'.
Qed.

Lemma OneBlock_liftTranspList_shift (xs : list RleItem) :
    forall {W W' : list Sym} {e0 : nat} {es : list nat}
    (hxs : isTranspList xs = true) (hb : OneBlock W W' e0 es)
    (hge : transpListCost_nat xs <= e0 + sumList es),
    exists e0' es', OneBlock (W ++ encItems xs) (W' ++ encItems xs) e0' es' /\
      SuffixShift (transpListCost_nat xs) (e0 :: es) (e0' :: es').
Proof.
  induction xs as [|x xs' IH]; intros W W' e0 es hxs hb hge.
  - exists e0, es. cbn [encItems transpListCost_nat transpListCost N.to_nat].
    rewrite ?app_nil_r. split; [exact hb | exact (SuffixShift_zero e0 es)].
  - cbn [isTranspList List.forallb] in hxs.
    apply Bool.andb_true_iff in hxs; destruct hxs as [hx hxs'].
    assert (hcs : transpListCost_nat (x :: xs') = transpItemCost_nat x + transpListCost_nat xs').
    { unfold transpListCost_nat, transpItemCost_nat; cbn [transpListCost]; lia. }
    (try rewrite hcs in hge; try rewrite hcs).
    destruct (OneBlock_liftTranspItem_shift x hx hb ltac:(lia)) as [e1 [es1 [hb1 hsh1]]].
    pose proof (SuffixShift_sum_eq hsh1) as hsum1; cbn [sumList] in hsum1.
    destruct (IH _ _ _ _ hxs' hb1 ltac:(lia)) as [e2 [es2 [hb2 hsh2]]].
    exists e2, es2. split; [| exact (SuffixShift_trans hsh1 hsh2)].
    cbn [encItems]; rewrite ?append_assoc.
    rewrite ?append_assoc in hb2. exact hb2.
Qed.

Lemma DirectBlock_liftTranspList {W W' : list Sym} {e : nat} (xs : list RleItem)
    (hxs : isTranspList xs = true) (hb : DirectBlock W W' e) (hge : transpListCost_nat xs <= e) :
    DirectBlock (W ++ encItems xs) (W' ++ encItems xs) (e - transpListCost_nat xs).
Proof.
  assert (hb1 : OneBlock W W' e []).
  { exists W'. split; [exact hb | exact (PureP2_nil W')]. }
  destruct (OneBlock_liftTranspList_shift xs hxs hb1 ltac:(cbn [sumList]; lia))
    as [e0' [es' [hb' hsh]]].
  destruct (SuffixShift_singleton hsh) as [he0 hes]; subst e0' es'.
  destruct hb' as [Wm [h1 hp]]. inversion hp; subst. exact h1.
Qed.

Lemma DirectBlock_liftS0 {W W' : list Sym} {e : nat}
    (m b : nat) (hb_pos : 1 <= b) (hb : DirectBlock W W' e) (hge : m + 1 <= e) :
    HubP2B (e - m) (W ++ encS (2 * m + 1) true (b + 1) [] None)
      (W' ++ encS (2 * m + 2) true b [] None).
Proof.
  split; [lia | split].
  - intros r.
    destruct (hb (encS (2 * m + 1) true (b + 1) [] None) r) as [cfg0 [hpe0 hs0]].
    assert (hpe0' : P1Entry e W' ((((T2 ^^ (2 * m + 1)) ++ T5) ++ (T4 ^^ (b + 1))) ++ []) r cfg0).
    { unfold encS in hpe0; cbn [encSegTail] in hpe0.
      (rewrite ?app_nil_r in hpe0; rewrite ?append_assoc in hpe0; rewrite ?app_nil_r; rewrite ?append_assoc). exact hpe0. }
    destruct (p1Entry_h1_enter_odd m b hge hpe0') as [Lt' [hpL' hs1]].
    exists Lt'. split.
    + eapply pipeL_eqR; [| exact hpL'].
      unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
    + rewrite zLan in hs1. exact (stepStar_trans hs0 hs1).
  - intros Wp hWp.
    assert (hsplit : W ++ encS (2 * m + 1) true (b + 1) [] None =
                     (W ++ encS (2 * m + 1) true b [] None) ++ T4).
    { unfold encS; cbn [encSegTail]. rewrite (list_pow_succ_right T4), ?app_nil_r, ?append_assoc. reflexivity. }
    assert (hWpEq : Wp = W ++ encS (2 * m + 1) true b [] None).
    { apply (@app_cancel_right _ _ _ T4). congruence. }
    subst Wp.
    set (b' := b - 1).
    assert (hb_eq : b = b' + 1) by lia.
    exists (W' ++ encS (2 * m + 2) true b' [] None). split.
    + rewrite hb_eq. unfold encS; cbn [encSegTail].
      rewrite (list_pow_succ_right T4), ?app_nil_r, ?append_assoc. reflexivity.
    + intros r. rewrite hb_eq.
      destruct (hb (encS (2 * m + 1) true (b' + 1) [] None) r) as [cfg0 [hpe0 hs0]].
      assert (hpe0' : P1Entry e W' ((((T2 ^^ (2 * m + 1)) ++ T5) ++ (T4 ^^ (b' + 1))) ++ []) r cfg0).
      { unfold encS in hpe0; cbn [encSegTail] in hpe0.
        (rewrite ?app_nil_r in hpe0; rewrite ?append_assoc in hpe0; rewrite ?app_nil_r; rewrite ?append_assoc). exact hpe0. }
      destruct (p1Entry_h1_enter_odd m b' hge hpe0') as [Lt' [hpL' hs1]].
      exists Lt'. split.
      * eapply pipeL_eqR; [| exact hpL'].
        unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
      * rewrite zLan in hs1. exact (stepStar_trans hs0 hs1).
Qed.

Lemma DirectBlock_liftS1 {W W' : list Sym} {e : nat}
    (m b : nat) (hm : 1 <= m) (hb_pos : 1 <= b) (hb : DirectBlock W W' e) (hge : m + 1 <= e) :
    HubP2B (e - m) (W ++ encS (2 * m) true (b + 1) [] None)
      (W' ++ encS (2 * m + 1) false (b + 1) [] None).
Proof.
  split; [lia | split].
  - intros r.
    destruct (hb (encS (2 * m) true (b + 1) [] None) r) as [cfg0 [hpe0 hs0]].
    assert (hpe0' : P1Entry e W' ((((T2 ^^ (2 * m)) ++ T5) ++ (T4 ^^ (b + 1))) ++ []) r cfg0).
    { unfold encS in hpe0; cbn [encSegTail] in hpe0.
      (rewrite ?app_nil_r in hpe0; rewrite ?append_assoc in hpe0; rewrite ?app_nil_r; rewrite ?append_assoc). exact hpe0. }
    destruct (p1Entry_h1_enter_even m b hm hge hpe0') as [Lt' [hpL' hs1]].
    exists Lt'. split.
    + eapply pipeL_eqR; [| exact hpL'].
      unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
    + rewrite zLan in hs1. exact (stepStar_trans hs0 hs1).
  - intros Wp hWp.
    assert (hsplit : W ++ encS (2 * m) true (b + 1) [] None =
                     (W ++ encS (2 * m) true b [] None) ++ T4).
    { unfold encS; cbn [encSegTail]. rewrite (list_pow_succ_right T4), ?app_nil_r, ?append_assoc. reflexivity. }
    assert (hWpEq : Wp = W ++ encS (2 * m) true b [] None).
    { apply (@app_cancel_right _ _ _ T4). congruence. }
    subst Wp.
    set (b' := b - 1).
    assert (hb_eq : b = b' + 1) by lia.
    exists (W' ++ encS (2 * m + 1) false (b' + 1) [] None). split.
    + rewrite hb_eq. unfold encS; cbn [encSegTail].
      rewrite (list_pow_succ_right T4), ?app_nil_r, ?append_assoc. reflexivity.
    + intros r. rewrite hb_eq.
      destruct (hb (encS (2 * m) true (b' + 1) [] None) r) as [cfg0 [hpe0 hs0]].
      assert (hpe0' : P1Entry e W' ((((T2 ^^ (2 * m)) ++ T5) ++ (T4 ^^ (b' + 1))) ++ []) r cfg0).
      { unfold encS in hpe0; cbn [encSegTail] in hpe0.
        (rewrite ?app_nil_r in hpe0; rewrite ?append_assoc in hpe0; rewrite ?app_nil_r; rewrite ?append_assoc). exact hpe0. }
      destruct (p1Entry_h1_enter_even m b' hm hge hpe0') as [Lt' [hpL' hs1]].
      exists Lt'. split.
      * eapply pipeL_eqR; [| exact hpL'].
        unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
      * rewrite zLan in hs1. exact (stepStar_trans hs0 hs1).
Qed.

Lemma DirectBlock_liftS2 {W W' : list Sym} {e : nat}
    (m b : nat) (hb : DirectBlock W W' e) (hge : m + b + 2 <= e) :
    DirectBlock (W ++ encS (2 * m + 1) false (b + 2) [] None)
      (W' ++ encS (2 * m + 1) true (b + 1) [] None) (e - (m + b + 2)).
Proof.
  intros W_next r.
  destruct (hb (encS (2 * m + 1) false (b + 2) [] None ++ W_next) r) as [cfg0 [hpe0 hs0]].
  assert (hpe0' : P1Entry e W' (((T2 ^^ (2 * m + 1)) ++ (T4 ^^ ((b + 1) + 1))) ++ W_next) r cfg0).
  { unfold encS in hpe0; cbn [encSegTail] in hpe0.
    replace (b + 2) with ((b + 1) + 1) in hpe0 by lia.
    (rewrite ?app_nil_r in hpe0; rewrite ?append_assoc in hpe0; rewrite ?app_nil_r; rewrite ?append_assoc). exact hpe0. }
  destruct (p1Entry_eat_t2_odd_t4 (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) m (b + 1) ltac:(lia) hpe0') as [Lt1 [hpL1 hs1]].
  destruct (pipeL_eat_t4_pipeL1 (En := ltac:(match type of hpL1 with PipeL ?x _ _ => exact x end)) b ltac:(lia) hpL1 (W_next *> r)) as [Lt2 [hpL2 hs2]].
  assert (hpL2' : PipeL1 (e - (m + b + 2)) (W' ++ encS (2 * m + 1) true (b + 1) [] None) Lt2).
  { replace (e - m - 1 - (b + 1)) with (e - (m + b + 2)) in hpL2 by lia.
    eapply pipeL1_eqR; [| exact hpL2].
    unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity. }
  exists (([S1; S1] *> Lt2) {{F}}> (W_next *> r)).
  split; [left; exists Lt2; split; [exact hpL2' | reflexivity] |].
  rewrite ?append_assoc. exact (stepStar_trans hs0 (stepStar_trans hs1 hs2)).
Qed.

Lemma HubP2B_lift2Seg_heal_direct {W W' : list Sym} {e : nat}
    (p s1 : nat) (h1 : HubP2B e W W') (hge : s1 + 1 <= e) :
    DirectBlock (((W ++ (T4 ^^ p)) ++ T3) ++ (T4 ^^ s1)) (W' ++ (T4 ^^ (p + s1 + 1))) (e - (s1 + 1)).
Proof.
  intros W_next r.
  destruct (proj1 (proj2 h1) ((T4 ^^ p) *> T3 *> (T4 ^^ s1) *> W_next *> r)) as [Lt [hpL hs1]].
  pose proof (rule_q0_t4_next p Lt (T3 *> (T4 ^^ s1) *> W_next *> r)) as hs2.
  pose proof (pipeL_t5 p hpL) as hpL1.
  destruct (pipeL_absorb_2seg_exact (E_rem := ltac:(match type of hpL1 with PipeL ?x _ _ => exact x end)) s1 ltac:(lia) hpL1 (W_next *> r)) as [Lt2 [hpL2 hs3]].
  assert (hpL2' : PipeL1 (e - (s1 + 1)) (W' ++ (T4 ^^ (p + s1 + 1))) Lt2).
  { replace (e - 1 - s1) with (e - (s1 + 1)) in hpL2 by lia.
    eapply pipeL1_eqR; [| exact hpL2].
    replace (p + s1 + 1) with (p + (s1 + 1)) by lia.
    rewrite (list_pow_add T4 p (s1 + 1)), ?append_assoc. reflexivity. }
  exists (([S1; S1] *> Lt2) {{F}}> (W_next *> r)).
  split; [left; exists Lt2; split; [exact hpL2' | reflexivity] |].
  rewrite ?Str_app_assoc. exact (stepStar_trans hs1 (stepStar_trans hs2 hs3)).
Qed.

(* --- ScratchS4B2a.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

Lemma DirectBlock_liftDigitCycle_exact {W0 W1 W2 W3 : list Sym} {E1 E2 E3 : nat}
    (m b : nat) (hb2_pos : 2 <= b)
    (hb1 : DirectBlock W0 W1 E1) (hb2 : DirectBlock W1 W2 E2) (hb3 : DirectBlock W2 W3 E3)
    (hE1 : m + 3 <= E1) (hE2 : m + 1 <= E2) (hE3 : m + 2 <= E3)
    (hTot : 3 * m + b + 3 <= E1 + E2 + E3) :
    exists e0' es', OneBlock (W0 ++ encS (2 * m + 1) false (b + 2) [] None)
        (W3 ++ encS (2 * m + 3) false b [] None) e0' es' /\
      e0' + sumList es' = E1 + E2 + E3 - (3 * m + b + 3) /\
      ((m + b + 2 <= E1 /\ e0' :: es' = [E1 - (m + b + 2); E2 - m; E3 - (m + 1)]) \/
       (E1 < m + b + 2 /\ 2 * m + b + 2 <= E1 + E2 /\ e0' :: es' = [E1 + E2 - (2 * m + b + 2); E3 - (m + 1)]) \/
       (E1 + E2 < 2 * m + b + 2 /\ e0' :: es' = [E1 + E2 + E3 - (3 * m + b + 3)])).
Proof.
  pose proof (DirectBlock_liftS1 (m + 1) (b - 1) ltac:(lia) ltac:(lia) hb3 ltac:(lia)) as hp3_hub.
  replace (2 * (m + 1)) with (2 * m + 2) in hp3_hub by lia.
  replace (2 * m + 2 + 1) with (2 * m + 3) in hp3_hub by lia.
  replace (b - 1 + 1) with b in hp3_hub by lia.
  pose proof (PureP2_cons hp3_hub (PureP2_nil _)) as hp3.
  destruct (Nat.leb_spec0 (m + b + 2) E1) as [hA | hnA].
  - pose proof (DirectBlock_liftS2 m b hb1 hA) as hb1'.
    assert (hb1_ob : OneBlock (W0 ++ encS (2 * m + 1) false (b + 2) [] None)
                              (W1 ++ encS (2 * m + 1) true (b + 1) [] None) (E1 - (m + b + 2)) []).
    { exists (W1 ++ encS (2 * m + 1) true (b + 1) [] None).
      split; [exact hb1' | exact (PureP2_nil _)]. }
    pose proof (DirectBlock_liftS0 m b ltac:(lia) hb2 hE2) as hp2_hub.
    pose proof (PureP2_cons hp2_hub (PureP2_nil _)) as hp2.
    exists (E1 - (m + b + 2)), [E2 - m; E3 - (m + 1)].
    split; [exact (OneBlock_appendP2 (OneBlock_appendP2 hb1_ob hp2) hp3) |].
    cbn [sumList]. split; [lia | left; split; [exact hA | reflexivity]].
  - set (s0 := E1 - (m + 1)).
    set (s1 := m + b + 1 - E1).
    assert (hb1_ob : OneBlock W0 W1 E1 []).
    { exists W1. split; [exact hb1 | exact (PureP2_nil _)]. }
    assert (hpark1 : forall r : Stream Sym,
      (b0 {{E}}> (T2 *> T0 *> T1 *> (W0 ++ encS (2 * m + 1) false (b + 2) [] None) *> r)) -[ tm ]->*
      (b0 {{E}}> (T2 *> T0 *> T1 *> (W1 ++ encS (2 * m + 1) true s0 (sp1 s1) None) *> r))).
    { intros r.
      pose proof (OneBlock_liftS2_park m b hb1_ob ltac:(cbn [sumList]; lia) ltac:(cbn [sumList]; lia) r) as hp.
      cbn [sumList] in hp; replace (E1 + 0) with E1 in hp by lia.
      exact hp. }
    destruct (Nat.leb_spec0 (2 * m + b + 2) (E1 + E2)) as [hB | hnB].
    + set (s0' := s0 - 1).
      pose proof (DirectBlock_liftS0 m s0' ltac:(unfold s0', s0; lia) hb2 hE2) as h2_hub.
      pose proof (HubP2B_lift2Seg_heal_direct 0 s1 h2_hub ltac:(unfold s1; lia)) as h2_heal.
      assert (hL2 : (((W1 ++ encS (2 * m + 1) true (s0' + 1) [] None) ++ (T4 ^^ 0)) ++ T3) ++ (T4 ^^ s1) =
                    W1 ++ encS (2 * m + 1) true s0 (sp1 s1) None).
      { unfold encS; rewrite encSegTail_sp1; cbn [encSegTail].
        replace (s0' + 1) with s0 by (unfold s0', s0; lia).
        rewrite zPz, ?app_nil_r, ?append_assoc. reflexivity. }
      assert (hR2 : (W2 ++ encS (2 * m + 2) true s0' [] None) ++ (T4 ^^ (0 + s1 + 1)) =
                    W2 ++ encS (2 * m + 2) true b [] None).
      { unfold encS; cbn [encSegTail].
        rewrite ?app_nil_r, ?append_assoc; fold_pow_add.
        replace (s0' + (0 + s1 + 1)) with b by (unfold s0', s0, s1; lia). reflexivity. }
      rewrite hL2, hR2 in h2_heal.
      replace (E2 - m - (s1 + 1)) with (E1 + E2 - (2 * m + b + 2)) in h2_heal by (unfold s1; lia).
      assert (h2_ob : OneBlock (W1 ++ encS (2 * m + 1) true s0 (sp1 s1) None)
                               (W2 ++ encS (2 * m + 2) true b [] None) (E1 + E2 - (2 * m + b + 2)) []).
      { exists (W2 ++ encS (2 * m + 2) true b [] None).
        split; [exact h2_heal | exact (PureP2_nil _)]. }
      exists (E1 + E2 - (2 * m + b + 2)), [E3 - (m + 1)].
      split; [exact (OneBlock_appendP2 (OneBlock_prependStep hpark1 h2_ob) hp3) |].
      cbn [sumList]. split; [lia | right; left; split; [lia | split; [exact hB | reflexivity]]].
    + set (s0' := s0 - 1 + (E2 - m)).
      set (s1' := s1 - (E2 - m)).
      assert (hb2_ob : OneBlock W1 W2 E2 []).
      { exists W2. split; [exact hb2 | exact (PureP2_nil _)]. }
      assert (hdump2 : forall r : Stream Sym,
        (b0 {{E}}> (T2 *> T0 *> T1 *> (W1 ++ encS (2 * m + 1) true s0 (sp1 s1) None) *> r)) -[ tm ]->*
        (b0 {{E}}> (T2 *> T0 *> T1 *> (W2 ++ encS (2 * m + 2) true s0' (sp1 s1') None) *> r))).
      { intros r.
        pose proof (OneBlock_liftS0_2seg_dump m s0 s1 ltac:(unfold s0; lia) hb2_ob
                      ltac:(cbn [sumList]; lia) ltac:(cbn [sumList]; unfold s1; lia) r) as hd.
        cbn [sumList] in hd; replace (E2 + 0) with E2 in hd by lia.
        exact hd. }
      set (s0'' := s0' - 1).
      pose proof (DirectBlock_liftS1 (m + 1) s0'' ltac:(lia) ltac:(unfold s0'', s0', s0; lia) hb3 ltac:(lia)) as h3_hub.
      pose proof (HubP2B_lift2Seg_heal_direct 0 s1' h3_hub ltac:(unfold s1', s1; lia)) as h3_heal.
      assert (hL3 : (((W2 ++ encS (2 * (m + 1)) true (s0'' + 1) [] None) ++ (T4 ^^ 0)) ++ T3) ++ (T4 ^^ s1') =
                    W2 ++ encS (2 * m + 2) true s0' (sp1 s1') None).
      { unfold encS; rewrite encSegTail_sp1; cbn [encSegTail].
        replace (2 * (m + 1)) with (2 * m + 2) by lia.
        replace (s0'' + 1) with s0' by (unfold s0'', s0', s0; lia).
        rewrite zPz, ?app_nil_r, ?append_assoc. reflexivity. }
      assert (hR3 : (W3 ++ encS (2 * (m + 1) + 1) false (s0'' + 1) [] None) ++ (T4 ^^ (0 + s1' + 1)) =
                    W3 ++ encS (2 * m + 3) false b [] None).
      { unfold encS; cbn [encSegTail].
        replace (2 * (m + 1) + 1) with (2 * m + 3) by lia.
        rewrite ?app_nil_r, ?append_assoc; fold_pow_add.
        replace (s0'' + 1 + (0 + s1' + 1)) with b by (unfold s0'', s0', s0, s1', s1; lia). reflexivity. }
      rewrite hL3, hR3 in h3_heal.
      replace (E3 - (m + 1) - (s1' + 1)) with (E1 + E2 + E3 - (3 * m + b + 3)) in h3_heal
        by (unfold s1', s1; lia).
      assert (h3_ob : OneBlock (W2 ++ encS (2 * m + 2) true s0' (sp1 s1') None)
                               (W3 ++ encS (2 * m + 3) false b [] None) (E1 + E2 + E3 - (3 * m + b + 3)) []).
      { exists (W3 ++ encS (2 * m + 3) false b [] None).
        split; [exact h3_heal | exact (PureP2_nil _)]. }
      exists (E1 + E2 + E3 - (3 * m + b + 3)), (@nil nat).
      split; [exact (OneBlock_prependStep (fun r => stepStar_trans (hpark1 r) (hdump2 r)) h3_ob) |].
      cbn [sumList]. split; [lia | right; right; split; [lia | reflexivity]].
Qed.

(* ========================================================================= *)
(* Section 13.2: Weak OneBlockW, Fast Front Lifters & Symbolic Front Engine  *)
(* ========================================================================= *)

Definition OneBlockW (W W' : list Sym) (e0 : nat) (es : list nat) : Prop :=
  exists W1, HubP1 e0 W W1 /\ PureP2W W1 W' es.

Lemma OneBlock_toWeak {W W' : list Sym} {e0 : nat} {es : list nat}
    (h : OneBlock W W' e0 es) : OneBlockW W W' e0 es.
Proof.
  destruct h as [W1 [h1 hp]].
  exists W1. split; [exact h1 | exact (PureP2_toWeak hp)].
Qed.

Lemma OneBlockW_liftTransp_fast {W W' : list Sym} {e0 : nat} {es : list nat}
    (m b : nat) (hm : 1 <= m) (hb : OneBlockW W W' e0 es) (hge : m + b + 3 <= e0) :
    OneBlockW (W ++ encS (2 * m) false (b + 2) [] None)
      (W' ++ encS (2 * m) false (b + 2) [] None) (e0 - (m + b + 2)) es.
Proof.
  destruct hb as [W1 [h1 hp]].
  exists (W1 ++ encS (2 * m) false (b + 2) [] None).
  split; [| exact (PureP2W_liftCell (2 * m) false (b + 2) ltac:(right; split; lia) hp)].
  intros W_next r.
  destruct (h1 (encS (2 * m) false (b + 2) [] None ++ W_next) r) as [cfg0 [hpe0 hs0]].
  assert (hpe0' : P1Entry e0 W1 (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ++ W_next) r cfg0).
  { unfold encS in hpe0; cbn [encSegTail] in hpe0.
    (rewrite ?app_nil_r in hpe0; rewrite ?append_assoc in hpe0; rewrite ?app_nil_r; rewrite ?append_assoc). exact hpe0. }
  destruct (p1Entry_transp_pass (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) m b hm ltac:(lia) hpe0') as [Lt' [hpL' hs1]].
  assert (hpL'' : PipeL1 (e0 - (m + b + 2)) (W1 ++ encS (2 * m) false (b + 2) [] None) Lt').
  { eapply pipeL1_eqR; [| exact hpL'].
    unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity. }
  exists (([S1; S1] *> Lt') {{F}}> (W_next *> r)).
  split; [left; exists Lt'; split; [exact hpL'' | reflexivity] |].
  rewrite ?append_assoc. exact (stepStar_trans hs0 hs1).
Qed.

Lemma OneBlockW_liftS2_fast {W W' : list Sym} {e0 : nat} {es : list nat}
    (m b : nat) (hb : OneBlockW W W' e0 es) (hge : m + b + 2 <= e0) :
    OneBlockW (W ++ encS (2 * m + 1) false (b + 1) [] None)
      (W' ++ encS (2 * m + 1) true b [] None) (e0 - (m + b + 1)) es.
Proof.
  destruct hb as [W1 [h1 hp]].
  exists (W1 ++ encS (2 * m + 1) true b [] None).
  split; [| exact (PureP2W_liftCell (2 * m + 1) true b (or_introl eq_refl) hp)].
  intros W_next r.
  destruct (h1 (encS (2 * m + 1) false (b + 1) [] None ++ W_next) r) as [cfg0 [hpe0 hs0]].
  assert (hpe0' : P1Entry e0 W1 (((T2 ^^ (2 * m + 1)) ++ (T4 ^^ (b + 1))) ++ W_next) r cfg0).
  { unfold encS in hpe0; cbn [encSegTail] in hpe0.
    (rewrite ?app_nil_r in hpe0; rewrite ?append_assoc in hpe0; rewrite ?app_nil_r; rewrite ?append_assoc). exact hpe0. }
  destruct (p1Entry_eat_t2_odd_t4 (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) m b ltac:(lia) hpe0') as [Lt1 [hpL1 hs1]].
  destruct (pipeL_eat_t4 (En := ltac:(match type of hpL1 with PipeL ?x _ _ => exact x end)) b ltac:(lia) hpL1 (W_next *> r)) as [Lt2 [hpL2 hs2]].
  assert (hpL2' : PipeL1 (e0 - (m + b + 1)) (W1 ++ encS (2 * m + 1) true b [] None) Lt2).
  { split; [| intros h0; lia].
    replace (e0 - m - 1 - b) with (e0 - (m + b + 1)) in hpL2 by lia.
    eapply pipeL_eqR; [| exact hpL2].
    unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity. }
  exists (([S1; S1] *> Lt2) {{F}}> (W_next *> r)).
  split; [left; exists Lt2; split; [exact hpL2' | reflexivity] |].
  rewrite ?append_assoc. exact (stepStar_trans hs0 (stepStar_trans hs1 hs2)).
Qed.

Lemma OneBlockW_liftS0_fast {W W' : list Sym} {e0 : nat} {es : list nat}
    (m b : nat) (hb : OneBlockW W W' e0 es) (hge : m + 1 <= e0) :
    PureP2W (W ++ encS (2 * m + 1) true (b + 1) [] None)
      (W' ++ encS (2 * m + 2) true b [] None) ((e0 - m) :: es).
Proof.
  destruct hb as [W1 [h1 hp]].
  eapply PureP2W_cons; [| exact (PureP2W_liftCell (2 * m + 2) true b (or_introl eq_refl) hp)].
  split; [lia | intros r].
  destruct (h1 (encS (2 * m + 1) true (b + 1) [] None) r) as [cfg0 [hpe0 hs0]].
  assert (hpe0' : P1Entry e0 W1 ((((T2 ^^ (2 * m + 1)) ++ T5) ++ (T4 ^^ (b + 1))) ++ []) r cfg0).
  { unfold encS in hpe0; cbn [encSegTail] in hpe0.
    (rewrite ?app_nil_r in hpe0; rewrite ?append_assoc in hpe0; rewrite ?app_nil_r; rewrite ?append_assoc). exact hpe0. }
  destruct (p1Entry_h1_enter_odd m b hge hpe0') as [Lt' [hpL' hs1]].
  exists Lt'. split.
  - eapply pipeL_eqR; [| exact hpL'].
    unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
  - rewrite zLan in hs1. exact (stepStar_trans hs0 hs1).
Qed.

Lemma OneBlockW_liftS1_fast {W W' : list Sym} {e0 : nat} {es : list nat}
    (m b : nat) (hm : 1 <= m) (hb : OneBlockW W W' e0 es) (hge : m + 1 <= e0) :
    PureP2W (W ++ encS (2 * m) true (b + 1) [] None)
      (W' ++ encS (2 * m + 1) false (b + 1) [] None) ((e0 - m) :: es).
Proof.
  destruct hb as [W1 [h1 hp]].
  eapply PureP2W_cons; [| exact (PureP2W_liftCell (2 * m + 1) false (b + 1) ltac:(right; split; lia) hp)].
  split; [lia | intros r].
  destruct (h1 (encS (2 * m) true (b + 1) [] None) r) as [cfg0 [hpe0 hs0]].
  assert (hpe0' : P1Entry e0 W1 ((((T2 ^^ (2 * m)) ++ T5) ++ (T4 ^^ (b + 1))) ++ []) r cfg0).
  { unfold encS in hpe0; cbn [encSegTail] in hpe0.
    (rewrite ?app_nil_r in hpe0; rewrite ?append_assoc in hpe0; rewrite ?app_nil_r; rewrite ?append_assoc). exact hpe0. }
  destruct (p1Entry_h1_enter_even m b hm hge hpe0') as [Lt' [hpL' hs1]].
  exists Lt'. split.
  - eapply pipeL_eqR; [| exact hpL'].
    unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
  - rewrite zLan in hs1. exact (stepStar_trans hs0 hs1).
Qed.

Lemma OneBlockW_liftB0Even_fast {W W' : list Sym} {e0 : nat} {es : list nat}
    (m a2 : nat) (h2 : bool) (b2 : nat) (hb2 : h2 = true \/ 1 <= b2)
    (hb : OneBlockW W W' e0 es) (hge : m + 1 <= e0) :
    PureP2W ((W ++ encS (2 * m) true 0 [] None) ++ encS a2 h2 b2 [] None)
      (W' ++ encS (2 * m + a2 + 1) h2 b2 [] None) ((e0 - m) :: es).
Proof.
  destruct hb as [W1 [h1 hp]].
  assert (hok_out : h2 = true \/ (1 <= 2 * m + a2 + 1 /\ 1 <= b2)).
  { destruct hb2 as [hh | hh]; [left; exact hh | right; lia]. }
  eapply PureP2W_cons; [| exact (PureP2W_liftCell (2 * m + a2 + 1) h2 b2 hok_out hp)].
  split; [lia | intros r].
  destruct (h1 (encS (2 * m) true 0 [] None ++ encS a2 h2 b2 [] None) r) as [cfg0 [hpe0 hs0]].
  rewrite append_assoc.
  destruct m as [|m'].
  - assert (h0_enc : encS (2 * 0) true 0 [] None = T5) by reflexivity.
    (try rewrite h0_enc in hpe0; try rewrite h0_enc in hs0; try rewrite h0_enc).
    replace (e0 - 0 - 1) with (e0 - 1) by lia.
    replace (2 * 0 + a2 + 1) with (a2 + 1) by lia.
    destruct hpe0 as [[Lt [hp1 hcfg]] | [Lt [W2 [_ [hW [_ _]]]]]].
    + subst cfg0.
      assert (heq0 : e0 = (e0 - 1) + 1) by lia.
      pose proof (pipeL_eqE heq0 (proj1 hp1)) as hpL.
      destruct (PipeL_head0 hpL) as [l0 hl0].
      destruct (PipeL_pull hpL) as [Lt2 [hpull hp2]].
      pose proof (pull1_t3_t5 0 hl0 hpull (encS a2 h2 b2 [] None *> r)) as hs1.
      rewrite zPz, zLan in hs1.
      destruct (pipeL_q0_b0_finish 0 a2 h2 b2 hb2 hp2 r) as [Lt' [hpL' hs2]].
      simpl plus in hpL', hs2.
      exists Lt'. split; [exact hpL' |].
      (try rewrite Str_app_assoc in hs0; try rewrite Str_app_assoc).
      exact (stepStar_trans hs0 (stepStar_trans hs1 hs2)).
    + cbn [T5 T2 app] in hW; discriminate hW.
  - assert (hpe0' : P1Entry e0 W1 ((T2 ^^ (2 * S m')) ++ (T5 ++ encS a2 h2 b2 [] None)) r cfg0).
    { unfold encS in hpe0 at 1; cbn [encSegTail] in hpe0.
      rewrite zPz, ?app_nil_r, ?append_assoc in hpe0. exact hpe0. }
    destruct (p1Entry_eat_t2_even (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) (S m') ltac:(lia) ltac:(lia) hpe0') as [Lt1 [hp1 hs1]].
    assert (heq1 : e0 - S m' = (e0 - S m' - 1) + 1) by lia.
    pose proof (pipeL_eqE heq1 hp1) as hp1'.
    destruct (PipeL_head0 hp1') as [l1 hl1].
    destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
    pose proof (pull1_t3_t5 (2 * S m') hl1 hpull (encS a2 h2 b2 [] None *> r)) as hs2.
    destruct (pipeL_q0_b0_finish (2 * S m') a2 h2 b2 hb2 hp2 r) as [Lt' [hpL' hs3]].
    exists Lt'. split; [exact hpL' |].
    eapply evstep_trans; [exact hs0 |].
    eapply evstep_trans; [exact hs1 |].
    rewrite Str_app_assoc. exact (stepStar_trans hs2 hs3).
Qed.

Lemma OneBlockW_liftB0OddH1_fast {W W' : list Sym} {e0 : nat} {es : list nat}
    (m a2 b2 : nat) (hb : OneBlockW W W' e0 es) (hge : m + 2 <= e0) :
    PureP2W ((W ++ encS (2 * m + 1) true 0 [] None) ++ encS a2 true b2 [] None)
      (W' ++ encS (2 * m + 1 + a2 + 1) false (b2 + 1) [] None) ((e0 - (m + 1)) :: es).
Proof.
  destruct hb as [W1 [h1 hp]].
  eapply PureP2W_cons; [| exact (PureP2W_liftCell (2 * m + 1 + a2 + 1) false (b2 + 1) ltac:(right; split; lia) hp)].
  split; [lia | intros r].
  destruct (h1 (encS (2 * m + 1) true 0 [] None ++ encS a2 true b2 [] None) r) as [cfg0 [hpe0 hs0]].
  rewrite append_assoc.
  assert (hstep1 : exists Lt2, PipeL (e0 - m - 1) W1 Lt2 /\
      cfg0 -[ tm ]->* (([S1] *> (T3 ^^ (2 * m + 3)) *> Lt2) {{A}}> (encS a2 true b2 [] None *> r))).
  { destruct m as [|m'].
    - assert (h1_enc : encS (2 * 0 + 1) true 0 [] None = T2 ++ T5) by reflexivity.
      rewrite h1_enc in hpe0.
      replace (e0 - 0 - 1) with (e0 - 1) by lia.
      replace (2 * 0 + 3) with 3 by lia.
      destruct hpe0 as [[Lt [hp1 hcfg]] | [Lt [W2 [_ [hW [hpL hcfg]]]]]]; subst cfg0.
      + assert (heq0 : e0 = (e0 - 1) + 1) by lia.
        pose proof (pipeL_eqE heq0 (proj1 hp1)) as hpL.
        destruct (PipeL_head0 hpL) as [l0 hl0].
        destruct (PipeL_pull hpL) as [Lt2 [hpull hp2]].
        exists Lt2. split; [exact hp2 |].
        pose proof (pull1_t3_t2_t5 0 hl0 hpull (encS a2 true b2 [] None *> r)) as hs.
        rewrite zPz, zLan in hs; simpl plus in hs.
        rewrite ?append_assoc, ?Str_app_assoc. exact hs.
      + assert (hW2 : W2 = T5 ++ encS a2 true b2 [] None).
        { apply (@app_cancel_left _ T2). rewrite <- append_assoc. symmetry; exact hW. }
        subst W2. exists Lt. split; [exact hpL |].
        rewrite Str_app_assoc. exact (step_t2L_eat_t5 Lt (encS a2 true b2 [] None *> r)).
    - assert (hpe0' : P1Entry e0 W1 ((T2 ^^ (2 * S m')) ++ (T2 ++ T5 ++ encS a2 true b2 [] None)) r cfg0).
      { unfold encS in hpe0 at 1; cbn [encSegTail] in hpe0.
        rewrite (list_pow_succ_right T2 (2 * S m')), zPz, ?app_nil_r, ?append_assoc in hpe0. exact hpe0. }
      destruct (p1Entry_eat_t2_even (e := ltac:(match type of hpe0' with P1Entry ?x _ _ _ _ => exact x end)) (S m') ltac:(lia) ltac:(lia) hpe0') as [Lt1 [hp1 hs1]].
      assert (heq1 : e0 - S m' = (e0 - S m' - 1) + 1) by lia.
      pose proof (pipeL_eqE heq1 hp1) as hp1'.
      destruct (PipeL_head0 hp1') as [l1 hl1].
      destruct (PipeL_pull hp1') as [Lt2 [hpull hp2]].
      exists Lt2. split; [exact hp2 |].
      eapply evstep_trans; [exact hs1 |].
      rewrite ?Str_app_assoc.
      exact (pull1_t3_t2_t5 (2 * S m') hl1 hpull (encS a2 true b2 [] None *> r)). }
  destruct hstep1 as [Lt2 [hp2 hs1]].
  assert (heq2 : e0 - m - 1 = (e0 - (m + 1) - 1) + 1) by lia.
  pose proof (pipeL_eqE heq2 hp2) as hp2'.
  destruct (PipeL_head0 hp2') as [l2 hl2].
  destruct (PipeL_pull hp2') as [Lt3 [hpull2 hp3]].
  exists ((T5 ^^ b2) *> T4 *> (T3 ^^ (2 * m + 1 + a2)) *> T2 *> Lt3). split.
  - eapply pipeL_eqR; [| exact (pipeL_T2_blk b2 (2 * m + 1 + a2) hp3)].
    unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
  - eapply evstep_trans; [exact hs0 |].
    eapply evstep_trans; [exact hs1 |].
    assert (hEnc2 : encS a2 true b2 [] None *> r = (T2 ^^ a2) *> T5 *> (T4 ^^ b2) *> r).
    { unfold encS; cbn [encSegTail]. rewrite ?app_nil_r, ?append_assoc, ?Str_app_assoc. reflexivity. }
    rewrite hEnc2.
    eapply evstep_trans; [exact (rule_q0_t2 a2 ((T3 ^^ (2 * m + 3)) *> Lt2) (T5 *> (T4 ^^ b2) *> r)) |].
    rewrite <- pow_add_blank.
    replace (a2 + (2 * m + 3)) with (S (2 * m + 2 + a2)) by lia.
    rewrite zPsr.
    destruct (head0_t3_t0 (2 * m + 2 + a2) l2) as [l2' hl2'].
    assert (hs_t5 : (([S1] *> T3 *> (T3 ^^ (2 * m + 2 + a2)) *> Lt2) {{A}}> (T5 *> (T4 ^^ b2) *> r)) -[ tm ]->*
                    (((T3 ^^ (2 * m + 2 + a2)) *> Lt2) {{E}}> (T0 *> T2 *> T4 *> (T4 ^^ b2) *> r))).
    { rewrite hl2, hl2'. exact (step_q0_t5_on_t3 l2' ((T4 ^^ b2) *> r)). }
    eapply evstep_trans; [exact hs_t5 |].
    assert (hs_e : (((T3 ^^ (2 * m + 2 + a2)) *> Lt2) {{E}}> (T0 *> T2 *> T4 *> (T4 ^^ b2) *> r)) -[ tm ]->*
                   (([S1; S1] *> Lt2) {{F}}> ([S0; S1] *> (T2 ^^ (2 * m + 2 + a2)) *> T4 *> (T4 ^^ b2) *> r))).
    { rewrite hl2. replace (2 * m + 2 + a2) with ((2 * m + 1 + a2) + 1) by lia.
      eapply evstep_trans; [exact (rule_E_t3_to_Q5 (2 * m + 1 + a2) l2 (T2 *> T4 *> (T4 ^^ b2) *> r)) |].
      rewrite zPal. replace (S (2 * m + 1 + a2)) with (2 * m + 1 + a2 + 1) by lia. apply evstep_refl. }
    eapply evstep_trans; [exact hs_e |].
    change ([S0; S1] *> (T2 ^^ (2 * m + 2 + a2)) *> T4 *> (T4 ^^ b2) *> r)
      with (T0 *> [S1] *> (T2 ^^ (2 * m + 2 + a2)) *> T4 *> (T4 ^^ b2) *> r).
    eapply evstep_trans; [exact (hpull2 ([S1] *> (T2 ^^ (2 * m + 2 + a2)) *> T4 *> (T4 ^^ b2) *> r)) |].
    change (T1 *> [S1] *> (T2 ^^ (2 * m + 2 + a2)) *> T4 *> (T4 ^^ b2) *> r)
      with ([S1; S1] *> (T2 ^^ (2 * m + 2 + a2)) *> T4 *> (T4 ^^ b2) *> r).
    eapply evstep_trans; [exact (post_pull_q0 Lt3 ((T2 ^^ (2 * m + 2 + a2)) *> T4 *> (T4 ^^ b2) *> r)) |].
    eapply evstep_trans; [exact (rule_q0_t2 (2 * m + 2 + a2) (T2 *> Lt3) (T4 *> (T4 ^^ b2) *> r)) |].
    replace (2 * m + 2 + a2) with (S (2 * m + 1 + a2)) by lia.
    rewrite zPsr.
    eapply evstep_trans; [exact (step_q0_t4_first ((T3 ^^ (2 * m + 1 + a2)) *> T2 *> Lt3) ((T4 ^^ b2) *> r)) |].
    exact (rule_q0_t4_next b2 (T4 *> (T3 ^^ (2 * m + 1 + a2)) *> T2 *> Lt3) r).
Qed.

(* ========================================================================= *)
(* Computable Symbolic Front Engine                                          *)
(* ========================================================================= *)

(* --- ScratchS4B2b1.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

Definition FrontCell : Type := nat * bool * nat.

Fixpoint encFront (cs : list FrontCell) : list Sym :=
  match cs with
  | [] => []
  | (a, hc, b) :: rest => encS a hc b [] None ++ encFront rest
  end.

Fixpoint frontValid (cs : list FrontCell) : bool :=
  match cs with
  | [] => true
  | (a, hc, b) :: rest => (hc || (Nat.leb 1 a && Nat.leb 1 b))%bool && frontValid rest
  end.

Lemma PureP2W_liftFront : forall (cs : list FrontCell) {W W' : list Sym} {es : list nat},
    frontValid cs = true -> PureP2W W W' es ->
    PureP2W (W ++ encFront cs) (W' ++ encFront cs) es.
Proof.
  induction cs as [|[[a hc] b] rest IH]; intros W W' es hv hp.
  - cbn [encFront]; rewrite ?app_nil_r. exact hp.
  - cbn [frontValid] in hv.
    apply Bool.andb_true_iff in hv; destruct hv as [h1 hv'].
    assert (hok : hc = true \/ (1 <= a /\ 1 <= b)).
    { destruct hc; [left; reflexivity | right; cbn [orb] in h1; apply Bool.andb_true_iff in h1;
      destruct h1 as [ha hb]; apply Nat.leb_le in ha; apply Nat.leb_le in hb; lia]. }
    pose proof (PureP2W_liftCell a hc b hok hp) as hp1.
    pose proof (IH _ _ _ hv' hp1) as hp2.
    cbn [encFront]; rewrite ?append_assoc.
    rewrite ?append_assoc in hp2. exact hp2.
Qed.

Fixpoint symCarry (cs : list FrontCell) : option (list FrontCell * nat * nat) :=
  match cs with
  | [] => None
  | (a, false, b) :: rest =>
      if Nat.eqb (a mod 2) 0 then
        if (Nat.leb 2 a && Nat.leb 2 b)%bool then
          match symCarry rest with
          | Some (rest', c_r, m_r) =>
              let c := a / 2 + b in
              Some ((a, false, b) :: rest', c + c_r, Nat.max (c + 1) (c + m_r))
          | None => None
          end
        else None
      else
        if Nat.leb 1 b then
          match symCarry rest with
          | Some (rest', c_r, m_r) =>
              let c := a / 2 + b in
              Some ((a, true, b - 1) :: rest', c + c_r, Nat.max (c + 1) (c + m_r))
          | None => None
          end
        else None
  | (a, true, b) :: rest =>
      if Nat.leb 1 b then
        if Nat.eqb (a mod 2) 1 then
          if frontValid rest then Some ((a + 1, true, b - 1) :: rest, a / 2, a / 2 + 1)
          else None
        else
          if (Nat.leb 2 a && frontValid rest)%bool then Some ((a + 1, false, b) :: rest, a / 2, a / 2 + 1)
          else None
      else
        match rest with
        | [] => None
        | (a2, h2, b2) :: rest2 =>
            if Nat.eqb (a mod 2) 0 then
              if ((h2 || Nat.leb 1 b2) && frontValid rest2)%bool then
                Some ((a + a2 + 1, h2, b2) :: rest2, a / 2, a / 2 + 1)
              else None
            else
              if (h2 && frontValid rest2)%bool then
                Some ((a + a2 + 1, false, b2 + 1) :: rest2, a / 2 + 1, a / 2 + 2)
              else None
        end
  end.

Lemma symCarry_sound (cs : list FrontCell) :
    forall {cs' : list FrontCell} {cost minE : nat}
    (h : symCarry cs = Some (cs', cost, minE))
    {W W' : list Sym} {e0 : nat} {es : list nat}
    (hb : OneBlockW W W' e0 es) (hge : minE <= e0),
    exists es', PureP2W (W ++ encFront cs) (W' ++ encFront cs') es' /\
      sumList es' = e0 + sumList es - cost /\ cost <= e0.
Proof.
  induction cs as [|[[a hc] b] rest IH]; intros cs' cost minE h W W' e0 es hb hge.
  - discriminate h.
  - destruct hc.
    + cbn [symCarry] in h.
      destruct (Nat.leb 1 b) eqn:hb1.
      * apply Nat.leb_le in hb1.
        destruct (Nat.eqb (a mod 2) 1) eqn:haodd.
        -- apply Nat.eqb_eq in haodd.
           destruct (frontValid rest) eqn:hv; [| discriminate].
           inv_some h; subst cs' cost minE.
           assert (ha_eq : a = 2 * (a / 2) + 1) by (pose proof (Nat.div_mod a 2 ltac:(lia)); lia).
           assert (hb_eq : b = (b - 1) + 1) by lia.
           pose proof (OneBlockW_liftS0_fast (a / 2) (b - 1) hb hge) as hp1.
           pose proof (PureP2W_liftFront rest hv hp1) as hp2.
           exists ((e0 - a / 2) :: es).
           split; [| cbn [sumList]; lia].
           cbn [encFront]; rewrite <- ha_eq, <- hb_eq in hp2.
           replace (2 * (a / 2) + 2) with (a + 1) in hp2 by lia.
           (rewrite ?append_assoc in hp2; rewrite ?append_assoc). exact hp2.
        -- apply Nat.eqb_neq in haodd.
           assert (haev : a mod 2 = 0) by (pose proof (Nat.mod_upper_bound a 2 ltac:(lia)); lia).
           destruct ((Nat.leb 2 a && frontValid rest)%bool) eqn:hav; [| discriminate].
           apply Bool.andb_true_iff in hav; destruct hav as [ha2 hv].
           apply Nat.leb_le in ha2.
           inv_some h; subst cs' cost minE.
           assert (ha_eq : a = 2 * (a / 2)) by (pose proof (Nat.div_mod a 2 ltac:(lia)); lia).
           assert (hb_eq : b = (b - 1) + 1) by lia.
           pose proof (OneBlockW_liftS1_fast (a / 2) (b - 1) ltac:(lia) hb hge) as hp1.
           pose proof (PureP2W_liftFront rest hv hp1) as hp2.
           exists ((e0 - a / 2) :: es).
           split; [| cbn [sumList]; lia].
           cbn [encFront]; rewrite <- ha_eq, <- hb_eq in hp2.
           (rewrite ?append_assoc in hp2; rewrite ?append_assoc). exact hp2.
      * apply Nat.leb_gt in hb1; assert (b = 0) by lia; subst b.
        destruct rest as [|[[a2 h2] b2] rest2]; [discriminate |].
        destruct (Nat.eqb (a mod 2) 0) eqn:haev.
        -- apply Nat.eqb_eq in haev.
           destruct (((h2 || Nat.leb 1 b2) && frontValid rest2)%bool) eqn:hcond; [| discriminate].
           apply Bool.andb_true_iff in hcond; destruct hcond as [hh2 hv2].
           assert (hb2_ok : h2 = true \/ 1 <= b2).
           { destruct h2; [left; reflexivity | right; cbn [orb] in hh2; apply Nat.leb_le in hh2; exact hh2]. }
           inv_some h; subst cs' cost minE.
           assert (ha_eq : a = 2 * (a / 2)) by (pose proof (Nat.div_mod a 2 ltac:(lia)); lia).
           pose proof (OneBlockW_liftB0Even_fast (a / 2) a2 h2 b2 hb2_ok hb hge) as hp1.
           pose proof (PureP2W_liftFront rest2 hv2 hp1) as hp2.
           exists ((e0 - a / 2) :: es).
           split; [| cbn [sumList]; lia].
           cbn [encFront]; rewrite <- ha_eq in hp2.
           (rewrite ?append_assoc in hp2; rewrite ?append_assoc). exact hp2.
        -- apply Nat.eqb_neq in haev.
           assert (haodd : a mod 2 = 1) by (pose proof (Nat.mod_upper_bound a 2 ltac:(lia)); lia).
           destruct ((h2 && frontValid rest2)%bool) eqn:hcond; [| discriminate].
           apply Bool.andb_true_iff in hcond; destruct hcond as [hh2 hv2]; subst h2.
           inv_some h; subst cs' cost minE.
           assert (ha_eq : a = 2 * (a / 2) + 1) by (pose proof (Nat.div_mod a 2 ltac:(lia)); lia).
           pose proof (OneBlockW_liftB0OddH1_fast (a / 2) a2 b2 hb ltac:(lia)) as hp1.
           pose proof (PureP2W_liftFront rest2 hv2 hp1) as hp2.
           exists ((e0 - (a / 2 + 1)) :: es).
           split; [| cbn [sumList]; lia].
           cbn [encFront]; rewrite <- ha_eq in hp2.
           (rewrite ?append_assoc in hp2; rewrite ?append_assoc). exact hp2.
    + cbn [symCarry] in h.
      destruct (Nat.eqb (a mod 2) 0) eqn:haev.
      * apply Nat.eqb_eq in haev.
        destruct ((Nat.leb 2 a && Nat.leb 2 b)%bool) eqn:hab; [| discriminate].
        apply Bool.andb_true_iff in hab; destruct hab as [ha2 hb2].
        apply Nat.leb_le in ha2; apply Nat.leb_le in hb2.
        destruct (symCarry rest) as [[[rest' c_r] m_r]|] eqn:hrec; [| discriminate].
        inv_some h; subst cs' cost minE.
        assert (ha_eq : a = 2 * (a / 2)) by (pose proof (Nat.div_mod a 2 ltac:(lia)); lia).
        assert (hb_eq : b = (b - 2) + 2) by lia.
        pose proof (OneBlockW_liftTransp_fast (a / 2) (b - 2) ltac:(lia) hb ltac:(lia)) as hb1.
        rewrite <- ha_eq, <- hb_eq in hb1.
        replace (a / 2 + (b - 2) + 2) with (a / 2 + b) in hb1 by lia.
        destruct (IH _ _ _ eq_refl _ _ _ _ hb1 ltac:(lia)) as [es' [hp' [hsum' hle']]].
        exists es'. split; [| lia].
        cbn [encFront]; rewrite ?append_assoc; rewrite ?append_assoc in hp'. exact hp'.
      * apply Nat.eqb_neq in haev.
        assert (haodd : a mod 2 = 1) by (pose proof (Nat.mod_upper_bound a 2 ltac:(lia)); lia).
        destruct (Nat.leb 1 b) eqn:hb1_ge; [| discriminate].
        apply Nat.leb_le in hb1_ge.
        destruct (symCarry rest) as [[[rest' c_r] m_r]|] eqn:hrec; [| discriminate].
        inv_some h; subst cs' cost minE.
        assert (ha_eq : a = 2 * (a / 2) + 1) by (pose proof (Nat.div_mod a 2 ltac:(lia)); lia).
        assert (hb_eq : b = (b - 1) + 1) by lia.
        pose proof (OneBlockW_liftS2_fast (a / 2) (b - 1) hb ltac:(lia)) as hb1.
        rewrite <- ha_eq, <- hb_eq in hb1.
        replace (a / 2 + (b - 1) + 1) with (a / 2 + b) in hb1 by lia.
        destruct (IH _ _ _ eq_refl _ _ _ _ hb1 ltac:(lia)) as [es' [hp' [hsum' hle']]].
        exists es'. split; [| lia].
        cbn [encFront]; rewrite ?append_assoc; rewrite ?append_assoc in hp'. exact hp'.
Qed.

Fixpoint symRunFront (n : nat) (cs : list FrontCell) : option (list FrontCell * nat * nat) :=
  match n with
  | O => Some (cs, 0, 0)
  | S n' =>
      match symCarry cs with
      | None => None
      | Some (cs1, c1, m1) =>
          match symRunFront n' cs1 with
          | None => None
          | Some (cs2, c2, m2) => Some (cs2, c1 + c2, Nat.max m1 m2)
          end
      end
  end.

Inductive BlockListMin (minE : nat) : list Sym -> list Sym -> list nat -> Prop :=
  | BlockListMin_nil (W : list Sym) : BlockListMin minE W W []
  | BlockListMin_cons {W W1 W' : list Sym} {e0 : nat} {es bs : list nat}
      (hb : OneBlockW W W1 e0 es) (hmin : minE <= e0)
      (hrest : BlockListMin minE W1 W' bs) :
      BlockListMin minE W W' ((e0 + sumList es) :: bs).

Lemma BlockListMin_weaken {m1 m2 : nat} {W W' : list Sym} {bs : list nat}
    (hle : m1 <= m2) (h : BlockListMin m2 W W' bs) : BlockListMin m1 W W' bs.
Proof.
  induction h as [W0 | Wa Wb Wc e0 es bs' hb hmin _ IH].
  - exact (BlockListMin_nil _ W0).
  - exact (BlockListMin_cons m1 hb ltac:(lia) IH).
Qed.

Lemma BlockListMin_append {minE : nat} {W1 W2 W3 : list Sym} {bs1 bs2 : list nat}
    (h1 : BlockListMin minE W1 W2 bs1) (h2 : BlockListMin minE W2 W3 bs2) :
    BlockListMin minE W1 W3 (bs1 ++ bs2).
Proof.
  induction h1 as [W0 | Wa Wb Wc e0 es bs' hb hmin _ IH].
  - exact h2.
  - exact (BlockListMin_cons _ hb hmin (IH h2)).
Qed.

Lemma BlockListMin_liftTransp_fast {minE : nat} {W W' : list Sym} {bs : list nat}
    (m b : nat) (hm : 1 <= m) (h : BlockListMin (minE + (m + b + 2)) W W' bs)
    (hmin1 : 1 <= minE) :
    BlockListMin minE (W ++ encS (2 * m) false (b + 2) [] None)
      (W' ++ encS (2 * m) false (b + 2) [] None) (List.map (fun x => x - (m + b + 2)) bs).
Proof.
  induction h as [W0 | Wa Wb Wc e0 es bs' hb hmin _ IH].
  - exact (BlockListMin_nil _ _).
  - pose proof (OneBlockW_liftTransp_fast m b hm hb ltac:(lia)) as hb'.
    cbn [List.map].
    replace (e0 + sumList es - (m + b + 2)) with ((e0 - (m + b + 2)) + sumList es) by lia.
    exact (BlockListMin_cons minE hb' ltac:(lia) IH).
Qed.

Lemma BlockListMin_liftTranspRun_fast (rep : nat) :
    forall {minE : nat} {W W' : list Sym} {bs : list nat}
    (m b : nat) (hm : 1 <= m) (h : BlockListMin (minE + rep * (m + b + 2)) W W' bs)
    (hmin1 : 1 <= minE),
    BlockListMin minE (W ++ (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ^^ rep))
      (W' ++ (((T2 ^^ (2 * m)) ++ (T4 ^^ (b + 2))) ^^ rep))
      (List.map (fun x => x - rep * (m + b + 2)) bs).
Proof.
  induction rep as [|k IH]; intros minE W W' bs m b hm h hmin1.
  - assert (hmap : List.map (fun x => x - 0 * (m + b + 2)) bs = bs).
    { clear; induction bs as [|x xs IHx]; [reflexivity | cbn [List.map]; rewrite IHx; f_equal; lia]. }
    rewrite hmap, zPz, ?app_nil_r.
    replace (minE + 0 * (m + b + 2)) with minE in h by lia. exact h.
  - assert (h1 : BlockListMin ((minE + k * (m + b + 2)) + (m + b + 2)) W W' bs).
    { replace ((minE + k * (m + b + 2)) + (m + b + 2)) with (minE + S k * (m + b + 2)) by lia. exact h. }
    pose proof (BlockListMin_liftTransp_fast m b hm h1 ltac:(lia)) as h2.
    pose proof (IH _ _ _ _ m b hm h2 hmin1) as h3.
    assert (hmap : List.map (fun x => x - k * (m + b + 2)) (List.map (fun x => x - (m + b + 2)) bs) =
                   List.map (fun x => x - S k * (m + b + 2)) bs).
    { clear; induction bs as [|x xs IHx]; [reflexivity | cbn [List.map]; rewrite IHx; f_equal; lia]. }
    rewrite hmap in h3.
    unfold encS in h3; cbn [encSegTail] in h3.
    assert (hpow : forall u : list Sym, u ^^ S k = u ++ (u ^^ k))
      by (clear; intros u; replace (S k) with (k + 1) by lia; apply list_pow_succ).
    rewrite !hpow, ?append_assoc.
    rewrite ?app_nil_r, ?append_assoc in h3. exact h3.
Qed.

Lemma BlockListMin_splitAt (n : nat) :
    forall {minE : nat} {W W' : list Sym} {bs : list nat}
    (h : BlockListMin minE W W' bs) (hn : n <= List.length bs),
    exists Wm bs1 bs2, BlockListMin minE W Wm bs1 /\ BlockListMin minE Wm W' bs2 /\
      bs = bs1 ++ bs2 /\ List.length bs1 = n.
Proof.
  induction n as [|n' IH]; intros minE W W' bs h hn.
  - exists W, (@nil nat), bs. split; [exact (BlockListMin_nil _ W) | split; [exact h | split; [reflexivity | reflexivity]]].
  - destruct h as [W0 | Wa Wb Wc e0 es bs' hb hmin hrest].
    + simpl in hn; lia.
    + simpl in hn.
      destruct (IH _ _ _ _ hrest ltac:(lia)) as [Wm [bs1 [bs2 [h1 [h2 [heq hlen]]]]]].
      exists Wm, ((e0 + sumList es) :: bs1), bs2.
      split; [exact (BlockListMin_cons _ hb hmin h1) | split; [exact h2 | split; [simpl; congruence | simpl; lia]]].
Qed.

Lemma symRunFront_sound (n : nat) :
    forall (cs : list FrontCell) {cs' : list FrontCell} {cost minE : nat}
    (h : symRunFront n cs = Some (cs', cost, minE))
    {W W' : list Sym} {bs : list nat}
    (hbl : BlockListMin minE W W' bs) (hlen : List.length bs = n),
    exists es_tot, PureP2W (W ++ encFront cs) (W' ++ encFront cs') es_tot /\
      sumList es_tot = sumList bs - cost /\ cost <= sumList bs.
Proof.
  induction n as [|n' IH]; intros cs cs' cost minE h W W' bs hbl hlen.
  - cbn [symRunFront] in h; inv_some h; subst cs' cost minE.
    destruct hbl as [W0 |]; [| simpl in hlen; discriminate].
    exists (@nil nat). cbn [sumList]. split; [exact (PureP2W_nil _) | lia].
  - cbn [symRunFront] in h.
    destruct (symCarry cs) as [[[cs1 c1] m1]|] eqn:hc1; [| discriminate].
    destruct (symRunFront n' cs1) as [[[cs2 c2] m2]|] eqn:hrec; [| discriminate].
    inv_some h; subst cs2 cost minE.
    destruct hbl as [W0 | Wa W1 Wc e0 es bs' hb hmin hrest]; [simpl in hlen; discriminate |].
    simpl in hlen; inversion hlen as [hlen'].
    destruct (symCarry_sound cs hc1 hb ltac:(lia)) as [es1 [hp1 [hsum1 hle1]]].
    destruct (IH cs1 cs' c2 m2 hrec W1 Wc bs' (BlockListMin_weaken (m1 := m2) (m2 := ltac:(match type of hrest with BlockListMin ?x _ _ _ => exact x end)) ltac:(lia) hrest) hlen')
      as [es2 [hp2 [hsum2 hle2]]].
    exists (es1 ++ es2).
    split; [exact (PureP2W_append hp1 hp2) |].
    rewrite sumList_append; cbn [sumList]; lia.
Qed.

Definition wave402_in : list FrontCell :=
  [(5, true, 35); (3, false, 39); (1, true, 39); (1, true, 40); (1, true, 39); (1, true, 40)].

Definition wave402_out : list FrontCell :=
  [(138, false, 28); (5, true, 35); (3, false, 39)].

Lemma wave402_sym_eval :
  symRunFront 134 wave402_in = Some (wave402_out, (5 * 1000 + 704), 150).
Proof. vm_compute. reflexivity. Qed.

Lemma wave402_front_134 {W W' : list Sym} {bs : list nat}
    (hbl : BlockListMin 150 W W' bs) (hlen : List.length bs = 134) :
    exists es_tot,
      PureP2W
        (((W ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
           ++ encPairRun_nat 1 true 39 1 true 40 2)
        (((W' ++ encS 138 false 28 [] None)
           ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
        es_tot /\
      sumList es_tot = sumList bs - (5 * 1000 + 704) /\ (5 * 1000 + 704) <= sumList bs.
Proof.
  destruct (symRunFront_sound 134 wave402_in wave402_sym_eval hbl hlen) as [es_tot [hp [hsum hle]]].
  exists es_tot. split; [| split; [exact hsum | exact hle]].
  assert (hIn : W ++ encFront wave402_in =
                ((W ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None) ++
                  encPairRun_nat 1 true 39 1 true 40 2).
  { assert (hp2 : forall u : list Sym, u ^^ 2 = u ++ u)
      by (intros u; change 2 with (1 + 1); rewrite (list_pow_add u 1 1), !list_pow_one; reflexivity).
    unfold wave402_in, encPairRun_nat; cbn [encFront].
    rewrite hp2, ?app_nil_r, ?append_assoc. reflexivity. }
  assert (hOut : W' ++ encFront wave402_out =
                 ((W' ++ encS 138 false 28 [] None) ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None).
  { unfold wave402_out; cbn [encFront]. rewrite ?app_nil_r, ?append_assoc. reflexivity. }
  rewrite <- hIn, <- hOut. exact hp.
Qed.

Lemma wave402_Kcycles_r0 (Kv : nat) :
    forall {W W' : list Sym} {bs : list nat} (k_tr : nat)
    (hbl : BlockListMin (150 + 97 * (k_tr + Kv)) W W' bs) (hlen : List.length bs = 134 * Kv),
    exists es_tot,
      PureP2W
        ((((W ++ encTranspRun_nat 138 28 k_tr)
           ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
           ++ encPairRun_nat 1 true 39 1 true 40 (2 * Kv))
        (((W' ++ encTranspRun_nat 138 28 (k_tr + Kv))
           ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
        es_tot /\
      sumList es_tot = sumList bs - ((5 * 1000 + 704) * Kv + 134 * 97 * k_tr * Kv + (6 * 1000 + 499) * Kv * (Kv - 1)) /\
      (5 * 1000 + 704) * Kv + 134 * 97 * k_tr * Kv + (6 * 1000 + 499) * Kv * (Kv - 1) <= sumList bs.
Proof.
  induction Kv as [|K' IH]; intros W W' bs k_tr hbl hlen.
  - destruct hbl as [W0 |]; [| simpl in hlen; lia].
    exists (@nil nat). unfold encPairRun_nat; replace (2 * 0) with 0 by lia; rewrite zPz, ?app_nil_r.
    replace (k_tr + 0) with k_tr by lia.
    cbn [sumList]. split; [exact (PureP2W_nil _) | lia].
  - destruct (BlockListMin_splitAt 134 hbl ltac:(lia)) as [Wm [bs1 [bs2 [hbl1 [hbl2 [hbs hlen1]]]]]].
    subst bs. rewrite List.length_app in hlen.
    assert (hlen2 : List.length bs2 = 134 * K') by lia.
    assert (hbl1_tr : BlockListMin 150 (W ++ (((T2 ^^ (2 * 69)) ++ (T4 ^^ (26 + 2))) ^^ k_tr))
        (Wm ++ (((T2 ^^ (2 * 69)) ++ (T4 ^^ (26 + 2))) ^^ k_tr))
        (List.map (fun x => x - k_tr * (69 + 26 + 2)) bs1)).
    { pose proof (BlockListMin_weaken (m1 := 150 + k_tr * (69 + 26 + 2)) (m2 := ltac:(match type of hbl1 with BlockListMin ?x _ _ _ => exact x end)) ltac:(lia) hbl1) as hwk.
      exact (BlockListMin_liftTranspRun_fast k_tr 69 26 ltac:(lia) hwk ltac:(lia)). }
    destruct (wave402_front_134 hbl1_tr ltac:(rewrite List.length_map; exact hlen1))
      as [es1 [hp1 [hsum1 hle1]]].
    pose proof (PureP2W_liftPairRun 1 39 1 40 (2 * K') hp1) as hp1'.
    assert (hbl2' : BlockListMin (150 + 97 * ((k_tr + 1) + K')) Wm W' bs2).
    { replace (150 + 97 * ((k_tr + 1) + K')) with (150 + 97 * (k_tr + S K')) by lia. exact hbl2. }
    destruct (IH _ _ _ (k_tr + 1) hbl2' hlen2) as [es2 [hp2 [hsum2 hle2]]].
    assert (hMid1 : ((((W ++ (((T2 ^^ (2 * 69)) ++ (T4 ^^ (26 + 2))) ^^ k_tr))
                        ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
                        ++ encPairRun_nat 1 true 39 1 true 40 2)
                        ++ encPairRun_nat 1 true 39 1 true 40 (2 * K') =
                    (((W ++ encTranspRun_nat 138 28 k_tr)
                        ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
                        ++ encPairRun_nat 1 true 39 1 true 40 (2 * S K')).
    { unfold encTranspRun_nat, encPairRun_nat.
      replace (2 * S K') with (2 + 2 * K') by lia.
      rewrite (list_pow_add _ 2 (2 * K')), ?append_assoc. reflexivity. }
    assert (hMid2 : ((((Wm ++ (((T2 ^^ (2 * 69)) ++ (T4 ^^ (26 + 2))) ^^ k_tr))
                        ++ encS 138 false 28 [] None)
                        ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
                        ++ encPairRun_nat 1 true 39 1 true 40 (2 * K') =
                    (((Wm ++ encTranspRun_nat 138 28 (k_tr + 1))
                        ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
                        ++ encPairRun_nat 1 true 39 1 true 40 (2 * K')).
    { unfold encTranspRun_nat, encS at 1; cbn [encSegTail].
      rewrite (list_pow_succ_right _ k_tr), ?app_nil_r, ?append_assoc. reflexivity. }
    rewrite hMid1, hMid2 in hp1'.
    pose proof (PureP2W_append hp1' hp2) as hp_all.
    replace (k_tr + 1 + K') with (k_tr + S K') in hp_all by lia.
    assert (hge1 : forall x, List.In x bs1 -> k_tr * (69 + 26 + 2) <= x).
    { clear - hbl1.
      induction hbl1 as [W0 | Wa Wb Wc e0 es bs' _ hmin _ IHb]; intros x hx; simpl in hx; [contradiction |].
      destruct hx as [hx | hx]; [subst x; lia | exact (IHb x hx)]. }
    pose proof (sum_map_sub bs1 (k_tr * (69 + 26 + 2)) hge1) as hsum_map.
    pose proof (list_len_mul_le_sum bs1 (k_tr * (69 + 26 + 2)) hge1) as hlen_le.
    try (rewrite hlen1 in hsum_map); try (rewrite hlen1 in hlen_le).
    exists (es1 ++ es2). split; [exact hp_all |].
    rewrite sumList_append, sumList_append, hsum1, hsum2, hsum_map.
    rewrite hsum_map in hle1.
    clear - hle1 hle2 hlen_le; destruct K' as [|K'']; nia.
Qed.

