(* --- ScratchS4B2b2a.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

Lemma c0_directBlock_2 (m0 b0_v : nat) (hb : 5 <= b0_v) (hle : b0_v + 1 <= m0) :
    DirectBlockList (encS (2 * m0) true b0_v [] None)
      (encS (2 * (m0 + 3)) true (b0_v - 2) [] None) [m0 - b0_v; m0 - b0_v + 3].
Proof.
  assert (hv1 : c0Valid_nat (2 * m0) true b0_v = true).
  { unfold c0Valid_nat. apply Bool.andb_true_iff; split; [apply Nat.leb_le; lia |].
    apply Bool.andb_true_iff; split; [apply Nat.eqb_eq; lia | apply Nat.leb_le; lia]. }
  assert (hp1 : 1 <= c0E1_nat (2 * m0) true b0_v).
  { unfold c0E1_nat; pose proof (Nat.div_mod (2 * m0) 2 ltac:(lia)); lia. }
  pose proof (c0_directBlock (2 * m0) true b0_v hv1 hp1) as h1.
  cbn [c0Step1_nat c0E1_nat] in h1.
  replace ((2 * m0) / 2 - b0_v) with (m0 - b0_v) in h1
    by (pose proof (Nat.div_mod (2 * m0) 2 ltac:(lia)); lia).
  assert (hv2 : c0Valid_nat (2 * m0 + 3) false b0_v = true).
  { unfold c0Valid_nat. apply Bool.andb_true_iff; split; [apply Nat.leb_le; lia |].
    apply Bool.andb_true_iff; split; [apply Nat.eqb_eq; lia | apply Nat.leb_le; lia]. }
  assert (hp2 : 1 <= c0E1_nat (2 * m0 + 3) false b0_v).
  { unfold c0E1_nat; pose proof (Nat.div_mod (2 * m0 + 3) 2 ltac:(lia)); lia. }
  pose proof (c0_directBlock (2 * m0 + 3) false b0_v hv2 hp2) as h2.
  cbn [c0Step1_nat c0E1_nat] in h2.
  replace (2 * m0 + 3 + 3) with (2 * (m0 + 3)) in h2 by lia.
  replace ((2 * m0 + 3) / 2 + 2 - b0_v) with (m0 - b0_v + 3) in h2
    by (pose proof (Nat.div_mod (2 * m0 + 3) 2 ltac:(lia)); lia).
  exact (DirectBlockList_cons h1 (DirectBlockList_cons h2 (DirectBlockList_nil _))).
Qed.

Lemma DirectBlockList_uncons {W W' : list Sym} {b : nat} {bs : list nat}
    (h : DirectBlockList W W' (b :: bs)) :
    exists Wm, DirectBlock W Wm b /\ DirectBlockList Wm W' bs.
Proof.
  inversion h as [| Wa Wm Wb e bs' hb hrest]; subst.
  exists Wm. split; [exact hb | exact hrest].
Qed.

Lemma DirectBlockList_nil_eq {W W' : list Sym}
    (h : DirectBlockList W W' []) : W = W'.
Proof. inversion h. reflexivity. Qed.

Lemma c0_directBlock_6 (m0 b0_v : nat) (hb : 9 <= b0_v) (hle : b0_v + 1 <= m0) :
    DirectBlockList (encS (2 * m0) true b0_v [] None)
      (encS (2 * (m0 + 9)) true (b0_v - 6) [] None)
      [m0 - b0_v; m0 - b0_v + 3; m0 - b0_v + 5; m0 - b0_v + 8; m0 - b0_v + 10; m0 - b0_v + 13].
Proof.
  pose proof (c0_directBlock_2 m0 b0_v ltac:(lia) ltac:(lia)) as h1.
  pose proof (c0_directBlock_2 (m0 + 3) (b0_v - 2) ltac:(lia) ltac:(lia)) as h2.
  pose proof (c0_directBlock_2 (m0 + 6) (b0_v - 4) ltac:(lia) ltac:(lia)) as h3.
  replace (m0 + 3 + 3) with (m0 + 6) in h2 by lia.
  replace (b0_v - 2 - 2) with (b0_v - 4) in h2 by lia.
  replace (m0 + 3 - (b0_v - 2)) with (m0 - b0_v + 5) in h2 by lia.
  replace (m0 - b0_v + 5 + 3) with (m0 - b0_v + 8) in h2 by lia.
  replace (m0 + 6 + 3) with (m0 + 9) in h3 by lia.
  replace (b0_v - 4 - 2) with (b0_v - 6) in h3 by lia.
  replace (m0 + 6 - (b0_v - 4)) with (m0 - b0_v + 10) in h3 by lia.
  replace (m0 - b0_v + 10 + 3) with (m0 - b0_v + 13) in h3 by lia.
  destruct (DirectBlockList_uncons h1) as [Wa [ha h1']].
  destruct (DirectBlockList_uncons h1') as [Wb [hb' h1'']].
  rewrite (DirectBlockList_nil_eq h1'') in hb'.
  destruct (DirectBlockList_uncons h2) as [Wc [hc h2']].
  destruct (DirectBlockList_uncons h2') as [Wd [hd h2'']].
  rewrite (DirectBlockList_nil_eq h2'') in hd.
  exact (DirectBlockList_cons ha (DirectBlockList_cons hb' (DirectBlockList_cons hc (DirectBlockList_cons hd h3)))).
Qed.

Definition Wave3Gap (E1 E2 E3 m1 b1 Cv : nat) : Prop :=
  (m1 + b1 <= E1 -> (E1 - (m1 + b1) < Cv \/ Cv + 150 <= E1 - (m1 + b1)) /\
    (E1 + E2 - (2 * m1 + b1) < Cv \/ Cv + 150 <= E1 + E2 - (2 * m1 + b1))) /\
  (E1 < m1 + b1 -> 2 * m1 + b1 <= E1 + E2 ->
    (E1 + E2 - (2 * m1 + b1) < Cv \/ Cv + 150 <= E1 + E2 - (2 * m1 + b1))) /\
  Cv + 150 <= E1 + E2 + E3 - (3 * m1 + b1 + 1).

Lemma wave_3hub_to_blockMin {W0 W1 W2 W3 : list Sym} {E1 E2 E3 : nat}
    (m1 b1 : nat) (sp_list : list RleItem) (hsp1 : isTranspList sp_list = true) (k_tr : nat)
    (hb1_ge : 4 <= b1) (hE1 : m1 + 3 <= E1) (hE2 : m1 + 1 <= E2) (hE3 : m1 + 2 <= E3)
    (hgap : Wave3Gap E1 E2 E3 m1 b1 (transpListCost_nat sp_list + 97 * k_tr))
    (hd1 : DirectBlock W0 W1 E1) (hd2 : DirectBlock W1 W2 E2) (hd3 : DirectBlock W2 W3 E3) :
    exists e0' es',
      OneBlockW
        (((W0 ++ encS (2 * m1 + 1) false b1 [] None) ++ encItems sp_list) ++ encTranspRun_nat 138 28 k_tr)
        (((W3 ++ encS (2 * (m1 + 1) + 1) false (b1 - 2) [] None) ++ encItems sp_list) ++ encTranspRun_nat 138 28 k_tr)
        e0' es' /\
      150 <= e0' /\
      e0' + sumList es' = E1 + E2 + E3 - (3 * m1 + b1 + 1) - (transpListCost_nat sp_list + 97 * k_tr).
Proof.
  set (Cv := transpListCost_nat sp_list + 97 * k_tr) in *.
  assert (hTot : 3 * m1 + (b1 - 2) + 3 <= E1 + E2 + E3) by (destruct hgap as [_ [_ hg3]]; lia).
  destruct (DirectBlock_liftDigitCycle_exact m1 (b1 - 2) ltac:(lia) hd1 hd2 hd3 hE1 hE2 hE3 hTot)
    as [e1 [es1 [hblk1 [hsum1 hcases]]]].
  replace (b1 - 2 + 2) with b1 in hblk1 by lia.
  replace (2 * m1 + 3) with (2 * (m1 + 1) + 1) in hblk1 by lia.
  destruct (OneBlock_liftTranspList_shift sp_list hsp1 hblk1 ltac:(destruct hgap as [_ [_ hg3]]; lia))
    as [e1a [es1a [hblk1a hsh1a]]].
  pose proof (SuffixShift_sum_eq hsh1a) as hsum1a; cbn [sumList] in hsum1a.
  destruct (OneBlock_liftTranspRun_shift k_tr 69 26 ltac:(lia) hblk1a ltac:(destruct hgap as [_ [_ hg3]]; lia))
    as [e2 [es2 [hblk2 hsh1b]]].
  assert (hsh : SuffixShift Cv (e1 :: es1) (e2 :: es2)).
  { pose proof (SuffixShift_trans hsh1a hsh1b) as htr.
    replace (transpListCost_nat sp_list + k_tr * (69 + 26 + 2)) with Cv in htr by (unfold Cv; lia).
    exact htr. }
  pose proof (SuffixShift_sum_eq hsh) as hsum2; cbn [sumList] in hsum2.
  assert (hmin : 150 <= e2).
  { apply (SuffixShift_head_ge_of_gap hsh).
    clearbody Cv; clear - hb1_ge hE1 hE2 hE3 hgap hcases.
    intros j hj.
    destruct hgap as [hg1 [hg2 hg3]].
    destruct hcases as [[hA heq] | [[hnA [hB heq]] | [hnB heq]]]; (try rewrite heq in hj; try rewrite heq); simpl in hj.
    - clear hg2; destruct (hg1 ltac:(lia)) as [hga1 hga2].
      destruct j as [|[|[|]]]; try lia; simpl; lia.
    - clear hg1; pose proof (hg2 ltac:(lia) ltac:(lia)) as hgb.
      destruct j as [|[|]]; try lia; simpl; lia.
    - clear hg1 hg2; assert (j = 0) by lia; subst j; simpl; lia. }
  exists e2, es2. split; [| split; [exact hmin | clearbody Cv; clear - hb1_ge hsum1 hsum2 hgap; destruct hgap as [_ [_ hg3]]; lia]].
  exact (OneBlock_toWeak hblk2).
Qed.

Lemma wave_6hub_2blocks (m0 b0_v m1 b1 : nat)
    (sp0 sp_list : list RleItem) (hsp0 : isTranspList sp0 = true) (hsp1 : isTranspList sp_list = true)
    (k_tr : nat) (hb0 : 9 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + m1 + 4 <= m0) (hb1 : 6 <= b1)
    (hgap0 : Wave3Gap (m0 - b0_v - transpListCost_nat sp0) (m0 - b0_v - transpListCost_nat sp0 + 3)
      (m0 - b0_v - transpListCost_nat sp0 + 5) m1 b1 (transpListCost_nat sp_list + 97 * k_tr))
    (hgap1 : Wave3Gap (m0 - b0_v - transpListCost_nat sp0 + 8) (m0 - b0_v - transpListCost_nat sp0 + 10)
      (m0 - b0_v - transpListCost_nat sp0 + 13) (m1 + 1) (b1 - 2) (transpListCost_nat sp_list + 97 * k_tr)) :
    let E0 := m0 - b0_v - transpListCost_nat sp0 in
    let Cv := transpListCost_nat sp_list + 97 * k_tr in
    BlockListMin 150
      ((((encS (2 * m0) true b0_v [] None ++ encItems sp0) ++ encS (2 * m1 + 1) false b1 [] None)
        ++ encItems sp_list) ++ encTranspRun_nat 138 28 k_tr)
      ((((encS (2 * (m0 + 9)) true (b0_v - 6) [] None ++ encItems sp0)
        ++ encS (2 * (m1 + 2) + 1) false (b1 - 4) [] None)
        ++ encItems sp_list) ++ encTranspRun_nat 138 28 k_tr)
      [3 * E0 + 8 - (3 * m1 + b1 + 1) - Cv; 3 * E0 + 31 - (3 * m1 + b1 + 2) - Cv].
Proof.
  cbv zeta.
  pose proof (c0_directBlock_6 m0 b0_v hb0 ltac:(lia)) as h6.
  destruct (DirectBlockList_uncons h6) as [Wa [d0 h6a]].
  destruct (DirectBlockList_uncons h6a) as [Wb [d1 h6b]].
  destruct (DirectBlockList_uncons h6b) as [Wc [d2 h6c]].
  destruct (DirectBlockList_uncons h6c) as [Wd [d3 h6d]].
  destruct (DirectBlockList_uncons h6d) as [We [d4 h6e]].
  destruct (DirectBlockList_uncons h6e) as [Wf [d5 h6f]].
  rewrite (DirectBlockList_nil_eq h6f) in d5.
  set (E0 := m0 - b0_v - transpListCost_nat sp0) in *.
  set (Cv := transpListCost_nat sp_list + 97 * k_tr) in *.
  assert (hE0_ge : m1 + 4 <= E0) by (clear - hle0; unfold E0; lia).
  pose proof (DirectBlock_liftTranspList sp0 hsp0 d0 ltac:(clear - hle0; lia)) as l0.
  pose proof (DirectBlock_liftTranspList sp0 hsp0 d1 ltac:(clear - hle0; lia)) as l1.
  pose proof (DirectBlock_liftTranspList sp0 hsp0 d2 ltac:(clear - hle0; lia)) as l2.
  pose proof (DirectBlock_liftTranspList sp0 hsp0 d3 ltac:(clear - hle0; lia)) as l3.
  pose proof (DirectBlock_liftTranspList sp0 hsp0 d4 ltac:(clear - hle0; lia)) as l4.
  pose proof (DirectBlock_liftTranspList sp0 hsp0 d5 ltac:(clear - hle0; lia)) as l5.
  change (m0 - b0_v - transpListCost_nat sp0) with E0 in l0.
  replace (m0 - b0_v + 3 - transpListCost_nat sp0) with (E0 + 3) in l1 by (clear - hle0; unfold E0; lia).
  replace (m0 - b0_v + 5 - transpListCost_nat sp0) with (E0 + 5) in l2 by (clear - hle0; unfold E0; lia).
  replace (m0 - b0_v + 8 - transpListCost_nat sp0) with (E0 + 8) in l3 by (clear - hle0; unfold E0; lia).
  replace (m0 - b0_v + 10 - transpListCost_nat sp0) with (E0 + 10) in l4 by (clear - hle0; unfold E0; lia).
  replace (m0 - b0_v + 13 - transpListCost_nat sp0) with (E0 + 13) in l5 by (clear - hle0; unfold E0; lia).
  destruct (wave_3hub_to_blockMin (E1 := E0) (E2 := E0 + 3) (E3 := E0 + 5) m1 b1 sp_list hsp1 k_tr
    ltac:(clear - hb1; lia) ltac:(clear - hE0_ge; lia) ltac:(clear - hE0_ge; lia) ltac:(clear - hE0_ge; lia) hgap0 l0 l1 l2)
    as [eA [esA [hA [hminA hsumA]]]].
  destruct (wave_3hub_to_blockMin (E1 := E0 + 8) (E2 := E0 + 10) (E3 := E0 + 13) (m1 + 1) (b1 - 2) sp_list hsp1 k_tr
    ltac:(clear - hb1; lia) ltac:(clear - hE0_ge; lia) ltac:(clear - hE0_ge; lia) ltac:(clear - hE0_ge; lia) hgap1 l3 l4 l5)
    as [eB [esB [hB [hminB hsumB]]]].
  change (transpListCost_nat sp_list + 97 * k_tr) with Cv in hsumA, hsumB.
  replace (m1 + 1 + 1) with (m1 + 2) in hB by (clear; lia).
  replace (b1 - 2 - 2) with (b1 - 4) in hB by (clear - hb1; lia).
  assert (hAeq : eA + sumList esA = 3 * E0 + 8 - (3 * m1 + b1 + 1) - Cv) by (clear - hsumA; clearbody E0 Cv; lia).
  assert (hBeq : eB + sumList esB = 3 * E0 + 31 - (3 * m1 + b1 + 2) - Cv) by (clear - hsumB hb1; clearbody E0 Cv; lia).
  rewrite <- hAeq, <- hBeq.
  exact (BlockListMin_cons _ hA hminA (BlockListMin_cons _ hB hminB (BlockListMin_nil _ _))).
Qed.

Lemma wave_6K_sum_eq (K E0 M1 Cv : nat) (hge : M1 + Cv <= 3 * E0) :
  6 * K * E0 + 45 * K * K - 6 * K - (2 * K * M1 + K * (2 * K - 1)) - 2 * K * Cv =
  2 * K * (3 * E0 - M1 - Cv) + 43 * K * K - 5 * K.
Proof.
  destruct K as [|k]; [simpl; lia |].
  set (D := 3 * E0 - M1 - Cv).
  assert (h6 : 6 * S k * E0 = 2 * S k * D + 2 * S k * M1 + 2 * S k * Cv)
    by (unfold D; clear - hge; nia).
  rewrite h6; clearbody D; clear hge h6.
  set (P := 2 * S k * D); set (A := 2 * S k * M1); set (B := 2 * S k * Cv).
  clearbody P A B; clear; nia.
Qed.

Lemma wave_6K_blocks (Kv : nat) :
    forall (m0 b0_v m1 b1 : nat)
    (sp0 sp_list : list RleItem) (hsp0 : isTranspList sp0 = true) (hsp1 : isTranspList sp_list = true)
    (k_tr : nat)
    (hb0 : 6 * Kv + 3 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + m1 + 4 <= m0) (hb1 : 4 * Kv + 2 <= b1)
    (hgaps : forall j, j < Kv ->
      let E0 := m0 - b0_v - transpListCost_nat sp0 + 15 * j in
      let m1j := m1 + 2 * j in
      let b1j := b1 - 4 * j in
      Wave3Gap E0 (E0 + 3) (E0 + 5) m1j b1j (transpListCost_nat sp_list + 97 * k_tr) /\
      Wave3Gap (E0 + 8) (E0 + 10) (E0 + 13) (m1j + 1) (b1j - 2) (transpListCost_nat sp_list + 97 * k_tr)),
    exists bs, BlockListMin 150
        ((((encS (2 * m0) true b0_v [] None ++ encItems sp0) ++ encS (2 * m1 + 1) false b1 [] None)
          ++ encItems sp_list) ++ encTranspRun_nat 138 28 k_tr)
        ((((encS (2 * (m0 + 9 * Kv)) true (b0_v - 6 * Kv) [] None ++ encItems sp0)
          ++ encS (2 * (m1 + 2 * Kv) + 1) false (b1 - 4 * Kv) [] None)
          ++ encItems sp_list) ++ encTranspRun_nat 138 28 k_tr) bs /\
      List.length bs = 2 * Kv /\
      sumList bs = 6 * Kv * (m0 - b0_v - transpListCost_nat sp0) + 45 * Kv * Kv - 6 * Kv
        - (2 * Kv * (3 * m1 + b1 + 1) + Kv * (2 * Kv - 1)) - 2 * Kv * (transpListCost_nat sp_list + 97 * k_tr).
Proof.
  induction Kv as [|K' IH]; intros m0 b0_v m1 b1 sp0 sp_list hsp0 hsp1 k_tr hb0 hle0 hb1 hgaps.
  - exists (@nil nat). replace (m0 + 9 * 0) with m0 by lia.
    replace (b0_v - 6 * 0) with b0_v by lia.
    replace (m1 + 2 * 0) with m1 by lia.
    replace (b1 - 4 * 0) with b1 by lia.
    split; [exact (BlockListMin_nil _ _) | simpl; lia].
  - pose proof (hgaps 0 ltac:(clear; lia)) as hg0; cbv zeta in hg0.
    replace (15 * 0) with 0 in hg0 by (clear; lia).
    replace (m0 - b0_v - transpListCost_nat sp0 + 0) with (m0 - b0_v - transpListCost_nat sp0) in hg0 by (clear; lia).
    replace (m1 + 2 * 0) with m1 in hg0 by (clear; lia).
    replace (b1 - 4 * 0) with b1 in hg0 by (clear; lia).
    pose proof (wave_6hub_2blocks m0 b0_v m1 b1 sp0 sp_list hsp0 hsp1 k_tr
                  ltac:(clear - hb0; lia) hle0 ltac:(clear - hb1; lia) (proj1 hg0) (proj2 hg0)) as h2; cbv zeta in h2.
    assert (hrec_gaps : forall j, j < K' ->
      let E0 := (m0 + 9) - (b0_v - 6) - transpListCost_nat sp0 + 15 * j in
      let m1j := (m1 + 2) + 2 * j in
      let b1j := (b1 - 4) - 4 * j in
      Wave3Gap E0 (E0 + 3) (E0 + 5) m1j b1j (transpListCost_nat sp_list + 97 * k_tr) /\
      Wave3Gap (E0 + 8) (E0 + 10) (E0 + 13) (m1j + 1) (b1j - 2) (transpListCost_nat sp_list + 97 * k_tr)).
    { intros j hj. pose proof (hgaps (j + 1) ltac:(clear - hj; lia)) as hgj; cbv zeta in hgj |- *.
      replace ((m0 + 9) - (b0_v - 6) - transpListCost_nat sp0 + 15 * j)
        with (m0 - b0_v - transpListCost_nat sp0 + 15 * (j + 1)) by (clear - hb0 hle0; lia).
      replace ((m1 + 2) + 2 * j) with (m1 + 2 * (j + 1)) by (clear; lia).
      replace ((b1 - 4) - 4 * j) with (b1 - 4 * (j + 1)) by (clear - hb1 hj; lia).
      exact hgj. }
    destruct (IH (m0 + 9) (b0_v - 6) (m1 + 2) (b1 - 4) sp0 sp_list hsp0 hsp1 k_tr
                ltac:(clear - hb0; lia) ltac:(clear - hb0 hle0; lia) ltac:(clear - hb1; lia) hrec_gaps) as [bs' [hbl' [hlen' hsum']]].
    replace (m0 + 9 + 9 * K') with (m0 + 9 * S K') in hbl' by (clear; lia).
    replace (b0_v - 6 - 6 * K') with (b0_v - 6 * S K') in hbl' by (clear - hb0; lia).
    replace (m1 + 2 + 2 * K') with (m1 + 2 * S K') in hbl' by (clear; lia).
    replace (b1 - 4 - 4 * K') with (b1 - 4 * S K') in hbl' by (clear - hb1; lia).
    exists ([3 * (m0 - b0_v - transpListCost_nat sp0) + 8 - (3 * m1 + b1 + 1) - (transpListCost_nat sp_list + 97 * k_tr);
             3 * (m0 - b0_v - transpListCost_nat sp0) + 31 - (3 * m1 + b1 + 2) - (transpListCost_nat sp_list + 97 * k_tr)] ++ bs').
    split; [exact (BlockListMin_append h2 hbl') |].
    split; [clear - hlen'; simpl; lia |].
    set (E0 := m0 - b0_v - transpListCost_nat sp0) in *.
    set (Cv := transpListCost_nat sp_list + 97 * k_tr) in *.
    replace ((m0 + 9) - (b0_v - 6) - transpListCost_nat sp0) with (E0 + 15) in hsum' by (clear - hb0 hle0; unfold E0; lia).
    replace (3 * (m1 + 2) + (b1 - 4) + 1) with (3 * m1 + b1 + 3) in hsum' by (clear - hb1; lia).
    assert (hgeA : (3 * m1 + b1 + 1) + Cv + 150 <= 3 * E0 + 8) by (destruct hg0 as [[_ [_ ha]] _]; clear - ha; unfold E0, Cv in *; lia).
    rewrite sumList_append; cbn [sumList].
    destruct K' as [|K''].
    + simpl in hsum' |- *; rewrite hsum'; clear - hgeA; clearbody E0 Cv; lia.
    + rewrite (wave_6K_sum_eq (S K'') (E0 + 15) (3 * m1 + b1 + 3) Cv ltac:(clear - hgeA; lia)) in hsum'.
      rewrite (wave_6K_sum_eq (S (S K'')) E0 (3 * m1 + b1 + 1) Cv ltac:(clear - hgeA; lia)).
      rewrite hsum'.
      set (D := 3 * E0 - (3 * m1 + b1 + 1) - Cv).
      replace (3 * E0 + 8 - (3 * m1 + b1 + 1) - Cv) with (D + 8) by (unfold D; clear - hgeA; lia).
      replace (3 * E0 + 31 - (3 * m1 + b1 + 2) - Cv) with (D + 30) by (unfold D; clear - hgeA; lia).
      replace (3 * (E0 + 15) - (3 * m1 + b1 + 3) - Cv) with (D + 43) by (unfold D; clear - hgeA; lia).
      clearbody D; clear; nia.
Qed.

Definition wave402dS0_nat (m0 b0_v sp0_c m1 b1 sp1_c k_tr : nat) : nat :=
  402 * (m0 - b0_v - sp0_c) + (186 * 1000 + 988) - 134 * (3 * m1 + b1 + 1 + sp1_c + 97 * k_tr).

Definition wave402Stot_nat (m0 b0_v sp0_c m1 b1 sp1_c k_tr Wv : nat) : nat :=
  Wv * wave402dS0_nat m0 b0_v sp0_c m1 b1 sp1_c k_tr + (186 * 1000 + 528) * Wv * (Wv - 1).

Lemma wave402dS0_to_nat (m0 b0_v sp0_c m1 b1 sp1_c k_tr : N) :
  N.to_nat (wave402dS0 m0 b0_v sp0_c m1 b1 sp1_c k_tr) =
  wave402dS0_nat (N.to_nat m0) (N.to_nat b0_v) (N.to_nat sp0_c)
    (N.to_nat m1) (N.to_nat b1) (N.to_nat sp1_c) (N.to_nat k_tr).
Proof. unfold wave402dS0, wave402dS0_nat; lia. Qed.

Lemma wave402Stot_to_nat (m0 b0_v sp0_c m1 b1 sp1_c k_tr Wv : N) :
  N.to_nat (wave402Stot m0 b0_v sp0_c m1 b1 sp1_c k_tr Wv) =
  wave402Stot_nat (N.to_nat m0) (N.to_nat b0_v) (N.to_nat sp0_c)
    (N.to_nat m1) (N.to_nat b1) (N.to_nat sp1_c) (N.to_nat k_tr) (N.to_nat Wv).
Proof.
  unfold wave402Stot, wave402Stot_nat; rewrite <- wave402dS0_to_nat.
  set (D := wave402dS0 m0 b0_v sp0_c m1 b1 sp1_c k_tr); clearbody D; clear; nia.
Qed.

Lemma wave402_1cycle (m0 b0_v m1 b1 k_tr pr : nat)
    (sp0 sp_list : list RleItem) (hsp0 : isTranspList sp0 = true) (hsp1 : isTranspList sp_list = true)
    (hb0 : 405 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + m1 + 4 <= m0) (hb1 : 270 <= b1) (hpr : 2 <= pr)
    (hgaps : forall j, j < 67 ->
      let E0 := m0 - b0_v - transpListCost_nat sp0 + 15 * j in
      let m1j := m1 + 2 * j in
      let b1j := b1 - 4 * j in
      Wave3Gap E0 (E0 + 3) (E0 + 5) m1j b1j (transpListCost_nat sp_list + 97 * k_tr) /\
      Wave3Gap (E0 + 8) (E0 + 10) (E0 + 13) (m1j + 1) (b1j - 2) (transpListCost_nat sp_list + 97 * k_tr)) :
    exists es_tot,
      PureP2W
        (((((((encS (2 * m0) true b0_v [] None ++ encItems sp0)
          ++ encS (2 * m1 + 1) false b1 [] None) ++ encItems sp_list)
          ++ encTranspRun_nat 138 28 k_tr)
          ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
          ++ encPairRun_nat 1 true 39 1 true 40 pr)
        (((((((encS (2 * (m0 + 603)) true (b0_v - 402) [] None ++ encItems sp0)
          ++ encS (2 * (m1 + 134) + 1) false (b1 - 268) [] None) ++ encItems sp_list)
          ++ encTranspRun_nat 138 28 (k_tr + 1))
          ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
          ++ encPairRun_nat 1 true 39 1 true 40 (pr - 2))
        es_tot /\
      sumList es_tot = wave402dS0_nat m0 b0_v (transpListCost_nat sp0) m1 b1 (transpListCost_nat sp_list) k_tr.
Proof.
  destruct (wave_6K_blocks 67 m0 b0_v m1 b1 sp0 sp_list hsp0 hsp1 k_tr ltac:(lia) hle0 ltac:(lia) hgaps)
    as [bs [hbl [hlen hsum]]].
  destruct (wave402_front_134 hbl hlen) as [es_tot [hp [hsum_es _]]].
  pose proof (PureP2W_liftPairRun 1 39 1 40 (pr - 2) hp) as hp'.
  assert (hPR : encPairRun_nat 1 true 39 1 true 40 2 ++ encPairRun_nat 1 true 39 1 true 40 (pr - 2) =
                encPairRun_nat 1 true 39 1 true 40 pr).
  { unfold encPairRun_nat; fold_pow_add; replace (2 + (pr - 2)) with pr by lia; reflexivity. }
  assert (hTR : encTranspRun_nat 138 28 k_tr ++ encS 138 false 28 [] None =
                encTranspRun_nat 138 28 (k_tr + 1)).
  { unfold encTranspRun_nat, encS; cbn [encSegTail].
    rewrite (list_pow_succ_right _ k_tr), ?app_nil_r, ?append_assoc. reflexivity. }
  exists es_tot. split.
  - replace (m0 + 9 * 67) with (m0 + 603) in hp' by lia.
    replace (b0_v - 6 * 67) with (b0_v - 402) in hp' by lia.
    replace (m1 + 2 * 67) with (m1 + 134) in hp' by lia.
    replace (b1 - 4 * 67) with (b1 - 268) in hp' by lia.
    assert (hL : (((((((encS (2 * m0) true b0_v [] None ++ encItems sp0)
                    ++ encS (2 * m1 + 1) false b1 [] None) ++ encItems sp_list)
                    ++ encTranspRun_nat 138 28 k_tr)
                    ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
                    ++ encPairRun_nat 1 true 39 1 true 40 2)
                    ++ encPairRun_nat 1 true 39 1 true 40 (pr - 2) =
                 ((((((encS (2 * m0) true b0_v [] None ++ encItems sp0)
                    ++ encS (2 * m1 + 1) false b1 [] None) ++ encItems sp_list)
                    ++ encTranspRun_nat 138 28 k_tr)
                    ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
                    ++ encPairRun_nat 1 true 39 1 true 40 pr).
    { rewrite <- hPR, ?append_assoc. reflexivity. }
    assert (hR : (((((((encS (2 * (m0 + 603)) true (b0_v - 402) [] None ++ encItems sp0)
                    ++ encS (2 * (m1 + 134) + 1) false (b1 - 268) [] None) ++ encItems sp_list)
                    ++ encTranspRun_nat 138 28 k_tr) ++ encS 138 false 28 [] None)
                    ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
                    ++ encPairRun_nat 1 true 39 1 true 40 (pr - 2) =
                 ((((((encS (2 * (m0 + 603)) true (b0_v - 402) [] None ++ encItems sp0)
                    ++ encS (2 * (m1 + 134) + 1) false (b1 - 268) [] None) ++ encItems sp_list)
                    ++ encTranspRun_nat 138 28 (k_tr + 1))
                    ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
                    ++ encPairRun_nat 1 true 39 1 true 40 (pr - 2)).
    { rewrite <- hTR, ?append_assoc. reflexivity. }
    rewrite hL, hR in hp'. exact hp'.
  - pose proof (hgaps 0 ltac:(clear; lia)) as hg0; cbv zeta in hg0.
    assert (hge0 : (3 * m1 + b1 + 1) + (transpListCost_nat sp_list + 97 * k_tr) + 150 <= 3 * (m0 - b0_v - transpListCost_nat sp0) + 8)
      by (destruct hg0 as [[_ [_ ha]] _]; clear - ha; lia).
    rewrite (wave_6K_sum_eq 67 (m0 - b0_v - transpListCost_nat sp0) (3 * m1 + b1 + 1) (transpListCost_nat sp_list + 97 * k_tr) ltac:(clear - hge0; lia)) in hsum.
    rewrite hsum_es, hsum; clear - hge0; unfold wave402dS0_nat; lia.
Qed.

Definition wave402RegimeOk_nat (m0 b0_v sp0_c m1 b1 sp1_c k_tr Wv : nat) : bool :=
  if Nat.eqb Wv 0 then true
  else
    let E0 := m0 - b0_v - sp0_c in
    let Cv := sp1_c + 97 * k_tr in
    let E1_max := E0 + 1005 * (Wv - 1) + 998 in
    let m1_max := m1 + 134 * Wv - 1 in
    let b1_max := b1 - 268 * Wv + 2 in
    let C_max := Cv + 97 * (Wv - 1) in
    let ok2 := (Nat.ltb (2 * E1_max + 2) (2 * m1_max + b1_max) &&
                Nat.leb (Cv + 150 + (3 * m1 + b1 + 1)) (3 * E0 + 8))%bool in
    let ok1A := (Nat.ltb E1_max (m1_max + b1_max) &&
                 Nat.leb (Cv + 150 + (2 * m1 + b1)) (2 * E0 + 3))%bool in
    let ok0A := Nat.leb (Cv + 150 + (m1 + b1)) E0 in
    let ok0C := (Nat.leb (m1 + b1) E0 &&
                 Nat.ltb E1_max (m1_max + b1_max + C_max) &&
                 Nat.leb (Cv + 150 + (2 * m1 + b1)) (2 * E0 + 3))%bool in
    let ok0B := (Nat.leb (m1 + b1) E0 &&
                 Nat.ltb (2 * E1_max + 2) (2 * m1_max + b1_max + C_max) &&
                 Nat.leb (Cv + 150 + (3 * m1 + b1 + 1)) (3 * E0 + 8))%bool in
    let ok1B := (Nat.ltb E1_max (m1_max + b1_max) &&
                 Nat.ltb (2 * E1_max + 2) (2 * m1_max + b1_max + C_max) &&
                 Nat.leb (Cv + 150 + (3 * m1 + b1 + 1)) (3 * E0 + 8))%bool in
    (ok2 || ok1A || ok0A || ok0C || ok0B || ok1B)%bool.

Lemma N_leb_to_nat (a b : N) : (a <=? b)%N = Nat.leb (N.to_nat a) (N.to_nat b).
Proof.
  destruct ((a <=? b)%N) eqn:H1; destruct (Nat.leb (N.to_nat a) (N.to_nat b)) eqn:H2; try reflexivity.
  - apply N.leb_le in H1; apply Nat.leb_gt in H2; lia.
  - apply N.leb_gt in H1; apply Nat.leb_le in H2; lia.
Qed.

Lemma N_ltb_to_nat (a b : N) : (a <? b)%N = Nat.ltb (N.to_nat a) (N.to_nat b).
Proof.
  destruct ((a <? b)%N) eqn:H1; destruct (Nat.ltb (N.to_nat a) (N.to_nat b)) eqn:H2; try reflexivity.
  - apply N.ltb_lt in H1; apply Nat.ltb_ge in H2; lia.
  - apply N.ltb_ge in H1; apply Nat.ltb_lt in H2; lia.
Qed.

Lemma N_eqb_to_nat (a b : N) : (a =? b)%N = Nat.eqb (N.to_nat a) (N.to_nat b).
Proof.
  destruct ((a =? b)%N) eqn:H1; destruct (Nat.eqb (N.to_nat a) (N.to_nat b)) eqn:H2; try reflexivity.
  - apply N.eqb_eq in H1; apply Nat.eqb_neq in H2; lia.
  - apply N.eqb_neq in H1; apply Nat.eqb_eq in H2; lia.
Qed.

Lemma wave402RegimeOk_to_nat (m0 b0_v sp0_c m1 b1 sp1_c k_tr Wv : N) :
  wave402RegimeOk m0 b0_v sp0_c m1 b1 sp1_c k_tr Wv =
  wave402RegimeOk_nat (N.to_nat m0) (N.to_nat b0_v) (N.to_nat sp0_c)
    (N.to_nat m1) (N.to_nat b1) (N.to_nat sp1_c) (N.to_nat k_tr) (N.to_nat Wv).
Proof.
  unfold wave402RegimeOk, wave402RegimeOk_nat; cbv zeta.
  rewrite N_eqb_to_nat; cbn [N.to_nat Pos.to_nat Pos.iter_op Nat.add].
  destruct (Nat.eqb (N.to_nat Wv) 0); [reflexivity |].
  rewrite !N_ltb_to_nat, !N_leb_to_nat.
  repeat match goal with
  | |- (?a || ?b)%bool = (?c || ?d)%bool => f_equal
  | |- (?a && ?b)%bool = (?c && ?d)%bool => f_equal
  | |- Nat.ltb _ _ = Nat.ltb _ _ => f_equal; lia
  | |- Nat.leb _ _ = Nat.leb _ _ => f_equal; lia
  end.
Qed.

(* --- ScratchS4B2b2b.v --- *)
