Lemma Wave3Gap_of_no_sub (E1 E2 E3 m1 b1 Cv : nat) (hle12 : E1 <= E2)
    (h1 : m1 + b1 <= E1 ->
      (E1 < m1 + b1 + Cv \/ m1 + b1 + Cv + 150 <= E1) /\
      (E1 + E2 < 2 * m1 + b1 + Cv \/ 2 * m1 + b1 + Cv + 150 <= E1 + E2))
    (h2 : E1 < m1 + b1 -> 2 * m1 + b1 <= E1 + E2 ->
      (E1 + E2 < 2 * m1 + b1 + Cv \/ 2 * m1 + b1 + Cv + 150 <= E1 + E2))
    (h3 : 3 * m1 + b1 + 1 + Cv + 150 <= E1 + E2 + E3) :
    Wave3Gap E1 E2 E3 m1 b1 Cv.
Proof.
  unfold Wave3Gap; split; [| split].
  - intros hm; destruct (h1 hm) as [ha hb]; split.
    + clear - hm ha; lia.
    + clear - hle12 hm hb; lia.
  - intros hm1 hm2; pose proof (h2 hm1 hm2) as hb; clear - hm2 hb; lia.
  - clear - h3; lia.
Qed.

Lemma wave402RegimeOk_step (m0 b0_v sp0_c m1 b1 sp1_c k_tr W' : nat)
    (hb0 : 402 * (W' + 1) + 3 <= b0_v) (hle0 : b0_v + sp0_c + m1 + 4 <= m0)
    (hb1 : 268 * (W' + 1) + 2 <= b1)
    (hok : wave402RegimeOk_nat m0 b0_v sp0_c m1 b1 sp1_c k_tr (W' + 1) = true) :
    (forall j, j < 67 ->
      let E0 := m0 - b0_v - sp0_c + 15 * j in
      let m1j := m1 + 2 * j in
      let b1j := b1 - 4 * j in
      Wave3Gap E0 (E0 + 3) (E0 + 5) m1j b1j (sp1_c + 97 * k_tr) /\
      Wave3Gap (E0 + 8) (E0 + 10) (E0 + 13) (m1j + 1) (b1j - 2) (sp1_c + 97 * k_tr)) /\
    wave402RegimeOk_nat (m0 + 603) (b0_v - 402) sp0_c (m1 + 134) (b1 - 268) sp1_c (k_tr + 1) W' = true.
Proof.
  unfold wave402RegimeOk_nat in hok; cbv zeta in hok.
  replace (Nat.eqb (W' + 1) 0) with false in hok by (symmetry; apply Nat.eqb_neq; lia).
  replace (W' + 1 - 1) with W' in hok by lia.
  set (E0 := m0 - b0_v - sp0_c) in *.
  set (Cv := sp1_c + 97 * k_tr) in *.
  set (db1 := b1 - (268 * W' + 270)) in *.
  assert (hm0_eq : m0 = E0 + b0_v + sp0_c) by (clear - hle0; unfold E0; lia).
  assert (hE0_ge : m1 + 4 <= E0) by (clear - hle0; unfold E0; lia).
  assert (hb1_eq : b1 = db1 + 268 * W' + 270) by (clear - hb1; unfold db1; lia).
  clearbody db1.
  replace (m1 + 134 * (W' + 1) - 1) with (m1 + 134 * W' + 133) in hok by (clear; lia).
  replace (b1 - 268 * (W' + 1) + 2) with (db1 + 4) in hok by (clear - hb1_eq; lia).
  split.
  - intros j hj; cbv zeta.
    change (m0 - b0_v - sp0_c) with E0.
    set (rj := 66 - j).
    assert (hrj : j + rj = 66) by (clear - hj; unfold rj; lia).
    replace (b1 - 4 * j) with (db1 + 268 * W' + 4 * rj + 6) by (clear - hb1_eq hrj; lia).
    replace (db1 + 268 * W' + 4 * rj + 6 - 2) with (db1 + 268 * W' + 4 * rj + 4) by (clear; lia).
    rewrite hb1_eq in hok.
    clearbody E0 Cv rj; clear hm0_eq hb1_eq hb1 hj hle0 hb0.
    repeat (apply Bool.orb_true_iff in hok; destruct hok as [hok | hok]);
      repeat match goal with
      | H : (_ && _)%bool = true |- _ => apply Bool.andb_true_iff in H; destruct H
      | H : Nat.ltb _ _ = true |- _ => apply Nat.ltb_lt in H
      | H : Nat.leb _ _ = true |- _ => apply Nat.leb_le in H
      end;
      (split; (apply Wave3Gap_of_no_sub; [lia | intros; split; lia | intros; lia | lia])).
  - destruct W' as [|W''].
    + reflexivity.
    + unfold wave402RegimeOk_nat; cbv zeta.
      cbn [Nat.eqb].
      replace (S W'' - 1) with W'' by (clear; lia).
      replace ((m0 + 603) - (b0_v - 402) - sp0_c) with (E0 + 1005) by (clear - hb0 hm0_eq; clearbody E0; lia).
      replace (sp1_c + 97 * (k_tr + 1)) with (Cv + 97) by (clear; unfold Cv; lia).
      replace (E0 + 1005 + 1005 * W'' + 998) with (E0 + 1005 * S W'' + 998) by (clear; lia).
      replace (m1 + 134 + 134 * S W'' - 1) with (m1 + 134 * S W'' + 133) by (clear; lia).
      replace (b1 - 268 - 268 * S W'' + 2) with (db1 + 4) by (clear - hb1_eq; lia).
      replace (b1 - 268) with (db1 + 268 * S W'' + 2) by (clear - hb1_eq; lia).
      replace (Cv + 97 + 97 * W'') with (Cv + 97 * S W'') by (clear; lia).
      rewrite hb1_eq in hok.
      clearbody E0 Cv; clear hm0_eq hb1_eq hb1 hle0 hb0.
      repeat (apply Bool.orb_true_iff in hok; destruct hok as [hok | hok]);
        repeat match goal with
        | H : (_ && _)%bool = true |- _ => apply Bool.andb_true_iff in H; destruct H
        | H : Nat.ltb _ _ = true |- _ => apply Nat.ltb_lt in H
        | H : Nat.leb _ _ = true |- _ => apply Nat.leb_le in H
        end.
      * do 5 (apply Bool.orb_true_iff; left).
        apply Bool.andb_true_iff; split; [apply Nat.ltb_lt; lia | apply Nat.leb_le; lia].
      * do 4 (apply Bool.orb_true_iff; left); apply Bool.orb_true_iff; right.
        apply Bool.andb_true_iff; split; [apply Nat.ltb_lt; lia | apply Nat.leb_le; lia].
      * do 3 (apply Bool.orb_true_iff; left); apply Bool.orb_true_iff; right.
        apply Nat.leb_le; lia.
      * do 2 (apply Bool.orb_true_iff; left); apply Bool.orb_true_iff; right.
        repeat (apply Bool.andb_true_iff; split); try (apply Nat.ltb_lt; lia); apply Nat.leb_le; lia.
      * apply Bool.orb_true_iff; left; apply Bool.orb_true_iff; right.
        repeat (apply Bool.andb_true_iff; split); try (apply Nat.ltb_lt; lia); apply Nat.leb_le; lia.
      * apply Bool.orb_true_iff; right.
        repeat (apply Bool.andb_true_iff; split); try (apply Nat.ltb_lt; lia); apply Nat.leb_le; lia.
Qed.

Lemma wave402_Wcycles (Wv : nat) :
    forall (m0 b0_v m1 b1 k_tr pr : nat)
    (sp0 sp_list : list RleItem) (hsp0 : isTranspList sp0 = true) (hsp1 : isTranspList sp_list = true)
    (hb0 : 402 * Wv + 3 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + m1 + 4 <= m0)
    (hb1 : 268 * Wv + 2 <= b1) (hpr : 2 * Wv <= pr)
    (hok : wave402RegimeOk_nat m0 b0_v (transpListCost_nat sp0) m1 b1 (transpListCost_nat sp_list) k_tr Wv = true),
    exists es_tot,
      PureP2W
        (((((((encS (2 * m0) true b0_v [] None ++ encItems sp0)
          ++ encS (2 * m1 + 1) false b1 [] None) ++ encItems sp_list)
          ++ encTranspRun_nat 138 28 k_tr)
          ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
          ++ encPairRun_nat 1 true 39 1 true 40 pr)
        (((((((encS (2 * (m0 + 603 * Wv)) true (b0_v - 402 * Wv) [] None ++ encItems sp0)
          ++ encS (2 * (m1 + 134 * Wv) + 1) false (b1 - 268 * Wv) [] None) ++ encItems sp_list)
          ++ encTranspRun_nat 138 28 (k_tr + Wv))
          ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
          ++ encPairRun_nat 1 true 39 1 true 40 (pr - 2 * Wv))
        es_tot /\
      sumList es_tot = wave402Stot_nat m0 b0_v (transpListCost_nat sp0) m1 b1 (transpListCost_nat sp_list) k_tr Wv.
Proof.
  induction Wv as [|W' IH]; intros m0 b0_v m1 b1 k_tr pr sp0 sp_list hsp0 hsp1 hb0 hle0 hb1 hpr hok.
  - exists (@nil nat).
    replace (m0 + 603 * 0) with m0 by lia.
    replace (b0_v - 402 * 0) with b0_v by lia.
    replace (m1 + 134 * 0) with m1 by lia.
    replace (b1 - 268 * 0) with b1 by lia.
    replace (k_tr + 0) with k_tr by lia.
    replace (pr - 2 * 0) with pr by lia.
    split; [exact (PureP2W_nil _) | unfold wave402Stot_nat; simpl; lia].
  - replace (S W') with (W' + 1) in hb0, hb1, hok by lia.
    destruct (wave402RegimeOk_step m0 b0_v (transpListCost_nat sp0) m1 b1
                (transpListCost_nat sp_list) k_tr W' hb0 hle0 hb1 hok) as [hgaps hok_next].
    destruct (wave402_1cycle m0 b0_v m1 b1 k_tr pr sp0 sp_list hsp0 hsp1
                ltac:(lia) hle0 ltac:(lia) ltac:(lia) hgaps) as [es1 [hp1 hsum1]].
    destruct (IH (m0 + 603) (b0_v - 402) (m1 + 134) (b1 - 268) (k_tr + 1) (pr - 2) sp0 sp_list
                hsp0 hsp1 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) hok_next) as [es2 [hp2 hsum2]].
    replace (m0 + 603 + 603 * W') with (m0 + 603 * S W') in hp2 by lia.
    replace (b0_v - 402 - 402 * W') with (b0_v - 402 * S W') in hp2 by lia.
    replace (m1 + 134 + 134 * W') with (m1 + 134 * S W') in hp2 by lia.
    replace (b1 - 268 - 268 * W') with (b1 - 268 * S W') in hp2 by lia.
    replace (k_tr + 1 + W') with (k_tr + S W') in hp2 by lia.
    replace (pr - 2 - 2 * W') with (pr - 2 * S W') in hp2 by lia.
    exists (es1 ++ es2). split; [exact (PureP2W_append hp1 hp2) |].
    rewrite sumList_append, hsum1, hsum2.
    pose proof (hgaps 0 ltac:(lia)) as hg0; cbv zeta in hg0.
    assert (hge0 : 134 * (3 * m1 + b1 + 1 + transpListCost_nat sp_list + 97 * k_tr) <=
                   402 * (m0 - b0_v - transpListCost_nat sp0) + (186 * 1000 + 988))
      by (destruct hg0 as [[_ [_ ha]] _]; clear - ha; lia).
    assert (hdS_step : wave402dS0_nat (m0 + 603) (b0_v - 402) (transpListCost_nat sp0) (m1 + 134) (b1 - 268)
                         (transpListCost_nat sp_list) (k_tr + 1) =
                       wave402dS0_nat m0 b0_v (transpListCost_nat sp0) m1 b1 (transpListCost_nat sp_list) k_tr + (373 * 1000 + 56)).
    { unfold wave402dS0_nat.
      set (E0 := m0 - b0_v - transpListCost_nat sp0) in *.
      replace ((m0 + 603) - (b0_v - 402) - transpListCost_nat sp0) with (E0 + 1005)
        by (clear - hb0 hle0; unfold E0; lia).
      replace (3 * (m1 + 134) + (b1 - 268) + 1 + transpListCost_nat sp_list + 97 * (k_tr + 1))
        with (3 * m1 + b1 + 1 + transpListCost_nat sp_list + 97 * k_tr + 231)
        by (clear - hb1; lia).
      clearbody E0; clear - hge0; lia. }
    unfold wave402Stot_nat; rewrite hdS_step.
    set (D0 := wave402dS0_nat m0 b0_v (transpListCost_nat sp0) m1 b1 (transpListCost_nat sp_list) k_tr).
    clearbody D0; clear; destruct W' as [|W'']; nia.
Qed.

Lemma extractTR138_sound {hasTR : bool} {xs rest : list RleItem} {k_tr : N}
    (h : extractTR138 hasTR xs = Some (k_tr, rest)) :
    encItems xs = encItem (RItranspRun 138%N 28%N k_tr) ++ encItems rest.
Proof.
  unfold extractTR138 in h.
  destruct hasTR.
  - destruct xs as [|y ys]; [discriminate |].
    destruct y as [| ay by' k | |]; try discriminate.
    destruct (((ay =? 138)%N && (by' =? 28)%N)%bool) eqn:hc; [| discriminate].
    apply Bool.andb_true_iff in hc; destruct hc as [ha hb].
    apply N.eqb_eq in ha; apply N.eqb_eq in hb; subst ay by'.
    inv_some h; subst k rest. reflexivity.
  - inv_some h; subst k_tr rest.
    unfold encItem; cbn [N.to_nat]; rewrite zPz; reflexivity.
Qed.

Lemma stepWave402_sound (k0 k1 : nat) (Wv : N) (hasTR : bool) (items items' : list RleItem)
    (h : stepWave402 k0 k1 Wv hasTR items = Some items') :
    HubCfg items -[ tm ]->* HubCfg items'.
Proof.
  unfold stepWave402 in h.
  destruct items as [|x0 rest0]; [discriminate |].
  destruct x0 as [a0 [|] b0_v [|? ?] [?|] | | |]; try discriminate.
  destruct (negb (a0 mod 2 =? 0)%N) eqn:ha0; [discriminate |].
  apply Bool.negb_false_iff in ha0; apply N.eqb_eq in ha0.
  destruct (splitAtList k0 rest0) as [[sp0 rest1a]|] eqn:hs0; [| discriminate].
  destruct (negb (isTranspList sp0)) eqn:hsp0; [discriminate |].
  apply Bool.negb_false_iff in hsp0.
  destruct rest1a as [|x1 rest1]; [discriminate |].
  destruct x1 as [a1 [|] b1 [|? ?] [?|] | | |]; try discriminate.
  destruct (negb (a1 mod 2 =? 1)%N) eqn:ha1; [discriminate |].
  apply Bool.negb_false_iff in ha1; apply N.eqb_eq in ha1.
  destruct (splitAtList k1 rest1) as [[sp_list rest2]|] eqn:hs1; [| discriminate].
  destruct (negb (isTranspList sp_list)) eqn:hsp1; [discriminate |].
  apply Bool.negb_false_iff in hsp1.
  destruct (extractTR138 hasTR rest2) as [[k_tr rest3]|] eqn:htr; [| discriminate].
  destruct rest3 as [|u1 r3a]; [discriminate |].
  destruct u1 as [au1 [|] bu1 [|? ?] [?|] | | |]; try discriminate.
  destruct r3a as [|u2 r3b]; [discriminate |].
  destruct u2 as [au2 [|] bu2 [|? ?] [?|] | | |]; try discriminate.
  destruct r3b as [|u3 tail]; [discriminate |].
  destruct u3 as [| | pa1 [|] pb1 pa2 [|] pb2 pr |]; try discriminate.
  destruct (((au1 =? 5)%N && (bu1 =? 35)%N && (au2 =? 3)%N && (bu2 =? 39)%N &&
             (pa1 =? 1)%N && (pb1 =? 39)%N && (pa2 =? 1)%N && (pb2 =? 40)%N)%bool)
    eqn:hfront; [| discriminate].
  split_andb; subst au1 bu1 au2 bu2 pa1 pb1 pa2 pb2.
  cbv zeta in h.
  destruct (((402 * Wv + 3 <=? b0_v)%N && (b0_v + transpListCost sp0 + a1 / 2 + 4 <=? a0 / 2)%N &&
             (268 * Wv + 2 <=? b1)%N && (2 * Wv <=? pr)%N &&
             wave402RegimeOk (a0 / 2) b0_v (transpListCost sp0) (a1 / 2) b1 (transpListCost sp_list) k_tr Wv)%bool)
    eqn:hcond; [| discriminate].
  split_andb.
  destruct (applySinkDumpBig
              (wave402Stot (a0 / 2) b0_v (transpListCost sp0) (a1 / 2) b1 (transpListCost sp_list) k_tr Wv)
              tail) as [tail'|] eqn:hd; [| discriminate].
  inv_some h; subst items'.
  pose proof (splitAtList_sound _ _ _ _ hs0) as hr0; subst rest0.
  pose proof (splitAtList_sound _ _ _ _ hs1) as hr1; subst rest1.
  pose proof (extractTR138_sound htr) as hEncTR.
  pose proof (N2Nat_div a0 2) as Ha0div; change (N.to_nat 2%N) with 2 in Ha0div.
  pose proof (N2Nat_mod a0 2) as Ha0mod; change (N.to_nat 2%N) with 2 in Ha0mod.
  pose proof (N2Nat_div a1 2) as Ha1div; change (N.to_nat 2%N) with 2 in Ha1div.
  pose proof (N2Nat_mod a1 2) as Ha1mod; change (N.to_nat 2%N) with 2 in Ha1mod.
  assert (ha0_par : N.to_nat a0 = 2 * (N.to_nat a0 / 2))
    by (clear - ha0 Ha0mod; pose proof (Nat.div_mod (N.to_nat a0) 2 ltac:(lia)); lia).
  assert (ha1_par : N.to_nat a1 = 2 * (N.to_nat a1 / 2) + 1)
    by (clear - ha1 Ha1mod; pose proof (Nat.div_mod (N.to_nat a1) 2 ltac:(lia)); lia).
  clear Ha0mod Ha1mod ha0 ha1 hs0 hs1 htr.
  assert (hok_nat : wave402RegimeOk_nat (N.to_nat a0 / 2) (N.to_nat b0_v) (transpListCost_nat sp0)
                      (N.to_nat a1 / 2) (N.to_nat b1) (transpListCost_nat sp_list)
                      (N.to_nat k_tr) (N.to_nat Wv) = true).
  { rewrite wave402RegimeOk_to_nat in H0.
    unfold transpListCost_nat; rewrite Ha0div, Ha1div in H0. exact H0. }
  clear H0.
  destruct (wave402_Wcycles (N.to_nat Wv) (N.to_nat a0 / 2) (N.to_nat b0_v)
              (N.to_nat a1 / 2) (N.to_nat b1) (N.to_nat k_tr) (N.to_nat pr)
              sp0 sp_list hsp0 hsp1
              ltac:(lia) ltac:(unfold transpListCost_nat; lia) ltac:(lia) ltac:(lia) hok_nat)
    as [es_tot [hpw hsum]].
  pose proof (applySinkDumpBig_sound hd) as hdump.
  rewrite wave402Stot_to_nat, Ha0div, Ha1div in hdump.
  unfold transpListCost_nat in hsum.
  rewrite <- hsum in hdump.
  pose proof (PureP2W_dump hpw hdump) as hrun.
  clear - hrun hEncTR ha0_par ha1_par.
  assert (htrOut : encItems (if (k_tr + Wv =? 0)%N then [] else [RItranspRun 138%N 28%N (k_tr + Wv)]) =
                   encTranspRun_nat 138 28 (N.to_nat k_tr + N.to_nat Wv)).
  { destruct ((k_tr + Wv =? 0)%N) eqn:hz.
    - apply N.eqb_eq in hz. replace (N.to_nat k_tr + N.to_nat Wv) with 0 by (clear - hz; lia).
      unfold encTranspRun_nat; rewrite zPz; reflexivity.
    - cbn [encItems]; rewrite encItem_transpRun_eq, app_nil_r, N2Nat.inj_add. reflexivity. }
  replace (2 * (N.to_nat a0 / 2)) with (N.to_nat a0) in hrun by lia.
  replace (2 * (N.to_nat a1 / 2) + 1) with (N.to_nat a1) in hrun by lia.
  replace (2 * (N.to_nat a0 / 2 + 603 * N.to_nat Wv)) with (N.to_nat (a0 + 1206 * Wv)%N) in hrun by lia.
  replace (N.to_nat b0_v - 402 * N.to_nat Wv) with (N.to_nat (b0_v - 402 * Wv)%N) in hrun by lia.
  replace (2 * (N.to_nat a1 / 2 + 134 * N.to_nat Wv) + 1) with (N.to_nat (a1 + 268 * Wv)%N) in hrun by lia.
  replace (N.to_nat b1 - 268 * N.to_nat Wv) with (N.to_nat (b1 - 268 * Wv)%N) in hrun by lia.
  replace (N.to_nat pr - 2 * N.to_nat Wv) with (N.to_nat (pr - 2 * Wv)%N) in hrun by lia.
  unfold HubCfg.
  repeat (cbn [encItems app]; simp_encItems_app); rewrite hEncTR, htrOut; cbn [encItems];
    rewrite !encItem_transpRun_eq, !encItem_pairRun_eq; cbn [encItem];
    rewrite !encSingle_eq_encS; cbn [option_map N.to_nat Pos.to_nat].
  rewrite ?append_assoc, ?Str_app_assoc.
  rewrite ?append_assoc, ?Str_app_assoc in hrun.
  exact hrun.
Qed.

