(* Section 14.1: Unified Mirror 2-Hub Primitives                             *)
(* ========================================================================= *)

Lemma p1Entry_enterMirror_direct {e : nat} {R_out rest : list Sym} {r : Stream Sym}
    {cfg : Q * tape} (u aR : nat) (hge : u + 1 <= e)
    (h : P1Entry e R_out ((((T2 ^^ (2 * u + 1)) ++ T0) ++ (T2 ^^ aR)) ++ rest) r cfg) :
    exists Lt, PipeL (e - (u + 1)) R_out Lt /\
      cfg -[ tm ]->* (((T2 ^^ aR) *> (T3 ^^ (2 * u + 2)) *> Lt) {{C}}> (rest *> r)).
Proof.
  destruct h as [[Lt [[hp1 _] Hcfg]] | [Lt [W' [_ [hW [hp Hcfg]]]]]]; subst cfg.
  - assert (hsplit : ((((T2 ^^ (2 * u + 1)) ++ T0) ++ (T2 ^^ aR)) ++ rest) *> r =
                     (T2 ^^ (2 * u)) *> T2 *> T0 *> (T2 ^^ aR) *> rest *> r).
    { rewrite (list_pow_add T2 (2 * u) 1), list_pow_one, ?append_assoc, ?Str_app_assoc. reflexivity. }
    rewrite hsplit.
    destruct (pipeL_eat_t2_even (En := ltac:(match type of hp1 with PipeL ?x _ _ => exact x end))
                u 0 ltac:(lia) hp1 (T2 *> T0 *> (T2 ^^ aR) *> rest *> r))
      as [Lt1 [hp1' hs1]].
    simpl Nat.add in hs1; rewrite zPz, zLan in hs1.
    assert (he' : e - u = (e - (u + 1)) + 1) by lia.
    pose proof (pipeL_eqE he' hp1') as hp1''.
    destruct (PipeL_head0 hp1'') as [l1 hl1].
    destruct (PipeL_pull hp1'') as [Lt2 [hpull hp2]].
    pose proof (pull1_t3_t2_t0 (2 * u) hl1 hpull ((T2 ^^ aR) *> rest *> r)) as hs2.
    pose proof (step_mirror_enter ((T3 ^^ (2 * u + 1)) *> Lt2) ((T2 ^^ aR) *> rest *> r)) as hs3.
    pose proof (rule_mirror_t2 aR ((T3 ^^ (2 * u + 2)) *> Lt2) (rest *> r)) as hs4.
    exists Lt2. split; [exact hp2 |].
    eapply evstep_trans; [exact hs1 |].
    eapply evstep_trans; [exact hs2 |].
    eapply evstep_trans; [exact hs3 |].
    assert (hT3 : T3 *> (T3 ^^ (2 * u + 1)) *> Lt2 = (T3 ^^ (2 * u + 2)) *> Lt2)
      by (rewrite <- zPsr; replace (S (2 * u + 1)) with (2 * u + 2) by lia; reflexivity).
    rewrite hT3. exact hs4.
  - destruct u as [|u'].
    + assert (hW0 : (((T2 ^^ (2 * 0 + 1)) ++ T0) ++ (T2 ^^ aR)) ++ rest =
                    T2 ++ ((T0 ++ (T2 ^^ aR)) ++ rest)).
      { simpl (2 * 0 + 1). rewrite list_pow_one, ?append_assoc. reflexivity. }
      rewrite hW0 in hW.
      assert (hW' : W' = (T0 ++ (T2 ^^ aR)) ++ rest) by exact (app_cancel_left (eq_sym hW)).
      subst W'. rewrite ?Str_app_assoc.
      replace (e - (0 + 1)) with (e - 1) by lia.
      exists Lt. split; [exact hp |].
      eapply evstep_trans; [exact (step_t2_q5_t0_k0 Lt ((T2 ^^ aR) *> rest *> r)) |].
      eapply evstep_trans; [exact (step_mirror_enter (T3 *> Lt) ((T2 ^^ aR) *> rest *> r)) |].
      assert (h2 : T3 *> T3 *> Lt = (T3 ^^ (2 * 0 + 2)) *> Lt).
      { simpl (2 * 0 + 2). rewrite zPsr, zP1. reflexivity. }
      rewrite h2.
      exact (rule_mirror_t2 aR ((T3 ^^ (2 * 0 + 2)) *> Lt) (rest *> r)).
    + assert (hWs : (((T2 ^^ (2 * S u' + 1)) ++ T0) ++ (T2 ^^ aR)) ++ rest =
                    T2 ++ (T2 ++ ((T2 ^^ (2 * u')) ++ (((T2 ++ T0) ++ (T2 ^^ aR)) ++ rest)))).
      { replace (2 * S u' + 1) with (1 + (1 + (2 * u' + 1))) by lia.
        simp_pow_add; rewrite !list_pow_one, ?append_assoc. reflexivity. }
      rewrite hWs in hW.
      assert (hW' : W' = T2 ++ ((T2 ^^ (2 * u')) ++ (((T2 ++ T0) ++ (T2 ^^ aR)) ++ rest)))
        by exact (app_cancel_left (eq_sym hW)).
      subst W'. rewrite ?Str_app_assoc.
      pose proof (step_t2L_eat_t2 Lt ((T2 ^^ (2 * u')) *> T2 *> T0 *> (T2 ^^ aR) *> rest *> r)) as hs0.
      destruct (pipeL_eat_t2_even (En := ltac:(match type of hp with PipeL ?x _ _ => exact x end))
                  u' 2 ltac:(lia) hp (T2 *> T0 *> (T2 ^^ aR) *> rest *> r))
        as [Lt1 [hp1' hs1]].
      assert (he' : e - 1 - u' = (e - (S u' + 1)) + 1) by lia.
      pose proof (pipeL_eqE he' hp1') as hp1''.
      destruct (PipeL_head0 hp1'') as [l1 hl1].
      destruct (PipeL_pull hp1'') as [Lt2 [hpull hp2]].
      pose proof (pull1_t3_t2_t0 (2 + 2 * u') hl1 hpull ((T2 ^^ aR) *> rest *> r)) as hs2.
      pose proof (step_mirror_enter ((T3 ^^ (2 + 2 * u' + 1)) *> Lt2) ((T2 ^^ aR) *> rest *> r)) as hs3.
      pose proof (rule_mirror_t2 aR ((T3 ^^ (2 * S u' + 2)) *> Lt2) (rest *> r)) as hs4.
      exists Lt2. split; [exact hp2 |].
      eapply evstep_trans; [exact hs0 |].
      eapply evstep_trans; [exact hs1 |].
      eapply evstep_trans; [exact hs2 |].
      eapply evstep_trans; [exact hs3 |].
      assert (hT3 : T3 *> (T3 ^^ (2 + 2 * u' + 1)) *> Lt2 = (T3 ^^ (2 * S u' + 2)) *> Lt2)
        by (rewrite <- zPsr; replace (S (2 + 2 * u' + 1)) with (2 * S u' + 2) by lia; reflexivity).
      rewrite hT3. exact hs4.
Qed.

Lemma directBlock_enterMirror {W0 W1 W2 : list Sym} {E1 E2 : nat}
    (am : nat) (hm : bool) (bm : nat) (hok : hm = true \/ 1 <= bm)
    (d1 : DirectBlock W0 W1 E1) (d2 : DirectBlock W1 W2 E2)
    (hE1 : 1 <= E1) (hE12 : E1 <= E2) (ham : 2 * E1 + 2 <= am)
    (W_next : list Sym) (r : Stream Sym) :
    exists Lt, PipeL (E2 - E1) W2 Lt /\
      (b0 {{E}}> (T2 *> T0 *> T1 *> ((W0 ++ encS am hm bm [] None) ++ W_next) *> r))
        -[ tm ]->*
      (((T2 ^^ (am - 2 * E1)) *> (T3 ^^ (2 * E1)) *> Lt) {{C}}>
        ((((if hm then T5 else []) ++ (T4 ^^ bm)) ++ W_next) *> r)).
Proof.
  pose proof (OneBlock_enterASplit am hm bm [] hok (DirectBlock_toOneBlock d1)
                ltac:(cbn [sumList]; lia) ltac:(cbn [sumList]; lia) (W_next *> r)) as hs1.
  cbn [sumList] in hs1; replace (E1 + 0) with E1 in hs1 by lia.
  destruct (d2 (encS (2 * E1 - 1) hm bm [] (Some (am - 2 * E1)) ++ W_next) r) as [cfg0 [hpe0 hs2]].
  assert (hEnc : encS (2 * E1 - 1) hm bm [] (Some (am - 2 * E1)) ++ W_next =
                 ((((T2 ^^ (2 * (E1 - 1) + 1)) ++ T0) ++ (T2 ^^ (am - 2 * E1))) ++
                   (((if hm then T5 else []) ++ (T4 ^^ bm)) ++ W_next))).
  { unfold encS; cbn [encSegTail].
    replace (2 * (E1 - 1) + 1) with (2 * E1 - 1) by lia.
    rewrite ?app_nil_r, ?append_assoc. reflexivity. }
  rewrite hEnc in hpe0.
  destruct (p1Entry_enterMirror_direct (e := E2) (E1 - 1) (am - 2 * E1) ltac:(lia) hpe0)
    as [Lt [hpL hs3]].
  replace (E1 - 1 + 1) with E1 in hpL by lia.
  replace (2 * (E1 - 1) + 2) with (2 * E1) in hs3 by lia.
  exists Lt. split; [exact hpL |].
  assert (hW0 : ((W0 ++ encS am hm bm [] None) ++ W_next) *> r =
                (W0 ++ encS am hm bm [] None) *> W_next *> r) by (rewrite Str_app_assoc; reflexivity).
  assert (hW1 : (W1 ++ encS (2 * E1 - 1) hm bm [] (Some (am - 2 * E1))) *> W_next *> r =
                (W1 ++ (encS (2 * E1 - 1) hm bm [] (Some (am - 2 * E1)) ++ W_next)) *> r).
  { rewrite <- append_assoc, ?Str_app_assoc. reflexivity. }
  rewrite hW0.
  eapply evstep_trans; [exact hs1 |].
  rewrite hW1.
  exact (stepStar_trans hs2 hs3).
Qed.

Lemma mirror_norm_tail_even {W2 W_next : list Sym} {E1 E2 k b' : nat} {Lt : Stream Sym}
    {r : Stream Sym} (hE1 : E1 + 1 <= k) (hK : b' + 2 <= (k - E1) + (E2 - E1))
    (hp : PipeL (E2 - E1) W2 Lt) :
    exists Lt', PipeL1 ((k - E1) + (E2 - E1) - (b' + 1)) (W2 ++ encS (2 * k + 1) true b' [] None) Lt' /\
      (([S1; S1] *> T4 *> (T3 ^^ 3) *> (T2 ^^ (2 * (k - E1 - 1))) *> (T3 ^^ (2 * E1)) *> Lt) {{F}}>
        (((T4 ^^ b') ++ W_next) *> r))
        -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> (W_next *> r)).
Proof.
  pose proof (pipeL_mirror_noT2 0 3 (k - E1 - 1) (2 * E1) hp) as hp1.
  rewrite zPz, zLan, app_nil_r in hp1.
  destruct (pipeL_eat_t4 (En := E2 - E1 + (k - E1 - 1)) b' ltac:(lia) hp1 (W_next *> r))
    as [Lt' [hp2 hs]].
  exists Lt'. split.
  - split; [| intros; lia].
    replace (E2 - E1 + (k - E1 - 1) - b') with ((k - E1) + (E2 - E1) - (b' + 1)) in hp2 by lia.
    eapply pipeL_eqR; [| exact hp2].
    unfold encS; cbn [encSegTail].
    replace (3 + 2 * (k - E1 - 1) + 2 * E1) with (2 * k + 1) by lia.
    rewrite ?app_nil_r, ?append_assoc. reflexivity.
  - rewrite Str_app_assoc. exact hs.
Qed.

Lemma mirror_norm_tail_odd {W2 W_next : list Sym} {E1 E2 k b' : nat} {Lt : Stream Sym}
    {r : Stream Sym} (hE1 : E1 + 1 <= k) (hK : b' + 2 <= (k - E1) + (E2 - E1))
    (hp : PipeL (E2 - E1) W2 Lt) :
    exists Lt', PipeL1 ((k - E1) + (E2 - E1) - (b' + 1)) (W2 ++ encS (2 * k + 2) false (b' + 1) [] None) Lt' /\
      (([S1; S1] *> T4 *> (T3 ^^ 3) *> (T2 ^^ (2 * (k - E1 - 1) + 1)) *> (T3 ^^ (2 * E1)) *> Lt) {{F}}>
        (((T4 ^^ b') ++ W_next) *> r))
        -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> (W_next *> r)).
Proof.
  pose proof (pipeL_mirror_T2 0 3 (k - E1 - 1) (2 * E1) hp) as hp1.
  rewrite zPz, zLan in hp1.
  destruct (pipeL_eat_t4 (En := E2 - E1 + (k - E1 - 1)) b' ltac:(lia) hp1 (W_next *> r))
    as [Lt' [hp2 hs]].
  exists Lt'. split.
  - split; [| intros; lia].
    replace (E2 - E1 + (k - E1 - 1) - b') with ((k - E1) + (E2 - E1) - (b' + 1)) in hp2 by lia.
    eapply pipeL_eqR; [| exact hp2].
    unfold encS; cbn [encSegTail].
    replace (3 + 2 * (k - E1 - 1) + 2 * E1 + 1) with (2 * k + 2) by lia.
    rewrite ?app_nil_r, ?append_assoc; fold_pow_add.
    replace (0 + 1 + b') with (b' + 1) by lia. reflexivity.
  - rewrite Str_app_assoc. exact hs.
Qed.

Lemma mirror_norm_even_h1 {W0 W1 W2 : list Sym} {E1 E2 : nat} (k b' : nat)
    (d1 : DirectBlock W0 W1 E1) (d2 : DirectBlock W1 W2 E2)
    (hE1 : 1 <= E1) (hE12 : E1 <= E2) (hk : E1 + 1 <= k) (hK : b' + 2 <= (k - E1) + (E2 - E1)) :
    DirectBlock (W0 ++ encS (2 * k) true (b' + 1) [] None)
      (W2 ++ encS (2 * k + 1) true b' [] None) ((k - E1) + (E2 - E1) - (b' + 1)).
Proof.
  intros W_next r.
  destruct (directBlock_enterMirror (2 * k) true (b' + 1) (or_introl eq_refl)
              d1 d2 hE1 hE12 ltac:(lia) W_next r) as [Lt [hpL hs1]].
  destruct (mirror_norm_tail_even (W_next := W_next) (r := r) hk hK hpL) as [Lt' [hpL' hs_tail]].
  exists (([S1; S1] *> Lt') {{F}}> (W_next *> r)).
  split; [left; exists Lt'; split; [exact hpL' | reflexivity] |].
  eapply evstep_trans; [exact hs1 |].
  rewrite ?Str_app_assoc.
  eapply evstep_trans; [apply step_mirror_cap_t5 |].
  assert (haR1 : (T2 ^^ (2 * k - 2 * E1)) *> (T3 ^^ (2 * E1)) *> Lt =
                 T2 *> T2 *> (T2 ^^ (2 * (k - E1 - 1))) *> (T3 ^^ (2 * E1)) *> Lt).
  { replace (2 * k - 2 * E1) with (1 + (1 + 2 * (k - E1 - 1))) by lia.
    simp_pow_add; rewrite !zP1. reflexivity. }
  rewrite haR1.
  eapply evstep_trans; [apply step_t2L_eat_t2 |].
  assert (hb_split : (T4 ^^ (b' + 1)) *> W_next *> r = T4 *> (T4 ^^ b') *> W_next *> r).
  { replace (b' + 1) with (S b') by lia. rewrite zPsr. reflexivity. }
  rewrite hb_split.
  eapply evstep_trans; [exact (step_t3_t2_eat_t4 2 ((T2 ^^ (2 * (k - E1 - 1))) *> (T3 ^^ (2 * E1)) *> Lt)
                                 ((T4 ^^ b') *> W_next *> r)) |].
  rewrite Str_app_assoc in hs_tail. exact hs_tail.
Qed.

Lemma mirror_norm_odd_h1 {W0 W1 W2 : list Sym} {E1 E2 : nat} (k b' : nat)
    (d1 : DirectBlock W0 W1 E1) (d2 : DirectBlock W1 W2 E2)
    (hE1 : 1 <= E1) (hE12 : E1 <= E2) (hk : E1 + 1 <= k) (hK : b' + 2 <= (k - E1) + (E2 - E1)) :
    DirectBlock (W0 ++ encS (2 * k + 1) true (b' + 1) [] None)
      (W2 ++ encS (2 * k + 2) false (b' + 1) [] None) ((k - E1) + (E2 - E1) - (b' + 1)).
Proof.
  intros W_next r.
  destruct (directBlock_enterMirror (2 * k + 1) true (b' + 1) (or_introl eq_refl)
              d1 d2 hE1 hE12 ltac:(lia) W_next r) as [Lt [hpL hs1]].
  destruct (mirror_norm_tail_odd (W_next := W_next) (r := r) hk hK hpL) as [Lt' [hpL' hs_tail]].
  exists (([S1; S1] *> Lt') {{F}}> (W_next *> r)).
  split; [left; exists Lt'; split; [exact hpL' | reflexivity] |].
  eapply evstep_trans; [exact hs1 |].
  rewrite ?Str_app_assoc.
  eapply evstep_trans; [apply step_mirror_cap_t5 |].
  assert (haR1 : (T2 ^^ (2 * k + 1 - 2 * E1)) *> (T3 ^^ (2 * E1)) *> Lt =
                 T2 *> T2 *> (T2 ^^ (2 * (k - E1 - 1) + 1)) *> (T3 ^^ (2 * E1)) *> Lt).
  { replace (2 * k + 1 - 2 * E1) with (1 + (1 + (2 * (k - E1 - 1) + 1))) by lia.
    simp_pow_add; rewrite !zP1. reflexivity. }
  rewrite haR1.
  eapply evstep_trans; [apply step_t2L_eat_t2 |].
  assert (hb_split : (T4 ^^ (b' + 1)) *> W_next *> r = T4 *> (T4 ^^ b') *> W_next *> r).
  { replace (b' + 1) with (S b') by lia. rewrite zPsr. reflexivity. }
  rewrite hb_split.
  eapply evstep_trans; [exact (step_t3_t2_eat_t4 2 ((T2 ^^ (2 * (k - E1 - 1) + 1)) *> (T3 ^^ (2 * E1)) *> Lt)
                                 ((T4 ^^ b') *> W_next *> r)) |].
  rewrite Str_app_assoc in hs_tail. exact hs_tail.
Qed.

Lemma mirror_norm_even_h0 {W0 W1 W2 : list Sym} {E1 E2 : nat} (k b' : nat)
    (d1 : DirectBlock W0 W1 E1) (d2 : DirectBlock W1 W2 E2)
    (hE1 : 1 <= E1) (hE12 : E1 <= E2) (hk : E1 + 1 <= k) (hK : b' + 2 <= (k - E1) + (E2 - E1)) :
    DirectBlock (W0 ++ encS (2 * k) false (b' + 2) [] None)
      (W2 ++ encS (2 * k + 1) true b' [] None) ((k - E1) + (E2 - E1) - (b' + 1)).
Proof.
  intros W_next r.
  destruct (directBlock_enterMirror (2 * k) false (b' + 2) ltac:(right; lia)
              d1 d2 hE1 hE12 ltac:(lia) W_next r) as [Lt [hpL hs1]].
  destruct (mirror_norm_tail_even (W_next := W_next) (r := r) hk hK hpL) as [Lt' [hpL' hs_tail]].
  exists (([S1; S1] *> Lt') {{F}}> (W_next *> r)).
  split; [left; exists Lt'; split; [exact hpL' | reflexivity] |].
  eapply evstep_trans; [exact hs1 |].
  rewrite ?app_nil_l, ?Str_app_assoc.
  assert (haR1 : (T2 ^^ (2 * k - 2 * E1)) *> (T3 ^^ (2 * E1)) *> Lt =
                 T2 *> T2 *> (T2 ^^ (2 * (k - E1 - 1))) *> (T3 ^^ (2 * E1)) *> Lt).
  { replace (2 * k - 2 * E1) with (1 + (1 + 2 * (k - E1 - 1))) by lia.
    simp_pow_add; rewrite !zP1. reflexivity. }
  assert (hb2 : (T4 ^^ (b' + 2)) *> W_next *> r = T4 *> T4 *> (T4 ^^ b') *> W_next *> r).
  { replace (b' + 2) with (1 + (1 + b')) by lia.
    simp_pow_add; rewrite !zP1. reflexivity. }
  rewrite haR1, hb2.
  eapply evstep_trans; [apply step_mirror_t2_t2_t4 |].
  eapply evstep_trans; [apply step_q1_t4_to_q5 |].
  rewrite Str_app_assoc in hs_tail. exact hs_tail.
Qed.

Lemma mirror_norm_odd_h0 {W0 W1 W2 : list Sym} {E1 E2 : nat} (k b' : nat)
    (d1 : DirectBlock W0 W1 E1) (d2 : DirectBlock W1 W2 E2)
    (hE1 : 1 <= E1) (hE12 : E1 <= E2) (hk : E1 + 1 <= k) (hK : b' + 2 <= (k - E1) + (E2 - E1)) :
    DirectBlock (W0 ++ encS (2 * k + 1) false (b' + 2) [] None)
      (W2 ++ encS (2 * k + 2) false (b' + 1) [] None) ((k - E1) + (E2 - E1) - (b' + 1)).
Proof.
  intros W_next r.
  destruct (directBlock_enterMirror (2 * k + 1) false (b' + 2) ltac:(right; lia)
              d1 d2 hE1 hE12 ltac:(lia) W_next r) as [Lt [hpL hs1]].
  destruct (mirror_norm_tail_odd (W_next := W_next) (r := r) hk hK hpL) as [Lt' [hpL' hs_tail]].
  exists (([S1; S1] *> Lt') {{F}}> (W_next *> r)).
  split; [left; exists Lt'; split; [exact hpL' | reflexivity] |].
  eapply evstep_trans; [exact hs1 |].
  rewrite ?app_nil_l, ?Str_app_assoc.
  assert (haR1 : (T2 ^^ (2 * k + 1 - 2 * E1)) *> (T3 ^^ (2 * E1)) *> Lt =
                 T2 *> T2 *> (T2 ^^ (2 * (k - E1 - 1) + 1)) *> (T3 ^^ (2 * E1)) *> Lt).
  { replace (2 * k + 1 - 2 * E1) with (1 + (1 + (2 * (k - E1 - 1) + 1))) by lia.
    simp_pow_add; rewrite !zP1. reflexivity. }
  assert (hb2 : (T4 ^^ (b' + 2)) *> W_next *> r = T4 *> T4 *> (T4 ^^ b') *> W_next *> r).
  { replace (b' + 2) with (1 + (1 + b')) by lia.
    simp_pow_add; rewrite !zP1. reflexivity. }
