Lemma mirror_eat_core_h0 {W2 W_next : list Sym} {e_m K_t3 Qv A_cnt Nv b2' : nat}
    {Lt : Stream Sym} {r : Stream Sym}
    (hQ : Nv / 2 + 1 <= Qv) (hE : b2' + 2 <= e_m + (Qv - Nv / 2)) (hp : PipeL e_m W2 Lt) :
    exists Lt', PipeL1 (e_m + (Qv - Nv / 2) - (b2' + 1))
        (W2 ++ encS (K_t3 + Nv + 2 * Qv + A_cnt) (Nat.eqb (Nv mod 2) 1)
                 (if Nat.eqb (Nv mod 2) 1 then b2' else b2' + 1) [] None) Lt' /\
      (([S1; S1] *> (T3 ^^ K_t3) *> (T2 ^^ (2 * Qv)) *> (T3 ^^ A_cnt) *> Lt) {{F}}>
        ((((T2 ^^ Nv) ++ (T4 ^^ (b2' + 1))) ++ W_next) *> r))
        -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> (W_next *> r)).
Proof.
  assert (hsplit : 2 * Qv = Nv + (1 + (2 * Qv - Nv - 1))) by lia.
  assert (hT2_split : forall s, (T2 ^^ (2 * Qv)) *> s = (T2 ^^ Nv) *> (T2 ^^ (1 + (2 * Qv - Nv - 1))) *> s)
    by (intros s; symmetry; rewrite <- pow_add_blank, <- hsplit; reflexivity).
  rewrite hT2_split, ?Str_app_assoc.
  pose proof (rule_t3_t2_eat_t2 Nv K_t3 ((T2 ^^ (1 + (2 * Qv - Nv - 1))) *> (T3 ^^ A_cnt) *> Lt)
                ((T4 ^^ (b2' + 1)) *> W_next *> r)) as hs1.
  assert (hs2 : (([S1; S1] *> (T3 ^^ (K_t3 + 2 * Nv)) *> (T2 ^^ (1 + (2 * Qv - Nv - 1))) *> (T3 ^^ A_cnt) *> Lt) {{F}}>
                  ((T4 ^^ (b2' + 1)) *> W_next *> r))
                -[ tm ]->*
                (([S1; S1] *> T4 *> (T3 ^^ (K_t3 + 2 * Nv + 1)) *> (T2 ^^ (2 * Qv - Nv - 1)) *> (T3 ^^ A_cnt) *> Lt) {{F}}>
                  ((T4 ^^ b2') *> W_next *> r))).
  { rewrite (zPsr T2 (2 * Qv - Nv - 1)).
    replace (b2' + 1) with (S b2') by lia; rewrite zPsr.
    exact (step_t3_t2_eat_t4 (K_t3 + 2 * Nv) ((T2 ^^ (2 * Qv - Nv - 1)) *> (T3 ^^ A_cnt) *> Lt)
             ((T4 ^^ b2') *> W_next *> r)). }
  pose proof (Nat.div_mod Nv 2 ltac:(lia)) as hdm.
  pose proof (Nat.mod_upper_bound Nv 2 ltac:(lia)) as hmu.
  set (n := Nv / 2) in *.
  assert (hpar : Nv = 2 * n \/ Nv = 2 * n + 1) by lia.
  destruct hpar as [hpar | hpar].
  - assert (hrem : 2 * Qv - Nv - 1 = 2 * (Qv - n - 1) + 1) by lia.
    pose proof (pipeL_mirror_T2 0 (K_t3 + 2 * Nv + 1) (Qv - n - 1) A_cnt hp) as hp1.
    rewrite zPz, zLan in hp1.
    destruct (pipeL_eat_t4 (En := e_m + (Qv - n - 1)) b2' ltac:(lia) hp1 (W_next *> r))
      as [Lt' [hp2 hs3]].
    assert (hmod : Nat.eqb (Nv mod 2) 1 = false) by (apply Nat.eqb_neq; lia).
    exists Lt'. split.
    + split; [| intros; lia].
      replace (e_m + (Qv - n - 1) - b2') with (e_m + (Qv - n) - (b2' + 1)) in hp2 by lia.
      eapply pipeL_eqR; [| exact hp2].
      rewrite hmod; unfold encS; cbn [encSegTail].
      replace ((K_t3 + 2 * Nv + 1) + 2 * (Qv - n - 1) + A_cnt + 1) with (K_t3 + Nv + 2 * Qv + A_cnt) by lia.
      rewrite ?app_nil_r, ?append_assoc; fold_pow_add.
      replace (0 + 1 + b2') with (b2' + 1) by lia. reflexivity.
    + rewrite <- hrem in hs3.
      exact (stepStar_trans hs1 (stepStar_trans hs2 hs3)).
  - assert (hrem : 2 * Qv - Nv - 1 = 2 * (Qv - n - 1)) by lia.
    pose proof (pipeL_mirror_noT2 0 (K_t3 + 2 * Nv + 1) (Qv - n - 1) A_cnt hp) as hp1.
    rewrite zPz, zLan, app_nil_r in hp1.
    destruct (pipeL_eat_t4 (En := e_m + (Qv - n - 1)) b2' ltac:(lia) hp1 (W_next *> r))
      as [Lt' [hp2 hs3]].
    assert (hmod : Nat.eqb (Nv mod 2) 1 = true) by (apply Nat.eqb_eq; lia).
    exists Lt'. split.
    + split; [| intros; lia].
      replace (e_m + (Qv - n - 1) - b2') with (e_m + (Qv - n) - (b2' + 1)) in hp2 by lia.
      eapply pipeL_eqR; [| exact hp2].
      rewrite hmod; unfold encS; cbn [encSegTail].
      replace ((K_t3 + 2 * Nv + 1) + 2 * (Qv - n - 1) + A_cnt) with (K_t3 + Nv + 2 * Qv + A_cnt) by lia.
      rewrite ?app_nil_r, ?append_assoc. reflexivity.
    + rewrite <- hrem in hs3.
      exact (stepStar_trans hs1 (stepStar_trans hs2 hs3)).
Qed.

Lemma mirror_eat_core_h1 {W2 : list Sym} {e_m K_t3 Qv A_cnt Nv b2' : nat}
    {Lt : Stream Sym} {r : Stream Sym}
    (hQ : Nv / 2 + 1 <= Qv) (hp : PipeL e_m W2 Lt) :
    exists Lt', PipeL (e_m + (Qv - Nv / 2) - 1)
        (W2 ++ encS (K_t3 + Nv + 2 * Qv + A_cnt + 1) (Nat.eqb (Nv mod 2) 1)
                 (if Nat.eqb (Nv mod 2) 1 then b2' else b2' + 1) [] None) Lt' /\
      (([S1; S1] *> (T3 ^^ K_t3) *> (T2 ^^ (2 * Qv)) *> (T3 ^^ A_cnt) *> Lt) {{F}}>
        ((((T2 ^^ Nv) ++ T5) ++ (T4 ^^ (b2' + 1))) *> r))
        -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  assert (hsplit : 2 * Qv = Nv + (1 + (2 * Qv - Nv - 1))) by lia.
  assert (hT2_split : forall s, (T2 ^^ (2 * Qv)) *> s = (T2 ^^ Nv) *> (T2 ^^ (1 + (2 * Qv - Nv - 1))) *> s)
    by (intros s; symmetry; rewrite <- pow_add_blank, <- hsplit; reflexivity).
  rewrite hT2_split, ?Str_app_assoc.
  pose proof (rule_t3_t2_eat_t2 Nv K_t3 ((T2 ^^ (1 + (2 * Qv - Nv - 1))) *> (T3 ^^ A_cnt) *> Lt)
                (T5 *> (T4 ^^ (b2' + 1)) *> r)) as hs1.
  assert (hs2 : (([S1; S1] *> (T3 ^^ (K_t3 + 2 * Nv)) *> (T2 ^^ (1 + (2 * Qv - Nv - 1))) *> (T3 ^^ A_cnt) *> Lt) {{F}}>
                  (T5 *> (T4 ^^ (b2' + 1)) *> r))
                -[ tm ]->*
                (([S1] *> (T3 ^^ (K_t3 + 2 * Nv + 3)) *> (T2 ^^ (2 * Qv - Nv - 1)) *> (T3 ^^ A_cnt) *> Lt) {{A}}>
                  ((T4 ^^ (b2' + 1)) *> r))).
  { rewrite (zPsr T2 (2 * Qv - Nv - 1)).
    exact (step_t3_t2_eat_t5 (K_t3 + 2 * Nv) ((T2 ^^ (2 * Qv - Nv - 1)) *> (T3 ^^ A_cnt) *> Lt)
             ((T4 ^^ (b2' + 1)) *> r)). }
  assert (hs3 : (([S1] *> (T3 ^^ (K_t3 + 2 * Nv + 3)) *> (T2 ^^ (2 * Qv - Nv - 1)) *> (T3 ^^ A_cnt) *> Lt) {{A}}>
                  ((T4 ^^ (b2' + 1)) *> r))
                -[ tm ]->*
                (([S1] *> T2 *> (T5 ^^ b2') *> T4 *> (T3 ^^ (K_t3 + 2 * Nv + 2)) *> (T2 ^^ (2 * Qv - Nv - 1)) *> (T3 ^^ A_cnt) *> Lt) {{A}}> r)).
  { replace (K_t3 + 2 * Nv + 3) with (S (K_t3 + 2 * Nv + 2)) by lia.
    replace (b2' + 1) with (S b2') by lia.
    rewrite !zPsr.
    eapply evstep_trans; [apply step_q0_t4_first | apply rule_q0_t4_next]. }
  pose proof (Nat.div_mod Nv 2 ltac:(lia)) as hdm.
  pose proof (Nat.mod_upper_bound Nv 2 ltac:(lia)) as hmu.
  set (n := Nv / 2) in *.
  assert (hpar : Nv = 2 * n \/ Nv = 2 * n + 1) by lia.
  destruct hpar as [hpar | hpar].
  - assert (hrem : 2 * Qv - Nv - 1 = 2 * (Qv - n - 1) + 1) by lia.
    pose proof (pipeL_mirror_T2 b2' (K_t3 + 2 * Nv + 2) (Qv - n - 1) A_cnt hp) as hp1.
    assert (hmod : Nat.eqb (Nv mod 2) 1 = false) by (apply Nat.eqb_neq; lia).
    exists ((T5 ^^ b2') *> T4 *> (T3 ^^ (K_t3 + 2 * Nv + 2)) *> (T2 ^^ (2 * (Qv - n - 1) + 1)) *> (T3 ^^ A_cnt) *> Lt).
    split.
    + replace (e_m + (Qv - n - 1)) with (e_m + (Qv - n) - 1) in hp1 by lia.
      eapply pipeL_eqR; [| exact hp1].
      rewrite hmod; unfold encS; cbn [encSegTail].
      replace ((K_t3 + 2 * Nv + 2) + 2 * (Qv - n - 1) + A_cnt + 1) with (K_t3 + Nv + 2 * Qv + A_cnt + 1) by lia.
      rewrite ?app_nil_r, ?append_assoc. reflexivity.
    + rewrite <- hrem.
      exact (stepStar_trans hs1 (stepStar_trans hs2 hs3)).
  - assert (hrem : 2 * Qv - Nv - 1 = 2 * (Qv - n - 1)) by lia.
    pose proof (pipeL_mirror_noT2 b2' (K_t3 + 2 * Nv + 2) (Qv - n - 1) A_cnt hp) as hp1.
    assert (hmod : Nat.eqb (Nv mod 2) 1 = true) by (apply Nat.eqb_eq; lia).
    exists ((T5 ^^ b2') *> T4 *> (T3 ^^ (K_t3 + 2 * Nv + 2)) *> (T2 ^^ (2 * (Qv - n - 1))) *> (T3 ^^ A_cnt) *> Lt).
    split.
    + replace (e_m + (Qv - n - 1)) with (e_m + (Qv - n) - 1) in hp1 by lia.
      eapply pipeL_eqR; [| exact hp1].
      rewrite hmod; unfold encS; cbn [encSegTail].
      replace ((K_t3 + 2 * Nv + 2) + 2 * (Qv - n - 1) + A_cnt) with (K_t3 + Nv + 2 * Qv + A_cnt + 1) by lia.
      rewrite ?app_nil_r, ?append_assoc. reflexivity.
    + rewrite <- hrem.
      exact (stepStar_trans hs1 (stepStar_trans hs2 hs3)).
Qed.

Lemma mirror_eat_odd_b0_h0 {W0 W1 W2 : list Sym} {E1 E2 : nat} (k a2 b2' : nat)
    (d1 : DirectBlock W0 W1 E1) (d2 : DirectBlock W1 W2 E2)
    (hE1 : 1 <= E1) (hE12 : E1 <= E2) (hQ : a2 / 2 + 1 <= k - E1)
    (hK : a2 / 2 + b2' + 2 <= (k - E1) + (E2 - E1)) :
    DirectBlock ((W0 ++ encS (2 * k + 1) true 0 [] None) ++ encS a2 false (b2' + 1) [] None)
      (W2 ++ encS (2 * k + 2 + a2) (Nat.eqb (a2 mod 2) 1)
               (if Nat.eqb (a2 mod 2) 1 then b2' else b2' + 1) [] None)
      ((k - E1) + (E2 - E1) - (a2 / 2 + b2' + 1)).
Proof.
  intros W_next r.
  destruct (directBlock_enterMirror (2 * k + 1) true 0 (or_introl eq_refl)
              d1 d2 hE1 hE12 ltac:(lia) (encS a2 false (b2' + 1) [] None ++ W_next) r)
    as [Lt [hpL hs1]].
  destruct (mirror_eat_core_h0 (W2 := W2) (W_next := W_next) (r := r) (e_m := E2 - E1)
              (K_t3 := 2) (Qv := k - E1) (A_cnt := 2 * E1) (Nv := a2) (b2' := b2')
              hQ ltac:(lia) hpL) as [Lt' [hpL' hs_core]].
  replace (E2 - E1 + (k - E1 - a2 / 2) - (b2' + 1))
    with ((k - E1) + (E2 - E1) - (a2 / 2 + b2' + 1)) in hpL' by lia.
  replace (2 + a2 + 2 * (k - E1) + 2 * E1) with (2 * k + 2 + a2) in hpL' by lia.
  exists (([S1; S1] *> Lt') {{F}}> (W_next *> r)).
  split; [left; exists Lt'; split; [exact hpL' | reflexivity] |].
  rewrite ?append_assoc in hs1; rewrite ?append_assoc.
  eapply evstep_trans; [exact hs1 |].
  unfold encS; cbn [encSegTail].
  rewrite list_pow_zero, ?app_nil_r, ?app_nil_l, ?Str_app_assoc.
  eapply evstep_trans; [apply step_mirror_cap_t5 |].
  assert (hT2 : (T2 ^^ (2 * k + 1 - 2 * E1)) *> (T3 ^^ (2 * E1)) *> Lt =
                T2 *> (T2 ^^ (2 * (k - E1))) *> (T3 ^^ (2 * E1)) *> Lt).
  { replace (2 * k + 1 - 2 * E1) with (1 + 2 * (k - E1)) by lia.
    rewrite pow_add_blank, zP1. reflexivity. }
  rewrite hT2.
  eapply evstep_trans; [apply step_t2L_eat_t2 |].
  rewrite ?Str_app_assoc in hs_core. exact hs_core.
Qed.

Lemma mirror_eat_odd_b0_h1 {W0 W1 W2 : list Sym} {E1 E2 : nat} (k a2 b2' : nat)
    (d1 : DirectBlock W0 W1 E1) (d2 : DirectBlock W1 W2 E2)
    (hE1 : 1 <= E1) (hE12 : E1 <= E2) (hQ : a2 / 2 + 1 <= k - E1) :
    PureP2W ((W0 ++ encS (2 * k + 1) true 0 [] None) ++ encS a2 true (b2' + 1) [] None)
      (W2 ++ encS (2 * k + 3 + a2) (Nat.eqb (a2 mod 2) 1)
               (if Nat.eqb (a2 mod 2) 1 then b2' else b2' + 1) [] None)
      [(k - E1) + (E2 - E1) - a2 / 2].
Proof.
  eapply PureP2W_cons; [| exact (PureP2W_nil _)].
  split; [lia | intros r].
  destruct (directBlock_enterMirror (2 * k + 1) true 0 (or_introl eq_refl)
              d1 d2 hE1 hE12 ltac:(lia) (encS a2 true (b2' + 1) [] None) r)
    as [Lt [hpL hs1]].
  destruct (mirror_eat_core_h1 (W2 := W2) (r := r)
              (K_t3 := 2) (Qv := k - E1) (A_cnt := 2 * E1) (Nv := a2) (b2' := b2')
              hQ hpL) as [Lt' [hpL' hs_core]].
  exists Lt'. split.
  - replace (E2 - E1 + (k - E1 - a2 / 2) - 1)
      with ((k - E1) + (E2 - E1) - a2 / 2 - 1) in hpL' by lia.
    replace (2 + a2 + 2 * (k - E1) + 2 * E1 + 1) with (2 * k + 3 + a2) in hpL' by lia.
    exact hpL'.
  - eapply evstep_trans; [exact hs1 |].
    unfold encS; cbn [encSegTail].
    rewrite list_pow_zero, ?app_nil_r, ?Str_app_assoc.
    eapply evstep_trans; [apply step_mirror_cap_t5 |].
    assert (hT2 : (T2 ^^ (2 * k + 1 - 2 * E1)) *> (T3 ^^ (2 * E1)) *> Lt =
                  T2 *> (T2 ^^ (2 * (k - E1))) *> (T3 ^^ (2 * E1)) *> Lt).
    { replace (2 * k + 1 - 2 * E1) with (1 + 2 * (k - E1)) by lia.
      rewrite pow_add_blank, zP1. reflexivity. }
    rewrite hT2.
    eapply evstep_trans; [apply step_t2L_eat_t2 |].
    rewrite ?Str_app_assoc in hs_core. exact hs_core.
Qed.

Lemma mirror_eat_even_b1_h0 {W0 W1 W2 : list Sym} {E1 E2 : nat} (k a2' b2' : nat)
    (d1 : DirectBlock W0 W1 E1) (d2 : DirectBlock W1 W2 E2)
    (hE1 : 1 <= E1) (hE12 : E1 <= E2) (hQ : a2' / 2 + 2 <= k - E1)
    (hK : a2' / 2 + b2' + 3 <= (k - E1) + (E2 - E1)) :
    DirectBlock ((W0 ++ encS (2 * k) false 1 [] None) ++ encS (a2' + 1) false (b2' + 1) [] None)
      (W2 ++ encS (2 * k + 2 + a2') (Nat.eqb (a2' mod 2) 1)
               (if Nat.eqb (a2' mod 2) 1 then b2' else b2' + 1) [] None)
      ((k - E1) + (E2 - E1) - (a2' / 2 + b2' + 2)).
Proof.
  intros W_next r.
  destruct (directBlock_enterMirror (2 * k) false 1 ltac:(right; lia)
              d1 d2 hE1 hE12 ltac:(lia) (encS (a2' + 1) false (b2' + 1) [] None ++ W_next) r)
    as [Lt [hpL hs1]].
  destruct (mirror_eat_core_h0 (W2 := W2) (W_next := W_next) (r := r) (e_m := E2 - E1)
              (K_t3 := 4) (Qv := k - E1 - 1) (A_cnt := 2 * E1) (Nv := a2') (b2' := b2')
              ltac:(lia) ltac:(lia) hpL) as [Lt' [hpL' hs_core]].
  replace (E2 - E1 + (k - E1 - 1 - a2' / 2) - (b2' + 1))
    with ((k - E1) + (E2 - E1) - (a2' / 2 + b2' + 2)) in hpL' by lia.
  replace (4 + a2' + 2 * (k - E1 - 1) + 2 * E1) with (2 * k + 2 + a2') in hpL' by lia.
  exists (([S1; S1] *> Lt') {{F}}> (W_next *> r)).
  split; [left; exists Lt'; split; [exact hpL' | reflexivity] |].
  rewrite ?append_assoc in hs1; rewrite ?append_assoc.
  eapply evstep_trans; [exact hs1 |].
  unfold encS; cbn [encSegTail].
  rewrite list_pow_one, ?app_nil_r, ?app_nil_l, ?Str_app_assoc.
  assert (hT2 : (T2 ^^ (2 * k - 2 * E1)) *> (T3 ^^ (2 * E1)) *> Lt =
                T2 *> T2 *> (T2 ^^ (2 * (k - E1 - 1))) *> (T3 ^^ (2 * E1)) *> Lt).
  { replace (2 * k - 2 * E1) with (1 + (1 + 2 * (k - E1 - 1))) by lia.
    simp_pow_add; rewrite !zP1. reflexivity. }
  rewrite hT2.
  eapply evstep_trans; [apply step_mirror_t2_t2_t4 |].
  replace (a2' + 1) with (S a2') by lia; rewrite (zPsr T2 a2').
  eapply evstep_trans; [apply step_q1_t2_to_q5 |].
  change (T3 *> (T3 ^^ 3) *> (T2 ^^ (2 * (k - E1 - 1))) *> (T3 ^^ (2 * E1)) *> Lt)
    with ((T3 ^^ 4) *> (T2 ^^ (2 * (k - E1 - 1))) *> (T3 ^^ (2 * E1)) *> Lt).
  rewrite ?Str_app_assoc in hs_core. exact hs_core.
Qed.

Lemma mirror_eat_even_b1_h1 {W0 W1 W2 : list Sym} {E1 E2 : nat} (k a2' b2' : nat)
    (d1 : DirectBlock W0 W1 E1) (d2 : DirectBlock W1 W2 E2)
    (hE1 : 1 <= E1) (hE12 : E1 <= E2) (hQ : a2' / 2 + 2 <= k - E1) :
    PureP2W ((W0 ++ encS (2 * k) false 1 [] None) ++ encS (a2' + 1) true (b2' + 1) [] None)
      (W2 ++ encS (2 * k + 3 + a2') (Nat.eqb (a2' mod 2) 1)
               (if Nat.eqb (a2' mod 2) 1 then b2' else b2' + 1) [] None)
      [(k - E1) + (E2 - E1) - (a2' / 2 + 1)].
Proof.
  eapply PureP2W_cons; [| exact (PureP2W_nil _)].
  split; [lia | intros r].
  destruct (directBlock_enterMirror (2 * k) false 1 ltac:(right; lia)
              d1 d2 hE1 hE12 ltac:(lia) (encS (a2' + 1) true (b2' + 1) [] None) r)
    as [Lt [hpL hs1]].
  destruct (mirror_eat_core_h1 (W2 := W2) (r := r)
              (K_t3 := 4) (Qv := k - E1 - 1) (A_cnt := 2 * E1) (Nv := a2') (b2' := b2')
              ltac:(lia) hpL) as [Lt' [hpL' hs_core]].
  exists Lt'. split.
  - replace (E2 - E1 + (k - E1 - 1 - a2' / 2) - 1)
      with ((k - E1) + (E2 - E1) - (a2' / 2 + 1) - 1) in hpL' by lia.
    replace (4 + a2' + 2 * (k - E1 - 1) + 2 * E1 + 1) with (2 * k + 3 + a2') in hpL' by lia.
    exact hpL'.
  - eapply evstep_trans; [exact hs1 |].
    unfold encS; cbn [encSegTail].
    rewrite list_pow_one, ?app_nil_r, ?app_nil_l, ?Str_app_assoc.
    assert (hT2 : (T2 ^^ (2 * k - 2 * E1)) *> (T3 ^^ (2 * E1)) *> Lt =
                  T2 *> T2 *> (T2 ^^ (2 * (k - E1 - 1))) *> (T3 ^^ (2 * E1)) *> Lt).
    { replace (2 * k - 2 * E1) with (1 + (1 + 2 * (k - E1 - 1))) by lia.
      simp_pow_add; rewrite !zP1. reflexivity. }
    rewrite hT2.
    eapply evstep_trans; [apply step_mirror_t2_t2_t4 |].
    replace (a2' + 1) with (S a2') by lia; rewrite (zPsr T2 a2').
    eapply evstep_trans; [apply step_q1_t2_to_q5 |].
    change (T3 *> (T3 ^^ 3) *> (T2 ^^ (2 * (k - E1 - 1))) *> (T3 ^^ (2 * E1)) *> Lt)
      with ((T3 ^^ 4) *> (T2 ^^ (2 * (k - E1 - 1))) *> (T3 ^^ (2 * E1)) *> Lt).
    rewrite ?Str_app_assoc in hs_core. exact hs_core.
Qed.

