Lemma c0_sp0_2hubs (m0 b0_v : nat) (sp0 : list RleItem) (hsp0 : isTranspList sp0 = true)
    (hb0 : 5 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + 1 <= m0) :
    exists Wm,
      DirectBlock (encS (2 * m0) true b0_v [] None ++ encItems sp0) Wm (m0 - b0_v - transpListCost_nat sp0) /\
      DirectBlock Wm (encS (2 * (m0 + 3)) true (b0_v - 2) [] None ++ encItems sp0)
        (m0 - b0_v - transpListCost_nat sp0 + 3).
Proof.
  pose proof (c0_directBlock_2 m0 b0_v hb0 ltac:(lia)) as h2.
  destruct (DirectBlockList_uncons h2) as [Wm0 [d1 h2']].
  destruct (DirectBlockList_uncons h2') as [Wm1 [d2 h2'']].
  rewrite (DirectBlockList_nil_eq h2'') in d2.
  pose proof (DirectBlock_liftTranspList sp0 hsp0 d1 ltac:(lia)) as l1.
  pose proof (DirectBlock_liftTranspList sp0 hsp0 d2 ltac:(lia)) as l2.
  replace (m0 - b0_v + 3 - transpListCost_nat sp0)
    with (m0 - b0_v - transpListCost_nat sp0 + 3) in l2 by lia.
  exists (Wm0 ++ encItems sp0). split; [exact l1 | exact l2].
Qed.

Lemma mirror_eater_2pair (m0 b0_v k bm minE : nat) (sp0 : list RleItem)
    (hsp0 : isTranspList sp0 = true) (hb0 : 7 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + 1 <= m0)
    (hbm : 2 <= bm) (hgap : bm + minE + 5 <= k - (m0 - b0_v - transpListCost_nat sp0))
    (hle_k : m0 - b0_v - transpListCost_nat sp0 + 6 <= k) :
    let gap := k - (m0 - b0_v - transpListCost_nat sp0) in
    BlockListMin minE
      ((encS (2 * m0) true b0_v [] None ++ encItems sp0) ++ encS (2 * k + 1) true bm [] None)
      ((encS (2 * (m0 + 6)) true (b0_v - 4) [] None ++ encItems sp0) ++ encS (2 * (k + 1) + 1) true (bm - 2) [] None)
      [gap + 3 - bm; gap - bm].
Proof.
  cbv zeta.
  set (c0s := transpListCost_nat sp0) in *.
  set (E0 := m0 - b0_v - c0s) in *.
  set (gap := k - E0) in *.
  destruct (c0_sp0_2hubs m0 b0_v sp0 hsp0 ltac:(lia) ltac:(lia)) as [Wm1 [d1 d2]].
  destruct (c0_sp0_2hubs (m0 + 3) (b0_v - 2) sp0 hsp0 ltac:(lia) ltac:(lia)) as [Wm2 [d3 d4]].
  fold c0s in d1, d2, d3, d4; fold E0 in d1, d2.
  replace ((m0 + 3) - (b0_v - 2) - c0s) with (E0 + 5) in d3, d4 by lia.
  replace (m0 + 3 + 3) with (m0 + 6) in d4 by lia.
  replace (b0_v - 2 - 2) with (b0_v - 4) in d4 by lia.
  set (b' := bm - 2).
  assert (hbm_eq : bm = b' + 2) by (unfold b'; lia).
  rewrite hbm_eq.
  pose proof (mirror_norm_odd_h1 k (b' + 1) d1 d2 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) as hcar1.
  pose proof (mirror_norm_even_h0 (k + 1) b' d3 d4 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) as hcar2.
  replace (b' + 1 + 1) with (b' + 2) in hcar1 by lia.
  replace (2 * k + 2) with (2 * (k + 1)) in hcar1 by lia.
  replace (k - E0 + (E0 + 3 - E0) - (b' + 2)) with (gap + 3 - (b' + 2)) in hcar1 by lia.
  replace (k + 1 - (E0 + 5) + (E0 + 5 + 3 - (E0 + 5)) - (b' + 1)) with (gap - (b' + 2)) in hcar2 by lia.
  replace (b' + 2 - 2) with b' by lia.
  pose proof (OneBlock_toWeak (DirectBlock_toOneBlock hcar1)) as hw1.
  pose proof (OneBlock_toWeak (DirectBlock_toOneBlock hcar2)) as hw2.
  replace [gap + 3 - (b' + 2); gap - (b' + 2)]
    with (((gap + 3 - (b' + 2)) + sumList []) :: ((gap - (b' + 2)) + sumList []) :: [])
    by (cbn [sumList]; rewrite !Nat.add_0_r; reflexivity).
  exact (BlockListMin_cons minE hw1 ltac:(lia)
           (BlockListMin_cons minE hw2 ltac:(lia) (BlockListMin_nil minE _))).
Qed.

Lemma mirror_eater_npairs (n : nat) :
    forall (m0 b0_v k bm minE : nat) (sp0 : list RleItem)
    (hsp0 : isTranspList sp0 = true)
    (hb0 : 4 * n + 3 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + 1 <= m0)
    (hbm : 2 * n <= bm)
    (hgap : bm + minE + 9 * n <= k - (m0 - b0_v - transpListCost_nat sp0))
    (hle_k : m0 - b0_v - transpListCost_nat sp0 + 9 * n + 2 <= k),
    exists bs,
      BlockListMin minE
        ((encS (2 * m0) true b0_v [] None ++ encItems sp0) ++ encS (2 * k + 1) true bm [] None)
        ((encS (2 * (m0 + 6 * n)) true (b0_v - 4 * n) [] None ++ encItems sp0)
          ++ encS (2 * (k + n) + 1) true (bm - 2 * n) [] None)
        bs /\
      List.length bs = 2 * n /\
      sumList bs + 2 * n * bm + 7 * n * (n - 1) =
        2 * n * (k - (m0 - b0_v - transpListCost_nat sp0)) + 3 * n.
Proof.
  induction n as [|n' IH]; intros m0 b0_v k bm minE sp0 hsp0 hb0 hle0 hbm hgap hle_k.
  - exists (@nil nat).
    replace (m0 + 6 * 0) with m0 by lia.
    replace (b0_v - 4 * 0) with b0_v by lia.
    replace (k + 0) with k by lia.
    replace (bm - 2 * 0) with bm by lia.
    split; [exact (BlockListMin_nil _ _) | simpl; lia].
  - pose proof (mirror_eater_2pair m0 b0_v k bm minE sp0 hsp0 ltac:(lia) hle0 ltac:(lia) ltac:(lia) ltac:(lia)) as hpair.
    cbv zeta in hpair.
    destruct (IH (m0 + 6) (b0_v - 4) (k + 1) (bm - 2) minE sp0 hsp0
                ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia))
      as [bs' [hbl' [hlen' hsum']]].
    replace (m0 + 6 + 6 * n') with (m0 + 6 * S n') in hbl' by (clear; lia).
    replace (b0_v - 4 - 4 * n') with (b0_v - 4 * S n') in hbl' by (clear - hb0; lia).
    replace (k + 1 + n') with (k + S n') in hbl' by (clear; lia).
    replace (bm - 2 - 2 * n') with (bm - 2 * S n') in hbl' by (clear - hbm; lia).
    set (G := k - (m0 - b0_v - transpListCost_nat sp0)) in *.
    replace ((k + 1) - ((m0 + 6) - (b0_v - 4) - transpListCost_nat sp0)) with (G - 9) in hsum' by (clear - hb0 hle0 hle_k; unfold G; lia).
    exists ([G + 3 - bm; G - bm] ++ bs').
    split; [exact (BlockListMin_append hpair hbl') |].
    split; [clear - hlen'; simpl; lia |].
    rewrite sumList_append; cbn [sumList].
    set (bm2 := bm - 2).
    set (dG := G - bm2 - 11).
    assert (hbm_eq : bm = bm2 + 2) by (unfold bm2; clear - hbm; lia).
    assert (hG_eq : G = dG + bm2 + 11) by (unfold dG, bm2; clear - hbm hgap; clearbody G; lia).
    rewrite hbm_eq, hG_eq in hsum' |- *.
    replace (bm2 + 2 - 2) with bm2 in hsum' by (clear; lia).
    replace (dG + bm2 + 11 - 9) with (dG + bm2 + 2) in hsum' by (clear; lia).
    replace (dG + bm2 + 11 + 3 - (bm2 + 2)) with (dG + 12) by (clear; lia).
    replace (dG + bm2 + 11 - (bm2 + 2)) with (dG + 9) by (clear; lia).
    clear - hsum'; clearbody bm2 dG; destruct n' as [|n'']; nia.
Qed.

Lemma mirror_eater_28 (m0 b0_v k minE : nat) (sp0 : list RleItem)
    (hsp0 : isTranspList sp0 = true)
    (hmin1 : 1 <= minE)
    (hb0 : 59 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + 1 <= m0)
    (hgap : minE + 250 <= k - (m0 - b0_v - transpListCost_nat sp0))
    (hle_k : m0 - b0_v - transpListCost_nat sp0 + 250 <= k) :
    exists bs,
      BlockListMin minE
        (((encS (2 * m0) true b0_v [] None ++ encItems sp0)
          ++ encS (2 * k + 1) true 27 [] None) ++ encS 138 false 28 [] None)
        ((encS (2 * (m0 + 84)) true (b0_v - 56) [] None ++ encItems sp0)
          ++ encS (2 * (k + 83) + 1) true 27 [] None)
        bs /\
      List.length bs = 28 /\
      sumList bs + 4704 = 28 * (k - (m0 - b0_v - transpListCost_nat sp0)).
Proof.
  set (c0s := transpListCost_nat sp0) in *.
  set (E0 := m0 - b0_v - c0s) in *.
  set (G := k - E0) in *.
  destruct (mirror_eater_npairs 13 m0 b0_v k 27 (minE + 97) sp0 hsp0
              ltac:(lia) hle0 ltac:(lia) ltac:(lia) ltac:(lia))
    as [bs26 [hbl26 [hlen26 hsum26]]].
  fold c0s in hsum26; fold E0 in hsum26; fold G in hsum26.
  destruct (c0_sp0_2hubs (m0 + 78) (b0_v - 52) sp0 hsp0 ltac:(lia) ltac:(lia)) as [Wm26 [d26a d26b]].
  fold c0s in d26a, d26b.
  replace ((m0 + 78) - (b0_v - 52) - c0s) with (E0 + 130) in d26a, d26b by lia.
  replace (m0 + 78 + 3) with (m0 + 81) in d26b by lia.
  replace (b0_v - 52 - 2) with (b0_v - 54) in d26b by lia.
  pose proof (mirror_norm_odd_h1 (k + 13) 0 d26a d26b ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) as hcar27.
  replace (2 * (k + 13) + 2) with (2 * (k + 14)) in hcar27 by lia.
  replace (k + 13 - (E0 + 130) + (E0 + 130 + 3 - (E0 + 130)) - (0 + 1)) with (G - 115) in hcar27 by lia.
  replace (m0 + 6 * 13) with (m0 + 78) in hbl26 by lia.
  replace (b0_v - 4 * 13) with (b0_v - 52) in hbl26 by lia.
  replace (27 - 2 * 13) with (0 + 1) in hbl26 by lia.
  assert (hbl27 : BlockListMin (minE + 97)
      ((encS (2 * m0) true b0_v [] None ++ encItems sp0) ++ encS (2 * k + 1) true 27 [] None)
      ((encS (2 * (m0 + 81)) true (b0_v - 54) [] None ++ encItems sp0) ++ encS (2 * (k + 14)) false 1 [] None)
      (bs26 ++ [G - 115])).
  { replace [G - 115] with (((G - 115) + sumList []) :: [])
      by (cbn [sumList]; rewrite Nat.add_0_r; reflexivity).
    exact (BlockListMin_append hbl26
             (BlockListMin_cons (minE + 97) (OneBlock_toWeak (DirectBlock_toOneBlock hcar27)) ltac:(lia)
                (BlockListMin_nil (minE + 97) _))). }
  pose proof (BlockListMin_liftTransp_fast 69 26 ltac:(lia)
                (ltac:(replace (minE + (69 + 26 + 2)) with (minE + 97) by lia; exact hbl27))
                hmin1) as hbl27_tr.
  simpl (2 * 69) in hbl27_tr; simpl (26 + 2) in hbl27_tr.
  destruct (c0_sp0_2hubs (m0 + 81) (b0_v - 54) sp0 hsp0 ltac:(lia) ltac:(lia)) as [Wm27 [d27a d27b]].
  fold c0s in d27a, d27b.
  replace ((m0 + 81) - (b0_v - 54) - c0s) with (E0 + 135) in d27a, d27b by lia.
  replace (m0 + 81 + 3) with (m0 + 84) in d27b by lia.
  replace (b0_v - 54 - 2) with (b0_v - 56) in d27b by lia.
  pose proof (mirror_eat_even_b1_h0 (k + 14) 137 27 d27a d27b ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) as hcar28.
  simpl (Nat.eqb (137 mod 2) 1) in hcar28.
  simpl (137 + 1) in hcar28; simpl (27 + 1) in hcar28.
  replace (2 * (k + 14) + 2 + 137) with (2 * (k + 83) + 1) in hcar28 by lia.
  replace ((k + 14) - (E0 + 135) + (E0 + 135 + 3 - (E0 + 135)) - (137 / 2 + 27 + 2))
    with (G - 215) in hcar28 by (simpl (137 / 2); lia).
  assert (hge97 : forall x, List.In x (bs26 ++ [G - 115]) -> 69 + 26 + 2 <= x).
  { clear - hbl27.
    induction hbl27 as [W0 | Wa Wb Wc e0 es bs' _ hmin _ IH]; intros x hx; simpl in hx; [contradiction |].
    destruct hx as [hx | hx]; [subst x; lia | exact (IH x hx)]. }
  pose proof (sum_map_sub (bs26 ++ [G - 115]) (69 + 26 + 2) hge97) as hmap_sum.
  assert (hlen27 : List.length (bs26 ++ [G - 115]) = 27) by (rewrite List.length_app; simpl; lia).
  rewrite hlen27 in hmap_sum.
  exists (List.map (fun x => x - (69 + 26 + 2)) (bs26 ++ [G - 115]) ++ [G - 215]).
  split.
  - replace [G - 215] with (((G - 215) + sumList []) :: [])
      by (cbn [sumList]; rewrite Nat.add_0_r; reflexivity).
    exact (BlockListMin_append hbl27_tr
             (BlockListMin_cons minE (OneBlock_toWeak (DirectBlock_toOneBlock hcar28)) ltac:(lia)
                (BlockListMin_nil minE _))).
  - split.
    + rewrite List.length_app, List.length_map, hlen27; simpl; lia.
    + simp_sumList; cbn [sumList] in hmap_sum |- *.
      clear - hgap hsum26 hmap_sum; clearbody G; lia.
Qed.

Lemma mirror_eater_28_rep (Rv : nat) :
    forall (m0 b0_v k minE : nat) (sp0 : list RleItem)
    (hsp0 : isTranspList sp0 = true)
    (hmin1 : 1 <= minE)
    (hb0 : 56 * Rv + 3 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + 1 <= m0)
    (hgap : minE + 250 + 97 * Rv + 57 * Rv <= k - (m0 - b0_v - transpListCost_nat sp0))
    (hle_k : m0 - b0_v - transpListCost_nat sp0 + 250 + 57 * Rv <= k),
    exists bs,
      BlockListMin minE
        (((encS (2 * m0) true b0_v [] None ++ encItems sp0)
          ++ encS (2 * k + 1) true 27 [] None) ++ encTranspRun_nat 138 28 Rv)
        ((encS (2 * (m0 + 84 * Rv)) true (b0_v - 56 * Rv) [] None ++ encItems sp0)
          ++ encS (2 * (k + 83 * Rv) + 1) true 27 [] None)
        bs /\
      List.length bs = 28 * Rv /\
      sumList bs + (4704 * Rv + 2156 * Rv * (Rv - 1)) =
        28 * Rv * (k - (m0 - b0_v - transpListCost_nat sp0)).
Proof.
  induction Rv as [|R' IH]; intros m0 b0_v k minE sp0 hsp0 hmin1 hb0 hle0 hgap hle_k.
  - exists (@nil nat).
    unfold encTranspRun_nat; rewrite zPz, app_nil_r.
    replace (m0 + 84 * 0) with m0 by lia.
    replace (b0_v - 56 * 0) with b0_v by lia.
    replace (k + 83 * 0) with k by lia.
    split; [exact (BlockListMin_nil _ _) | simpl; lia].
  - set (c0s := transpListCost_nat sp0) in *.
    set (G := k - (m0 - b0_v - c0s)) in *.
    destruct (mirror_eater_28 m0 b0_v k (minE + 97 * R') sp0 hsp0
                ltac:(lia) ltac:(lia) hle0 ltac:(lia) ltac:(lia))
      as [bs1 [hbl1 [hlen1 hsum1]]].
    fold c0s in hsum1; fold G in hsum1.
    assert (hwk : BlockListMin (minE + R' * (69 + 26 + 2))
      (((encS (2 * m0) true b0_v [] None ++ encItems sp0) ++ encS (2 * k + 1) true 27 [] None)
        ++ encS 138 false 28 [] None)
      ((encS (2 * (m0 + 84)) true (b0_v - 56) [] None ++ encItems sp0)
        ++ encS (2 * (k + 83) + 1) true 27 [] None) bs1).
    { exact (BlockListMin_weaken (m1 := minE + R' * (69 + 26 + 2)) (m2 := minE + 97 * R') ltac:(lia) hbl1). }
    pose proof (BlockListMin_liftTranspRun_fast R' 69 26 ltac:(lia) hwk hmin1) as hbl1_tr.
    destruct (IH (m0 + 84) (b0_v - 56) (k + 83) minE sp0 hsp0 hmin1
                ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia))
      as [bs2 [hbl2 [hlen2 hsum2]]].
    fold c0s in hsum2.
    replace (m0 + 84 + 84 * R') with (m0 + 84 * S R') in hbl2 by (clear; lia).
    replace (b0_v - 56 - 56 * R') with (b0_v - 56 * S R') in hbl2 by (clear - hb0; lia).
    replace (k + 83 + 83 * R') with (k + 83 * S R') in hbl2 by (clear; lia).
    replace ((k + 83) - ((m0 + 84) - (b0_v - 56) - c0s)) with (G - 57) in hsum2 by (clear - hb0 hle0 hle_k; unfold G, c0s; lia).
    assert (hTR_lhs :
      ((((encS (2 * m0) true b0_v [] None ++ encItems sp0) ++ encS (2 * k + 1) true 27 [] None)
        ++ encS 138 false 28 [] None) ++ (((T2 ^^ (2 * 69)) ++ (T4 ^^ (26 + 2))) ^^ R')) =
      (((encS (2 * m0) true b0_v [] None ++ encItems sp0) ++ encS (2 * k + 1) true 27 [] None)
        ++ encTranspRun_nat 138 28 (S R'))).
    { unfold encTranspRun_nat, encS at 3; cbn [encSegTail].
      simpl (2 * 69); simpl (26 + 2).
      replace (S R') with (R' + 1) by lia.
      rewrite (list_pow_succ ((T2 ^^ 138) ++ (T4 ^^ 28)) R'), ?app_nil_r, ?append_assoc. reflexivity. }
    assert (hTR_rhs :
      (((encS (2 * (m0 + 84)) true (b0_v - 56) [] None ++ encItems sp0)
        ++ encS (2 * (k + 83) + 1) true 27 [] None)
        ++ (((T2 ^^ (2 * 69)) ++ (T4 ^^ (26 + 2))) ^^ R')) =
      (((encS (2 * (m0 + 84)) true (b0_v - 56) [] None ++ encItems sp0)
        ++ encS (2 * (k + 83) + 1) true 27 [] None) ++ encTranspRun_nat 138 28 R')).
    { unfold encTranspRun_nat; simpl (2 * 69); simpl (26 + 2); reflexivity. }
    rewrite hTR_lhs, hTR_rhs in hbl1_tr.
    assert (hge1 : forall x, List.In x bs1 -> R' * (69 + 26 + 2) <= x).
    { clear - hbl1.
      induction hbl1 as [W0 | Wa Wb Wc e0 es bs' _ hmin _ IHb]; intros x hx; simpl in hx; [contradiction |].
      destruct hx as [hx | hx]; [subst x; lia | exact (IHb x hx)]. }
    pose proof (sum_map_sub bs1 (R' * (69 + 26 + 2)) hge1) as hmap_sum.
    pose proof (list_len_mul_le_sum bs1 (R' * (69 + 26 + 2)) hge1) as hlen_le.
    try (rewrite hlen1 in hmap_sum); try (rewrite hlen1 in hlen_le).
    exists (List.map (fun x => x - R' * (69 + 26 + 2)) bs1 ++ bs2).
    split; [exact (BlockListMin_append hbl1_tr hbl2) |].
    split; [rewrite List.length_app, List.length_map; lia |].
    rewrite sumList_append, hmap_sum.
    set (dG := G - 97 * R' - 250).
    assert (hG_eq : G = dG + 97 * R' + 250) by (unfold dG; clear - hgap; clearbody G; lia).
    assert (hbs1 : sumList bs1 - 28 * (R' * (69 + 26 + 2)) = 28 * dG + 2296)
      by (rewrite hG_eq in hsum1; clear - hsum1; clearbody dG; lia).
    rewrite hbs1.
    rewrite hG_eq in hsum2 |- *.
    replace (dG + 97 * R' + 250 - 57) with (dG + 97 * R' + 193) in hsum2 by (clear; lia).
    clear - hsum2; clearbody dG; destruct R' as [|R'']; nia.
Qed.

Lemma m3752_1cycle (m0 b0_v k rep pr : nat) (sp0 : list RleItem)
    (hsp0 : isTranspList sp0 = true)
    (hb0 : 3755 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + 1 <= m0)
    (hrep : 67 <= rep) (hpr : 28 <= pr)
    (hgap : 97 * rep + (6 * 1000 + 620) <= k - (m0 - b0_v - transpListCost_nat sp0))
    (hle_k : m0 - b0_v - transpListCost_nat sp0 + 4040 <= k) :
    exists es_tot,
      PureP2W
        ((((((encS (2 * m0) true b0_v [] None ++ encItems sp0)
          ++ encS (2 * k + 1) true 27 [] None)
          ++ encTranspRun_nat 138 28 rep)
          ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
          ++ encPairRun_nat 1 true 39 1 true 40 pr)
        ((((((encS (2 * (m0 + (5 * 1000 + 628))) true (b0_v - 3752) [] None ++ encItems sp0)
          ++ encS (2 * (k + (5 * 1000 + 561)) + 1) true 27 [] None)
          ++ encTranspRun_nat 138 28 (rep - 53))
          ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
          ++ encPairRun_nat 1 true 39 1 true 40 (pr - 28))
        es_tot /\
      sumList es_tot = 1876 * (k - (m0 - b0_v - transpListCost_nat sp0) - 97 * rep) + (1080 * 1000 + 450).
Proof.
  set (c0s := transpListCost_nat sp0) in *.
  set (G := k - (m0 - b0_v - c0s)) in *.
  destruct (mirror_eater_28_rep 67 m0 b0_v k (150 + 97 * (rep - 67 + 14)) sp0 hsp0
              ltac:(lia) ltac:(lia) hle0 ltac:(lia) ltac:(lia))
    as [bs [hbl [hlen hsum]]].
  destruct (wave402_Kcycles_r0 14 (rep - 67) hbl ltac:(lia))
    as [es_tot [hp [hsum_es _]]].
  pose proof (PureP2W_liftPairRun 1 39 1 40 (pr - 28) hp) as hp'.
  assert (hTRsplit : encTranspRun_nat 138 28 67 ++ encTranspRun_nat 138 28 (rep - 67) =
                     encTranspRun_nat 138 28 rep).
  { unfold encTranspRun_nat; fold_pow_add; replace (67 + (rep - 67)) with rep by lia; reflexivity. }
  assert (hPRsplit : encPairRun_nat 1 true 39 1 true 40 (2 * 14) ++ encPairRun_nat 1 true 39 1 true 40 (pr - 28) =
                     encPairRun_nat 1 true 39 1 true 40 pr).
  { unfold encPairRun_nat; fold_pow_add; replace (2 * 14 + (pr - 28)) with pr by lia; reflexivity. }
  exists es_tot. split.
  - replace (m0 + 84 * 67) with (m0 + (5 * 1000 + 628)) in hp' by lia.
    replace (b0_v - 56 * 67) with (b0_v - 3752) in hp' by lia.
    replace (k + 83 * 67) with (k + (5 * 1000 + 561)) in hp' by lia.
    replace (rep - 67 + 14) with (rep - 53) in hp' by lia.
    assert (hL : (((((((encS (2 * m0) true b0_v [] None ++ encItems sp0)
                    ++ encS (2 * k + 1) true 27 [] None) ++ encTranspRun_nat 138 28 67)
                    ++ encTranspRun_nat 138 28 (rep - 67))
                    ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
                    ++ encPairRun_nat 1 true 39 1 true 40 (2 * 14))
                    ++ encPairRun_nat 1 true 39 1 true 40 (pr - 28) =
                 ((((((encS (2 * m0) true b0_v [] None ++ encItems sp0)
                    ++ encS (2 * k + 1) true 27 [] None)
                    ++ encTranspRun_nat 138 28 rep)
                    ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
                    ++ encPairRun_nat 1 true 39 1 true 40 pr)).
    { rewrite <- hTRsplit, <- hPRsplit, ?append_assoc. reflexivity. }
    rewrite hL in hp'. exact hp'.
  - fold c0s in hsum; fold G in hsum.
    rewrite hsum_es; clear - hrep hgap hsum; clearbody G; lia.
Qed.

