Definition m3752Stot_nat (m0 b0_v sp0_c k rep Mv : nat) : nat :=
  let dS0 := 1876 * (k - (m0 - b0_v - sp0_c) - 97 * rep) + (1080 * 1000 + 450) in
  Mv * dS0 + (1240 * 1000 + 36) * Mv * (Mv - 1).

Lemma m3752Stot_to_nat (m0 b0_v sp0_c k rep Mv : N) :
  N.to_nat (m3752Stot m0 b0_v sp0_c k rep Mv) =
  m3752Stot_nat (N.to_nat m0) (N.to_nat b0_v) (N.to_nat sp0_c)
    (N.to_nat k) (N.to_nat rep) (N.to_nat Mv).
Proof.
  unfold m3752Stot, m3752Stot_nat; cbv zeta.
  repeat (rewrite N2Nat.inj_add || rewrite N2Nat.inj_mul || rewrite N2Nat.inj_sub).
  assert (hc1 : N.to_nat 1080450%N = 1080 * 1000 + 450) by (clear; lia).
  assert (hc2 : N.to_nat 1240036%N = 1240 * 1000 + 36) by (clear; lia).
  change (N.to_nat 1876%N) with 1876.
  change (N.to_nat 97%N) with 97.
  change (N.to_nat 1%N) with 1.
  rewrite hc1, hc2. reflexivity.
Qed.

Lemma m3752_Mcycles (Mv : nat) :
    forall (m0 b0_v k rep pr : nat) (sp0 : list RleItem)
    (hsp0 : isTranspList sp0 = true)
    (hb0 : 3752 * Mv + 3 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + 1 <= m0)
    (hrep : 53 * Mv + 14 <= rep) (hpr : 28 * Mv <= pr)
    (hgap : 97 * rep + (6 * 1000 + 620) <= k - (m0 - b0_v - transpListCost_nat sp0))
    (hle_k : m0 - b0_v - transpListCost_nat sp0 + 3819 * Mv + 4040 <= k),
    exists es_tot,
      PureP2W
        ((((((encS (2 * m0) true b0_v [] None ++ encItems sp0)
          ++ encS (2 * k + 1) true 27 [] None)
          ++ encTranspRun_nat 138 28 rep)
          ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
          ++ encPairRun_nat 1 true 39 1 true 40 pr)
        ((((((encS (2 * (m0 + (5 * 1000 + 628) * Mv)) true (b0_v - 3752 * Mv) [] None ++ encItems sp0)
          ++ encS (2 * (k + (5 * 1000 + 561) * Mv) + 1) true 27 [] None)
          ++ encTranspRun_nat 138 28 (rep - 53 * Mv))
          ++ encS 5 true 35 [] None) ++ encS 3 false 39 [] None)
          ++ encPairRun_nat 1 true 39 1 true 40 (pr - 28 * Mv))
        es_tot /\
      sumList es_tot = m3752Stot_nat m0 b0_v (transpListCost_nat sp0) k rep Mv.
Proof.
  induction Mv as [|M' IH]; intros m0 b0_v k rep pr sp0 hsp0 hb0 hle0 hrep hpr hgap hle_k.
  - exists (@nil nat).
    replace (m0 + (5 * 1000 + 628) * 0) with m0 by (clear; lia).
    replace (b0_v - 3752 * 0) with b0_v by (clear; lia).
    replace (k + (5 * 1000 + 561) * 0) with k by (clear; lia).
    replace (rep - 53 * 0) with rep by (clear; lia).
    replace (pr - 28 * 0) with pr by (clear; lia).
    split; [exact (PureP2W_nil _) | cbn [sumList]; unfold m3752Stot_nat; cbv zeta; clear; lia].
  - assert (hE0_step : (m0 + (5 * 1000 + 628)) - (b0_v - 3752) - transpListCost_nat sp0 =
                       (m0 - b0_v - transpListCost_nat sp0) + (9 * 1000 + 380))
      by (clear - hb0 hle0; lia).
    assert (hgap_next : 97 * (rep - 53) + (6 * 1000 + 620) <=
                        (k + (5 * 1000 + 561)) - ((m0 + (5 * 1000 + 628)) - (b0_v - 3752) - transpListCost_nat sp0)).
    { rewrite hE0_step; set (E0 := m0 - b0_v - transpListCost_nat sp0) in *;
      clearbody E0; clear - hrep hgap; lia. }
    assert (hle_k_next : ((m0 + (5 * 1000 + 628)) - (b0_v - 3752) - transpListCost_nat sp0) + 3819 * M' + 4040 <=
                         k + (5 * 1000 + 561)).
    { rewrite hE0_step; set (E0 := m0 - b0_v - transpListCost_nat sp0) in *;
      clearbody E0; clear - hle_k; lia. }
    destruct (m3752_1cycle m0 b0_v k rep pr sp0 hsp0
                ltac:(clear - hb0; lia) hle0 ltac:(clear - hrep; lia) ltac:(clear - hpr; lia) hgap
                ltac:(set (E0 := m0 - b0_v - transpListCost_nat sp0) in *; clearbody E0; clear - hle_k; lia))
      as [es1 [hp1 hsum1]].
    destruct (IH (m0 + (5 * 1000 + 628)) (b0_v - 3752) (k + (5 * 1000 + 561)) (rep - 53) (pr - 28) sp0 hsp0
                ltac:(clear - hb0; lia) ltac:(clear - hb0 hle0; lia) ltac:(clear - hrep; lia) ltac:(clear - hpr; lia)
                hgap_next hle_k_next)
      as [es2 [hp2 hsum2]].
    replace (m0 + (5 * 1000 + 628) + (5 * 1000 + 628) * M') with (m0 + (5 * 1000 + 628) * S M') in hp2 by (clear; lia).
    replace (b0_v - 3752 - 3752 * M') with (b0_v - 3752 * S M') in hp2 by (clear; lia).
    replace (k + (5 * 1000 + 561) + (5 * 1000 + 561) * M') with (k + (5 * 1000 + 561) * S M') in hp2 by (clear; lia).
    replace (rep - 53 - 53 * M') with (rep - 53 * S M') in hp2 by (clear; lia).
    replace (pr - 28 - 28 * M') with (pr - 28 * S M') in hp2 by (clear; lia).
    exists (es1 ++ es2). split; [exact (PureP2W_append hp1 hp2) |].
    rewrite sumList_append, hsum1, hsum2.
    unfold m3752Stot_nat; cbv zeta.
    set (G := k - (m0 - b0_v - transpListCost_nat sp0)) in *.
    assert (hdS_step :
      1876 * ((k + (5 * 1000 + 561)) - ((m0 + (5 * 1000 + 628)) - (b0_v - 3752) - transpListCost_nat sp0) - 97 * (rep - 53)) + (1080 * 1000 + 450) =
      (1876 * (G - 97 * rep) + (1080 * 1000 + 450)) + (2480 * 1000 + 72)).
    { replace ((m0 + (5 * 1000 + 628)) - (b0_v - 3752) - transpListCost_nat sp0)
        with ((m0 - b0_v - transpListCost_nat sp0) + (9 * 1000 + 380)) by (clear - hb0 hle0; lia).
      replace ((k + (5 * 1000 + 561)) - ((m0 - b0_v - transpListCost_nat sp0) + (9 * 1000 + 380)))
        with (G - 3819) by (clear - hle_k; unfold G; lia).
      clear - hrep hgap; clearbody G; lia. }
    rewrite hdS_step.
    set (D0 := 1876 * (G - 97 * rep) + (1080 * 1000 + 450)); clearbody D0; clear.
    destruct M' as [|M'']; cbn [Nat.sub]; rewrite ?Nat.sub_0_r; nia.
Qed.

Lemma stepMirror3752_sound (k0 : nat) (Mv : N) (items items' : list RleItem)
    (h : stepMirror3752 k0 Mv items = Some items') :
    (HubCfg items) -[ tm ]->* (HubCfg items').
Proof.
  unfold stepMirror3752 in h.
  destruct items as [|x0 rest0]; [discriminate |].
  destruct x0 as [a0 [|] b0_v [|? ?] [?|] | | |]; try discriminate.
  destruct (negb (a0 mod 2 =? 0)%N) eqn:ha0; [discriminate |].
  apply Bool.negb_false_iff in ha0; apply N.eqb_eq in ha0.
  destruct (splitAtList k0 rest0) as [[sp0 rest1]|] eqn:hs0; [| discriminate].
  destruct (negb (isTranspList sp0)) eqn:hsp0; [discriminate |].
  apply Bool.negb_false_iff in hsp0.
  destruct rest1 as [|xm r1]; [discriminate |].
  destruct xm as [am [|] bm [|? ?] [?|] | | |]; try discriminate.
  destruct r1 as [|xtr r2]; [discriminate |].
  destruct xtr as [| ta tb rep | |]; try discriminate.
  destruct r2 as [|xu1 r3]; [discriminate |].
  destruct xu1 as [u1 [|] ub1 [|? ?] [?|] | | |]; try discriminate.
  destruct r3 as [|xu2 r4]; [discriminate |].
  destruct xu2 as [u2 [|] ub2 [|? ?] [?|] | | |]; try discriminate.
  destruct r4 as [|xpr tail]; [discriminate |].
  destruct xpr as [| | pa1 [|] pb1 pa2 [|] pb2 pr |]; try discriminate.
  destruct (((am mod 2 =? 1)%N && (bm =? 27)%N && (ta =? 138)%N && (tb =? 28)%N &&
             (u1 =? 5)%N && (ub1 =? 35)%N && (u2 =? 3)%N && (ub2 =? 39)%N &&
             (pa1 =? 1)%N && (pb1 =? 39)%N && (pa2 =? 1)%N && (pb2 =? 40)%N)%bool)
    eqn:hpat; [| discriminate].
  split_andb; subst bm ta tb u1 ub1 u2 ub2 pa1 pb1 pa2 pb2.
  cbv zeta in h.
  destruct (((3752 * Mv + 3 <=? b0_v)%N && (b0_v + transpListCost sp0 + 1 <=? a0 / 2)%N &&
             (53 * Mv + 14 <=? rep)%N && (28 * Mv <=? pr)%N &&
             (97 * rep + 6620 <=? am / 2 - (a0 / 2 - b0_v - transpListCost sp0))%N &&
             ((a0 / 2 - b0_v - transpListCost sp0) + 3819 * Mv + 4040 <=? am / 2)%N)%bool)
    eqn:hcond; [| discriminate].
  split_andb.
  destruct (applySinkDumpBig (m3752Stot (a0 / 2) b0_v (transpListCost sp0) (am / 2) rep Mv) tail)
    as [tail'|] eqn:hd; [| discriminate].
  inv_some h; subst items'.
  pose proof (splitAtList_sound _ _ _ _ hs0) as hr0; subst rest0.
  pose proof (N2Nat_div a0 2) as Ha0div; change (N.to_nat 2%N) with 2 in Ha0div.
  pose proof (N2Nat_mod a0 2) as Ha0mod; change (N.to_nat 2%N) with 2 in Ha0mod.
  pose proof (N2Nat_div am 2) as Hamdiv; change (N.to_nat 2%N) with 2 in Hamdiv.
  pose proof (N2Nat_mod am 2) as Hammod; change (N.to_nat 2%N) with 2 in Hammod.
  assert (ha0_par : N.to_nat a0 = 2 * (N.to_nat a0 / 2))
    by (clear - ha0 Ha0mod; pose proof (Nat.div_mod (N.to_nat a0) 2 ltac:(lia)); lia).
  assert (ham_par : N.to_nat am = 2 * (N.to_nat am / 2) + 1)
    by (match goal with H : (am mod 2 = 1)%N |- _ => clear - H Hammod end;
        pose proof (Nat.div_mod (N.to_nat am) 2 ltac:(lia)); lia).
  clear Ha0mod Hammod ha0 hs0.
  assert (hE0_nat : N.to_nat (a0 / 2 - b0_v - transpListCost sp0)%N =
                    N.to_nat a0 / 2 - N.to_nat b0_v - transpListCost_nat sp0)
    by (unfold transpListCost_nat; rewrite !N2Nat.inj_sub, Ha0div; reflexivity).
  destruct (m3752_Mcycles (N.to_nat Mv) (N.to_nat a0 / 2) (N.to_nat b0_v)
              (N.to_nat am / 2) (N.to_nat rep) (N.to_nat pr) sp0 hsp0
              ltac:(lia) ltac:(unfold transpListCost_nat; lia) ltac:(lia) ltac:(lia)
              ltac:(rewrite <- hE0_nat, <- Hamdiv, <- N2Nat.inj_sub;
                    set (E0n := (a0 / 2 - b0_v - transpListCost sp0)%N) in *; clearbody E0n; lia)
              ltac:(rewrite <- hE0_nat, <- Hamdiv;
                    set (E0n := (a0 / 2 - b0_v - transpListCost sp0)%N) in *; clearbody E0n; lia))
    as [es_tot [hpw hsum]].
  pose proof (applySinkDumpBig_sound hd) as hdump.
  rewrite m3752Stot_to_nat, Ha0div, Hamdiv in hdump.
  unfold transpListCost_nat in hsum.
  rewrite <- hsum in hdump.
  pose proof (PureP2W_dump hpw hdump) as hrun.
  clear - hrun ha0_par ham_par.
  replace (2 * (N.to_nat a0 / 2)) with (N.to_nat a0) in hrun by lia.
  replace (2 * (N.to_nat am / 2) + 1) with (N.to_nat am) in hrun by lia.
  replace (2 * (N.to_nat a0 / 2 + (5 * 1000 + 628) * N.to_nat Mv))
    with (N.to_nat (a0 + 11256%N * Mv)%N) in hrun
    by (rewrite N2Nat.inj_add, N2Nat.inj_mul; assert (N.to_nat 11256%N = 2 * (5 * 1000 + 628)) by (clear; lia); lia).
  replace (N.to_nat b0_v - 3752 * N.to_nat Mv)
    with (N.to_nat (b0_v - 3752 * Mv)%N) in hrun
    by (rewrite N2Nat.inj_sub, N2Nat.inj_mul; change (N.to_nat 3752%N) with 3752; reflexivity).
  replace (2 * (N.to_nat am / 2 + (5 * 1000 + 561) * N.to_nat Mv) + 1)
    with (N.to_nat (am + 11122%N * Mv)%N) in hrun
    by (rewrite N2Nat.inj_add, N2Nat.inj_mul; assert (N.to_nat 11122%N = 2 * (5 * 1000 + 561)) by (clear; lia); lia).
  replace (N.to_nat rep - 53 * N.to_nat Mv)
    with (N.to_nat (rep - 53 * Mv)%N) in hrun
    by (rewrite N2Nat.inj_sub, N2Nat.inj_mul; change (N.to_nat 53%N) with 53; reflexivity).
  replace (N.to_nat pr - 28 * N.to_nat Mv)
    with (N.to_nat (pr - 28 * Mv)%N) in hrun
    by (rewrite N2Nat.inj_sub, N2Nat.inj_mul; change (N.to_nat 28%N) with 28; reflexivity).
  unfold HubCfg.
  repeat (cbn [encItems app]; simp_encItems_app); cbn [encItems];
    rewrite !encItem_transpRun_eq, !encItem_pairRun_eq; cbn [encItem];
    rewrite !encSingle_eq_encS; cbn [option_map N.to_nat Pos.to_nat].
  rewrite ?append_assoc, ?Str_app_assoc.
  rewrite ?append_assoc, ?Str_app_assoc in hrun.
  exact hrun.
Qed.

