(* ========================================================================= *)
(* Section 14.3: Symbolic Mirror Engine & M162 (81 Carries via vm_compute)   *)
(* ========================================================================= *)

Definition MirrorSymState : Type := nat * bool * nat * list FrontCell.

Definition symMirrorStep (i : nat) (st : MirrorSymState) :
    option (MirrorSymState * nat * nat * nat) :=
  let '(dam, hm, bm, front) := st in
  let addK := (1 + dam) / 2 + 3 in
  let subK := 5 * i in
  let amOdd := Nat.eqb ((1 + dam) mod 2) 1 in
  if (hm && Nat.leb 1 bm)%bool then
    match symCarry front with
    | None => None
    | Some (front', cf, mf) =>
        let '(hm', bm') := if amOdd then (false, bm) else (true, bm - 1) in
        let minG := Nat.max (subK + 1) (subK + bm + mf + 1) in
        Some ((dam + 1, hm', bm', front'), addK, subK + bm + cf, minG)
    end
  else if (negb hm && Nat.leb 2 bm)%bool then
    match symCarry front with
    | None => None
    | Some (front', cf, mf) =>
        let '(hm', bm') := if amOdd then (false, bm - 1) else (true, bm - 2) in
        let minG := Nat.max (subK + 1) (subK + bm + mf + 1) in
        Some ((dam + 1, hm', bm', front'), addK + 1, subK + bm + cf, minG)
    end
  else match front with
  | [] => None
  | (a2, h2, b2) :: rest =>
      if Nat.eqb b2 0 then None
      else if (hm && Nat.eqb bm 0 && amOdd)%bool then
        if negb h2 then
          match symCarry rest with
          | None => None
          | Some (front', cf, mf) =>
              let '(hm', bm') := if Nat.eqb (a2 mod 2) 1 then (true, b2 - 1) else (false, b2) in
              let subE := subK + a2 / 2 + b2 in
              let minG := Nat.max (subK + a2 / 2 + 2) (subE + mf + 1) in
              Some ((dam + 1 + a2, hm', bm', front'), addK, subE + cf, minG)
          end
        else if frontValid rest then
          let '(hm', bm') := if Nat.eqb (a2 mod 2) 1 then (true, b2 - 1) else (false, b2) in
          let subE := subK + a2 / 2 in
          let minG := subK + a2 / 2 + 2 in
          Some ((dam + 2 + a2, hm', bm', rest), addK, subE, minG)
        else None
      else if (negb hm && Nat.eqb bm 1 && negb amOdd && Nat.leb 1 a2)%bool then
        let a2' := a2 - 1 in
        if negb h2 then
          match symCarry rest with
          | None => None
          | Some (front', cf, mf) =>
              let '(hm', bm') := if Nat.eqb (a2' mod 2) 1 then (true, b2 - 1) else (false, b2) in
              let subE := subK + a2' / 2 + b2 + 1 in
              let minG := Nat.max (subK + a2' / 2 + 3) (subE + mf + 1) in
              Some ((dam + 1 + a2, hm', bm', front'), addK, subE + cf, minG)
          end
        else if frontValid rest then
          let '(hm', bm') := if Nat.eqb (a2' mod 2) 1 then (true, b2 - 1) else (false, b2) in
          let subE := subK + a2' / 2 + 1 in
          let minG := subK + a2' / 2 + 3 in
          Some ((dam + 2 + a2, hm', bm', rest), addK, subE, minG)
        else None
      else None
  end.

Fixpoint symMirrorRun (n i : nat) (st : MirrorSymState) :
    option (MirrorSymState * nat * nat * nat) :=
  match n with
  | O => Some (st, 0, 0, 0)
  | S n' =>
      match symMirrorStep i st with
      | None => None
      | Some (st1, a1, s1, mg1) =>
          match symMirrorRun n' (i + 1) st1 with
          | None => None
          | Some (st2, a2, s2, mg2) => Some (st2, a1 + a2, s1 + s2, Nat.max mg1 mg2)
          end
      end
  end.

Lemma symMirrorStep_sound {W0 W1 W2 : list Sym} {E0 k i : nat}
    {st st' : MirrorSymState} {addE subE minG : nat}
    (h : symMirrorStep i st = Some (st', addE, subE, minG))
    (d1 : DirectBlock W0 W1 (E0 + 5 * i)) (d2 : DirectBlock W1 W2 (E0 + 5 * i + 3))
    (hE0 : 1 <= E0) (hgap : minG <= k - E0) (hE0k : E0 + minG <= k) :
    let '(dam, hm, bm, front) := st in
    let '(dam', hm', bm', front') := st' in
    exists es,
      PureP2W
        ((W0 ++ encS (2 * k + 1 + dam) hm bm [] None) ++ encFront front)
        ((W2 ++ encS (2 * k + 1 + dam') hm' bm' [] None) ++ encFront front')
        es /\
      sumList es + subE = (k - E0) + addE /\
      subE <= (k - E0) + addE.
Proof.
  destruct st as [[[dam hm] bm] front].
  destruct st' as [[[dam' hm'] bm'] front'].
  cbv beta iota zeta.
  unfold symMirrorStep in h; cbv beta iota zeta in h.
  set (G := k - E0) in *.
  assert (hk_G : k = E0 + G) by (clear - hE0k; unfold G; lia).
  clearbody G.
  set (K_cur := (2 * k + 1 + dam) / 2).
  assert (hK_cur : K_cur = k + (1 + dam) / 2)
    by (unfold K_cur; pose proof (Nat.div_mod (2 * k + 1 + dam) 2 ltac:(lia));
        pose proof (Nat.div_mod (1 + dam) 2 ltac:(lia)); lia).
  clearbody K_cur.
  pose proof (Nat.div_mod (1 + dam) 2 ltac:(lia)) as hdm_dam.
  pose proof (Nat.mod_upper_bound (1 + dam) 2 ltac:(lia)) as hmu_dam.
  destruct ((hm && Nat.leb 1 bm)%bool) eqn:hc1.
  - apply Bool.andb_true_iff in hc1; destruct hc1 as [hhm hbm]; subst hm.
    apply Nat.leb_le in hbm.
    destruct (symCarry front) as [[[f' cf] mf]|] eqn:hsc; [| discriminate].
    destruct (Nat.eqb ((1 + dam) mod 2) 1) eqn:hpar.
    + apply Nat.eqb_eq in hpar.
      cbv beta iota zeta in h; inv_some h; subst dam' hm' bm' front' addE subE minG.
      pose proof (mirror_norm_odd_h1 K_cur (bm - 1) d1 d2 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) as hcar.
      replace (2 * K_cur + 1) with (2 * k + 1 + dam) in hcar by lia.
      replace (bm - 1 + 1) with bm in hcar by lia.
      replace (2 * K_cur + 2) with (2 * k + 1 + (dam + 1)) in hcar by lia.
      replace (K_cur - (E0 + 5 * i) + (E0 + 5 * i + 3 - (E0 + 5 * i)) - bm)
        with (G + ((1 + dam) / 2 + 3) - (5 * i + bm)) in hcar by lia.
      destruct (symCarry_sound front hsc (OneBlock_toWeak (DirectBlock_toOneBlock hcar)) ltac:(lia))
        as [es [hp [hsum hcf_le]]].
      cbn [sumList] in hsum.
      exists es. split; [exact hp | clear d1 d2 hcar hp hsc; lia].
    + apply Nat.eqb_neq in hpar.
      cbv beta iota zeta in h; inv_some h; subst dam' hm' bm' front' addE subE minG.
      pose proof (mirror_norm_even_h1 K_cur (bm - 1) d1 d2 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) as hcar.
      replace (2 * K_cur + 1) with (2 * k + 1 + (dam + 1)) in hcar by lia.
      replace (2 * K_cur) with (2 * k + 1 + dam) in hcar by lia.
      replace (bm - 1 + 1) with bm in hcar by lia.
      replace (K_cur - (E0 + 5 * i) + (E0 + 5 * i + 3 - (E0 + 5 * i)) - bm)
        with (G + ((1 + dam) / 2 + 3) - (5 * i + bm)) in hcar by lia.
      destruct (symCarry_sound front hsc (OneBlock_toWeak (DirectBlock_toOneBlock hcar)) ltac:(lia))
        as [es [hp [hsum hcf_le]]].
      cbn [sumList] in hsum.
      exists es. split; [exact hp | clear d1 d2 hcar hp hsc; lia].
  - destruct ((negb hm && Nat.leb 2 bm)%bool) eqn:hc2.
    + apply Bool.andb_true_iff in hc2; destruct hc2 as [hhm hbm].
      apply Bool.negb_true_iff in hhm; subst hm.
      apply Nat.leb_le in hbm.
      destruct (symCarry front) as [[[f' cf] mf]|] eqn:hsc; [| discriminate].
      destruct (Nat.eqb ((1 + dam) mod 2) 1) eqn:hpar.
      * apply Nat.eqb_eq in hpar.
        cbv beta iota zeta in h; inv_some h; subst dam' hm' bm' front' addE subE minG.
        pose proof (mirror_norm_odd_h0 K_cur (bm - 2) d1 d2 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) as hcar.
        replace (2 * K_cur + 1) with (2 * k + 1 + dam) in hcar by lia.
        replace (bm - 2 + 2) with bm in hcar by lia.
        replace (bm - 2 + 1) with (bm - 1) in hcar by lia.
        replace (2 * K_cur + 2) with (2 * k + 1 + (dam + 1)) in hcar by lia.
        replace (K_cur - (E0 + 5 * i) + (E0 + 5 * i + 3 - (E0 + 5 * i)) - (bm - 1))
          with (G + ((1 + dam) / 2 + 3 + 1) - (5 * i + bm)) in hcar by lia.
        destruct (symCarry_sound front hsc (OneBlock_toWeak (DirectBlock_toOneBlock hcar)) ltac:(lia))
          as [es [hp [hsum hcf_le]]].
        cbn [sumList] in hsum.
        exists es. split; [exact hp | clear d1 d2 hcar hp hsc; lia].
      * apply Nat.eqb_neq in hpar.
        cbv beta iota zeta in h; inv_some h; subst dam' hm' bm' front' addE subE minG.
        pose proof (mirror_norm_even_h0 K_cur (bm - 2) d1 d2 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) as hcar.
        replace (2 * K_cur + 1) with (2 * k + 1 + (dam + 1)) in hcar by lia.
        replace (2 * K_cur) with (2 * k + 1 + dam) in hcar by lia.
        replace (bm - 2 + 2) with bm in hcar by lia.
        replace (K_cur - (E0 + 5 * i) + (E0 + 5 * i + 3 - (E0 + 5 * i)) - (bm - 2 + 1))
          with (G + ((1 + dam) / 2 + 3 + 1) - (5 * i + bm)) in hcar by lia.
        destruct (symCarry_sound front hsc (OneBlock_toWeak (DirectBlock_toOneBlock hcar)) ltac:(lia))
          as [es [hp [hsum hcf_le]]].
        cbn [sumList] in hsum.
        exists es. split; [exact hp | clear d1 d2 hcar hp hsc; lia].
    + destruct front as [|[[a2 h2] b2] rest]; [discriminate |].
      destruct (Nat.eqb b2 0) eqn:hb2z; [discriminate |].
      apply Nat.eqb_neq in hb2z.
      set (b2' := b2 - 1).
      assert (hb2_eq : b2 = b2' + 1) by (unfold b2'; lia).
      destruct ((hm && Nat.eqb bm 0 && Nat.eqb ((1 + dam) mod 2) 1)%bool) eqn:hc3a.
      * apply Bool.andb_true_iff in hc3a; destruct hc3a as [hc3a' hodd].
        apply Bool.andb_true_iff in hc3a'; destruct hc3a' as [hhm hbm0].
        subst hm; apply Nat.eqb_eq in hbm0; subst bm.
        apply Nat.eqb_eq in hodd.
        destruct h2.
        -- simpl negb in h.
           destruct (frontValid rest) eqn:hfv; [| discriminate].
           assert (hmg : 5 * i + a2 / 2 + 2 <= minG)
             by (destruct (Nat.eqb (a2 mod 2) 1); cbv beta iota zeta in h; inv_some h; lia).
           pose proof (mirror_eat_odd_b0_h1 K_cur a2 b2' d1 d2 ltac:(lia) ltac:(lia) ltac:(lia)) as hcar.
           replace (2 * K_cur + 1) with (2 * k + 1 + dam) in hcar by lia.
           replace (2 * K_cur + 3 + a2) with (2 * k + 1 + (dam + 2 + a2)) in hcar by lia.
           replace (K_cur - (E0 + 5 * i) + (E0 + 5 * i + 3 - (E0 + 5 * i)) - a2 / 2)
             with (G + ((1 + dam) / 2 + 3) - (5 * i + a2 / 2)) in hcar by lia.
           rewrite <- hb2_eq in hcar.
           pose proof (PureP2W_liftFront rest hfv hcar) as hp.
           destruct (Nat.eqb (a2 mod 2) 1);
             cbv beta iota zeta in h; inv_some h; subst dam' hm' bm' front' addE subE minG;
             exists [G + ((1 + dam) / 2 + 3) - (5 * i + a2 / 2)];
             (split; [cbn [encFront]; rewrite ?append_assoc in hp; rewrite ?append_assoc; exact hp
                     | cbn [sumList]; clear d1 d2 hcar hp; lia]).
        -- simpl negb in h.
           destruct (symCarry rest) as [[[f' cf] mf]|] eqn:hsc; [| discriminate].
           assert (hmg : 5 * i + a2 / 2 + b2 + mf + 1 <= minG /\ 5 * i + a2 / 2 + 2 <= minG)
             by (destruct (Nat.eqb (a2 mod 2) 1); cbv beta iota zeta in h; inv_some h; lia).
           pose proof (mirror_eat_odd_b0_h0 K_cur a2 b2' d1 d2 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) as hcar.
           replace (2 * K_cur + 1) with (2 * k + 1 + dam) in hcar by lia.
           replace (2 * K_cur + 2 + a2) with (2 * k + 1 + (dam + 1 + a2)) in hcar by lia.
           replace (K_cur - (E0 + 5 * i) + (E0 + 5 * i + 3 - (E0 + 5 * i)) - (a2 / 2 + b2' + 1))
             with (G + ((1 + dam) / 2 + 3) - (5 * i + a2 / 2 + b2)) in hcar by lia.
           rewrite <- hb2_eq in hcar.
           destruct (symCarry_sound rest hsc (OneBlock_toWeak (DirectBlock_toOneBlock hcar)) ltac:(lia))
             as [es [hp [hsum hcf_le]]].
           cbn [sumList] in hsum.
           destruct (Nat.eqb (a2 mod 2) 1);
             cbv beta iota zeta in h; inv_some h; subst dam' hm' bm' front' addE subE minG;
             exists es;
             (split; [cbn [encFront]; rewrite ?append_assoc in hp; rewrite ?append_assoc; exact hp
                     | clear d1 d2 hcar hp hsc; lia]).
      * destruct ((negb hm && Nat.eqb bm 1 && negb (Nat.eqb ((1 + dam) mod 2) 1) && Nat.leb 1 a2)%bool)
          eqn:hc3b; [| discriminate].
        repeat match goal with
        | H : (_ && _)%bool = true |- _ => apply Bool.andb_true_iff in H; destruct H
        | H : negb (Nat.eqb _ _) = true |- _ => apply Bool.negb_true_iff in H; apply Nat.eqb_neq in H
        | H : negb _ = true |- _ => apply Bool.negb_true_iff in H
        | H : Nat.eqb _ _ = true |- _ => apply Nat.eqb_eq in H
        | H : Nat.leb _ _ = true |- _ => apply Nat.leb_le in H
        end; subst hm bm.
        set (a2' := a2 - 1).
        assert (ha2_eq : a2 = a2' + 1) by (unfold a2'; lia).
        fold a2' in h.
        destruct h2.
        -- simpl negb in h.
           destruct (frontValid rest) eqn:hfv; [| discriminate].
           assert (hmg : 5 * i + a2' / 2 + 3 <= minG)
             by (destruct (Nat.eqb (a2' mod 2) 1); cbv beta iota zeta in h; inv_some h; lia).
           pose proof (mirror_eat_even_b1_h1 K_cur a2' b2' d1 d2 ltac:(lia) ltac:(lia) ltac:(lia)) as hcar.
           replace (2 * K_cur + 3 + a2') with (2 * k + 1 + (dam + 2 + a2)) in hcar by lia.
           replace (2 * K_cur) with (2 * k + 1 + dam) in hcar by lia.
           replace (K_cur - (E0 + 5 * i) + (E0 + 5 * i + 3 - (E0 + 5 * i)) - (a2' / 2 + 1))
             with (G + ((1 + dam) / 2 + 3) - (5 * i + a2' / 2 + 1)) in hcar by lia.
           rewrite <- ha2_eq, <- hb2_eq in hcar.
           pose proof (PureP2W_liftFront rest hfv hcar) as hp.
           destruct (Nat.eqb (a2' mod 2) 1);
             cbv beta iota zeta in h; inv_some h; subst dam' hm' bm' front' addE subE minG;
             exists [G + ((1 + dam) / 2 + 3) - (5 * i + a2' / 2 + 1)];
             (split; [cbn [encFront]; rewrite ?append_assoc in hp; rewrite ?append_assoc; exact hp
                     | cbn [sumList]; clear d1 d2 hcar hp; lia]).
        -- simpl negb in h.
           destruct (symCarry rest) as [[[f' cf] mf]|] eqn:hsc; [| discriminate].
           assert (hmg : 5 * i + a2' / 2 + b2 + 1 + mf + 1 <= minG /\ 5 * i + a2' / 2 + 3 <= minG)
             by (destruct (Nat.eqb (a2' mod 2) 1); cbv beta iota zeta in h; inv_some h; lia).
           pose proof (mirror_eat_even_b1_h0 K_cur a2' b2' d1 d2 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) as hcar.
           replace (2 * K_cur + 2 + a2') with (2 * k + 1 + (dam + 1 + a2)) in hcar by lia.
           replace (2 * K_cur) with (2 * k + 1 + dam) in hcar by lia.
           replace (K_cur - (E0 + 5 * i) + (E0 + 5 * i + 3 - (E0 + 5 * i)) - (a2' / 2 + b2' + 2))
             with (G + ((1 + dam) / 2 + 3) - (5 * i + a2' / 2 + b2 + 1)) in hcar by lia.
           rewrite <- ha2_eq, <- hb2_eq in hcar.
           destruct (symCarry_sound rest hsc (OneBlock_toWeak (DirectBlock_toOneBlock hcar)) ltac:(lia))
             as [es [hp [hsum hcf_le]]].
           cbn [sumList] in hsum.
           destruct (Nat.eqb (a2' mod 2) 1);
             cbv beta iota zeta in h; inv_some h; subst dam' hm' bm' front' addE subE minG;
             exists es;
             (split; [cbn [encFront]; rewrite ?append_assoc in hp; rewrite ?append_assoc; exact hp
                     | clear d1 d2 hcar hp hsc; lia]).
Qed.

Lemma symMirrorRun_sound (n : nat) :
    forall (i E0_base m0 b0_v k : nat) (sp0 : list RleItem)
    (hsp0 : isTranspList sp0 = true)
    {st st' : MirrorSymState} {sumAdd sumSub minG : nat}
    (h : symMirrorRun n i st = Some (st', sumAdd, sumSub, minG))
    (hb0 : 2 * n + 3 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + 1 <= m0)
    (hEbase : m0 - b0_v - transpListCost_nat sp0 = E0_base + 5 * i)
    (hE0 : 1 <= E0_base) (hgap : minG <= k - E0_base) (hE0k : E0_base + minG <= k),
    let '(dam, hm, bm, front) := st in
    let '(dam', hm', bm', front') := st' in
    exists es,
      PureP2W
        (((encS (2 * m0) true b0_v [] None ++ encItems sp0)
          ++ encS (2 * k + 1 + dam) hm bm [] None) ++ encFront front)
        (((encS (2 * (m0 + 3 * n)) true (b0_v - 2 * n) [] None ++ encItems sp0)
          ++ encS (2 * k + 1 + dam') hm' bm' [] None) ++ encFront front')
        es /\
      sumList es + sumSub = n * (k - E0_base) + sumAdd.
Proof.
  induction n as [|n' IH];
    intros i E0_base m0 b0_v k sp0 hsp0 st st' sumAdd sumSub minG h hb0 hle0 hEbase hE0 hgap hE0k.
  - cbn [symMirrorRun] in h; inv_some h; subst st' sumAdd sumSub minG.
    destruct st as [[[dam hm] bm] front].
    cbv beta iota zeta.
    exists (@nil nat).
    replace (m0 + 3 * 0) with m0 by lia.
    replace (b0_v - 2 * 0) with b0_v by lia.
    split; [exact (PureP2W_nil _) | cbn [sumList]; lia].
  - cbn [symMirrorRun] in h.
    destruct (symMirrorStep i st) as [[[[st1 a1] s1] mg1]|] eqn:hs1; [| discriminate].
    destruct (symMirrorRun n' (i + 1) st1) as [[[[st2 a2] s2] mg2]|] eqn:hs2; [| discriminate].
    inv_some h; subst st2 sumAdd sumSub minG.
    destruct st as [[[dam hm] bm] front].
    destruct st1 as [[[dam1 hm1] bm1] front1].
    destruct st' as [[[dam2 hm2] bm2] front2].
    cbv beta iota zeta.
    destruct (c0_sp0_2hubs m0 b0_v sp0 hsp0 ltac:(lia) hle0) as [Wm [d1 d2]].
    try (rewrite hEbase in d1); try (rewrite hEbase in d2).
    pose proof (symMirrorStep_sound (E0 := E0_base) (k := k) hs1 d1 d2 hE0 ltac:(lia) ltac:(lia)) as Hms.
    cbv beta iota zeta in Hms.
    destruct Hms as [es1 [hp1 [hsum1 _]]].
    pose proof (IH (i + 1) E0_base (m0 + 3) (b0_v - 2) k sp0 hsp0
                  _ _ _ _ _ hs2 ltac:(lia) ltac:(lia) ltac:(lia) hE0 ltac:(lia) ltac:(lia)) as Hmr.
    cbv beta iota zeta in Hmr.
    destruct Hmr as [es2 [hp2 hsum2]].
    replace (m0 + 3 + 3 * n') with (m0 + 3 * S n') in hp2 by lia.
    replace (b0_v - 2 - 2 * n') with (b0_v - 2 * S n') in hp2 by lia.
    exists (es1 ++ es2).
    split; [exact (PureP2W_append hp1 hp2) |].
    rewrite sumList_append.
    cbn [Nat.mul]; set (G0 := k - E0_base) in *; clearbody G0; clear - hsum1 hsum2; lia.
Qed.

Definition m162_front_in : list FrontCell :=
  [(8, true, 32); (3, true, 38); (2, true, 38);
   (1, true, 40); (1, true, 39); (1, true, 40); (1, true, 39)].

Definition m162_front_out : list FrontCell :=
  [(8, true, 32); (3, true, 38); (2, true, 38)].

Lemma m162_sym_eval :
  symMirrorRun 81 0 (0, true, 20, m162_front_in) =
  Some ((166, true, 20, m162_front_out), 3221, (18 * 1000 + 798), 500).
Proof. vm_compute. reflexivity. Qed.

Lemma m162_1cycle (m0 b0_v k pr : nat) (sp0 : list RleItem)
    (hsp0 : isTranspList sp0 = true)
    (hb0 : 165 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + 1 <= m0)
    (hpr : 2 <= pr)
    (hgap : 500 <= k - (m0 - b0_v - transpListCost_nat sp0))
    (hE0k : (m0 - b0_v - transpListCost_nat sp0) + 500 <= k) :
    exists es_tot,
      PureP2W
        ((((((encS (2 * m0) true b0_v [] None ++ encItems sp0)
          ++ encS (2 * k + 1) true 20 [] None)
          ++ encS 8 true 32 [] None) ++ encS 3 true 38 [] None) ++ encS 2 true 38 [] None)
          ++ encPairRun_nat 1 true 40 1 true 39 pr)
        ((((((encS (2 * (m0 + 243)) true (b0_v - 162) [] None ++ encItems sp0)
          ++ encS (2 * (k + 83) + 1) true 20 [] None)
          ++ encS 8 true 32 [] None) ++ encS 3 true 38 [] None) ++ encS 2 true 38 [] None)
          ++ encPairRun_nat 1 true 40 1 true 39 (pr - 2))
        es_tot /\
      sumList es_tot = 81 * (k - (m0 - b0_v - transpListCost_nat sp0)) - (15 * 1000 + 577).
Proof.
  pose proof (symMirrorRun_sound 81 0 (m0 - b0_v - transpListCost_nat sp0) m0 b0_v k sp0 hsp0
                m162_sym_eval ltac:(lia) hle0 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) as Hmr.
  cbv beta iota zeta in Hmr.
  destruct Hmr as [es [hp hsum]].
  pose proof (PureP2W_liftPairRun 1 40 1 39 (pr - 2) hp) as hp'.
  assert (hEncIn : encFront m162_front_in =
                   ((encS 8 true 32 [] None ++ encS 3 true 38 [] None) ++ encS 2 true 38 [] None)
                     ++ encPairRun_nat 1 true 40 1 true 39 2).
  { assert (hp2 : forall u : list Sym, u ^^ 2 = u ++ u)
      by (intros u; change 2 with (1 + 1); rewrite (list_pow_add u 1 1), !list_pow_one; reflexivity).
    unfold m162_front_in, encPairRun_nat; cbn [encFront].
    rewrite hp2, ?app_nil_r, ?append_assoc. reflexivity. }
  assert (hEncOut : encFront m162_front_out =
                    (encS 8 true 32 [] None ++ encS 3 true 38 [] None) ++ encS 2 true 38 [] None).
  { unfold m162_front_out; cbn [encFront]. rewrite ?app_nil_r, ?append_assoc. reflexivity. }
  assert (hPRsplit : encPairRun_nat 1 true 40 1 true 39 2 ++ encPairRun_nat 1 true 40 1 true 39 (pr - 2) =
                     encPairRun_nat 1 true 40 1 true 39 pr).
  { unfold encPairRun_nat; fold_pow_add; replace (2 + (pr - 2)) with pr by lia; reflexivity. }
  replace (2 * k + 1 + 0) with (2 * k + 1) in hp' by lia.
  replace (2 * k + 1 + 166) with (2 * (k + 83) + 1) in hp' by lia.
  replace (m0 + 3 * 81) with (m0 + 243) in hp' by lia.
  replace (b0_v - 2 * 81) with (b0_v - 162) in hp' by lia.
  rewrite hEncIn, hEncOut in hp'.
  exists es. split.
  - assert (hL : ((((encS (2 * m0) true b0_v [] None ++ encItems sp0) ++ encS (2 * k + 1) true 20 [] None)
                  ++ (((encS 8 true 32 [] None ++ encS 3 true 38 [] None) ++ encS 2 true 38 [] None)
                      ++ encPairRun_nat 1 true 40 1 true 39 2))
                  ++ encPairRun_nat 1 true 40 1 true 39 (pr - 2)) =
                 ((((((encS (2 * m0) true b0_v [] None ++ encItems sp0)
                  ++ encS (2 * k + 1) true 20 [] None)
                  ++ encS 8 true 32 [] None) ++ encS 3 true 38 [] None) ++ encS 2 true 38 [] None)
                  ++ encPairRun_nat 1 true 40 1 true 39 pr)).
    { rewrite <- hPRsplit, ?append_assoc. reflexivity. }
    assert (hR : ((((encS (2 * (m0 + 243)) true (b0_v - 162) [] None ++ encItems sp0)
                  ++ encS (2 * (k + 83) + 1) true 20 [] None)
                  ++ ((encS 8 true 32 [] None ++ encS 3 true 38 [] None) ++ encS 2 true 38 [] None))
                  ++ encPairRun_nat 1 true 40 1 true 39 (pr - 2)) =
                 ((((((encS (2 * (m0 + 243)) true (b0_v - 162) [] None ++ encItems sp0)
                  ++ encS (2 * (k + 83) + 1) true 20 [] None)
                  ++ encS 8 true 32 [] None) ++ encS 3 true 38 [] None) ++ encS 2 true 38 [] None)
                  ++ encPairRun_nat 1 true 40 1 true 39 (pr - 2))).
    { rewrite ?append_assoc. reflexivity. }
    rewrite hL, hR in hp'. exact hp'.
  - set (G := k - (m0 - b0_v - transpListCost_nat sp0)) in *; clearbody G; clear - hgap hsum; lia.
Qed.

Definition m162Stot_nat (m0 b0_v sp0_c k Mv : nat) : nat :=
  let dS0 := 81 * (k - (m0 - b0_v - sp0_c)) - (15 * 1000 + 577) in
  Mv * dS0 - (13 * 1000 + 41) * Mv * (Mv - 1).

Lemma m162Stot_to_nat (m0 b0_v sp0_c k Mv : N) :
  N.to_nat (m162Stot m0 b0_v sp0_c k Mv) =
  m162Stot_nat (N.to_nat m0) (N.to_nat b0_v) (N.to_nat sp0_c)
    (N.to_nat k) (N.to_nat Mv).
Proof.
  unfold m162Stot, m162Stot_nat; cbv zeta.
  repeat (rewrite N2Nat.inj_add || rewrite N2Nat.inj_mul || rewrite N2Nat.inj_sub).
  assert (hc1 : N.to_nat 15577%N = 15 * 1000 + 577) by (clear; lia).
  assert (hc2 : N.to_nat 13041%N = 13 * 1000 + 41) by (clear; lia).
  change (N.to_nat 81%N) with 81.
  change (N.to_nat 1%N) with 1.
  rewrite hc1, hc2. reflexivity.
Qed.

Lemma m162_Mcycles (Mv : nat) :
    forall (m0 b0_v k pr : nat) (sp0 : list RleItem)
    (hsp0 : isTranspList sp0 = true)
    (hb0 : 162 * Mv + 3 <= b0_v) (hle0 : b0_v + transpListCost_nat sp0 + 1 <= m0)
    (hpr : 2 * Mv <= pr)
    (hE0k : (m0 - b0_v - transpListCost_nat sp0) + 322 * Mv + 500 <= k),
    exists es_tot,
      PureP2W
        ((((((encS (2 * m0) true b0_v [] None ++ encItems sp0)
          ++ encS (2 * k + 1) true 20 [] None)
          ++ encS 8 true 32 [] None) ++ encS 3 true 38 [] None) ++ encS 2 true 38 [] None)
          ++ encPairRun_nat 1 true 40 1 true 39 pr)
        ((((((encS (2 * (m0 + 243 * Mv)) true (b0_v - 162 * Mv) [] None ++ encItems sp0)
          ++ encS (2 * (k + 83 * Mv) + 1) true 20 [] None)
          ++ encS 8 true 32 [] None) ++ encS 3 true 38 [] None) ++ encS 2 true 38 [] None)
          ++ encPairRun_nat 1 true 40 1 true 39 (pr - 2 * Mv))
        es_tot /\
      sumList es_tot = m162Stot_nat m0 b0_v (transpListCost_nat sp0) k Mv.
Proof.
  induction Mv as [|M' IH]; intros m0 b0_v k pr sp0 hsp0 hb0 hle0 hpr hE0k.
  - exists (@nil nat).
    replace (m0 + 243 * 0) with m0 by (clear; lia).
    replace (b0_v - 162 * 0) with b0_v by (clear; lia).
    replace (k + 83 * 0) with k by (clear; lia).
    replace (pr - 2 * 0) with pr by (clear; lia).
    split; [exact (PureP2W_nil _) | cbn [sumList]; unfold m162Stot_nat; cbv zeta; clear; lia].
  - assert (hE0_step : (m0 + 243) - (b0_v - 162) - transpListCost_nat sp0 =
                       (m0 - b0_v - transpListCost_nat sp0) + 405)
      by (clear - hb0 hle0; lia).
    assert (hE0k_next : ((m0 + 243) - (b0_v - 162) - transpListCost_nat sp0) + 322 * M' + 500 <= k + 83).
    { rewrite hE0_step; set (E0 := m0 - b0_v - transpListCost_nat sp0) in *;
      clearbody E0; clear - hE0k; lia. }
    destruct (m162_1cycle m0 b0_v k pr sp0 hsp0
                ltac:(clear - hb0; lia) hle0 ltac:(clear - hpr; lia)
                ltac:(set (E0 := m0 - b0_v - transpListCost_nat sp0) in *; clearbody E0; clear - hE0k; lia)
                ltac:(set (E0 := m0 - b0_v - transpListCost_nat sp0) in *; clearbody E0; clear - hE0k; lia))
      as [es1 [hp1 hsum1]].
    destruct (IH (m0 + 243) (b0_v - 162) (k + 83) (pr - 2) sp0 hsp0
                ltac:(clear - hb0; lia) ltac:(clear - hb0 hle0; lia) ltac:(clear - hpr; lia) hE0k_next)
      as [es2 [hp2 hsum2]].
    replace (m0 + 243 + 243 * M') with (m0 + 243 * S M') in hp2 by (clear; lia).
    replace (b0_v - 162 - 162 * M') with (b0_v - 162 * S M') in hp2 by (clear; lia).
    replace (k + 83 + 83 * M') with (k + 83 * S M') in hp2 by (clear; lia).
    replace (pr - 2 - 2 * M') with (pr - 2 * S M') in hp2 by (clear; lia).
    exists (es1 ++ es2). split; [exact (PureP2W_append hp1 hp2) |].
    rewrite sumList_append, hsum1, hsum2.
    unfold m162Stot_nat; cbv zeta.
    set (G := k - (m0 - b0_v - transpListCost_nat sp0)) in *.
    set (d0 := 81 * G - (15 * 1000 + 577)) in *.
    assert (hd0_ge : (26 * 1000 + 82) * M' <= d0)
      by (assert (hG_ge : 322 * S M' + 500 <= G) by (clear - hE0k; unfold G; lia);
          clear - hG_ge; unfold d0; clearbody G; lia).
    assert (hd1 : 81 * ((k + 83) - ((m0 + 243) - (b0_v - 162) - transpListCost_nat sp0)) - (15 * 1000 + 577) =
                  d0 - (26 * 1000 + 82)).
    { replace ((m0 + 243) - (b0_v - 162) - transpListCost_nat sp0)
        with ((m0 - b0_v - transpListCost_nat sp0) + 405) by (clear - hb0 hle0; lia).
      replace ((k + 83) - ((m0 - b0_v - transpListCost_nat sp0) + 405))
        with (G - 322) by (clear - hE0k; unfold G; lia).
      assert (hG_ge : 322 * S M' + 500 <= G) by (clear - hE0k; unfold G; lia).
      clear - hG_ge; unfold d0; clearbody G; lia. }
    rewrite hd1.
    destruct M' as [|M'']; [cbn [Nat.sub Nat.mul]; rewrite ?Nat.sub_0_r; clearbody d0; clear; lia |].
    set (rem := d0 - (26 * 1000 + 82) * S M'').
    assert (hd0_eq : d0 = rem + (26 * 1000 + 82) * S M'') by (unfold rem; clear - hd0_ge; clearbody d0; lia).
    rewrite hd0_eq; clearbody rem; clear.
    replace (S M'' - 1) with M'' by lia.
    replace (S (S M'') - 1) with (S M'') by lia.
    replace (rem + (26 * 1000 + 82) * S M'' - (26 * 1000 + 82)) with (rem + (26 * 1000 + 82) * M'') by lia.
    assert (hsub1 : S M'' * (rem + (26 * 1000 + 82) * M'') =
                    (S M'' * rem + (13 * 1000 + 41) * S M'' * M'') + (13 * 1000 + 41) * S M'' * M'') by nia.
    assert (hsub2 : S (S M'') * (rem + (26 * 1000 + 82) * S M'') =
                    (S (S M'') * rem + (13 * 1000 + 41) * S (S M'') * S M'') + (13 * 1000 + 41) * S (S M'') * S M'') by nia.
    rewrite hsub1, hsub2, !Nat.add_sub. nia.
Qed.

Lemma stepMirror162_sound (k0 : nat) (Mv : N) (items items' : list RleItem)
    (h : stepMirror162 k0 Mv items = Some items') :
    (HubCfg items) -[ tm ]->* (HubCfg items').
Proof.
  unfold stepMirror162 in h.
  destruct items as [|x0 rest0]; [discriminate |].
  destruct x0 as [a0 [|] b0_v [|? ?] [?|] | | |]; try discriminate.
  destruct (negb (a0 mod 2 =? 0)%N) eqn:ha0; [discriminate |].
  apply Bool.negb_false_iff in ha0; apply N.eqb_eq in ha0.
  destruct (splitAtList k0 rest0) as [[sp0 rest1]|] eqn:hs0; [| discriminate].
  destruct (negb (isTranspList sp0)) eqn:hsp0; [discriminate |].
  apply Bool.negb_false_iff in hsp0.
  destruct rest1 as [|xm r1]; [discriminate |].
  destruct xm as [am [|] bm [|? ?] [?|] | | |]; try discriminate.
  destruct r1 as [|xu1 r2]; [discriminate |].
  destruct xu1 as [u1 [|] ub1 [|? ?] [?|] | | |]; try discriminate.
  destruct r2 as [|xu2 r3]; [discriminate |].
  destruct xu2 as [u2 [|] ub2 [|? ?] [?|] | | |]; try discriminate.
  destruct r3 as [|xu3 r4]; [discriminate |].
  destruct xu3 as [u3 [|] ub3 [|? ?] [?|] | | |]; try discriminate.
  destruct r4 as [|xpr tail]; [discriminate |].
  destruct xpr as [| | pa1 [|] pb1 pa2 [|] pb2 pr |]; try discriminate.
  destruct (((am mod 2 =? 1)%N && (bm =? 20)%N &&
             (u1 =? 8)%N && (ub1 =? 32)%N && (u2 =? 3)%N && (ub2 =? 38)%N && (u3 =? 2)%N && (ub3 =? 38)%N &&
             (pa1 =? 1)%N && (pb1 =? 40)%N && (pa2 =? 1)%N && (pb2 =? 39)%N)%bool)
    eqn:hpat; [| discriminate].
  split_andb; subst bm u1 ub1 u2 ub2 u3 ub3 pa1 pb1 pa2 pb2.
  cbv zeta in h.
  destruct (((162 * Mv + 3 <=? b0_v)%N && (b0_v + transpListCost sp0 + 1 <=? a0 / 2)%N &&
             (2 * Mv <=? pr)%N &&
             ((a0 / 2 - b0_v - transpListCost sp0) + 322 * Mv + 500 <=? am / 2)%N)%bool)
    eqn:hcond; [| discriminate].
  split_andb.
  destruct (applySinkDumpBig (m162Stot (a0 / 2) b0_v (transpListCost sp0) (am / 2) Mv) tail)
    as [tail'|] eqn:hd; [| discriminate].
  inv_some h; subst items'.
  pose proof (splitAtList_sound _ _ _ _ hs0) as hr0; subst rest0.
  pose proof (N2Nat_div a0 2) as Ha0div; change (N.to_nat 2%N) with 2 in Ha0div.
  pose proof (N2Nat_mod a0 2) as Ha0mod; change (N.to_nat 2%N) with 2 in Ha0mod.
  pose proof (N2Nat_div am 2) as Hamdiv; change (N.to_nat 2%N) with 2 in Hamdiv.
  pose proof (N2Nat_mod am 2) as Hammod; change (N.to_nat 2%N) with 2 in Hammod.
  assert (ha0_par : N.to_nat a0 = 2 * (N.to_nat a0 / 2))
    by (clear - ha0 Ha0mod; pose proof (Nat.div_mod (N.to_nat a0) 2 ltac:(lia)); lia).
  assert (ham_par : N.to_nat am = 2 * (N.to_nat am / 2) + 1)
    by (match goal with H : (am mod 2 = 1)%N |- _ => clear - H Hammod end;
        pose proof (Nat.div_mod (N.to_nat am) 2 ltac:(lia)); lia).
  clear Ha0mod Hammod ha0 hs0.
  assert (hE0_nat : N.to_nat (a0 / 2 - b0_v - transpListCost sp0)%N =
                    N.to_nat a0 / 2 - N.to_nat b0_v - transpListCost_nat sp0)
    by (unfold transpListCost_nat; rewrite !N2Nat.inj_sub, Ha0div; reflexivity).
  destruct (m162_Mcycles (N.to_nat Mv) (N.to_nat a0 / 2) (N.to_nat b0_v)
              (N.to_nat am / 2) (N.to_nat pr) sp0 hsp0
              ltac:(lia) ltac:(unfold transpListCost_nat; lia) ltac:(lia)
              ltac:(rewrite <- hE0_nat, <- Hamdiv;
                    set (E0n := (a0 / 2 - b0_v - transpListCost sp0)%N) in *; clearbody E0n; lia))
    as [es_tot [hpw hsum]].
  pose proof (applySinkDumpBig_sound hd) as hdump.
  rewrite m162Stot_to_nat, Ha0div, Hamdiv in hdump.
  unfold transpListCost_nat in hsum.
  rewrite <- hsum in hdump.
  pose proof (PureP2W_dump hpw hdump) as hrun.
  clear - hrun ha0_par ham_par.
  replace (2 * (N.to_nat a0 / 2)) with (N.to_nat a0) in hrun by lia.
  replace (2 * (N.to_nat am / 2) + 1) with (N.to_nat am) in hrun by lia.
  replace (2 * (N.to_nat a0 / 2 + 243 * N.to_nat Mv))
    with (N.to_nat (a0 + 486 * Mv)%N) in hrun
    by (rewrite N2Nat.inj_add, N2Nat.inj_mul; change (N.to_nat 486%N) with 486; lia).
  replace (N.to_nat b0_v - 162 * N.to_nat Mv)
    with (N.to_nat (b0_v - 162 * Mv)%N) in hrun
    by (rewrite N2Nat.inj_sub, N2Nat.inj_mul; change (N.to_nat 162%N) with 162; reflexivity).
  replace (2 * (N.to_nat am / 2 + 83 * N.to_nat Mv) + 1)
    with (N.to_nat (am + 166 * Mv)%N) in hrun
    by (rewrite N2Nat.inj_add, N2Nat.inj_mul; change (N.to_nat 166%N) with 166; lia).
  replace (N.to_nat pr - 2 * N.to_nat Mv)
    with (N.to_nat (pr - 2 * Mv)%N) in hrun
    by (rewrite N2Nat.inj_sub, N2Nat.inj_mul; change (N.to_nat 2%N) with 2; reflexivity).
  unfold HubCfg.
  repeat (cbn [encItems app]; simp_encItems_app); cbn [encItems];
    rewrite !encItem_pairRun_eq; cbn [encItem];
    rewrite !encSingle_eq_encS; cbn [option_map N.to_nat Pos.to_nat].
  rewrite ?append_assoc, ?Str_app_assoc.
  rewrite ?append_assoc, ?Str_app_assoc in hrun.
  exact hrun.
Qed.

(* --- ScratchS6A1.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

(* ========================================================================= *)
(* Boolean Equality Deciders                                                 *)
(* ========================================================================= *)

Lemma list_eqb_eq {A : Type} (eqb : A -> A -> bool)
    (heqb : forall x y : A, eqb x y = true <-> x = y) :
    forall xs ys : list A, list_eqb eqb xs ys = true <-> xs = ys.
Proof.
  induction xs as [|x xs' IH]; intros [|y ys']; simpl.
  - split; reflexivity.
  - split; discriminate.
  - split; discriminate.
  - rewrite Bool.andb_true_iff, heqb, IH.
    split.
    + intros [-> ->]. reflexivity.
    + intros H; inversion H; split; reflexivity.
Qed.

Lemma option_eqb_eq {A : Type} (eqb : A -> A -> bool)
    (heqb : forall x y : A, eqb x y = true <-> x = y)
    (ox oy : option A) :
    option_eqb eqb ox oy = true <-> ox = oy.
Proof.
  destruct ox as [x|], oy as [y|]; simpl.
  - rewrite heqb. split; [intros ->; reflexivity | intros H; inversion H; reflexivity].
  - split; discriminate.
  - split; discriminate.
  - split; reflexivity.
Qed.

Lemma segPiece_eqb_eq (x y : SegPiece) :
    segPiece_eqb x y = true <-> x = y.
Proof.
  destruct x as [b1 | v1 v2 r1], y as [b2 | u1 u2 r2]; simpl.
  - rewrite N.eqb_eq. split; [intros ->; reflexivity | intros H; inversion H; reflexivity].
  - split; discriminate.
  - split; discriminate.
  - rewrite !Bool.andb_true_iff, !N.eqb_eq.
    split.
    + intros [[-> ->] ->]. reflexivity.
    + intros H; inversion H; auto.
Qed.

Lemma rleItem_eqb_eq (x y : RleItem) :
    rleItem_eqb x y = true <-> x = y.
Proof.
  destruct x as [a1 h1 s1 seg1 ar1 | a1 b1 r1 | a1 h1 b1 c1 j1 d1 r1 | t1 n1],
           y as [a2 h2 s2 seg2 ar2 | a2 b2 r2 | a2 h2 b2 c2 j2 d2 r2 | t2 n2];
    simpl; try (split; discriminate).
  - rewrite !Bool.andb_true_iff, !N.eqb_eq, Bool.eqb_true_iff,
      (list_eqb_eq _ segPiece_eqb_eq), (option_eqb_eq _ N.eqb_eq).
    split.
    + intros [[[[-> ->] ->] ->] ->]. reflexivity.
    + intros H; inversion H; subst; repeat split.
  - rewrite !Bool.andb_true_iff, !N.eqb_eq.
    split.
    + intros [[-> ->] ->]. reflexivity.
    + intros H; inversion H; subst; repeat split.
  - rewrite !Bool.andb_true_iff, !N.eqb_eq, !Bool.eqb_true_iff.
    split.
    + intros [[[[[[-> ->] ->] ->] ->] ->] ->]. reflexivity.
    + intros H; inversion H; subst; repeat split.
  - rewrite Bool.andb_true_iff, tok_eqb_eq, N.eqb_eq.
    split.
    + intros [-> ->]. reflexivity.
    + intros H; inversion H; subst; repeat split.
Qed.

(* ========================================================================= *)
(* Power-Shift Helpers for (k + 1)                                           *)
(* ========================================================================= *)

Lemma zPsr1 (w : list Sym) (k : nat) (b : Stream Sym) :
  (w ^^ (k + 1)) *> b = w *> (w ^^ k) *> b.
Proof. replace (k + 1) with (S k) by lia. apply zPsr. Qed.

Lemma zPal1 (w : list Sym) (k : nat) (b : Stream Sym) :
  (w ^^ k) *> w *> b = (w ^^ (k + 1)) *> b.
Proof. replace (k + 1) with (S k) by lia. apply zPal. Qed.

(* ========================================================================= *)
(* Phase-1 End-of-Tape & Asplit Pipeline Acceleration Lemmas                 *)
(* ========================================================================= *)

Lemma pipeL_end_p1_loop : forall (En : nat) {R_out : list Sym} {Lt : Stream Sym},
    PipeL En R_out Lt ->
    (([S1; S1] *> Lt) {{F}}> ([S0; S1; S0; S1; S0; S1] *> b0)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *> (R_out ++ (T4 ^^ En)) *> [S0; S1; S0; S1] *> b0)).
Proof.
  induction En as [|E' IH]; intros R_out Lt hp.
  - pose proof (PipeL_unwind hp ([S0; S1; S0; S1] *> b0)) as hunw.
    rewrite list_pow_zero, app_nil_r. exact hunw.
  - replace (S E') with (E' + 1) in hp |- * by lia.
    destruct (PipeL_pull hp) as [L1 [hpull hp1]].
    pose proof (hpull ([S1; S0; S1; S0; S1] *> b0)) as h1.
    pose proof (step_end_p1_next L1) as h2.
    pose proof (pipeL_t5 1 hp1) as hp1'.
    rewrite list_pow_one, zP1 in hp1'.
    pose proof (IH _ _ hp1') as h3.
    rewrite append_assoc, <- list_pow_succ in h3.
    exact (stepStar_trans h1 (stepStar_trans h2 h3)).
Qed.

Lemma pipeL_end_p1 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (hp : PipeL (En + 1) R_out Lt) :
    (([S1; S1] *> Lt) {{F}}> ([S0; S1; S0; S1] *> b0)) -[ tm ]->*
    (b0 {{E}}> (T2 *> T0 *> T1 *> (R_out ++ T5 ++ (T4 ^^ En)) *> [S0; S1; S0; S1] *> b0)).
Proof.
  destruct (PipeL_pull hp) as [L1 [hpull hp1]].
  pose proof (hpull ([S1; S0; S1] *> b0)) as h1.
  pose proof (step_end_p1_first L1) as h2.
  pose proof (pipeL_noT2_blk 0 0 hp1) as hp1'.
  rewrite !zPz, zLan, !app_nil_r in hp1'.
  pose proof (pipeL_end_p1_loop En hp1') as h3.
  rewrite append_assoc in h3.
  exact (stepStar_trans h1 (stepStar_trans h2 h3)).
Qed.

Lemma pull1_t3_t2 (k : nat) {L_in L_out l0 : Stream Sym}
    (h0 : L_in = T0 *> l0) (h : Pull1 L_in L_out) (r : Stream Sym) :
    (([S1; S1] *> (T3 ^^ k) *> L_in) {{F}}> (T2 *> r)) -[ tm ]->*
    (([S1; S1] *> (T3 ^^ k) *> T2 *> L_out) {{F}}> r).
Proof.
  destruct k as [|k'].
  - rewrite !zPz, !zLan.
    change (T2 *> r) with (T0 *> [S0; S1] *> r).
    exact (stepStar_trans (h ([S0; S1] *> r)) (step_post_pull_t2_k0 L_out r)).
  - assert (h1 : (([S1; S1] *> (T3 ^^ S k') *> L_in) {{F}}> (T2 *> r)) -[ tm ]->*
                 (((T3 ^^ S k') *> L_in) {{E}}> (T0 *> T0 *> T2 *> r))).
    { rewrite zPsr.
      exact (step_8A_head ([S1; S1] *> (T3 ^^ k') *> L_in) ([S0; S1] *> r)). }
    eapply stepStar_trans; [exact h1 |].
    assert (h2 : (((T3 ^^ S k') *> L_in) {{E}}> (T0 *> T0 *> T2 *> r)) -[ tm ]->*
                 (([S1; S1] *> L_in) {{F}}> ([S0; S1] *> (T2 ^^ k') *> T0 *> T2 *> r))).
    { replace (S k') with (k' + 1) by lia. rewrite h0.
      exact (rule_E_t3_to_Q5 k' l0 (T0 *> T2 *> r)). }
    eapply stepStar_trans; [exact h2 |].
    change ([S0; S1] *> (T2 ^^ k') *> T0 *> T2 *> r) with
      (T0 *> [S1] *> (T2 ^^ k') *> T0 *> T2 *> r).
    eapply stepStar_trans; [exact (h ([S1] *> (T2 ^^ k') *> T0 *> T2 *> r)) |].
    eapply stepStar_trans; [exact (post_pull_rt5 L_out ((T2 ^^ k') *> T0 *> T2 *> r)) |].
    eapply stepStar_trans; [exact (rule_C_1_t2 k' (T2 *> L_out) (T0 *> T2 *> r)) |].
    rewrite zPsr.
    exact (step_8A_tail ((T3 ^^ k') *> T2 *> L_out) r).
Qed.

Lemma rule_p1_t0_sweep (k aR : nat) (Lt r : Stream Sym) :
    (([S1; S1] *> (T3 ^^ k) *> T2 *> Lt) {{F}}> (T0 *> (T2 ^^ aR) *> [S0; S1] *> r)) -[ tm ]->*
    (([S1; S1] *> (T2 ^^ aR) *> (T3 ^^ (k + 2)) *> Lt) {{F}}> r).
Proof.
  assert (hq0 : (([S1; S1] *> (T3 ^^ k) *> T2 *> Lt) {{F}}> (T0 *> (T2 ^^ aR) *> [S0; S1] *> r)) -[ tm ]->*
                (([S1] *> Lt) {{A}}> ((T2 ^^ (k + 1)) *> [S0; S0] *> (T2 ^^ aR) *> [S0; S1] *> r))).
  { destruct k as [|k'].
    - simpl Nat.add. rewrite zPz, zLan, zP1.
      exact (step_p1_t0_k0 Lt ((T2 ^^ aR) *> [S0; S1] *> r)).
    - destruct (head0_t3_t0 k' ([S0; S1] *> Lt)) as [l0 hl0].
      assert (h1 : (([S1; S1] *> (T3 ^^ S k') *> T2 *> Lt) {{F}}> (T0 *> (T2 ^^ aR) *> [S0; S1] *> r)) -[ tm ]->*
                   (([S1; S1] *> (T3 ^^ k') *> T2 *> Lt) {{F}}> ([S0; S1] *> [S0; S0] *> (T2 ^^ aR) *> [S0; S1] *> r))).
      { rewrite zPsr. change (T2 *> Lt) with (T0 *> [S0; S1] *> Lt). rewrite hl0.
        exact (step_p1_t0_first l0 ((T2 ^^ aR) *> [S0; S1] *> r)). }
      eapply stepStar_trans; [exact h1 |].
      assert (h2 : (([S1; S1] *> (T3 ^^ k') *> T2 *> Lt) {{F}}> ([S0; S1] *> [S0; S0] *> (T2 ^^ aR) *> [S0; S1] *> r)) -[ tm ]->*
                   (([S1; S1] *> T2 *> Lt) {{F}}> ([S0; S1] *> (T2 ^^ k') *> [S0; S0] *> (T2 ^^ aR) *> [S0; S1] *> r))).
      { change (T2 *> Lt) with (T0 *> [S0; S1] *> Lt).
        exact (rule_q5_t3_unwind k' ([S0; S1] *> Lt) ([S0; S0] *> (T2 ^^ aR) *> [S0; S1] *> r)). }
      eapply stepStar_trans; [exact h2 |].
      eapply stepStar_trans; [exact (step_q5_t2_unwind Lt ((T2 ^^ k') *> [S0; S0] *> (T2 ^^ aR) *> [S0; S1] *> r)) |].
      replace (S k' + 1) with (S (S k')) by lia.
      rewrite !zPsr. apply evstep_refl. }
  eapply stepStar_trans; [exact hq0 |].
  eapply stepStar_trans; [exact (rule_q0_t2 (k + 1) Lt ([S0; S0] *> (T2 ^^ aR) *> [S0; S1] *> r)) |].
  eapply stepStar_trans; [exact (step_q0_00_to_q2 ((T3 ^^ (k + 1)) *> Lt) ((T2 ^^ aR) *> [S0; S1] *> r)) |].
  replace (k + 2) with ((k + 1) + 1) by lia.
  rewrite <- zPsr1.
  eapply stepStar_trans; [exact (rule_c0_t2 aR ((T3 ^^ ((k + 1) + 1)) *> Lt) ([S0; S1] *> r)) |].
  exact (step_q2_01_to_q5 ((T2 ^^ aR) *> (T3 ^^ ((k + 1) + 1)) *> Lt) r).
Qed.

Lemma rule_asplit_t5_even (j : nat) (Lt r : Stream Sym) :
    (([S1; S1] *> (T3 ^^ j) *> T2 *> Lt) {{F}}> (T5 *> T5 *> r)) -[ tm ]->*
    (([S1; S1] *> (T3 ^^ (j + 1)) *> Lt) {{F}}> (T5 *> T4 *> r)).
Proof.
  change (T5 *> T5 *> r) with ([S0; S1] *> T2 *> T5 *> r).
  assert (h1 : (([S1; S1] *> (T3 ^^ j) *> T2 *> Lt) {{F}}> ([S0; S1] *> T2 *> T5 *> r)) -[ tm ]->*
               (([S1; S1] *> T2 *> Lt) {{F}}> ([S0; S1] *> (T2 ^^ j) *> T2 *> T5 *> r))).
  { change (T2 *> Lt) with (T0 *> [S0; S1] *> Lt).
    exact (rule_q5_t3_unwind j ([S0; S1] *> Lt) (T2 *> T5 *> r)). }
  eapply stepStar_trans; [exact h1 |].
  eapply stepStar_trans; [exact (step_q5_t2_unwind Lt ((T2 ^^ j) *> T2 *> T5 *> r)) |].
  assert (hpow : T2 *> T2 *> (T2 ^^ j) *> T2 *> T5 *> r =
                 (T2 ^^ (j + 1)) *> T2 *> T2 *> T5 *> r).
  { rewrite zPal1. replace (j + 1) with (S j) by lia.
    rewrite <- !zPsr. replace (S (S (S j))) with (S j + 2) by lia.
    rewrite pow_add_blank, !zPsr, zPz, zLan. reflexivity. }
  rewrite hpow.
  eapply stepStar_trans; [exact (rule_q0_t2 (j + 1) Lt (T2 *> T2 *> T5 *> r)) |].
  exact (step_asplit_t5_even_tail ((T3 ^^ (j + 1)) *> Lt) r).
Qed.

Lemma rule_asplit_t5_odd (j p : nat) (Lt r : Stream Sym) :
    (([S1; S1] *> (T3 ^^ j) *> T2 *> Lt) {{F}}> (T5 *> (T4 ^^ p) *> T3 *> T4 *> r)) -[ tm ]->*
    (([S1; S1] *> (T3 ^^ (j + 1)) *> Lt) {{F}}> (T5 *> T5 *> (T4 ^^ p) *> T3 *> r)).
Proof.
  change (T5 *> (T4 ^^ p) *> T3 *> T4 *> r) with ([S0; S1] *> T2 *> (T4 ^^ p) *> T3 *> T4 *> r).
  assert (h1 : (([S1; S1] *> (T3 ^^ j) *> T2 *> Lt) {{F}}> ([S0; S1] *> T2 *> (T4 ^^ p) *> T3 *> T4 *> r)) -[ tm ]->*
               (([S1; S1] *> T2 *> Lt) {{F}}> ([S0; S1] *> (T2 ^^ j) *> T2 *> (T4 ^^ p) *> T3 *> T4 *> r))).
  { change (T2 *> Lt) with (T0 *> [S0; S1] *> Lt).
    exact (rule_q5_t3_unwind j ([S0; S1] *> Lt) (T2 *> (T4 ^^ p) *> T3 *> T4 *> r)). }
  eapply stepStar_trans; [exact h1 |].
  eapply stepStar_trans; [exact (step_q5_t2_unwind Lt ((T2 ^^ j) *> T2 *> (T4 ^^ p) *> T3 *> T4 *> r)) |].
  assert (hpow : T2 *> T2 *> (T2 ^^ j) *> T2 *> (T4 ^^ p) *> T3 *> T4 *> r =
                 (T2 ^^ (j + 3)) *> (T4 ^^ p) *> T3 *> T4 *> r).
  { rewrite zPal1. replace (j + 3) with (2 + (j + 1)) by lia.
    rewrite (pow_add_blank T2 2 (j + 1)), !zPsr, zPz, zLan. reflexivity. }
  rewrite hpow.
  eapply stepStar_trans; [exact (rule_q0_t2 (j + 3) Lt ((T4 ^^ p) *> T3 *> T4 *> r)) |].
  assert (ht3split : (T3 ^^ (j + 3)) *> Lt = T3 *> T3 *> (T3 ^^ (j + 1)) *> Lt).
  { replace (j + 3) with (2 + (j + 1)) by lia.
    rewrite pow_add_blank, !zPsr, zPz, zLan. reflexivity. }
  rewrite ht3split.
  assert (hhead : (T3 ^^ (j + 1)) *> Lt = T0 *> [S1; S1] *> (T3 ^^ j) *> Lt).
  { rewrite zPsr1. reflexivity. }
  destruct p as [|p'].
  - rewrite !zPz, !zLan, hhead.
    exact (step_asplit_t5_odd_p0 ([S1; S1] *> (T3 ^^ j) *> Lt) r).
  - rewrite (zPsr T4).
    eapply stepStar_trans; [exact (step_q0_t4_first (T3 *> (T3 ^^ (j + 1)) *> Lt) ((T4 ^^ p') *> T3 *> T4 *> r)) |].
    eapply stepStar_trans; [exact (rule_q0_t4_next p' (T4 *> T3 *> (T3 ^^ (j + 1)) *> Lt) (T3 *> T4 *> r)) |].
    destruct (head0_t5_t4 p' (T3 *> (T3 ^^ (j + 1)) *> Lt)) as [l' hl'].
    assert (hwall : (([S1] *> T2 *> (T5 ^^ p') *> T4 *> T3 *> (T3 ^^ (j + 1)) *> Lt) {{A}}> (T3 *> T4 *> r)) -[ tm ]->*
                    (([S1; S1] *> (T5 ^^ p') *> T4 *> T3 *> (T3 ^^ (j + 1)) *> Lt) {{F}}> ([S0; S1] *> T4 *> T3 *> r))).
    { rewrite hl'. exact (step_asplit_t5_odd_wall1 l' r). }
    eapply stepStar_trans; [exact hwall |].
    assert (hunw : (([S1; S1] *> (T5 ^^ p') *> T4 *> T3 *> (T3 ^^ (j + 1)) *> Lt) {{F}}> ([S0; S1] *> T4 *> T3 *> r)) -[ tm ]->*
                   (([S1; S1] *> (T3 ^^ (j + 1)) *> Lt) {{F}}> ([S0; S1] *> T2 *> T5 *> (T4 ^^ p') *> T4 *> T3 *> r))).
    { rewrite hhead.
      pose proof (unwind_noT2 p' 1 ([S1; S1] *> (T3 ^^ j) *> Lt) (T4 *> T3 *> r)) as hu.
      rewrite !zP1 in hu. exact hu. }
    eapply stepStar_trans; [exact hunw |].
    rewrite zPal.
    change ([S0; S1] *> T2 *> T5 *> (T4 ^^ S p') *> T3 *> r) with (T5 *> T5 *> (T4 ^^ S p') *> T3 *> r).
    apply evstep_refl.
Qed.

Lemma rule_asplit_pump_loop : forall (q j p : nat) (Lt r : Stream Sym),
    (([S1; S1] *> (T3 ^^ j) *> (T2 ^^ (2 * q)) *> Lt) {{F}}> (T5 *> (T4 ^^ p) *> T3 *> (T4 ^^ q) *> r)) -[ tm ]->*
    (([S1; S1] *> (T3 ^^ (j + 2 * q)) *> Lt) {{F}}> (T5 *> (T4 ^^ (p + q)) *> T3 *> r)).
Proof.
  induction q as [|q' IH]; intros j p Lt r.
  - replace (2 * 0) with 0 by lia. replace (j + 0) with j by lia. replace (p + 0) with p by lia.
    rewrite !zPz, !zLan. apply evstep_refl.
  - assert (ht2 : (T2 ^^ (2 * S q')) *> Lt = T2 *> T2 *> (T2 ^^ (2 * q')) *> Lt).
    { replace (2 * S q') with (2 + 2 * q') by lia.
      rewrite pow_add_blank, !zPsr, zPz, zLan. reflexivity. }
    rewrite ht2, (zPsr T4).
    eapply stepStar_trans; [exact (rule_asplit_t5_odd j p (T2 *> (T2 ^^ (2 * q')) *> Lt) ((T4 ^^ q') *> r)) |].
    eapply stepStar_trans; [exact (rule_asplit_t5_even (j + 1) ((T2 ^^ (2 * q')) *> Lt) ((T4 ^^ p) *> T3 *> (T4 ^^ q') *> r)) |].
    rewrite <- zPsr1.
    pose proof (IH (j + 2) (p + 1) Lt r) as hrec.
    replace (j + 2 + 2 * q') with (j + 2 * S q') in hrec by lia.
    replace (p + 1 + q') with (p + S q') in hrec by lia.
    replace (j + 1 + 1) with (j + 2) by lia.
    exact hrec.
Qed.

Lemma rule_asplit_t5_end (j q4 : nat) (Lt r : Stream Sym) :
    (([S1; S1] *> (T3 ^^ j) *> T2 *> Lt) {{F}}> (T5 *> (T4 ^^ q4) *> T3 *> r)) -[ tm ]->*
    (([S1; S1] *> (T5 ^^ q4) *> T4 *> (T3 ^^ (j + 2)) *> Lt) {{F}}> r).
Proof.
  change (T5 *> (T4 ^^ q4) *> T3 *> r) with ([S0; S1] *> T2 *> (T4 ^^ q4) *> T3 *> r).
  assert (h1 : (([S1; S1] *> (T3 ^^ j) *> T2 *> Lt) {{F}}> ([S0; S1] *> T2 *> (T4 ^^ q4) *> T3 *> r)) -[ tm ]->*
               (([S1; S1] *> T2 *> Lt) {{F}}> ([S0; S1] *> (T2 ^^ j) *> T2 *> (T4 ^^ q4) *> T3 *> r))).
  { change (T2 *> Lt) with (T0 *> [S0; S1] *> Lt).
    exact (rule_q5_t3_unwind j ([S0; S1] *> Lt) (T2 *> (T4 ^^ q4) *> T3 *> r)). }
  eapply stepStar_trans; [exact h1 |].
  eapply stepStar_trans; [exact (step_q5_t2_unwind Lt ((T2 ^^ j) *> T2 *> (T4 ^^ q4) *> T3 *> r)) |].
  assert (hpow : T2 *> T2 *> (T2 ^^ j) *> T2 *> (T4 ^^ q4) *> T3 *> r =
                 (T2 ^^ (j + 3)) *> (T4 ^^ q4) *> T3 *> r).
  { rewrite zPal1. replace (j + 3) with (2 + (j + 1)) by lia.
    rewrite (pow_add_blank T2 2 (j + 1)), !zPsr, zPz, zLan. reflexivity. }
  rewrite hpow.
  eapply stepStar_trans; [exact (rule_q0_t2 (j + 3) Lt ((T4 ^^ q4) *> T3 *> r)) |].
  assert (ht3split : (T3 ^^ (j + 3)) *> Lt = T3 *> (T3 ^^ (j + 2)) *> Lt).
  { replace (j + 3) with (S (j + 2)) by lia. apply zPsr. }
  rewrite ht3split.
  destruct q4 as [|q'].
  - rewrite !zPz, !zLan. exact (step_q0_t3_t3 ((T3 ^^ (j + 2)) *> Lt) r).
  - rewrite (zPsr T4).
    eapply stepStar_trans; [exact (step_q0_t4_first ((T3 ^^ (j + 2)) *> Lt) ((T4 ^^ q') *> T3 *> r)) |].
    eapply stepStar_trans; [exact (rule_q0_t4_next q' (T4 *> (T3 ^^ (j + 2)) *> Lt) (T3 *> r)) |].
    eapply stepStar_trans; [exact (step_q0_t2_t3 ((T5 ^^ q') *> T4 *> (T3 ^^ (j + 2)) *> Lt) r) |].
    rewrite <- zPsr. apply evstep_refl.
Qed.

Lemma pipeL_noT2_t2pairs {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (d b j k : nat) (hp : PipeL En R_out Lt) :
    PipeL (En + d) (((R_out ++ (T2 ^^ (j + 2 * d + k))) ++ T5) ++ (T4 ^^ b))
      ((T5 ^^ b) *> T4 *> (T3 ^^ j) *> (T2 ^^ (2 * d)) *> (T3 ^^ k) *> Lt).
Proof.
  revert j. induction d as [|d' IH]; intros j.
  - replace (En + 0) with En by lia. replace (2 * 0) with 0 by lia. replace (j + 0 + k) with (j + k) by lia.
    rewrite zPz, zLan, <- pow_add_blank.
    exact (pipeL_noT2_blk b (j + k) hp).
  - destruct (PipeL_head0 hp) as [l0 hl0].
    destruct (head0_t3_t0 k l0) as [lk hlk].
    destruct (head0_t2_t0 (2 * d') lk) as [lt hlt].
    destruct (head0_t5_t4 b ((T3 ^^ j) *> (T2 ^^ (2 * S d')) *> (T3 ^^ k) *> Lt)) as [l' hl'].
    assert (h2d : (T2 ^^ (2 * S d')) *> (T3 ^^ k) *> Lt =
                  T2 *> T2 *> (T2 ^^ (2 * d')) *> (T3 ^^ k) *> Lt).
    { replace (2 * S d') with (2 + 2 * d') by lia.
      rewrite pow_add_blank, !zPsr, zPz, zLan. reflexivity. }
    assert (hpull : Pull1
        ((T5 ^^ b) *> T4 *> (T3 ^^ j) *> (T2 ^^ (2 * S d')) *> (T3 ^^ k) *> Lt)
        ((T5 ^^ b) *> T4 *> (T3 ^^ (j + 2)) *> (T2 ^^ (2 * d')) *> (T3 ^^ k) *> Lt)).
    { rewrite h2d, hl0, hlk, hlt. exact (pull1_base b j lt). }
    pose proof (IH (j + 2)) as hnext.
    replace (j + 2 + 2 * d' + k) with (j + 2 * S d' + k) in hnext by lia.
    replace (En + S d') with ((En + d') + 1) by lia.
    exact (PipeL_mkS hl' hpull hnext).
Qed.

Lemma pipeL_p1_asplit_odd_even_small_s0 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m p d : nat) (h : bool) (hE : m + 1 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    let aL := 2 * m + 1 in
    let aR := 2 * (p + d + 1) + 2 in
    let s0 := p + (if h then 2 else 3) in
    exists Lt', PipeL (En - m - 1 + d) (((R_out ++ (T2 ^^ (aL + aR + 2))) ++ T5) ++ (T4 ^^ (p + 1))) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ aL) *> T0 *> (T2 ^^ aR) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> r).
Proof.
  intros aL aR s0.
  set (q := p + d + 1).
  destruct (pipeL_eat_t2_even (En := En) m 0 ltac:(lia) hp
    (T2 *> T0 *> (T2 ^^ (2 * q + 2)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) as [L1 [hp1 hs1]].
  rewrite zPz, zLan in hs1. replace (0 + 2 * m) with (2 * m) in hs1 by lia.
  assert (hE1eq : En - m = (En - m - 1) + 1) by lia.
  pose proof (pipeL_eqE hE1eq hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [L2 [hpull1 hp2]].
  pose proof (pull1_t3_t2 (2 * m) hl1 hpull1
    (T0 *> (T2 ^^ (2 * q + 2)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) as hs2.
  assert (hs34 : (([S1; S1] *> (T3 ^^ (2 * m)) *> T2 *> L2) {{F}}>
                   (T0 *> (T2 ^^ (2 * q + 2)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) -[ tm ]->*
                 (([S1; S1] *> T3 *> (T2 ^^ (2 * p)) *> T2 *> T2 *> T2 *> (T2 ^^ (2 * d)) *> (T3 ^^ (2 * m + 2)) *> L2) {{F}}>
                   (T5 *> T3 *> (T4 ^^ p) *> T4 *> r))).
  { assert (ht2split : (T2 ^^ (2 * q + 2)) *> (T3 ^^ (2 * m + 2)) *> L2 =
                       T2 *> (T2 ^^ (2 * p)) *> T2 *> T2 *> T2 *> (T2 ^^ (2 * d)) *> (T3 ^^ (2 * m + 2)) *> L2).
    { replace (2 * q + 2) with (1 + (2 * p + (1 + (1 + (1 + 2 * d))))) by (unfold q; lia).
      rewrite !pow_add_blank, !zP1. reflexivity. }
    destruct h.
    - assert (hT5split : T5 *> (T4 ^^ s0) *> r = [S0; S1] *> T2 *> T4 *> (T4 ^^ p) *> T4 *> r).
      { unfold s0. replace (p + 2) with (1 + (p + 1)) by lia.
        rewrite !pow_add_blank, !zP1. reflexivity. }
      rewrite hT5split.
      eapply stepStar_trans; [exact (rule_p1_t0_sweep (2 * m) (2 * q + 2) L2 _) |].
      rewrite ht2split. exact (step_asplit_pump_start_h1 _ _).
    - assert (hT4split : ([] : list Sym) *> (T4 ^^ s0) *> r = [S0; S1] *> T3 *> T4 *> (T4 ^^ p) *> T4 *> r).
      { rewrite zLan. unfold s0. replace (p + 3) with (1 + (1 + (p + 1))) by lia.
        rewrite !pow_add_blank, !zP1. reflexivity. }
      rewrite hT4split.
      eapply stepStar_trans; [exact (rule_p1_t0_sweep (2 * m) (2 * q + 2) L2 _) |].
      rewrite ht2split. exact (step_asplit_pump_start _ _). }
  pose proof (rule_asplit_pump_loop p 1 0
    (T2 *> T2 *> T2 *> (T2 ^^ (2 * d)) *> (T3 ^^ (2 * m + 2)) *> L2) (T4 *> r)) as hs5.
  replace (0 + p) with p in hs5 by lia. rewrite zPz, zLan, zP1 in hs5.
  pose proof (rule_asplit_t5_odd (1 + 2 * p) p
    (T2 *> T2 *> (T2 ^^ (2 * d)) *> (T3 ^^ (2 * m + 2)) *> L2) r) as hs6.
  pose proof (rule_asplit_t5_even (1 + 2 * p + 1)
    (T2 *> (T2 ^^ (2 * d)) *> (T3 ^^ (2 * m + 2)) *> L2) ((T4 ^^ p) *> T3 *> r)) as hs7.
  pose proof (rule_asplit_t5_end (1 + 2 * p + 1 + 1) (p + 1)
    ((T2 ^^ (2 * d)) *> (T3 ^^ (2 * m + 2)) *> L2) r) as hs8.
  pose proof (pipeL_noT2_t2pairs d (p + 1) (1 + 2 * p + 1 + 1 + 2) (2 * m + 2) hp2) as hp3.
  exists ((T5 ^^ (p + 1)) *> T4 *> (T3 ^^ (1 + 2 * p + 1 + 1 + 2)) *> (T2 ^^ (2 * d)) *> (T3 ^^ (2 * m + 2)) *> L2).
  split.
  - eapply pipeL_eqER; [exact hp3 | lia |].
    unfold aL, aR; f_equal; f_equal; f_equal; f_equal; lia.
  - unfold aL, aR. replace (2 * (p + d + 1) + 2) with (2 * q + 2) by (unfold q; lia).
    rewrite (pow_add_blank T2 (2 * m) 1), zP1.
    eapply stepStar_trans; [exact hs1 |].
    eapply stepStar_trans; [exact hs2 |].
    eapply stepStar_trans; [exact hs34 |].
    eapply stepStar_trans; [exact hs5 |].
    eapply stepStar_trans; [exact hs6 |].
    eapply stepStar_trans; [exact hs7 |].
    rewrite <- (zPsr1 T4). exact hs8.
Qed.

Lemma pipeL_T2_mid_t3 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (b j k : nat) (hp : PipeL En R_out Lt) :
    PipeL En ((R_out ++ (T2 ^^ (j + k + 1))) ++ (T4 ^^ (b + 1)))
      ((T5 ^^ b) *> T4 *> (T3 ^^ j) *> T2 *> (T3 ^^ k) *> Lt).
Proof.
  destruct hp as [R_out Lt l0 h0 hunw | E' R_out Lt Lt' l0 h0 hpull hnext].
  - destruct (head0_t3_t0 k l0) as [lk hlk].
    destruct (head0_t5_t4 b ((T3 ^^ j) *> T2 *> (T3 ^^ k) *> Lt)) as [l' hl'].
    eapply PipeL_mk0; [exact hl' |].
    intros r.
    assert (h1 : (([S1; S1] *> (T5 ^^ b) *> T4 *> (T3 ^^ j) *> T2 *> (T3 ^^ k) *> Lt) {{F}}> ([S0; S1] *> r)) -[ tm ]->*
                 (([S1; S1] *> (T3 ^^ k) *> Lt) {{F}}> ([S0; S1] *> (T2 ^^ (j + 1)) *> (T4 ^^ (b + 1)) *> r))).
    { rewrite h0, hlk. exact (unwind_T2 b j lk r). }
    assert (h2 : (([S1; S1] *> (T3 ^^ k) *> Lt) {{F}}> ([S0; S1] *> (T2 ^^ (j + 1)) *> (T4 ^^ (b + 1)) *> r)) -[ tm ]->*
                 (([S1; S1] *> Lt) {{F}}> ([S0; S1] *> (T2 ^^ (j + k + 1)) *> (T4 ^^ (b + 1)) *> r))).
    { rewrite h0.
      eapply stepStar_trans; [exact (rule_q5_t3_unwind k l0 ((T2 ^^ (j + 1)) *> (T4 ^^ (b + 1)) *> r)) |].
      rewrite <- pow_add_blank. replace (k + (j + 1)) with (j + k + 1) by lia. apply evstep_refl. }
    eapply stepStar_trans; [exact h1 |].
    eapply stepStar_trans; [exact h2 |].
    rewrite !Str_app_assoc. exact (hunw ((T2 ^^ (j + k + 1)) *> (T4 ^^ (b + 1)) *> r)).
  - destruct (head0_t3_t0 k l0) as [lk hlk].
    destruct (head0_t5_t4 b ((T3 ^^ j) *> T2 *> (T3 ^^ k) *> Lt)) as [l' hl'].
    assert (hp1 : Pull1
        ((T5 ^^ b) *> T4 *> (T3 ^^ j) *> T2 *> (T3 ^^ k) *> Lt)
        ((T5 ^^ b) *> T4 *> (T3 ^^ (j + k)) *> T2 *> Lt')).
    { intros r.
      assert (h1 : (([S1; S1] *> (T5 ^^ b) *> T4 *> (T3 ^^ j) *> T2 *> (T3 ^^ k) *> Lt) {{F}}> (T0 *> r)) -[ tm ]->*
                   (([S1; S1] *> (T3 ^^ k) *> Lt) {{F}}> ([S0; S1] *> (T2 ^^ (j + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r))).
      { rewrite h0, hlk. exact (left_T2_blk b j lk r). }
      assert (h2 : (([S1; S1] *> (T3 ^^ k) *> Lt) {{F}}> ([S0; S1] *> (T2 ^^ (j + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r)) -[ tm ]->*
                   (([S1; S1] *> Lt) {{F}}> ([S0; S1] *> (T2 ^^ (j + k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r))).
      { rewrite h0.
        eapply stepStar_trans; [exact (rule_q5_t3_unwind k l0 ((T2 ^^ (j + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r)) |].
        rewrite <- pow_add_blank. replace (k + (j + 1)) with (j + k + 1) by lia. apply evstep_refl. }
      eapply stepStar_trans; [exact h1 |].
      eapply stepStar_trans; [exact h2 |].
      change ([S0; S1] *> (T2 ^^ (j + k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r) with
        (T0 *> [S1] *> (T2 ^^ (j + k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r).
      eapply stepStar_trans; [exact (hpull ([S1] *> (T2 ^^ (j + k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r)) |].
      eapply stepStar_trans; [exact (post_pull_rt5 Lt' ((T2 ^^ (j + k + 1)) *> (T4 ^^ b) *> [S0; S1; S0; S1] *> r)) |].
      eapply stepStar_trans; [exact (rule_C_1_t2 (j + k + 1) (T2 *> Lt') ((T4 ^^ b) *> [S0; S1; S0; S1] *> r)) |].
      rewrite zPsr1.
      exact (right_ret_t4_0101_t3 b ((T3 ^^ (j + k)) *> T2 *> Lt') r). }
    exact (PipeL_mkS hl' hp1 (pipeL_T2_blk b (j + k) hnext)).
Qed.

Lemma pipeL_T2_t2pairs {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (d b j k : nat) (hp : PipeL En R_out Lt) :
    PipeL (En + d) ((R_out ++ (T2 ^^ (j + 2 * d + k + 1))) ++ (T4 ^^ (b + 1)))
      ((T5 ^^ b) *> T4 *> (T3 ^^ j) *> (T2 ^^ (2 * d)) *> T2 *> (T3 ^^ k) *> Lt).
Proof.
  revert j. induction d as [|d' IH]; intros j.
  - replace (En + 0) with En by lia. replace (2 * 0) with 0 by lia. replace (j + 0 + k + 1) with (j + k + 1) by lia.
    rewrite zPz, zLan. exact (pipeL_T2_mid_t3 b j k hp).
  - destruct (PipeL_head0 hp) as [l0 hl0].
    destruct (head0_t3_t0 k l0) as [lk hlk].
    destruct (head0_t2_t0 (2 * d' + 1) lk) as [lt hlt].
    destruct (head0_t5_t4 b ((T3 ^^ j) *> (T2 ^^ (2 * S d')) *> T2 *> (T3 ^^ k) *> Lt)) as [l' hl'].
    assert (h2d : (T2 ^^ (2 * S d')) *> T2 *> (T3 ^^ k) *> Lt =
                  T2 *> T2 *> (T2 ^^ (2 * d')) *> T2 *> (T3 ^^ k) *> Lt).
    { replace (2 * S d') with (2 + 2 * d') by lia.
      rewrite pow_add_blank, !zPsr, zPz, zLan. reflexivity. }
    assert (htail : (T2 ^^ (2 * d')) *> T2 *> (T3 ^^ k) *> Lt =
                    (T2 ^^ (2 * d' + 1)) *> (T3 ^^ k) *> Lt).
    { apply zPal1. }
    assert (hpull : Pull1
        ((T5 ^^ b) *> T4 *> (T3 ^^ j) *> (T2 ^^ (2 * S d')) *> T2 *> (T3 ^^ k) *> Lt)
        ((T5 ^^ b) *> T4 *> (T3 ^^ (j + 2)) *> (T2 ^^ (2 * d')) *> T2 *> (T3 ^^ k) *> Lt)).
    { rewrite h2d, htail, hl0, hlk, hlt. exact (pull1_base b j lt). }
    pose proof (IH (j + 2)) as hnext.
    replace (j + 2 + 2 * d' + k + 1) with (j + 2 * S d' + k + 1) in hnext by lia.
    replace (En + S d') with ((En + d') + 1) by lia.
    exact (PipeL_mkS hl' hpull hnext).
Qed.

Lemma pipeL_p1_asplit_odd_odd_small_s0 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m p d : nat) (h : bool) (hE : m + 1 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    let aL := 2 * m + 1 in
    let aR := 2 * (p + d + 1) + 1 in
    let s0 := p + (if h then 1 else 2) in
    exists Lt', PipeL (En - m - 1 + d) ((R_out ++ (T2 ^^ (aL + aR + 2))) ++ (T4 ^^ (p + 1))) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ aL) *> T0 *> (T2 ^^ aR) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> r).
Proof.
  intros aL aR s0.
  set (q := p + d + 1).
  destruct (pipeL_eat_t2_even (En := En) m 0 ltac:(lia) hp
    (T2 *> T0 *> (T2 ^^ (2 * q + 1)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) as [L1 [hp1 hs1]].
  rewrite zPz, zLan in hs1. replace (0 + 2 * m) with (2 * m) in hs1 by lia.
  assert (hE1eq : En - m = (En - m - 1) + 1) by lia.
  pose proof (pipeL_eqE hE1eq hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [L2 [hpull1 hp2]].
  pose proof (pull1_t3_t2 (2 * m) hl1 hpull1
    (T0 *> (T2 ^^ (2 * q + 1)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) as hs2.
  assert (hs34 : (([S1; S1] *> (T3 ^^ (2 * m)) *> T2 *> L2) {{F}}>
                   (T0 *> (T2 ^^ (2 * q + 1)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) -[ tm ]->*
                 (([S1; S1] *> T3 *> (T2 ^^ (2 * p)) *> T2 *> (T2 ^^ (2 * d)) *> T2 *> (T3 ^^ (2 * m + 2)) *> L2) {{F}}>
                   (T5 *> T3 *> (T4 ^^ p) *> r))).
  { assert (ht2split : (T2 ^^ (2 * q + 1)) *> (T3 ^^ (2 * m + 2)) *> L2 =
                       T2 *> (T2 ^^ (2 * p)) *> T2 *> (T2 ^^ (2 * d)) *> T2 *> (T3 ^^ (2 * m + 2)) *> L2).
    { replace (2 * q + 1) with (1 + (2 * p + (1 + (2 * d + 1)))) by (unfold q; lia).
      rewrite !pow_add_blank, !zP1. reflexivity. }
    destruct h.
    - assert (hT5split : T5 *> (T4 ^^ s0) *> r = [S0; S1] *> T2 *> T4 *> (T4 ^^ p) *> r).
      { unfold s0. replace (p + 1) with (1 + p) by lia.
        rewrite pow_add_blank, zP1. reflexivity. }
      rewrite hT5split.
      eapply stepStar_trans; [exact (rule_p1_t0_sweep (2 * m) (2 * q + 1) L2 _) |].
      rewrite ht2split. exact (step_asplit_pump_start_h1 _ _).
    - assert (hT4split : ([] : list Sym) *> (T4 ^^ s0) *> r = [S0; S1] *> T3 *> T4 *> (T4 ^^ p) *> r).
      { rewrite zLan. unfold s0. replace (p + 2) with (1 + (1 + p)) by lia.
        rewrite !pow_add_blank, !zP1. reflexivity. }
      rewrite hT4split.
      eapply stepStar_trans; [exact (rule_p1_t0_sweep (2 * m) (2 * q + 1) L2 _) |].
      rewrite ht2split. exact (step_asplit_pump_start _ _). }
  pose proof (rule_asplit_pump_loop p 1 0
    (T2 *> (T2 ^^ (2 * d)) *> T2 *> (T3 ^^ (2 * m + 2)) *> L2) r) as hs5.
  replace (0 + p) with p in hs5 by lia. rewrite zPz, zLan in hs5.
  pose proof (rule_asplit_t5_end (1 + 2 * p) p
    ((T2 ^^ (2 * d)) *> T2 *> (T3 ^^ (2 * m + 2)) *> L2) r) as hs6.
  pose proof (pipeL_T2_t2pairs d p (1 + 2 * p + 2) (2 * m + 2) hp2) as hp3.
  exists ((T5 ^^ p) *> T4 *> (T3 ^^ (1 + 2 * p + 2)) *> (T2 ^^ (2 * d)) *> T2 *> (T3 ^^ (2 * m + 2)) *> L2).
  split.
  - eapply pipeL_eqER; [exact hp3 | lia |].
    unfold aL, aR; f_equal; f_equal; f_equal; lia.
  - unfold aL, aR. replace (2 * (p + d + 1) + 1) with (2 * q + 1) by (unfold q; lia).
    rewrite (pow_add_blank T2 (2 * m) 1), zP1.
    exact (stepStar_trans hs1 (stepStar_trans hs2 (stepStar_trans hs34 (stepStar_trans hs5 hs6)))).
Qed.

Lemma step_q5_t3_t2_eat_t2 (j : nat) (l r : Stream Sym) :
    (([S1; S1] *> (T3 ^^ (j + 1)) *> T2 *> l) {{F}}> (T2 *> r)) -[ tm ]->*
    (([S1; S1] *> (T3 ^^ (j + 3)) *> l) {{F}}> r).
Proof.
  assert (h1 : (([S1; S1] *> (T3 ^^ (j + 1)) *> T2 *> l) {{F}}> (T2 *> r)) -[ tm ]->*
               (((T3 ^^ (j + 1)) *> T2 *> l) {{E}}> (T0 *> T0 *> T2 *> r))).
  { rewrite zPsr1.
    exact (step_8A_head ([S1; S1] *> (T3 ^^ j) *> T2 *> l) ([S0; S1] *> r)). }
  eapply stepStar_trans; [exact h1 |].
  change (T2 *> l) with (T0 *> [S0; S1] *> l).
  eapply stepStar_trans; [exact (rule_E_t3 (j + 1) ([S0; S1] *> l) (T0 *> T2 *> r)) |].
  change (T0 *> [S0; S1] *> l) with (T2 *> l).
  eapply stepStar_trans; [exact (step_E_t2_bounce l ((T2 ^^ (j + 1)) *> T0 *> T2 *> r)) |].
  eapply stepStar_trans; [exact (rule_C_1_t2 (j + 1) (T3 *> l) (T0 *> T2 *> r)) |].
  rewrite zPal1.
  eapply stepStar_trans; [exact (step_C_1_t0_t2 ((T3 ^^ ((j + 1) + 1)) *> l) r) |].
  replace (j + 3) with (((j + 1) + 1) + 1) by lia.
  rewrite <- (zPsr1 T3). apply evstep_refl.
Qed.

Lemma rule_q5_t3_t2_eat_t2 : forall (n j : nat) (l r : Stream Sym),
    (([S1; S1] *> (T3 ^^ (j + 1)) *> (T2 ^^ n) *> l) {{F}}> ((T2 ^^ n) *> r)) -[ tm ]->*
    (([S1; S1] *> (T3 ^^ (j + 2 * n + 1)) *> l) {{F}}> r).
Proof.
  induction n as [|n' IH]; intros j l r.
  - replace (2 * 0) with 0 by lia. replace (j + 0 + 1) with (j + 1) by lia.
    rewrite !zPz, !zLan. apply evstep_refl.
  - rewrite !(zPsr T2).
    eapply stepStar_trans; [exact (step_q5_t3_t2_eat_t2 j ((T2 ^^ n') *> l) ((T2 ^^ n') *> r)) |].
    replace (j + 3) with ((j + 2) + 1) by lia.
    pose proof (IH (j + 2) l r) as hnext.
    replace (j + 2 + 2 * n' + 1) with (j + 2 * S n' + 1) in hnext by lia.
    exact hnext.
Qed.

Lemma pipeL_p1_asplit_odd_even_s2_or_h1s1 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m d : nat) (h : bool) (hE : m + 1 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    let aL := 2 * m + 1 in
    let aR := 2 * d + 2 in
    let s0 := if h then 1 else 2 in
    exists Lt', PipeL (En - m - 1 + d) ((R_out ++ (T2 ^^ (aL + aR + 2))) ++ T5) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ aL) *> T0 *> (T2 ^^ aR) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> r).
Proof.
  intros aL aR s0.
  destruct (pipeL_eat_t2_even (En := En) m 0 ltac:(lia) hp
    (T2 *> T0 *> (T2 ^^ (2 * d + 2)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) as [L1 [hp1 hs1]].
  rewrite zPz, zLan in hs1. replace (0 + 2 * m) with (2 * m) in hs1 by lia.
  assert (hE1eq : En - m = (En - m - 1) + 1) by lia.
  pose proof (pipeL_eqE hE1eq hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [L2 [hpull1 hp2]].
  pose proof (pull1_t3_t2 (2 * m) hl1 hpull1
    (T0 *> (T2 ^^ (2 * d + 2)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) as hs2.
  assert (ht2split : (T2 ^^ (2 * d + 2)) *> (T3 ^^ (2 * m + 2)) *> L2 =
                     T2 *> T2 *> (T2 ^^ (2 * d)) *> (T3 ^^ (2 * m + 2)) *> L2).
  { replace (2 * d + 2) with (2 + 2 * d) by lia.
    rewrite pow_add_blank, !zPsr, zPz, zLan. reflexivity. }
  assert (hs34 : (([S1; S1] *> (T3 ^^ (2 * m)) *> T2 *> L2) {{F}}>
                   (T0 *> (T2 ^^ (2 * d + 2)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) -[ tm ]->*
                 (([S1; S1] *> T4 *> (T3 ^^ 3) *> (T2 ^^ (2 * d)) *> (T3 ^^ (2 * m + 2)) *> L2) {{F}}> r)).
  { destruct h.
    - change (T5 *> (T4 ^^ s0) *> r) with ([S0; S1] *> T2 *> T4 *> r).
      eapply stepStar_trans; [exact (rule_p1_t0_sweep (2 * m) (2 * d + 2) L2 (T2 *> T4 *> r)) |].
      rewrite ht2split. exact (step_q5_t2_t2_t2_t4 ((T2 ^^ (2 * d)) *> (T3 ^^ (2 * m + 2)) *> L2) r).
    - change (([] : list Sym) *> (T4 ^^ s0) *> r) with ([S0; S1] *> T3 *> T4 *> r).
      eapply stepStar_trans; [exact (rule_p1_t0_sweep (2 * m) (2 * d + 2) L2 (T3 *> T4 *> r)) |].
      rewrite ht2split. exact (step_q5_t2_t2_t3_t4 ((T2 ^^ (2 * d)) *> (T3 ^^ (2 * m + 2)) *> L2) r). }
  pose proof (pipeL_noT2_t2pairs d 0 3 (2 * m + 2) hp2) as hp3.
  rewrite zPz, zLan, app_nil_r in hp3.
  exists (T4 *> (T3 ^^ 3) *> (T2 ^^ (2 * d)) *> (T3 ^^ (2 * m + 2)) *> L2).
  split.
  - eapply pipeL_eqER; [exact hp3 | lia |].
    unfold aL, aR; f_equal; f_equal; f_equal; lia.
  - unfold aL, aR. rewrite (pow_add_blank T2 (2 * m) 1), zP1.
    exact (stepStar_trans hs1 (stepStar_trans hs2 hs34)).
Qed.

Lemma pipeL_p1_asplit_odd_h0_s1_merge {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m aR a2 b2 : nat) (hE : m + 1 <= En) (ha2 : 1 <= a2) (haR : a2 + 2 <= aR)
    (hEb : b2 <= En - m - 1 + (aR - a2 - 2) / 2)
    (hp : PipeL En R_out Lt) (r : Stream Sym) :
    let aL := 2 * m + 1 in
    let rem := aR - a2 - 2 in
    let hOut := (rem mod 2 =? 0) in
    let bOut := if hOut then b2 else b2 + 1 in
    exists Lt', PipeL (En - m - 1 + rem / 2 - b2)
        (((R_out ++ (T2 ^^ (aL + aR + a2 + 2))) ++ (if hOut then T5 else [])) ++ (T4 ^^ bOut)) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ aL) *> T0 *> (T2 ^^ aR) *> T4 *> (T2 ^^ a2) *> (T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> r).
Proof.
  intros aL rem hOut bOut.
  set (a2' := a2 - 1).
  assert (ha2eq : a2 = a2' + 1) by (unfold a2'; lia).
  destruct (pipeL_eat_t2_even (En := En) m 0 ltac:(lia) hp
    (T2 *> T0 *> (T2 ^^ aR) *> T4 *> (T2 ^^ (a2' + 1)) *> (T4 ^^ (b2 + 1)) *> r)) as [L1 [hp1 hs1]].
  rewrite zPz, zLan in hs1. replace (0 + 2 * m) with (2 * m) in hs1 by lia.
  assert (hE1eq : En - m = (En - m - 1) + 1) by lia.
  pose proof (pipeL_eqE hE1eq hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [L2 [hpull1 hp2]].
  pose proof (pull1_t3_t2 (2 * m) hl1 hpull1
    (T0 *> (T2 ^^ aR) *> T4 *> (T2 ^^ (a2' + 1)) *> (T4 ^^ (b2 + 1)) *> r)) as hs2.
  assert (hs3 : (([S1; S1] *> (T3 ^^ (2 * m)) *> T2 *> L2) {{F}}>
                  (T0 *> (T2 ^^ aR) *> T4 *> (T2 ^^ (a2' + 1)) *> (T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
                (([S1; S1] *> (T2 ^^ aR) *> (T3 ^^ (2 * m + 2)) *> L2) {{F}}>
                  (T3 *> (T2 ^^ (a2' + 1)) *> (T4 ^^ (b2 + 1)) *> r))).
  { change (T4 *> (T2 ^^ (a2' + 1)) *> (T4 ^^ (b2 + 1)) *> r) with
      ([S0; S1] *> T3 *> (T2 ^^ (a2' + 1)) *> (T4 ^^ (b2 + 1)) *> r).
    exact (rule_p1_t0_sweep (2 * m) aR L2 _). }
  assert (ht2split1 : (T2 ^^ aR) *> (T3 ^^ (2 * m + 2)) *> L2 =
                      T2 *> T2 *> (T2 ^^ a2') *> T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2).
  { replace aR with (1 + (1 + (a2' + (1 + rem)))) at 1 by (unfold rem, a2'; lia).
    rewrite !pow_add_blank, !zP1. reflexivity. }
  pose proof (step_q5_t2_t2_t3 ((T2 ^^ a2') *> T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2)
    ((T2 ^^ (a2' + 1)) *> (T4 ^^ (b2 + 1)) *> r)) as hs4.
  assert (hs5 : (([S1] *> (T3 ^^ 3) *> (T2 ^^ a2') *> T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) {{A}}>
                  (T0 *> (T2 ^^ (a2' + 1)) *> (T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
                (([S1; S1] *> (T3 ^^ 4) *> (T2 ^^ a2') *> T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) {{F}}>
                  ((T2 ^^ a2') *> (T4 ^^ (b2 + 1)) *> r))).
  { rewrite zPsr1.
    pose proof (step_q0_t0_t2 ((T3 ^^ 3) *> (T2 ^^ a2') *> T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2)
      ((T2 ^^ a2') *> (T4 ^^ (b2 + 1)) *> r)) as h5.
    rewrite <- zPsr in h5. exact h5. }
  pose proof (rule_q5_t3_t2_eat_t2 a2' 3 (T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2)
    ((T4 ^^ (b2 + 1)) *> r)) as hs6.
  assert (hs7 : (([S1; S1] *> (T3 ^^ (3 + 2 * a2' + 1)) *> T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) {{F}}>
                  ((T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
                (([S1; S1] *> T4 *> (T3 ^^ (2 * a2' + 5)) *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) {{F}}>
                  ((T4 ^^ b2) *> r))).
  { rewrite (zPsr1 T4). replace (3 + 2 * a2' + 1) with ((2 * a2' + 3) + 1) by lia.
    replace (2 * a2' + 5) with ((2 * a2' + 3) + 2) by lia.
    exact (step_heal_odd_h0 (2 * a2' + 3) ((T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) ((T4 ^^ b2) *> r)). }
  assert (hmid : (([S1; S1] *> Lt) {{F}}>
                   ((T2 ^^ (2 * m + 1)) *> T0 *> (T2 ^^ aR) *> T4 *> (T2 ^^ (a2' + 1)) *> (T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
                 (([S1; S1] *> T4 *> (T3 ^^ (2 * a2' + 5)) *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) {{F}}>
                   ((T4 ^^ b2) *> r))).
  { rewrite (pow_add_blank T2 (2 * m) 1), zP1.
    eapply stepStar_trans; [exact hs1 |].
    eapply stepStar_trans; [exact hs2 |].
    eapply stepStar_trans; [exact hs3 |].
    rewrite ht2split1.
    exact (stepStar_trans hs4 (stepStar_trans hs5 (stepStar_trans hs6 hs7))). }
  destruct (rem mod 2 =? 0) eqn:hbeq.
  - pose proof (proj1 (Nat.eqb_eq _ _) hbeq) as hrem0.
    set (d := rem / 2).
    assert (hd : rem = 2 * d) by (unfold d; lia).
    pose proof (pipeL_noT2_t2pairs d 0 (2 * a2' + 5) (2 * m + 2) hp2) as hp3.
    rewrite zPz, zLan, app_nil_r in hp3.
    destruct (pipeL_eat_t4 (En := (En - m - 1) + d) b2 ltac:(unfold d, rem; lia) hp3 r) as [Lt' [hp4 hs8]].
    exists Lt'. split.
    + eapply pipeL_eqER; [exact hp4 | unfold d; lia |].
      unfold bOut, hOut; cbv iota; unfold aL.
      f_equal; f_equal; f_equal; f_equal; unfold rem, a2' in *; lia.
    + unfold aL; rewrite ha2eq. rewrite hd in hmid. exact (stepStar_trans hmid hs8).
  - pose proof (proj1 (Nat.eqb_neq _ _) hbeq) as hrem1.
    set (d := rem / 2).
    assert (hd : rem = 2 * d + 1) by (unfold d; lia).
    pose proof (pipeL_T2_t2pairs d 0 (2 * a2' + 5) (2 * m + 2) hp2) as hp3.
    rewrite zPz, zLan in hp3.
    destruct (pipeL_eat_t4 (En := (En - m - 1) + d) b2 ltac:(unfold d, rem; lia) hp3 r) as [Lt' [hp4 hs8]].
    exists Lt'. split.
    + eapply pipeL_eqER; [exact hp4 | unfold d; lia |].
      unfold bOut, hOut; cbv iota; rewrite app_nil_r, append_assoc, <- list_pow_add.
      replace (0 + 1 + b2) with (b2 + 1) by lia.
      unfold aL; f_equal; f_equal; f_equal; unfold rem, a2' in *; lia.
    + unfold aL; rewrite ha2eq.
      assert (hrem_rw : (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2 =
                        (T2 ^^ (2 * d)) *> T2 *> (T3 ^^ (2 * m + 2)) *> L2)
        by (rewrite hd, pow_add_blank, zP1; reflexivity).
      rewrite hrem_rw in hmid. exact (stepStar_trans hmid hs8).
Qed.

Lemma pipeL_p1_asplit_odd_h0_s1_merge_h1 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m aR a2 b2 : nat) (hE : m + 1 <= En) (ha2 : 1 <= a2) (haR : a2 + 2 <= aR)
    (hp : PipeL En R_out Lt) (r : Stream Sym) :
    let aL := 2 * m + 1 in
    let rem := aR - a2 - 2 in
    let hOut := (rem mod 2 =? 0) in
