    exists Lt', PipeL (En - m - 1 + rem / 2)
        (((R_out ++ (T2 ^^ (aL + aR + a2 + 3))) ++ (if hOut then T5 else [])) ++ (T4 ^^ bOut)) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ aL) *> T0 *> (T2 ^^ aR) *> T4 *> (T2 ^^ a2) *> T5 *> (T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  intros aL rem hOut bOut.
  set (a2' := a2 - 1).
  assert (ha2eq : a2 = a2' + 1) by (unfold a2'; lia).
  destruct (pipeL_eat_t2_even (En := En) m 0 ltac:(lia) hp
    (T2 *> T0 *> (T2 ^^ aR) *> T4 *> (T2 ^^ (a2' + 1)) *> T5 *> (T4 ^^ (b2 + 1)) *> r)) as [L1 [hp1 hs1]].
  rewrite zPz, zLan in hs1. replace (0 + 2 * m) with (2 * m) in hs1 by lia.
  assert (hE1eq : En - m = (En - m - 1) + 1) by lia.
  pose proof (pipeL_eqE hE1eq hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [L2 [hpull1 hp2]].
  pose proof (pull1_t3_t2 (2 * m) hl1 hpull1
    (T0 *> (T2 ^^ aR) *> T4 *> (T2 ^^ (a2' + 1)) *> T5 *> (T4 ^^ (b2 + 1)) *> r)) as hs2.
  assert (hs3 : (([S1; S1] *> (T3 ^^ (2 * m)) *> T2 *> L2) {{F}}>
                  (T0 *> (T2 ^^ aR) *> T4 *> (T2 ^^ (a2' + 1)) *> T5 *> (T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
                (([S1; S1] *> (T2 ^^ aR) *> (T3 ^^ (2 * m + 2)) *> L2) {{F}}>
                  (T3 *> (T2 ^^ (a2' + 1)) *> T5 *> (T4 ^^ (b2 + 1)) *> r))).
  { change (T4 *> (T2 ^^ (a2' + 1)) *> T5 *> (T4 ^^ (b2 + 1)) *> r) with
      ([S0; S1] *> T3 *> (T2 ^^ (a2' + 1)) *> T5 *> (T4 ^^ (b2 + 1)) *> r).
    exact (rule_p1_t0_sweep (2 * m) aR L2 _). }
  assert (ht2split1 : (T2 ^^ aR) *> (T3 ^^ (2 * m + 2)) *> L2 =
                      T2 *> T2 *> (T2 ^^ a2') *> T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2).
  { replace aR with (1 + (1 + (a2' + (1 + rem)))) at 1 by (unfold rem, a2'; lia).
    rewrite !pow_add_blank, !zP1. reflexivity. }
  pose proof (step_q5_t2_t2_t3 ((T2 ^^ a2') *> T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2)
    ((T2 ^^ (a2' + 1)) *> T5 *> (T4 ^^ (b2 + 1)) *> r)) as hs4.
  assert (hs5 : (([S1] *> (T3 ^^ 3) *> (T2 ^^ a2') *> T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) {{A}}>
                  (T0 *> (T2 ^^ (a2' + 1)) *> T5 *> (T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
                (([S1; S1] *> (T3 ^^ 4) *> (T2 ^^ a2') *> T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) {{F}}>
                  ((T2 ^^ a2') *> T5 *> (T4 ^^ (b2 + 1)) *> r))).
  { rewrite zPsr1.
    pose proof (step_q0_t0_t2 ((T3 ^^ 3) *> (T2 ^^ a2') *> T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2)
      ((T2 ^^ a2') *> T5 *> (T4 ^^ (b2 + 1)) *> r)) as h5.
    rewrite <- zPsr in h5. exact h5. }
  pose proof (rule_q5_t3_t2_eat_t2 a2' 3 (T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2)
    (T5 *> (T4 ^^ (b2 + 1)) *> r)) as hs6.
  assert (hs7 : (([S1; S1] *> (T3 ^^ (3 + 2 * a2' + 1)) *> T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) {{F}}>
                  (T5 *> (T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
                (([S1] *> (T3 ^^ (2 * a2' + 7)) *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) {{A}}>
                  ((T4 ^^ (b2 + 1)) *> r))).
  { replace (3 + 2 * a2' + 1) with ((2 * a2' + 3) + 1) by lia.
    replace (2 * a2' + 7) with ((2 * a2' + 3) + 4) by lia.
    exact (step_heal_odd_h1 (2 * a2' + 3) ((T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) ((T4 ^^ (b2 + 1)) *> r)). }
  assert (hs8 : (([S1] *> (T3 ^^ (2 * a2' + 7)) *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) {{A}}>
                  ((T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
                (([S1] *> T2 *> T4 *> (T3 ^^ (2 * a2' + 6)) *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) {{A}}>
                  ((T4 ^^ b2) *> r))).
  { replace (2 * a2' + 7) with (S (2 * a2' + 6)) by lia.
    rewrite (zPsr T3), (zPsr1 T4).
    exact (step_q0_t4_first ((T3 ^^ (2 * a2' + 6)) *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) ((T4 ^^ b2) *> r)). }
  pose proof (rule_q0_t4_next b2
    (T4 *> (T3 ^^ (2 * a2' + 6)) *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) r) as hs9.
  assert (hmid : (([S1; S1] *> Lt) {{F}}>
                   ((T2 ^^ (2 * m + 1)) *> T0 *> (T2 ^^ aR) *> T4 *> (T2 ^^ (a2' + 1)) *> T5 *> (T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
                 (([S1] *> T2 *> (T5 ^^ b2) *> T4 *> (T3 ^^ (2 * a2' + 6)) *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) {{A}}> r)).
  { rewrite (pow_add_blank T2 (2 * m) 1), zP1.
    eapply stepStar_trans; [exact hs1 |].
    eapply stepStar_trans; [exact hs2 |].
    eapply stepStar_trans; [exact hs3 |].
    rewrite ht2split1.
    exact (stepStar_trans hs4 (stepStar_trans hs5 (stepStar_trans hs6 (stepStar_trans hs7 (stepStar_trans hs8 hs9))))). }
  destruct (rem mod 2 =? 0) eqn:hbeq.
  - pose proof (proj1 (Nat.eqb_eq _ _) hbeq) as hrem0.
    set (d := rem / 2).
    assert (hd : rem = 2 * d) by (unfold d; lia).
    pose proof (pipeL_noT2_t2pairs d b2 (2 * a2' + 6) (2 * m + 2) hp2) as hp3.
    exists ((T5 ^^ b2) *> T4 *> (T3 ^^ (2 * a2' + 6)) *> (T2 ^^ (2 * d)) *> (T3 ^^ (2 * m + 2)) *> L2).
    split.
    + eapply pipeL_eqER; [exact hp3 | unfold d; lia |].
      unfold bOut, hOut; cbv iota; unfold aL.
      f_equal; f_equal; f_equal; f_equal; unfold rem, a2' in *; lia.
    + unfold aL; rewrite ha2eq. rewrite hd in hmid. exact hmid.
  - pose proof (proj1 (Nat.eqb_neq _ _) hbeq) as hrem1.
    set (d := rem / 2).
    assert (hd : rem = 2 * d + 1) by (unfold d; lia).
    pose proof (pipeL_T2_t2pairs d b2 (2 * a2' + 6) (2 * m + 2) hp2) as hp3.
    exists ((T5 ^^ b2) *> T4 *> (T3 ^^ (2 * a2' + 6)) *> (T2 ^^ (2 * d)) *> T2 *> (T3 ^^ (2 * m + 2)) *> L2).
    split.
    + eapply pipeL_eqER; [exact hp3 | unfold d; lia |].
      unfold bOut, hOut; cbv iota; rewrite app_nil_r.
      unfold aL; f_equal; f_equal; f_equal; unfold rem, a2' in *; lia.
    + unfold aL; rewrite ha2eq.
      assert (hrem_rw : (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2 =
                        (T2 ^^ (2 * d)) *> T2 *> (T3 ^^ (2 * m + 2)) *> L2)
        by (rewrite hd, pow_add_blank, zP1; reflexivity).
      rewrite hrem_rw in hmid. exact hmid.
