                  (T2 *> (T2 ^^ a2) *> (T4 ^^ (b2 + 1)) *> r))).
  { change (T5 *> (T2 ^^ a2) *> (T4 ^^ (b2 + 1)) *> r) with
      ([S0; S1] *> T2 *> (T2 ^^ a2) *> (T4 ^^ (b2 + 1)) *> r).
    exact (rule_p1_t0_sweep (2 * m) aR L2 _). }
  assert (ht2split : (T2 ^^ aR) *> (T3 ^^ (2 * m + 2)) *> L2 =
                     T2 *> (T2 ^^ a2) *> T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2).
  { replace aR with (1 + (a2 + (1 + rem))) at 1 by (unfold rem; lia).
    rewrite !pow_add_blank, !zP1. reflexivity. }
  pose proof (step_q5_t2_t2_eat ((T2 ^^ a2) *> T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2)
    ((T2 ^^ a2) *> (T4 ^^ (b2 + 1)) *> r)) as hs4.
  pose proof (rule_q5_t3_t2_eat_t2 a2 1 (T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2)
    ((T4 ^^ (b2 + 1)) *> r)) as hs5.
  assert (hs6 : (([S1; S1] *> (T3 ^^ (1 + 2 * a2 + 1)) *> T2 *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) {{F}}>
                  ((T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
                (([S1; S1] *> T4 *> (T3 ^^ (2 * a2 + 3)) *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) {{F}}>
                  ((T4 ^^ b2) *> r))).
  { rewrite (zPsr1 T4). replace (1 + 2 * a2 + 1) with ((2 * a2 + 1) + 1) by lia.
    replace (2 * a2 + 3) with ((2 * a2 + 1) + 2) by lia.
    exact (step_heal_odd_h0 (2 * a2 + 1) ((T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) ((T4 ^^ b2) *> r)). }
  assert (hmid : (([S1; S1] *> Lt) {{F}}>
                   ((T2 ^^ (2 * m + 1)) *> T0 *> (T2 ^^ aR) *> T5 *> (T2 ^^ a2) *> (T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
                 (([S1; S1] *> T4 *> (T3 ^^ (2 * a2 + 3)) *> (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2) {{F}}>
                   ((T4 ^^ b2) *> r))).
  { rewrite (pow_add_blank T2 (2 * m) 1), zP1.
    eapply stepStar_trans; [exact hs1 |].
    eapply stepStar_trans; [exact hs2 |].
    eapply stepStar_trans; [exact hs3 |].
    rewrite ht2split.
    exact (stepStar_trans hs4 (stepStar_trans hs5 hs6)). }
  destruct (rem mod 2 =? 0) eqn:hbeq.
  - pose proof (proj1 (Nat.eqb_eq _ _) hbeq) as hrem0.
    set (d := rem / 2).
    assert (hd : rem = 2 * d) by (unfold d; lia).
    pose proof (pipeL_noT2_t2pairs d 0 (2 * a2 + 3) (2 * m + 2) hp2) as hp3.
    rewrite zPz, zLan, app_nil_r in hp3.
    destruct (pipeL_eat_t4 (En := (En - m - 1) + d) b2 ltac:(unfold d, rem; lia) hp3 r) as [Lt' [hp4 hs7]].
    exists Lt'. split.
    + eapply pipeL_eqER; [exact hp4 | unfold d; lia |].
      unfold bOut, hOut; cbv iota; unfold aL.
      f_equal; f_equal; f_equal; f_equal; unfold rem in *; lia.
    + unfold aL; rewrite hd in hmid. exact (stepStar_trans hmid hs7).
  - pose proof (proj1 (Nat.eqb_neq _ _) hbeq) as hrem1.
    set (d := rem / 2).
    assert (hd : rem = 2 * d + 1) by (unfold d; lia).
    pose proof (pipeL_T2_t2pairs d 0 (2 * a2 + 3) (2 * m + 2) hp2) as hp3.
    rewrite zPz, zLan in hp3.
    destruct (pipeL_eat_t4 (En := (En - m - 1) + d) b2 ltac:(unfold d, rem; lia) hp3 r) as [Lt' [hp4 hs7]].
    exists Lt'. split.
    + eapply pipeL_eqER; [exact hp4 | unfold d; lia |].
      unfold bOut, hOut; cbv iota; rewrite app_nil_r, append_assoc, <- list_pow_add.
      replace (0 + 1 + b2) with (b2 + 1) by lia.
      unfold aL; f_equal; f_equal; f_equal; unfold rem in *; lia.
    + unfold aL.
      assert (hrem_rw : (T2 ^^ rem) *> (T3 ^^ (2 * m + 2)) *> L2 =
                        (T2 ^^ (2 * d)) *> T2 *> (T3 ^^ (2 * m + 2)) *> L2)
        by (rewrite hd, pow_add_blank, zP1; reflexivity).
      rewrite hrem_rw in hmid. exact (stepStar_trans hmid hs7).
Qed.

Lemma pipeL_q5_t0_asplit_odd {E2 : nat} {R_out : list Sym} {L2 : Stream Sym}
    (k q' rem : nat) (h : bool) (hp2 : PipeL (E2 + 1) R_out L2) (r : Stream Sym) :
    let aR := 2 * (q' + 1) + 1 in
    let s0 := (q' + 1) + (if h then 1 else 2) + rem in
    exists Lt', PipeL E2 ((R_out ++ (T2 ^^ (k + aR + 3))) ++ (T4 ^^ (q' + 1))) Lt' /\
      (([S1; S1] *> (T3 ^^ k) *> T2 *> L2) {{F}}> (T0 *> (T2 ^^ aR) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> (T3 *> (T4 ^^ rem) *> r)).
Proof.
  intros aR s0.
  assert (hs34 : (([S1; S1] *> (T3 ^^ k) *> T2 *> L2) {{F}}>
                   (T0 *> (T2 ^^ (2 * (q' + 1) + 1)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) -[ tm ]->*
                 (([S1; S1] *> T3 *> (T2 ^^ (2 * (q' + 1))) *> (T3 ^^ (k + 2)) *> L2) {{F}}>
                   (T5 *> T3 *> (T4 ^^ (q' + 1)) *> (T4 ^^ rem) *> r))).
  { assert (ht2split : (T2 ^^ (2 * (q' + 1) + 1)) *> (T3 ^^ (k + 2)) *> L2 =
                       T2 *> (T2 ^^ (2 * (q' + 1))) *> (T3 ^^ (k + 2)) *> L2)
      by (apply zPsr1).
    destruct h.
    - assert (hT5split : T5 *> (T4 ^^ s0) *> r = [S0; S1] *> T2 *> T4 *> (T4 ^^ (q' + 1)) *> (T4 ^^ rem) *> r).
      { unfold s0. replace ((q' + 1) + 1 + rem) with (1 + ((q' + 1) + rem)) by lia.
        rewrite !pow_add_blank, !zP1. reflexivity. }
      rewrite hT5split.
      eapply stepStar_trans; [exact (rule_p1_t0_sweep k (2 * (q' + 1) + 1) L2 _) |].
      rewrite ht2split. exact (step_asplit_pump_start_h1 _ _).
    - assert (hT4split : ([] : list Sym) *> (T4 ^^ s0) *> r = [S0; S1] *> T3 *> T4 *> (T4 ^^ (q' + 1)) *> (T4 ^^ rem) *> r).
      { rewrite zLan. unfold s0. replace ((q' + 1) + 2 + rem) with (1 + (1 + ((q' + 1) + rem))) by lia.
        rewrite !pow_add_blank, !zP1. reflexivity. }
      rewrite hT4split.
      eapply stepStar_trans; [exact (rule_p1_t0_sweep k (2 * (q' + 1) + 1) L2 _) |].
      rewrite ht2split. exact (step_asplit_pump_start _ _). }
  pose proof (rule_asplit_pump_loop (q' + 1) 1 0 ((T3 ^^ (k + 2)) *> L2) ((T4 ^^ rem) *> r)) as hs5.
  replace (0 + (q' + 1)) with (q' + 1) in hs5 by lia. rewrite zPz, zLan in hs5.
  destruct (PipeL_head0 hp2) as [l2 hl2].
  destruct (PipeL_pull hp2) as [L3 [hpull2 hp3]].
  assert (hT3comb : (T3 ^^ (1 + 2 * (q' + 1))) *> (T3 ^^ (k + 2)) *> L2 =
                    (T3 ^^ (k + (2 * (q' + 1) + 1) + 2)) *> L2).
  { rewrite <- pow_add_blank. f_equal. f_equal. lia. }
  pose proof (pull1_t3_t5 (k + (2 * (q' + 1) + 1) + 2) hl2 hpull2
    ((T4 ^^ (q' + 1)) *> T3 *> (T4 ^^ rem) *> r)) as hs6.
  assert (hmid : (([S1] *> (T3 ^^ (k + (2 * (q' + 1) + 1) + 2 + 1)) *> T2 *> L3) {{A}}>
                   ((T4 ^^ (q' + 1)) *> T3 *> (T4 ^^ rem) *> r)) -[ tm ]->*
                 (([S1] *> T2 *> (T5 ^^ q') *> T4 *> (T3 ^^ (k + (2 * (q' + 1) + 1) + 2)) *> T2 *> L3) {{A}}>
                   (T3 *> (T4 ^^ rem) *> r))).
  { rewrite (zPsr1 T3), (zPsr1 T4).
    eapply stepStar_trans; [exact (step_q0_t4_first ((T3 ^^ (k + (2 * (q' + 1) + 1) + 2)) *> T2 *> L3)
      ((T4 ^^ q') *> T3 *> (T4 ^^ rem) *> r)) |].
    exact (rule_q0_t4_next q' (T4 *> (T3 ^^ (k + (2 * (q' + 1) + 1) + 2)) *> T2 *> L3)
      (T3 *> (T4 ^^ rem) *> r)). }
  exists ((T5 ^^ q') *> T4 *> (T3 ^^ (k + (2 * (q' + 1) + 1) + 2)) *> T2 *> L3).
  split.
  - eapply pipeL_eqER; [exact (pipeL_T2_blk q' (k + (2 * (q' + 1) + 1) + 2) hp3) | reflexivity | unfold aR; f_equal; f_equal; f_equal; lia].
  - unfold aR. eapply stepStar_trans; [exact hs34 |].
    eapply stepStar_trans; [exact hs5 |].
    rewrite hT3comb. exact (stepStar_trans hs6 hmid).
Qed.

Lemma pipeL_q5_t0_asplit_even {E2 : nat} {R_out : list Sym} {L2 : Stream Sym}
    (k q rem : nat) (h : bool) (hp2 : PipeL (E2 + 1) R_out L2) (r : Stream Sym) :
    let aR := 2 * q + 2 in
    let s0 := q + (if h then 2 else 3) + rem in
    exists Lt', PipeL E2 (((R_out ++ (T2 ^^ (k + aR + 3))) ++ T5) ++ (T4 ^^ q)) Lt' /\
      (([S1; S1] *> (T3 ^^ k) *> T2 *> L2) {{F}}> (T0 *> (T2 ^^ aR) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> (T3 *> (T4 ^^ rem) *> r)).
Proof.
  intros aR s0.
  assert (hs34 : (([S1; S1] *> (T3 ^^ k) *> T2 *> L2) {{F}}>
                   (T0 *> (T2 ^^ (2 * q + 2)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) -[ tm ]->*
                 (([S1; S1] *> T3 *> (T2 ^^ (2 * q)) *> T2 *> (T3 ^^ (k + 2)) *> L2) {{F}}>
                   (T5 *> T3 *> (T4 ^^ q) *> T4 *> (T4 ^^ rem) *> r))).
  { assert (ht2split : (T2 ^^ (2 * q + 2)) *> (T3 ^^ (k + 2)) *> L2 =
                       T2 *> (T2 ^^ (2 * q)) *> T2 *> (T3 ^^ (k + 2)) *> L2).
    { replace (2 * q + 2) with (1 + (2 * q + 1)) by lia.
      rewrite !pow_add_blank, !zP1. reflexivity. }
    destruct h.
    - assert (hT5split : T5 *> (T4 ^^ s0) *> r = [S0; S1] *> T2 *> T4 *> (T4 ^^ q) *> T4 *> (T4 ^^ rem) *> r).
      { unfold s0. replace (q + 2 + rem) with (1 + (q + (1 + rem))) by lia.
        rewrite !pow_add_blank, !zP1. reflexivity. }
      rewrite hT5split.
      eapply stepStar_trans; [exact (rule_p1_t0_sweep k (2 * q + 2) L2 _) |].
      rewrite ht2split. exact (step_asplit_pump_start_h1 _ _).
    - assert (hT4split : ([] : list Sym) *> (T4 ^^ s0) *> r = [S0; S1] *> T3 *> T4 *> (T4 ^^ q) *> T4 *> (T4 ^^ rem) *> r).
      { rewrite zLan. unfold s0. replace (q + 3 + rem) with (1 + (1 + (q + (1 + rem)))) by lia.
        rewrite !pow_add_blank, !zP1. reflexivity. }
      rewrite hT4split.
      eapply stepStar_trans; [exact (rule_p1_t0_sweep k (2 * q + 2) L2 _) |].
      rewrite ht2split. exact (step_asplit_pump_start _ _). }
  pose proof (rule_asplit_pump_loop q 1 0 (T2 *> (T3 ^^ (k + 2)) *> L2) (T4 *> (T4 ^^ rem) *> r)) as hs5.
  replace (0 + q) with q in hs5 by lia. rewrite zPz, zLan in hs5.
  pose proof (rule_asplit_t5_odd (1 + 2 * q) q ((T3 ^^ (k + 2)) *> L2) ((T4 ^^ rem) *> r)) as hs5b.
  destruct (PipeL_head0 hp2) as [l2 hl2].
  destruct (PipeL_pull hp2) as [L3 [hpull2 hp3]].
  assert (hT3comb : (T3 ^^ (1 + 2 * q + 1)) *> (T3 ^^ (k + 2)) *> L2 =
                    (T3 ^^ (k + (2 * q + 2) + 2)) *> L2).
  { rewrite <- pow_add_blank. f_equal. f_equal. lia. }
  pose proof (pull1_t3_t5 (k + (2 * q + 2) + 2) hl2 hpull2
    (T5 *> (T4 ^^ q) *> T3 *> (T4 ^^ rem) *> r)) as hs6.
  destruct (PipeL_head0 hp3) as [l3 hl3].
  set (An := k + (2 * q + 2) + 3).
  assert (hmid : (([S1] *> (T3 ^^ An) *> T2 *> L3) {{A}}> (T5 *> (T4 ^^ q) *> T3 *> (T4 ^^ rem) *> r)) -[ tm ]->*
                 (([S1] *> T2 *> (T5 ^^ q) *> T4 *> (T3 ^^ An) *> L3) {{A}}> (T3 *> (T4 ^^ rem) *> r))).
  { rewrite hl3.
    set (A' := k + (2 * q + 2) + 2).
    assert (hA' : An = A' + 1) by (unfold An, A'; lia).
    assert (h5 : (([S1] *> (T3 ^^ An) *> T2 *> T0 *> l3) {{A}}> (T5 *> (T4 ^^ q) *> T3 *> (T4 ^^ rem) *> r)) -[ tm ]->*
                 (([S1] *> T2 *> T4 *> (T3 ^^ An) *> T0 *> l3) {{A}}> ((T4 ^^ q) *> T3 *> (T4 ^^ rem) *> r))).
    { rewrite hA', (zPsr1 T3).
      destruct (head0_t3_t0 A' ([S0; S1] *> T0 *> l3)) as [l' hl'].
      assert (hst1 : (([S1] *> T3 *> (T3 ^^ A') *> T2 *> T0 *> l3) {{A}}> (T5 *> (T4 ^^ q) *> T3 *> (T4 ^^ rem) *> r)) -[ tm ]->*
                     (((T3 ^^ A') *> T2 *> T0 *> l3) {{E}}> (T0 *> T2 *> T4 *> (T4 ^^ q) *> T3 *> (T4 ^^ rem) *> r))).
      { change (T2 *> T0 *> l3) with (T0 *> [S0; S1] *> T0 *> l3).
        rewrite hl'. exact (step_q0_t5_on_t3 l' ((T4 ^^ q) *> T3 *> (T4 ^^ rem) *> r)). }
      eapply stepStar_trans; [exact hst1 |].
      change (T2 *> T0 *> l3) with (T0 *> [S0; S1] *> T0 *> l3).
      eapply stepStar_trans; [exact (rule_E_t3 A' ([S0; S1] *> T0 *> l3) (T2 *> T4 *> (T4 ^^ q) *> T3 *> (T4 ^^ rem) *> r)) |].
      change (T0 *> [S0; S1] *> T0 *> l3) with (T2 *> T0 *> l3).
      eapply stepStar_trans; [exact (step_E_t2_bounce (T0 *> l3) ((T2 ^^ A') *> T2 *> T4 *> (T4 ^^ q) *> T3 *> (T4 ^^ rem) *> r)) |].
      rewrite (zPal1 T2).
      eapply stepStar_trans; [exact (rule_C_1_t2 (A' + 1) (T3 *> T0 *> l3) (T4 *> (T4 ^^ q) *> T3 *> (T4 ^^ rem) *> r)) |].
      rewrite (zPal1 T3).
      eapply stepStar_trans; [exact (step_C_1_to_q0 ((T3 ^^ ((A' + 1) + 1)) *> T0 *> l3) (T4 *> (T4 ^^ q) *> T3 *> (T4 ^^ rem) *> r)) |].
      rewrite (zPsr1 T3).
      exact (step_q0_t4_first ((T3 ^^ (A' + 1)) *> T0 *> l3) ((T4 ^^ q) *> T3 *> (T4 ^^ rem) *> r)). }
    eapply stepStar_trans; [exact h5 |].
    exact (rule_q0_t4_next q (T4 *> (T3 ^^ An) *> T0 *> l3) (T3 *> (T4 ^^ rem) *> r)). }
  exists ((T5 ^^ q) *> T4 *> (T3 ^^ An) *> L3).
  split.
  - exact (pipeL_noT2_blk q An hp3).
  - unfold aR. eapply stepStar_trans; [exact hs34 |].
    eapply stepStar_trans; [exact hs5 |].
    eapply stepStar_trans; [exact hs5b |].
    rewrite hT3comb. replace (k + (2 * q + 2) + 2 + 1) with An in hs6 by (unfold An; lia).
    exact (stepStar_trans hs6 hmid).
Qed.

Lemma pipeL_p1_asplit_odd_odd {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m q' rem : nat) (h : bool) (hE : m + 2 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    let aL := 2 * m + 1 in
    let aR := 2 * (q' + 1) + 1 in
    let s0 := (q' + 1) + (if h then 1 else 2) + rem in
    exists Lt', PipeL (En - m - 2) ((R_out ++ (T2 ^^ (aL + aR + 2))) ++ (T4 ^^ (q' + 1))) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ aL) *> T0 *> (T2 ^^ aR) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> (T3 *> (T4 ^^ rem) *> r)).
Proof.
  intros aL aR s0.
  destruct (pipeL_eat_t2_even (En := En) m 0 ltac:(lia) hp
    (T2 *> T0 *> (T2 ^^ (2 * (q' + 1) + 1)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) as [L1 [hp1 hs1]].
  rewrite zPz, zLan in hs1. replace (0 + 2 * m) with (2 * m) in hs1 by lia.
  assert (hE1eq : En - m = (En - m - 1) + 1) by lia.
  pose proof (pipeL_eqE hE1eq hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [L2 [hpull1 hp2]].
  pose proof (pull1_t3_t2 (2 * m) hl1 hpull1
    (T0 *> (T2 ^^ (2 * (q' + 1) + 1)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) as hs2.
  assert (hE2eq : En - m - 1 = (En - m - 2) + 1) by lia.
  pose proof (pipeL_eqE hE2eq hp2) as hp2'.
  destruct (pipeL_q5_t0_asplit_odd (2 * m) q' rem h hp2' r) as [Lt' [hp' hs3]].
  exists Lt'. split.
  - eapply pipeL_eqER; [exact hp' | lia |].
    unfold aL, aR; f_equal; f_equal; f_equal; lia.
  - unfold aL, aR. rewrite (pow_add_blank T2 (2 * m) 1), zP1.
    exact (stepStar_trans hs1 (stepStar_trans hs2 hs3)).
Qed.

Lemma pipeL_p1_asplit_odd_even {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m q rem : nat) (h : bool) (hE : m + 2 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    let aL := 2 * m + 1 in
    let aR := 2 * q + 2 in
    let s0 := q + (if h then 2 else 3) + rem in
    exists Lt', PipeL (En - m - 2) (((R_out ++ (T2 ^^ (aL + aR + 2))) ++ T5) ++ (T4 ^^ q)) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ aL) *> T0 *> (T2 ^^ aR) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> (T3 *> (T4 ^^ rem) *> r)).
Proof.
  intros aL aR s0.
  destruct (pipeL_eat_t2_even (En := En) m 0 ltac:(lia) hp
    (T2 *> T0 *> (T2 ^^ (2 * q + 2)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) as [L1 [hp1 hs1]].
  rewrite zPz, zLan in hs1. replace (0 + 2 * m) with (2 * m) in hs1 by lia.
  assert (hE1eq : En - m = (En - m - 1) + 1) by lia.
  pose proof (pipeL_eqE hE1eq hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [L2 [hpull1 hp2]].
  pose proof (pull1_t3_t2 (2 * m) hl1 hpull1
    (T0 *> (T2 ^^ (2 * q + 2)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) as hs2.
  assert (hE2eq : En - m - 1 = (En - m - 2) + 1) by lia.
  pose proof (pipeL_eqE hE2eq hp2) as hp2'.
  destruct (pipeL_q5_t0_asplit_even (2 * m) q rem h hp2' r) as [Lt' [hp' hs3]].
  exists Lt'. split.
  - eapply pipeL_eqER; [exact hp' | lia |].
    unfold aL, aR; f_equal; f_equal; f_equal; f_equal; lia.
  - unfold aL, aR. rewrite (pow_add_blank T2 (2 * m) 1), zP1.
    exact (stepStar_trans hs1 (stepStar_trans hs2 hs3)).
Qed.

Lemma pipeL_p2_double_asplit_odd_odd {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (a1 q2 q3' rem : nat) (h : bool) (hE : q2 + 1 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    let a2 := 2 * q2 + 1 in
    let a3 := 2 * (q3' + 1) + 1 in
    let s0 := (q3' + 1) + (if h then 1 else 2) + rem in
    exists Lt', PipeL (En - q2 - 1) ((R_out ++ (T2 ^^ (a1 + a2 + a3 + 3))) ++ (T4 ^^ (q3' + 1))) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> ((T2 ^^ a1) *> T0 *> (T2 ^^ a2) *> T0 *> (T2 ^^ a3) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> (T3 *> (T4 ^^ rem) *> r)).
Proof.
  intros a2 a3 s0.
  destruct (pipeL_asplit_prep (E_rem := En) a1 q2 1 ltac:(lia) hp
    ((T2 ^^ (2 * (q3' + 1) + 1)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) as [L1 [hp1 hs1]].
  rewrite zP1 in hs1.
  pose proof (step_q0_t0_t2 ((T3 ^^ (a1 + 2 * q2)) *> T2 *> L1)
    (T0 *> (T2 ^^ (2 * (q3' + 1) + 1)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) as hs2.
  rewrite <- (zPsr1 T3) in hs2.
  assert (hE2eq : En - q2 = (En - q2 - 1) + 1) by lia.
  pose proof (pipeL_eqE hE2eq hp1) as hp1'.
  destruct (pipeL_q5_t0_asplit_odd (a1 + 2 * q2 + 1) q3' rem h hp1' r) as [Lt' [hp' hs3]].
  exists Lt'. split.
  - eapply pipeL_eqER; [exact hp' | lia |].
    unfold a2, a3; f_equal; f_equal; f_equal; lia.
  - exact (stepStar_trans hs1 (stepStar_trans hs2 hs3)).
Qed.

Lemma pipeL_p2_double_asplit_odd_even {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (a1 q2 q3 rem : nat) (h : bool) (hE : q2 + 1 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    let a2 := 2 * q2 + 1 in
    let a3 := 2 * q3 + 2 in
    let s0 := q3 + (if h then 2 else 3) + rem in
    exists Lt', PipeL (En - q2 - 1) (((R_out ++ (T2 ^^ (a1 + a2 + a3 + 3))) ++ T5) ++ (T4 ^^ q3)) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> ((T2 ^^ a1) *> T0 *> (T2 ^^ a2) *> T0 *> (T2 ^^ a3) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> (T3 *> (T4 ^^ rem) *> r)).
Proof.
  intros a2 a3 s0.
  destruct (pipeL_asplit_prep (E_rem := En) a1 q2 1 ltac:(lia) hp
    ((T2 ^^ (2 * q3 + 2)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) as [L1 [hp1 hs1]].
  rewrite zP1 in hs1.
  pose proof (step_q0_t0_t2 ((T3 ^^ (a1 + 2 * q2)) *> T2 *> L1)
    (T0 *> (T2 ^^ (2 * q3 + 2)) *> (if h then T5 else []) *> (T4 ^^ s0) *> r)) as hs2.
  rewrite <- (zPsr1 T3) in hs2.
  assert (hE2eq : En - q2 = (En - q2 - 1) + 1) by lia.
  pose proof (pipeL_eqE hE2eq hp1) as hp1'.
  destruct (pipeL_q5_t0_asplit_even (a1 + 2 * q2 + 1) q3 rem h hp1' r) as [Lt' [hp' hs3]].
  exists Lt'. split.
  - eapply pipeL_eqER; [exact hp' | lia |].
    unfold a2, a3; f_equal; f_equal; f_equal; f_equal; lia.
  - exact (stepStar_trans hs1 (stepStar_trans hs2 hs3)).
Qed.

Lemma pipeL_asplit_heal_h1_b0_even {E_rem : nat} {R_out : list Sym} {Lt : Stream Sym}
    (aL q_as a2 s02 : nat) (h2 : bool) (hle : q_as <= E_rem) (hok : h2 = true \/ 1 <= s02)
    (hp : PipeL E_rem R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (E_rem - q_as)
        (R_out ++ (((T2 ^^ (aL + 2 * q_as + 2 + a2)) ++ (if h2 then T5 else [])) ++ (T4 ^^ s02))) Lt' /\
      (([S1] *> T2 *> Lt) {{A}}> ((T2 ^^ aL) *> T0 *> (T2 ^^ (2 * q_as)) *> T5 *> (T2 ^^ a2) *> (if h2 then T5 else []) *> (T4 ^^ s02) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  destruct (pipeL_asplit_prep aL q_as 0 hle hp
    ([S1; S0; S0; S1] *> (T2 ^^ a2) *> (if h2 then T5 else []) *> (T4 ^^ s02) *> r)) as [L1 [hp1 h1]].
  replace (2 * q_as + 0) with (2 * q_as) in h1 by lia. rewrite zPz, zLan in h1.
  change (T0 *> [S1; S0; S0; S1] *> (T2 ^^ a2) *> (if h2 then T5 else []) *> (T4 ^^ s02) *> r) with
    (T5 *> (T2 ^^ a2) *> (if h2 then T5 else []) *> (T4 ^^ s02) *> r) in h1.
  set (An := aL + 2 * q_as + 2 + a2).
  assert (h2_sw : (([S1] *> (T3 ^^ (aL + 2 * q_as)) *> T2 *> L1) {{A}}>
                    (T0 *> T5 *> (T2 ^^ a2) *> (if h2 then T5 else []) *> (T4 ^^ s02) *> r)) -[ tm ]->*
                  (([S1] *> (T3 ^^ An) *> T2 *> L1) {{A}}>
                    ((if h2 then T5 else []) *> (T4 ^^ s02) *> r))).
  { change (T0 *> T5 *> (T2 ^^ a2) *> (if h2 then T5 else []) *> (T4 ^^ s02) *> r) with
      (T2 *> T2 *> (T2 ^^ a2) *> (if h2 then T5 else []) *> (T4 ^^ s02) *> r).
    eapply stepStar_trans; [exact (step_q0_t2_one ((T3 ^^ (aL + 2 * q_as)) *> T2 *> L1) _) |].
    eapply stepStar_trans; [exact (step_q0_t2_one (T3 *> (T3 ^^ (aL + 2 * q_as)) *> T2 *> L1) _) |].
    eapply stepStar_trans; [exact (rule_q0_t2 a2 (T3 *> T3 *> (T3 ^^ (aL + 2 * q_as)) *> T2 *> L1) _) |].
    rewrite <- !(zPsr1 T3), <- (pow_add_blank T3).
    replace (a2 + (aL + 2 * q_as + 1 + 1)) with An by (unfold An; lia).
    apply evstep_refl. }
  destruct h2.
  - destruct (PipeL_head0 hp1) as [l1 hl1].
    set (A' := aL + 2 * q_as + 1 + a2).
    assert (hA' : An = A' + 1) by (unfold An, A'; lia).
    assert (hfin : (([S1] *> (T3 ^^ An) *> T2 *> L1) {{A}}> (T5 *> (T4 ^^ s02) *> r)) -[ tm ]->*
                   (([S1] *> T2 *> (T5 ^^ s02) *> T4 *> (T3 ^^ An) *> L1) {{A}}> r)).
    { rewrite hl1.
      assert (h5s : (([S1] *> (T3 ^^ An) *> T2 *> T0 *> l1) {{A}}> (T5 *> (T4 ^^ s02) *> r)) -[ tm ]->*
                    (([S1] *> T2 *> T4 *> (T3 ^^ An) *> T0 *> l1) {{A}}> ((T4 ^^ s02) *> r))).
      { rewrite hA', (zPsr1 T3).
        destruct (head0_t3_t0 A' ([S0; S1] *> T0 *> l1)) as [l' hl'].
        assert (hst1 : (([S1] *> T3 *> (T3 ^^ A') *> T2 *> T0 *> l1) {{A}}> (T5 *> (T4 ^^ s02) *> r)) -[ tm ]->*
                       (((T3 ^^ A') *> T2 *> T0 *> l1) {{E}}> (T0 *> T2 *> T4 *> (T4 ^^ s02) *> r))).
        { change (T2 *> T0 *> l1) with (T0 *> [S0; S1] *> T0 *> l1).
          rewrite hl'. exact (step_q0_t5_on_t3 l' ((T4 ^^ s02) *> r)). }
        eapply stepStar_trans; [exact hst1 |].
        change (T2 *> T0 *> l1) with (T0 *> [S0; S1] *> T0 *> l1).
        eapply stepStar_trans; [exact (rule_E_t3 A' ([S0; S1] *> T0 *> l1) (T2 *> T4 *> (T4 ^^ s02) *> r)) |].
        change (T0 *> [S0; S1] *> T0 *> l1) with (T2 *> T0 *> l1).
        eapply stepStar_trans; [exact (step_E_t2_bounce (T0 *> l1) ((T2 ^^ A') *> T2 *> T4 *> (T4 ^^ s02) *> r)) |].
        rewrite zPal1.
        eapply stepStar_trans; [exact (rule_C_1_t2 (A' + 1) (T3 *> T0 *> l1) (T4 *> (T4 ^^ s02) *> r)) |].
        rewrite zPal1.
        eapply stepStar_trans; [exact (step_C_1_to_q0 ((T3 ^^ ((A' + 1) + 1)) *> T0 *> l1) (T4 *> (T4 ^^ s02) *> r)) |].
        rewrite zPsr1.
        exact (step_q0_t4_first ((T3 ^^ (A' + 1)) *> T0 *> l1) ((T4 ^^ s02) *> r)). }
      eapply stepStar_trans; [exact h5s |].
      exact (rule_q0_t4_next s02 (T4 *> (T3 ^^ An) *> T0 *> l1) r). }
    exists ((T5 ^^ s02) *> T4 *> (T3 ^^ An) *> L1).
    split.
    + eapply pipeL_eqER; [exact (pipeL_noT2_blk s02 An hp1) | lia |].
      rewrite !append_assoc. reflexivity.
    + exact (stepStar_trans h1 (stepStar_trans h2_sw hfin)).
  - destruct hok as [Hfalse | hs02]; [discriminate |].
    set (b2' := s02 - 1).
    assert (hs02eq : s02 = b2' + 1) by (unfold b2'; lia).
    set (A' := aL + 2 * q_as + 1 + a2).
    assert (hA' : An = A' + 1) by (unfold An, A'; lia).
    assert (hfin : (([S1] *> (T3 ^^ An) *> T2 *> L1) {{A}}> (([] : list Sym) *> (T4 ^^ (b2' + 1)) *> r)) -[ tm ]->*
                   (([S1] *> T2 *> (T5 ^^ b2') *> T4 *> (T3 ^^ A') *> T2 *> L1) {{A}}> r)).
    { rewrite zLan, hA', (zPsr1 T3), (zPsr1 T4).
      eapply stepStar_trans; [exact (step_q0_t4_first ((T3 ^^ A') *> T2 *> L1) ((T4 ^^ b2') *> r)) |].
      exact (rule_q0_t4_next b2' (T4 *> (T3 ^^ A') *> T2 *> L1) r). }
    exists ((T5 ^^ b2') *> T4 *> (T3 ^^ A') *> T2 *> L1).
    split.
    + eapply pipeL_eqER; [exact (pipeL_T2_blk b2' A' hp1) | lia |].
      rewrite hs02eq, <- hA', app_nil_r, !append_assoc. reflexivity.
    + rewrite hs02eq in h1, h2_sw |- *.
      exact (stepStar_trans h1 (stepStar_trans h2_sw hfin)).
Qed.

Lemma pipeL_h1_b0_even_h1 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m a2 b2 : nat) (hle : m + 1 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (En - m - 1) (((R_out ++ (T2 ^^ (2 * m + 1 + a2))) ++ T5) ++ (T4 ^^ b2)) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ (2 * m)) *> T5 *> (T2 ^^ a2) *> T5 *> (T4 ^^ b2) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  destruct (pipeL_eat_t2_even (En := En) m 0 ltac:(lia) hp (T5 *> (T2 ^^ a2) *> T5 *> (T4 ^^ b2) *> r)) as [L1 [hp1 h1]].
  rewrite zPz, zLan in h1. replace (0 + 2 * m) with (2 * m) in h1 by lia.
  assert (hE1eq : En - m = (En - m - 1) + 1) by lia.
  pose proof (pipeL_eqE hE1eq hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [L2 [hpull hp2]].
  pose proof (pull1_t3_t5 (2 * m) hl1 hpull ((T2 ^^ a2) *> T5 *> (T4 ^^ b2) *> r)) as h2.
  pose proof (rule_q0_t2 a2 ((T3 ^^ (2 * m + 1)) *> T2 *> L2) (T5 *> (T4 ^^ b2) *> r)) as h3.
  assert (hcomb : (T3 ^^ a2) *> (T3 ^^ (2 * m + 1)) *> T2 *> L2 =
                  T3 *> (T3 ^^ (2 * m + a2)) *> T2 *> L2).
  { rewrite <- pow_add_blank. replace (a2 + (2 * m + 1)) with ((2 * m + a2) + 1) by lia. apply zPsr1. }
  destruct (PipeL_head0 hp2) as [l2 hl2].
  assert (h4 : (([S1] *> T3 *> (T3 ^^ (2 * m + a2)) *> T2 *> T0 *> l2) {{A}}> (T5 *> (T4 ^^ b2) *> r)) -[ tm ]->*
               (([S1] *> T2 *> (T5 ^^ b2) *> T4 *> (T3 ^^ (2 * m + a2 + 1)) *> T0 *> l2) {{A}}> r)).
  { destruct (head0_t3_t0 (2 * m + a2) ([S0; S1] *> T0 *> l2)) as [l' hl'].
    assert (hs1 : (([S1] *> T3 *> (T3 ^^ (2 * m + a2)) *> T2 *> T0 *> l2) {{A}}> (T5 *> (T4 ^^ b2) *> r)) -[ tm ]->*
                  (((T3 ^^ (2 * m + a2)) *> T2 *> T0 *> l2) {{E}}> (T0 *> T2 *> T4 *> (T4 ^^ b2) *> r))).
    { change (T2 *> T0 *> l2) with (T0 *> [S0; S1] *> T0 *> l2).
      rewrite hl'. exact (step_q0_t5_on_t3 l' ((T4 ^^ b2) *> r)). }
    eapply stepStar_trans; [exact hs1 |].
    change (T2 *> T0 *> l2) with (T0 *> [S0; S1] *> T0 *> l2).
    eapply stepStar_trans; [exact (rule_E_t3 (2 * m + a2) ([S0; S1] *> T0 *> l2) (T2 *> T4 *> (T4 ^^ b2) *> r)) |].
    change (T0 *> [S0; S1] *> T0 *> l2) with (T2 *> T0 *> l2).
    eapply stepStar_trans; [exact (step_E_t2_bounce (T0 *> l2) ((T2 ^^ (2 * m + a2)) *> T2 *> T4 *> (T4 ^^ b2) *> r)) |].
    rewrite (zPal1 T2).
    eapply stepStar_trans; [exact (rule_C_1_t2 (2 * m + a2 + 1) (T3 *> T0 *> l2) (T4 *> (T4 ^^ b2) *> r)) |].
    rewrite (zPal1 T3).
    eapply stepStar_trans; [exact (step_C_1_to_q0 ((T3 ^^ ((2 * m + a2 + 1) + 1)) *> T0 *> l2) (T4 *> (T4 ^^ b2) *> r)) |].
    rewrite (zPsr1 T3).
    eapply stepStar_trans; [exact (step_q0_t4_first ((T3 ^^ (2 * m + a2 + 1)) *> T0 *> l2) ((T4 ^^ b2) *> r)) |].
    exact (rule_q0_t4_next b2 (T4 *> (T3 ^^ (2 * m + a2 + 1)) *> T0 *> l2) r). }
  rewrite <- hl2 in h4.
  pose proof (pipeL_noT2_blk b2 (2 * m + a2 + 1) hp2) as hp2blk.
  exists ((T5 ^^ b2) *> T4 *> (T3 ^^ (2 * m + a2 + 1)) *> L2).
  split.
  - eapply pipeL_eqER; [exact hp2blk | lia |].
    f_equal; f_equal; f_equal; f_equal; lia.
  - eapply stepStar_trans; [exact h1 |].
    eapply stepStar_trans; [exact h2 |].
    eapply stepStar_trans; [exact h3 |].
    rewrite hcomb. exact h4.
Qed.

Lemma pipeL_h1_b0_even_h0 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m a2 b2 : nat) (hle : m + 1 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (En - m - 1) ((R_out ++ (T2 ^^ (2 * m + 1 + a2))) ++ (T4 ^^ (b2 + 1))) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ (2 * m)) *> T5 *> (T2 ^^ a2) *> (T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  destruct (pipeL_eat_t2_even (En := En) m 0 ltac:(lia) hp (T5 *> (T2 ^^ a2) *> (T4 ^^ (b2 + 1)) *> r)) as [L1 [hp1 h1]].
  rewrite zPz, zLan in h1. replace (0 + 2 * m) with (2 * m) in h1 by lia.
  assert (hE1eq : En - m = (En - m - 1) + 1) by lia.
  pose proof (pipeL_eqE hE1eq hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [L2 [hpull hp2]].
  pose proof (pull1_t3_t5 (2 * m) hl1 hpull ((T2 ^^ a2) *> (T4 ^^ (b2 + 1)) *> r)) as h2.
  pose proof (rule_q0_t2 a2 ((T3 ^^ (2 * m + 1)) *> T2 *> L2) ((T4 ^^ (b2 + 1)) *> r)) as h3.
  assert (hcomb : (T3 ^^ a2) *> (T3 ^^ (2 * m + 1)) *> T2 *> L2 =
                  T3 *> (T3 ^^ (2 * m + a2)) *> T2 *> L2).
  { rewrite <- pow_add_blank. replace (a2 + (2 * m + 1)) with ((2 * m + a2) + 1) by lia. apply zPsr1. }
  assert (h4 : (([S1] *> T3 *> (T3 ^^ (2 * m + a2)) *> T2 *> L2) {{A}}> ((T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
               (([S1] *> T2 *> (T5 ^^ b2) *> T4 *> (T3 ^^ (2 * m + a2)) *> T2 *> L2) {{A}}> r)).
  { rewrite (zPsr1 T4).
    eapply stepStar_trans; [exact (step_q0_t4_first ((T3 ^^ (2 * m + a2)) *> T2 *> L2) ((T4 ^^ b2) *> r)) |].
    exact (rule_q0_t4_next b2 (T4 *> (T3 ^^ (2 * m + a2)) *> T2 *> L2) r). }
  pose proof (pipeL_T2_blk b2 (2 * m + a2) hp2) as hp2blk.
  exists ((T5 ^^ b2) *> T4 *> (T3 ^^ (2 * m + a2)) *> T2 *> L2).
  split.
  - eapply pipeL_eqER; [exact hp2blk | lia |].
    f_equal; f_equal; f_equal; lia.
  - eapply stepStar_trans; [exact h1 |].
    eapply stepStar_trans; [exact h2 |].
    eapply stepStar_trans; [exact h3 |].
    rewrite hcomb. exact h4.
Qed.

Lemma pipeL_h1_b0_odd_h0 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m a2 b2 : nat) (hle : m + 1 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (En - m - 1) (((R_out ++ (T2 ^^ (2 * m + 2 + a2))) ++ T5) ++ (T4 ^^ b2)) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ (2 * m + 1)) *> T5 *> (T2 ^^ a2) *> (T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  rewrite (pow_add_blank T2 (2 * m) 1), zP1.
  destruct (pipeL_eat_t2_even (En := En) m 0 ltac:(lia) hp (T2 *> T5 *> (T2 ^^ a2) *> (T4 ^^ (b2 + 1)) *> r)) as [L1 [hp1 h1]].
  rewrite zPz, zLan in h1. replace (0 + 2 * m) with (2 * m) in h1 by lia.
  assert (hE1eq : En - m = (En - m - 1) + 1) by lia.
  pose proof (pipeL_eqE hE1eq hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [L2 [hpull hp2]].
  pose proof (pull1_t3_t2_t5 (2 * m) hl1 hpull ((T2 ^^ a2) *> (T4 ^^ (b2 + 1)) *> r)) as h2.
  pose proof (rule_q0_t2 a2 ((T3 ^^ (2 * m + 3)) *> L2) ((T4 ^^ (b2 + 1)) *> r)) as h3.
  assert (hcomb : (T3 ^^ a2) *> (T3 ^^ (2 * m + 3)) *> L2 =
                  T3 *> (T3 ^^ (2 * m + 2 + a2)) *> L2).
  { rewrite <- pow_add_blank. replace (a2 + (2 * m + 3)) with ((2 * m + 2 + a2) + 1) by lia. apply zPsr1. }
  assert (h4 : (([S1] *> T3 *> (T3 ^^ (2 * m + 2 + a2)) *> L2) {{A}}> ((T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
               (([S1] *> T2 *> (T5 ^^ b2) *> T4 *> (T3 ^^ (2 * m + 2 + a2)) *> L2) {{A}}> r)).
  { rewrite (zPsr1 T4).
    eapply stepStar_trans; [exact (step_q0_t4_first ((T3 ^^ (2 * m + 2 + a2)) *> L2) ((T4 ^^ b2) *> r)) |].
    exact (rule_q0_t4_next b2 (T4 *> (T3 ^^ (2 * m + 2 + a2)) *> L2) r). }
  pose proof (pipeL_noT2_blk b2 (2 * m + 2 + a2) hp2) as hp2blk.
  exists ((T5 ^^ b2) *> T4 *> (T3 ^^ (2 * m + 2 + a2)) *> L2).
  split.
  - exact hp2blk.
  - eapply stepStar_trans; [exact h1 |].
    eapply stepStar_trans; [exact h2 |].
    eapply stepStar_trans; [exact h3 |].
    rewrite hcomb. exact h4.
Qed.

Lemma rule_q0_t3_not2_t0_t2 (K : nat) (l r : Stream Sym) :
    (([S1] *> (T3 ^^ K) *> T0 *> l) {{A}}> (T0 *> T2 *> T0 *> r)) -[ tm ]->*
    (([S1; S1] *> T0 *> l) {{F}}> ([S0; S1] *> (T2 ^^ K) *> T0 *> T0 *> r)).
Proof.
  eapply stepStar_trans; [exact (step_q0_t0_t2 ((T3 ^^ K) *> T0 *> l) (T0 *> r)) |].
  assert (h8 : (([S1; S1] *> T3 *> (T3 ^^ K) *> T0 *> l) {{F}}> (T0 *> r)) -[ tm ]->*
               ((T3 *> (T3 ^^ K) *> T0 *> l) {{E}}> (T0 *> T0 *> T0 *> r)))
    by exact (step_8A_head ([S1; S1] *> (T3 ^^ K) *> T0 *> l) r).
  eapply stepStar_trans; [exact h8 |].
  rewrite <- (zPsr1 T3).
  exact (rule_E_t3_to_Q5 K l (T0 *> T0 *> r)).
Qed.

Lemma pipeL_h1_b0_odd_asplit_h0_even {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m a2 q' b2 : nat) (hle : m + q' + 2 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (En - m - q' - 2) ((R_out ++ (T2 ^^ (2 * m + 1 + a2 + 2 * (q' + 1) + 2))) ++ T5) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ (2 * m + 1)) *> T5 *> (T2 ^^ a2) *> T0 *> (T2 ^^ (2 * (q' + 1))) *> (T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
      (([S1; S1] *> Lt') {{F}}> ((T4 ^^ b2) *> r)).
Proof.
  rewrite (pow_add_blank T2 (2 * m) 1), zP1.
  destruct (pipeL_eat_t2_even (En := En) m 0 ltac:(lia) hp
    (T2 *> T5 *> (T2 ^^ a2) *> T0 *> (T2 ^^ (2 * (q' + 1))) *> (T4 ^^ (b2 + 1)) *> r)) as [L1 [hp1 h1]].
  rewrite zPz, zLan in h1. replace (0 + 2 * m) with (2 * m) in h1 by lia.
  assert (hE1eq : En - m = (En - m - 1) + 1) by lia.
  pose proof (pipeL_eqE hE1eq hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [L2 [hpull1 hp2]].
  pose proof (pull1_t3_t2_t5 (2 * m) hl1 hpull1
    ((T2 ^^ a2) *> T0 *> (T2 ^^ (2 * (q' + 1))) *> (T4 ^^ (b2 + 1)) *> r)) as h2.
  pose proof (rule_q0_t2 a2 ((T3 ^^ (2 * m + 3)) *> L2)
    (T0 *> (T2 ^^ (2 * (q' + 1))) *> (T4 ^^ (b2 + 1)) *> r)) as h3.
  assert (hcomb : (T3 ^^ a2) *> (T3 ^^ (2 * m + 3)) *> L2 = (T3 ^^ (2 * m + 3 + a2)) *> L2).
  { rewrite <- pow_add_blank. f_equal. f_equal. lia. }
  assert (hE2eq : En - m - 1 = (En - m - 2) + 1) by lia.
  pose proof (pipeL_eqE hE2eq hp2) as hp2'.
  destruct (PipeL_head0 hp2') as [l2 hl2].
  destruct (PipeL_pull hp2') as [L3 [hpull2 hp3]].
  assert (hT2split : (T2 ^^ (2 * (q' + 1))) *> (T4 ^^ (b2 + 1)) *> r =
                     T2 *> (T2 ^^ (2 * q' + 1)) *> (T4 ^^ (b2 + 1)) *> r).
  { replace (2 * (q' + 1)) with (1 + (2 * q' + 1)) by lia.
    rewrite pow_add_blank, zP1. reflexivity. }
  assert (h4 : (([S1] *> (T3 ^^ (2 * m + 3 + a2)) *> L2) {{A}}>
                 (T0 *> (T2 ^^ (2 * (q' + 1))) *> (T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
               (([S1; S1] *> L2) {{F}}>
                 ([S0; S1] *> (T2 ^^ (2 * m + 3 + a2)) *> T0 *> (T2 ^^ (2 * q' + 1)) *> (T4 ^^ (b2 + 1)) *> r))).
  { rewrite hl2, hT2split.
    assert (hhd : (T2 ^^ (2 * q' + 1)) *> (T4 ^^ (b2 + 1)) *> r =
                  T0 *> [S0; S1] *> (T2 ^^ (2 * q')) *> (T4 ^^ (b2 + 1)) *> r).
    { replace (2 * q' + 1) with (1 + 2 * q') by lia.
      rewrite pow_add_blank, zP1. reflexivity. }
    rewrite hhd.
    exact (rule_q0_t3_not2_t0_t2 (2 * m + 3 + a2) l2 ([S0; S1] *> (T2 ^^ (2 * q')) *> (T4 ^^ (b2 + 1)) *> r)). }
  assert (h5 : (([S1; S1] *> L2) {{F}}>
                 ([S0; S1] *> (T2 ^^ (2 * m + 3 + a2)) *> T0 *> (T2 ^^ (2 * q' + 1)) *> (T4 ^^ (b2 + 1)) *> r)) -[ tm ]->*
               (([S1] *> T2 *> L3) {{A}}>
                 ((T2 ^^ (2 * m + 3 + a2)) *> T0 *> (T2 ^^ (2 * q' + 1)) *> (T4 ^^ (b2 + 1)) *> r))).
  { change ([S0; S1] *> (T2 ^^ (2 * m + 3 + a2)) *> T0 *> (T2 ^^ (2 * q' + 1)) *> (T4 ^^ (b2 + 1)) *> r) with
      (T0 *> [S1] *> (T2 ^^ (2 * m + 3 + a2)) *> T0 *> (T2 ^^ (2 * q' + 1)) *> (T4 ^^ (b2 + 1)) *> r).
    exact (stepStar_trans (hpull2 _) (post_pull_q0 L3 _)). }
  destruct (pipeL_asplit_heal_h0_odd (E_rem := En - m - 2) (2 * m + 3 + a2) q' b2 ltac:(lia) hp3 r) as [L4 [hp4 h6]].
  exists L4. split.
  - eapply pipeL_eqER; [exact hp4 | lia |].
    f_equal; f_equal; f_equal; lia.
  - eapply stepStar_trans; [exact h1 |].
    eapply stepStar_trans; [exact h2 |].
    eapply stepStar_trans; [exact h3 |].
    rewrite hcomb. exact (stepStar_trans h4 (stepStar_trans h5 h6)).
Qed.

Lemma pipeL_h1_b0_odd_h1 {En : nat} {R_out : list Sym} {Lt : Stream Sym}
    (m a2 b2 : nat) (hle : m + 2 <= En) (hp : PipeL En R_out Lt) (r : Stream Sym) :
    exists Lt', PipeL (En - m - 2) ((R_out ++ (T2 ^^ (2 * m + 2 + a2))) ++ (T4 ^^ (b2 + 1))) Lt' /\
      (([S1; S1] *> Lt) {{F}}> ((T2 ^^ (2 * m + 1)) *> T5 *> (T2 ^^ a2) *> T5 *> (T4 ^^ b2) *> r)) -[ tm ]->*
      (([S1] *> T2 *> Lt') {{A}}> r).
Proof.
  rewrite (pow_add_blank T2 (2 * m) 1), zP1.
  destruct (pipeL_eat_t2_even (En := En) m 0 ltac:(lia) hp (T2 *> T5 *> (T2 ^^ a2) *> T5 *> (T4 ^^ b2) *> r)) as [L1 [hp1 h1]].
  rewrite zPz, zLan in h1. replace (0 + 2 * m) with (2 * m) in h1 by lia.
  assert (hE1eq : En - m = (En - m - 1) + 1) by lia.
  pose proof (pipeL_eqE hE1eq hp1) as hp1'.
  destruct (PipeL_head0 hp1') as [l1 hl1].
  destruct (PipeL_pull hp1') as [L2 [hpull1 hp2]].
  pose proof (pull1_t3_t2_t5 (2 * m) hl1 hpull1 ((T2 ^^ a2) *> T5 *> (T4 ^^ b2) *> r)) as h2.
  assert (hE2eq : En - m - 1 = (En - m - 2) + 1) by lia.
  pose proof (pipeL_eqE hE2eq hp2) as hp2'.
  destruct (PipeL_head0 hp2') as [l2 hl2].
  destruct (PipeL_pull hp2') as [L3 [hpull2 hp3]].
  pose proof (rule_q0_t2 a2 ((T3 ^^ (2 * m + 3)) *> L2) (T5 *> (T4 ^^ b2) *> r)) as h3.
  assert (hcomb : (T3 ^^ a2) *> (T3 ^^ (2 * m + 3)) *> L2 =
                  T3 *> (T3 ^^ (2 * m + 2 + a2)) *> L2).
  { rewrite <- pow_add_blank. replace (a2 + (2 * m + 3)) with ((2 * m + 2 + a2) + 1) by lia. apply zPsr1. }
  destruct (head0_t3_t0 (2 * m + 2 + a2) l2) as [l2' hl2'].
  assert (hs_t5 : (([S1] *> T3 *> (T3 ^^ (2 * m + 2 + a2)) *> L2) {{A}}> (T5 *> (T4 ^^ b2) *> r)) -[ tm ]->*
                  (((T3 ^^ (2 * m + 2 + a2)) *> L2) {{E}}> (T0 *> T2 *> T4 *> (T4 ^^ b2) *> r))).
  { rewrite hl2, hl2'. exact (step_q0_t5_on_t3 l2' ((T4 ^^ b2) *> r)). }
  assert (hs_e : (((T3 ^^ (2 * m + 2 + a2)) *> L2) {{E}}> (T0 *> T2 *> T4 *> (T4 ^^ b2) *> r)) -[ tm ]->*
                 (([S1; S1] *> L2) {{F}}> ([S0; S1] *> (T2 ^^ (2 * m + 2 + a2)) *> T4 *> (T4 ^^ b2) *> r))).
  { rewrite hl2. replace (2 * m + 2 + a2) with ((2 * m + 1 + a2) + 1) at 1 by lia.
    eapply stepStar_trans; [exact (rule_E_t3_to_Q5 (2 * m + 1 + a2) l2 (T2 *> T4 *> (T4 ^^ b2) *> r)) |].
    rewrite (zPal1 T2). replace ((2 * m + 1 + a2) + 1) with (2 * m + 2 + a2) by lia. apply evstep_refl. }
  assert (hs_after : (([S1; S1] *> L2) {{F}}> ([S0; S1] *> (T2 ^^ (2 * m + 2 + a2)) *> T4 *> (T4 ^^ b2) *> r)) -[ tm ]->*
                     (([S1] *> T2 *> (T5 ^^ b2) *> T4 *> (T3 ^^ (2 * m + 1 + a2)) *> T2 *> L3) {{A}}> r)).
  { change ([S0; S1] *> (T2 ^^ (2 * m + 2 + a2)) *> T4 *> (T4 ^^ b2) *> r) with
      (T0 *> [S1] *> (T2 ^^ (2 * m + 2 + a2)) *> T4 *> (T4 ^^ b2) *> r).
    eapply stepStar_trans; [exact (hpull2 _) |].
    eapply stepStar_trans; [exact (post_pull_q0 L3 _) |].
    eapply stepStar_trans; [exact (rule_q0_t2 (2 * m + 2 + a2) (T2 *> L3) (T4 *> (T4 ^^ b2) *> r)) |].
    replace (2 * m + 2 + a2) with ((2 * m + 1 + a2) + 1) by lia. rewrite (zPsr1 T3).
    eapply stepStar_trans; [exact (step_q0_t4_first ((T3 ^^ (2 * m + 1 + a2)) *> T2 *> L3) ((T4 ^^ b2) *> r)) |].
    exact (rule_q0_t4_next b2 (T4 *> (T3 ^^ (2 * m + 1 + a2)) *> T2 *> L3) r). }
  pose proof (pipeL_T2_blk b2 (2 * m + 1 + a2) hp3) as hp3blk.
  exists ((T5 ^^ b2) *> T4 *> (T3 ^^ (2 * m + 1 + a2)) *> T2 *> L3).
  split.
  - eapply pipeL_eqER; [exact hp3blk | lia |].
    f_equal; f_equal; f_equal; lia.
  - eapply stepStar_trans; [exact h1 |].
    eapply stepStar_trans; [exact h2 |].
    eapply stepStar_trans; [exact h3 |].
    rewrite hcomb. exact (stepStar_trans hs_t5 (stepStar_trans hs_e hs_after)).
Qed.

(* --- ScratchS6A2.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

Ltac Zify.zify_pre_hook ::=
  repeat match goal with
  | x := _ : nat |- _ => unfold x in *; clear x
  | x := _ : N |- _ => unfold x in *; clear x
  end.

(* ========================================================================= *)
(* N <-> nat Parity & Division Helpers                                       *)
(* ========================================================================= *)

Lemma N_div2_to_nat (x : N) : N.to_nat (x / 2)%N = N.to_nat x / 2.
Proof.
  pose proof (N.div_mod x 2 ltac:(discriminate)) as H1.
  pose proof (N.mod_lt x 2 ltac:(lia)) as H2.
  pose proof (Nat.div_mod (N.to_nat x) 2 ltac:(lia)) as H3.
  pose proof (Nat.mod_upper_bound (N.to_nat x) 2 ltac:(lia)) as H4.
  lia.
Qed.

Lemma N_mod2_to_nat (x : N) : N.to_nat (x mod 2)%N = N.to_nat x mod 2.
Proof.
  pose proof (N.div_mod x 2 ltac:(discriminate)) as H1.
  pose proof (N.mod_lt x 2 ltac:(lia)) as H2.
  pose proof (Nat.div_mod (N.to_nat x) 2 ltac:(lia)) as H3.
  pose proof (Nat.mod_upper_bound (N.to_nat x) 2 ltac:(lia)) as H4.
  lia.
Qed.

Lemma N_mod2_eqb0_nat (x : N) : ((x mod 2 =? 0)%N) = Nat.eqb (N.to_nat x mod 2) 0.
Proof.
  rewrite <- N_mod2_to_nat.
  destruct ((x mod 2 =? 0)%N) eqn:H1; [apply N.eqb_eq in H1 | apply N.eqb_neq in H1];
    symmetry; [apply Nat.eqb_eq | apply Nat.eqb_neq]; lia.
Qed.

Lemma N_mod2_eq1_decomp (x : N) (h : (x mod 2 =? 1)%N = true) :
    N.to_nat x = 2 * N.to_nat (x / 2)%N + 1.
Proof.
  apply N.eqb_eq in h.
  pose proof (N.div_mod x 2 ltac:(discriminate)) as Hdm.
  lia.
Qed.

Lemma N_mod2_ne1_decomp (x : N) (h : (x mod 2 =? 1)%N = false) :
    N.to_nat x = 2 * N.to_nat (x / 2)%N.
Proof.
  apply N.eqb_neq in h.
  pose proof (N.div_mod x 2 ltac:(discriminate)) as Hdm.
  pose proof (N.mod_lt x 2 ltac:(lia)) as Hlt.
  lia.
Qed.

Lemma N_mod2_eq0_decomp (x : N) (h : (x mod 2 =? 0)%N = true) :
    N.to_nat x = 2 * N.to_nat (x / 2)%N.
Proof.
  apply N.eqb_eq in h.
  pose proof (N.div_mod x 2 ltac:(discriminate)) as Hdm.
  lia.
Qed.

Lemma N_mod2_ne0_decomp (x : N) (h : (x mod 2 =? 0)%N = false) :
    N.to_nat x = 2 * N.to_nat (x / 2)%N + 1.
Proof.
  apply N.eqb_neq in h.
  pose proof (N.div_mod x 2 ltac:(discriminate)) as Hdm.
  pose proof (N.mod_lt x 2 ltac:(lia)) as Hlt.
  lia.
Qed.

(* ========================================================================= *)
(* AsplitSound & step1Phase1Asplit_sound                                     *)
(* ========================================================================= *)

Definition AsplitSound (revOut : list RleItem) (aL : N) (hb : bool)
    (s0 : N) (segTail : list SegPiece) (aR : N) (rest : list RleItem)
    (Lt : Stream Sym) (res : AsplitResult) : Prop :=
  match res with
  | ARcreate out =>
      (([S1; S1] *> Lt) {{F}}>
        (encItems (RIsingle aL hb s0 segTail (Some aR) :: rest) *> [S0; S1; S0; S1] *> b0))
        -[ tm ]->* HubCfg out
  | ARdump E_rem a h' q segs =>
      exists L1,
        PipeL (N.to_nat E_rem)
          (((encItems (List.rev revOut) ++ (T2 ^^ N.to_nat a)) ++ (if h' then T5 else [])) ++
            (T4 ^^ N.to_nat q)) L1 /\
        (([S1; S1] *> Lt) {{F}}>
          (encItems (RIsingle aL hb s0 segTail (Some aR) :: rest) *> [S0; S1; S0; S1] *> b0))
          -[ tm ]->*
          (([S1] *> T2 *> L1) {{A}}> (encSegTail segs *> encItems rest *> [S0; S1; S0; S1] *> b0))
  | ARcont E' rev' segs =>
      exists L1,
        PipeL (N.to_nat E') (encItems (List.rev rev')) L1 /\
        (([S1; S1] *> Lt) {{F}}>
          (encItems (RIsingle aL hb s0 segTail (Some aR) :: rest) *> [S0; S1; S0; S1] *> b0))
          -[ tm ]->*
          (([S1; S1] *> L1) {{F}}> (encSegTail segs *> encItems rest *> [S0; S1; S0; S1] *> b0))
  | ARcontDrop1 E' rev' segs2 =>
      exists item2 rest2 L1,
        rest = item2 :: rest2 /\
        PipeL (N.to_nat E') (encItems (List.rev rev')) L1 /\
        (([S1; S1] *> Lt) {{F}}>
          (encItems (RIsingle aL hb s0 segTail (Some aR) :: rest) *> [S0; S1; S0; S1] *> b0))
          -[ tm ]->*
          (([S1; S1] *> L1) {{F}}> (encSegTail segs2 *> encItems rest2 *> [S0; S1; S0; S1] *> b0))
  | ARcontDrop1P2 E' rev' =>
      exists item2 rest2 L1,
        rest = item2 :: rest2 /\
        PipeL (N.to_nat E') (encItems (List.rev rev')) L1 /\
        (([S1; S1] *> Lt) {{F}}>
          (encItems (RIsingle aL hb s0 segTail (Some aR) :: rest) *> [S0; S1; S0; S1] *> b0))
          -[ tm ]->*
          (([S1] *> T2 *> L1) {{A}}> (encItems rest2 *> [S0; S1; S0; S1] *> b0))
  end.

Lemma step1Phase1Asplit_sound {En : N} {revOut : list RleItem} {aL : N} {hb : bool}
    {s0 : N} {segTail : list SegPiece} {aR : N} {rest : list RleItem} {Lt : Stream Sym}
    {res : AsplitResult}
    (hp : PipeL (N.to_nat En) (encItems (List.rev revOut)) Lt)
    (h : step1Phase1Asplit En revOut aL hb s0 segTail aR rest = Some res) :
    AsplitSound revOut aL hb s0 segTail aR rest Lt res.
Proof.
  unfold step1Phase1Asplit in h.
  destruct (((aL mod 2 =? 1)%N && (aL / 2 + 2 <=? En)%N)%bool) eqn:Hcond1.
  - apply Bool.andb_true_iff in Hcond1; destruct Hcond1 as [HaLodd HEn].
    apply N.leb_le in HEn.
    pose proof (N_mod2_eq1_decomp aL HaLodd) as HaL_eq.
    set (m := N.to_nat (aL / 2)%N) in *.
    destruct ((negb hb && (s0 =? 1)%N && isEmpty segTail)%bool) eqn:Hs1c.
    + apply Bool.andb_true_iff in Hs1c; destruct Hs1c as [Hs1c1 Hemp].
      apply Bool.andb_true_iff in Hs1c1; destruct Hs1c1 as [Hnhb Hs01].
      destruct hb; [discriminate |].
      apply N.eqb_eq in Hs01; subst s0.
      apply isEmpty_true_iff in Hemp; subst segTail.
      destruct rest as [|[a2 [|] b2 segTail2 [?|] | | |] rest2]; try discriminate.
      * (* h2 = true *)
        destruct (((1 <=? a2)%N && (1 <=? b2)%N && (a2 + 2 <=? aR)%N && isEmpty segTail2)%bool) eqn:Hc2; [|discriminate].
        apply Bool.andb_true_iff in Hc2; destruct Hc2 as [Hc2 Hemp2]; apply isEmpty_true_iff in Hemp2; subst segTail2.
        split_andb.
        inversion h; subst res; cbn [AsplitSound].
        set (remN := (aR - a2 - 2)%N).
        assert (Hrem : N.to_nat remN = N.to_nat aR - N.to_nat a2 - 2) by (unfold remN; lia).
        assert (Hdiv : N.to_nat (remN / 2)%N = (N.to_nat aR - N.to_nat a2 - 2) / 2)
          by (rewrite N_div2_to_nat, Hrem; reflexivity).
        assert (Hhout : ((remN mod 2 =? 0)%N) = Nat.eqb ((N.to_nat aR - N.to_nat a2 - 2) mod 2) 0)
          by (rewrite N_mod2_eqb0_nat, Hrem; reflexivity).
        destruct (pipeL_p1_asplit_odd_h0_s1_merge_h1 (En := N.to_nat En) m (N.to_nat aR) (N.to_nat a2) (N.to_nat (b2 - 1)%N)
                    ltac:(lia) ltac:(lia) ltac:(lia) hp
                    (encItems rest2 *> [S0; S1; S0; S1] *> b0)) as [L1 [hp1 hs1]].
        exists (RIsingle a2 true b2 [] None), rest2, L1.
        split; [reflexivity | split].
        -- eapply pipeL_eqER; [exact hp1 | lia |].
           rewrite encItems_rev_cons; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
           rewrite ?app_nil_r, ?append_assoc.
           replace (2 * m + 1 + N.to_nat aR + N.to_nat a2 + 3) with (N.to_nat (aL + aR + a2 + 3)%N) by lia.
           rewrite <- Hhout.
           replace (if (remN mod 2 =? 0)%N then N.to_nat (b2 - 1)%N else N.to_nat (b2 - 1)%N + 1)
             with (N.to_nat (if (remN mod 2 =? 0)%N then (b2 - 1)%N else (b2 - 1 + 1)%N))
             by (destruct (remN mod 2 =? 0)%N; lia).
           reflexivity.
        -- cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
           rewrite HaL_eq, N_to_nat_1, list_pow_one, ?app_nil_r, ?Str_app_assoc.
           replace (N.to_nat b2) with (N.to_nat (b2 - 1)%N + 1) by lia.
           exact hs1.
      * (* h2 = false *)
        destruct (((1 <=? a2)%N && (1 <=? b2)%N && (a2 + 2 <=? aR)%N)%bool) eqn:Hc2; [|discriminate].
        split_andb.
        set (remN := (aR - a2 - 2)%N) in *.
        assert (Hrem : N.to_nat remN = N.to_nat aR - N.to_nat a2 - 2) by (unfold remN; lia).
        assert (Hdiv : N.to_nat (remN / 2)%N = (N.to_nat aR - N.to_nat a2 - 2) / 2)
          by (rewrite N_div2_to_nat, Hrem; reflexivity).
        assert (Hhout : ((remN mod 2 =? 0)%N) = Nat.eqb ((N.to_nat aR - N.to_nat a2 - 2) mod 2) 0)
          by (rewrite N_mod2_eqb0_nat, Hrem; reflexivity).
        destruct ((b2 - 1 <=? En - aL / 2 - 1 + remN / 2)%N) eqn:HEb; [|discriminate].
        apply N.leb_le in HEb.
        inversion h; subst res; cbn [AsplitSound].
        destruct (pipeL_p1_asplit_odd_h0_s1_merge (En := N.to_nat En) m (N.to_nat aR) (N.to_nat a2) (N.to_nat (b2 - 1)%N)
                    ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) hp
                    (encSegTail segTail2 *> encItems rest2 *> [S0; S1; S0; S1] *> b0)) as [L1 [hp1 hs1]].
        exists (RIsingle a2 false b2 segTail2 None), rest2, L1.
        split; [reflexivity | split].
        -- eapply pipeL_eqER; [exact hp1 | lia |].
           rewrite encItems_rev_cons; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
           rewrite ?app_nil_r, ?append_assoc.
           replace (2 * m + 1 + N.to_nat aR + N.to_nat a2 + 2) with (N.to_nat (aL + aR + a2 + 2)%N) by lia.
           rewrite <- Hhout.
           replace (if (remN mod 2 =? 0)%N then N.to_nat (b2 - 1)%N else N.to_nat (b2 - 1)%N + 1)
             with (N.to_nat (if (remN mod 2 =? 0)%N then (b2 - 1)%N else (b2 - 1 + 1)%N))
             by (destruct (remN mod 2 =? 0)%N; lia).
           reflexivity.
        -- cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
           rewrite HaL_eq, N_to_nat_1, list_pow_one, ?app_nil_r, ?Str_app_assoc.
           replace (N.to_nat b2) with (N.to_nat (b2 - 1)%N + 1) by lia.
           exact hs1.
    + destruct ((hb && (s0 =? 0)%N && isEmpty segTail)%bool) eqn:Hs0c.
      * apply Bool.andb_true_iff in Hs0c; destruct Hs0c as [Hs0c1 Hemp].
        apply Bool.andb_true_iff in Hs0c1; destruct Hs0c1 as [Hhb Hs00].
        destruct hb; [|discriminate].
        apply N.eqb_eq in Hs00; subst s0.
        apply isEmpty_true_iff in Hemp; subst segTail.
        destruct rest as [|[a2 [|] b2 segTail2 [?|] | | |] rest2]; try discriminate.
        -- (* h2 = true *)
           destruct (((1 <=? b2)%N && (a2 + 2 <=? aR)%N && isEmpty segTail2)%bool) eqn:Hc2; [|discriminate].
           apply Bool.andb_true_iff in Hc2; destruct Hc2 as [Hc2 Hemp2]; apply isEmpty_true_iff in Hemp2; subst segTail2.
           split_andb.
           inversion h; subst res; cbn [AsplitSound].
           set (remN := (aR - a2 - 2)%N).
           assert (Hrem : N.to_nat remN = N.to_nat aR - N.to_nat a2 - 2) by (unfold remN; lia).
           assert (Hdiv : N.to_nat (remN / 2)%N = (N.to_nat aR - N.to_nat a2 - 2) / 2)
             by (rewrite N_div2_to_nat, Hrem; reflexivity).
           assert (Hhout : ((remN mod 2 =? 0)%N) = Nat.eqb ((N.to_nat aR - N.to_nat a2 - 2) mod 2) 0)
             by (rewrite N_mod2_eqb0_nat, Hrem; reflexivity).
           destruct (pipeL_p1_asplit_odd_h1_s0_merge_h1 (En := N.to_nat En) m (N.to_nat aR) (N.to_nat a2) (N.to_nat (b2 - 1)%N)
                       ltac:(lia) ltac:(lia) hp
                       (encItems rest2 *> [S0; S1; S0; S1] *> b0)) as [L1 [hp1 hs1]].
           exists (RIsingle a2 true b2 [] None), rest2, L1.
           split; [reflexivity | split].
           ++ eapply pipeL_eqER; [exact hp1 | lia |].
              rewrite encItems_rev_cons; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
              rewrite ?app_nil_r, ?append_assoc.
              replace (2 * m + 1 + N.to_nat aR + N.to_nat a2 + 3) with (N.to_nat (aL + aR + a2 + 3)%N) by lia.
              rewrite <- Hhout.
              replace (if (remN mod 2 =? 0)%N then N.to_nat (b2 - 1)%N else N.to_nat (b2 - 1)%N + 1)
                with (N.to_nat (if (remN mod 2 =? 0)%N then (b2 - 1)%N else (b2 - 1 + 1)%N))
                by (destruct (remN mod 2 =? 0)%N; lia).
              reflexivity.
           ++ cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail N.to_nat].
              rewrite HaL_eq, list_pow_zero, ?app_nil_r, ?Str_app_assoc.
              replace (N.to_nat b2) with (N.to_nat (b2 - 1)%N + 1) by lia.
              exact hs1.
        -- (* h2 = false *)
           destruct (((1 <=? b2)%N && (a2 + 2 <=? aR)%N)%bool) eqn:Hc2; [|discriminate].
           split_andb.
           set (remN := (aR - a2 - 2)%N) in *.
           assert (Hrem : N.to_nat remN = N.to_nat aR - N.to_nat a2 - 2) by (unfold remN; lia).
           assert (Hdiv : N.to_nat (remN / 2)%N = (N.to_nat aR - N.to_nat a2 - 2) / 2)
             by (rewrite N_div2_to_nat, Hrem; reflexivity).
           assert (Hhout : ((remN mod 2 =? 0)%N) = Nat.eqb ((N.to_nat aR - N.to_nat a2 - 2) mod 2) 0)
             by (rewrite N_mod2_eqb0_nat, Hrem; reflexivity).
           destruct ((b2 - 1 <=? En - aL / 2 - 1 + remN / 2)%N) eqn:HEb; [|discriminate].
           apply N.leb_le in HEb.
           inversion h; subst res; cbn [AsplitSound].
           destruct (pipeL_p1_asplit_odd_h1_s0_merge_h0 (En := N.to_nat En) m (N.to_nat aR) (N.to_nat a2) (N.to_nat (b2 - 1)%N)
                       ltac:(lia) ltac:(lia) ltac:(lia) hp
                       (encSegTail segTail2 *> encItems rest2 *> [S0; S1; S0; S1] *> b0)) as [L1 [hp1 hs1]].
           exists (RIsingle a2 false b2 segTail2 None), rest2, L1.
           split; [reflexivity | split].
           ++ eapply pipeL_eqER; [exact hp1 | lia |].
              rewrite encItems_rev_cons; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
              rewrite ?app_nil_r, ?append_assoc.
              replace (2 * m + 1 + N.to_nat aR + N.to_nat a2 + 2) with (N.to_nat (aL + aR + a2 + 2)%N) by lia.
              rewrite <- Hhout.
              replace (if (remN mod 2 =? 0)%N then N.to_nat (b2 - 1)%N else N.to_nat (b2 - 1)%N + 1)
                with (N.to_nat (if (remN mod 2 =? 0)%N then (b2 - 1)%N else (b2 - 1 + 1)%N))
                by (destruct (remN mod 2 =? 0)%N; lia).
              reflexivity.
           ++ cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail N.to_nat].
              rewrite HaL_eq, list_pow_zero, ?app_nil_r, ?Str_app_assoc.
              replace (N.to_nat b2) with (N.to_nat (b2 - 1)%N + 1) by lia.
              exact hs1.
      * destruct ((aR mod 2 =? 1)%N) eqn:HaRodd.
        -- pose proof (N_mod2_eq1_decomp aR HaRodd) as HaR_eq.
           destruct ((1 <=? aR / 2)%N) eqn:Hq1; [|discriminate].
           apply N.leb_le in Hq1.
           set (q' := N.to_nat (aR / 2)%N - 1).
           assert (HaR_q : N.to_nat aR = 2 * (q' + 1) + 1) by (unfold q'; lia).
           set (baseN := (if hb then 1 else 2)%N) in *.
           assert (Hbase_nat : N.to_nat baseN = (if hb then 1 else 2)) by (unfold baseN; destruct hb; lia).
           destruct ((aR / 2 + baseN <=? s0)%N) eqn:Hs0.
           ++ apply N.leb_le in Hs0.
              inversion h; subst res; cbn [AsplitSound].
              set (rem := N.to_nat (s0 - (aR / 2 + baseN))%N).
              destruct (pipeL_p1_asplit_odd_odd (En := N.to_nat En) m q' rem hb ltac:(lia) hp
                          (encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0)) as [L1 [hp1 hs1]].
              exists L1. split.
              ** eapply pipeL_eqER; [exact hp1 | lia |].
                 rewrite app_nil_r.
                 replace (2 * m + 1 + (2 * (q' + 1) + 1) + 2) with (N.to_nat (aL + aR + 2)%N) by lia.
                 replace (q' + 1) with (N.to_nat (aR / 2)%N) by (unfold q'; lia).
                 reflexivity.
              ** cbn [encItems encSegTail]; unfold encItem, encSingle.
                 rewrite ?Str_app_assoc, HaL_eq, HaR_q.
                 replace (N.to_nat s0) with ((q' + 1) + (if hb then 1 else 2) + rem) by (unfold rem, q'; lia).
                 exact hs1.
           ++ destruct ((baseN <=? s0)%N) eqn:Hbase; [|discriminate].
              apply N.leb_le in Hbase. apply N.leb_gt in Hs0.
              inversion h; subst res; cbn [AsplitSound].
              set (p := N.to_nat (s0 - baseN)%N).
              set (d := N.to_nat (aR / 2 - (s0 - baseN) - 1)%N).
              destruct (pipeL_p1_asplit_odd_odd_small_s0 (En := N.to_nat En) m p d hb ltac:(lia) hp
                          (encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0)) as [L1 [hp1 hs1]].
              exists L1. split.
              ** eapply pipeL_eqER; [exact hp1 | unfold d, p; lia |].
                 rewrite encItems_rev_cons; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
                 rewrite ?app_nil_r, ?append_assoc.
                 replace (2 * m + 1 + (2 * (p + d + 1) + 1) + 2) with (N.to_nat (aL + aR + 2)%N) by (unfold p, d, q' in *; lia).
                 replace (p + 1) with (N.to_nat (s0 - baseN + 1)%N) by (unfold p; lia).
                 reflexivity.
              ** cbn [encItems]; unfold encItem, encSingle.
                 rewrite ?Str_app_assoc, HaL_eq.
                 replace (N.to_nat aR) with (2 * (p + d + 1) + 1) by (unfold p, d, q' in *; lia).
                 replace (N.to_nat s0) with (p + (if hb then 1 else 2)) by (unfold p; lia).
                 exact hs1.
        -- pose proof (N_mod2_ne1_decomp aR HaRodd) as HaR_even.
           destruct ((2 <=? aR)%N) eqn:HaR2; [|discriminate].
           apply N.leb_le in HaR2.
           set (q := N.to_nat ((aR - 2) / 2)%N).
           assert (Hq_eq : N.to_nat aR = 2 * q + 2).
           { unfold q. rewrite N_div2_to_nat.
             pose proof (Nat.div_mod (N.to_nat (aR - 2)%N) 2 ltac:(lia)).
             pose proof (Nat.mod_upper_bound (N.to_nat (aR - 2)%N) 2 ltac:(lia)).
             lia. }
           set (baseN := (if hb then 2 else 3)%N) in *.
           assert (Hbase_nat : N.to_nat baseN = (if hb then 2 else 3)) by (unfold baseN; destruct hb; lia).
           destruct ((((aR - 2) / 2 + baseN) <=? s0)%N) eqn:Hs0.
           ++ apply N.leb_le in Hs0.
              inversion h; subst res; cbn [AsplitSound].
              set (rem := N.to_nat (s0 - ((aR - 2) / 2 + baseN))%N).
              destruct (pipeL_p1_asplit_odd_even (En := N.to_nat En) m q rem hb ltac:(lia) hp
                          (encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0)) as [L1 [hp1 hs1]].
              exists L1. split.
              ** eapply pipeL_eqER; [exact hp1 | lia |].
                 replace (2 * m + 1 + (2 * q + 2) + 2) with (N.to_nat (aL + aR + 2)%N) by lia.
                 reflexivity.
              ** cbn [encItems encSegTail]; unfold encItem, encSingle.
                 rewrite ?Str_app_assoc, HaL_eq, Hq_eq.
                 replace (N.to_nat s0) with (q + (if hb then 2 else 3) + rem) by (unfold rem, q; lia).
                 exact hs1.
           ++ apply N.leb_gt in Hs0.
              destruct ((baseN <=? s0)%N) eqn:Hbase.
              ** apply N.leb_le in Hbase.
                 inversion h; subst res; cbn [AsplitSound].
                 set (p := N.to_nat (s0 - baseN)%N).
                 set (d := N.to_nat ((aR - 2) / 2 - (s0 - baseN) - 1)%N).
                 destruct (pipeL_p1_asplit_odd_even_small_s0 (En := N.to_nat En) m p d hb ltac:(lia) hp
                             (encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0)) as [L1 [hp1 hs1]].
                 exists L1. split.
                 --- eapply pipeL_eqER; [exact hp1 | unfold d, p, q in *; lia |].
                     rewrite encItems_rev_cons; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
                     rewrite ?app_nil_r, ?append_assoc.
                     replace (2 * m + 1 + (2 * (p + d + 1) + 2) + 2) with (N.to_nat (aL + aR + 2)%N)
                       by (unfold p, d, q in *; lia).
                     replace (p + 1) with (N.to_nat (s0 - baseN + 1)%N) by (unfold p; lia).
                     reflexivity.
                 --- cbn [encItems]; unfold encItem, encSingle.
                     rewrite ?Str_app_assoc, HaL_eq.
                     replace (N.to_nat aR) with (2 * (p + d + 1) + 2) by (unfold p, d, q in *; lia).
                     replace (N.to_nat s0) with (p + (if hb then 2 else 3)) by (unfold p; lia).
                     exact hs1.
              ** destruct (((negb hb && (s0 =? 2)%N) || (hb && (s0 =? 1)%N))%bool) eqn:Hs2c; [|discriminate].
                 inversion h; subst res; cbn [AsplitSound].
                 assert (Hs0_eq : N.to_nat s0 = (if hb then 1 else 2)).
                 { destruct hb; simpl in Hs2c; rewrite ?Bool.orb_false_r in Hs2c; apply N.eqb_eq in Hs2c; subst s0; lia. }
                 destruct (pipeL_p1_asplit_odd_even_s2_or_h1s1 (En := N.to_nat En) m q hb ltac:(lia) hp
                             (encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0)) as [L1 [hp1 hs1]].
                 exists L1. split.
                 --- eapply pipeL_eqER; [exact hp1 | unfold q; lia |].
                     rewrite encItems_rev_cons; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail N.to_nat].
                     rewrite list_pow_zero, ?app_nil_r, ?append_assoc.
                     replace (2 * m + 1 + (2 * q + 2) + 2) with (N.to_nat (aL + aR + 2)%N) by lia.
                     reflexivity.
                 --- cbn [encItems]; unfold encItem, encSingle.
                     rewrite ?Str_app_assoc, HaL_eq, Hq_eq, Hs0_eq.
                     exact hs1.
  - destruct (((1 <=? En)%N && (2 * En + 1 <=? aL)%N)%bool) eqn:Hcr; [|discriminate].
    split_andb. inversion h; subst res; cbn [AsplitSound].
    pose proof (pipeL_asplit_create (En := N.to_nat En) (N.to_nat aL) ltac:(lia) ltac:(lia) hp
      (T0 *> (T2 ^^ N.to_nat aR) *> (if hb then T5 else []) *> (T4 ^^ N.to_nat s0) *>
        encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0)) as Hstep.
    cbn [encItems]; unfold encItem, encSingle; rewrite ?Str_app_assoc.
    eapply stepStar_trans; [exact Hstep |].
    unfold HubCfg. rewrite encItems_append; cbn [encItems]; unfold encItem, encSingle, encTok.
    rewrite N_to_nat_1, list_pow_one, ?Str_app_assoc.
    replace (2 * N.to_nat En - 1) with (N.to_nat (2 * En - 1)%N) by lia.
    replace (N.to_nat aL - 2 * N.to_nat En) with (N.to_nat (aL - 2 * En)%N) by lia.
    apply evstep_refl.
Qed.

(* ========================================================================= *)
(* Big Prefix & b0=0 Merge Helpers                                           *)
(* ========================================================================= *)

Lemma step_c0_merge_mid (a0 : nat) (h0 : bool) (b0_v a1 : nat)
    (hm : isMergeC0 h0 (N.of_nat b0_v) (N.of_nat a1) = true) (ha : a1 + 1 <= a0) (r : Stream Sym) :
    let d := a0 - a1 - 1 in
    (b0 {{E}}> (T2 *> T0 *> T1 *> (T2 ^^ a0) *> (if h0 then T5 else []) *> (T4 ^^ b0_v) *> (T2 ^^ a1) *> r))
      -[ tm ]->*
      (([S1; S1] *> (T3 ^^ (1 + 2 * a1 + 1)) *> T2 *> (T2 ^^ d) *> [S0; S1; S0; S1] *> b0) {{F}}> r).
Proof.
  intros d.
  assert (ha0_eq : a0 = a1 + 1 + d) by (unfold d; lia).
  unfold isMergeC0 in hm.
  destruct h0.
  - simpl in hm. rewrite Bool.orb_false_r in hm. apply N.eqb_eq in hm.
    assert (hb0 : b0_v = 0) by lia; subst b0_v.
    rewrite zPz, zLan.
    eapply stepStar_trans; [exact (step_c0_prefix ((T2 ^^ a0) *> T5 *> (T2 ^^ a1) *> r)) |].
    eapply stepStar_trans; [exact (rule_c0_t2 a0 (T2 *> [S0; S1; S0; S1] *> b0) (T5 *> (T2 ^^ a1) *> r)) |].
    assert (hL0 : (T2 ^^ a0) *> T2 *> [S0; S1; S0; S1] *> b0 =
                  T2 *> (T2 ^^ a0) *> [S0; S1; S0; S1] *> b0).
    { rewrite zPal1. replace (a0 + 1) with (1 + a0) by lia.
      rewrite pow_add_blank, zP1. reflexivity. }
    destruct (head0_t2_t0 a0 ([S1; S0; S1] *> b0)) as [lt hlt].
    rewrite hL0.
    assert (hcap : ((T2 *> (T2 ^^ a0) *> [S0; S1; S0; S1] *> b0) {{C}}> (T5 *> (T2 ^^ a1) *> r)) -[ tm ]->*
                   (([S1; S1] *> (T3 ^^ 2) *> (T2 ^^ a0) *> [S0; S1; S0; S1] *> b0) {{F}}> ((T2 ^^ a1) *> r))).
    { change ([S0; S1; S0; S1] *> b0) with (T0 *> [S1; S0; S1] *> b0).
      rewrite hlt. exact (step_c0_h1_b0z_cap lt ((T2 ^^ a1) *> r)). }
    eapply stepStar_trans; [exact hcap |].
    assert (hpow : (T2 ^^ a0) *> [S0; S1; S0; S1] *> b0 =
                   (T2 ^^ a1) *> T2 *> (T2 ^^ d) *> [S0; S1; S0; S1] *> b0).
    { rewrite ha0_eq, !pow_add_blank, zP1. reflexivity. }
    rewrite hpow.
    exact (rule_q5_t3_t2_eat_t2 a1 1 (T2 *> (T2 ^^ d) *> [S0; S1; S0; S1] *> b0) r).
  - simpl in hm. apply Bool.andb_true_iff in hm; destruct hm as [Hb01 Ha11].
    apply N.eqb_eq in Hb01; apply N.leb_le in Ha11.
    assert (hb0 : b0_v = 1) by lia; subst b0_v.
    assert (ha1 : 1 <= a1) by lia.
    rewrite zLan, zP1.
    set (a1' := a1 - 1).
    set (a0' := a0 - 1).
    replace a1 with (a1' + 1) by (unfold a1'; lia).
    replace a0 with (a0' + 1) by (unfold a0'; lia).
    eapply stepStar_trans; [exact (step_c0_prefix ((T2 ^^ (a0' + 1)) *> T4 *> (T2 ^^ (a1' + 1)) *> r)) |].
    eapply stepStar_trans; [exact (rule_c0_t2 (a0' + 1) (T2 *> [S0; S1; S0; S1] *> b0) (T4 *> (T2 ^^ (a1' + 1)) *> r)) |].
    assert (hL0 : (T2 ^^ (a0' + 1)) *> T2 *> [S0; S1; S0; S1] *> b0 =
                  T2 *> T2 *> (T2 ^^ a0') *> [S0; S1; S0; S1] *> b0).
    { rewrite zPal1. replace (a0' + 1 + 1) with (2 + a0') by lia.
      rewrite pow_add_blank, !zPsr, zPz, zLan. reflexivity. }
    rewrite hL0, (zPsr1 T2 a1').
    eapply stepStar_trans; [exact (step_c0_h0_b1_cap ((T2 ^^ a0') *> [S0; S1; S0; S1] *> b0) ((T2 ^^ a1') *> r)) |].
    assert (hpow : (T2 ^^ a0') *> [S0; S1; S0; S1] *> b0 =
                   (T2 ^^ a1') *> T2 *> (T2 ^^ d) *> [S0; S1; S0; S1] *> b0).
    { replace a0' with (a1' + 1 + d) by (unfold a0', a1', d; lia).
      rewrite !pow_add_blank, zP1. reflexivity. }
    rewrite hpow.
    pose proof (rule_q5_t3_t2_eat_t2 a1' 3 (T2 *> (T2 ^^ d) *> [S0; S1; S0; S1] *> b0) r) as heat.
    replace (3 + 2 * a1' + 1) with (1 + 2 * (a1' + 1) + 1) in heat by lia.
    exact heat.
Qed.

Lemma pipeL_start_c0_b0z_h0 (a0 : N) (h0 : bool) (b0_v a1 b1' : N)
    (hm : isMergeC0 h0 b0_v a1 = true) (ha : (a1 + 1 <= a0)%N)
    (hb : (b1' <= (a0 - a1 - 1) / 2)%N) (r : Stream Sym) :
    let d := (a0 - a1 - 1)%N in
    let Ev := (d / 2)%N in
    let item :=
      if (d mod 2 =? 0)%N then RIsingle (a0 + a1 + 3)%N true b1' [] None
      else RIsingle (a0 + a1 + 3)%N false (b1' + 1)%N [] None in
    exists Lt, PipeL (N.to_nat (Ev - b1')%N) (encItems (List.rev [item])) Lt /\
      (b0 {{E}}> (T2 *> T0 *> T1 *> (T2 ^^ N.to_nat a0) *> (if h0 then T5 else []) *>
        (T4 ^^ N.to_nat b0_v) *> (T2 ^^ N.to_nat a1) *> (T4 ^^ (N.to_nat b1' + 1)) *> r))
        -[ tm ]->* (([S1; S1] *> Lt) {{F}}> r).
Proof.
  intros d Ev item.
  assert (Hm_nat : isMergeC0 h0 (N.of_nat (N.to_nat b0_v)) (N.of_nat (N.to_nat a1)) = true)
    by (rewrite !N2Nat.id; exact hm).
  pose proof (step_c0_merge_mid (N.to_nat a0) h0 (N.to_nat b0_v) (N.to_nat a1) Hm_nat ltac:(lia)
                ((T4 ^^ (N.to_nat b1' + 1)) *> r)) as Hmid.
  replace (N.to_nat a0 - N.to_nat a1 - 1) with (N.to_nat d) in Hmid by (unfold d; lia).
  assert (Hpre : (b0 {{E}}> (T2 *> T0 *> T1 *> (T2 ^^ N.to_nat a0) *> (if h0 then T5 else []) *>
                    (T4 ^^ N.to_nat b0_v) *> (T2 ^^ N.to_nat a1) *> (T4 ^^ (N.to_nat b1' + 1)) *> r))
                 -[ tm ]->*
                 (([S1; S1] *> T4 *> (T3 ^^ (3 + 2 * N.to_nat a1)) *> (T2 ^^ N.to_nat d) *> [S0; S1; S0; S1] *> b0)
                    {{F}}> ((T4 ^^ N.to_nat b1') *> r))).
  { eapply stepStar_trans; [exact Hmid |].
    rewrite (zPsr1 T4).
    replace (3 + 2 * N.to_nat a1) with ((1 + 2 * N.to_nat a1) + 2) by lia.
    exact (step_heal_odd_h0 (1 + 2 * N.to_nat a1) ((T2 ^^ N.to_nat d) *> [S0; S1; S0; S1] *> b0)
             ((T4 ^^ N.to_nat b1') *> r)). }
  unfold item.
  destruct ((d mod 2 =? 0)%N) eqn:Hpar.
  - pose proof (N_mod2_eq0_decomp d Hpar) as Hd_eq.
    pose proof (pipeL_base_c0_noT2 (N.to_nat Ev) 0 (3 + 2 * N.to_nat a1)) as Hbase.
    rewrite !zPz, zLan, app_nil_r in Hbase.
    replace (2 * N.to_nat Ev) with (N.to_nat d) in Hbase by (unfold Ev; lia).
    destruct (pipeL_eat_t4 (En := N.to_nat Ev) (N.to_nat b1') ltac:(lia) Hbase r) as [Lt [hp heat]].
    exists Lt. split.
    + eapply pipeL_eqER; [exact hp | lia |].
      cbn [List.rev app encItems]; unfold encItem, encSingle; cbn [encSegTail].
      rewrite ?app_nil_r.
      replace (3 + 2 * N.to_nat a1 + N.to_nat d + 1) with (N.to_nat (a0 + a1 + 3)%N)
        by (unfold d in *; lia).
      reflexivity.
    + exact (stepStar_trans Hpre heat).
  - pose proof (N_mod2_ne0_decomp d Hpar) as Hd_eq.
    pose proof (pipeL_base_c0_T2 (N.to_nat Ev) 0 (3 + 2 * N.to_nat a1)) as Hbase.
    rewrite zPz, zLan in Hbase.
    assert (HT2d : (T2 ^^ (2 * N.to_nat Ev)) *> T2 *> [S0; S1; S0; S1] *> b0 =
                   (T2 ^^ N.to_nat d) *> [S0; S1; S0; S1] *> b0).
    { unfold Ev; rewrite Hd_eq, pow_add_blank, zP1; reflexivity. }
    rewrite HT2d in Hbase.
    destruct (pipeL_eat_t4 (En := N.to_nat Ev) (N.to_nat b1') ltac:(lia) Hbase r) as [Lt [hp heat]].
    exists Lt. split.
    + eapply pipeL_eqER; [exact hp | lia |].
      cbn [List.rev app encItems]; unfold encItem, encSingle; cbn [encSegTail].
      rewrite ?app_nil_r, append_assoc, <- list_pow_add.
      replace (0 + 1 + N.to_nat b1') with (N.to_nat (b1' + 1)%N) by lia.
      replace (3 + 2 * N.to_nat a1 + 2 * N.to_nat Ev + 2) with (N.to_nat (a0 + a1 + 3)%N)
        by (unfold Ev, d in *; lia).
      reflexivity.
    + exact (stepStar_trans Hpre heat).
Qed.

Lemma pipeL_start_c0_b0z_h1 (a0 : N) (h0 : bool) (b0_v a1 b1' : N)
    (hm : isMergeC0 h0 b0_v a1 = true) (ha : (a1 + 1 <= a0)%N) (r : Stream Sym) :
    let d := (a0 - a1 - 1)%N in
    let Ev := (d / 2)%N in
    let item :=
      if (d mod 2 =? 0)%N then RIsingle (a0 + a1 + 4)%N true b1' [] None
      else RIsingle (a0 + a1 + 4)%N false (b1' + 1)%N [] None in
    exists Lt, PipeL (N.to_nat Ev) (encItems (List.rev [item])) Lt /\
      (b0 {{E}}> (T2 *> T0 *> T1 *> (T2 ^^ N.to_nat a0) *> (if h0 then T5 else []) *>
        (T4 ^^ N.to_nat b0_v) *> (T2 ^^ N.to_nat a1) *> T5 *> (T4 ^^ (N.to_nat b1' + 1)) *> r))
        -[ tm ]->* (([S1] *> T2 *> Lt) {{A}}> r).
Proof.
  intros d Ev item.
  assert (Hm_nat : isMergeC0 h0 (N.of_nat (N.to_nat b0_v)) (N.of_nat (N.to_nat a1)) = true)
    by (rewrite !N2Nat.id; exact hm).
  pose proof (step_c0_merge_mid (N.to_nat a0) h0 (N.to_nat b0_v) (N.to_nat a1) Hm_nat ltac:(lia)
                (T5 *> (T4 ^^ (N.to_nat b1' + 1)) *> r)) as Hmid.
  replace (N.to_nat a0 - N.to_nat a1 - 1) with (N.to_nat d) in Hmid by (unfold d; lia).
  assert (Hpre : (b0 {{E}}> (T2 *> T0 *> T1 *> (T2 ^^ N.to_nat a0) *> (if h0 then T5 else []) *>
                    (T4 ^^ N.to_nat b0_v) *> (T2 ^^ N.to_nat a1) *> T5 *> (T4 ^^ (N.to_nat b1' + 1)) *> r))
                 -[ tm ]->*
                 (([S1] *> T2 *> (T5 ^^ N.to_nat b1') *> T4 *> (T3 ^^ (4 + 2 * N.to_nat a1)) *>
                    (T2 ^^ N.to_nat d) *> [S0; S1; S0; S1] *> b0) {{A}}> r)).
  { eapply stepStar_trans; [exact Hmid |].
    eapply stepStar_trans;
      [exact (step_heal_odd_h1 (1 + 2 * N.to_nat a1) ((T2 ^^ N.to_nat d) *> [S0; S1; S0; S1] *> b0)
               ((T4 ^^ (N.to_nat b1' + 1)) *> r)) |].
    replace (1 + 2 * N.to_nat a1 + 4) with (S (4 + 2 * N.to_nat a1)) by lia.
    rewrite (zPsr T3), (zPsr1 T4).
    eapply stepStar_trans;
      [exact (step_q0_t4_first ((T3 ^^ (4 + 2 * N.to_nat a1)) *> (T2 ^^ N.to_nat d) *> [S0; S1; S0; S1] *> b0)
               ((T4 ^^ N.to_nat b1') *> r)) |].
    exact (rule_q0_t4_next (N.to_nat b1')
             (T4 *> (T3 ^^ (4 + 2 * N.to_nat a1)) *> (T2 ^^ N.to_nat d) *> [S0; S1; S0; S1] *> b0) r). }
  unfold item.
  destruct ((d mod 2 =? 0)%N) eqn:Hpar.
  - pose proof (N_mod2_eq0_decomp d Hpar) as Hd_eq.
    pose proof (pipeL_base_c0_noT2 (N.to_nat Ev) (N.to_nat b1') (4 + 2 * N.to_nat a1)) as Hbase.
    replace (2 * N.to_nat Ev) with (N.to_nat d) in Hbase by (unfold Ev; lia).
    eexists; split; [| exact Hpre].
    eapply pipeL_eqR; [| exact Hbase].
    cbn [List.rev app encItems]; unfold encItem, encSingle; cbn [encSegTail].
    rewrite ?app_nil_r.
    replace (4 + 2 * N.to_nat a1 + N.to_nat d + 1) with (N.to_nat (a0 + a1 + 4)%N)
      by (unfold d in *; lia).
    reflexivity.
  - pose proof (N_mod2_ne0_decomp d Hpar) as Hd_eq.
    pose proof (pipeL_base_c0_T2 (N.to_nat Ev) (N.to_nat b1') (4 + 2 * N.to_nat a1)) as Hbase.
    assert (HT2d : (T2 ^^ (2 * N.to_nat Ev)) *> T2 *> [S0; S1; S0; S1] *> b0 =
                   (T2 ^^ N.to_nat d) *> [S0; S1; S0; S1] *> b0).
    { unfold Ev; rewrite Hd_eq, pow_add_blank, zP1; reflexivity. }
    rewrite HT2d in Hbase.
    eexists; split; [| exact Hpre].
    eapply pipeL_eqR; [| exact Hbase].
    cbn [List.rev app encItems]; unfold encItem, encSingle; cbn [encSegTail].
    rewrite ?app_nil_r.
    replace (4 + 2 * N.to_nat a1 + 2 * N.to_nat Ev + 2) with (N.to_nat (a0 + a1 + 4)%N)
      by (unfold Ev, d in *; lia).
    replace (N.to_nat b1' + 1) with (N.to_nat (b1' + 1)%N) by lia.
    reflexivity.
Qed.

Lemma step1HubPrefixBig_sound {pref : list RleItem} (tail : list RleItem)
    {isP2 : bool} {E' : N} {revOut : list RleItem}
    (h : step1HubPrefixBig pref = Some (isP2, E', revOut)) :
    exists Lt', PipeL (N.to_nat E') (encItems (List.rev revOut)) Lt' /\
      (HubCfg (pref ++ tail)) -[ tm ]->*
        (if isP2 then (([S1] *> T2 *> Lt') {{A}}> (encItems tail *> [S0; S1; S0; S1] *> b0))
         else (([S1; S1] *> Lt') {{F}}> (encItems tail *> [S0; S1; S0; S1] *> b0))).
Proof.
  unfold step1HubPrefixBig in h.
  destruct (step1HubPrefix pref) as [r|] eqn:Hp.
  - inversion h; subst r. exact (step1HubPrefix_sound tail Hp).
  - destruct pref as [|[a0 [|] b0_v [|? ?] [?|] | | |] rest]; try discriminate.
    + (* h0 = true *)
      destruct ((b0_v =? 1)%N) eqn:Hb01.
      * apply N.eqb_eq in Hb01; subst b0_v.
        destruct (((2 <=? a0)%N && (a0 mod 2 =? 0)%N)%bool) eqn:Hc; [|discriminate].
        split_andb.
        pose proof (N_mod2_eq0_decomp a0 ltac:(apply N.eqb_eq; lia)) as Ha0_eq.
        set (m := N.to_nat (a0 / 2 - 1)%N).
        destruct (pipeL_start_c0_h1 m 0 (Nat.le_0_l m)
                    (encItems rest *> encItems tail *> [S0; S1; S0; S1] *> b0)) as [L0 [hp0 hs0]].
        assert (Hp0' : PipeL (N.to_nat (a0 / 2 - 1)%N)
                         (encItems (List.rev [RIsingle (a0 + 3)%N false 1%N [] None])) L0).
        { eapply pipeL_eqER; [exact hp0 | unfold m; lia |].
          cbn [List.rev app encItems]; unfold encItem, encSingle; cbn [encSegTail].
          rewrite N_to_nat_1, ?app_nil_r.
          replace (2 * m + 5) with (N.to_nat (a0 + 3)%N) by (unfold m; lia).
          reflexivity. }
        destruct (proj1 (step1Pref_sound rest) _ _ isP2 E' revOut L0
                    (encItems tail *> [S0; S1; S0; S1] *> b0) Hp0' h) as [Lt' [hp' hs2]].
        exists Lt'; split; [exact hp' |].
        unfold HubCfg; cbn [List.app encItems]; unfold encItem, encSingle; cbn [encSegTail].
        rewrite encItems_append, N_to_nat_1, ?app_nil_r, ?Str_app_assoc.
        replace (N.to_nat a0) with (2 * m + 2) by (unfold m; lia).
        exact (stepStar_trans hs0 hs2).
      * destruct rest as [|[a1 h1 b1 [|? ?] [?|] | | |] rest2]; try discriminate.
        destruct ((isMergeC0 true b0_v a1 && (a1 + 1 <=? a0)%N && (1 <=? b1)%N)%bool) eqn:Hc; [|discriminate].
        apply Bool.andb_true_iff in Hc; destruct Hc as [Hc1 Hb1]; apply Bool.andb_true_iff in Hc1; destruct Hc1 as [Hm Ha].
        apply N.leb_le in Ha; apply N.leb_le in Hb1.
        destruct h1; simpl negb in h.
        -- destruct (pipeL_start_c0_b0z_h1 a0 true b0_v a1 (b1 - 1)%N Hm Ha
                       (encItems rest2 *> encItems tail *> [S0; S1; S0; S1] *> b0)) as [L0 [hp0 hs0]].
           replace (if ((a0 - a1 - 1) mod 2 =? 0)%N
                    then RIsingle (a0 + a1 + 4)%N true (b1 - 1)%N [] None
                    else RIsingle (a0 + a1 + 4)%N false (b1 - 1 + 1)%N [] None)
             with (if ((a0 - a1 - 1) mod 2 =? 0)%N
                   then RIsingle (a0 + a1 + 4)%N true (b1 - 1)%N [] None
                   else RIsingle (a0 + a1 + 4)%N false b1 [] None) in hp0
             by (destruct (((a0 - a1 - 1) mod 2 =? 0)%N); [reflexivity | repeat f_equal; lia]).
           destruct (proj2 (step1Pref_sound rest2) _ _ isP2 E' revOut L0
                       (encItems tail *> [S0; S1; S0; S1] *> b0) hp0 h) as [Lt' [hp' hs2]].
           exists Lt'; split; [exact hp' |].
           unfold HubCfg; cbn [List.app encItems]; unfold encItem, encSingle; cbn [encSegTail].
           rewrite encItems_append, ?app_nil_r, ?Str_app_assoc.
           replace (N.to_nat b1) with (N.to_nat (b1 - 1)%N + 1) by lia.
           exact (stepStar_trans hs0 hs2).
        -- destruct ((b1 - 1 <=? (a0 - a1 - 1) / 2)%N) eqn:Hb; [|discriminate].
           apply N.leb_le in Hb.
           destruct (pipeL_start_c0_b0z_h0 a0 true b0_v a1 (b1 - 1)%N Hm Ha Hb
                       (encItems rest2 *> encItems tail *> [S0; S1; S0; S1] *> b0)) as [L0 [hp0 hs0]].
           replace (if ((a0 - a1 - 1) mod 2 =? 0)%N
                    then RIsingle (a0 + a1 + 3)%N true (b1 - 1)%N [] None
                    else RIsingle (a0 + a1 + 3)%N false (b1 - 1 + 1)%N [] None)
             with (if ((a0 - a1 - 1) mod 2 =? 0)%N
                   then RIsingle (a0 + a1 + 3)%N true (b1 - 1)%N [] None
                   else RIsingle (a0 + a1 + 3)%N false b1 [] None) in hp0
             by (destruct (((a0 - a1 - 1) mod 2 =? 0)%N); [reflexivity | repeat f_equal; lia]).
           destruct (proj1 (step1Pref_sound rest2) _ _ isP2 E' revOut L0
                       (encItems tail *> [S0; S1; S0; S1] *> b0) hp0 h) as [Lt' [hp' hs2]].
           exists Lt'; split; [exact hp' |].
           unfold HubCfg; cbn [List.app encItems]; unfold encItem, encSingle; cbn [encSegTail].
           rewrite encItems_append, ?app_nil_r, ?Str_app_assoc.
           replace (N.to_nat b1) with (N.to_nat (b1 - 1)%N + 1) by lia.
           exact (stepStar_trans hs0 hs2).
    + (* h0 = false *)
      destruct ((b0_v =? 2)%N) eqn:Hb02.
      * apply N.eqb_eq in Hb02; subst b0_v.
        destruct (((3 <=? a0)%N && (a0 mod 2 =? 1)%N)%bool) eqn:Hc; [|discriminate].
        apply Bool.andb_true_iff in Hc; destruct Hc as [Ha03 Ha0odd].
        apply N.leb_le in Ha03.
        pose proof (N_mod2_eq1_decomp a0 Ha0odd) as Ha0_eq.
        set (m := N.to_nat (a0 / 2)%N).
        destruct (pipeL_start_c0_h0 m 0 (Nat.le_0_l m)
                    (encItems rest *> encItems tail *> [S0; S1; S0; S1] *> b0)) as [L0 [hp0 hs0]].
        assert (Hp0' : PipeL (N.to_nat (a0 / 2)%N)
                         (encItems (List.rev [RIsingle (a0 + 3)%N true 0%N [] None])) L0).
        { eapply pipeL_eqER; [exact hp0 | unfold m; lia |].
          cbn [List.rev app encItems]; unfold encItem, encSingle; cbn [encSegTail N.to_nat].
          rewrite list_pow_zero, ?app_nil_r.
          replace (2 * m + 4) with (N.to_nat (a0 + 3)%N) by (unfold m; lia).
          reflexivity. }
        destruct (proj1 (step1Pref_sound rest) _ _ isP2 E' revOut L0
                    (encItems tail *> [S0; S1; S0; S1] *> b0) Hp0' h) as [Lt' [hp' hs2]].
        exists Lt'; split; [exact hp' |].
        unfold HubCfg; cbn [List.app encItems]; unfold encItem, encSingle; cbn [encSegTail].
        rewrite encItems_append, ?app_nil_r, ?Str_app_assoc.
        replace (N.to_nat a0) with (2 * m + 1) by (unfold m; lia).
        replace (N.to_nat 2%N) with (0 + 2) by reflexivity.
        exact (stepStar_trans hs0 hs2).
      * destruct rest as [|[a1 h1 b1 [|? ?] [?|] | | |] rest2]; try discriminate.
        destruct ((isMergeC0 false b0_v a1 && (a1 + 1 <=? a0)%N && (1 <=? b1)%N)%bool) eqn:Hc; [|discriminate].
        apply Bool.andb_true_iff in Hc; destruct Hc as [Hc1 Hb1]; apply Bool.andb_true_iff in Hc1; destruct Hc1 as [Hm Ha].
        apply N.leb_le in Ha; apply N.leb_le in Hb1.
        destruct h1; simpl negb in h.
        -- destruct (pipeL_start_c0_b0z_h1 a0 false b0_v a1 (b1 - 1)%N Hm Ha
                       (encItems rest2 *> encItems tail *> [S0; S1; S0; S1] *> b0)) as [L0 [hp0 hs0]].
           replace (if ((a0 - a1 - 1) mod 2 =? 0)%N
                    then RIsingle (a0 + a1 + 4)%N true (b1 - 1)%N [] None
                    else RIsingle (a0 + a1 + 4)%N false (b1 - 1 + 1)%N [] None)
             with (if ((a0 - a1 - 1) mod 2 =? 0)%N
                   then RIsingle (a0 + a1 + 4)%N true (b1 - 1)%N [] None
                   else RIsingle (a0 + a1 + 4)%N false b1 [] None) in hp0
             by (destruct (((a0 - a1 - 1) mod 2 =? 0)%N); [reflexivity | repeat f_equal; lia]).
           destruct (proj2 (step1Pref_sound rest2) _ _ isP2 E' revOut L0
                       (encItems tail *> [S0; S1; S0; S1] *> b0) hp0 h) as [Lt' [hp' hs2]].
           exists Lt'; split; [exact hp' |].
           unfold HubCfg; cbn [List.app encItems]; unfold encItem, encSingle; cbn [encSegTail].
           rewrite encItems_append, ?app_nil_r, ?Str_app_assoc.
           replace (N.to_nat b1) with (N.to_nat (b1 - 1)%N + 1) by lia.
           exact (stepStar_trans hs0 hs2).
        -- destruct ((b1 - 1 <=? (a0 - a1 - 1) / 2)%N) eqn:Hb; [|discriminate].
           apply N.leb_le in Hb.
           destruct (pipeL_start_c0_b0z_h0 a0 false b0_v a1 (b1 - 1)%N Hm Ha Hb
                       (encItems rest2 *> encItems tail *> [S0; S1; S0; S1] *> b0)) as [L0 [hp0 hs0]].
           replace (if ((a0 - a1 - 1) mod 2 =? 0)%N
                    then RIsingle (a0 + a1 + 3)%N true (b1 - 1)%N [] None
                    else RIsingle (a0 + a1 + 3)%N false (b1 - 1 + 1)%N [] None)
             with (if ((a0 - a1 - 1) mod 2 =? 0)%N
                   then RIsingle (a0 + a1 + 3)%N true (b1 - 1)%N [] None
                   else RIsingle (a0 + a1 + 3)%N false b1 [] None) in hp0
             by (destruct (((a0 - a1 - 1) mod 2 =? 0)%N); [reflexivity | repeat f_equal; lia]).
           destruct (proj1 (step1Pref_sound rest2) _ _ isP2 E' revOut L0
                       (encItems tail *> [S0; S1; S0; S1] *> b0) hp0 h) as [Lt' [hp' hs2]].
           exists Lt'; split; [exact hp' |].
           unfold HubCfg; cbn [List.app encItems]; unfold encItem, encSingle; cbn [encSegTail].
           rewrite encItems_append, ?app_nil_r, ?Str_app_assoc.
           replace (N.to_nat b1) with (N.to_nat (b1 - 1)%N + 1) by lia.
           exact (stepStar_trans hs0 hs2).
Qed.

(* ========================================================================= *)
(* pop01Runs, isFooterOnly, HubCfgShort, Short-Footer Bridges                *)
(* ========================================================================= *)

Lemma pop01Runs_sound {rs out : list (Tok * N)} (h : pop01Runs rs = Some out) :
    encRuns rs = [S0; S1] ++ encRuns out.
Proof.
  unfold pop01Runs in h.
  destruct rs as [|[[| | | | | |] n0] rest]; try discriminate.
  - (* T_0 *)
    destruct rest as [|[[| | | | | |] m] rest2]; try discriminate.
    destruct (((n0 =? 1)%N && (1 <=? m)%N)%bool) eqn:Hc; [|discriminate].
    split_andb; subst n0. inversion h; subst out.
    cbn [encRuns encTok]; rewrite N_to_nat_1, list_pow_one, encRuns_decRun.
    replace (N.to_nat m) with (S (N.to_nat (m - 1)%N)) by lia.
    cbn [lpow encTok List.app]; reflexivity.
  - (* T_3 *)
    destruct ((1 <=? n0)%N) eqn:Hc; [|discriminate]. split_andb.
    inversion h; subst out.
    cbn [encRuns encTok]; rewrite encRuns_pushRun, encRuns_decRun, N_to_nat_1, list_pow_one.
    replace (N.to_nat n0) with (S (N.to_nat (n0 - 1)%N)) by lia.
    cbn [lpow encTok List.app]; reflexivity.
  - (* T_4 *)
    destruct ((1 <=? n0)%N) eqn:Hc; [|discriminate]. split_andb.
    inversion h; subst out.
    cbn [encRuns encTok]; rewrite encRuns_pushRun, encRuns_decRun, N_to_nat_1, list_pow_one.
    replace (N.to_nat n0) with (S (N.to_nat (n0 - 1)%N)) by lia.
    cbn [lpow encTok List.app]; reflexivity.
  - (* T_5 *)
    destruct ((1 <=? n0)%N) eqn:Hc; [|discriminate]. split_andb.
    inversion h; subst out.
    cbn [encRuns encTok]; rewrite encRuns_pushRun, encRuns_decRun, N_to_nat_1, list_pow_one.
    replace (N.to_nat n0) with (S (N.to_nat (n0 - 1)%N)) by lia.
    cbn [lpow encTok List.app]; reflexivity.
Qed.

Lemma isFooterOnly_sound {rs : list (Tok * N)} (h : isFooterOnly rs = true) :
    encRuns rs = [S0; S1; S0; S1].
Proof.
  unfold isFooterOnly in h.
  destruct (stripFooterRuns rs) as [[|? ?]|] eqn:Hsf; try discriminate.
  rewrite (stripFooterRuns_sound Hsf). reflexivity.
Qed.

Definition HubCfgShort (items : list RleItem) : Q * tape :=
  b0 {{E}}> (T2 *> T0 *> T1 *> encItems items *> [S0; S1] *> b0).

Lemma stepPipeRawToShort_sound {prefixLen fuel : nat} {xs ys : list RleItem}
    (h : stepPipeRawToShort prefixLen fuel xs = Some ys) :
    (HubCfg xs) -[ tm ]->* HubCfgShort ys.
Proof.
  unfold stepPipeRawToShort in h.
  destruct (splitAtList prefixLen xs) as [[pref win]|] eqn:Hsp; [|discriminate].
  destruct (itemsToRuns win) as [winRuns|] eqn:Hwr; [|discriminate].
  destruct (step1HubPrefix pref) as [[[isP2 Ep] revPref]|] eqn:Hpre; [|discriminate].
  pose proof (splitAtList_sound _ _ _ _ Hsp) as Hxs.
  pose proof (itemsToRuns_sound _ _ Hwr) as Hwin.
  destruct (step1HubPrefix_gen_sound (encItems win *> [S0; S1; S0; S1] *> b0) Hpre)
    as [Lt' [hp' hreach0]].
  assert (Hhub : HubCfg xs = b0 {{E}}> (T2 *> T0 *> T1 *> encItems pref *> encItems win *> [S0; S1; S0; S1] *> b0)).
  { unfold HubCfg. rewrite Hxs, encItems_append, Str_app_assoc. reflexivity. }
  rewrite <- Hhub in hreach0.
  set (rc0 := if isP2 then mkRawCfg A [(T_1, 1%N); (T_2, 1%N)] (LBpipe Ep revPref) (winRuns ++ footerRuns) RBblank
              else mkRawCfg F [(T_1, 2%N)] (LBpipe Ep revPref) (winRuns ++ footerRuns) RBblank) in *.
  assert (Hd0 : RawDenote b0 rc0
    (if isP2 then (([S1] *> T2 *> Lt') {{A}}> (encItems win *> [S0; S1; S0; S1] *> b0))
     else (([S1; S1] *> Lt') {{F}}> (encItems win *> [S0; S1; S0; S1] *> b0)))).
  { exists Lt'. unfold rc0; destruct isP2.
    - split; [exact hp' |].
      cbn [rc_q rc_L rc_lBase rc_R rc_rBase RightBaseStream encRuns encTok].
      rewrite N_to_nat_1, !list_pow_one, encRuns_append, encRuns_footerRuns, Hwin, ?app_nil_r, ?Str_app_assoc.
      reflexivity.
    - split; [exact hp' |].
      cbn [rc_q rc_L rc_lBase rc_R rc_rBase RightBaseStream encRuns encTok].
      replace (N.to_nat 2%N) with 2 by reflexivity.
      cbn [lpow List.app].
      rewrite encRuns_append, encRuns_footerRuns, Hwin, ?Str_app_assoc.
      reflexivity. }
  destruct (runRawUntil isRawDoneBig fuel rc0) as [rc1|] eqn:Hrun; [|discriminate].
  destruct (runRawUntil_sound _ _ _ _ _ _ Hd0 Hrun) as [_ [cfg1 [Hd1 Hs1]]].
  pose proof (stepStar_trans hreach0 Hs1) as Hreach1.
  destruct Hd1 as [L1 [Hlb1 Hcfg1]]; subst cfg1.
  destruct rc1 as [q1 Lr1 lb1 Rr1 rb1]; cbn [rc_q rc_L rc_lBase rc_R rc_rBase LeftBaseDenote RightBaseStream] in h, Hlb1, Hreach1.
  destruct q1; try discriminate.
  destruct Lr1 as [|[[| | | | | |] n1] [|? ?]]; try discriminate.
  destruct lb1 as [|Ep' revOut]; [discriminate |].
  destruct rb1; [|discriminate].
  destruct (((n1 =? 2)%N && (Ep' =? 0)%N)%bool) eqn:Hc; [|discriminate].
  split_andb; subst n1 Ep'.
  destruct (pop01Runs Rr1) as [R_out|] eqn:Hpop; [|discriminate].
  apply option_map_Some in h; destruct h as [body [Hsf Hys]]; subst ys.
  eapply stepStar_trans; [exact Hreach1 |].
  cbn [N.to_nat] in Hlb1.
  pose proof (PipeL_unwind Hlb1 (encRuns body *> [S0; S1] *> b0)) as Hunw.
  unfold HubCfgShort.
  rewrite encItems_append, encItems_runsToItems, ?Str_app_assoc.
  rewrite (pop01Runs_sound Hpop), (stripShortFooterRuns_sound Hsf), ?Str_app_assoc.
  cbn [encRuns encTok]; replace (N.to_nat 2%N) with 2 by reflexivity; cbn [lpow List.app].
  rewrite ?Str_app_assoc. exact Hunw.
Qed.

Lemma stepPipeRawFromShort_sound {prefixLen fuel : nat} {xs ys : list RleItem}
    (h : stepPipeRawFromShort prefixLen fuel xs = Some ys) :
    (HubCfgShort xs) -[ tm ]->* HubCfg ys.
Proof.
  unfold stepPipeRawFromShort in h.
  destruct (splitAtList prefixLen xs) as [[pref win]|] eqn:Hsp; [|discriminate].
  destruct (itemsToRuns win) as [winRuns|] eqn:Hwr; [|discriminate].
  destruct (step1HubPrefix pref) as [[[isP2 Ep] revPref]|] eqn:Hpre; [|discriminate].
  pose proof (splitAtList_sound _ _ _ _ Hsp) as Hxs.
  pose proof (itemsToRuns_sound _ _ Hwr) as Hwin.
  destruct (step1HubPrefix_gen_sound (encItems win *> [S0; S1] *> b0) Hpre)
    as [Lt' [hp' hreach0]].
  assert (Hhub : HubCfgShort xs = b0 {{E}}> (T2 *> T0 *> T1 *> encItems pref *> encItems win *> [S0; S1] *> b0)).
  { unfold HubCfgShort. rewrite Hxs, encItems_append, Str_app_assoc. reflexivity. }
  rewrite <- Hhub in hreach0.
  set (rc0 := if isP2 then mkRawCfg A [(T_1, 1%N); (T_2, 1%N)] (LBpipe Ep revPref) (winRuns ++ shortFooterRuns) RBblank
              else mkRawCfg F [(T_1, 2%N)] (LBpipe Ep revPref) (winRuns ++ shortFooterRuns) RBblank) in *.
  assert (Hd0 : RawDenote b0 rc0
    (if isP2 then (([S1] *> T2 *> Lt') {{A}}> (encItems win *> [S0; S1] *> b0))
     else (([S1; S1] *> Lt') {{F}}> (encItems win *> [S0; S1] *> b0)))).
  { exists Lt'. unfold rc0; destruct isP2.
    - split; [exact hp' |].
      cbn [rc_q rc_L rc_lBase rc_R rc_rBase RightBaseStream encRuns encTok].
      rewrite N_to_nat_1, !list_pow_one, encRuns_append, encRuns_shortFooterRuns, Hwin, ?app_nil_r, ?Str_app_assoc.
      reflexivity.
    - split; [exact hp' |].
      cbn [rc_q rc_L rc_lBase rc_R rc_rBase RightBaseStream encRuns encTok].
      replace (N.to_nat 2%N) with 2 by reflexivity.
      cbn [lpow List.app].
      rewrite encRuns_append, encRuns_shortFooterRuns, Hwin, ?Str_app_assoc.
      reflexivity. }
  destruct (runRawUntil isRawDoneBig fuel rc0) as [rc1|] eqn:Hrun; [|discriminate].
  destruct (runRawUntil_sound _ _ _ _ _ _ Hd0 Hrun) as [_ [cfg1 [Hd1 Hs1]]].
  pose proof (stepStar_trans hreach0 Hs1) as Hreach1.
  destruct Hd1 as [L1 [Hlb1 Hcfg1]]; subst cfg1.
  destruct rc1 as [q1 Lr1 lb1 Rr1 rb1]; cbn [rc_q rc_L rc_lBase rc_R rc_rBase LeftBaseDenote RightBaseStream] in h, Hlb1, Hreach1.
  destruct q1; try discriminate.
  destruct Lr1 as [|[[| | | | | |] n1] [|? ?]]; try discriminate.
  destruct lb1 as [|Ep' revOut]; [discriminate |].
  destruct rb1; [|discriminate].
  destruct (((n1 =? 2)%N && (Ep' =? 0)%N)%bool) eqn:Hc; [|discriminate].
  split_andb; subst n1 Ep'.
  destruct (pop01Runs Rr1) as [R_out|] eqn:Hpop; [|discriminate].
  apply option_map_Some in h; destruct h as [body [Hsf Hys]]; subst ys.
  eapply stepStar_trans; [exact Hreach1 |].
  cbn [N.to_nat] in Hlb1.
  pose proof (PipeL_unwind Hlb1 (encRuns body *> [S0; S1; S0; S1] *> b0)) as Hunw.
  unfold HubCfg.
  rewrite encItems_append, encItems_runsToItems, ?Str_app_assoc.
  rewrite (pop01Runs_sound Hpop), (stripFooterRuns_sound Hsf), ?Str_app_assoc.
  cbn [encRuns encTok]; replace (N.to_nat 2%N) with 2 by reflexivity; cbn [lpow List.app].
  rewrite ?Str_app_assoc. exact Hunw.
Qed.

(* ========================================================================= *)
(* Right-to-Left Automatic Normalizer & Raw Repacker                         *)
(* ========================================================================= *)

Lemma encSegTail_consNormSeg (s : SegPiece) (ys : list SegPiece) :
    encSegTail (consNormSeg s ys) = encSegTail (s :: ys).
Proof.
  destruct s as [v1 | v1 v2 r1]; cbn [consNormSeg].
  - destruct ys as [|[v2 | a b c] rest]; [reflexivity | | reflexivity].
    destruct rest as [|[u1 | u1 u2 r] rest2]; [reflexivity | |].
    + destruct rest2 as [|[u2 | ? ? ?] rest3]; [reflexivity | | reflexivity].
      destruct (((v1 =? u1)%N && (v2 =? u2)%N)%bool) eqn:Heq; [|reflexivity].
      split_andb; subst u1 u2.
      cbn [encSegTail]. replace (N.to_nat 2%N) with 2 by reflexivity.
      cbn [lpow]. rewrite ?app_nil_r, ?append_assoc. reflexivity.
    + destruct (((v1 =? u1)%N && (v2 =? u2)%N)%bool) eqn:Heq; [|reflexivity].
      split_andb; subst u1 u2.
      cbn [encSegTail]. replace (N.to_nat (r + 1)%N) with (S (N.to_nat r)) by lia.
      cbn [lpow]. rewrite ?append_assoc. reflexivity.
  - destruct ((r1 =? 0)%N) eqn:Hr0.
    + apply N.eqb_eq in Hr0; subst r1. cbn [encSegTail N.to_nat]; rewrite list_pow_zero; reflexivity.
    + destruct ys as [|[? | u1 u2 r2] rest]; [reflexivity | reflexivity |].
      destruct (((v1 =? u1)%N && (v2 =? u2)%N)%bool) eqn:Heq; [|reflexivity].
      split_andb; subst u1 u2.
      cbn [encSegTail]. replace (N.to_nat (r1 + r2)%N) with (N.to_nat r1 + N.to_nat r2) by lia.
      rewrite list_pow_add, ?append_assoc. reflexivity.
Qed.

Lemma encSegTail_normSegs (ss : list SegPiece) :
    encSegTail (normSegs ss) = encSegTail ss.
Proof.
  induction ss as [|s ss IH]; [reflexivity |].
  cbn [normSegs]. rewrite encSegTail_consNormSeg.
  destruct s; cbn [encSegTail]; rewrite IH; reflexivity.
Qed.

Lemma encSegTail_append (ss1 ss2 : list SegPiece) :
    encSegTail (ss1 ++ ss2) = encSegTail ss1 ++ encSegTail ss2.
Proof.
  induction ss1 as [|s ss IH]; [reflexivity |].
  destruct s; cbn [List.app encSegTail]; rewrite IH, ?append_assoc; reflexivity.
Qed.

Lemma encItems_consPackRaw (x : RleItem) (ys : list RleItem) :
    encItems (consPackRaw x ys) = encItem x ++ encItems ys.
Proof.
  destruct x as [a h s0 segTail aR | a b r | a1 h1 b1 a2 h2 b2 r | t n]; cbn [consPackRaw].
  - (* RIsingle *)
    assert (Hdef : encItems (RIsingle a h s0 (normSegs segTail) aR :: ys) =
                   encItem (RIsingle a h s0 segTail aR) ++ encItems ys).
    { cbn [encItems]; unfold encItem, encSingle; rewrite encSegTail_normSegs; reflexivity. }
    destruct ys as [|[? ? ? ? ? | ? ? ? | ? ? ? ? ? ? ? | [| | | | | |] m] rest]; try exact Hdef.
    + (* RIraw T_3 m :: rest *)
      destruct ((m =? 1)%N) eqn:Hm1; [| exact Hdef].
      apply N.eqb_eq in Hm1; subst m.
      assert (Hdef3 : encItems (RIsingle a h s0 (normSegs (segTail ++ [SPsingle 0%N])) aR :: rest) =
                      encItem (RIsingle a h s0 segTail aR) ++ encItems (RIraw T_3 1%N :: rest)).
      { cbn [encItems]; unfold encItem, encSingle; rewrite encSegTail_normSegs, encSegTail_append.
        cbn [encSegTail N.to_nat encTok]; rewrite list_pow_zero, list_pow_one, ?app_nil_r, ?append_assoc.
        reflexivity. }
      destruct rest as [|[a2 [|] s1 segRest [?|] | | |] rest2]; try exact Hdef3.
      destruct ((a2 =? 0)%N) eqn:Ha20; [| exact Hdef3].
      apply N.eqb_eq in Ha20; subst a2.
      cbn [encItems]; unfold encItem, encSingle; rewrite encSegTail_normSegs, encSegTail_append.
      cbn [encSegTail N.to_nat encTok]; rewrite list_pow_zero, list_pow_one, ?app_nil_r, ?append_assoc.
      reflexivity.
    + (* RIraw T_4 m :: rest *)
      destruct (isEmpty segTail) eqn:Hemp; [| exact Hdef].
      apply isEmpty_true_iff in Hemp; subst segTail.
      cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail encTok].
      replace (N.to_nat (s0 + m)%N) with (N.to_nat s0 + N.to_nat m) by lia.
      rewrite list_pow_add, ?app_nil_r, ?append_assoc. reflexivity.
  - (* RItranspRun *)
    destruct ((r =? 0)%N) eqn:Hr0; [|reflexivity].
    apply N.eqb_eq in Hr0; subst r. cbn [encItem N.to_nat]; rewrite list_pow_zero; reflexivity.
  - (* RIpairRun *)
    destruct ((r =? 0)%N) eqn:Hr0; [|reflexivity].
    apply N.eqb_eq in Hr0; subst r. cbn [encItem N.to_nat]; rewrite list_pow_zero; reflexivity.
  - (* RIraw t n *)
    destruct ((n =? 0)%N) eqn:Hn0.
    + apply N.eqb_eq in Hn0; subst n. cbn [encItem N.to_nat]; rewrite list_pow_zero; reflexivity.
    + assert (HmergeRaw :
        encItems (match ys with
                  | RIraw tk2 n2 :: rest => if tok_eqb t tk2 then RIraw t (n + n2)%N :: rest else RIraw t n :: ys
                  | _ => RIraw t n :: ys
                  end) = encItem (RIraw t n) ++ encItems ys).
      { destruct ys as [|[? ? ? ? ? | ? ? ? | ? ? ? ? ? ? ? | tk2 n2] rest]; try reflexivity.
        destruct (tok_eqb t tk2) eqn:Htk; [|reflexivity].
        apply tok_eqb_eq in Htk; subst tk2.
        cbn [encItems]; unfold encItem.
        replace (N.to_nat (n + n2)%N) with (N.to_nat n + N.to_nat n2) by lia.
        rewrite list_pow_add, ?append_assoc; reflexivity. }
      destruct t.
      * (* T_0 *)
        destruct ((n =? 1)%N) eqn:Hn1; [|reflexivity].
        apply N.eqb_eq in Hn1; subst n.
        destruct ys as [|[aR h s0 segTail [?|] | | | [| | | | | |] n1] restY]; try reflexivity.
        -- (* RIsingle aR h s0 segTail None :: restY *)
           destruct ((1 <=? aR)%N) eqn:HaR1; [|reflexivity].
           cbn [encItems]; unfold encItem, encSingle; cbn [N.to_nat encTok].
           rewrite list_pow_zero, list_pow_one, ?append_assoc; reflexivity.
        -- (* RIraw T_1 n1 :: restY *)
           destruct ((n1 =? 1)%N) eqn:Hn11; [|reflexivity].
           apply N.eqb_eq in Hn11; subst n1.
           destruct restY as [|[a h s0 segTail aR | | | [| | | | | |] m] rest]; try reflexivity.
           ++ (* RIsingle a h s0 segTail aR :: rest *)
              destruct (((a =? 1)%N && negb h && match aR with None => true | Some _ => false end)%bool) eqn:Hc1.
              ** apply Bool.andb_true_iff in Hc1; destruct Hc1 as [Hc1a HaRnone].
                 apply Bool.andb_true_iff in Hc1a; destruct Hc1a as [Ha1 Hnh].
                 apply N.eqb_eq in Ha1; subst a.
                 destruct h; [discriminate |].
                 destruct aR as [?|]; [discriminate |].
                 cbn [encItems]; unfold encItem, encSingle; cbn [N.to_nat encTok].
                 rewrite list_pow_zero, !list_pow_one, ?append_assoc; reflexivity.
              ** destruct ((2 <=? a)%N) eqn:Ha2; [|reflexivity].
                 apply N.leb_le in Ha2.
                 cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail N.to_nat encTok].
                 rewrite !list_pow_zero, !list_pow_one, ?app_nil_r.
                 replace (N.to_nat a) with (S (N.to_nat (a - 1)%N)) by lia.
                 cbn [lpow List.app]. reflexivity.
           ++ (* RIraw T_2 m :: rest *)
              destruct ((m =? 1)%N) eqn:Hm1.
              ** apply N.eqb_eq in Hm1; subst m.
                 assert (HdefT2 : encItems (RIsingle 0%N true 0%N [] None :: rest) =
                                  encItem (RIraw T_0 1%N) ++ encItems (RIraw T_1 1%N :: RIraw T_2 1%N :: rest)).
                 { cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail N.to_nat encTok].
                   rewrite !list_pow_zero, !list_pow_one, ?app_nil_r; reflexivity. }
                 destruct rest as [|[? ? ? ? ? | ? ? ? | ? ? ? ? ? ? ? | [| | | | | |] n3] rest1]; try exact HdefT2.
                 destruct rest1 as [|[a2 [|] s1 segRest [?|] | | |] rest2]; try exact HdefT2.
                 destruct (((n3 =? 1)%N && (a2 =? 0)%N)%bool) eqn:Hc3; [| exact HdefT2].
                 split_andb; subst n3 a2.
                 cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail N.to_nat encTok].
                 rewrite !list_pow_zero, !list_pow_one, ?app_nil_r, ?append_assoc; reflexivity.
              ** destruct ((2 <=? m)%N) eqn:Hm2; [|reflexivity].
                 apply N.leb_le in Hm2.
                 cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail N.to_nat encTok].
                 rewrite !list_pow_zero, !list_pow_one, ?app_nil_r.
                 replace (N.to_nat m) with (S (N.to_nat (m - 1)%N)) by lia.
                 cbn [lpow List.app]; reflexivity.
      * exact HmergeRaw.
      * (* T_2 *)
        destruct ys as [|[a2 h s0 segTail aR | | | [| | | | | |] a2] rest]; try reflexivity.
        -- destruct ((a2 =? 0)%N) eqn:Ha20; [|reflexivity].
           apply N.eqb_eq in Ha20; subst a2.
           cbn [encItems]; unfold encItem, encSingle; cbn [N.to_nat encTok].
           rewrite list_pow_zero, ?append_assoc; reflexivity.
        -- cbn [encItems]; unfold encItem, encTok.
           replace (N.to_nat (n + a2)%N) with (N.to_nat n + N.to_nat a2) by lia.
           rewrite list_pow_add, ?append_assoc; reflexivity.
      * exact HmergeRaw.
      * (* T_4 *)
        assert (Hdef4 : encItems (RIsingle 0%N false n [] None :: ys) =
                        encItem (RIraw T_4 n) ++ encItems ys).
        { cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail N.to_nat encTok].
          rewrite list_pow_zero, ?app_nil_r; reflexivity. }
        destruct ys as [|[a2 [|] s2 segTail [?|] | | | [| | | | | |] s2] rest]; try exact Hdef4.
        -- destruct ((a2 =? 0)%N) eqn:Ha20; [| exact Hdef4].
           apply N.eqb_eq in Ha20; subst a2.
           cbn [encItems]; unfold encItem, encSingle; cbn [N.to_nat encTok].
           replace (N.to_nat (n + s2)%N) with (N.to_nat n + N.to_nat s2) by lia.
           rewrite list_pow_zero, list_pow_add, ?append_assoc; reflexivity.
        -- cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail N.to_nat encTok].
           replace (N.to_nat (n + s2)%N) with (N.to_nat n + N.to_nat s2) by lia.
           rewrite list_pow_zero, list_pow_add, ?app_nil_r, ?append_assoc; reflexivity.
      * (* T_5 *)
        destruct ((n =? 1)%N) eqn:Hn1; [|reflexivity].
        apply N.eqb_eq in Hn1; subst n.
        assert (Hdef5 : encItems (RIsingle 0%N true 0%N [] None :: ys) =
                        encItem (RIraw T_5 1%N) ++ encItems ys).
        { cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail N.to_nat encTok].
          rewrite !list_pow_zero, list_pow_one, ?app_nil_r; reflexivity. }
        destruct ys as [|[a2 [|] s0 segTail [?|] | | |] rest]; try exact Hdef5.
        destruct ((a2 =? 0)%N) eqn:Ha20; [| exact Hdef5].
        apply N.eqb_eq in Ha20; subst a2.
        cbn [encItems]; unfold encItem, encSingle; cbn [N.to_nat encTok].
        rewrite list_pow_zero, list_pow_one, ?append_assoc; reflexivity.
      * exact HmergeRaw.
Qed.

Lemma encItems_packRawItems (xs : list RleItem) :
    encItems (packRawItems xs) = encItems xs.
Proof.
  induction xs as [|x xs IH]; [reflexivity |].
  cbn [packRawItems encItems]. rewrite encItems_consPackRaw, IH. reflexivity.
Qed.

Lemma encItems_consNormItem (x : RleItem) (ys : list RleItem) :
    encItems (consNormItem x ys) = encItem x ++ encItems ys.
Proof.
  destruct x as [a h s0 segTail aR | a b r1 | a1 h1 b1 a2 h2 b2 r1 | t n]; cbn [consNormItem].
  - (* RIsingle *)
    pose proof (encSegTail_normSegs segTail) as Hseg.
    destruct (normSegs segTail) as [|sh st].
    + destruct aR as [aR'|].
      * cbn [encItems]; unfold encItem, encSingle; rewrite <- Hseg; reflexivity.
      * set (tryPairMerge :=
               match ys with
               | RIsingle a2 h2 b2 [] None :: RIpairRun u1 j1 c1 u2 j2 c2 r :: rest =>
                   if (a =? u1)%N && Bool.eqb h j1 && (s0 =? c1)%N &&
                      (a2 =? u2)%N && Bool.eqb h2 j2 && (b2 =? c2)%N then
                     RIpairRun a h s0 a2 h2 b2 (r + 1)%N :: rest
                   else RIsingle a h s0 [] None :: ys
               | RIsingle a2 h2 b2 [] None :: RIsingle u1 j1 c1 [] None :: RIsingle u2 j2 c2 [] None :: rest =>
                   if (a =? u1)%N && Bool.eqb h j1 && (s0 =? c1)%N &&
                      (a2 =? u2)%N && Bool.eqb h2 j2 && (b2 =? c2)%N &&
                      (negb (a =? a2)%N || negb (Bool.eqb h h2) || negb (s0 =? b2)%N) then
                     RIpairRun a h s0 a2 h2 b2 2%N :: rest
                   else RIsingle a h s0 [] None :: ys
               | _ => RIsingle a h s0 [] None :: ys
               end).
        assert (Hbase : encItems (RIsingle a h s0 [] None :: ys) =
                        encItem (RIsingle a h s0 segTail None) ++ encItems ys).
        { cbn [encItems]; unfold encItem, encSingle; rewrite <- Hseg; reflexivity. }
        assert (Htry : encItems tryPairMerge =
                       encItem (RIsingle a h s0 segTail None) ++ encItems ys).
        { unfold tryPairMerge.
          destruct ys as [|[a2 h2 b2 [|? ?] [?|] | | |] rest1]; try exact Hbase.
          destruct rest1 as [|[u1 j1 c1 [|? ?] [?|] | | u1 j1 c1 u2 j2 c2 r |] rest2]; try exact Hbase.
          - destruct rest2 as [|[u2 j2 c2 [|? ?] [?|] | | |] rest3]; try exact Hbase.
            destruct (((a =? u1)%N && Bool.eqb h j1 && (s0 =? c1)%N &&
                       (a2 =? u2)%N && Bool.eqb h2 j2 && (b2 =? c2)%N &&
                       (negb (a =? a2)%N || negb (Bool.eqb h h2) || negb (s0 =? b2)%N))%bool) eqn:Heq;
              [| exact Hbase].
            apply Bool.andb_true_iff in Heq; destruct Heq as [Heq1 Heq_or]; clear Heq_or.
            split_andb; subst u1 j1 c1 u2 j2 c2.
            rewrite <- Hbase; cbn [encItems]; unfold encItem.
            replace (N.to_nat 2%N) with 2 by reflexivity; cbn [lpow].
            rewrite ?app_nil_r, ?append_assoc; reflexivity.
          - destruct (((a =? u1)%N && Bool.eqb h j1 && (s0 =? c1)%N &&
                       (a2 =? u2)%N && Bool.eqb h2 j2 && (b2 =? c2)%N)%bool) eqn:Heq;
              [| exact Hbase].
        split_andb; subst u1 j1 c1 u2 j2 c2.
            rewrite <- Hbase; cbn [encItems]; unfold encItem.
            replace (N.to_nat (r + 1)%N) with (S (N.to_nat r)) by lia; cbn [lpow].
            rewrite ?append_assoc; reflexivity. }
        destruct h; simpl negb; [exact Htry |].
        destruct ys as [|[a2 [|] b2 [|? ?] [?|] | a2 b2 r | |] rest]; try exact Htry.
        -- destruct (((a =? a2)%N && (s0 =? b2)%N && (2 <=? a)%N && (a mod 2 =? 0)%N && (1 <=? s0)%N)%bool) eqn:Heq;
             [| exact Htry].
           split_andb; subst a2 b2.
           rewrite <- Hbase; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
           replace (N.to_nat 2%N) with 2 by reflexivity; cbn [lpow].
           rewrite ?app_nil_r, ?append_assoc; reflexivity.
        -- destruct (((a =? a2)%N && (s0 =? b2)%N)%bool) eqn:Heq; [| exact Hbase].
           split_andb; subst a2 b2.
           rewrite <- Hbase; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
           replace (N.to_nat (r + 1)%N) with (S (N.to_nat r)) by lia; cbn [lpow].
           rewrite ?app_nil_r, ?append_assoc; reflexivity.
    + cbn [encItems]; unfold encItem, encSingle; rewrite <- Hseg; reflexivity.
  - (* RItranspRun *)
    destruct ((r1 =? 0)%N) eqn:Hr0.
    + apply N.eqb_eq in Hr0; subst r1; cbn [encItem N.to_nat]; rewrite list_pow_zero; reflexivity.
    + destruct ys as [|[a2 [|] b2 [|? ?] [?|] | a2 b2 r2 | |] rest]; try reflexivity.
      * destruct (((a =? a2)%N && (b =? b2)%N)%bool) eqn:Heq; [|reflexivity].
        split_andb; subst a2 b2.
        cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
        replace (N.to_nat (r1 + 1)%N) with (N.to_nat r1 + 1) by lia.
        rewrite list_pow_add, list_pow_one, ?app_nil_r, ?append_assoc; reflexivity.
      * destruct (((a =? a2)%N && (b =? b2)%N)%bool) eqn:Heq; [|reflexivity].
        split_andb; subst a2 b2.
        cbn [encItems]; unfold encItem.
        replace (N.to_nat (r1 + r2)%N) with (N.to_nat r1 + N.to_nat r2) by lia.
        rewrite list_pow_add, ?append_assoc; reflexivity.
  - (* RIpairRun *)
    destruct ((r1 =? 0)%N) eqn:Hr0.
    + apply N.eqb_eq in Hr0; subst r1; cbn [encItem N.to_nat]; rewrite list_pow_zero; reflexivity.
    + destruct ys as [|[u1 j1 c1 [|? ?] [?|] | | u1 j1 c1 u2 j2 c2 r2 |] rest]; try reflexivity.
      * destruct rest as [|[u2 j2 c2 [|? ?] [?|] | | |] rest2]; try reflexivity.
        destruct (((a1 =? u1)%N && Bool.eqb h1 j1 && (b1 =? c1)%N &&
                   (a2 =? u2)%N && Bool.eqb h2 j2 && (b2 =? c2)%N)%bool) eqn:Heq; [|reflexivity].
        split_andb; subst u1 j1 c1 u2 j2 c2.
        cbn [encItems]; unfold encItem.
        replace (N.to_nat (r1 + 1)%N) with (N.to_nat r1 + 1) by lia.
        rewrite list_pow_add, list_pow_one, ?append_assoc; reflexivity.
      * destruct (((a1 =? u1)%N && Bool.eqb h1 j1 && (b1 =? c1)%N &&
                   (a2 =? u2)%N && Bool.eqb h2 j2 && (b2 =? c2)%N)%bool) eqn:Heq; [|reflexivity].
        split_andb; subst u1 j1 c1 u2 j2 c2.
        cbn [encItems]; unfold encItem.
        replace (N.to_nat (r1 + r2)%N) with (N.to_nat r1 + N.to_nat r2) by lia.
        rewrite list_pow_add, ?append_assoc; reflexivity.
  - (* RIraw *)
    destruct ((n =? 0)%N) eqn:Hn0.
    + apply N.eqb_eq in Hn0; subst n; cbn [encItem N.to_nat]; rewrite list_pow_zero; reflexivity.
    + destruct ys as [|[? ? ? ? ? | ? ? ? | ? ? ? ? ? ? ? | tk2 n2] rest]; try reflexivity.
      destruct (tok_eqb t tk2) eqn:Htk; [|reflexivity].
      apply tok_eqb_eq in Htk; subst tk2.
      cbn [encItems]; unfold encItem.
      replace (N.to_nat (n + n2)%N) with (N.to_nat n + N.to_nat n2) by lia.
      rewrite list_pow_add, ?append_assoc; reflexivity.
Qed.

Lemma encItems_normItems (xs : list RleItem) :
    encItems (normItems xs) = encItems xs.
Proof.
  induction xs as [|x xs IH]; [reflexivity |].
  cbn [normItems encItems]. rewrite encItems_consNormItem, IH. reflexivity.
Qed.

Lemma encItems_autoPackNorm (xs : list RleItem) :
    encItems (autoPackNorm xs) = encItems xs.
Proof.
  unfold autoPackNorm. rewrite encItems_normItems, encItems_packRawItems. reflexivity.
Qed.

Lemma stepPipeRawBridge_sound {p1 f1 p2 f2 : nat} {xs ys : list RleItem}
    (h : stepPipeRawBridge p1 f1 p2 f2 xs = Some ys) :
    (HubCfg xs) -[ tm ]->* HubCfg ys.
Proof.
  unfold stepPipeRawBridge in h.
  destruct (stepPipeRawToShort p1 f1 xs) as [mid|] eqn:H1; [|discriminate].
  apply option_map_Some in h; destruct h as [out [H2 Hys]]; subst ys.
  pose proof (stepPipeRawToShort_sound H1) as Hs1.
  assert (Hmid : HubCfgShort (autoPackNorm mid) = HubCfgShort mid).
  { unfold HubCfgShort. rewrite encItems_autoPackNorm. reflexivity. }
  rewrite <- Hmid in Hs1.
  pose proof (stepPipeRawFromShort_sound H2) as Hs2.
  rewrite (HubCfg_of_encItems_eq (encItems_autoPackNorm out)).
  exact (stepStar_trans Hs1 Hs2).
Qed.

Lemma runH1_sound : forall (n : nat) (xs ys : list RleItem),
    runH1 n xs = Some ys -> (HubCfg xs) -[ tm ]->* HubCfg ys.
Proof.
  induction n as [|n' IH]; intros xs ys h; cbn [runH1] in h.
  - inversion h; subst ys; apply evstep_refl.
  - destruct (step1Hub xs) as [xs'|] eqn:Hs; [|discriminate].
    exact (stepStar_trans (step1Hub_sound Hs) (IH xs' ys h)).
Qed.

(* --- ScratchS6B1.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

Lemma pipeL_castE (E2 : nat) {E1 : nat} {R_out : list Sym} {Lt : Stream Sym}
    (hp : PipeL E1 R_out Lt) (heq : E1 = E2) : PipeL E2 R_out Lt.
Proof. subst E2; exact hp. Qed.

Lemma some_eq_b1 {A : Type} {x y : A} (h : Some x = Some y) : x = y.
Proof. exact (f_equal (fun o => match o with Some v => v | None => x end) h). Qed.

Lemma pair_eq_b1 {A B : Type} {a1 a2 : A} {b1 b2 : B} (h : (a1, b1) = (a2, b2)) : a1 = a2 /\ b1 = b2.
Proof. exact (conj (f_equal fst h) (f_equal snd h)). Qed.

Ltac inv_some_b1 H :=
  try apply some_eq_b1 in H;
  repeat match goal with
  | Hpq : (_, _) = (_, _) |- _ =>
      apply pair_eq_b1 in Hpq; cbn [fst snd] in Hpq; destruct Hpq
  end.


Ltac simp_list_pow_add :=
  repeat match goal with
  | |- context [?w ^^ (?a + ?b)] => rewrite (list_pow_add w a b)
  end.

(* ========================================================================= *)
(* Big 1-Hub Phase 1 / Phase 2 / DumpSegs Soundness                          *)
(* ========================================================================= *)

Lemma step1Phase2OrBig_sound {En : N} {revOut tail ys : list RleItem} {Lt : Stream Sym}
    (hp : PipeL (N.to_nat En) (encItems (List.rev revOut)) Lt)
    (h : step1Phase2OrBig En revOut tail = Some ys) :
    (([S1] *> T2 *> Lt) {{A}}> (encItems tail *> [S0; S1; S0; S1] *> b0))
      -[ tm ]->* HubCfg ys.
Proof.
  unfold step1Phase2OrBig in h.
  destruct (step1Phase2 En revOut tail) as [y|] eqn:Hp2.
  - inv_some_b1 h; subst y.
    exact (proj2 (step1Phases_sound tail) En revOut ys Lt hp Hp2).
  - apply option_map_Some in h; destruct h as [ys0 [Hd Hys]]; subst ys.
    destruct (applySinkDumpBig_sound Hd) as [f [Hf0 [HfE Hstep]]].
    pose proof (Hstep 0 (N.to_nat (En + 1)%N) ltac:(lia) ltac:(lia)
                  (encItems (List.rev revOut)) Lt
                  (pipeL_castE (N.to_nat (En + 1)%N - 1) hp ltac:(lia))) as Hs.
    cbn [Nat.add] in Hs. rewrite Hf0, HfE in Hs.
    unfold HubCfg. rewrite encItems_append. exact Hs.
Qed.

Lemma step1DumpSegsBigAux_sound
    {kP1Big : N -> list RleItem -> list RleItem -> option (list RleItem)}
    {En sa s0 : N} {sh : bool} {revOut rest ys : list RleItem}
    {segTail : list SegPiece} {Lt : Stream Sym}
    (ih1 : forall (E1 : N) (rev1 y1 : list RleItem) (L1 : Stream Sym),
      PipeL (N.to_nat E1) (encItems (List.rev rev1)) L1 ->
      kP1Big E1 rev1 rest = Some y1 ->
      (([S1; S1] *> L1) {{F}}> (encItems rest *> [S0; S1; S0; S1] *> b0)) -[ tm ]->* HubCfg y1)
    (h : step1DumpSegsBigAux kP1Big En revOut sa sh s0 segTail rest = Some ys)
    (hp : PipeL (N.to_nat En)
            (((encItems (List.rev revOut) ++ (T2 ^^ N.to_nat sa)) ++ (if sh then T5 else [])) ++
              (T4 ^^ N.to_nat s0)) Lt) :
    (([S1] *> T2 *> Lt) {{A}}> (encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0))
      -[ tm ]->* HubCfg ys.
Proof.
  unfold step1DumpSegsBigAux in h.
  destruct (unpackFrontSeg segTail) as [[s1 segRest]|] eqn:Hu; [|discriminate].
  rewrite (unpackFrontSeg_sound Hu), ?Str_app_assoc.
  destruct ((En + 1 <=? s1)%N) eqn:Hle.
  - apply N.leb_le in Hle; inv_some_b1 h; subst ys.
    pose proof (pipeL_dump_wall1 (E_rem := N.to_nat En) (N.to_nat s1) ltac:(lia) hp
                  (encSegTail segRest *> encItems rest *> [S0; S1; S0; S1] *> b0)) as Hdump.
    unfold HubCfg.
    rewrite encItems_append; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
    replace (N.to_nat (s0 + En + 1)%N) with (N.to_nat s0 + (N.to_nat En + 1)) by lia.
    replace (N.to_nat (s1 - (En + 1))%N) with (N.to_nat s1 - (N.to_nat En + 1)) by lia.
    rewrite (list_pow_add T4 (N.to_nat s0) (N.to_nat En + 1)), ?app_nil_r, ?append_assoc, ?Str_app_assoc.
    rewrite ?append_assoc in Hdump; rewrite ?Str_app_assoc in Hdump.
    exact Hdump.
  - destruct ((s1 + 1 <=? En)%N) eqn:Hge; [|discriminate].
    apply N.leb_le in Hge.
    destruct (pipeL_absorb_2seg (E_rem := N.to_nat En) (N.to_nat s1) ltac:(lia) hp
                (encSegTail segRest *> encItems rest *> [S0; S1; S0; S1] *> b0)) as [L2 [Hp2 Hs2]].
    assert (Hp2' : PipeL (N.to_nat (En - s1)%N)
                     (encItems (List.rev (RIsingle sa sh (s0 + s1 + 1)%N [] None :: revOut))) L2).
    { eapply pipeL_eqER; [exact Hp2 | lia |].
      rewrite encItems_rev_cons; unfold encItem, encSingle; cbn [encSegTail].
      replace (N.to_nat (s0 + s1 + 1)%N) with (N.to_nat s0 + (N.to_nat s1 + 1)) by lia.
      rewrite (list_pow_add T4 (N.to_nat s0) (N.to_nat s1 + 1)), ?app_nil_r, ?append_assoc. reflexivity. }
    destruct (isEmpty segRest) eqn:Hemp.
    + apply isEmpty_true_iff in Hemp; subst segRest.
      cbn [encSegTail] in Hs2; rewrite zLan in Hs2.
      exact (stepStar_trans Hs2 (ih1 (En - s1)%N _ ys L2 Hp2' h)).
    + exact (stepStar_trans Hs2 (step1Unzip_sound segRest (En - s1)%N _ rest ys L2 Hp2' h)).
Qed.

Lemma step1PhasesBigFuel_sound : forall (fuel : nat) (tail : list RleItem),
    (forall (En : N) (revOut ys : list RleItem) (Lt : Stream Sym),
      PipeL (N.to_nat En) (encItems (List.rev revOut)) Lt ->
      step1PhasesBigFuel fuel false En revOut tail = Some ys ->
      (([S1; S1] *> Lt) {{F}}> (encItems tail *> [S0; S1; S0; S1] *> b0))
        -[ tm ]->* HubCfg ys) /\
    (forall (En : N) (revOut ys : list RleItem) (Lt : Stream Sym),
      PipeL (N.to_nat En) (encItems (List.rev revOut)) Lt ->
      step1PhasesBigFuel fuel true En revOut tail = Some ys ->
      (([S1] *> T2 *> Lt) {{A}}> (encItems tail *> [S0; S1; S0; S1] *> b0))
        -[ tm ]->* HubCfg ys).
Proof.
  induction fuel as [|fuel' IH]; intros tail.
  - split; intros En revOut ys Lt _ h; cbn [step1PhasesBigFuel] in h; discriminate.
  - split.
    + (* isP2 = false: step1Phase1Big *)
      intros En revOut ys Lt hp h.
      cbn [step1PhasesBigFuel] in h; simpl (negb false) in h.
      destruct (step1Phase1 En revOut tail) as [y|] eqn:Hp0.
      * inv_some_b1 h; subst y.
        exact (proj1 (step1Phases_sound tail) En revOut ys Lt hp Hp0).
      * destruct tail as [|item rest].
        -- destruct ((1 <=? En)%N) eqn:Hge; [|discriminate].
           apply N.leb_le in Hge; inv_some_b1 h; subst ys.
           pose proof (pipeL_end_p1 (En := N.to_nat (En - 1)%N) (pipeL_castE (N.to_nat (En - 1)%N + 1) hp ltac:(lia))) as H1.
           cbn [encItems]; rewrite zLan.
           unfold HubCfg. rewrite encItems_append; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail N.to_nat].
           rewrite list_pow_zero, ?app_nil_r, ?append_assoc.
           rewrite ?append_assoc in H1. exact H1.
        -- destruct (step1PrefP1 En revOut [item]) as [[[isP2 E'] rev']|] eqn:Hp1.
           ++ destruct (proj1 (step1Pref_sound [item]) En revOut isP2 E' rev' Lt
                          (encItems rest *> [S0; S1; S0; S1] *> b0) hp Hp1) as [Lt' [Hp' Hstep]].
              cbn [encItems] in Hstep |- *; rewrite ?app_nil_r in Hstep; rewrite ?Str_app_assoc in Hstep; rewrite ?Str_app_assoc.
              destruct isP2.
              ** exact (stepStar_trans Hstep (proj2 (IH rest) E' rev' ys Lt' Hp' h)).
              ** exact (stepStar_trans Hstep (proj1 (IH rest) E' rev' ys Lt' Hp' h)).
           ++ destruct item as [a [|] s0 segTail [aR|] | a b rep | a1 [|] b1 a2 h2 b2 rep | [| | | | | |] aL];
                try discriminate.
              ** (* RIsingle a true s0 segTail (Some aR) *)
                 destruct (step1Phase1Asplit En revOut a true s0 segTail aR rest) as [res|] eqn:Ha; [|discriminate].
                 pose proof (step1Phase1Asplit_sound hp Ha) as Hres.
                 destruct res as [out | E_rem a' h' q segs | E' rev' segs | E' rev' segs2 | E' rev'];
                   cbn [AsplitSound] in Hres.
                 --- inv_some_b1 h; subst ys; exact Hres.
                 --- destruct Hres as [L1 [Hp1'' Hs1']].
                     exact (stepStar_trans Hs1' (step1DumpSegsBigAux_sound (proj1 (IH rest)) h Hp1'')).
                 --- destruct Hres as [L1 [Hp1'' Hs1']].
                     destruct (isEmpty segs) eqn:Hemp.
                     +++ apply isEmpty_true_iff in Hemp; subst segs.
                         cbn [encSegTail] in Hs1'; rewrite zLan in Hs1'.
                         exact (stepStar_trans Hs1' (proj1 (IH rest) E' rev' ys L1 Hp1'' h)).
                     +++ exact (stepStar_trans Hs1' (step1Unzip_sound segs E' rev' rest ys L1 Hp1'' h)).
                 --- destruct Hres as [item2 [rest2 [L1 [Hrest [Hp1'' Hs1']]]]]; subst rest.
                     destruct (isEmpty segs2) eqn:Hemp.
                     +++ apply isEmpty_true_iff in Hemp; subst segs2.
                         cbn [encSegTail] in Hs1'; rewrite zLan in Hs1'.
                         exact (stepStar_trans Hs1' (proj1 (IH rest2) E' rev' ys L1 Hp1'' h)).
                     +++ exact (stepStar_trans Hs1' (step1Unzip_sound segs2 E' rev' rest2 ys L1 Hp1'' h)).
                 --- destruct Hres as [item2 [rest2 [L1 [Hrest [Hp1'' Hs1']]]]]; subst rest.
                     exact (stepStar_trans Hs1' (proj2 (IH rest2) E' rev' ys L1 Hp1'' h)).
              ** (* RIsingle a true s0 segTail None *)
                 destruct ((negb (isEmpty segTail) && (a / 2 + 1 <=? En)%N)%bool) eqn:Hc1.
                 --- apply Bool.andb_true_iff in Hc1; destruct Hc1 as [_ HEn]; apply N.leb_le in HEn.
                     destruct ((a mod 2 =? 0)%N) eqn:Hev.
                     +++ pose proof (N_mod2_eq0_decomp a Hev) as Ha_eq.
                         destruct ((1 <=? s0)%N) eqn:Hs0; [|discriminate].
                         apply N.leb_le in Hs0.
                         destruct (pipeL_h1_enter_even (En := N.to_nat En) (N.to_nat (a / 2)%N) (N.to_nat (s0 - 1)%N)
                                     ltac:(lia) hp (encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0))
                           as [L1 [Hp1' Hs1]].
                         assert (Hp1'' : PipeL (N.to_nat (En - a / 2 - 1)%N)
                                           (((encItems (List.rev revOut) ++ (T2 ^^ N.to_nat (a + 1)%N)) ++
                                              (if false then T5 else [])) ++ (T4 ^^ N.to_nat s0)) L1).
                         { eapply pipeL_eqER; [exact Hp1' | lia |].
                           rewrite ?app_nil_r, ?append_assoc.
                           replace (2 * N.to_nat (a / 2)%N + 1) with (N.to_nat (a + 1)%N) by lia.
                           replace (N.to_nat (s0 - 1)%N + 1) with (N.to_nat s0) by lia.
                           reflexivity. }
                         cbn [encItems]; unfold encItem, encSingle; rewrite ?app_nil_r, ?Str_app_assoc, Ha_eq.
                         replace (N.to_nat s0) with (N.to_nat (s0 - 1)%N + 1) by lia.
                         exact (stepStar_trans Hs1 (step1DumpSegsBigAux_sound (proj1 (IH rest)) h Hp1'')).
                     +++ pose proof (N_mod2_ne0_decomp a Hev) as Ha_eq.
                         destruct ((2 <=? s0)%N) eqn:Hs0; [|discriminate].
                         apply N.leb_le in Hs0.
                         destruct (pipeL_h1_enter_odd (En := N.to_nat En) (N.to_nat (a / 2)%N) (N.to_nat (s0 - 1)%N)
                                     ltac:(lia) hp (encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0))
                           as [L1 [Hp1' Hs1]].
                         assert (Hp1'' : PipeL (N.to_nat (En - a / 2 - 1)%N)
                                           (((encItems (List.rev revOut) ++ (T2 ^^ N.to_nat (a + 1)%N)) ++
                                              (if true then T5 else [])) ++ (T4 ^^ N.to_nat (s0 - 1)%N)) L1).
                         { eapply pipeL_eqER; [exact Hp1' | lia |].
                           rewrite ?append_assoc.
                           replace (2 * N.to_nat (a / 2)%N + 2) with (N.to_nat (a + 1)%N) by lia.
                           reflexivity. }
                         cbn [encItems]; unfold encItem, encSingle; rewrite ?app_nil_r, ?Str_app_assoc, Ha_eq.
                         replace (N.to_nat s0) with (N.to_nat (s0 - 1)%N + 1) by lia.
                         exact (stepStar_trans Hs1 (step1DumpSegsBigAux_sound (proj1 (IH rest)) h Hp1'')).
                 --- destruct (((a =? 0)%N && isEmpty segTail && (1 <=? En)%N && (1 <=? s0)%N)%bool) eqn:Hc2.
                     +++ repeat (apply Bool.andb_true_iff in Hc2; destruct Hc2 as [Hc2 ?]).
                         apply N.eqb_eq in Hc2; apply isEmpty_true_iff in H1; apply N.leb_le in H0; apply N.leb_le in H.
                         subst a segTail.
                         destruct (pipeL_h1_enter_even (En := N.to_nat En) 0 (N.to_nat (s0 - 1)%N)
                                     ltac:(lia) hp (encItems rest *> [S0; S1; S0; S1] *> b0)) as [L1 [Hp1' Hs1]].
                         assert (Hp1'' : PipeL (N.to_nat (En - 1)%N)
                                           (encItems (List.rev (RIsingle 1%N false s0 [] None :: revOut))) L1).
                         { eapply pipeL_eqER; [exact Hp1' | lia |].
                           rewrite encItems_rev_cons; unfold encItem, encSingle; cbn [encSegTail].
                           rewrite N_to_nat_1, ?app_nil_r, ?append_assoc.
                           replace (N.to_nat (s0 - 1)%N + 1) with (N.to_nat s0) by lia.
                           reflexivity. }
                         cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail N.to_nat].
                         rewrite ?app_nil_r, ?Str_app_assoc.
                         replace (N.to_nat s0) with (N.to_nat (s0 - 1)%N + 1) by lia.
                         cbn [Nat.mul] in Hs1.
                         exact (stepStar_trans Hs1 (proj2 (IH rest) (En - 1)%N _ ys L1 Hp1'' h)).
                     +++ destruct ((isEmpty segTail && (s0 =? 0)%N && (a / 2 + 1 <=? En)%N)%bool) eqn:Hc3; [|discriminate].
                         apply Bool.andb_true_iff in Hc3; destruct Hc3 as [Hc3a HEn]; apply N.leb_le in HEn.
                         apply Bool.andb_true_iff in Hc3a; destruct Hc3a as [Hemp Hs00].
                         apply isEmpty_true_iff in Hemp; apply N.eqb_eq in Hs00; subst segTail s0.
                         destruct rest as [|[a2 h2 b2 segTail2 [aR2|] | | |] rest2]; try discriminate.
                         *** (* RIsingle a2 h2 b2 segTail2 (Some aR2) *)
                             destruct h2; [discriminate |].
                             destruct (((a mod 2 =? 1)%N && (2 <=? aR2)%N && (aR2 mod 2 =? 0)%N &&
                                        (1 <=? b2)%N && (a / 2 + aR2 / 2 + 1 <=? En)%N)%bool) eqn:Hca; [|discriminate].
                             repeat (apply Bool.andb_true_iff in Hca; destruct Hca as [Hca ?]).
                             pose proof (N_mod2_eq1_decomp a Hca) as Ha_odd.
                             pose proof (N_mod2_eq0_decomp aR2 H1) as HaR_even.
                             apply N.leb_le in H2; apply N.leb_le in H0; apply N.leb_le in H.
                             set (m := N.to_nat (a / 2)%N) in *.
                             set (q' := N.to_nat (aR2 / 2)%N - 1).
                             set (b2' := N.to_nat (b2 - 1)%N).
                             destruct (pipeL_h1_b0_odd_asplit_h0_even (En := N.to_nat En) m (N.to_nat a2) q' b2'
                                         ltac:(unfold q'; lia) hp
                                         (encSegTail segTail2 *> encItems rest2 *> [S0; S1; S0; S1] *> b0))
                               as [L1 [Hp1' Hs1]].
                             set (Er := (En - a / 2 - aR2 / 2 - 1)%N) in *.
                             set (a' := (a + a2 + aR2 + 2)%N) in *.
                             assert (Hsrc : encItems (RIsingle a true 0%N [] None ::
                                              RIsingle a2 false b2 segTail2 (Some aR2) :: rest2) *> [S0; S1; S0; S1] *> b0 =
                                            (T2 ^^ (2 * m + 1)) *> T5 *> (T2 ^^ N.to_nat a2) *> T0 *>
                                              (T2 ^^ (2 * (q' + 1))) *> (T4 ^^ (b2' + 1)) *>
                                              encSegTail segTail2 *> encItems rest2 *> [S0; S1; S0; S1] *> b0).
                             { cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail N.to_nat].
                               rewrite list_pow_zero, ?app_nil_r, ?Str_app_assoc, Ha_odd.
                               replace (N.to_nat aR2) with (2 * (q' + 1)) by (unfold q'; lia).
                               replace (N.to_nat b2) with (b2' + 1) by (unfold b2'; lia).
