                 inv_some_b1 h; subst ys.
                 pose proof (pipeL_dump_wall3 (E_rem := N.to_nat En) (N.to_nat a1) (N.to_nat a2)
                               ltac:(lia) hp (encItems rest3 *> [S0; S1; S0; S1] *> b0)) as Hw3.
                 cbn [encItems]; unfold encItem, encTok; rewrite N_to_nat_1, list_pow_one, ?Str_app_assoc.
                 eapply stepStar_trans; [exact Hw3 |].
                 unfold HubCfg. rewrite encItems_append; cbn [encItems]; unfold encItem, encTok.
                 rewrite N_to_nat_1, list_pow_one, ?append_assoc, ?Str_app_assoc.
                 replace (N.to_nat a1 + 2 * (N.to_nat En + 1)) with (N.to_nat (a1 + 2 * (En + 1))%N) by lia.
                 replace (N.to_nat a2 - 2 * (N.to_nat En + 1)) with (N.to_nat (a2 - 2 * (En + 1))%N) by lia.
                 apply evstep_refl.
Qed.

Lemma step1Phase1Big_sound {En : N} {revOut tail ys : list RleItem} {Lt : Stream Sym}
    (hp : PipeL (N.to_nat En) (encItems (List.rev revOut)) Lt)
    (h : step1Phase1Big En revOut tail = Some ys) :
    (([S1; S1] *> Lt) {{F}}> (encItems tail *> [S0; S1; S0; S1] *> b0))
      -[ tm ]->* HubCfg ys.
Proof.
  unfold step1Phase1Big in h.
  exact (proj1 (step1PhasesBigFuel_sound (S (List.length tail)) tail) En revOut ys Lt hp h).
Qed.

Lemma step1Phase2Big_sound {En : N} {revOut tail ys : list RleItem} {Lt : Stream Sym}
    (hp : PipeL (N.to_nat En) (encItems (List.rev revOut)) Lt)
    (h : step1Phase2Big En revOut tail = Some ys) :
    (([S1] *> T2 *> Lt) {{A}}> (encItems tail *> [S0; S1; S0; S1] *> b0))
      -[ tm ]->* HubCfg ys.
Proof.
  unfold step1Phase2Big in h.
  exact (proj2 (step1PhasesBigFuel_sound (S (List.length tail)) tail) En revOut ys Lt hp h).
Qed.

Lemma step1DumpSegsBig_sound {En sa s0 : N} {sh : bool} {revOut rest ys : list RleItem}
    {segTail : list SegPiece} {Lt : Stream Sym}
    (hp : PipeL (N.to_nat En)
            (((encItems (List.rev revOut) ++ (T2 ^^ N.to_nat sa)) ++ (if sh then T5 else [])) ++
              (T4 ^^ N.to_nat s0)) Lt)
    (h : step1DumpSegsBig En revOut sa sh s0 segTail rest = Some ys) :
    (([S1] *> T2 *> Lt) {{A}}> (encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0))
      -[ tm ]->* HubCfg ys.
Proof.
  unfold step1DumpSegsBig in h.
  exact (step1DumpSegsBigAux_sound (fun _ _ _ _ hp1 h1 => step1Phase1Big_sound hp1 h1) h hp).
Qed.

(* ========================================================================= *)
(* step1HubB0Z, step1HubDump, stepPipeRawBig Soundness                       *)
(* ========================================================================= *)

Lemma step1HubB0Z_sound {xs ys : list RleItem} (h : step1HubB0Z xs = Some ys) :
    (HubCfg xs) -[ tm ]->* HubCfg ys.
Proof.
  unfold step1HubB0Z in h.
  destruct xs as [|[a0 h0 b0_v [|? ?] [?|] | | |] [|[a1 h1 b1 segTail [?|] | | |] rest]]; try discriminate.
  destruct ((isMergeC0 h0 b0_v a1 && (a1 + 1 <=? a0)%N && (1 <=? b1)%N)%bool) eqn:Hc; [|discriminate].
  apply Bool.andb_true_iff in Hc; destruct Hc as [Hc1 Hb1]; apply Bool.andb_true_iff in Hc1; destruct Hc1 as [Hm Ha].
  apply N.leb_le in Ha; apply N.leb_le in Hb1.
  set (d := (a0 - a1 - 1)%N) in *.
  set (Ev := (d / 2)%N) in *.
  destruct h1; simpl negb in h.
  - (* h1 = true *)
    destruct (isEmpty segTail) eqn:Hemp.
    + apply isEmpty_true_iff in Hemp; subst segTail.
      destruct (pipeL_start_c0_b0z_h1 a0 h0 b0_v a1 (b1 - 1)%N Hm Ha
                  (encItems rest *> [S0; S1; S0; S1] *> b0)) as [L0 [Hp0 Hs0]].
      fold d in Hp0; fold Ev in Hp0.
      replace (if (d mod 2 =? 0)%N
               then RIsingle (a0 + a1 + 4)%N true (b1 - 1)%N [] None
               else RIsingle (a0 + a1 + 4)%N false (b1 - 1 + 1)%N [] None)
        with (if (d mod 2 =? 0)%N
              then RIsingle (a0 + a1 + 4)%N true (b1 - 1)%N [] None
              else RIsingle (a0 + a1 + 4)%N false b1 [] None) in Hp0
        by (destruct ((d mod 2 =? 0)%N); [reflexivity | repeat f_equal; lia]).
      unfold HubCfg; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
      rewrite ?app_nil_r, ?Str_app_assoc.
      replace (N.to_nat b1) with (N.to_nat (b1 - 1)%N + 1) by lia.
      exact (stepStar_trans Hs0 (step1Phase2Big_sound Hp0 h)).
    + destruct (pipeL_start_c0_b0z_h1 a0 h0 b0_v a1 (b1 - 1)%N Hm Ha
                  (encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0)) as [L0 [Hp0 Hs0]].
      set (h' := (d mod 2 =? 0)%N) in *.
      set (s0' := if h' then (b1 - 1)%N else b1) in *.
      assert (Hp0' : PipeL (N.to_nat Ev)
                       (((encItems (List.rev ([] : list RleItem)) ++ (T2 ^^ N.to_nat (a0 + a1 + 4)%N)) ++
                          (if h' then T5 else [])) ++ (T4 ^^ N.to_nat s0')) L0).
      { eapply pipeL_eqR; [| exact Hp0].
        unfold h', s0', d in *; destruct (((a0 - a1 - 1) mod 2 =? 0)%N);
          cbn [List.rev List.app encItems]; unfold encItem, encSingle; cbn [encSegTail];
          rewrite ?app_nil_r, ?append_assoc.
        - reflexivity.
        - replace (N.to_nat (b1 - 1 + 1)%N) with (N.to_nat b1) by lia; reflexivity. }
      unfold HubCfg; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
      rewrite ?app_nil_r, ?Str_app_assoc.
      replace (N.to_nat b1) with (N.to_nat (b1 - 1)%N + 1) by lia.
      exact (stepStar_trans Hs0 (step1DumpSegsBig_sound Hp0' h)).
  - (* h1 = false *)
    destruct ((b1 - 1 <=? Ev)%N) eqn:Hb.
    + apply N.leb_le in Hb.
      destruct (isEmpty segTail) eqn:Hemp.
      * apply isEmpty_true_iff in Hemp; subst segTail.
        destruct (pipeL_start_c0_b0z_h0 a0 h0 b0_v a1 (b1 - 1)%N Hm Ha Hb
                    (encItems rest *> [S0; S1; S0; S1] *> b0)) as [L0 [Hp0 Hs0]].
        fold d in Hp0; fold Ev in Hp0.
        replace (if (d mod 2 =? 0)%N
                 then RIsingle (a0 + a1 + 3)%N true (b1 - 1)%N [] None
                 else RIsingle (a0 + a1 + 3)%N false (b1 - 1 + 1)%N [] None)
          with (if (d mod 2 =? 0)%N
                then RIsingle (a0 + a1 + 3)%N true (b1 - 1)%N [] None
                else RIsingle (a0 + a1 + 3)%N false b1 [] None) in Hp0
          by (destruct ((d mod 2 =? 0)%N); [reflexivity | repeat f_equal; lia]).
        unfold HubCfg; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
        rewrite ?app_nil_r, ?Str_app_assoc.
        replace (N.to_nat b1) with (N.to_nat (b1 - 1)%N + 1) by lia.
        exact (stepStar_trans Hs0 (step1Phase1Big_sound Hp0 h)).
      * destruct (pipeL_start_c0_b0z_h0 a0 h0 b0_v a1 (b1 - 1)%N Hm Ha Hb
                    (encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0)) as [L0 [Hp0 Hs0]].
        fold d in Hp0; fold Ev in Hp0.
        replace (if (d mod 2 =? 0)%N
                 then RIsingle (a0 + a1 + 3)%N true (b1 - 1)%N [] None
                 else RIsingle (a0 + a1 + 3)%N false (b1 - 1 + 1)%N [] None)
          with (if (d mod 2 =? 0)%N
                then RIsingle (a0 + a1 + 3)%N true (b1 - 1)%N [] None
                else RIsingle (a0 + a1 + 3)%N false b1 [] None) in Hp0
          by (destruct ((d mod 2 =? 0)%N); [reflexivity | repeat f_equal; lia]).
        unfold HubCfg; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
        rewrite ?app_nil_r, ?Str_app_assoc.
        replace (N.to_nat b1) with (N.to_nat (b1 - 1)%N + 1) by lia.
        exact (stepStar_trans Hs0 (step1Unzip_sound segTail (Ev - (b1 - 1))%N _ rest ys L0 Hp0 h)).
    + apply N.leb_gt in Hb; inv_some_b1 h; subst ys.
      set (rem := (b1 - 1 - Ev - 1)%N).
      destruct (pipeL_start_c0_b0z_h0 a0 h0 b0_v a1 Ev Hm Ha (N.le_refl Ev)
                  (T4 *> (T4 ^^ N.to_nat rem) *> encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0))
        as [L0 [Hp0 Hs0]].
      pose proof (PipeL_unwind (pipeL_castE 0 Hp0 ltac:(lia))
                    (T3 *> (T4 ^^ N.to_nat rem) *> encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0))
        as Hunw.
      change (T4 *> (T4 ^^ N.to_nat rem) *> encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0)
        with ([S0; S1] *> T3 *> (T4 ^^ N.to_nat rem) *> encSegTail segTail *> encItems rest *> [S0; S1; S0; S1] *> b0)
        in Hs0.
      assert (Hsrc : HubCfg (RIsingle a0 h0 b0_v [] None :: RIsingle a1 false b1 segTail None :: rest) =
                     b0 {{E}}> (T2 *> T0 *> T1 *> (T2 ^^ N.to_nat a0) *> (if h0 then T5 else []) *>
                       (T4 ^^ N.to_nat b0_v) *> (T2 ^^ N.to_nat a1) *> (T4 ^^ (N.to_nat Ev + 1)) *>
                       [S0; S1] *> T3 *> (T4 ^^ N.to_nat rem) *> encSegTail segTail *>
                       encItems rest *> [S0; S1; S0; S1] *> b0)).
      { unfold HubCfg; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail].
        replace (N.to_nat b1) with ((N.to_nat Ev + 1) + (N.to_nat rem + 1)) by (unfold rem; lia).
        rewrite ?app_nil_r, ?Str_app_assoc, (pow_add_blank T4 (N.to_nat Ev + 1) (N.to_nat rem + 1)), (zPsr1 T4 (N.to_nat rem)), ?Str_app_assoc.
        reflexivity. }
      rewrite Hsrc.
      eapply stepStar_trans; [exact Hs0 |].
      eapply stepStar_trans; [exact Hunw |].
      unfold HubCfg.
      destruct (((a0 - a1 - 1) mod 2 =? 0)%N) eqn:Hpar;
        unfold d in *; rewrite ?Hpar;
        cbn [List.rev List.app encItems]; unfold encItem, encSingle; cbn [encSegTail];
        rewrite ?app_nil_r, ?Str_app_assoc; apply evstep_refl.
Qed.

Lemma step1HubDump_sound {p : nat} {xs ys : list RleItem}
    (h : step1HubDump p xs = Some ys) :
    (HubCfg xs) -[ tm ]->* HubCfg ys.
Proof.
  unfold step1HubDump in h.
  destruct (splitAtList p xs) as [[pref tail]|] eqn:Hsp; [|discriminate].
  destruct (step1HubPrefixBig pref) as [[[isP2 Ev] revOut]|] eqn:Hpre; [|discriminate].
  destruct (step1HubPrefixBig_sound tail Hpre) as [Lt' [Hp' Hreach0]].
  rewrite <- (splitAtList_sound _ _ _ _ Hsp) in Hreach0.
  destruct isP2.
  - exact (stepStar_trans Hreach0 (step1Phase2Big_sound Hp' h)).
  - exact (stepStar_trans Hreach0 (step1Phase1Big_sound Hp' h)).
Qed.

Lemma stepPipeRawBig_sound {prefixLen winLen fuel : nat} {xs ys : list RleItem}
    (h : stepPipeRawBig prefixLen winLen fuel xs = Some ys) :
    (HubCfg xs) -[ tm ]->* HubCfg ys.
Proof.
  unfold stepPipeRawBig in h.
  destruct (splitAtList prefixLen xs) as [[pref afterPref]|] eqn:Hsp1; [|discriminate].
  destruct (splitAtList winLen afterPref) as [[win tail]|] eqn:Hsp2; [|discriminate].
  destruct (itemsToRuns win) as [winRuns|] eqn:Hwr; [|discriminate].
  assert (Hxs : xs = pref ++ (win ++ tail)).
  { rewrite (splitAtList_sound _ _ _ _ Hsp1), (splitAtList_sound _ _ _ _ Hsp2). reflexivity. }
  pose proof (itemsToRuns_sound _ _ Hwr) as Hwin.
  set (R_tail := encItems tail *> [S0; S1; S0; S1] *> b0) in *.
  set (rBase := if isEmpty tail then RBblank else RBtail) in *.
  set (R_body := if isEmpty tail then winRuns ++ footerRuns else winRuns) in *.
  assert (HRbody : encRuns R_body *> RightBaseStream R_tail rBase =
                   encItems win *> encItems tail *> [S0; S1; S0; S1] *> b0).
  { unfold R_body, rBase, R_tail.
    destruct tail as [|t ts]; cbn [isEmpty RightBaseStream].
    - rewrite encRuns_append, encRuns_footerRuns, Hwin; cbn [encItems]; rewrite zLan, ?Str_app_assoc.
      reflexivity.
    - rewrite Hwin; reflexivity. }
  set (initRaw :=
    if Nat.eqb prefixLen O then
      stepRaw (mkRawCfg E [] LBblank ((T_2, 1%N) :: (T_0, 1%N) :: (T_1, 1%N) :: R_body) rBase)
    else
      match step1HubPrefixBig pref with
      | None => None
      | Some (false, Ep, revPref) =>
          Some (mkRawCfg F [(T_1, 2%N)] (LBpipe Ep revPref) R_body rBase)
      | Some (true, Ep, revPref) =>
          Some (mkRawCfg A [(T_1, 1%N); (T_2, 1%N)] (LBpipe Ep revPref) R_body rBase)
      end) in *.
  assert (Hstart : forall rc0, initRaw = Some rc0 ->
    exists cfg0, RawDenote R_tail rc0 cfg0 /\ (HubCfg xs) -[ tm ]->* cfg0).
  { intros rc0 Hrc0. unfold initRaw in Hrc0.
    destruct prefixLen as [|p']; simpl Nat.eqb in Hrc0.
    - cbn [splitAtList] in Hsp1; inv_some_b1 Hsp1; subst pref afterPref.
      set (rcBase := mkRawCfg E [] LBblank ((T_2, 1%N) :: (T_0, 1%N) :: (T_1, 1%N) :: R_body) rBase) in *.
      assert (HdBase : RawDenote R_tail rcBase (HubCfg xs)).
      { exists b0; split; [reflexivity |].
        rewrite Hxs; cbn [List.app]; unfold HubCfg, rcBase.
        cbn [rc_q rc_L rc_lBase rc_R rc_rBase encRuns encTok].
        rewrite N_to_nat_1, !list_pow_one, zLan, ?Str_app_assoc, HRbody, encItems_append, ?Str_app_assoc.
        reflexivity. }
      exact (stepRaw_sound HdBase Hrc0).
    - destruct (step1HubPrefixBig pref) as [[[isP2 Ep] revPref]|] eqn:Hpre; [|discriminate].
      destruct (step1HubPrefixBig_sound (win ++ tail) Hpre) as [Lt' [Hp' Hreach]].
      rewrite <- Hxs, encItems_append, Str_app_assoc in Hreach.
      destruct isP2; inv_some_b1 Hrc0; subst rc0.
      + eexists; split; [exists Lt'; split; [exact Hp' | reflexivity] |].
        cbn [rc_q rc_L rc_lBase rc_R rc_rBase encRuns encTok].
        rewrite N_to_nat_1, !list_pow_one, ?app_nil_r, ?Str_app_assoc, HRbody.
        exact Hreach.
      + eexists; split; [exists Lt'; split; [exact Hp' | reflexivity] |].
        cbn [rc_q rc_L rc_lBase rc_R rc_rBase encRuns encTok].
        replace (N.to_nat 2%N) with 2 by reflexivity; cbn [lpow List.app].
        rewrite ?app_nil_r, ?Str_app_assoc, HRbody.
        exact Hreach. }
  destruct initRaw as [rc0|] eqn:Hinit; [|discriminate].
  destruct (Hstart rc0 eq_refl) as [cfg0 [Hd0 Hs0]].
  destruct (runRawUntil isRawDoneBig fuel rc0) as [rc1|] eqn:Hrun; [|discriminate].
  destruct (runRawUntil_sound _ _ _ _ _ _ Hd0 Hrun) as [_ [cfg1 [Hd1 Hs1]]].
  pose proof (stepStar_trans Hs0 Hs1) as Hreach1.
  destruct Hd1 as [L1 [Hlb1 Hcfg1]]; subst cfg1.
  destruct rc1 as [q1 Lr1 lb1 Rr1 rb1];
    cbn [rc_q rc_L rc_lBase rc_R rc_rBase LeftBaseDenote RightBaseStream] in h, Hlb1, Hreach1.
  destruct q1.
  - (* A *)
    destruct Lr1 as [|[[| | | | | |] n1] [|[[| | | | | |] n2] [|? ?]]]; try discriminate.
    destruct lb1 as [|Ep revOut]; [discriminate |]; cbn [LeftBaseDenote] in Hlb1.
    destruct Rr1 as [|? ?]; [|discriminate].
    destruct rb1; [discriminate |]; cbn [RightBaseStream] in Hreach1.
    destruct (((n1 =? 1)%N && (n2 =? 1)%N)%bool) eqn:Hc; [|discriminate].
    split_andb; subst n1 n2.
    eapply stepStar_trans; [exact Hreach1 |].
    cbn [encRuns encTok]; rewrite N_to_nat_1, !list_pow_one, ?app_nil_r, zLan, ?Str_app_assoc.
    exact (step1Phase2Big_sound Hlb1 h).
  - (* B *) discriminate.
  - (* C *) discriminate.
  - (* D *) discriminate.
  - (* E *)
    destruct Lr1 as [|? ?]; [|discriminate].
    destruct lb1 as [|? ?]; [|discriminate]; cbn [LeftBaseDenote] in Hlb1; subst L1.
    destruct Rr1 as [|[[| | | | | |] n2] [|[[| | | | | |] n0] [|[[| | | | | |] n1] R_out]]]; try discriminate.
    destruct rb1; cbn [RightBaseStream] in Hreach1.
    + (* RBblank *)
      destruct (((n2 =? 1)%N && (n0 =? 1)%N && (n1 =? 1)%N)%bool) eqn:Hc; [|discriminate].
      repeat (apply Bool.andb_true_iff in Hc; destruct Hc as [Hc ?]).
      apply N.eqb_eq in Hc; apply N.eqb_eq in H0; apply N.eqb_eq in H; subst n2 n0 n1.
      apply option_map_Some in h; destruct h as [body [Hsf Hys]]; subst ys.
      eapply stepStar_trans; [exact Hreach1 |].
      unfold HubCfg.
      cbn [encRuns encTok]; rewrite N_to_nat_1, !list_pow_one, zLan, (stripFooterRuns_sound Hsf),
        encItems_runsToItems, ?Str_app_assoc.
      apply evstep_refl.
    + (* RBtail *)
      destruct (((n2 =? 1)%N && (n0 =? 1)%N && (n1 =? 1)%N)%bool) eqn:Hc; [|discriminate].
      repeat (apply Bool.andb_true_iff in Hc; destruct Hc as [Hc ?]).
      apply N.eqb_eq in Hc; apply N.eqb_eq in H0; apply N.eqb_eq in H; subst n2 n0 n1.
      inv_some_b1 h; subst ys.
      eapply stepStar_trans; [exact Hreach1 |].
      unfold HubCfg, R_tail.
      cbn [encRuns encTok]; rewrite N_to_nat_1, !list_pow_one, zLan, encItems_append,
        encItems_runsToItems, ?Str_app_assoc.
      apply evstep_refl.
  - (* F *)
    destruct Lr1 as [|[[| | | | | |] n1] [|? ?]]; try discriminate.
    destruct lb1 as [|Ep revOut]; [discriminate |]; cbn [LeftBaseDenote] in Hlb1.
    destruct ((n1 =? 2)%N) eqn:Hn1; [|discriminate]; apply N.eqb_eq in Hn1; subst n1.
    assert (HLr : encRuns [(T_1, 2%N)] = [S1; S1]) by reflexivity.
    rewrite HLr in Hreach1.
    destruct ((isEmpty Rr1 && isRBtail rb1)%bool) eqn:HempTail.
    + apply Bool.andb_true_iff in HempTail; destruct HempTail as [Hemp Hrb].
      apply isEmpty_true_iff in Hemp; subst Rr1.
      destruct rb1; [discriminate |]; cbn [RightBaseStream] in Hreach1.
      eapply stepStar_trans; [exact Hreach1 |].
      cbn [encRuns]; rewrite zLan.
      exact (step1Phase1Big_sound Hlb1 h).
    + destruct ((Ep =? 0)%N) eqn:HEp0.
      * apply N.eqb_eq in HEp0; subst Ep; cbn [N.to_nat] in Hlb1.
        destruct rb1; cbn [RightBaseStream] in Hreach1.
        -- destruct (pop01Runs Rr1) as [R_out|] eqn:Hpop; [|discriminate].
           apply option_map_Some in h; destruct h as [body [Hsf Hys]]; subst ys.
           eapply stepStar_trans; [exact Hreach1 |].
           pose proof (PipeL_unwind Hlb1 (encRuns body *> [S0; S1; S0; S1] *> b0)) as Hunw.
           unfold HubCfg.
           rewrite encItems_append, encItems_runsToItems, (pop01Runs_sound Hpop),
             (stripFooterRuns_sound Hsf), ?Str_app_assoc.
           exact Hunw.
        -- destruct (pop01Runs Rr1) as [R_out|] eqn:Hpop; [|discriminate].
           inv_some_b1 h; subst ys.
           eapply stepStar_trans; [exact Hreach1 |].
           pose proof (PipeL_unwind Hlb1 (encRuns R_out *> R_tail)) as Hunw.
           unfold HubCfg, R_tail.
           simp_encItems_app; rewrite encItems_runsToItems, (pop01Runs_sound Hpop), ?Str_app_assoc.
           exact Hunw.
      * apply N.eqb_neq in HEp0.
        destruct rb1; [|discriminate]; cbn [RightBaseStream] in Hreach1.
        destruct (isFooterOnly Rr1) eqn:Hfo; [|discriminate].
        inv_some_b1 h; subst ys.
        eapply stepStar_trans; [exact Hreach1 |].
        pose proof (pipeL_end_p1 (En := N.to_nat (Ep - 1)%N) (pipeL_castE (N.to_nat (Ep - 1)%N + 1) Hlb1 ltac:(lia))) as H1.
        unfold HubCfg.
        rewrite encItems_append; cbn [encItems]; unfold encItem, encSingle; cbn [encSegTail N.to_nat].
        rewrite list_pow_zero, ?app_nil_r, ?append_assoc, (isFooterOnly_sound Hfo).
        rewrite ?append_assoc in H1.
        exact H1.
Qed.

(* --- ScratchS6B2.v --- *)
Local Close Scope sym_scope.
Local Close Scope N_scope.
Local Open Scope list_scope.
Local Open Scope nat_scope.

(* ========================================================================= *)
(* Certificate Evaluator Soundness & End-to-End Halting Chain                *)
(* ========================================================================= *)

Lemma stepCert1_sound {op : CertOp} {xs ys : list RleItem}
    (h : stepCert1 op xs = Some ys) :
    (HubCfg xs) -[ tm ]->* HubCfg ys.
Proof.
  destruct op as [n | | p | k Nv | k mult | k Mv | k0 k1 Mv | k0 k1 Wv hasTR | k0 Mv | k0 Mv | p w f | p1 f1 p2 f2 | nop |];
    cbn [stepCert1] in h.
  - exact (runH1_sound n xs ys h).
  - exact (step1HubB0Z_sound h).
  - exact (step1HubDump_sound h).
  - exact (stepOdoD0_sound h).
  - exact (stepOdoRelay_sound h).
  - exact (stepEater_sound h).
  - exact (stepSlicer12_sound k0 k1 Mv xs ys h).
  - exact (stepWave402_sound k0 k1 Wv hasTR xs ys h).
  - exact (stepMirror3752_sound k0 Mv xs ys h).
  - exact (stepMirror162_sound k0 Mv xs ys h).
  - apply option_map_Some in h; destruct h as [mid [Hraw Hys]]; subst ys.
    rewrite (HubCfg_of_encItems_eq (encItems_autoPackNorm mid)).
    exact (stepPipeRawBig_sound Hraw).
  - exact (stepPipeRawBridge_sound h).
  - rewrite (HubCfg_of_encItems_eq (applyNorm_sound h)).
    apply evstep_refl.
  - inversion h; subst ys.
    rewrite (HubCfg_of_encItems_eq (encItems_autoPackNorm xs)).
    apply evstep_refl.
Qed.

Lemma runCert_sound : forall (ops : list CertOp) (xs ys : list RleItem),
    runCert ops xs = Some ys ->
    (HubCfg xs) -[ tm ]->* HubCfg ys.
Proof.
  induction ops as [|op ops' IH]; intros xs ys h; cbn [runCert] in h.
  - inversion h; subst ys; apply evstep_refl.
  - destruct (stepCert1 op xs) as [xs'|] eqn:Hs; [|discriminate].
    exact (stepStar_trans (stepCert1_sound Hs) (IH xs' ys h)).
Qed.

Lemma checkCert_sound {ops : list CertOp} {src tgt : list RleItem}
    (h : checkCert ops src tgt = true) :
    (HubCfg src) -[ tm ]->* HubCfg tgt.
Proof.
  unfold checkCert in h.
  apply (option_eqb_eq (list_eqb rleItem_eqb) (list_eqb_eq rleItem_eqb rleItem_eqb_eq)) in h.
  exact (runCert_sound ops src tgt h).
Qed.

Definition Reach (src tgt : list RleItem) : Prop :=
  (HubCfg src) -[ tm ]->* HubCfg tgt.

Lemma Reach_refl (x : list RleItem) : Reach x x.
Proof. apply evstep_refl. Qed.

Lemma Reach_trans {a b c : list RleItem} (h1 : Reach a b) (h2 : Reach b c) : Reach a c.
Proof. exact (stepStar_trans h1 h2). Qed.

Lemma Reach_of_checkCert {ops : list CertOp} {src tgt : list RleItem}
    (h : checkCert ops src tgt = true) : Reach src tgt.
Proof. exact (checkCert_sound h). Qed.

Lemma checkInit_sound {fuel : nat} {tgt : list RleItem}
    (h : checkInit fuel tgt = true) :
    c0 -[ tm ]->* HubCfg tgt.
Proof.
  unfold checkInit in h.
  apply (option_eqb_eq (list_eqb rleItem_eqb) (list_eqb_eq rleItem_eqb rleItem_eqb_eq)) in h.
  apply option_map_Some in h; destruct h as [mid [Hinit Htgt]]; subst tgt.
  rewrite (HubCfg_of_encItems_eq (encItems_autoPackNorm mid)).
  exact (runRawFromInit_sound Hinit).
Qed.

Theorem halt_of_chain {fuelInit pH wH fH : nat} {s0 sEnd : list RleItem}
    (hinit : checkInit fuelInit s0 = true)
    (hreach : Reach s0 sEnd)
    (hhalt : runPipeRawHalt pH wH fH sEnd = true) :
    halts tm c0.
Proof.
  exact (runPipeRawHalt_sound (stepStar_trans (checkInit_sound hinit) hreach) hhalt).
Qed.


