  eapply Reach_trans; [exact (Reach_of_checkCert part_1_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_2_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_3_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_4_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_5_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_6_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_7_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_8_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_9_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_10_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_11_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_12_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_13_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_14_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_15_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_16_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_17_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_18_ok) |].
  eapply Reach_trans; [exact (Reach_of_checkCert part_19_ok) |].
  exact (Reach_of_checkCert part_20_ok).
Qed.

Lemma halt_internal : halts tm c0.
Proof.
  exact (halt_of_chain init_ok reach_0_20 halt_ok).
Qed.

End Internal.

Theorem halt : halts tm c0.
Proof.
  exact Internal.halt_internal.
Qed.
